INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p2-2', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 2, 'NIST Special Publication 800-53 Revision 5 Security and Privacy Controls for Information Systems and Organizations JOINT TASK FORCE This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 September 2020 INCLUDES UPDATES AS OF 12-10-2020; SEE PAGE XVII U.S. Department of Commerce Wilbur L. Ross, Jr., Secretary National Institute of Standards and Technology Walter Copan, NIST Director and Under Secretary of Commerce for Standards and Technology', 'vec_doc-14-nist-sp-800-53-p2-2', 0, 121, 'v2.1.0', 'ff1c471c5215461821a677b4449c37e8e2cb0227f6f7c04893c18b45ee9948d3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":2,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p3-3', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 3, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ i This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Authority This publication has been developed by NIST to further its statutory responsibilities under the Federal Information Security Modernization Act (FISMA), 44 U.S.C. § 3551 et seq., Public Law (P.L.) 113-283. NIST is responsible for developing information security standards and guidelines, including minimum requirements for federal information systems. Such information security standards and guidelines shall not apply to national security systems without the express approval of the appropriate federal officials exercising policy authority over such systems.', 'vec_doc-14-nist-sp-800-53-p3-3', 0, 235, 'v2.1.0', 'fb40a6f43c4f304883c6f1cb8fae516e506fdc9d4952b62a5dc0d68dfa33d7ba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p3-4', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 3, 'This guideline is consistent with the requirements of the Office of Management and Budget (OMB) Circular A-130. Nothing in this publication should be taken to contradict the standards and guidelines made mandatory and binding on federal agencies by the Secretary of Commerce under statutory authority. Nor should these guidelines be interpreted as altering or superseding the existing authorities of the Secretary of Commerce, OMB Director, or any other federal official. This publication may be used by nongovernmental organizations on a voluntary basis and is not subject to copyright in the United States. Attribution would, however, be appreciated by NIST. National Institute of Standards and Technology Special Publication 800-53, Revision 5 Natl. Inst. Stand. Technol. Spec. Publ. 800-53, Rev.', 'vec_doc-14-nist-sp-800-53-p3-4', 0, 200, 'v2.1.0', '33bf515c506dedd4f14010279c54de636ac51edf8cbac32bc547a855e5b06b7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":4,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p3-5', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 3, '5, 492 pages (September 2020) CODEN: NSPUE2 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Comments on this publication may be submitted to: National Institute of Standards and Technology Attn: Computer Security Division, Information Technology Laboratory 100 Bureau Drive (Mail Stop 8930) Gaithersburg, MD 20899-8930 Email: sec-cert@nist.gov All comments are subject to release under the Freedom of Information Act (FOIA) [FOIA96]. Certain commercial entities, equipment, or materials may be identified in this document to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by NIST, nor is it intended to imply that the entities, materials, or equipment are necessarily the best available for the purpose. There may be references in this publication to other publications currently under development by NIST in accordance with its assigned statutory responsibilities.', 'vec_doc-14-nist-sp-800-53-p3-5', 0, 249, 'v2.1.0', 'c711abafdc3d2b361c1ce3e07d36a94d23c2d29c60a70b4a8dd64adc9f018c43', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":5,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p3-6', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 3, 'The information in this publication, including concepts, practices, and methodologies may be used by federal agencies even before the completion of such companion publications. Thus, until each publication is completed, current requirements, guidelines, and procedures, where they exist, remain operative. For planning and transition purposes, federa l agencies may wish to closely follow the development of these new publications by NIST. Organizations are encouraged to review draft publications during the designated public comment periods and provide feedback to NIST. Many NIST publications, other than the ones noted above, are available at https://csrc.nist.gov/publications.', 'vec_doc-14-nist-sp-800-53-p3-6', 0, 171, 'v2.1.0', '25413ca324643ff35076402b70939ce9e0909d3ab06720733a9f445f937141b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":6,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p4-7', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 4, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ ii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Reports on Computer Systems Technology The National Institute of Standards and Technology (NIST) Information Technology Laboratory (ITL) promotes the U.S. economy and public welfare by providing technical leadership for the Nation’s measurement and standards infrastructure. ITL develops tests, test methods, reference data, proof of concept implementations, and technical analyses to advance the development and productive use of information technology (IT).', 'vec_doc-14-nist-sp-800-53-p4-7', 0, 208, 'v2.1.0', 'dd44f7fb861ca33ed9976868e2dbd1b324ac4335e5d56952b0143af676038db1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":7,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p4-8', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 4, 'ITL’s responsibilities include the development of management, administrative, technical, and physical standards and guidelines for the cost- effective security of other than national security-related information in federal information systems. The Special Publication 800-series reports on ITL’s research, guidelines, and outreach efforts in information systems security and privacy and its collaborative activities with industry, government, and academic organizations. Abstract This publication provides a catalog of security and privacy controls for information systems and organizations to protect organizational operations and assets, individuals, other organizations, and the Nation from a diverse set of threats and risks, including hostile attacks, human errors, natural disasters, structural failures, foreign intelligence entities, and privacy risks. The controls are flexible and customizable and implemented as part of an organization-wide process to manage risk.', 'vec_doc-14-nist-sp-800-53-p4-8', 0, 244, 'v2.1.0', '4e26d0316c97f5b34bc422e5d95c3c8d8e5869996c6d3f2dd1de7766e8930416', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":8,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p4-9', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 4, 'The controls address diverse requirements derived from mission and business needs, laws, executive orders, directives, regulations, policies, standards, and guidelines. Finally, the consolidated control catalog addresses security and privacy from a functionality perspective (i.e., the strength of functions and mechanisms provided by the controls) and from an assurance perspective (i.e., the measure of confidence in the security or privacy capability provided by the controls). Addressing functionality and assurance helps to ensure that information technology products and the systems that rely on those products are sufficiently trustworthy.', 'vec_doc-14-nist-sp-800-53-p4-9', 0, 162, 'v2.1.0', '395888add21395275c7f3746f6eabdb9a9b957c23dc1af5d0f8b07791a3ea195', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":9,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p4-10', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 4, 'Keywords Assurance; availability; computer security; confidentiality; control; cybersecurity; FISMA; information security; information system; integrity; personally identifiable information; Privacy Act; privacy controls; privacy functions; privacy requirements; Risk Management Framework; security controls; security functions; security requirements; system; system security.', 'vec_doc-14-nist-sp-800-53-p4-10', 0, 94, 'v2.1.0', 'd676756d3a8028813701931996aeb1c8425ff619e96066c95fe94f44f134d12a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":10,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
