INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p6-16', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'UNKNOWN', 6, 'Finally, the authors gratefully acknowledge the contributions from individuals and organizations in the public and private sectors, both nationally and internationally, whose insightful and constructive comments improved the overall quality, thoroughness, and usefulness of this publication. HISTORICAL CONTRIBUTIONS TO NIST SPECIAL PUBLICATION 800-53 The authors wanted to acknowledge the many individuals who contributed to previous versions of Special Publication 800-53 since its inception in 2005.', 'vec_doc-14-nist-sp-800-53-p6-16', 0, 126, 'v2.1.0', '97f405fe7bbf8db198b1652857262e695c1739f95292ae61db9029b4087654c4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":6,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":16,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"General Document Content"}');
