INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p14-29', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'chapter sections, controls, and control enhancements. These examples are illustrative in nature', 14, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ xii This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 FEDERAL RECORDS MANAGEMENT COLLABORATION Federal records management processes have a nexus with certain information security and privacy requirements and controls. For example, records officers may be managing records retention, including when records will be deleted. Collaborating with records officers on the selection and implementation of security and privacy controls related to records management can support consistency and efficiency and ultimately strengthen the organization’s security and privacy posture.', 'vec_doc-14-nist-sp-800-53-p14-29', 0, 223, 'v2.1.0', '53eb753aad23e41c551e4dcd817a532a431c4e5a678c30027a2db00bb02b8a2b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"chapter sections, controls, and control enhancements. These examples are illustrative in nature","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":29,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"chapter sections, controls, and control enhancements. These examples are illustrative in nature"}');
