INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-66', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'Section 1.4 (Footnote 23): Delete “[OMB A-130] establishes policy', 28, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________', 'vec_doc-14-nist-sp-800-53-p28-66', 0, 69, 'v2.1.0', '681b5c83cde7f72211b1127e18a6675b9c3f07e1b466634f0c8e0196e9fcea7f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"Section 1.4 (Footnote 23): Delete “[OMB A-130] establishes policy","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":66,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"Section 1.4 (Footnote 23): Delete “[OMB A-130] establishes policy"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-67', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 1', 28, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'vec_doc-14-nist-sp-800-53-p28-67', 0, 23, 'v2.1.0', 'e542637362ea230cdb228d0b14653a901af6bc58d36b77a85e6486641cfa5939', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 1","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":67,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 1"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-68', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE', 28, 'INTRODUCTION THE NEED TO PROTECT INFORMATION, SYSTEMS, ORGANIZATIONS, AND INDIVIDUALS Modern information systems1 can include a variety of computing platforms (e.g., industrial control systems, general purpose computing systems, cyber-physical systems, super computers, weapons systems, communications systems, environmental control systems, medical devices, embedded devices, sensors, and mobile devices such as smart phones and tablets). These platforms all share a common foundation— computers with complex hardware, software and firmware providing a capability that supports the essential mission and business functions of organizations.2 Security controls are the safeguards or countermeasures employed within a system or an organization to protect the confidentiality, integrity, and availability of the system and its information and to manage information security3 risk.', 'vec_doc-14-nist-sp-800-53-p28-68', 0, 220, 'v2.1.0', '130f7ffeb97cc83a1f16a559d9a239bfc0c49011f39a3873cd177ed43b24c8a9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":68,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-69', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE', 28, 'Privacy controls are the administrative, technical, and physical safeguards employed within a system or an organization to manage privacy risks and to ensure compliance with applicable privacy requirements.4 Security and privacy controls are selected and implemented to satisfy security and privacy requirements levied on a system or organization. Security and privacy requirements are derived from applicable laws, executive orders, directives, regulations, policies, standards, and mission needs to ensure the confidentiality, integrity, and availability of information processed, stored, or transmitted and to manage risks to individual privacy. The selection, design, and implementation of security and privacy controls5 are important tasks that have significant implications for the operations6 and assets of organizations as well as the welfare of individuals and the Nation.', 'vec_doc-14-nist-sp-800-53-p28-69', 0, 221, 'v2.1.0', 'c6f2b51949dd4bb290fab03dd84de1c7e0e9f198b97509febc0fef56628dbd61', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":69,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-70', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE', 28, 'Organizations should answer several key questions when addressing information security and privacy controls: • What security and privacy controls are needed to satisfy security and privacy requirements and to adequately manage mission/business risks or risks to individuals? • Have the selected controls been implemented or is there a plan in place to do so? • What is the required level of assurance (i.e., grounds for confidence) that the selected controls, as designed and implemented, are effective?7 1 An information system is a discrete set of information resources organized for the collection, processing, maintenance, use, sharing, dissemination, or disposition of information [OMB A-130]. 2 The term organization describes an entity of any size, complexity, or positioning within an organizational structure (e.g., a federal agency or, as appropriate, any of its operational elements). 3 The two terms information security and security are used synonymously in this publication.', 'vec_doc-14-nist-sp-800-53-p28-70', 0, 247, 'v2.1.0', 'e6bb4025aa0ce85241a6547c38c40cf8eee433a2070e72b18a14b8f0c599c6dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":70,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p28-71', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE', 28, '4 [OMB A-130] defines security and privacy controls. 5 Controls provide safeguards and countermeasures in systems security and privacy engineering processes to reduce risk during the system development life cycle. 6 Organizational operations include mission, functions, image, and reputation. 7 Security and privacy control effectiveness addresses the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting the designated security and privacy requirements [SP 800-53A].', 'vec_doc-14-nist-sp-800-53-p28-71', 0, 138, 'v2.1.0', '2816cc311fe65b91f9d1796194eda245b49d53e66ab47e3f90a46daed7ec20a8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":71,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p29-72', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 2', 29, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 The answers to these questions are not given in isolation but rather in the context of a risk management process for the organization that identifies, assesses, responds to, and monitors security and privacy risks arising from its information and systems on an ongoing basis.8 The security and privacy controls in this publication are recommended for use by organizations to satisfy their information security and privacy requirements. The control catalog can be viewed as a toolbox containing a collection of safeguards, countermeasures, techniques, and processes to respond to security and privacy risks. The controls are employed as part of a well-defined risk management process that supports organizational information security and privacy programs. In turn, those information security and privacy programs lay the foundation for the success of the mission and business functions of the organization. It is important that responsible officials understand the security and privacy risks that could adversely affect organizational operations and assets, individuals, other organizations, and the Nation.9 These officials must also understand the current status of their security and privacy programs and the controls planned or in place to protect information, information systems, and organizations in order to make informed judgments and investments that respond to identified risks in an acceptable manner. The objective is to manage these risks through the selection and implementation of security and privacy controls.', 'vec_doc-14-nist-sp-800-53-p29-72', 0, 405, 'v2.1.0', '1d1fad491b16eae23cc4d6f139c12e4041a0008f57449d3f581ebb35fbfc1737', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 2","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":72,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 2"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p29-73', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.1   PURPOSE AND APPLICABILITY', 29, 'This publication establishes controls for systems and organizations. The controls can be implemented within any organization or system that processes, stores, or transmits information. The use of these controls is mandatory for federal information systems10 in accordance with Office of Management and Budget (OMB) Circular A-130 [OMB A-130] and the provisions of the Federal Information Security Modernization Act11 [FISMA], which requires the implementation of minimum controls to protect federal information and information systems.12 This publication, along with other supporting NIST publications, is designed to help organizations identify the security and privacy controls needed to manage risk and to satisfy the security and privacy requirements in FISMA, the Privacy Act of 1974 [PRIVACT], OMB policies (e.g., [OMB A-130]), and designated Federal Information Processing Standards (FIPS), among others.', 'vec_doc-14-nist-sp-800-53-p29-73', 0, 228, 'v2.1.0', '94f18d299eed3dd11c07c0638c9b37baaed405474a50e882f50ceda52cb77aee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.1   PURPOSE AND APPLICABILITY","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":73,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.1   PURPOSE AND APPLICABILITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p29-74', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.1   PURPOSE AND APPLICABILITY', 29, 'It accomplishes this objective by providing a comprehensive and flexible catalog of security and privacy controls to meet current and future protection needs based on changing threats, vulnerabilities, requirements, and technologies. The publication also improves communication among organizations by providing a common lexicon that supports the discussion of security, privacy, and risk management concepts. 8 The Risk Management Framework in [SP 800-37] is an example of a comprehensive risk management process. 9 This includes risk to critical infrastructure and key resources described in [HSPD-7]. 10 A federal information system is an information system used or operated by an agency, a contractor of an agency, or another organization on behalf of an agency. 11 Information systems that have been designated as national security systems, as defined in 44 U.S.C., Section 3542, are not subject to the requirements in [FISMA].', 'vec_doc-14-nist-sp-800-53-p29-74', 0, 233, 'v2.1.0', 'b6de45abf1d2a0cdf966db77fa18c59ba5f3e2e35960f6e55f7c55d816c932ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.1   PURPOSE AND APPLICABILITY","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":74,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.1   PURPOSE AND APPLICABILITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p29-75', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.1   PURPOSE AND APPLICABILITY', 29, 'However, the controls established in this publication may be selected for national security systems as otherwise required (e.g., the Privacy Act of 1974) or with the approval of federal officials exercising policy authority over such systems. [CNSSP 22] and [CNSSI 1253] provide guidance for national security systems. [DODI 8510.01] provides guidance for the Department of Defense. 12 While the controls established in this publication are mandatory for federal information systems and organizations, other organizations such as state, local, and tribal governments as well as private sector organizations are encouraged to consider using these guidelines, as appropriate. See [SP 800-53B] for federal control baselines.', 'vec_doc-14-nist-sp-800-53-p29-75', 0, 181, 'v2.1.0', '744685bf49689d714b2c1ab9705e25e3ca1c2943119a4bd7aa0971674f02bc51', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.1   PURPOSE AND APPLICABILITY","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":75,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.1   PURPOSE AND APPLICABILITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p30-76', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 3', 30, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Finally, the controls are independent of the process employed to select those controls. The control selection process can be part of an organization-wide risk management process, a systems engineering process [SP 800-160-1],13 the Risk Management Framework [SP 800-37], the Cybersecurity Framework [NIST CSF], or the Privacy Framework [NIST PF].14 The control selection criteria can be guided and informed by many factors, including mission and business needs, stakeholder protection needs, threats, vulnerabilities, and requirements to comply with federal laws, executive orders, directives, regulations, policies, standards, and guidelines. The combination of a catalog of security and privacy controls and a risk-based control selection process can help organizations comply with stated security and privacy requirements, obtain adequate security for their information systems, and protect the privacy of individuals.', 'vec_doc-14-nist-sp-800-53-p30-76', 0, 253, 'v2.1.0', '42ca6e1c52d3800cb7afe4a3436e2a8a3ffcde3ff4cb87f4b439f44ba91d5ff8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 3","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":76,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 3"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p30-77', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.2   TARGET AUDIENCE', 30, 'This publication is intended to serve a diverse audience, including: • Individuals with system, information security, privacy, or risk management and oversight responsibilities, including authorizing officials, chief information officers, senior agency information security officers, and senior agency officials for privacy; • Individuals with system development responsibilities, including mission owners, program managers, system engineers, system security engineers, privacy engineers, hardware and software developers, system integrators, and acquisition or procurement officials; • Individuals with logistical or disposition-related responsibilities, including program managers, procurement officials, system integrators, and property managers; • Individuals with security and privacy implementation and operations responsibilities, including mission or business owners, system owners, information owners or stewards, system administrators, continuity planners, and system security or privacy officers; • Individuals with security and privacy assessment and monitoring responsibilities, including auditors, Inspectors General, system evaluators, control assessors, independent verifiers and validators, and analysts; and • Commercial entities, including industry partners, producing component products and systems, creating security and privacy technologies, or providing services or capabilities that support information security or privacy.', 'vec_doc-14-nist-sp-800-53-p30-77', 0, 362, 'v2.1.0', '1d4aee497e5bdf37ae5f43d9420cae727490489002561e6dc5f75b3c5d91f2ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.2   TARGET AUDIENCE","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":77,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.2   TARGET AUDIENCE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p30-78', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.3   ORGANIZATIONAL RESPONSIBILITIES', 30, 'Managing security and privacy risks is a complex, multifaceted undertaking that requires: • Well-defined security and privacy requirements for systems and organizations; • The use of trustworthy information system components based on state-of-the-practice hardware, firmware, and software development and acquisition processes; 13 Risk management is an integral part of systems engineering, systems security engineering, and privacy engineering. 14 [OMB A-130] requires federal agencies to implement the NIST Risk Management Framework for the selection of controls for federal information systems. [EO 13800] requires federal agencies to implement the NIST Framework for Improving Critical Infrastructure Cybersecurity to manage cybersecurity risk. The NIST frameworks are also available to nonfederal organizations as optional resources.', 'vec_doc-14-nist-sp-800-53-p30-78', 0, 210, 'v2.1.0', 'b65a80656e6decd7c5422ea8032dc840c89771cd95b404744df5b5e47631aa2c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.3   ORGANIZATIONAL RESPONSIBILITIES","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":78,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.3   ORGANIZATIONAL RESPONSIBILITIES"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p31-79', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 4', 31, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 • Rigorous security and privacy planning and system development life cycle management; • The application of system security and privacy engineering principles and practices to securely develop and integrate system components into information systems; • The employment of security and privacy practices that are properly documented and integrated into and supportive of the institutional and operational processes of organizations; and • Continuous monitoring of information systems and organizations to determine the ongoing effectiveness of controls, changes in information systems and environments of operation, and the state of security and privacy organization-wide. Organizations continuously assess the security and privacy risks to organizational operations and assets, individuals, other organizations, and the Nation.', 'vec_doc-14-nist-sp-800-53-p31-79', 0, 230, 'v2.1.0', 'c77dd2e2f7adf09da2b6139ba7b1da05c1b8d4a949cfe38d4e17485ff9660e99', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 4","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":79,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 4"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p31-80', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 4', 31, 'Security and privacy risks arise from the planning and execution of organizational mission and business functions, placing information systems into operation, or continuing system operations. Realistic assessments of risk require a thorough understanding of the susceptibility to threats based on the specific vulnerabilities in information systems and organizations and the likelihood and potential adverse impacts of successful exploitations of such vulnerabilities by those threats.15 Risk assessments also require an understanding of privacy risks.16 To address the organization’s concerns about assessment and determination of risk, security and privacy requirements are satisfied with the knowledge and understanding of the organizational risk management strategy.17 The risk management strategy considers the cost, schedule, performance, and supply chain issues associated with the design, development, acquisition, deployment, operation, sustainment, and disposal of organizational systems.', 'vec_doc-14-nist-sp-800-53-p31-80', 0, 250, 'v2.1.0', '610610549ee0cab6d66a24baa8769e7aa3e656bb81d98dc300e7982d904d627a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 4","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":80,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 4"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p31-81', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 4', 31, 'A risk management process is then applied to manage risk on an ongoing basis.18 The catalog of security and privacy controls can be effectively used to protect organizations, individuals, and information systems from traditional and advanced persistent threats and privacy risks arising from the processing of personally identifiable information (PII) in varied operational, environmental, and technical scenarios. The controls can be used to demonstrate compliance with a variety of governmental, organizational, or institutional security and privacy requirements. Organizations have the responsibility to select the appropriate security and privacy controls, to implement the controls correctly, and to demonstrate the effectiveness of the controls in satisfying security and privacy requirements.', 'vec_doc-14-nist-sp-800-53-p31-81', 0, 200, 'v2.1.0', '7389aced5319b28e84a29d5095bcb3c6b60a3afa38010b9517ab7ad47a65048d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 4","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":81,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 4"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p31-82', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 4', 31, '19 Security and privacy controls can also be used in developing specialized baselines or overlays for unique or specialized missions or business applications, information systems, threat concerns, operational environments, technologies, or communities of interest.20 15 [SP 800-30] provides guidance on the risk assessment process. 16 [IR 8062] introduces privacy risk concepts. 17 [SP 800-39] provides guidance on risk management processes and strategies. 18 [SP 800-37] provides a comprehensive risk management process. 19 [SP 800-53A] provides guidance on assessing the effectiveness of controls. 20 [SP 800-53B] provides guidance for tailoring security and privacy control baselines and for developing overlays to support the specific protection needs and requirements of stakeholders and their organizations.', 'vec_doc-14-nist-sp-800-53-p31-82', 0, 204, 'v2.1.0', 'a0ef6a5cbb108606fb75359a0d0a741bb196a09e27a9ea5891697513c52573c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 4","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":82,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 4"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p32-83', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 5', 32, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Organizational risk assessments are used, in part, to inform the security and privacy control selection process. The selection process results in an agreed-upon set of security and privacy controls addressing specific mission or business needs consistent with organizational risk tolerance.21 The process preserves, to the greatest extent possible, the agility and flexibility that organizations need to address an increasingly sophisticated and hostile threat space, mission and business requirements, rapidly changing technologies, complex supply chains, and many types of operational environments.', 'vec_doc-14-nist-sp-800-53-p32-83', 0, 173, 'v2.1.0', '8c97e059a97a98d8113d7b6fbf4e774f9e2692cfad89ecbb5c41a5c05531e2a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 5","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":83,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 5"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p32-84', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.4   RELATIONSHIP TO OTHER PUBLICATIONS', 32, 'This publication defines controls to satisfy a diverse set of security and privacy requirements that have been levied on information systems and organizations and that are consistent with and complementary to other recognized national and international information security and privacy standards. To develop a broadly applicable and technically sound set of controls for information systems and organizations, many sources were considered during the development of this publication. These sources included requirements and controls from the manufacturing, defense, financial, healthcare, transportation, energy, intelligence, industrial control, and audit communities as well as national and international standards organizations. In addition, the controls in this publication are used by the national security community in publications such as Committee on National Security Systems (CNSS) Instruction No. 1253 [CNSSI 1253] to provide guidance specific to systems designated as national security systems. Whenever possible, the controls have been mapped to international standards to help ensure maximum usability and applicability.22 The relationship of this publication to other risk management, security, privacy, and publications can be found at [FISMA IMP].', 'vec_doc-14-nist-sp-800-53-p32-84', 0, 316, 'v2.1.0', 'f325ff894bd0f1480e4a63664a20af814410cb5ff81338fed7386b78f25c333d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.4   RELATIONSHIP TO OTHER PUBLICATIONS","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":84,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.4   RELATIONSHIP TO OTHER PUBLICATIONS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p32-85', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.5   REVISIONS AND EXTENSIONS', 32, 'The security and privacy controls described in this publication represent the state-of-the- practice protection measures for individuals, information systems, and organizations. The controls are reviewed and revised periodically to reflect the experience gained from using the controls; new or revised laws, executive orders, directives, regulations, policies, and standards; changing security and privacy requirements; emerging threats, vulnerabilities, attack and information processing methods; and the availability of new technologies. The security and privacy controls in the control catalog are also expected to change over time as controls are withdrawn, revised, and added. In addition to the need for change, the need for stability is addressed by requiring that proposed modifications to security and privacy controls go through a rigorous and transparent public review process to obtain public and private sector feedback and to build a consensus for such change. The review process provides a technically sound, flexible, and stable set of security and privacy controls for the organizations that use the control catalog.', 'vec_doc-14-nist-sp-800-53-p32-85', 0, 284, 'v2.1.0', '89f438036785b03e6c4982d922b8742e568aa47b3cf7f58f34f087843ed9a961', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.5   REVISIONS AND EXTENSIONS","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":85,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.5   REVISIONS AND EXTENSIONS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p32-86', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1.6   PUBLICATION ORGANIZATION', 32, 'The remainder of this special publication is organized as follows: 21 Authorizing officials or their designated representatives, by accepting the security and privacy plans, agree to the security and privacy controls proposed to meet the security and privacy requirements for organizations and systems. 22 Mapping tables are available at [SP 800-53 RES].', 'vec_doc-14-nist-sp-800-53-p32-86', 0, 89, 'v2.1.0', 'eb7f4ddef478ed0aa6d4ae7e0670277ffb24809031b15b715a5f8bcfdde26280', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1.6   PUBLICATION ORGANIZATION","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":86,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1.6   PUBLICATION ORGANIZATION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p33-87', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER ONE  PAGE 6', 33, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 • Chapter Two describes the fundamental concepts associated with security and privacy controls, including the structure of the controls, how the controls are organized in the consolidated catalog, control implementation approaches, the relationship between security and privacy controls, and trustworthiness and assurance. • Chapter Three provides a consolidated catalog of security and privacy controls including a discussion section to explain the purpose of each control and to provide useful information regarding control implementation and assessment, a list of related controls to show the relationships and dependencies among controls, and a list of references to supporting publications that may be helpful to organizations. • References, Glossary, Acronyms, and Control Summaries provide additional information on the use of security and privacy controls.23 23 Unless otherwise stated, all references to NIST publications refer to the most recent version of those publications.', 'vec_doc-14-nist-sp-800-53-p33-87', 0, 270, 'v2.1.0', '51a1f2f6d7d57ff2566e675c6a52a4b0f46e3b34a40aee0482a758bac5652555', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER ONE  PAGE 6","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":87,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER ONE  PAGE 6"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p34-88', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO', 34, 'THE FUNDAMENTALS STRUCTURE, TYPE, AND ORGANIZATION OF SECURITY AND PRIVACY CONTROLS This chapter presents the fundamental concepts associated with security and privacy controls, including the relationship between requirements and controls, the structure of controls, how controls are organized in the consolidated control catalog, the different control implementation approaches for information systems and organizations, the relationship between security and privacy controls, the importance of the concepts of trustworthiness and assurance for security and privacy controls, and the effects of the controls on achieving trustworthy, secure, and resilient systems.', 'vec_doc-14-nist-sp-800-53-p34-88', 0, 167, 'v2.1.0', '63d3334119ea7bc2ceed3e5eb11e1f3e0f459ab8963e509b444312423daae137', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":88,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p34-89', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.1   REQUIREMENTS AND CONTROLS', 34, 'It is important to understand the relationship between requirements and controls. For federal information security and privacy policies, the term requirement is generally used to refer to information security and privacy obligations imposed on organizations. For example, [OMB A- 130] imposes information security and privacy requirements with which federal agencies must comply when managing information resources. The term requirement can also be used in a broader sense to refer to an expression of stakeholder protection needs for a particular system or organization. Stakeholder protection needs and the corresponding security and privacy requirements may be derived from many sources (e.g., laws, executive orders, directives, regulations, policies, standards, mission and business needs, or risk assessments).', 'vec_doc-14-nist-sp-800-53-p34-89', 0, 204, 'v2.1.0', 'ac82d85a6ab99b0873d6becea2fbfe68cfec409c5ef39f66829f46232af1c8c3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.1   REQUIREMENTS AND CONTROLS","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":89,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.1   REQUIREMENTS AND CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p34-90', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.1   REQUIREMENTS AND CONTROLS', 34, 'The term requirement, as used in this guideline, includes both legal and policy requirements, as well as an expression of the broader set of stakeholder protection needs that may be derived from other sources. All of these requirements, when applied to a system, help determine the necessary characteristics of the system— encompassing security, privacy, and assurance. 24 Organizations may divide security and privacy requirements into more granular categories, depending on where the requirements are employed in the system development life cycle (SDLC) and for what purpose. Organizations may use the term capability requirement to describe a capability that the system or organization must provide to satisfy a stakeholder protection need.', 'vec_doc-14-nist-sp-800-53-p34-90', 0, 186, 'v2.1.0', '5166f1afa9589c16b0577e36edb67d37982fe1846d92c587f878550a75cd8b74', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.1   REQUIREMENTS AND CONTROLS","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":90,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.1   REQUIREMENTS AND CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p34-91', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.1   REQUIREMENTS AND CONTROLS', 34, 'In addition, organizations may refer to system requirements that pertain to particular hardware, software, and firmware components of a system as specification requirements— that is, capabilities that implement all or part of a control and that may be assessed (i.e., as part of the verification, validation, testing, and evaluation processes). Finally, organizations may use the term statement of work requirements to refer to actions that must be performed operationally or during system development.', 'vec_doc-14-nist-sp-800-53-p34-91', 0, 126, 'v2.1.0', 'f6f5760273efe519d5f2b01ea6633de31c183b909fe33547c29d9c535e339fe3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.1   REQUIREMENTS AND CONTROLS","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":91,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.1   REQUIREMENTS AND CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p34-92', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.1   REQUIREMENTS AND CONTROLS', 34, '24 The system characteristics that impact security and privacy vary and include the system type and function in terms of its primary purpose; the system make-up in terms of its technology, mechanical, physical, and human elements; the modes and states within which the system delivers its functions and services; the criticality or importance of the system and its constituent functions and services; the sensitivity of the data or information processed, stored, or transmitted; the consequence of loss, failure, or degradation relative to the ability of the system to execute correctly and to provide for its own protection (i.e., self-protection); and monetary or other value [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p34-92', 0, 174, 'v2.1.0', 'de227f2f7258663abb183f51fdab107de5c1a544c1e67c3c8314f1e5d2bd9d6a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.1   REQUIREMENTS AND CONTROLS","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":92,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.1   REQUIREMENTS AND CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p35-93', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 8', 35, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Controls can be viewed as descriptions of the safeguards and protection capabilities appropriate for achieving the particular security and privacy objectives of the organization and reflecting the protection needs of organizational stakeholders. Controls are selected and implemented by the organization in order to satisfy the system requirements. Controls can include administrative, technical, and physical aspects. In some cases, the selection and implementation of a control may necessitate additional specification by the organization in the form of derived requirements or instantiated control parameter values. The derived requirements and control parameter values may be necessary to provide the appropriate level of implementation detail for particular controls within the SDLC.', 'vec_doc-14-nist-sp-800-53-p35-93', 0, 220, 'v2.1.0', 'a953e146a69c601a311def84f8167a81434ebe58b72db9ee79fd00036127fe18', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 8","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":93,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 8"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p35-94', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.2   CONTROL STRUCTURE AND ORGANIZATION', 35, 'Security and privacy controls described in this publication have a well-defined organization and structure. For ease of use in the security and privacy control selection and specification process, controls are organized into 20 families.25 Each family contains controls that are related to the specific topic of the family. A two-character identifier uniquely identifies each control family (e.g., PS for Personnel Security). Security and privacy controls may involve aspects of policy, oversight, supervision, manual processes, and automated mechanisms that are implemented by systems or actions by individuals. Table 1 lists the security and privacy control families and their associated family identifiers.', 'vec_doc-14-nist-sp-800-53-p35-94', 0, 178, 'v2.1.0', '21c5d42d306a1314827b59588e09bfd8760cc0d1323147f39f98d5f824a77552', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.2   CONTROL STRUCTURE AND ORGANIZATION","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":94,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.2   CONTROL STRUCTURE AND ORGANIZATION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p35-95', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.2   CONTROL STRUCTURE AND ORGANIZATION', 35, 'TABLE 1: SECURITY AND PRIVACY CONTROL FAMILIES ID FAMILY ID FAMILY AC Access Control PE Physical and Environmental Protection AT Awareness and Training PL Planning AU Audit and Accountability PM Program Management CA Assessment, Authorization, and Monitoring PS Personnel Security CM Configuration Management PT PII Processing and Transparency CP Contingency Planning RA Risk Assessment IA Identification and Authentication SA System and Services Acquisition IR Incident Response SC System and Communications Protection MA Maintenance  SI System and Information Integrity MP Media Protection  SR Supply Chain Risk Management Families of controls contain base controls and control enhancements, which are directly related to their base controls. Control enhancements either add functionality or specificity to a base control or increase the strength of a base control.', 'vec_doc-14-nist-sp-800-53-p35-95', 0, 217, 'v2.1.0', '22e0a1464f017f54b7e62489715d1b4a0f1e31162dc337bef7ffed51888f0522', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.2   CONTROL STRUCTURE AND ORGANIZATION","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":95,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.2   CONTROL STRUCTURE AND ORGANIZATION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p35-96', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.2   CONTROL STRUCTURE AND ORGANIZATION', 35, 'Control enhancements are used in systems and environments of operation that require greater protection than the protection provided by the base control. The need for organizations to select and implement control enhancements is due to the potential adverse organizational or individual impacts or when organizations require additions to the base control functionality or assurance based on assessments of risk. The 25 Of the 20 control families in NIST SP 800-53, 17 are aligned with the minimum security requirements in [FIPS 200]. The Program Management (PM), PII Processing and Transparency (PT), and Supply Chain Risk Management (SR) families address enterprise-level program management, privacy, and supply chain risk considerations pertaining to federal mandates emergent since [FIPS 200].', 'vec_doc-14-nist-sp-800-53-p35-96', 0, 199, 'v2.1.0', 'dbcefbd478356f97729a7042758fd7435d853b25958c61a7c74b3c4a4b001b62', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.2   CONTROL STRUCTURE AND ORGANIZATION","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":96,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.2   CONTROL STRUCTURE AND ORGANIZATION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p36-97', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 9', 36, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 selection and implementation of control enhancements always requires the selection and implementation of the base control. The families are arranged in alphabetical order, while the controls and control enhancements within each family are in numerical order. The order of the families, controls, and control enhancements does not imply any logical progression, level of prioritization or importance, or order in which the controls or control enhancements are to be implemented. Rather, it reflects the order in which they were included in the catalog. Control designations are not re-used when a control is withdrawn. Security and privacy controls have the following structure: a base control section, a discussion section, a related controls section, a control enhancements section, and a references section. Figure 1 illustrates the structure of a typical control.', 'vec_doc-14-nist-sp-800-53-p36-97', 0, 240, 'v2.1.0', '04cfefb66b5748c553e0c045de49c0fbc91cfce7e40e43faf1fe5dabeb858ad9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 9","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":97,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 9"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p36-98', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 9', 36, 'FIGURE 1: CONTROL STRUCTURE The control section prescribes a security or privacy capability to be implemented. Security and privacy capabilities are achieved by the activities or actions, automated or nonautomated, carried out by information systems and organizations. Organizations designate the responsibility for control development, implementation, assessment, and monitoring. Organizations have the AU-4 AUDIT STORAGE CAPACITY Control:  Allocate audit record storage capacity to accommodate [Assignment: organization- defined audit record retention requirements]. Discussion:  Organizations consider the types of auditing to be performed and the audit processing requirements when allocating audit storage capacity. Allocating sufficient audit storage capacity reduces the likelihood of such capacity being exceeded and resulting in the potential loss or reduction of auditing capability. Related Controls:  AU-2, AU-5, AU-6, AU-7, AU-9, AU-11, AU-12, AU-14, SI-4.', 'vec_doc-14-nist-sp-800-53-p36-98', 0, 243, 'v2.1.0', 'ff8cf75c8d870732f2faa06dc25230e7345f2143f5e36f424b8c731d140f3d85', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 9","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":98,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 9"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p36-99', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 9', 36, 'Control Enhancements: (1) AUDIT STORAGE CAPACITY | TRANSFER TO ALTERNATE STORAGE Off-load audit records [Assignment: organization-defined frequency] onto a different system or media than the system being audited. Discussion:  Off-loading is a process designed to preserve the confidentiality and integrity of audit records by moving the records from the primary system to a secondary or alternate system. It is a common process in systems with limited audit storage capacity; the audit storage is used only in a transitory fashion until the system can communicate with the secondary or alternate system designated for storing the audit records, at which point the information is transferred. Related Controls:  None. References:  None. Base Control Organization-defined Parameter Control Enhancement Sources for additional information related to the control Organization-defined Parameter Control Identifier Control Name', 'vec_doc-14-nist-sp-800-53-p36-99', 0, 230, 'v2.1.0', '0094a8ad8c18a355208c48627be6e45ee76fa868b86038ac9a08e82b4ade3485', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 9","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":99,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 9"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p37-100', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 10', 37, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 flexibility to implement the controls selected in whatever manner that satisfies organizational mission or business needs consistent with law, regulation, and policy. The discussion section provides additional information about a control. Organizations can use the information as needed when developing, tailoring, implementing, assessing, or monitoring controls. The information provides important considerations for implementing controls based on mission or business requirements, operational environments, or assessments of risk. The additional information can also explain the purpose of controls and often includes examples. Control enhancements may also include a separate discussion section when the discussion information is applicable only to a specific control enhancement.', 'vec_doc-14-nist-sp-800-53-p37-100', 0, 219, 'v2.1.0', '46c805e8597ed8932e9246ffb1317bcc3f5f1d209036e814148927483f557f19', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 10","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":100,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 10"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p37-101', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 10', 37, 'The related controls section provides a list of controls from the control catalog that impact or support the implementation of a particular control or control enhancement, address a related security or privacy capability, or are referenced in the discussion section. Control enhancements are inherently related to their base control. Thus, related controls that are referenced in the base control are not repeated in the control enhancements. However, there may be related controls identified for control enhancements that are not referenced in the base control (i.e., the related control is only associated with the specific control enhancement). Controls may also be related to enhancements of other base controls. When a control is designated as a related control, a corresponding designation is made on that control in its source location in the catalog to illustrate the two-way relationship.', 'vec_doc-14-nist-sp-800-53-p37-101', 0, 225, 'v2.1.0', 'e2cc966e8e612f81e4e1c43298227311798afaf0b4f5d2e5aa09c2723a26d122', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 10","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":101,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 10"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p37-102', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 10', 37, 'Additionally, each control in a given family is inherently related to the -1 control (Policy and Procedures) in the same family. Therefore, the relationship between the -1 control and the other controls in the same family is not specified in the related controls section for each control. The control enhancements section provides statements of security and privacy capability that augment a base control. The control enhancements are numbered sequentially within each control so that the enhancements can be easily identified when selected to supplement the base control. Each control enhancement has a short subtitle to indicate the intended function or capability provided by the enhancement. In the AU-4 example, if the control enhancement is selected, the control designation becomes AU-4(1). The numerical designation of a control enhancement is used only to identify that enhancement within the control.', 'vec_doc-14-nist-sp-800-53-p37-102', 0, 228, 'v2.1.0', 'e70b0260043025c9dc43ac3f466cbaf80f940cc4828b2d29021a669033e723cf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 10","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":102,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 10"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p37-103', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 10', 37, 'The designation is not indicative of the strength of the control enhancement, level of protection, priority, degree of importance, or any hierarchical relationship among the enhancements. Control enhancements are not intended to be selected independently. That is, if a control enhancement is selected, then the corresponding base control is also selected and implemented. The references section includes a list of applicable laws, policies, standards, guidelines, websites, and other useful references that are relevant to a specific control or control enhancement. 26 The references section also includes hyperlinks to publications for obtaining additional information for control development, implementation, assessment, and monitoring. For some controls, additional flexibility is provided by allowing organizations to define specific values for designated parameters associated with the controls.', 'vec_doc-14-nist-sp-800-53-p37-103', 0, 226, 'v2.1.0', '1e97cdab796c6a3876b1c6df82150ef6852c3e4a01571e845c5f8f469917a30b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 10","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":103,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 10"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p37-104', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 10', 37, 'Flexibility is achieved as part of a tailoring process using assignment and selection operations embedded within the controls and 26 References are provided to assist organizations in understanding and implementing the security and privacy controls and are not intended to be inclusive or complete.', 'vec_doc-14-nist-sp-800-53-p37-104', 0, 75, 'v2.1.0', 'e0a4cf0d16d0c219c27f9a1b860c35e557de78186fff040555b0809fff6361ec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 10","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":104,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 10"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p38-105', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 11', 38, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 enclosed by brackets. The assignment and selection operations give organizations the capability to customize controls based on organizational security and privacy requirements. In contrast to assignment operations which allow complete flexibility in the designation of parameter values, selection operations narrow the range of potential values by providing a specific list of items from which organizations choose. Determination of the organization-defined parameters can evolve from many sources, including laws, executive orders, directives, regulations, policies, standards, guidance, and mission or business needs. Organizational risk assessments and risk tolerance are also important factors in determining the values for control parameters. Once specified by the organization, the values for the assignment and selection operations become a part of the control.', 'vec_doc-14-nist-sp-800-53-p38-105', 0, 240, 'v2.1.0', '5f9b5b4bcbfbe3cd0be8bee724cd3e85003b882ce875d096349d2f0ca0b3f1c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 11","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":105,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 11"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p38-106', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 11', 38, 'Organization-defined control parameters used in the base controls also apply to the control enhancements associated with those controls. The implementation of the control is assessed for effectiveness against the completed control statement. In addition to assignment and selection operations embedded in a control, additional flexibility is achieved through iteration and refinement actions. Iteration allows organizations to use a control multiple times with different assignment and selection values, perhaps being applied in different situations or when implementing multiple policies. For example, an organization may have multiple systems implementing a control but with different parameters established to address different risks for each system and environment of operation. Refinement is the process of providing additional implementation detail to a control.', 'vec_doc-14-nist-sp-800-53-p38-106', 0, 217, 'v2.1.0', '30d7b35d1e18a35e0a177bdc26d05fe1a18fd45a1fae55f0701ad149cea724d9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 11","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":106,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 11"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p38-107', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 11', 38, 'Refinement can also be used to narrow the scope of a control in conjunction with iteration to cover all applicable scopes (e.g., applying different authentication mechanisms to different system interfaces). The combination of assignment and selection operations and iteration and refinement actions when applied to controls provides the needed flexibility to allow organizations to satisfy a broad base of security and privacy requirements at the organization, mission and business process, and system levels of implementation.', 'vec_doc-14-nist-sp-800-53-p38-107', 0, 132, 'v2.1.0', 'c8bbff9961b6e5dadd633f0e58005ad72ec245409fa079ec5d2c4292214febf7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 11","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":107,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 11"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p38-108', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.3   CONTROL IMPLEMENTATION APPROACHES', 38, 'There are three approaches to implementing the controls in Chapter Three: (1) a common (inheritable) control implementation approach, (2) a system-specific control implementation approach, and (3) a hybrid control implementation approach. The control implementation approaches define the scope of applicability for the control, the shared nature or inheritability of the control, and the responsibility for control development, implementation, assessment, and SECURITY AS A DESIGN PROBLEM “Providing satisfactory security controls in a computer system is….a system design problem. A combination of hardware, software, communications, physical, personnel and administrative - procedural safeguards is required for comprehensive security….software safeguards alone are not sufficient.” -- The Ware Report Defense Science Board Task Force on Computer Security, 1970', 'vec_doc-14-nist-sp-800-53-p38-108', 0, 216, 'v2.1.0', '01a8ead389f5c21823c41cae1304ae75b325ced5b7ada8cea9ec211f662dd7a8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.3   CONTROL IMPLEMENTATION APPROACHES","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":108,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.3   CONTROL IMPLEMENTATION APPROACHES"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p39-109', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 12', 39, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 authorization. Each control implementation approach has a specific objective and focus that helps organizations select the appropriate controls, implement the controls in an effective manner, and satisfy security and privacy requirements. A specific control implementation approach may achieve cost benefits by leveraging security and privacy capabilities across multiple systems and environments of operation.27 Common controls are controls whose implementation results in a capability that is inheritable by multiple systems or programs. A control is deemed inheritable when the system or program receives protection from the implemented control, but the control is developed, implemented, assessed, authorized, and monitored by an internal or external entity other than the entity responsible for the system or program.', 'vec_doc-14-nist-sp-800-53-p39-109', 0, 229, 'v2.1.0', '61cd1bffd0bab6b4d52d720961531383f036bf7180d030a92b49e5ac793e6a20', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 12","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":109,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 12"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p39-110', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 12', 39, 'The security and privacy capabilities provided by common controls can be inherited from many sources, including mission or business lines, organizations, enclaves, environments of operation, sites, or other systems or programs. Implementing controls as common controls can introduce the risk of a single point of failure. Many of the controls needed to protect organizational information systems— including many physical and environmental protection controls, personnel security controls, and incident response controls— are inheritable and, therefore, are good candidates for common control status. Common controls can also include technology-based controls, such as identification and authentication controls, boundary protection controls, audit and accountability controls,  and access controls.', 'vec_doc-14-nist-sp-800-53-p39-110', 0, 200, 'v2.1.0', 'c0e66de63220ae482bd98436927ebf2b309cefaa4161fcd1ef77e890f22f4014', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 12","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":110,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 12"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p39-111', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 12', 39, 'The cost of development, implementation, assessment, authorization, and monitoring can be amortized across multiple systems, organizational elements, and programs using the common control implementation approach. Controls not implemented as common controls are implemented as system-specific or hybrid controls. System-specific controls are the primary responsibility of the system owner and the authorizing official for a given system. Implementing system-specific controls can introduce risk if the control implementations are not interoperable with common controls. Organizations can implement a control as hybrid if one part of the control is common (inheritable) and the other part is system-specific. For example, an organization may implement control CP-2 using a predefined template for the contingency plan for all organizational information systems with individual system owners tailoring the plan for system-specific uses, where appropriate.', 'vec_doc-14-nist-sp-800-53-p39-111', 0, 238, 'v2.1.0', 'fb83add2f1fb9a9d8c3ec925d81d83f4acfd065091da59da2b8167c37e7385a0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 12","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":111,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 12"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p39-112', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 12', 39, 'The division of a hybrid control into its common (inheritable) and system-specific parts may vary by organization, depending on the types of information technologies employed, the approach used by the organization to manage its controls, and assignment of responsibilities. When a control is implemented as a hybrid control, the common control provider is responsible for ensuring the implementation, assessment, and monitoring of the common part of the hybrid control, and the system owner is responsible for ensuring the implementation, assessment, and monitoring of the system-specific part of the hybrid control. Implementing controls as hybrid controls can introduce risk if the responsibility for the implementation and ongoing management of the common and system-specific parts of the controls is unclear. The determination as to the appropriate control implementation approach (i.e., common, hybrid, or system-specific) is context-dependent.', 'vec_doc-14-nist-sp-800-53-p39-112', 0, 238, 'v2.1.0', '8dd2a05b0d608a03280f7699b301dfcff756dcae5f53fac7015395c1cff04344', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 12","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":112,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 12"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p39-113', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 12', 39, 'The control implementation approach cannot be determined to be common, hybrid, or system-specific simply based on the language of the 27 [SP 800-37] provides additional guidance on control implementation approaches (formerly referred to as control designations) and how the different approaches are used in the Risk Management Framework.', 'vec_doc-14-nist-sp-800-53-p39-113', 0, 85, 'v2.1.0', '4477793603e549f8b0ce2e2d17b0d630098d5533c99d6415a28841cb7c68fe9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 12","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":113,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 12"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p40-114', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 13', 40, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 control. Identifying the control implementation approach can result in significant savings to organizations in implementation and assessment costs and a more consistent application of the controls organization-wide. Typically, the identification of the control implementation approach is straightforward. However, the implementation takes significant planning and coordination. Planning for the implementation approach of a control (i.e., common, hybrid, or system-specific) is best carried out early in the system development life cycle and coordinated with the entities providing the control [SP 800-37]. Similarly, if a control is to be inheritable, coordination is required with the inheriting entity to ensure that the control meets its needs. This is especially important given the nature of control parameters. An inheriting entity cannot assume that controls are the same and mitigate the appropriate risk to the system just because the control identifiers (e.g., AC-1) are the same. It is essential to examine the control parameters (e.g., assignment or selection operations) when determining if a common control is adequate to mitigate system-specific risks.', 'vec_doc-14-nist-sp-800-53-p40-114', 0, 315, 'v2.1.0', '19494ec5d6164bc1a1ef9387389005a45ca073f8e3bc9f24474940936cb2e773', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 13","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":114,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 13"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p40-115', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.4   SECURITY AND PRIVACY CONTROLS', 40, 'The selection and implementation of security and privacy controls reflect the objectives of information security and privacy programs and how those programs manage their respective risks. Depending on the circumstances, these objectives and risks can be independent or overlapping. Federal information security programs are responsible for protecting information and information systems from unauthorized access, use, disclosure, disruption, modification, or destruction (i.e., unauthorized activity or system behavior) to provide confidentiality, integrity, and availability. Those programs are also responsible for managing security risk and for ensuring compliance with applicable security requirements.', 'vec_doc-14-nist-sp-800-53-p40-115', 0, 177, 'v2.1.0', 'aff3a4eb88665282f88bceab450fe60749bb122dd722ee70dab5b8bf587eb20d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.4   SECURITY AND PRIVACY CONTROLS","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":115,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.4   SECURITY AND PRIVACY CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p40-116', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.4   SECURITY AND PRIVACY CONTROLS', 40, 'Federal privacy programs are responsible for managing risks to individuals associated with the creation, collection, use, processing, storage, maintenance, dissemination, disclosure, or disposal (collectively referred to as “processing”) of PII and for ensuring compliance with applicable privacy requirements.28 When a system processes PII, the information security program and the privacy program have a shared responsibility for managing the security risks for the PII in the system. Due to this overlap in responsibilities, the controls that organizations select to manage these security risks will generally be the same regardless of their designation as security or privacy controls in control baselines or program or system plans. There also may be circumstances in which the selection and/or implementation of the control or control enhancement affects the ability of a program to achieve its objectives and manage its respective risks.', 'vec_doc-14-nist-sp-800-53-p40-116', 0, 236, 'v2.1.0', '8c4ea1bb9671240690543bdbe9b3c869b871124207ee23b904ef80f1a9e9facc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.4   SECURITY AND PRIVACY CONTROLS","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":116,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.4   SECURITY AND PRIVACY CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p40-117', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.4   SECURITY AND PRIVACY CONTROLS', 40, 'The control discussion section may highlight specific security and/or privacy considerations so that organizations can take these considerations into account as they determine the most effective method to implement the control. However, these considerations are not exhaustive. For example, an organization might select AU-3 (Content of Audit Records) to support monitoring for unauthorized access to an information asset that does not include PII. Since the 28 Privacy programs may also choose to consider the risks to individuals that may arise from their interactions with information systems, where the processing of personally identifiable information may be less impactful than the effect that the system has on individuals’ behavior or activities. Such effects would constitute risks to individual autonomy, and organizations may need to take steps to manage those risks in addition to information security and privacy risks.', 'vec_doc-14-nist-sp-800-53-p40-117', 0, 233, 'v2.1.0', '550769fba4de34a66c90506f87e2e7da35777c696bced522191cce840203e431', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.4   SECURITY AND PRIVACY CONTROLS","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":117,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.4   SECURITY AND PRIVACY CONTROLS"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p41-118', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 14', 41, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 potential loss of confidentiality of the information asset does not affect privacy, security objectives are the primary driver for the selection of the control. However, the implementation of the control with respect to monitoring for unauthorized access could involve the processing of PII which may result in privacy risks and affect privacy program objectives. The discussion', 'vec_doc-14-nist-sp-800-53-p41-118', 0, 118, 'v2.1.0', '27eae9bb62381c1da52d6a4306d3908ca13db47750fe21bac5281137ff0c6b88', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 14","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":118,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 14"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p41-119', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'section in AU-3 includes privacy risk considerations so that organizations can take those', 41, 'considerations into account as they determine the best way to implement the control. Additionally, the control enhancement AU-3(3) (Limit Personally Identifiable Information Elements) could be selected to support managing these privacy risks. Due to permutations in the relationship between information security and privacy program objectives and risk management, there is a need for close collaboration between programs to select and implement the appropriate controls for information systems processing PII. Organizations consider how to promote and institutionalize collaboration between the two programs to ensure that the objectives of both disciplines are met and risks are appropriately managed. 29', 'vec_doc-14-nist-sp-800-53-p41-119', 0, 177, 'v2.1.0', 'b784941a29e33c1fc8946b0c02de0adc300ce97315b959adf729f28a5737f84c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"section in AU-3 includes privacy risk considerations so that organizations can take those","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":119,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"section in AU-3 includes privacy risk considerations so that organizations can take those"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p41-120', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.5   TRUSTWORTHINESS AND ASSURANCE', 41, 'The trustworthiness of systems, system components, and system services is an important part of the risk management strategies developed by organizations.30 Trustworthiness, in this context, means worthy of being trusted to fulfill whatever requirements may be needed for a component, subsystem, system, network, application, mission, business function, enterprise, or other entity.31 Trustworthiness requirements can include attributes of reliability, dependability, performance, resilience, safety, security, privacy, and survivability under a range of potential adversity in the form of disruptions, hazards, threats, and privacy risks. Effective measures of trustworthiness are meaningful only to the extent that the requirements are complete, well- defined, and can be accurately assessed. Two fundamental concepts that affect the trustworthiness of systems are functionality and assurance.', 'vec_doc-14-nist-sp-800-53-p41-120', 0, 224, 'v2.1.0', '73d85c875f88934585cbabe4a0e0376bdaeeacff527674dec3fff27fcc4d5baa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.5   TRUSTWORTHINESS AND ASSURANCE","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":120,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.5   TRUSTWORTHINESS AND ASSURANCE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p41-121', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.5   TRUSTWORTHINESS AND ASSURANCE', 41, 'Functionality is defined in terms of the security and privacy features, functions, mechanisms, services, procedures, and architectures implemented within organizational systems and programs and the environments in which those systems and programs operate. Assurance is the measure of confidence that the system functionality is implemented correctly, operating as intended, and producing the desired outcome with respect to meeting the security and privacy requirements for the system— thus possessing the capability to accurately mediate and enforce established security and privacy policies. In general, the task of providing meaningful assurance that a system is likely to do what is expected of it can be enhanced by techniques that simplify or narrow the analysis by, for example, increasing the discipline applied to the system architecture, software design, specifications, code style, and configuration management. Security and privacy controls address functionality and assurance.', 'vec_doc-14-nist-sp-800-53-p41-121', 0, 248, 'v2.1.0', 'b1a881d95975279daf4aa166411eb7ead08868dd42a9e42a46a5a4585a9ed23f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.5   TRUSTWORTHINESS AND ASSURANCE","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":121,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.5   TRUSTWORTHINESS AND ASSURANCE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p41-122', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2.5   TRUSTWORTHINESS AND ASSURANCE', 41, 'Certain controls focus primarily on functionality while other controls focus primarily on assurance. Some controls can support functionality and assurance. 29 Resources to support information security and privacy program collaboration are available at [SP 800-53 RES]. 30 [SP 800-160-1] provides guidance on systems security engineering and the application of security design principles to achieve trustworthy systems. 31 See [NEUM04].', 'vec_doc-14-nist-sp-800-53-p41-122', 0, 109, 'v2.1.0', '5e3597cc55296521400c3d73981c7ee3aa3d4f39e5125258f8d753da86471f62', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2.5   TRUSTWORTHINESS AND ASSURANCE","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":122,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2.5   TRUSTWORTHINESS AND ASSURANCE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p42-123', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER TWO  PAGE 15', 42, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Organizations can select assurance-related controls to define system development activities, generate evidence about the functionality and behavior of the system, and trace the evidence to the system elements that provide such functionality or exhibit such behavior. The evidence is used to obtain a degree of confidence that the system satisfies the stated security and privacy requirements while supporting the organization’s mission and business functions. Assurance- related controls are identified in the control summary tables in Appendix C. EVIDENCE OF CONTROL IMPLEMENTATION During control selection and implementation, it is important for organizations to consider  the evidence (e.g., artifacts, documentation) that will be needed to support current and future control assessments. Such assessments help determine whether the controls are implemented correctly, operating as intended, and satisfying security and privacy policies— thus, providing essential information for senior leaders to make informed risk-based decisions.', 'vec_doc-14-nist-sp-800-53-p42-123', 0, 282, 'v2.1.0', 'ee53ba7a0d7c86882fc328e21c84a08448a746bcef0861ebce542bdab7948bb3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER TWO  PAGE 15","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":123,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER TWO  PAGE 15"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p43-124', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE', 43, 'THE CONTROLS SECURITY AND PRIVACY CONTROLS AND CONTROL ENHANCEMENTS This catalog of security and privacy controls provides protective measures for systems, organizations, and individuals.32 The controls are designed to facilitate risk management and compliance with applicable federal laws, executive orders, directives, regulations, policies, and standards. With few exceptions, the security and privacy controls in the catalog are policy-, technology-, and sector-neutral, meaning that the controls focus on the fundamental measures necessary to protect information and the privacy of individuals across the information life cycle. While the security and privacy controls are largely policy-, technology-, and sector-neutral, that does not imply that the controls are policy-, technology-, and sector-unaware. Understanding policies, technologies, and sectors is necessary so that the controls are relevant when they are implemented.', 'vec_doc-14-nist-sp-800-53-p43-124', 0, 234, 'v2.1.0', '943e264a593c228591ca33ed0653426171fc04fe89218539ed6ad11c818103e0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":124,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p43-125', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE', 43, 'Employing a policy-, technology-, and sector-neutral control catalog has many benefits. It encourages organizations to: • Focus on the security and privacy functions and capabilities required for mission and business success and the protection of information and the privacy of individuals, irrespective of the technologies that are employed in organizational systems; • Analyze each security and privacy control for its applicability to specific technologies, environments of operation, mission and business functions, and communities of interest; and • Specify security and privacy policies as part of the tailoring process for controls that have variable parameters. In the few cases where specific technologies are referenced in controls, organizations are cautioned that the need to manage security and privacy risks may go beyond the requirements in a single control associated with a technology. The additional needed protection measures are obtained from the other controls in the catalog.', 'vec_doc-14-nist-sp-800-53-p43-125', 0, 250, 'v2.1.0', 'a726f0a11b141ea0596cf33adca3726325b3f083450ed7cbd76d0aa47c126386', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":125,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p43-126', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE', 43, 'Federal Information Processing Standards , Special Publications, and Interagency/Internal Reports provide guidance on selecting security and privacy controls that reduce risk for specific technologies and sector-specific applications, including smart grid, cloud, healthcare, mobile, industrial control systems, and Internet of Things (IoT) devices.33 NIST publications are cited as references as applicable to specific controls in Sections 3.1 through 3.20. Security and privacy controls in the catalog are expected to change over time as controls are withdrawn, revised, and added. To maintain stability in security and privacy plans, controls are not renumbered each time a control is withdrawn. Rather, notations of the controls that have been withdrawn are maintained in the control catalog for historical purposes.', 'vec_doc-14-nist-sp-800-53-p43-126', 0, 205, 'v2.1.0', '2ff32ca8188ff8d7fad6479a071470bfebc037975b56ee7b9af36643347ac806', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":126,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p43-127', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE', 43, 'Controls may be withdrawn for a variety of reasons, including when the function or capability provided by the control has been incorporated into another control, the control is redundant to an existing control, or the control is deemed to be no longer necessary or effective. 32 The controls in this publication are available online and can be obtained in various formats. See [NVD 800-53]. 33 For example, [SP 800-82] provides guidance on risk management and control selection for industrial control systems.', 'vec_doc-14-nist-sp-800-53-p43-127', 0, 128, 'v2.1.0', '94a1752b74fe57914bc796ee69e572650ebba16de9299b2a8b694db24f5e7e60', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":127,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p44-128', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 17', 44, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 New controls are developed on a regular basis using threat and vulnerability information and information on the tactics, techniques, and procedures used by adversaries. In addition, new controls are developed based on a better understanding of how to mitigate information security risks to systems and organizations and risks to the privacy of individuals arising from information processing. Finally, new controls are developed based on new or changing requirements in laws, executive orders, regulations, policies, standards, or guidelines. Proposed modifications to the controls are carefully analyzed during each revision cycle, considering the need for stability of controls and the need to be responsive to changing technologies, threats, vulnerabilities, types of attack, and processing methods. The objective is to adjust the level of information security and privacy over time to meet the needs of organizations and individuals.', 'vec_doc-14-nist-sp-800-53-p44-128', 0, 258, 'v2.1.0', '6721998aedf387e7c1c6152d0b645e160683095183f6a238a0a3c3018c089148', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 17","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":128,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 17"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p45-129', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.1   ACCESS CONTROL', 45, 'Quick link to Access Control Summary Table AC-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p45-129', 0, 44, 'v2.1.0', '02a8b99b0cabd1a685355572df1a135bbc6e7a4214a1bf87f8062145eafce748', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.1   ACCESS CONTROL","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":129,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.1   ACCESS CONTROL"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p45-130', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 45, 'level] access control policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p45-130', 0, 75, 'v2.1.0', 'a7017651b1bbb189d5208b89bf3ae28911e99544c43e89df14654f157d27b43d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":130,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p45-131', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the access control policy and the', 45, 'associated access controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the access control policy and procedures; and c. Review and update the current access control:', 'vec_doc-14-nist-sp-800-53-p45-131', 0, 62, 'v2.1.0', 'c795d9fa38b7507e256e713aac535a0a8c7632f1b073cd5971254545b8431ee6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the access control policy and the","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":131,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the access control policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p45-132', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Policy [Assignment: organization-defined frequency] and following [Assignment:', 45, 'organization-defined events]; and', 'vec_doc-14-nist-sp-800-53-p45-132', 0, 9, 'v2.1.0', '2e7e8a58d0ff0fd9c9784f20b39f5f30267caea29ba1aa8653cc7eb6ede7e415', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Policy [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":132,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Policy [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p45-133', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 45, 'organization-defined events]. Discussion:  Access control policy and procedures address the controls in the AC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of access control policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to access control policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  IA-1, PM-9, PM-24, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100], [IR 7874].', 'vec_doc-14-nist-sp-800-53-p45-133', 0, 428, 'v2.1.0', '1d2ccc95780e0722e5e88f551af6549584c766324e1d27285ef8471c10bd8e1d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":133,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p46-134', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 19', 46, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 AC-2 ACCOUNT MANAGEMENT Control: a. Define and document the types of accounts allowed and specifically prohibited for use within the system; b. Assign account managers; c. Require [Assignment: organization-defined prerequisites and criteria] for group and role membership; d. Specify:', 'vec_doc-14-nist-sp-800-53-p46-134', 0, 94, 'v2.1.0', '85b7dff85f1b81dbc78fb335685ce7878773f7a5ec02e415549e88e4ec81f6c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 19","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":134,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 19"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p46-135', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes', 46, '(as required)] for each account; e. Require approvals by [Assignment: organization-defined personnel or roles] for requests to create accounts; f. Create, enable, modify, disable, and remove accounts in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria]; g. Monitor the use of accounts; h. Notify account managers and [Assignment: organization-defined personnel or roles] within:', 'vec_doc-14-nist-sp-800-53-p46-135', 0, 107, 'v2.1.0', '09d55daa09e1ad9829359b7f8d783a769aedb2fcd8b4fa09fa951ff0260c8190', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":135,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p46-136', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined time period] when system usage or need-to-know', 46, 'changes for an individual; i. Authorize access to the system based on:', 'vec_doc-14-nist-sp-800-53-p46-136', 0, 18, 'v2.1.0', 'a0197e88b6340c96027f2dc79c999a5bbff31ce724fdd0e599a4bb9ba989853b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined time period] when system usage or need-to-know","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":136,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined time period] when system usage or need-to-know"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p46-137', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined attributes (as required)];', 46, 'j. Review accounts for compliance with account management requirements [Assignment: organization-defined frequency]; k. Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; and l. Align account management processes with personnel termination and transfer processes. Discussion:  Examples of system account types include individual, shared, group, system, guest, anonymous, emergency, developer, temporary, and service. Identification of authorized system users and the specification of access privileges reflect the requirements in other controls in the security plan. Users requiring administrative privileges on system accounts receive additional scrutiny by organizational personnel responsible for approving such accounts and privileged access, including system owner, mission or business owner, senior agency information security officer, or senior agency official for privacy. Types of accounts that organizations may wish to prohibit due to increased risk include shared, group, emergency, anonymous, temporary, and guest accounts.', 'vec_doc-14-nist-sp-800-53-p46-137', 0, 283, 'v2.1.0', '94427f9f2556a16315a97e0bf60d85ecc7eac82db56389ee8514d8f8d3377105', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined attributes (as required)];","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":137,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined attributes (as required)];"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p47-138', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 20', 47, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Where access involves personally identifiable information, security programs collaborate with the senior agency official for privacy to establish the specific conditions for group and role membership; specify authorized users, group and role membership, and access authorizations for each account; and create, adjust, or remove system accounts in accordance with organizational policies. Policies can include such information as account expiration dates or other factors that trigger the disabling of accounts. Organizations may choose to define access privileges or other attributes by account, type of account, or a combination of the two. Examples of other attributes required for authorizing access include restrictions on time of day, day of week, and point of origin. In defining other system account attributes, organizations consider system-related requirements and mission/business requirements.', 'vec_doc-14-nist-sp-800-53-p47-138', 0, 249, 'v2.1.0', 'fb77477db5a544c5332d848481e3b67918ac92c7e9f8a343f05c1f5b8b5f28c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 20","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":138,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 20"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p47-139', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 20', 47, 'Failure to consider these factors could affect system availability. Temporary and emergency accounts are intended for short-term use. Organizations establish temporary accounts as part of normal account activation procedures when there is a need for short-term accounts without the demand for immediacy in account activation. Organizations establish emergency accounts in response to crisis situations and with the need for rapid account activation. Therefore, emergency account activation may bypass normal account authorization processes. Emergency and temporary accounts are not to be confused with infrequently used accounts, including local logon accounts used for special tasks or when network resources are unavailable (may also be known as accounts of last resort). Such accounts remain available and are not subject to automatic disabling or removal dates.', 'vec_doc-14-nist-sp-800-53-p47-139', 0, 217, 'v2.1.0', '13b5de4d621bc30606cbd70546240cb8a183cf5faf8b6c4006757fcb7fa62f09', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 20","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":139,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 20"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p47-140', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 20', 47, 'Conditions for disabling or deactivating accounts include when shared/group, emergency, or temporary accounts are no longer required and when individuals are transferred or terminated. Changing shared/group authenticators when members leave the group is intended to ensure that former group members do not retain access to the shared or group account. Some types of system accounts may require specialized training. Related Controls:  AC-3, AC-5, AC-6, AC-17, AC-18, AC-20, AC-24, AU-2, AU-12, CM-5, IA-2, IA-4, IA-5, IA-8, MA-3, MA-5, PE-2, PL-4, PS-2, PS-4, PS-5, PS-7, PT-2, PT-3, SC-7, SC-12, SC-13, SC-37. Control Enhancements: (1) ACCOUNT MANAGEMENT | AUTOMATED SYSTEM ACCOUNT MANAGEMENT Support the management of system accounts using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p47-140', 0, 200, 'v2.1.0', '7a16eb38299e8d9bde0cc4de5ca90bd7dfa7476e8c7deb77815b8ec26a8fae73', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 20","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":140,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 20"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p47-141', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 20', 47, 'Discussion:  Automated system account management includes using automated mechanisms to create, enable, modify, disable, and remove accounts; notify account managers when an account is created, enabled, modified, disabled, or removed, or when users are terminated or transferred; monitor system account usage; and report atypical system account usage. Automated mechanisms can include internal system functions and email, telephonic, and text messaging notifications. Related Controls:  None. (2) ACCOUNT MANAGEMENT | AUTOMATED TEMPORARY AND EMERGENCY ACCOUNT MANAGEMENT Automatically [Selection: remove; disable] temporary and emergency accounts after [Assignment: organization-defined time period for each type of account]. Discussion:  Management of temporary and emergency accounts includes the removal or disabling of such accounts automatically after a predefined time period rather than at the convenience of the system administrator.', 'vec_doc-14-nist-sp-800-53-p47-141', 0, 236, 'v2.1.0', 'b2d3ea486baf17a4114ee47a6d06e72f8d3cea9b3f0f3d7fad15e64a8d987c54', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 20","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":141,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 20"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p47-142', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 20', 47, 'Automatic removal or disabling of accounts provides a more consistent implementation. Related Controls:  None. (3) ACCOUNT MANAGEMENT | DISABLE ACCOUNTS Disable accounts within [Assignment: organization-defined time period] when the accounts:', 'vec_doc-14-nist-sp-800-53-p47-142', 0, 61, 'v2.1.0', '288be3aab9f8ad8a4e694a4c8a6315fd3d231bde63e22840de1ae08590338e08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 20","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":142,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 20"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p48-143', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 21', 48, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (a) Have expired; (b) Are no longer associated with a user or individual; (c) Are in violation of organizational policy; or (d) Have been inactive for [Assignment: organization-defined time period]. Discussion:  Disabling expired, inactive, or otherwise anomalous accounts supports the concepts of least privilege and least functionality which reduce the attack surface of the system. Related Controls:  None. (4) ACCOUNT MANAGEMENT | AUTOMATED AUDIT ACTIONS Automatically audit account creation, modification, enabling, disabling, and removal actions. Discussion:  Account management audit records are defined in accordance with AU-2 and reviewed, analyzed, and reported in accordance with AU-6. Related Controls:  AU-2, AU-6. (5) ACCOUNT MANAGEMENT | INACTIVITY LOGOUT Require that users log out when [Assignment: organization-defined time period of expected inactivity or description of when to log out].', 'vec_doc-14-nist-sp-800-53-p48-143', 0, 250, 'v2.1.0', 'fe24fc04b831ea6734016a6ce3f6c39f06b071826c5737b8a049ae1a7f979d17', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 21","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":143,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 21"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p48-144', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 21', 48, 'Discussion:  Inactivity logout is behavior- or policy-based and requires users to take physical action to log out when they are expecting inactivity longer than the defined period. Automatic enforcement of inactivity logout is addressed by AC-11. Related Controls:  AC-11. (6) ACCOUNT MANAGEMENT | DYNAMIC PRIVILEGE MANAGEMENT Implement [Assignment: organization-defined dynamic privilege management capabilities]. Discussion:  In contrast to access control approaches that employ static accounts and predefined user privileges, dynamic access control approaches rely on runtime access control decisions facilitated by dynamic privilege management, such as attribute-based access control. While user identities remain relatively constant over time, user privileges typically change more frequently based on ongoing mission or business requirements and the operational needs of organizations.', 'vec_doc-14-nist-sp-800-53-p48-144', 0, 223, 'v2.1.0', 'cf8a37fe062f9ab39c101b20ce5fa24e454b9a0c92d03ff7cddf304a1599c31f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 21","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":144,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 21"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p48-145', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 21', 48, 'An example of dynamic privilege management is the immediate revocation of privileges from users as opposed to requiring that users terminate and restart their sessions to reflect changes in privileges. Dynamic privilege management can also include mechanisms that change user privileges based on dynamic rules as opposed to editing specific user profiles. Examples include automatic adjustments of user privileges if they are operating out of their normal work times, if their job function or assignment changes, or if systems are under duress or in emergency situations. Dynamic privilege management includes the effects of privilege changes, for example, when there are changes to encryption keys used for communications. Related Controls:  AC-16.', 'vec_doc-14-nist-sp-800-53-p48-145', 0, 188, 'v2.1.0', '639df044c7470532be1f77a9035aad5593b1473913592f29f8a91040de49bc7c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 21","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":145,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 21"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p48-146', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 21', 48, '(7) ACCOUNT MANAGEMENT | PRIVILEGED USER ACCOUNTS (a) Establish and administer privileged user accounts in accordance with [Selection: a role- based access scheme; an attribute-based access scheme]; (b) Monitor privileged role or attribute assignments; (c) Monitor changes to roles or attributes; and (d) Revoke access when privileged role or attribute assignments are no longer appropriate.', 'vec_doc-14-nist-sp-800-53-p48-146', 0, 98, 'v2.1.0', '5de876837d1fd3b50fa1bd8b41cff1e0596bc9d27ee00ddac3800fbb4f13552f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 21","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":146,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 21"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p49-147', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 22', 49, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Privileged roles are organization-defined roles assigned to individuals that allow those individuals to perform certain security-relevant functions that ordinary users are not authorized to perform. Privileged roles include key management, account management, database administration, system and network administration, and web administration. A role-based access scheme organizes permitted system access and privileges into roles. In contrast, an attribute-based access scheme specifies allowed system access and privileges based on attributes. Related Controls:  None. (8) ACCOUNT MANAGEMENT | DYNAMIC ACCOUNT MANAGEMENT Create, activate, manage, and deactivate [Assignment: organization-defined system accounts] dynamically.', 'vec_doc-14-nist-sp-800-53-p49-147', 0, 208, 'v2.1.0', '69b307063338dbd4ab123a8caa4533c6e0218a11d3697c7d3b8c3f898f2d3b70', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 22","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":147,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 22"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p49-148', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 22', 49, 'Discussion:  Approaches for dynamically creating, activating, managing, and deactivating system accounts rely on automatically provisioning the accounts at runtime for entities that were previously unknown. Organizations plan for the dynamic management, creation, activation, and deactivation of system accounts by establishing trust relationships, business rules, and mechanisms with appropriate authorities to validate related authorizations and privileges. Related Controls:  AC-16. (9) ACCOUNT MANAGEMENT | RESTRICTIONS ON USE OF SHARED AND GROUP ACCOUNTS Only permit the use of shared and group accounts that meet [Assignment: organization- defined conditions for establishing shared and group accounts]. Discussion:  Before permitting the use of shared or group accounts, organizations consider the increased risk due to the lack of accountability with such accounts. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p49-148', 0, 225, 'v2.1.0', 'd35a7d0753bab66a89f4f55b171361937791b9acb219c55f04342ccd6375a004', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 22","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":148,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 22"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p49-149', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 22', 49, '(10) ACCOUNT MANAGEMENT | SHARED AND GROUP ACCOUNT CREDENTIAL CHANGE [Withdrawn: Incorporated into AC-2k.] (11) ACCOUNT MANAGEMENT | USAGE CONDITIONS Enforce [Assignment: organization-defined circumstances and/or usage conditions] for [Assignment: organization-defined system accounts]. Discussion:  Specifying and enforcing usage conditions helps to enforce the principle of least privilege, increase user accountability, and enable effective account monitoring. Account monitoring includes alerts generated if the account is used in violation of organizational parameters. Organizations can describe specific conditions or circumstances under which system accounts can be used, such as by restricting usage to certain days of the week, time of day, or specific durations of time. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p49-149', 0, 202, 'v2.1.0', 'eb2c0b6c261c045b2a7d9d54960b420396001c53aab9ee132f2d569d8e77a487', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 22","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":149,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 22"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p49-150', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 22', 49, '(12) ACCOUNT MANAGEMENT | ACCOUNT MONITORING FOR ATYPICAL USAGE (a) Monitor system accounts for [Assignment: organization-defined atypical usage]; and (b) Report atypical usage of system accounts to [Assignment: organization-defined personnel or roles]. Discussion:  Atypical usage includes accessing systems at certain times of the day or from locations that are not consistent with the normal usage patterns of individuals. Monitoring for atypical usage may reveal rogue behavior by individuals or an attack in progress. Account monitoring may inadvertently create privacy risks since data collected to identify atypical usage may reveal previously unknown information about the behavior of individuals. Organizations assess and document privacy risks from monitoring accounts for atypical', 'vec_doc-14-nist-sp-800-53-p49-150', 0, 198, 'v2.1.0', '6ce28c705e3e2ed9dad18f58b3a07aadd51079cf5c81775222b93ce8c635810c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 22","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":150,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 22"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p50-151', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 23', 50, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 usage in their privacy impact assessment and make determinations that are in alignment with their privacy program plan. Related Controls:  AU-6, AU-7, CA-7, IR-8, SI-4. (13) ACCOUNT MANAGEMENT | DISABLE ACCOUNTS FOR HIGH-RISK INDIVIDUALS Disable accounts of individuals within [Assignment: organization-defined time period] of discovery of [Assignment: organization-defined significant risks]. Discussion:  Users who pose a significant security and/or privacy risk include individuals for whom reliable evidence indicates either the intention to use authorized access to systems to cause harm or through whom adversaries will cause harm. Such harm includes adverse impacts to organizational operations, organizational assets, individuals, other organizations, or the Nation.', 'vec_doc-14-nist-sp-800-53-p50-151', 0, 217, 'v2.1.0', '690ccedfba940df8fe28c3bb2e133a9fba0366e113ad03b2da8d243030a5d45a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 23","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":151,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 23"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p50-152', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 23', 50, 'Close coordination among system administrators, legal staff, human resource managers, and authorizing officials is essential when disabling system accounts for high-risk individuals. Related Controls:  AU-6, SI-4. References:  [SP 800-162], [SP 800-178], [SP 800-192]. AC-3 ACCESS ENFORCEMENT Control:  Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies. Discussion:  Access control policies control access between active entities or subjects (i.e., users or processes acting on behalf of users) and passive entities or objects (i.e., devices, files, records, domains) in organizational systems.', 'vec_doc-14-nist-sp-800-53-p50-152', 0, 172, 'v2.1.0', 'cb7edef45f9ebf9c91bf08b7dffc2d1277110a791e94e4cedbbabfaf2a8245e0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 23","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":152,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 23"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p50-153', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 23', 50, 'In addition to enforcing authorized access at the system level and recognizing that systems can host many applications and services in support of mission and business functions, access enforcement mechanisms can also be employed at the application and service level to provide increased information security and privacy. In contrast to logical access controls that are implemented within the system, physical access controls are addressed by the controls in the Physical and Environmental Protection ( PE) family. Related Controls:  AC-2, AC-4, AC-5, AC-6, AC-16, AC-17, AC-18, AC-19, AC-20, AC-21, AC-22, AC- 24, AC-25, AT-2, AT-3, AU-9, CA-9, CM-5, CM-11, IA-2, IA-5, IA-6, IA-7, IA-11, MA-3, MA-4, MA-5, MP-4, PM-2, PS-3, PT-2, PT-3, SA-17, SC-2, SC-3, SC-4, SC-12, SC-13, SC-28, SC-31, SC-34, SI-4, SI-8.', 'vec_doc-14-nist-sp-800-53-p50-153', 0, 202, 'v2.1.0', '0234c929610e005f20330698940057d03241e57752290286c6a0e8e26d3f0f8b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 23","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":153,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 23"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p50-154', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 23', 50, 'Control Enhancements: (1) ACCESS ENFORCEMENT | RESTRICTED ACCESS TO PRIVILEGED FUNCTIONS [Withdrawn: Incorporated into AC-6.] (2) ACCESS ENFORCEMENT | DUAL AUTHORIZATION Enforce dual authorization for [Assignment: organization-defined privileged commands and/or other organization-defined actions]. Discussion:  Dual authorization, also known as two-person control, reduces risk related to insider threats. Dual authorization mechanisms require the approval of two authorized individuals to execute. To reduce the risk of collusion, organizations consider rotating dual authorization duties. Organizations consider the risk associated with implementing dual authorization mechanisms when immediate responses are necessary to ensure public and environmental safety. Related Controls:  CP-9, MP-6. (3) ACCESS ENFORCEMENT | MANDATORY ACCESS CONTROL', 'vec_doc-14-nist-sp-800-53-p50-154', 0, 212, 'v2.1.0', 'dc24c588403a2cf0b2fd10b24318c9154d555819cde55b4751bd2d2e692f3a06', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 23","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":154,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 23"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p51-155', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 24', 51, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Enforce [Assignment: organization-defined mandatory access control policy] over the set of covered subjects and objects specified in the policy, and where the policy: (a) Is uniformly enforced across the covered subjects and objects within the system; (b) Specifies that a subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes (specified by the policy) on subjects, objects, the system, or system components; (4) Choosing the security attributes and attribute values (specified by the policy) to be associated with newly created or modified objects; and (5) Changing the rules governing access control; and (c) Specifies that [Assignment: organization-defined subjects] may explicitly be granted [Assignment: organization-defined privileges] such that they are not limited by any defined subset (or all) of the above constraints.', 'vec_doc-14-nist-sp-800-53-p51-155', 0, 281, 'v2.1.0', '85c983f5ed44f287cb7ee38f8c98f86b90175b1e8be396c208cd8fa387decc03', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 24","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":155,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 24"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p51-156', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 24', 51, 'Discussion:  Mandatory access control is a type of nondiscretionary access control. Mandatory access control policies constrain what actions subjects can take with information obtained from objects for which they have already been granted access. This prevents the subjects from passing the information to unauthorized subjects and objects. Mandatory access control policies constrain actions that subjects can take with respect to the propagation of access control privileges; that is, a subject with a privilege cannot pass that privilege to other subjects. The policy is uniformly enforced over all subjects and objects to which the system has control. Otherwise, the access control policy can be circumvented. This enforcement is provided by an implementation that meets the reference monitor concept as described in AC-25.', 'vec_doc-14-nist-sp-800-53-p51-156', 0, 207, 'v2.1.0', '596a93613d6db8eedb3738760e74600803e056ee9f3475c52aff794c8d6cfeb0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 24","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":156,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 24"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p51-157', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 24', 51, 'The policy is bounded by the system (i.e., once the information is passed outside of the control of the system, additional means may be required to ensure that the constraints on the information remain in effect). The trusted subjects described above are granted privileges consistent with the concept of least privilege (see AC-6). Trusted subjects are only given the minimum privileges necessary for satisfying organizational mission/business needs relative to the above policy. The control is most applicable when there is a mandate that establishes a policy regarding access to controlled unclassified information or classified information and some users of the system are not authorized access to all such information resident in the system. Mandatory access control can operate in conjunction with discretionary access control as described in AC-3(4).', 'vec_doc-14-nist-sp-800-53-p51-157', 0, 215, 'v2.1.0', '4b006762dc55c3b2435f8659d505a9a95081503082ca6981471fcf5a5112778b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 24","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":157,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 24"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p51-158', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 24', 51, 'A subject constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of AC-3(4), but mandatory access control policies take precedence over the less rigorous constraints of AC-3(4). For example, while a mandatory access control policy imposes a constraint that prevents a subject from passing information to another subject operating at a different impact or classification level, AC-3(4) permits the subject to pass the information to any other subject with the same impact or classification level as the subject. Examples of mandatory access control policies include the Bell-LaPadula policy to protect confidentiality of information and the Biba policy to protect the integrity of information. Related Controls:  SC-7.', 'vec_doc-14-nist-sp-800-53-p51-158', 0, 196, 'v2.1.0', '45c207cecd0b4368bfb69c0439abd58059bc34e0c7147bc1a7e54f698fbdbfee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 24","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":158,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 24"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p51-159', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 24', 51, '(4) ACCESS ENFORCEMENT | DISCRETIONARY ACCESS CONTROL Enforce [Assignment: organization-defined discretionary access control policy] over the set of covered subjects and objects specified in the policy, and where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects;', 'vec_doc-14-nist-sp-800-53-p51-159', 0, 97, 'v2.1.0', 'fceb747a33e3858faf71bf6ce139b87ded3cce9a7bde401a3f1248bfac66682c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 24","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":159,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 24"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p52-160', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 25', 52, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the system, or the system’s components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control. Discussion:  When discretionary access control policies are implemented, subjects are not constrained with regard to what actions they can take with information for which they have already been granted access. Thus, subjects that have been granted access to information are not prevented from passing the information to other subjects or objects (i.e., subjects have the discretion to pass). Discretionary access control can operate in conjunction with mandatory access control as described in AC-3(3) and AC-3(15).', 'vec_doc-14-nist-sp-800-53-p52-160', 0, 222, 'v2.1.0', 'acef01934fdc38d15e1541d1dd1e57312163f1e54c02d2322fc44d9758d83b48', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 25","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":160,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 25"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p52-161', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 25', 52, 'A subject that is constrained in its operation by mandatory access control policies can still operate under the less rigorous constraints of discretionary access control. Therefore, while AC-3(3) imposes constraints that prevent a subject from passing information to another subject operating at a different impact or classification level, AC-3(4) permits the subject to pass the information to any subject at the same impact or classification level. The policy is bounded by the system. Once the information is passed outside of system control, additional means may be required to ensure that the constraints remain in effect. While traditional definitions of discretionary access control require identity-based access control, that limitation is not required for this particular use of discretionary access control. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p52-161', 0, 211, 'v2.1.0', '99dbb3c42fef14894d9c9992e162e7877dfa22354e2c786740e59e6b540a00c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 25","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":161,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 25"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p52-162', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 25', 52, '(5) ACCESS ENFORCEMENT | SECURITY-RELEVANT INFORMATION Prevent access to [Assignment: organization-defined security-relevant information] except during secure, non-operable system states. Discussion:  Security-relevant information is information within systems that can potentially impact the operation of security functions or the provision of security services in a manner that could result in failure to enforce system security and privacy policies or maintain the separation of code and data. Security-relevant information includes access control lists, filtering rules for routers or firewalls, configuration parameters for security services, and cryptographic key management information. Secure, non-operable system states include the times in which systems are not performing mission or business-related processing, such as when the system is offline for maintenance, boot-up, troubleshooting, or shut down. Related Controls:  CM-6, SC-39.', 'vec_doc-14-nist-sp-800-53-p52-162', 0, 237, 'v2.1.0', '5030d553a54f80c633ba143233618c848a13f91b68656844153096143e1147ae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 25","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":162,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 25"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p52-163', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 25', 52, '(6) ACCESS ENFORCEMENT | PROTECTION OF USER AND SYSTEM INFORMATION [Withdrawn: Incorporated into MP-4 and SC-28.] (7) ACCESS ENFORCEMENT | ROLE-BASED ACCESS CONTROL Enforce a role-based access control policy over defined subjects and objects and control access based upon [Assignment: organization-defined roles and users authorized to assume such roles]. Discussion:  Role-based access control (RBAC) is an access control policy that enforces access to objects and system functions based on the defined role (i.e., job function) of the subject. Organizations can create specific roles based on job functions and the authorizations (i.e., privileges) to perform needed operations on the systems associated with the organization- defined roles. When users are assigned to specific roles, they inherit the authorizations or privileges defined for those roles.', 'vec_doc-14-nist-sp-800-53-p52-163', 0, 215, 'v2.1.0', '1cec53d75a459c9e8adaa7a3a6244dab5f63dc167cfd1bf245fb4c33fa339c90', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 25","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":163,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 25"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p52-164', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 25', 52, 'RBAC simplifies privilege administration for organizations because privileges are not assigned directly to every user (which can be a large number of individuals) but are instead acquired through role assignments. RBAC can also increase', 'vec_doc-14-nist-sp-800-53-p52-164', 0, 59, 'v2.1.0', '90daaacd9321ac543f30201aa669879ccd060f98cd924c6aa21b562e857d2526', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 25","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":164,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 25"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p53-165', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 26', 53, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 privacy and security risk if individuals assigned to a role are given access to information beyond what they need to support organizational missions or business functions. RBAC can be implemented as a mandatory or discretionary form of access control. For organizations implementing RBAC with mandatory access controls, the requirements in AC-3(3) define the scope of the subjects and objects covered by the policy. Related Controls:  None. (8) ACCESS ENFORCEMENT | REVOCATION OF ACCESS AUTHORIZATIONS Enforce the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on [Assignment: organization-defined rules governing the timing of revocations of access authorizations]. Discussion:  Revocation of access rules may differ based on the types of access revoked.', 'vec_doc-14-nist-sp-800-53-p53-165', 0, 229, 'v2.1.0', '19682b848080aa6ef63a06364e9048cdc66898de1f4e6a72c635ee11841f349a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 26","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":165,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 26"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p53-166', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 26', 53, 'For example, if a subject (i.e., user or process acting on behalf of a user) is removed from a group, access may not be revoked until the next time the object is opened or the next time the subject attempts to access the object. Revocation based on changes to security labels may take effect immediately. Organizations provide alternative approaches on how to make revocations immediate if systems cannot provide such capability and immediate revocation is necessary. Related Controls:  None. (9) ACCESS ENFORCEMENT | CONTROLLED RELEASE Release information outside of the system only if: (a) The receiving [Assignment: organization-defined system or system component] provides [Assignment: organization-defined controls]; and (b) [Assignment: organization-defined controls] are used to validate the appropriateness of the information designated for release. Discussion:  Organizations can only directly protect information when it resides within the system.', 'vec_doc-14-nist-sp-800-53-p53-166', 0, 240, 'v2.1.0', '0f543c2fad08f23a788fde806d5e2ae60d571c33475cb16793ef88c067514182', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 26","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":166,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 26"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p53-167', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 26', 53, 'Additional controls may be needed to ensure that organizational information is adequately protected once it is transmitted outside of the system. In situations where the system is unable to determine the adequacy of the protections provided by external entities, as a mitigation measure, organizations procedurally determine whether the external systems are providing adequate controls. The means used to determine the adequacy of controls provided by external systems include conducting periodic assessments (inspections/tests), establishing agreements between the organization and its counterpart organizations, or some other process. The means used by external entities to protect the information received need not be the same as those used by the organization, but the means employed are sufficient to provide consistent adjudication of the security and privacy policy to protect the information and individuals’ privacy.', 'vec_doc-14-nist-sp-800-53-p53-167', 0, 232, 'v2.1.0', 'b369586dd30752b8a2ca2c874a979094f918fb76b1340f7ca8f8722e332ca3a4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 26","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":167,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 26"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p53-168', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 26', 53, 'Controlled release of information requires systems to implement technical or procedural means to validate the information prior to releasing it to external systems. For example, if the system passes information to a system controlled by another organization, technical means are employed to validate that the security and privacy attributes associated with the exported information are appropriate for the receiving system. Alternatively, if the system passes information to a printer in organization-controlled space, procedural means can be employed to ensure that only authorized individuals gain access to the printer. Related Controls:  CA-3, PT-7, PT-8, SA-9, SC-16. (10) ACCESS ENFORCEMENT | AUDITED OVERRIDE OF ACCESS CONTROL MECHANISMS Employ an audited override of automated access control mechanisms under [Assignment: organization-defined conditions] by [Assignment: organization-defined roles].', 'vec_doc-14-nist-sp-800-53-p53-168', 0, 227, 'v2.1.0', '49cdf67a5bed7007fee9595e2934edef03d6b770236e659abdbd356e90aa65a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 26","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":168,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 26"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p54-169', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 27', 54, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  In certain situations, such as when there is a threat to human life or an event that threatens the organization’s ability to carry out critical missions or business functions, an override capability for access control mechanisms may be needed. Override conditions are defined by organizations and used only in those limited circumstances. Audit events are defined in AU-2. Audit records are generated in AU-12. Related Controls:  AU-2, AU-6, AU-10, AU-12, AU-14. (11) ACCESS ENFORCEMENT | RESTRICT ACCESS TO SPECIFIC INFORMATION TYPES Restrict access to data repositories containing [Assignment: organization-defined information types]. Discussion:  Restricting access to specific information is intended to provide flexibility regarding access control of specific information types within a system.', 'vec_doc-14-nist-sp-800-53-p54-169', 0, 226, 'v2.1.0', 'eef75c5590371ef65c0a02b68dcd1db233b26d2b17d7e16554621a7139ea7ea9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 27","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":169,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 27"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p54-170', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 27', 54, 'For example, role- based access could be employed to allow access to only a specific type of personally identifiable information within a database rather than allowing access to the database in its entirety. Other examples include restricting access to cryptographic keys, authentication information, and selected system information. Related Controls:  CM-8, CM-12, CM-13, PM-5. (12) ACCESS ENFORCEMENT | ASSERT AND ENFORCE APPLICATION ACCESS (a) Require applications to assert, as part of the installation process, the access needed to the following system applications and functions: [Assignment: organization-defined system applications and functions]; (b) Provide an enforcement mechanism to prevent unauthorized access; and (c) Approve access changes after initial installation of the application.', 'vec_doc-14-nist-sp-800-53-p54-170', 0, 201, 'v2.1.0', '6a977ce2c4b0fb8a99e4b45f5d6e99c631dc2435c3abdbedc23e1b1b70009882', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 27","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":170,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 27"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p54-171', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 27', 54, 'Discussion:  Asserting and enforcing application access is intended to address applications that need to access existing system applications and functions, including user contacts, global positioning systems, cameras, keyboards, microphones, networks, phones, or other files. Related Controls:  CM-7. (13) ACCESS ENFORCEMENT | ATTRIBUTE-BASED ACCESS CONTROL Enforce attribute-based access control policy over defined subjects and objects and control access based upon [Assignment: organization-defined attributes to assume access permissions]. Discussion:  Attribute-based access control is an access control policy that restricts system access to authorized users based on specified organizational attributes (e.g., job function, identity), action attributes (e.g., read, write, delete), environmental attributes (e.g., time of day, location), and resource attributes (e.g., classification of a document).', 'vec_doc-14-nist-sp-800-53-p54-171', 0, 227, 'v2.1.0', '2a8663492de622a6ef0b6ae67caaa669e0976a77277099f5030be5716bc81c2a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 27","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":171,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 27"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p54-172', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 27', 54, 'Organizations can create rules based on attributes and the authorizations (i.e., privileges) to perform needed operations on the systems associated with organization-defined attributes and rules. When users are assigned to attributes defined in attribute-based access control policies or rules, they can be provisioned to a system with the appropriate privileges or dynamically granted access to a protected resource. Attribute-based access control can be implemented as either a mandatory or discretionary form of access control. When implemented with mandatory access controls, the requirements in AC-3(3) define the scope of the subjects and objects covered by the policy. Related Controls:  None. (14) ACCESS ENFORCEMENT | INDIVIDUAL ACCESS', 'vec_doc-14-nist-sp-800-53-p54-172', 0, 186, 'v2.1.0', 'b10ae179bf4045c911146e2a4a5e80b5a3fa8ce015cb7d4de7dc0a5a17676a80', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 27","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":172,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 27"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p55-173', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 28', 55, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Provide [Assignment: organization-defined mechanisms] to enable individuals to have access to the following elements of their personally identifiable information: [Assignment: organization-defined elements]. Discussion:  Individual access affords individuals the ability to review personally identifiable information about them held within organizational records, regardless of format. Access helps individuals to develop an understanding about how their personally identifiable information is being processed. It can also help individuals ensure that their data is accurate. Access mechanisms can include request forms and application interfaces. For federal agencies, [PRIVACT] processes can be located in systems of record notices and on agency websites.', 'vec_doc-14-nist-sp-800-53-p55-173', 0, 213, 'v2.1.0', '50c0b5c6459d64464303e9f1d7edbe20b56ba25f067945503bc4ba2adeffa4fa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 28","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":173,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 28"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p55-174', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 28', 55, 'Access to certain types of records may not be appropriate (e.g., for federal agencies, law enforcement records within a system of records may be exempt from disclosure under the [PRIVACT]) or may require certain levels of authentication assurance. Organizational personnel consult with the senior agency official for privacy and legal counsel to determine appropriate mechanisms and access rights or limitations. Related Controls:  IA-8, PM-22, PM-20, PM-21, PT-6. (15) ACCESS ENFORCEMENT | DISCRETIONARY AND MANDATORY ACCESS CONTROL (a) Enforce [Assignment: organization-defined mandatory access control policy] over the set of covered subjects and objects specified in the policy; and (b) Enforce [Assignment: organization-defined discretionary access control policy] over the set of covered subjects and objects specified in the policy.', 'vec_doc-14-nist-sp-800-53-p55-174', 0, 210, 'v2.1.0', 'ed06cb9f94977c2c3258d73b00e7a67e7e0176e942191328b20507052963f178', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 28","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":174,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 28"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p55-175', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 28', 55, 'Discussion:  Simultaneously implementing a mandatory access control policy and a discretionary access control policy can provide additional protection against the unauthorized execution of code by users or processes acting on behalf of users. This helps prevent a single compromised user or process from compromising the entire system. Related Controls:  SC-2, SC-3, AC-4. References:  [PRIVACT], [OMB A-130], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-162], [SP 800-178], [IR 7874]. AC-4 INFORMATION FLOW ENFORCEMENT Control:  Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on [Assignment: organization-defined information flow control policies]. Discussion:  Information flow control regulates where information can travel within a system and between systems (in contrast to who is allowed to access the information) and without regard to subsequent accesses to that information.', 'vec_doc-14-nist-sp-800-53-p55-175', 0, 243, 'v2.1.0', '5ca28fe462cbec447f6086e61cc0351adc5e8b2e818194ebf61224bf774d4d72', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 28","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":175,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 28"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p55-176', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 28', 55, 'Flow control restrictions include blocking external traffic that claims to be from within the organization, keeping export-controlled information from being transmitted in the clear to the Internet, restricting web requests that are not from the internal web proxy server, and limiting information transfers between organizations based on data structures and content. Transferring information between organizations may require an agreement specifying how the information flow is enforced (see CA-3). Transferring information between systems in different security or privacy domains with different security or privacy policies introduces the risk that such transfers violate one or more domain security or privacy policies. In such situations, information owners/stewards provide guidance at designated policy enforcement points between connected systems. Organizations consider mandating specific architectural solutions to enforce specific security and privacy policies.', 'vec_doc-14-nist-sp-800-53-p55-176', 0, 243, 'v2.1.0', '4122497d6a10804c1a47f9ced05bf3190662915ef9170f0050845ba602f4890f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 28","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":176,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 28"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p55-177', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 28', 55, 'Enforcement includes prohibiting information transfers between connected systems (i.e., allowing access only), verifying write permissions before accepting information from another security or privacy domain or connected system, employing hardware mechanisms to enforce one-way information', 'vec_doc-14-nist-sp-800-53-p55-177', 0, 73, 'v2.1.0', 'f5639f73fd36ddc2fd17c724849a1bd354570ad763a89e4dc9bf690dd0033582', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 28","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":177,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 28"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p56-178', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 29', 56, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 flows, and implementing trustworthy regrading mechanisms to reassign security or privacy attributes and labels. Organizations commonly employ information flow control policies and enforcement mechanisms to control the flow of information between designated sources and destinations within systems and between connected systems. Flow control is based on the characteristics of the information and/or the information path. Enforcement occurs, for example, in boundary protection devices that employ rule sets or establish configuration settings that restrict system services, provide a packet-filtering capability based on header information, or provide a message-filtering capability based on message content. Organizations also consider the trustworthiness of filtering and/or inspection mechanisms (i.e., hardware, firmware, and software components) that are critical to information flow enforcement.', 'vec_doc-14-nist-sp-800-53-p56-178', 0, 249, 'v2.1.0', '4ee22f78fb0443aadca8956452f25f4011d0e318296f5799322e0b1d42480b6d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 29","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":178,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 29"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p56-179', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 29', 56, 'Control enhancements 3 through 32 primarily address cross- domain solution needs that focus on more advanced filtering techniques, in-depth analysis, and stronger flow enforcement mechanisms implemented in cross-domain products, such as high- assurance guards. Such capabilities are generally not available in commercial off-the-shelf products. Information flow enforcement also applies to control plane traffic (e.g., routing and DNS). Related Controls:  AC-3, AC-6, AC-16, AC-17, AC-19, AC-21, AU-10, CA-3, CA-9, CM-7, PL-9, PM-24, SA-17, SC-4, SC-7, SC-16, SC-31. Control Enhancements: (1) INFORMATION FLOW ENFORCEMENT | OBJECT SECURITY AND PRIVACY ATTRIBUTES Use [Assignment: organization-defined security and privacy attributes] associated with [Assignment: organization-defined information, source, and destination objects] to enforce [Assignment: organization-defined information flow control policies] as a basis for flow control decisions.', 'vec_doc-14-nist-sp-800-53-p56-179', 0, 237, 'v2.1.0', '787d6439bd61f0da9fbeee1b504e49fa4221d62a3de209f81aa531290affba9a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 29","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":179,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 29"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p56-180', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 29', 56, 'Discussion:  Information flow enforcement mechanisms compare security and privacy attributes associated with information (i.e., data content and structure) and source and destination objects and respond appropriately when the enforcement mechanisms encounter information flows not explicitly allowed by information flow policies. For example, an information object labeled Secret would be allowed to flow to a destination object labeled Secret, but an information object labeled Top Secret would not be allowed to flow to a destination object labeled Secret. A dataset of personally identifiable information may be tagged with restrictions against combining with other types of datasets and, thus, would not be allowed to flow to the restricted dataset. Security and privacy attributes can also include source and destination addresses employed in traffic filter firewalls.', 'vec_doc-14-nist-sp-800-53-p56-180', 0, 219, 'v2.1.0', '680324b4f6d846187a98c3f24f762592e0f2d5639ede642e1ef07d7d81f2f7bc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 29","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":180,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 29"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p56-181', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 29', 56, 'Flow enforcement using explicit security or privacy attributes can be used, for example, to control the release of certain types of information. Related Controls:  None. (2) INFORMATION FLOW ENFORCEMENT | PROCESSING DOMAINS Use protected processing domains to enforce [Assignment: organization-defined information flow control policies] as a basis for flow control decisions. Discussion:  Protected processing domains within systems are processing spaces that have controlled interactions with other processing spaces, enabling control of information flows between these spaces and to/from information objects. A protected processing domain can be provided, for example, by implementing domain and type enforcement.', 'vec_doc-14-nist-sp-800-53-p56-181', 0, 179, 'v2.1.0', '8b12c242dce50e8cde2d85ac7d846458413c175ab8418df1161ef126069a9775', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 29","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":181,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 29"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p56-182', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 29', 56, 'In domain and type enforcement, system processes are assigned to domains, information is identified by types, and information flows are controlled based on allowed information accesses (i.e., determined by domain and type), allowed signaling among domains, and allowed process transitions to other domains.', 'vec_doc-14-nist-sp-800-53-p56-182', 0, 77, 'v2.1.0', '012ed91919b7191cf3e2d0fc98d57964f5816dbdcfed58e915b21884f79e5ff1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 29","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":182,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 29"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p57-183', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 30', 57, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  SC-39. (3) INFORMATION FLOW ENFORCEMENT | DYNAMIC INFORMATION FLOW CONTROL Enforce [Assignment: organization-defined information flow control policies]. Discussion:  Organizational policies regarding dynamic information flow control include allowing or disallowing information flows based on changing conditions or mission or operational considerations. Changing conditions include changes in risk tolerance due to changes in the immediacy of mission or business needs, changes in the threat environment, and detection of potentially harmful or adverse events. Related Controls:  SI-4.', 'vec_doc-14-nist-sp-800-53-p57-183', 0, 174, 'v2.1.0', '59e162736046cb43ba353ce7763053e346a8d019afffbc7a05079b993718faf2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 30","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":183,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 30"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p57-184', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 30', 57, '(4) INFORMATION FLOW ENFORCEMENT | FLOW CONTROL OF ENCRYPTED INFORMATION Prevent encrypted information from bypassing [Assignment: organization-defined information flow control mechanisms] by [Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]]. Discussion:  Flow control mechanisms include content checking, security policy filters, and data type identifiers. The term encryption is extended to cover encoded data not recognized by filtering mechanisms. Related Controls:  SI-4. (5) INFORMATION FLOW ENFORCEMENT | EMBEDDED DATA TYPES Enforce [Assignment: organization-defined limitations] on embedding data types within other data types. Discussion:  Embedding data types within other data types may result in reduced flow control effectiveness.', 'vec_doc-14-nist-sp-800-53-p57-184', 0, 233, 'v2.1.0', '0464bc60ec5bb51376589d5fd9779ddd5b65a3ad249e4efb139429da5414dca0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 30","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":184,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 30"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p57-185', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 30', 57, 'Data type embedding includes inserting files as objects within other files and using compressed or archived data types that may include multiple embedded data types. Limitations on data type embedding consider the levels of embedding and prohibit levels of data type embedding that are beyond the capability of the inspection tools. Related Controls:  None. (6) INFORMATION FLOW ENFORCEMENT | METADATA Enforce information flow control based on [Assignment: organization-defined metadata]. Discussion:  Metadata is information that describes the characteristics of data. Metadata can include structural metadata describing data structures or descriptive metadata describing data content. Enforcement of allowed information flows based on metadata enables simpler and more effective flow control.', 'vec_doc-14-nist-sp-800-53-p57-185', 0, 199, 'v2.1.0', '6024910ae7184b34e5016810410dd5bacb44d76060dab31633a79775ea5b1752', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 30","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":185,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 30"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p57-186', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 30', 57, 'Organizations consider the trustworthiness of metadata regarding data accuracy (i.e., knowledge that the metadata values are correct with respect to the data), data integrity (i.e., protecting against unauthorized changes to metadata tags), and the binding of metadata to the data payload (i.e., employing sufficiently strong binding techniques with appropriate assurance). Related Controls:  AC-16, SI-7. (7) INFORMATION FLOW ENFORCEMENT | ONE-WAY FLOW MECHANISMS Enforce one-way information flows through hardware-based flow control mechanisms. Discussion:  One-way flow mechanisms may also be referred to as a unidirectional network, unidirectional security gateway, or data diode. One-way flow mechanisms can be used to prevent data from being exported from a higher impact or classified domain or system while permitting data from a lower impact or unclassified domain or system to be imported. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p57-186', 0, 231, 'v2.1.0', 'ac77e4160b6e5965259519275645a3cc461823717fe43180fc2f930f1b452e4a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 30","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":186,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 30"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p58-187', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 31', 58, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (8) INFORMATION FLOW ENFORCEMENT | SECURITY AND PRIVACY POLICY FILTERS (a) Enforce information flow control using [Assignment: organization-defined security or privacy policy filters] as a basis for flow control decisions for [Assignment: organization-defined information flows]; and (b) [Selection (one or more): Block; Strip; Modify; Quarantine] data after a filter processing failure in accordance with [Assignment: organization-defined security or privacy policy]. Discussion:  Organization-defined security or privacy policy filters can address data structures and content. For example, security or privacy policy filters for data structures can check for maximum file lengths, maximum field sizes, and data/file types (for structured and unstructured data). Security or privacy policy filters for data content can check for specific words, enumerated values or data value ranges, and hidden content.', 'vec_doc-14-nist-sp-800-53-p58-187', 0, 250, 'v2.1.0', '1523990a3f0315e089043500341a6e92531c2b343421f0c3799d6fdce9d8d53f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 31","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":187,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 31"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p58-188', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 31', 58, 'Structured data permits the interpretation of data content by applications. Unstructured data refers to digital information without a data structure or with a data structure that does not facilitate the development of rule sets to address the impact or classification level of the information conveyed by the data or the flow enforcement decisions. Unstructured data consists of bitmap objects that are inherently non-language-based (i.e., image, video, or audio files) and textual objects that are based on written or printed languages. Organizations can implement more than one security or privacy policy filter to meet information flow control objectives. Related Controls:  None. (9) INFORMATION FLOW ENFORCEMENT | HUMAN REVIEWS Enforce the use of human reviews for [Assignment: organization-defined information flows] under the following conditions: [Assignment: organization-defined conditions].', 'vec_doc-14-nist-sp-800-53-p58-188', 0, 226, 'v2.1.0', 'c73e18ffd65293ed82c250512da4e7f970482f908785f040240de229874d9489', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 31","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":188,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 31"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p58-189', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 31', 58, 'Discussion:  Organizations define security or privacy policy filters for all situations where automated flow control decisions are possible. When a fully automated flow control decision is not possible, then a human review may be employed in lieu of or as a complement to automated security or privacy policy filtering. Human reviews may also be employed as deemed necessary by organizations. Related Controls:  None. (10) INFORMATION FLOW ENFORCEMENT | ENABLE AND DISABLE SECURITY OR PRIVACY POLICY FILTERS Provide the capability for privileged administrators to enable and disable [Assignment: organization-defined security or privacy policy filters] under the following conditions: [Assignment: organization-defined conditions]. Discussion:  For example, as allowed by the system authorization, administrators can enable security or privacy policy filters to accommodate approved data types.', 'vec_doc-14-nist-sp-800-53-p58-189', 0, 224, 'v2.1.0', '6d65424affef8f6c9f375c6475fabc1659f29148b57ecbbb75079066de75ee9a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 31","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":189,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 31"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p58-190', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 31', 58, 'Administrators also have the capability to select the filters that are executed on a specific data flow based on the type of data that is being transferred, the source and destination security domains, and other security or privacy relevant features, as needed. Related Controls:  None. (11) INFORMATION FLOW ENFORCEMENT | CONFIGURATION OF SECURITY OR PRIVACY POLICY FILTERS Provide the capability for privileged administrators to configure [Assignment: organization-defined security or privacy policy filters] to support different security or privacy policies. Discussion:  Documentation contains detailed information for configuring security or privacy policy filters. For example, administrators can configure security or privacy policy filters to include the list of inappropriate words that security or privacy policy mechanisms check in accordance with the definitions provided by organizations. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p58-190', 0, 232, 'v2.1.0', 'e4dbebdfe2f19f8791d37853895724cc1b88d022d0439ef0696c18ffa8b0f411', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 31","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":190,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 31"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p59-191', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 32', 59, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (12) INFORMATION FLOW ENFORCEMENT | DATA TYPE IDENTIFIERS When transferring information between different security domains, use [Assignment: organization-defined data type identifiers] to validate data essential for information flow decisions. Discussion:  Data type identifiers include filenames, file types, file signatures or tokens, and multiple internal file signatures or tokens. Systems only allow transfer of data that is compliant with data type format specifications. Identification and validation of data types is based on defined specifications associated with each allowed data format. The filename and number alone are not used for data type identification. Content is validated syntactically and semantically against its specification to ensure that it is the proper data type. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p59-191', 0, 228, 'v2.1.0', 'ede0a7fc6df1d095031e992f07b761b58ba11802dbf165b77adabbe9d0af3378', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 32","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":191,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 32"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p59-192', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 32', 59, '(13) INFORMATION FLOW ENFORCEMENT | DECOMPOSITION INTO POLICY-RELEVANT SUBCOMPONENTS When transferring information between different security domains, decompose information into [Assignment: organization-defined policy-relevant subcomponents] for submission to policy enforcement mechanisms. Discussion:  Decomposing information into policy-relevant subcomponents prior to information transfer facilitates policy decisions on source, destination, certificates, classification, attachments, and other security- or privacy-related component differentiators. Policy enforcement mechanisms apply filtering, inspection, and/or sanitization rules to the policy-relevant subcomponents of information to facilitate flow enforcement prior to transferring such information to different security domains. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p59-192', 0, 205, 'v2.1.0', '464a073f3dd466a98a213b2dab815396df56eaf0a568d27f9db84a26b2dac22a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 32","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":192,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 32"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p59-193', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 32', 59, '(14) INFORMATION FLOW ENFORCEMENT | SECURITY OR PRIVACY POLICY FILTER CONSTRAINTS When transferring information between different security domains, implement [Assignment: organization-defined security or privacy policy filters] requiring fully enumerated formats that restrict data structure and content. Discussion:  Data structure and content restrictions reduce the range of potential malicious or unsanctioned content in cross-domain transactions. Security or privacy policy filters that restrict data structures include restricting file sizes and field lengths. Data content policy filters include encoding formats for character sets, restricting character data fields to only contain alpha-numeric characters, prohibiting special characters, and validating schema structures. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p59-193', 0, 202, 'v2.1.0', '94836a41b3948c3e61a9ba51a7e1315942a850ae60b4cf43c410983ca8a67394', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 32","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":193,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 32"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p59-194', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 32', 59, '(15) INFORMATION FLOW ENFORCEMENT | DETECTION OF UNSANCTIONED INFORMATION When transferring information between different security domains, examine the information for the presence of [Assignment: organization-defined unsanctioned information] and prohibit the transfer of such information in accordance with the [Assignment: organization-defined security or privacy policy]. Discussion:  Unsanctioned information includes malicious code, information that is inappropriate for release from the source network, or executable code that could disrupt or harm the services or systems on the destination network. Related Controls:  SI-3. (16) INFORMATION FLOW ENFORCEMENT | INFORMATION TRANSFERS ON INTERCONNECTED SYSTEMS [Withdrawn: Incorporated into AC-4.] (17) INFORMATION FLOW ENFORCEMENT | DOMAIN AUTHENTICATION', 'vec_doc-14-nist-sp-800-53-p59-194', 0, 203, 'v2.1.0', '4a5bce75ae1dfaf82faa49f510125a818693d4ba30926a6b8688c4eeb4ff3567', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 32","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":194,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 32"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p60-195', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 33', 60, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Uniquely identify and authenticate source and destination points by [Selection (one or more): organization; system; application; service; individual] for information transfer. Discussion:  Attribution is a critical component of a security and privacy concept of operations. The ability to identify source and destination points for information flowing within systems allows the forensic reconstruction of events and encourages policy compliance by attributing policy violations to specific organizations or individuals. Successful domain authentication requires that system labels distinguish among systems, organizations, and individuals involved in preparing, sending, receiving, or disseminating information.', 'vec_doc-14-nist-sp-800-53-p60-195', 0, 201, 'v2.1.0', '6229cec302b87bfbf95d0fc7cb0142677344d18752e1572e91eb8a1e0a0a3ddd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 33","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":195,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 33"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p60-196', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 33', 60, 'Attribution also allows organizations to better maintain the lineage of personally identifiable information processing as it flows through systems and can facilitate consent tracking, as well as correction, deletion, or access requests from individuals. Related Controls:  IA-2, IA-3, IA-9. (18) INFORMATION FLOW ENFORCEMENT | SECURITY ATTRIBUTE BINDING [Withdrawn: Incorporated into AC-16.] (19) INFORMATION FLOW ENFORCEMENT | VALIDATION OF METADATA When transferring information between different security domains, implement [Assignment: organization-defined security or privacy policy filters] on metadata. Discussion:  All information (including metadata and the data to which the metadata applies) is subject to filtering and inspection. Some organizations distinguish between metadata and data payloads (i.e., only the data to which the metadata is bound). Other organizations do not make such distinctions and consider metadata and the data to which the metadata applies to be part of the payload.', 'vec_doc-14-nist-sp-800-53-p60-196', 0, 251, 'v2.1.0', '5e9353abd36b1a804f62e7a6ac71dc6aaeae2fa30475b6a051176e48ff2a97f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 33","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":196,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 33"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p60-197', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 33', 60, 'Related Controls:  None. (20) INFORMATION FLOW ENFORCEMENT | APPROVED SOLUTIONS Employ [Assignment: organization-defined solutions in approved configurations] to control the flow of [Assignment: organization-defined information] across security domains. Discussion:  Organizations define approved solutions and configurations in cross-domain policies and guidance in accordance with the types of information flows across classification boundaries. The National Security Agency (NSA) National Cross Domain Strategy and Management Office provides a listing of approved cross-domain solutions. Contact ncdsmo@nsa.gov for more information. Related Controls:  None. (21) INFORMATION FLOW ENFORCEMENT | PHYSICAL OR LOGICAL SEPARATION OF INFORMATION FLOWS Separate information flows logically or physically using [Assignment: organization-defined mechanisms and/or techniques] to accomplish [Assignment: organization-defined required separations by types of information].', 'vec_doc-14-nist-sp-800-53-p60-197', 0, 241, 'v2.1.0', 'a7ab60bc725ead941461c7fe437f5db4b74d0fce31c11573a82c5099f630dd40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 33","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":197,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 33"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p60-198', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 33', 60, 'Discussion:  Enforcing the separation of information flows associated with defined types of data can enhance protection by ensuring that information is not commingled while in transit and by enabling flow control by transmission paths that are not otherwise achievable. Types of separable information include inbound and outbound communications traffic, service requests and responses, and information of differing security impact or classification levels. Related Controls:  SC-32. (22) INFORMATION FLOW ENFORCEMENT | ACCESS ONLY Provide access from a single device to computing platforms, applications, or data residing in multiple different security domains, while preventing information flow between the different security domains.', 'vec_doc-14-nist-sp-800-53-p60-198', 0, 184, 'v2.1.0', '492362b25514d6faab79d77fe8752ecc409a77f2569ecd43a530f5be32bdec05', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 33","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":198,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 33"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p61-199', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 34', 61, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The system provides a capability for users to access each connected security domain without providing any mechanisms to allow users to transfer data or information between the different security domains. An example of an access-only solution is a terminal that provides a user access to information with different security classifications while assuredly keeping the information separate. Related Controls:  None. (23) INFORMATION FLOW ENFORCEMENT | MODIFY NON-RELEASABLE INFORMATION When transferring information between different security domains, modify non-releasable information by implementing [Assignment: organization-defined modification action]. Discussion:  Modifying non-releasable information can help prevent a data spill or attack when information is transferred across security domains. Modification actions include masking, permutation, alteration, removal, or redaction.', 'vec_doc-14-nist-sp-800-53-p61-199', 0, 249, 'v2.1.0', '08963bf7d15bf386a4efaa73c12c261f418c3bff4b02025711f47a8ac4366320', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 34","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":199,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 34"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p61-200', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 34', 61, 'Related Controls:  None. (24) INFORMATION FLOW ENFORCEMENT | INTERNAL NORMALIZED FORMAT When transferring information between different security domains, parse incoming data into an internal normalized format and regenerate the data to be consistent with its intended specification. Discussion:  Converting data into normalized forms is one of most of effective mechanisms to stop malicious attacks and large classes of data exfiltration. Related Controls:  None. (25) INFORMATION FLOW ENFORCEMENT | DATA SANITIZATION When transferring information between different security domains, sanitize data to minimize [Selection (one or more): delivery of malicious content, command and control of malicious code, malicious code augmentation, and steganography encoded data; spillage of sensitive information] in accordance with [Assignment: organization-defined policy]].', 'vec_doc-14-nist-sp-800-53-p61-200', 0, 216, 'v2.1.0', 'fada1d6b8b75ff18c825bddf02c7e277e41761167c3f33dad624fb85c9c8ee9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 34","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":200,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 34"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p61-201', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 34', 61, 'Discussion:  Data sanitization is the process of irreversibly removing or destroying data stored on a memory device (e.g., hard drives, flash memory/solid state drives, mobile devices, CDs, and DVDs) or in hard copy form. Related Controls:  MP-6. (26) INFORMATION FLOW ENFORCEMENT | AUDIT FILTERING ACTIONS When transferring information between different security domains, record and audit content filtering actions and results for the information being filtered. Discussion:  Content filtering is the process of inspecting information as it traverses a cross- domain solution and determines if the information meets a predefined policy. Content filtering actions and the results of filtering actions are recorded for individual messages to ensure that the correct filter actions were applied. Content filter reports are used to assist in troubleshooting actions by, for example, determining why message content was modified and/or why it failed the filtering process. Audit events are defined in AU-2.', 'vec_doc-14-nist-sp-800-53-p61-201', 0, 251, 'v2.1.0', '69076296e629ed32d8315e6d16658e53bd6d0780c69bc1b475edf2633702b5f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 34","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":201,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 34"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p61-202', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 34', 61, 'Audit records are generated in AU-12. Related Controls:  AU-2, AU-3, AU-12. (27) INFORMATION FLOW ENFORCEMENT | REDUNDANT/INDEPENDENT FILTERING MECHANISMS When transferring information between different security domains, implement content filtering solutions that provide redundant and independent filtering mechanisms for each data type. Discussion:  Content filtering is the process of inspecting information as it traverses a cross- domain solution and determines if the information meets a predefined policy. Redundant', 'vec_doc-14-nist-sp-800-53-p61-202', 0, 131, 'v2.1.0', 'dfcc9e1a3ed05f0409f3c8a39d728fea7f1bca475eb0437c662238084da16324', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 34","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":202,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 34"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p62-203', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 35', 62, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and independent content filtering eliminates a single point of failure filtering system. Independence is defined as the implementation of a content filter that uses a different code base and supporting libraries (e.g., two JPEG filters using different vendors’ JPEG libraries) and multiple, independent system processes. Related Controls:  None. (28) INFORMATION FLOW ENFORCEMENT | LINEAR FILTER PIPELINES When transferring information between different security domains, implement a linear content filter pipeline that is enforced with discretionary and mandatory access controls. Discussion:  Content filtering is the process of inspecting information as it traverses a cross- domain solution and determines if the information meets a predefined policy. The use of linear content filter pipelines ensures that filter processes are non-bypassable and always invoked.', 'vec_doc-14-nist-sp-800-53-p62-203', 0, 240, 'v2.1.0', '675c9f53c705f90bfcc7aa60ea59f8eb118096f3a67319ec342ccee2c3f5adb0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 35","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":203,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 35"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p62-204', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 35', 62, 'In general, the use of parallel filtering architectures for content filtering of a single data type introduces bypass and non-invocation issues. Related Controls:  None. (29) INFORMATION FLOW ENFORCEMENT | FILTER ORCHESTRATION ENGINES When transferring information between different security domains, employ content filter orchestration engines to ensure that: (a) Content filtering mechanisms successfully complete execution without errors; and (b) Content filtering actions occur in the correct order and comply with [Assignment: organization-defined policy]. Discussion:  Content filtering is the process of inspecting information as it traverses a cross- domain solution and determines if the information meets a predefined security policy. An orchestration engine coordinates the sequencing of activities (manual and automated) in a content filtering process. Errors are defined as either anomalous actions or unexpected termination of the content filter process.', 'vec_doc-14-nist-sp-800-53-p62-204', 0, 242, 'v2.1.0', 'bf4d154dc12364f543f4a9890a1e3150ee7db7b5e512bcbfe50a6b3eaaf5aca0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 35","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":204,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 35"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p62-205', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 35', 62, 'This is not the same as a filter failing content due to non-compliance with policy. Content filter reports are a commonly used mechanism to ensure that expected filtering actions are completed successfully. Related Controls:  None. (30) INFORMATION FLOW ENFORCEMENT | FILTER MECHANISMS USING MULTIPLE PROCESSES When transferring information between different security domains, implement content filtering mechanisms using multiple processes. Discussion:  The use of multiple processes to implement content filtering mechanisms reduces the likelihood of a single point of failure. Related Controls:  None. (31) INFORMATION FLOW ENFORCEMENT | FAILED CONTENT TRANSFER PREVENTION When transferring information between different security domains, prevent the transfer of failed content to the receiving domain. Discussion:  Content that failed filtering checks can corrupt the system if transferred to the receiving domain. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p62-205', 0, 236, 'v2.1.0', 'f587d09c457c5e71027cfed90f3cc2cbb62897a65c74e4af762c040346f025e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 35","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":205,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 35"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p62-206', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 35', 62, '(32) INFORMATION FLOW ENFORCEMENT | PROCESS REQUIREMENTS FOR INFORMATION TRANSFER When transferring information between different security domains, the process that transfers information between filter pipelines: (a) Does not filter message content; (b) Validates filtering metadata;', 'vec_doc-14-nist-sp-800-53-p62-206', 0, 71, 'v2.1.0', '17a58974ac6d786091e5aa66865b71e811f829e9370dc29490295443bd722014', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 35","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":206,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 35"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p63-207', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 36', 63, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (c) Ensures the content associated with the filtering metadata has successfully completed filtering; and (d) Transfers the content to the destination filter pipeline. Discussion:  The processes transferring information between filter pipelines have minimum complexity and functionality to provide assurance that the processes operate correctly. Related Controls:  None. References:  [SP-800-160-1], [SP 800-162], [SP 800-178], [IR 8112]. AC-5 SEPARATION OF DUTIES Control: a. Identify and document [Assignment: organization-defined duties of individuals requiring separation]; and b. Define system access authorizations to support separation of duties. Discussion:  Separation of duties addresses the potential for abuse of authorized privileges and helps to reduce the risk of malevolent activity without collusion.', 'vec_doc-14-nist-sp-800-53-p63-207', 0, 227, 'v2.1.0', '81a7a184ca306974af6d557403b45fad44fe3f9850b1edb47f96f6507e5dc41d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 36","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":207,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 36"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p63-208', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 36', 63, 'Separation of duties includes dividing mission or business functions and support functions among different individuals or roles, conducting system support functions with different individuals, and ensuring that security personnel who administer access control functions do not also administer audit functions. Because separation of duty violations can span systems and application domains, organizations consider the entirety of systems and system components when developing policy on separation of duties. Separation of duties is enforced through the account management activities in AC-2, access control mechanisms in AC-3, and identity management activities in IA-2, IA-4, and IA-12. Related Controls:  AC-2, AC-3, AC-6, AU-9, CM-5, CM-11, CP-9, IA-2, IA-4, IA-5, IA-12, MA-3, MA-5, PS-2, SA-8, SA-17. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p63-208', 0, 213, 'v2.1.0', '89c0812e710c807f6057401bc4f4b184258919a578a24153137e209c9d7046cd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 36","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":208,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 36"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p63-209', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 36', 63, 'AC-6 LEAST PRIVILEGE Control:  Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks. Discussion:  Organizations employ least privilege for specific duties and systems. The principle of least privilege is also applied to system processes, ensuring that the processes have access to systems and operate at privilege levels no higher than necessary to accomplish organizational missions or business functions. Organizations consider the creation of additional processes, roles, and accounts as necessary to achieve least privilege. Organizations apply least privilege to the development, implementation, and operation of organizational systems. Related Controls:  AC-2, AC-3, AC-5, AC-16, CM-5, CM-11, PL-2, PM-12, SA-8, SA-15, SA-17, SC-38.', 'vec_doc-14-nist-sp-800-53-p63-209', 0, 219, 'v2.1.0', '1c58354fa338a4398e38f3e9c17e4d43bb98bdfc4bf95777981467e87eee10e6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 36","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":209,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 36"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p63-210', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 36', 63, 'Control Enhancements: (1) LEAST PRIVILEGE | AUTHORIZE ACCESS TO SECURITY FUNCTIONS Authorize access for [Assignment: organization-defined individuals or roles] to: (a) [Assignment: organization-defined security functions (deployed in hardware, software, and firmware)]; and (b) [Assignment: organization-defined security-relevant information].', 'vec_doc-14-nist-sp-800-53-p63-210', 0, 86, 'v2.1.0', 'a4396460bf271d7f62df436aeb9b3e20d15a639a2d7a76bbd8893fa56f27d10e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 36","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":210,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 36"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p64-211', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 37', 64, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Security functions include establishing system accounts, configuring access authorizations (i.e., permissions, privileges), configuring settings for events to be audited, and establishing intrusion detection parameters. Security-relevant information includes filtering rules for routers or firewalls, configuration parameters for security services, cryptographic key management information, and access control lists. Authorized personnel include security administrators, system administrators, system security officers, system programmers, and other privileged users. Related Controls:  AC-17, AC-18, AC-19, AU-9, PE-2.', 'vec_doc-14-nist-sp-800-53-p64-211', 0, 181, 'v2.1.0', '94310464c47102d2fb818182357fc9f7cd9635a6af44629dff8ac289937fca5d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 37","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":211,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 37"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p64-212', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 37', 64, '(2) LEAST PRIVILEGE | NON-PRIVILEGED ACCESS FOR NONSECURITY FUNCTIONS Require that users of system accounts (or roles) with access to [Assignment: organization- defined security functions or security-relevant information] use non-privileged accounts or roles, when accessing nonsecurity functions. Discussion:  Requiring the use of non-privileged accounts when accessing nonsecurity functions limits exposure when operating from within privileged accounts or roles. The inclusion of roles addresses situations where organizations implement access control policies, such as role-based access control, and where a change of role provides the same degree of assurance in the change of access authorizations for the user and the processes acting on behalf of the user as would be provided by a change between a privileged and non- privileged account. Related Controls:  AC-17, AC-18, AC-19, PL-4.', 'vec_doc-14-nist-sp-800-53-p64-212', 0, 223, 'v2.1.0', 'c5dc94fa5227bd34e40e8ca1c94cd795ba696629bbc66f844232ee73689d09f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 37","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":212,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 37"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p64-213', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 37', 64, '(3) LEAST PRIVILEGE | NETWORK ACCESS TO PRIVILEGED COMMANDS Authorize network access to [Assignment: organization-defined privileged commands] only for [Assignment: organization-defined compelling operational needs] and document the rationale for such access in the security plan for the system. Discussion:  Network access is any access across a network connection in lieu of local access (i.e., user being physically present at the device). Related Controls:  AC-17, AC-18, AC-19. (4) LEAST PRIVILEGE | SEPARATE PROCESSING DOMAINS Provide separate processing domains to enable finer-grained allocation of user privileges.', 'vec_doc-14-nist-sp-800-53-p64-213', 0, 156, 'v2.1.0', 'ebbf7b349a6667124719e6ef3493387e1e14f97e4895629823e95916e63cea7a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 37","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":213,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 37"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p64-214', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 37', 64, 'Discussion:  Providing separate processing domains for finer-grained allocation of user privileges includes using virtualization techniques to permit additional user privileges within a virtual machine while restricting privileges to other virtual machines or to the underlying physical machine, implementing separate physical domains, and employing hardware or software domain separation mechanisms. Related Controls:  AC-4, SC-2, SC-3, SC-30, SC-32, SC-39. (5) LEAST PRIVILEGE | PRIVILEGED ACCOUNTS Restrict privileged accounts on the system to [Assignment: organization-defined personnel or roles]. Discussion:  Privileged accounts, including super user accounts, are typically described as system administrator for various types of commercial off-the-shelf operating systems. Restricting privileged accounts to specific personnel or roles prevents day-to-day users from accessing privileged information or privileged functions.', 'vec_doc-14-nist-sp-800-53-p64-214', 0, 233, 'v2.1.0', '9e3a86f9def0602824c549e03656d3dd676c123dba1466b0efa9427a2a2e4f0e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 37","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":214,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 37"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p64-215', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 37', 64, 'Organizations may differentiate in the application of restricting privileged accounts between allowed privileges for local accounts and for domain accounts provided that they retain the ability to control system configurations for key parameters and as otherwise necessary to sufficiently mitigate risk. Related Controls:  IA-2, MA-3, MA-4.', 'vec_doc-14-nist-sp-800-53-p64-215', 0, 85, 'v2.1.0', '9a71a265306e59f5e373cda661fe6343bc1d9bf9f37dc87e3abc7c6f75a68ed5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 37","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":215,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 37"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p65-216', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 38', 65, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (6) LEAST PRIVILEGE | PRIVILEGED ACCESS BY NON-ORGANIZATIONAL USERS Prohibit privileged access to the system by non-organizational users. Discussion:  An organizational user is an employee or an individual considered by the organization to have the equivalent status of an employee. Organizational users include contractors, guest researchers, or individuals detailed from other organizations. A non- organizational user is a user who is not an organizational user. Policies and procedures for granting equivalent status of employees to individuals include a need-to-know, citizenship, and the relationship to the organization. Related Controls:  AC-18, AC-19, IA-2, IA-8.', 'vec_doc-14-nist-sp-800-53-p65-216', 0, 191, 'v2.1.0', '20aac844d63d751926147fdc4917cf258472a0fb6e694313604ff409180cb7fa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 38","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":216,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 38"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p65-217', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 38', 65, '(7) LEAST PRIVILEGE | REVIEW OF USER PRIVILEGES (a) Review [Assignment: organization-defined frequency] the privileges assigned to [Assignment: organization-defined roles or classes of users] to validate the need for such privileges; and (b) Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs. Discussion:  The need for certain assigned user privileges may change over time to reflect changes in organizational mission and business functions, environments of operation, technologies, or threats. A periodic review of assigned user privileges is necessary to determine if the rationale for assigning such privileges remains valid. If the need cannot be revalidated, organizations take appropriate corrective actions. Related Controls:  CA-7.', 'vec_doc-14-nist-sp-800-53-p65-217', 0, 200, 'v2.1.0', '6d36d9558a8f581955492766dd96b283370284f73c1c8c8272489c8f4c541f30', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 38","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":217,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 38"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p65-218', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 38', 65, '(8) LEAST PRIVILEGE | PRIVILEGE LEVELS FOR CODE EXECUTION Prevent the following software from executing at higher privilege levels than users executing the software: [Assignment: organization-defined software]. Discussion:  In certain situations, software applications or programs need to execute with elevated privileges to perform required functions. However, depending on the software functionality and configuration, if the privileges required for execution are at a higher level than the privileges assigned to organizational users invoking such applications or programs, those users may indirectly be provided with greater privileges than assigned. Related Controls:  None. (9) LEAST PRIVILEGE | LOG USE OF PRIVILEGED FUNCTIONS Log the execution of privileged functions.', 'vec_doc-14-nist-sp-800-53-p65-218', 0, 194, 'v2.1.0', '7dc7ecc6ed563733f349a25913054a808b5e484d3013bc6887c6d7c02bc1e867', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 38","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":218,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 38"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p65-219', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 38', 65, 'Discussion:  The misuse of privileged functions, either intentionally or unintentionally by authorized users or by unauthorized external entities that have compromised system accounts, is a serious and ongoing concern and can have significant adverse impacts on organizations. Logging and analyzing the use of privileged functions is one way to detect such misuse and, in doing so, help mitigate the risk from insider threats and the advanced persistent threat. Related Controls:  AU-2, AU-3, AU-12. (10) LEAST PRIVILEGE | PROHIBIT NON-PRIVILEGED USERS FROM EXECUTING PRIVILEGED FUNCTIONS Prevent non-privileged users from executing privileged functions. Discussion:  Privileged functions include disabling, circumventing, or altering implemented security or privacy controls, establishing system accounts, performing system integrity checks, and administering cryptographic key management activities. Non-privileged users are individuals who do not possess appropriate authorizations.', 'vec_doc-14-nist-sp-800-53-p65-219', 0, 247, 'v2.1.0', 'e2d25f4fda06bcfcf396fd45705ef6385da2288769063cf6a69e236cd5534f4a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 38","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":219,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 38"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p65-220', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 38', 65, 'Privileged functions that require protection from non-privileged users include circumventing intrusion detection and', 'vec_doc-14-nist-sp-800-53-p65-220', 0, 29, 'v2.1.0', 'e27aacd78e3346aff8250402bf3aa3f1882a13c25692a08f9eea734d25f90eb5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 38","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":220,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 38"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p66-221', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 39', 66, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 prevention mechanisms or malicious code protection mechanisms. Preventing non- privileged users from executing privileged functions is enforced by AC-3. Related Controls:  None. References:  None. AC-7 UNSUCCESSFUL LOGON ATTEMPTS Control: a. Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts by a user during a [Assignment: organization-defined time period]; and b. Automatically [Selection (one or more): lock the account or node for an [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm]; notify system administrator; take other [Assignment: organization-defined action]] when the maximum number of unsuccessful attempts is exceeded.', 'vec_doc-14-nist-sp-800-53-p66-221', 0, 228, 'v2.1.0', '40577bf35f01115522375f2bb66272ec866e61f6281210ba0d8ef1c67a6bbff4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 39","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":221,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 39"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p66-222', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 39', 66, 'Discussion:  The need to limit unsuccessful logon attempts and take subsequent action when the maximum number of attempts is exceeded applies regardless of whether the logon occurs via a local or network connection. Due to the potential for denial of service, automatic lockouts initiated by systems are usually temporary and automatically release after a predetermined, organization-defined time period. If a delay algorithm is selected, organizations may employ different algorithms for different components of the system based on the capabilities of those components. Responses to unsuccessful logon attempts may be implemented at the operating system and the application levels.', 'vec_doc-14-nist-sp-800-53-p66-222', 0, 171, 'v2.1.0', '809ba840eb410c31653623b83c10031e0bfc1217b6d2faba28e37c18987ccd30', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 39","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":222,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 39"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p66-223', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 39', 66, 'Organization-defined actions that may be taken when the number of allowed consecutive invalid logon attempts is exceeded include prompting the user to answer a secret question in addition to the username and password, invoking a lockdown mode with limited user capabilities (instead of full lockout), allowing users to only logon from specified Internet Protocol (IP) addresses, requiring a CAPTCHA to prevent automated attacks, or applying user profiles such as location, time of day, IP address, device, or Media Access Control (MAC) address. If automatic system lockout or execution of a delay algorithm is not implemented in support of the availability objective, organizations consider a combination of other actions to help prevent brute force attacks. In addition to the above, organizations can prompt users to respond to a secret question before the number of allowed unsuccessful logon attempts is exceeded.', 'vec_doc-14-nist-sp-800-53-p66-223', 0, 230, 'v2.1.0', '933de25b397f51509506e34acea09784ab2c978d180ea8b3b9fe0a7028b8d0bf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 39","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":223,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 39"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p66-224', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 39', 66, 'Automatically unlocking an account after a specified period of time is generally not permitted. However, exceptions may be required based on operational mission or need. Related Controls:  AC-2, AC-9, AU-2, AU-6, IA-5. Control Enhancements: (1) UNSUCCESSFUL LOGON ATTEMPTS | AUTOMATIC ACCOUNT LOCK [Withdrawn: Incorporated into AC-7.] (2) UNSUCCESSFUL LOGON ATTEMPTS | PURGE OR WIPE MOBILE DEVICE Purge or wipe information from [Assignment: organization-defined mobile devices] based on [Assignment: organization-defined purging or wiping requirements and techniques] after [Assignment: organization-defined number] consecutive, unsuccessful device logon attempts. Discussion:  A mobile device is a computing device that has a small form factor such that it can be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source.', 'vec_doc-14-nist-sp-800-53-p66-224', 0, 238, 'v2.1.0', '8bffdab37ee5cc120338db188104f74b3a969ef0d37ed21ab3f196f4a396212b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 39","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":224,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 39"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p66-225', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 39', 66, 'Purging or wiping the device applies only to mobile devices for which the organization-defined number of unsuccessful logons occurs. The logon is to the mobile', 'vec_doc-14-nist-sp-800-53-p66-225', 0, 40, 'v2.1.0', '0965c3820436d84e2d80eb0adf483e618011550833074315d43cf02b3879e313', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 39","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":225,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 39"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-226', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 40', 67, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 device, not to any one account on the device. Successful logons to accounts on mobile devices reset the unsuccessful logon count to zero. Purging or wiping may be unnecessary if the information on the device is protected with sufficiently strong encryption mechanisms. Related Controls:  AC-19, MP-5, MP-6. (3) UNSUCCESSFUL LOGON ATTEMPTS | BIOMETRIC ATTEMPT LIMITING Limit the number of unsuccessful biometric logon attempts to [Assignment: organization- defined number]. Discussion:  Biometrics are probabilistic in nature. The ability to successfully authenticate can be impacted by many factors, including matching performance and presentation attack detection mechanisms. Organizations select the appropriate number of attempts for users based on organizationally-defined factors. Related Controls:  IA-3.', 'vec_doc-14-nist-sp-800-53-p67-226', 0, 226, 'v2.1.0', '016374da94f315911892cafaf8468b8bf3d2f6cc74d6bf148e2546995fb8cecf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 40","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":226,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 40"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-227', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 40', 67, '(4) UNSUCCESSFUL LOGON ATTEMPTS | USE OF ALTERNATE AUTHENTICATION FACTOR (a) Allow the use of [Assignment: organization-defined authentication factors] that are different from the primary authentication factors after the number of organization- defined consecutive invalid logon attempts have been exceeded; and (b) Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts through use of the alternative factors by a user during a [Assignment: organization-defined time period]. Discussion:  The use of alternate authentication factors supports the objective of availability and allows a user who has inadvertently been locked out to use additional authentication factors to bypass the lockout. Related Controls:  IA-3. References:   [SP 800-63-3], [SP 800-124]. AC-8 SYSTEM USE NOTIFICATION Control: a.', 'vec_doc-14-nist-sp-800-53-p67-227', 0, 211, 'v2.1.0', '732fabbe37f340b22236aee6212904d25a2e1e4ee1b02e1b0590d0134da3eb8a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 40","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":227,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 40"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-228', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 40', 67, 'Display [Assignment: organization-defined system use notification message or banner] to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:', 'vec_doc-14-nist-sp-800-53-p67-228', 0, 76, 'v2.1.0', '770bae48d33db57934f33f05fff7b6dee346dd5f3150c6def21e04a5ad47cecc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 40","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":228,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 40"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-229', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Use of the system indicates consent to monitoring and recording;', 67, 'b. Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; and c. For publicly accessible systems:', 'vec_doc-14-nist-sp-800-53-p67-229', 0, 53, 'v2.1.0', '4443d98b6ad4f5db5ea901554bc6a2b80465e9a3f03b1e38a41167b85e4853a8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Use of the system indicates consent to monitoring and recording;","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":229,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Use of the system indicates consent to monitoring and recording;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-230', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Display system use information [Assignment: organization-defined conditions], before', 67, 'granting further access to the publicly accessible system;', 'vec_doc-14-nist-sp-800-53-p67-230', 0, 15, 'v2.1.0', 'ec1bf5dbe08cde8436b37bdb3a136aab3c77227963a5030b039489d028112576', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Display system use information [Assignment: organization-defined conditions], before","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":230,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Display system use information [Assignment: organization-defined conditions], before"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p67-231', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Display references, if any, to monitoring, recording, or auditing that are consistent with', 67, 'privacy accommodations for such systems that generally prohibit those activities; and', 'vec_doc-14-nist-sp-800-53-p67-231', 0, 22, 'v2.1.0', 'd4676864f522da371bab481eca826148f667779447ae9344f5d3fceca1b32c2e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Display references, if any, to monitoring, recording, or auditing that are consistent with","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":231,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Display references, if any, to monitoring, recording, or auditing that are consistent with"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p68-232', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Include a description of the authorized uses of the system.', 68, 'Discussion:  System use notifications can be implemented using messages or warning banners displayed before individuals log in to systems. System use notifications are used only for access via logon interfaces with human users. Notifications are not required when human interfaces do not exist. Based on an assessment of risk, organizations consider whether or not a secondary system use notification is needed to access applications or other system resources after the initial network logon. Organizations consider system use notification messages or banners displayed in multiple languages based on organizational needs and the demographics of system users. Organizations consult with the privacy office for input regarding privacy messaging and the Office of the General Counsel or organizational equivalent for legal review and approval of warning banner content. Related Controls:  AC-14, PL-4, SI-4. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p68-232', 0, 239, 'v2.1.0', 'ecc3422b71b5664e0a7dbbfaf05d1a6ecb1b7a24a8c764b7f20c1973d9bd7734', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Include a description of the authorized uses of the system.","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":232,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Include a description of the authorized uses of the system."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p68-233', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Include a description of the authorized uses of the system.', 68, 'AC-9 PREVIOUS LOGON NOTIFICATION Control:  Notify the user, upon successful logon to the system, of the date and time of the last logon. Discussion:  Previous logon notification is applicable to system access via human user interfaces and access to systems that occurs in other types of architectures. Information about the last successful logon allows the user to recognize if the date and time provided is not consistent with the user’s last access. Related Controls:  AC-7, PL-4. Control Enhancements: (1) PREVIOUS LOGON NOTIFICATION | UNSUCCESSFUL LOGONS Notify the user, upon successful logon, of the number of unsuccessful logon attempts since the last successful logon. Discussion:  Information about the number of unsuccessful logon attempts since the last successful logon allows the user to recognize if the number of unsuccessful logon attempts is consistent with the user’s actual logon attempts. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p68-233', 0, 234, 'v2.1.0', '5f3898bfd20df63d8b8a04350862b3cc8d0e29a08370832779d1771ffbc33da5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Include a description of the authorized uses of the system.","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":233,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Include a description of the authorized uses of the system."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p68-234', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Include a description of the authorized uses of the system.', 68, '(2) PREVIOUS LOGON NOTIFICATION | SUCCESSFUL AND UNSUCCESSFUL LOGONS Notify the user, upon successful logon, of the number of [Selection: successful logons; unsuccessful logon attempts; both] during [Assignment: organization-defined time period]. Discussion:  Information about the number of successful and unsuccessful logon attempts within a specified time period allows the user to recognize if the number and type of logon attempts are consistent with the user’s actual logon attempts. Related Controls:  None. (3) PREVIOUS LOGON NOTIFICATION | NOTIFICATION OF ACCOUNT CHANGES Notify the user, upon successful logon, of changes to [Assignment: organization-defined security-related characteristics or parameters of the user’s account] during [Assignment: organization-defined time period]. Discussion:  Information about changes to security-related account characteristics within a specified time period allows users to recognize if changes were made without their knowledge.', 'vec_doc-14-nist-sp-800-53-p68-234', 0, 245, 'v2.1.0', '4f7c59d115fb5891cfe94965c0f04d3ebcdbb9f41c60e7ef14b44fcf0afde38f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Include a description of the authorized uses of the system.","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":234,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Include a description of the authorized uses of the system."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p69-235', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 42', 69, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (4) PREVIOUS LOGON NOTIFICATION | ADDITIONAL LOGON INFORMATION Notify the user, upon successful logon, of the following additional information: [Assignment: organization-defined additional information]. Discussion:  Organizations can specify additional information to be provided to users upon logon, including the location of the last logon. User location is defined as information that can be determined by systems, such as Internet Protocol (IP) addresses from which network logons occurred, notifications of local logons, or device identifiers. Related Controls:  None. References:  None. AC-10 CONCURRENT SESSION CONTROL Control:  Limit the number of concurrent sessions for each [Assignment: organization-defined account and/or account type] to [Assignment: organization-defined number].', 'vec_doc-14-nist-sp-800-53-p69-235', 0, 228, 'v2.1.0', '098333fb6912578397790a22a78ce7b9263a0ef9c31703202397537846e86c54', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 42","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":235,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 42"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p69-236', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 42', 69, 'Discussion:  Organizations may define the maximum number of concurrent sessions for system accounts globally, by account type, by account, or any combination thereof. For example, organizations may limit the number of concurrent sessions for system administrators or other individuals working in particularly sensitive domains or mission-critical applications. Concurrent session control addresses concurrent sessions for system accounts. It does not, however, address concurrent sessions by single users via multiple system accounts. Related Controls:  SC-23. Control Enhancements:  None. References:  None. AC-11 DEVICE LOCK Control: a. Prevent further access to the system by [Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended]; and b.', 'vec_doc-14-nist-sp-800-53-p69-236', 0, 222, 'v2.1.0', '098f9098b4d849a933f5281aa72f0b37370032b8642583ad411c9fe788af5297', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 42","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":236,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 42"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p69-237', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 42', 69, 'Retain the device lock until the user reestablishes access using established identification and authentication procedures. Discussion:  Device locks are temporary actions taken to prevent logical access to organizational systems when users stop work and move away from the immediate vicinity of those systems but do not want to log out because of the temporary nature of their absences. Device locks can be implemented at the operating system level or at the application level. A proximity lock may be used to initiate the device lock (e.g., via a Bluetooth-enabled device or dongle). User-initiated device locking is behavior or policy-based and, as such, requires users to take physical action to initiate the device lock. Device locks are not an acceptable substitute for logging out of systems, such as when organizations require users to log out at the end of workdays. Related Controls:  AC-2, AC-7, IA-11, PL-4.', 'vec_doc-14-nist-sp-800-53-p69-237', 0, 230, 'v2.1.0', '20a26a1d1649489ddfeae5a76ae0a1a33f8594960033817b316770676990ee36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 42","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":237,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 42"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p69-238', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 42', 69, 'Control Enhancements: (1) DEVICE LOCK | PATTERN-HIDING DISPLAYS Conceal, via the device lock, information previously visible on the display with a publicly viewable image.', 'vec_doc-14-nist-sp-800-53-p69-238', 0, 43, 'v2.1.0', '585b303290d471b36d26ab1cb1af68e9871c92a623f79cea5ce97e9194fceae5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 42","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":238,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 42"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p70-239', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 43', 70, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The pattern-hiding display can include static or dynamic images, such as patterns used with screen savers, photographic images, solid colors, clock, battery life indicator, or a blank screen with the caveat that controlled unclassified information is not displayed. Related Controls:  None. References:  None. AC-12 SESSION TERMINATION Control:  Automatically terminate a user session after [Assignment: organization-defined conditions or trigger events requiring session disconnect]. Discussion:  Session termination addresses the termination of user-initiated logical sessions (in contrast to SC-10, which addresses the termination of network connections associated with communications sessions (i.e., network disconnect)). A logical session (for local, network, and remote access) is initiated whenever a user (or process acting on behalf of a user) accesses an organizational system.', 'vec_doc-14-nist-sp-800-53-p70-239', 0, 248, 'v2.1.0', 'b8802a31bb3fa0cfb5a6cfae326f1158b9daf39fa875fdbe367cfc66887b871a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 43","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":239,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 43"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p70-240', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 43', 70, 'Such user sessions can be terminated without terminating network sessions. Session termination ends all processes associated with a user’s logical session except for those processes that are specifically created by the user (i.e., session owner) to continue after the session is terminated. Conditions or trigger events that require automatic termination of the session include organization-defined periods of user inactivity, targeted responses to certain types of incidents, or time-of-day restrictions on system use. Related Controls:  MA-4, SC-10, SC-23. Control Enhancements: (1) SESSION TERMINATION | USER-INITIATED LOGOUTS Provide a logout capability for user-initiated communications sessions whenever authentication is used to gain access to [Assignment: organization-defined information resources]. Discussion:  Information resources to which users gain access via authentication include local workstations, databases, and password-protected websites or web-based services.', 'vec_doc-14-nist-sp-800-53-p70-240', 0, 246, 'v2.1.0', '79eb177ff8ac3ae1baf71163a9ec5b32ce2abdf5b4dfc120341b6d173a267012', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 43","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":240,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 43"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p70-241', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 43', 70, 'Related Controls:  None. (2) SESSION TERMINATION | TERMINATION MESSAGE Display an explicit logout message to users indicating the termination of authenticated communications sessions. Discussion:  Logout messages for web access can be displayed after authenticated sessions have been terminated. However, for certain types of sessions, including file transfer protocol (FTP) sessions, systems typically send logout messages as final messages prior to terminating sessions. Related Controls:  None. (3) SESSION TERMINATION | TIMEOUT WARNING MESSAGE Display an explicit message to users indicating that the session will end in [Assignment: organization-defined time until end of session]. Discussion:  To increase usability, notify users of pending session termination and prompt users to continue the session. The pending session termination time period is based on the parameters defined in the AC-12 base control. Related Controls:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p70-241', 0, 240, 'v2.1.0', '286fbba7ef35ebf92b10cf777dc2441c4b11f6527e124eaf13f1348ae75bd4ac', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 43","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":241,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 43"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p71-242', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 44', 71, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 AC-13 SUPERVISION AND REVIEW —  ACCESS CONTROL [Withdrawn: Incorporated into AC-2 and AU-6.] AC-14 PERMITTED ACTIONS WITHOUT IDENTIFICATION OR AUTHENTICATION Control: a. Identify [Assignment: organization-defined user actions] that can be performed on the system without identification or authentication consistent with organizational mission and business functions; and b. Document and provide supporting rationale in the security plan for the system, user actions not requiring identification or authentication. Discussion:  Specific user actions may be permitted without identification or authentication if organizations determine that identification and authentication are not required for the specified user actions.', 'vec_doc-14-nist-sp-800-53-p71-242', 0, 204, 'v2.1.0', '7db52d7164080a4f3efe027da9fd086c1184889319d197bc50b9bf87bedf26e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 44","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":242,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 44"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p71-243', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 44', 71, 'Organizations may allow a limited number of user actions without identification or authentication, including when individuals access public websites or other publicly accessible federal systems, when individuals use mobile phones to receive calls, or when facsimiles are received. Organizations identify actions that normally require identification or authentication but may, under certain circumstances, allow identification or authentication mechanisms to be bypassed. Such bypasses may occur, for example, via a software-readable physical switch that commands bypass of the logon functionality and is protected from accidental or unmonitored use. Permitting actions without identification or authentication does not apply to situations where identification and authentication have already occurred and are not repeated but rather to situations where identification and authentication have not yet occurred.', 'vec_doc-14-nist-sp-800-53-p71-243', 0, 228, 'v2.1.0', 'e7ea6cb5c4ecb16446bc42ac629c7ee03cf8c98658837a340eedd60d3abe7a57', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 44","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":243,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 44"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p71-244', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 44', 71, 'Organizations may decide that there are no user actions that can be performed on organizational systems without identification and authentication, and therefore, the value for the assignment operation can be “none.” Related Controls:  AC-8, IA-2, PL-2. Control Enhancements:  None. (1) PERMITTED ACTIONS WITHOUT IDENTIFICATION OR AUTHENTICATION | NECESSARY USES [Withdrawn: Incorporated into AC-14.] References:  None. AC-15 AUTOMATED MARKING [Withdrawn: Incorporated into MP-3.] AC-16 SECURITY AND PRIVACY ATTRIBUTES Control: a. Provide the means to associate [Assignment: organization-defined types of security and privacy attributes] with [Assignment: organization-defined security and privacy attribute values] for information in storage, in process, and/or in transmission; b. Ensure that the attribute associations are made and retained with the information; c.', 'vec_doc-14-nist-sp-800-53-p71-244', 0, 217, 'v2.1.0', '03cb571a1ebed4ca8bdddd1c43e0bcc6b9240ab3f42c5e8f37eaf950b13a47ed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 44","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":244,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 44"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p71-245', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 44', 71, 'Establish the following permitted security and privacy attributes from the attributes defined in AC-16a for [Assignment: organization-defined systems]: [Assignment: organization-defined security and privacy attributes];', 'vec_doc-14-nist-sp-800-53-p71-245', 0, 55, 'v2.1.0', '4589b72a1433744ab709f218ac73f97cef3cf4bd0fa9ebf7e0486ec2923b9c7a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 44","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":245,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 44"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p72-246', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 45', 72, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 d. Determine the following permitted attribute values or ranges for each of the established attributes: [Assignment: organization-defined attribute values or ranges for established attributes]; e. Audit changes to attributes; and f. Review [Assignment: organization-defined security and privacy attributes] for applicability [Assignment: organization-defined frequency]. Discussion:  Information is represented internally within systems using abstractions known as data structures. Internal data structures can represent different types of entities, both active and passive. Active entities, also known as subjects, are typically associated with individuals, devices, or processes acting on behalf of individuals. Passive entities, also known as objects, are typically associated with data structures, such as records, buffers, tables, files, inter-process pipes, and communications ports.', 'vec_doc-14-nist-sp-800-53-p72-246', 0, 246, 'v2.1.0', '1ee97ed5ae26ba8ebb7246f3c38127299a46cd36e961a25852fbd0158a008554', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 45","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":246,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 45"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p72-247', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 45', 72, 'Security attributes, a form of metadata, are abstractions that represent the basic properties or characteristics of active and passive entities with respect to safeguarding information. Privacy attributes, which may be used independently or in conjunction with security attributes, represent the basic properties or characteristics of active or passive entities with respect to the management of personally identifiable information. Attributes can be either explicitly or implicitly associated with the information contained in organizational systems or system components. Attributes may be associated with active entities (i.e., subjects) that have the potential to send or receive information, cause information to flow among objects, or change the system state. These attributes may also be associated with passive entities (i.e., objects) that contain or receive information.', 'vec_doc-14-nist-sp-800-53-p72-247', 0, 220, 'v2.1.0', '6e18f55eedb27d28c447c89b499b08291e0c8a38e9375c9f56183c2b7d5707cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 45","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":247,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 45"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p72-248', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 45', 72, 'The association of attributes to subjects and objects by a system is referred to as binding and is inclusive of setting the attribute value and the attribute type. Attributes, when bound to data or information, permit the enforcement of security and privacy policies for access control and information flow control, including data retention limits, permitted uses of personally identifiable information, and identification of personal information within data objects. Such enforcement occurs through organizational processes or system functions or mechanisms. The binding techniques implemented by systems affect the strength of attribute binding to information. Binding strength and the assurance associated with binding techniques play important parts in the trust that organizations have in the information flow enforcement process. The binding techniques affect the number and degree of additional reviews required by organizations.', 'vec_doc-14-nist-sp-800-53-p72-248', 0, 234, 'v2.1.0', '799bda6c405700a7e46c1fea2bd70cd27a9a31e1de7bcc01e899c80d594269eb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 45","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":248,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 45"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p72-249', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 45', 72, 'The content or assigned values of attributes can directly affect the ability of individuals to access organizational information. Organizations can define the types of attributes needed for systems to support missions or business functions. There are many values that can be assigned to a security attribute. By specifying the permitted attribute ranges and values, organizations ensure that attribute values are meaningful and relevant. Labeling refers to the association of attributes with the subjects and objects represented by the internal data structures within systems. This facilitates system- based enforcement of information security and privacy policies.', 'vec_doc-14-nist-sp-800-53-p72-249', 0, 167, 'v2.1.0', '2d1c1cbb10886205181f715ad350b74d4f36282f32de18a5502517e81cb0fbf7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 45","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":249,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 45"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p72-250', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 45', 72, 'Labels include classification of information in accordance with legal and compliance requirements (e.g., top secret, secret, confidential, controlled unclassified), information impact level; high value asset information, access authorizations, nationality; data life cycle protection (i.e., encryption and data expiration), personally identifiable information processing permissions, including individual consent to personally identifiable information processing, and contractor affiliation. A related term to labeling is marking. Marking refers to the association of attributes with objects in a human- readable form and displayed on system media. Marking enables manual, procedural, or process- based enforcement of information security and privacy policies. Security and privacy labels may have the same value as media markings (e.g., top secret, secret, confidential). See MP-3 (Media Marking).', 'vec_doc-14-nist-sp-800-53-p72-250', 0, 225, 'v2.1.0', '6db02e32cb1832bdc0d6f88ab453714fc7d8c06091722265540ead83088e7cd7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 45","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":250,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 45"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p73-251', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 46', 73, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  AC-3, AC-4, AC-6, AC-21, AC-25, AU-2, AU-10, MP-3, PE-22, PT-2, PT-3, PT-4, SC-11, SC-16, SI-12, SI-18. Control Enhancements: (1) SECURITY AND PRIVACY ATTRIBUTES | DYNAMIC ATTRIBUTE ASSOCIATION Dynamically associate security and privacy attributes with [Assignment: organization- defined subjects and objects] in accordance with the following security and privacy policies as information is created and combined: [Assignment: organization-defined security and privacy policies]. Discussion:  Dynamic association of attributes is appropriate whenever the security or privacy characteristics of information change over time.', 'vec_doc-14-nist-sp-800-53-p73-251', 0, 184, 'v2.1.0', 'f3443a99d928e88e2b71558107362fcacaac3587a4763de654a88eb62ada9af8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 46","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":251,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 46"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p73-252', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 46', 73, 'Attributes may change due to information aggregation issues (i.e., characteristics of individual data elements are different from the combined elements), changes in individual access authorizations (i.e., privileges), changes in the security category of information, or changes in security or privacy policies. Attributes may also change situationally. Related Controls:  None. (2) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE VALUE CHANGES BY AUTHORIZED INDIVIDUALS Provide authorized individuals (or processes acting on behalf of individuals) the capability to define or change the value of associated security and privacy attributes. Discussion:  The content or assigned values of attributes can directly affect the ability of individuals to access organizational information. Therefore, it is important for systems to be able to limit the ability to create or modify attributes to authorized individuals. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p73-252', 0, 233, 'v2.1.0', '533ab5e43b0faa754da883e75d267159d52cfe9d80c848128df761b93cbef077', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 46","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":252,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 46"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p73-253', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 46', 73, '(3) SECURITY AND PRIVACY ATTRIBUTES | MAINTENANCE OF ATTRIBUTE ASSOCIATIONS BY SYSTEM Maintain the association and integrity of [Assignment: organization-defined security and privacy attributes] to [Assignment: organization-defined subjects and objects]. Discussion:  Maintaining the association and integrity of security and privacy attributes to subjects and objects with sufficient assurance helps to ensure that the attribute associations can be used as the basis of automated policy actions. The integrity of specific items, such as security configuration files, may be maintained through the use of an integrity monitoring mechanism that detects anomalies and changes that deviate from “known good” baselines. Automated policy actions include retention date expirations, access control decisions, information flow control decisions, and information disclosure decisions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p73-253', 0, 226, 'v2.1.0', 'd3d7ed38e7c74c395c2619780622b9f905b25bc2838e5ba6feb5f7ce8d4c7b05', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 46","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":253,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 46"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p73-254', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 46', 73, '(4) SECURITY AND PRIVACY ATTRIBUTES | ASSOCIATION OF ATTRIBUTES BY AUTHORIZED INDIVIDUALS Provide the capability to associate [Assignment: organization-defined security and privacy attributes] with [Assignment: organization-defined subjects and objects] by authorized individuals (or processes acting on behalf of individuals). Discussion:  Systems, in general, provide the capability for privileged users to assign security and privacy attributes to system-defined subjects (e.g., users) and objects (e.g., directories, files, and ports). Some systems provide additional capability for general users to assign security and privacy attributes to additional objects (e.g., files, emails). The association of attributes by authorized individuals is described in the design documentation.', 'vec_doc-14-nist-sp-800-53-p73-254', 0, 197, 'v2.1.0', '43a7d709e541e40396f9630879edfb727c900140e5f7fcf0e02499d833e4668e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 46","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":254,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 46"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p73-255', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 46', 73, 'The support provided by systems can include prompting users to select security and privacy attributes to be associated with information objects, employing automated mechanisms to categorize information with attributes based on defined policies, or ensuring that the combination of the security or privacy attributes selected is valid. Organizations consider the creation, deletion, or modification of attributes when defining auditable events.', 'vec_doc-14-nist-sp-800-53-p73-255', 0, 111, 'v2.1.0', '1345c6a19fdc8127533b3e1225c5fbd5f0ba603f4ae1dbfc9bfb9570f2a5e8c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 46","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":255,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 46"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p74-256', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 47', 74, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (5) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE DISPLAYS ON OBJECTS TO BE OUTPUT Display security and privacy attributes in human-readable form on each object that the system transmits to output devices to identify [Assignment: organization-defined special dissemination, handling, or distribution instructions] using [Assignment: organization- defined human-readable, standard naming conventions]. Discussion:  System outputs include printed pages, screens, or equivalent items. System output devices include printers, notebook computers, video displays, smart phones, and tablets. To mitigate the risk of unauthorized exposure of information (e.g., shoulder surfing), the outputs display full attribute values when unmasked by the subscriber. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p74-256', 0, 222, 'v2.1.0', 'b31ebc6eebe38c5d21cab916eeceeb80f81db04866961860e92c53abb4accc6b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 47","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":256,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 47"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p74-257', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 47', 74, '(6) SECURITY AND PRIVACY ATTRIBUTES | MAINTENANCE OF ATTRIBUTE ASSOCIATION Require personnel to associate and maintain the association of [Assignment: organization- defined security and privacy attributes] with [Assignment: organization-defined subjects and objects] in accordance with [Assignment: organization-defined security and privacy policies]. Discussion:  Maintaining attribute association requires individual users (as opposed to the system) to maintain associations of defined security and privacy attributes with subjects and objects. Related Controls:  None. (7) SECURITY AND PRIVACY ATTRIBUTES | CONSISTENT ATTRIBUTE INTERPRETATION Provide a consistent interpretation of security and privacy attributes transmitted between distributed system components.', 'vec_doc-14-nist-sp-800-53-p74-257', 0, 192, 'v2.1.0', '0f48fce3ba0aeaceec6730a9fdba4efc62968411d4bcdf90fbda84c177e71bde', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 47","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":257,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 47"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p74-258', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 47', 74, 'Discussion:  To enforce security and privacy policies across multiple system components in distributed systems, organizations provide a consistent interpretation of security and privacy attributes employed in access enforcement and flow enforcement decisions. Organizations can establish agreements and processes to help ensure that distributed system components implement attributes with consistent interpretations in automated access enforcement and flow enforcement actions. Related Controls:  None. (8) SECURITY AND PRIVACY ATTRIBUTES | ASSOCIATION TECHNIQUES AND TECHNOLOGIES Implement [Assignment: organization-defined techniques and technologies] in associating security and privacy attributes to information. Discussion:  The association of security and privacy attributes to information within systems is important for conducting automated access enforcement and flow enforcement actions.', 'vec_doc-14-nist-sp-800-53-p74-258', 0, 225, 'v2.1.0', '2134028eb2faf3af1bd8dd7110b31b120d8d379d45a2191cba40ce644805506a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 47","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":258,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 47"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p74-259', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 47', 74, 'The association of such attributes to information (i.e., binding) can be accomplished with technologies and techniques that provide different levels of assurance. For example, systems can cryptographically bind attributes to information using digital signatures that support cryptographic keys protected by hardware devices (sometimes known as hardware roots of trust). Related Controls:  SC-12, SC-13. (9) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE REASSIGNMENT —  REGRADING MECHANISMS Change security and privacy attributes associated with information only via regrading mechanisms validated using [Assignment: organization-defined techniques or procedures]. Discussion:  A regrading mechanism is a trusted process authorized to re-classify and re-label data in accordance with a defined policy exception. Validated regrading mechanisms are', 'vec_doc-14-nist-sp-800-53-p74-259', 0, 211, 'v2.1.0', 'd454bdc3af917351d65ffcb7b53604a5a620b079efd1c95e9e3b59c83db63b4d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 47","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":259,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 47"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p75-260', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 48', 75, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 used by organizations to provide the requisite levels of assurance for attribute reassignment activities. The validation is facilitated by ensuring that regrading mechanisms are single purpose and of limited function. Since security and privacy attribute changes can directly affect policy enforcement actions, implementing trustworthy regrading mechanisms is necessary to help ensure that such mechanisms perform in a consistent and correct mode of operation. Related Controls:  None. (10) SECURITY AND PRIVACY ATTRIBUTES | ATTRIBUTE CONFIGURATION BY AUTHORIZED INDIVIDUALS Provide authorized individuals the capability to define or change the type and value of security and privacy attributes available for association with subjects and objects. Discussion:  The content or assigned values of security and privacy attributes can directly affect the ability of individuals to access organizational information.', 'vec_doc-14-nist-sp-800-53-p75-260', 0, 251, 'v2.1.0', 'd3d2c44fa28e61cc40390c474f8d95d66cb697ed122241716637dced801ae35e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 48","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":260,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 48"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p75-261', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 48', 75, 'Thus, it is important for systems to be able to limit the ability to create or modify the type and value of attributes available for association with subjects and objects to authorized individuals only. Related Controls:  None. References:  [OMB A-130], [FIPS 140-3], [FIPS 186-4], [SP 800-162], [SP 800-178]. AC-17 REMOTE ACCESS Control: a. Establish and document usage restrictions, configuration/connection requirements, and implementation guidance for each type of remote access allowed; and b. Authorize each type of remote access to the system prior to allowing such connections. Discussion:  Remote access is access to organizational systems (or processes acting on behalf of users) that communicate through external networks such as the Internet. Types of remote access include dial-up, broadband, and wireless. Organizations use encrypted virtual private networks (VPNs) to enhance confidentiality and integrity for remote connections.', 'vec_doc-14-nist-sp-800-53-p75-261', 0, 236, 'v2.1.0', '48f949e4b6629cae258dd3aefc2360882d4b91ecc135f82905f836ce1e7e0f24', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 48","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":261,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 48"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p75-262', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 48', 75, 'The use of encrypted VPNs provides sufficient assurance to the organization that it can effectively treat such connections as internal networks if the cryptographic mechanisms used are implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Still, VPN connections traverse external networks, and the encrypted VPN does not enhance the availability of remote connections. VPNs with encrypted tunnels can also affect the ability to adequately monitor network communications traffic for malicious code. Remote access controls apply to systems other than public web servers or systems designed for public access. Authorization of each remote access type addresses authorization prior to allowing remote access without specifying the specific formats for such authorization.', 'vec_doc-14-nist-sp-800-53-p75-262', 0, 211, 'v2.1.0', '4e4d1805fe8f0afa4230559f949229f613383a3f214d2ac62086ec58502052fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 48","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":262,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 48"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p75-263', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 48', 75, 'While organizations may use information exchange and system connection security agreements to manage remote access connections to other systems, such agreements are addressed as part of CA-3. Enforcing access restrictions for remote access is addressed via AC-3. Related Controls:  AC-2, AC-3, AC-4, AC-18, AC-19, AC-20, CA-3, CM-10, IA-2, IA-3, IA-8, MA-4, PE- 17, PL-2, PL-4, SC-10, SC-12, SC-13, SI-4. Control Enhancements: (1) REMOTE ACCESS | MONITORING AND CONTROL Employ automated mechanisms to monitor and control remote access methods. Discussion:  Monitoring and control of remote access methods allows organizations to detect attacks and help ensure compliance with remote access policies by auditing the connection activities of remote users on a variety of system components, including servers,', 'vec_doc-14-nist-sp-800-53-p75-263', 0, 202, 'v2.1.0', '66bf259439858be87b8dbe9b24773e9b9cf2c1f0ea9dc6dc3b9f9b9411ead52c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 48","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":263,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 48"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p76-264', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 49', 76, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 notebook computers, workstations, smart phones, and tablets. Audit logging for remote access is enforced by AU-2. Audit events are defined in AU-2a. Related Controls:  AU-2, AU-6, AU-12, AU-14. (2) REMOTE ACCESS | PROTECTION OF CONFIDENTIALITY AND INTEGRITY USING ENCRYPTION Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions. Discussion:  Virtual private networks can be used to protect the confidentiality and integrity of remote access sessions. Transport Layer Security (TLS) is an example of a cryptographic protocol that provides end-to-end communications security over networks and is used for Internet communications and online transactions. Related Controls:  SC-8, SC-12, SC-13. (3) REMOTE ACCESS | MANAGED ACCESS CONTROL POINTS Route remote accesses through authorized and managed network access control points.', 'vec_doc-14-nist-sp-800-53-p76-264', 0, 243, 'v2.1.0', '93bb13fee57f824fdccad473bcdb1206db6aa8a2b2fbb6149469864d2b03c869', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 49","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":264,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 49"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p76-265', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 49', 76, 'Discussion:  Organizations consider the Trusted Internet Connections (TIC) initiative [DHS TIC] requirements for external network connections since limiting the number of access control points for remote access reduces attack surfaces. Related Controls:  SC-7. (4) REMOTE ACCESS | PRIVILEGED COMMANDS AND ACCESS (a) Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: [Assignment: organization-defined needs]; and (b) Document the rationale for remote access in the security plan for the system. Discussion:  Remote access to systems represents a significant potential vulnerability that can be exploited by adversaries. As such, restricting the execution of privileged commands and access to security-relevant information via remote access reduces the exposure of the organization and the susceptibility to threats by adversaries to the remote access capability.', 'vec_doc-14-nist-sp-800-53-p76-265', 0, 250, 'v2.1.0', 'ab9dec69c1c0167e1fd3407c553a6f0524092eeac335deaeff6ac05d3a348533', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 49","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":265,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 49"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p76-266', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 49', 76, 'Related Controls:  AC-6, SC-12, SC-13. (5) REMOTE ACCESS | MONITORING FOR UNAUTHORIZED CONNECTIONS [Withdrawn: Incorporated into SI-4.] (6) REMOTE ACCESS | PROTECTION OF MECHANISM INFORMATION Protect information about remote access mechanisms from unauthorized use and disclosure. Discussion:  Remote access to organizational information by non-organizational entities can increase the risk of unauthorized use and disclosure about remote access mechanisms. The organization considers including remote access requirements in the information exchange agreements with other organizations, as applicable. Remote access requirements can also be included in rules of behavior (see PL-4) and access agreements (see PS-6). Related Controls:  AT-2, AT-3, PS-6. (7) REMOTE ACCESS | ADDITIONAL PROTECTION FOR SECURITY FUNCTION ACCESS [Withdrawn: Incorporated into AC-3(10).] (8) REMOTE ACCESS | DISABLE NONSECURE NETWORK PROTOCOLS [Withdrawn: Incorporated into CM-7.] (9) REMOTE ACCESS | DISCONNECT OR DISABLE ACCESS', 'vec_doc-14-nist-sp-800-53-p76-266', 0, 252, 'v2.1.0', '15924e57227280452909939194b4ef6d564dfdfa514465af640493d37805765c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 49","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":266,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 49"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p77-267', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 50', 77, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Provide the capability to disconnect or disable remote access to the system within [Assignment: organization-defined time period]. Discussion:  The speed of system disconnect or disablement varies based on the criticality of missions or business functions and the need to eliminate immediate or future remote access to systems. Related Controls:  None. (10) REMOTE ACCESS | AUTHENTICATE REMOTE COMMANDS Implement [Assignment: organization-defined mechanisms] to authenticate [Assignment: organization-defined remote commands]. Discussion:  Authenticating remote commands protects against unauthorized commands and the replay of authorized commands.', 'vec_doc-14-nist-sp-800-53-p77-267', 0, 185, 'v2.1.0', '2b1b92e0a6e13e686cd49528afd805ffdb73a1aba6e4caf125f0dde1ef244dd2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 50","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":267,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 50"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p77-268', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 50', 77, 'The ability to authenticate remote commands is important for remote systems for which loss, malfunction, misdirection, or exploitation would have immediate or serious consequences, such as injury, death, property damage, loss of high value assets, failure of mission or business functions, or compromise of classified or controlled unclassified information. Authentication mechanisms for remote commands ensure that systems accept and execute commands in the order intended, execute only authorized commands, and reject unauthorized commands. Cryptographic mechanisms can be used, for example, to authenticate remote commands. Related Controls:  SC-12, SC-13, SC-23. References:  [SP 800-46], [SP 800-77], [SP 800-113], [SP 800-114], [SP 800-121], [IR 7966]. AC-18 WIRELESS ACCESS Control: a. Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and b.', 'vec_doc-14-nist-sp-800-53-p77-268', 0, 231, 'v2.1.0', 'a350ebdf6f8c4fc2dd4b24e4d9c79ee7c19d5e2e5632e9b9bf609e5e42f76a0c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 50","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":268,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 50"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p77-269', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 50', 77, 'Authorize each type of wireless access to the system prior to allowing such connections. Discussion:  Wireless technologies include microwave, packet radio (ultra-high frequency or very high frequency), 802.11x, and Bluetooth. Wireless networks use authentication protocols that provide authenticator protection and mutual authentication. Related Controls:  AC-2, AC-3, AC-17, AC-19, CA-9, CM-7, IA-2, IA-3, IA-8, PL-4, SC-40, SC-43, SI-4. Control Enhancements: (1) WIRELESS ACCESS | AUTHENTICATION AND ENCRYPTION Protect wireless access to the system using authentication of [Selection (one or more): users; devices] and encryption. Discussion:  Wireless networking capabilities represent a significant potential vulnerability that can be exploited by adversaries. To protect systems with wireless access points, strong authentication of users and devices along with strong encryption can reduce susceptibility to threats by adversaries involving wireless technologies.', 'vec_doc-14-nist-sp-800-53-p77-269', 0, 243, 'v2.1.0', 'a37089d9e3593193f22cf1931aae758201d325c94065dfbe15d49d57d2583285', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 50","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":269,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 50"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p77-270', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 50', 77, 'Related Controls:  SC-8, SC-12, SC-13. (2) WIRELESS ACCESS | MONITORING UNAUTHORIZED CONNECTIONS [Withdrawn: Incorporated into SI-4.] (3) WIRELESS ACCESS | DISABLE WIRELESS NETWORKING Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment.', 'vec_doc-14-nist-sp-800-53-p77-270', 0, 80, 'v2.1.0', 'c73f55ab5d4bdd0c1bba8e3ae262a0c276ecbcf4c9ea9252541593e10b03e4dd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 50","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":270,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 50"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p78-271', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 51', 78, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Wireless networking capabilities that are embedded within system components represent a significant potential vulnerability that can be exploited by adversaries. Disabling wireless capabilities when not needed for essential organizational missions or functions can reduce susceptibility to threats by adversaries involving wireless technologies. Related Controls:  None. (4) WIRELESS ACCESS | RESTRICT CONFIGURATIONS BY USERS Identify and explicitly authorize users allowed to independently configure wireless networking capabilities. Discussion:  Organizational authorizations to allow selected users to configure wireless networking capabilities are enforced, in part, by the access enforcement mechanisms employed within organizational systems. Related Controls:  SC-7, SC-15.', 'vec_doc-14-nist-sp-800-53-p78-271', 0, 221, 'v2.1.0', '6ea4a3c3c5da0d0970aeed275ef4b1292fa7341849eefe463cd2ba6998c7a03c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 51","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":271,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 51"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p78-272', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 51', 78, '(5) WIRELESS ACCESS | ANTENNAS AND TRANSMISSION POWER LEVELS Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries. Discussion:  Actions that may be taken to limit unauthorized use of wireless communications outside of organization-controlled boundaries include reducing the power of wireless transmissions so that the transmissions are less likely to emit a signal that can be captured outside of the physical perimeters of the organization, employing measures such as emissions security to control wireless emanations, and using directional or beamforming antennas that reduce the likelihood that unintended receivers will be able to intercept signals.', 'vec_doc-14-nist-sp-800-53-p78-272', 0, 198, 'v2.1.0', '0fb995b60b6409ca2844d2062d3534a0dd16f908c93bc736187ddafbb3c40385', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 51","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":272,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 51"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p78-273', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 51', 78, 'Prior to taking such mitigating actions, organizations can conduct periodic wireless surveys to understand the radio frequency profile of organizational systems as well as other systems that may be operating in the area. Related Controls:  PE-19. References:  [SP 800-94], [SP 800-97]. AC-19 ACCESS CONTROL FOR MOBILE DEVICES Control: a. Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; and b. Authorize the connection of mobile devices to organizational systems. Discussion:  A mobile device is a computing device that has a small form factor such that it can easily be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source.', 'vec_doc-14-nist-sp-800-53-p78-273', 0, 227, 'v2.1.0', '3f7eacffe15fbba2601d58667603e9f0c775bb01726888040010c9bf07de2bf7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 51","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":273,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 51"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p78-274', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 51', 78, 'Mobile device functionality may also include voice communication capabilities, on-board sensors that allow the device to capture information, and/or built-in features for synchronizing local data with remote locations. Examples include smart phones and tablets. Mobile devices are typically associated with a single individual. The processing, storage, and transmission capability of the mobile device may be comparable to or merely a subset of notebook/desktop systems, depending on the nature and intended purpose of the device. Protection and control of mobile devices is behavior or policy-based and requires users to take physical action to protect and control such devices when outside of controlled areas. Controlled areas are spaces for which organizations provide physical or procedural controls to meet the requirements established for protecting information and systems.', 'vec_doc-14-nist-sp-800-53-p78-274', 0, 221, 'v2.1.0', '1db203bc3945374547f77d67783b0b0efb98e48bb2e9ab8456c2a16124de9cb1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 51","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":274,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 51"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p79-275', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 52', 79, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Due to the large variety of mobile devices with different characteristics and capabilities, organizational restrictions may vary for the different classes or types of such devices. Usage restrictions and specific implementation guidance for mobile devices include configuration management, device identification and authentication, implementation of mandatory protective software, scanning devices for malicious code, updating virus protection software, scanning for critical software updates and patches, conducting primary operating system (and possibly other resident software) integrity checks, and disabling unnecessary hardware. Usage restrictions and authorization to connect may vary among organizational systems.', 'vec_doc-14-nist-sp-800-53-p79-275', 0, 204, 'v2.1.0', '7abf88e0b77181d7e44ac091c3c2b7aa59da9e0312ae793171c52899ce233d34', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 52","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":275,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 52"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p79-276', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 52', 79, 'For example, the organization may authorize the connection of mobile devices to its network and impose a set of usage restrictions, while a system owner may withhold authorization for mobile device connection to specific applications or impose additional usage restrictions before allowing mobile device connections to a system. Adequate security for mobile devices goes beyond the requirements specified in AC-19. Many safeguards for mobile devices are reflected in other controls. AC-20 addresses mobile devices that are not organization-controlled. Related Controls:  AC-3, AC-4, AC-7, AC-11, AC-17, AC-18, AC-20, CA-9, CM-2, CM-6, IA-2, IA-3, MP-2, MP-4, MP-5, MP-7, PL-4, SC-7, SC-34, SC-43, SI-3, SI-4.', 'vec_doc-14-nist-sp-800-53-p79-276', 0, 177, 'v2.1.0', 'ba5bac6db8ab0feccfb0283998fdfd1f2b63aa8de058a25177d76a055ac75360', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 52","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":276,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 52"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p79-277', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 52', 79, 'Control Enhancements: (1) ACCESS CONTROL FOR MOBILE DEVICES | USE OF WRITABLE AND PORTABLE STORAGE DEVICES [Withdrawn: Incorporated into MP-7.] (2) ACCESS CONTROL FOR MOBILE DEVICES | USE OF PERSONALLY OWNED PORTABLE STORAGE DEVICES [Withdrawn: Incorporated into MP-7.] (3) ACCESS CONTROL FOR MOBILE DEVICES | USE OF PORTABLE STORAGE DEVICES WITH NO IDENTIFIABLE OWNER [Withdrawn: Incorporated into MP-7.] (4) ACCESS CONTROL FOR MOBILE DEVICES | RESTRICTIONS FOR CLASSIFIED INFORMATION (a) Prohibit the use of unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and (b) Enforce the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing systems processing, storing, or transmitting classified information: (1) Connection of unclassified mobile devices to classified systems is prohibited; (2) Connection of unclassified mobile devices to unclassified systems requires approval from the authorizing official; (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by [Assignment: organization-defined security officials], and if classified information is found, the incident handling policy is followed.', 'vec_doc-14-nist-sp-800-53-p79-277', 0, 375, 'v2.1.0', '4ed6e103381f8a1a251747f0f7bac9267e08469122f28c895df5e9fcda87efe6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 52","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":277,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 52"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p79-278', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 52', 79, '(c) Restrict the connection of classified mobile devices to classified systems in accordance with [Assignment: organization-defined security policies]. Discussion:  None. Related Controls:  CM-8, IR-4. (5) ACCESS CONTROL FOR MOBILE DEVICES | FULL DEVICE OR CONTAINER-BASED ENCRYPTION', 'vec_doc-14-nist-sp-800-53-p79-278', 0, 71, 'v2.1.0', 'a38ecf76ae85347ecef47ddcac109b4d9ccab31e11d91d2518f7f83514064d58', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 52","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":278,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 52"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p80-279', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 53', 80, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices]. Discussion:  Container-based encryption provides a more fine-grained approach to data and information encryption on mobile devices, including encrypting selected data structures such as files, records, or fields. Related Controls:  SC-12,  SC-13, SC-28. References:  [SP 800-114], [SP 800-124]. AC-20 USE OF EXTERNAL SYSTEMS Control: a. [Selection (one or more): Establish [Assignment: organization-defined terms and conditions]; Identify [Assignment: organization-defined controls asserted to be implemented on external systems]], consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:', 'vec_doc-14-nist-sp-800-53-p80-279', 0, 245, 'v2.1.0', '36ded5e98594abafd6e6fdea07746fe2f10354bfd360e4dc46ceefc8bc7a5219', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 53","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":279,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 53"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p80-280', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Process, store, or transmit organization-controlled information using external systems;', 80, 'or b. Prohibit the use of [Assignment: organizationally-defined types of external systems]. Discussion:  External systems are systems that are used by but not part of organizational systems, and for which the organization has no direct control over the implementation of required controls or the assessment of control effectiveness. External systems include personally owned systems, components, or devices; privately owned computing and communications devices in commercial or public facilities; systems owned or controlled by nonfederal organizations; systems managed by contractors; and federal information systems that are not owned by, operated by, or under the direct supervision or authority of the organization. External systems also include systems owned or operated by other components within the same organization and systems within the organization with different authorization boundaries.', 'vec_doc-14-nist-sp-800-53-p80-280', 0, 226, 'v2.1.0', 'ea25942f9f70e17a9c88ea84d46a12f4328d933f2600715dd6dcc3373403b0bd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Process, store, or transmit organization-controlled information using external systems;","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":280,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Process, store, or transmit organization-controlled information using external systems;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p80-281', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Process, store, or transmit organization-controlled information using external systems;', 80, 'Organizations have the option to prohibit the use of any type of external system or prohibit the use of specified types of external systems, (e.g., prohibit the use of any external system that is not organizationally owned or prohibit the use of personally-owned systems). For some external systems (i.e., systems operated by other organizations), the trust relationships that have been established between those organizations and the originating organization may be such that no explicit terms and conditions are required. Systems within these organizations may not be considered external. These situations occur when, for example, there are pre-existing information exchange agreements (either implicit or explicit) established between organizations or components or when such agreements are specified by applicable laws, executive orders, directives, regulations, policies, or standards.', 'vec_doc-14-nist-sp-800-53-p80-281', 0, 223, 'v2.1.0', '15826a271776496e42129e559575cf82d7549fd4c772dcb2a2e8d9accd04b369', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Process, store, or transmit organization-controlled information using external systems;","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":281,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Process, store, or transmit organization-controlled information using external systems;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p80-282', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Process, store, or transmit organization-controlled information using external systems;', 80, 'Authorized individuals include organizational personnel, contractors, or other individuals with authorized access to organizational systems and over which organizations have the authority to impose specific rules of behavior regarding system access. Restrictions that organizations impose on authorized individuals need not be uniform, as the restrictions may vary depending on trust relationships between organizations. Therefore, organizations may choose to impose different security restrictions on contractors than on state, local, or tribal governments. External systems used to access public interfaces to organizational systems are outside the scope of AC-20 . Organizations establish specific terms and conditions for the use of external systems in accordance with organizational security policies and procedures. At a minimum, terms and conditions address the specific types of applications that can be accessed on organizational', 'vec_doc-14-nist-sp-800-53-p80-282', 0, 235, 'v2.1.0', '340e65d253f3a4a5f8e61ab84c6c32e5e7d41f4920ba7e91ffbeb626476dc0fa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Process, store, or transmit organization-controlled information using external systems;","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":282,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Process, store, or transmit organization-controlled information using external systems;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p81-283', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 54', 81, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 systems from external systems and the highest security category of information that can be processed, stored, or transmitted on external systems. If the terms and conditions with the owners of the external systems cannot be established, organizations may impose restrictions on organizational personnel using those external systems. Related Controls:  AC-2, AC-3, AC-17, AC-19, CA-3, PL-2, PL-4, SA-9, SC-7.', 'vec_doc-14-nist-sp-800-53-p81-283', 0, 125, 'v2.1.0', '009a6577f646f12b964b6c06e7166bb24a230fefcc6ce0940d5d8075ef3b1eec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 54","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":283,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 54"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p81-284', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 54', 81, 'Control Enhancements: (1) USE OF EXTERNAL SYSTEMS | LIMITS ON AUTHORIZED USE Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after: (a) Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or (b) Retention of approved system connection or processing agreements with the organizational entity hosting the external system. Discussion:  Limiting authorized use recognizes circumstances where individuals using external systems may need to access organizational systems. Organizations need assurance that the external systems contain the necessary controls so as not to compromise, damage, or otherwise harm organizational systems.', 'vec_doc-14-nist-sp-800-53-p81-284', 0, 212, 'v2.1.0', '30f0a8a7ceeaee774fb026634f3f19becdd82179bfa65c4e620c129fdd62c62e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 54","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":284,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 54"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p81-285', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 54', 81, 'Verification that the required controls have been implemented can be achieved by external, independent assessments, attestations, or other means, depending on the confidence level required by organizations. Related Controls:  CA-2. (2) USE OF EXTERNAL SYSTEMS | PORTABLE STORAGE DEVICES —  RESTRICTED USE Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using [Assignment: organization-defined restrictions]. Discussion:  Limits on the use of organization-controlled portable storage devices in external systems include restrictions on how the devices may be used and under what conditions the devices may be used. Related Controls:  MP-7, SC-41. (3) USE OF EXTERNAL SYSTEMS | NON-ORGANIZATIONALLY OWNED SYSTEMS  —  RESTRICTED USE Restrict the use of non-organizationally owned systems or system components to process, store, or transmit organizational information using [Assignment: organization-defined restrictions].', 'vec_doc-14-nist-sp-800-53-p81-285', 0, 247, 'v2.1.0', 'c63ed70c4c10ff68d5dbeaf526812c0b82aab073230545abe42c3fdfb8435c6f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 54","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":285,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 54"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p81-286', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 54', 81, 'Discussion:  Non-organizationally owned systems or system components include systems or system components owned by other organizations as well as personally owned devices. There are potential risks to using non-organizationally owned systems or components. In some cases, the risk is sufficiently high as to prohibit such use (see AC-20 b.). In other cases, the use of such systems or system components may be allowed but restricted in some way. Restrictions include requiring the implementation of approved controls prior to authorizing the connection of non-organizationally owned systems and components; limiting access to types of information, services, or applications; using virtualization techniques to limit processing and storage activities to servers or system components provisioned by the organization; and agreeing to the terms and conditions for usage.', 'vec_doc-14-nist-sp-800-53-p81-286', 0, 217, 'v2.1.0', 'e3f9be9cc0b4a40b1e0ce210e7b49ea5ff750e542b03a3a9152b88ad4b6300e5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 54","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":286,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 54"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p81-287', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 54', 81, 'Organizations consult with the Office of the General Counsel regarding legal issues associated with using personally owned devices, including requirements for conducting forensic analyses during investigations after an incident. Related Controls:  None. (4) USE OF EXTERNAL SYSTEMS | NETWORK ACCESSIBLE STORAGE DEVICES —  PROHIBITED USE', 'vec_doc-14-nist-sp-800-53-p81-287', 0, 84, 'v2.1.0', 'e2d7e13bdd21c36d2cd5d62d9c9a64664e4e5460cbb85e7e9447973f4c261686', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 54","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":287,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 54"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p82-288', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 55', 82, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Prohibit the use of [Assignment: organization-defined network accessible storage devices] in external systems. Discussion:  Network-accessible storage devices in external systems include online storage devices in public, hybrid, or community cloud-based systems. Related Controls:  None. (5) USE OF EXTERNAL SYSTEMS | PORTABLE STORAGE DEVICES —  PROHIBITED USE Prohibit the use of organization-controlled portable storage devices by authorized individuals on external systems. Discussion:  Limits on the use of organization-controlled portable storage devices in external systems include a complete prohibition of the use of such devices. Prohibiting such use is enforced using technical methods and/or nontechnical (i.e., process-based) methods. Related Controls:  MP-7, PL-4, PS-6, SC-41. References:  [FIPS 199], [SP 800-171], [SP 800-172]. AC-21 INFORMATION SHARING Control: a.', 'vec_doc-14-nist-sp-800-53-p82-288', 0, 244, 'v2.1.0', '089e4fa172d95ba6c7edc28301043de3a71e4b22c9265f93734c049b1bf62e51', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 55","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":288,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 55"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p82-289', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 55', 82, 'Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for [Assignment: organization- defined information sharing circumstances where user discretion is required]; and b. Employ [Assignment: organization-defined automated mechanisms or manual processes] to assist users in making information sharing and collaboration decisions. Discussion:  Information sharing applies to information that may be restricted in some manner based on some formal or administrative determination. Examples of such information include, contract-sensitive information, classified information related to special access programs or compartments, privileged information, proprietary information, and personally identifiable information. Security and privacy risk assessments as well as applicable laws, regulations, and policies can provide useful inputs to these determinations.', 'vec_doc-14-nist-sp-800-53-p82-289', 0, 237, 'v2.1.0', 'ce9eed3f05a4f8b2dc1bfb9ef569ac07ec67a234ba220e6ce633201849ad5d36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 55","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":289,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 55"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p82-290', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 55', 82, 'Depending on the circumstances, sharing partners may be defined at the individual, group, or organizational level. Information may be defined by content, type, security category, or special access program or compartment. Access restrictions may include non-disclosure agreements (NDA). Information flow techniques and security attributes may be used to provide automated assistance to users making sharing and collaboration decisions. Related Controls:  AC-3, AC-4, AC-16, PT-2, PT-7, RA-3, SC-15. Control Enhancements: (1) INFORMATION SHARING | AUTOMATED DECISION SUPPORT Employ [Assignment: organization-defined automated mechanisms] to enforce information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared. Discussion:  Automated mechanisms are used to enforce information sharing decisions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p82-290', 0, 228, 'v2.1.0', 'f7364591126aaa0955b3927af405f24235f2f04f3b51fd848cffc7e34edcd607', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 55","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":290,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 55"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p82-291', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 55', 82, '(2) INFORMATION SHARING | INFORMATION SEARCH AND RETRIEVAL Implement information search and retrieval services that enforce [Assignment: organization-defined information sharing restrictions]. Discussion:  Information search and retrieval services identify information system resources relevant to an information need.', 'vec_doc-14-nist-sp-800-53-p82-291', 0, 80, 'v2.1.0', '8c34cb3f747f79201efa8a480491871f65ecb3188f49e870385c43b19af3e606', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 55","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":291,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 55"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p83-292', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 56', 83, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. References:  [OMB A-130], [SP 800-150], [IR 8062]. AC-22 PUBLICLY ACCESSIBLE CONTENT Control: a. Designate individuals authorized to make information publicly accessible; b. Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information; c. Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and d. Review the content on the publicly accessible system for nonpublic information [Assignment: organization-defined frequency] and remove such information, if discovered.', 'vec_doc-14-nist-sp-800-53-p83-292', 0, 184, 'v2.1.0', '40819c28f812916a33fa548d47b46329c1fb6c2ab2c0e05d3c4a3051e129869e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 56","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":292,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 56"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p83-293', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 56', 83, 'Discussion:  In accordance with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines, the public is not authorized to have access to nonpublic information, including information protected under the [PRIVACT] and proprietary information. Publicly accessible content addresses systems that are controlled by the organization and accessible to the public, typically without identification or authentication. Posting information on non- organizational systems (e.g., non-organizational public websites, forums, and social media) is covered by organizational policy. While organizations may have individuals who are responsible for developing and implementing policies about the information that can be made publicly accessible, publicly accessible content addresses the management of the individuals who make such information publicly accessible. Related Controls:  AC-3, AT-2, AT-3, AU-13. Control Enhancements:  None. References:  [PRIVACT].', 'vec_doc-14-nist-sp-800-53-p83-293', 0, 246, 'v2.1.0', '1628dca9c4155be6c3818974c754ea6f870272020877af008080da9e242f622c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 56","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":293,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 56"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p83-294', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 56', 83, 'AC-23 DATA MINING PROTECTION Control:  Employ [Assignment: organization-defined data mining prevention and detection techniques] for [Assignment: organization-defined data storage objects] to detect and protect against unauthorized data mining. Discussion:  Data mining is an analytical process that attempts to find correlations or patterns in large data sets for the purpose of data or knowledge discovery. Data storage objects include database records and database fields. Sensitive information can be extracted from data mining operations. When information is personally identifiable information, it may lead to unanticipated revelations about individuals and give rise to privacy risks. Prior to performing data mining activities, organizations determine whether such activities are authorized. Organizations may be subject to applicable laws, executive orders, directives, regulations, or policies that address data mining requirements.', 'vec_doc-14-nist-sp-800-53-p83-294', 0, 236, 'v2.1.0', 'c42b0752fc5b5632e1ad81956b5d162f666311a4a388f2fbfa882ecd5f2adebf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 56","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":294,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 56"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p83-295', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 56', 83, 'Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements. Data mining prevention and detection techniques include limiting the number and frequency of database queries to increase the work factor needed to determine the contents of databases, limiting types of responses provided to database queries, applying differential privacy techniques or homomorphic encryption, and notifying personnel when atypical database queries or accesses occur. Data mining protection focuses on protecting information from data mining while such information resides in organizational data stores. In contrast, AU-13 focuses on monitoring for organizational information that may have been mined or otherwise obtained from data stores', 'vec_doc-14-nist-sp-800-53-p83-295', 0, 195, 'v2.1.0', 'e8dc5e06d2ae1a6513da236f8740b33cd6e776976da0c0c71d6aba8f2b85d1d4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 56","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":295,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 56"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p84-296', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 57', 84, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and is available as open-source information residing on external sites, such as social networking or social media websites. [EO 13587] requires the establishment of an insider threat program for deterring, detecting, and mitigating insider threats, including the safeguarding of sensitive information from exploitation, compromise, or other unauthorized disclosure. Data mining protection requires organizations to identify appropriate techniques to prevent and detect unnecessary or unauthorized data mining. Data mining can be used by an insider to collect organizational information for the purpose of exfiltration. Related Controls:  PM-12, PT-2. Control Enhancements:  None. References:  [EO 13587].', 'vec_doc-14-nist-sp-800-53-p84-296', 0, 199, 'v2.1.0', '585faa9c626d7fd9900834159c5b15da1fe5a9c5dc761e7ad9c0e229228b9794', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 57","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":296,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 57"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p84-297', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 57', 84, 'AC-24 ACCESS CONTROL DECISIONS Control:  [Selection: Establish procedures; Implement mechanisms] to ensure [Assignment: organization-defined access control decisions] are applied to each access request prior to access enforcement. Discussion:  Access control decisions (also known as authorization decisions) occur when authorization information is applied to specific accesses. In contrast, access enforcement occurs when systems enforce access control decisions. While it is common to have access control decisions and access enforcement implemented by the same entity, it is not required, and it is not always an optimal implementation choice. For some architectures and distributed systems, different entities may make access control decisions and enforce access. Related Controls:  AC-2, AC-3.', 'vec_doc-14-nist-sp-800-53-p84-297', 0, 200, 'v2.1.0', 'a35f0dcedc222ad22e830ba3cc049a386f4feb5c058fda22b7faa21cd662b90d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 57","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":297,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 57"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p84-298', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 57', 84, 'Control Enhancements: (1) ACCESS CONTROL DECISIONS | TRANSMIT ACCESS AUTHORIZATION INFORMATION Transmit [Assignment: organization-defined access authorization information] using [Assignment: organization-defined controls] to [Assignment: organization-defined systems] that enforce access control decisions. Discussion:  Authorization processes and access control decisions may occur in separate parts of systems or in separate systems. In such instances, authorization information is transmitted securely (e.g., using cryptographic mechanisms) so that timely access control decisions can be enforced at the appropriate locations. To support the access control decisions, it may be necessary to transmit as part of the access authorization information supporting security and privacy attributes.', 'vec_doc-14-nist-sp-800-53-p84-298', 0, 199, 'v2.1.0', '603591a3e47ed3d9e166e8c8e9752830334b9da7e0869870e30884bfacf9eb74', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 57","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":298,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 57"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p84-299', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 57', 84, 'This is because in distributed systems, there are various access control decisions that need to be made, and different entities make these decisions in a serial fashion, each requiring those attributes to make the decisions. Protecting access authorization information ensures that such information cannot be altered, spoofed, or compromised during transmission. Related Controls:  AU-10. (2) ACCESS CONTROL DECISIONS | NO USER OR PROCESS IDENTITY Enforce access control decisions based on [Assignment: organization-defined security or privacy attributes] that do not include the identity of the user or process acting on behalf of the user. Discussion:  In certain situations, it is important that access control decisions can be made without information regarding the identity of the users issuing the requests. These are generally instances where preserving individual privacy is of paramount importance. In other', 'vec_doc-14-nist-sp-800-53-p84-299', 0, 229, 'v2.1.0', '5022705e89f0d101ba0057a5a5963c2df330c21d5f3f16d9090b0efdd2b40a4c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 57","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":299,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 57"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p85-300', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 58', 85, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 situations, user identification information is simply not needed for access control decisions, and especially in the case of distributed systems, transmitting such information with the needed degree of assurance may be very expensive or difficult to accomplish. MAC, RBAC, ABAC, and label-based control policies, for example, might not include user identity as an attribute. Related Controls:  None. References:  [SP 800-162], [SP 800-178]. AC-25 REFERENCE MONITOR Control:  Implement a reference monitor for [Assignment: organization-defined access control policies] that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.', 'vec_doc-14-nist-sp-800-53-p85-300', 0, 199, 'v2.1.0', '0f9920630858e42e343db7178a8f57d2033afca969c7009f96c063b5c94e4313', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 58","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":300,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 58"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p85-301', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 58', 85, 'Discussion:  A reference monitor is a set of design requirements on a reference validation mechanism that, as a key component of an operating system, enforces an access control policy over all subjects and objects. A reference validation mechanism is always invoked, tamper-proof, and small enough to be subject to analysis and tests, the completeness of which can be assured (i.e., verifiable). Information is represented internally within systems using abstractions known as data structures. Internal data structures can represent different types of entities, both active and passive. Active entities, also known as subjects, are associated with individuals, devices, or processes acting on behalf of individuals. Passive entities, also known as objects, are associated with data structures, such as records, buffers, communications ports, tables, files, and inter- process pipes.', 'vec_doc-14-nist-sp-800-53-p85-301', 0, 221, 'v2.1.0', '3b6f2e2cf76a55fa8406ee91a3bdd81553e42bbccbff23db84d94b6fbb754a6c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 58","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":301,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 58"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p85-302', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 58', 85, 'Reference monitors enforce access control policies that restrict access to objects based on the identity of subjects or groups to which the subjects belong. The system enforces the access control policy based on the rule set established by the policy. The tamper-proof property of the reference monitor prevents determined adversaries from compromising the functioning of the reference validation mechanism. The always invoked property prevents adversaries from bypassing the mechanism and violating the security policy. The smallness property helps to ensure completeness in the analysis and testing of the mechanism to detect any weaknesses or deficiencies (i.e., latent flaws) that would prevent the enforcement of the security policy. Related Controls:  AC-3, AC-16, SA-8, SA-17, SC-3, SC-11, SC-39, SI-13. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p85-302', 0, 215, 'v2.1.0', '48d6f3d122a8292c68e037d949f823428edda1be6c68aa59870f91db665cfa6d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 58","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":302,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 58"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p86-303', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.2   AWARENESS AND TRAINING', 86, 'Quick link to Awareness and Training Summary Table AT-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p86-303', 0, 46, 'v2.1.0', 'aabbb9d88cc09efa54c01971e5804609d590872c6ef1d17474c7b9a8319862df', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.2   AWARENESS AND TRAINING","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":303,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.2   AWARENESS AND TRAINING"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p86-304', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 86, 'level] awareness and training policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p86-304', 0, 77, 'v2.1.0', '72cf65048580d3acfa11038dafeacaa8d6f7a7875714d0ef7016f11968415ec0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":304,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p86-305', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the awareness and training policy and', 86, 'the associated awareness and training controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the awareness and training policy and procedures; and c. Review and update the current awareness and training:', 'vec_doc-14-nist-sp-800-53-p86-305', 0, 71, 'v2.1.0', 'fecbe9de1ee2e13e39edd10aa239621d1ddc11f5a05c4be1217749425fc17d6a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the awareness and training policy and","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":305,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the awareness and training policy and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p86-306', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 86, 'organization-defined events]. Discussion:  Awareness and training policy and procedures address the controls in the AT family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of awareness and training policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to awareness and training policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-50], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p86-306', 0, 435, 'v2.1.0', '9de5b1ef0ad0ff52e9b69aa40dbd360f39bcba667986423d4a95a31953ede71c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":306,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-307', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 60', 87, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 AT-2 LITERACY TRAINING AND AWARENESS Control: a. Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):', 'vec_doc-14-nist-sp-800-53-p87-307', 0, 66, 'v2.1.0', 'aa47c0da450690633e815851258334c0cd6a9e8eb4b5a6c58c9939a4a35f8f85', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 60","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":307,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 60"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-308', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. As part of initial training for new users and [Assignment: organization-defined', 87, 'frequency] thereafter; and', 'vec_doc-14-nist-sp-800-53-p87-308', 0, 7, 'v2.1.0', '894e9237500a125b42bd40bab33fe0e12959de2c4dc7f9f35fa5f49e82dd1df5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. As part of initial training for new users and [Assignment: organization-defined","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":308,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. As part of initial training for new users and [Assignment: organization-defined"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-309', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes or following [Assignment: organization-defined', 87, 'events]; b. Employ the following techniques to increase the security and privacy awareness of system users [Assignment: organization-defined awareness techniques]; c. Update literacy training and awareness content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and d. Incorporate lessons learned from internal or external security incidents or breaches into literacy training and awareness techniques. Discussion:  Organizations provide basic and advanced levels of literacy training to system users, including measures to test the knowledge level of users. Organizations determine the content of literacy training and awareness based on specific organizational requirements, the systems to which personnel have authorized access, and work environments (e.g., telework).', 'vec_doc-14-nist-sp-800-53-p87-309', 0, 207, 'v2.1.0', 'cad36c75be0bf60e9c08ff75ec7389866f036c6e19425140eb6adbcdccc1b596', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes or following [Assignment: organization-defined","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":309,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes or following [Assignment: organization-defined"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-310', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes or following [Assignment: organization-defined', 87, 'The content includes an understanding of the need for security and privacy as well as actions by users to maintain security and personal privacy and to respond to suspected incidents. The content addresses the need for operations security and the handling of personally identifiable information. Awareness techniques include displaying posters, offering supplies inscribed with security and privacy reminders, displaying logon screen messages, generating email advisories or notices from organizational officials, and conducting awareness events. Literacy training after the initial training described in AT-2a.1 is conducted at a minimum frequency consistent with applicable laws, directives, regulations, and policies.', 'vec_doc-14-nist-sp-800-53-p87-310', 0, 180, 'v2.1.0', 'f93c099984d2d9be91c54a0b957bc9194b5e2d1748409ccf0fa0b4733226e380', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes or following [Assignment: organization-defined","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":310,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes or following [Assignment: organization-defined"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-311', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes or following [Assignment: organization-defined', 87, 'Subsequent literacy training may be satisfied by one or more short ad hoc sessions and include topical information on recent attack schemes, changes to organizational security and privacy policies, revised security and privacy expectations, or a subset of topics from the initial training. Updating literacy training and awareness content on a regular basis helps to ensure that the content remains relevant. Events that may precipitate an update to literacy training and awareness content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  AC-3, AC-17, AC-22, AT-3, AT-4, CP-3, IA-4, IR-2, IR-7, IR-9, PL-4, PM-13, PM-21, PS-7, PT-2, SA-8, SA-16. Control Enhancements: (1) LITERACY TRAINING AND AWARENESS | PRACTICAL EXERCISES Provide practical exercises in literacy training that simulate events and incidents.', 'vec_doc-14-nist-sp-800-53-p87-311', 0, 247, 'v2.1.0', 'a3713d122632d90c6a9ab01e0f848490e06b16092845044ddb57e283b89568ff', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes or following [Assignment: organization-defined","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":311,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes or following [Assignment: organization-defined"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p87-312', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes or following [Assignment: organization-defined', 87, 'Discussion:  Practical exercises include no-notice social engineering attempts to collect information, gain unauthorized access, or simulate the adverse impact of opening malicious email attachments or invoking, via spear phishing attacks, malicious web links. Related Controls:  CA-2, CA-7, CP-4, IR-3. (2) LITERACY TRAINING AND AWARENESS | INSIDER THREAT Provide literacy training on recognizing and reporting potential indicators of insider threat.', 'vec_doc-14-nist-sp-800-53-p87-312', 0, 113, 'v2.1.0', 'e1c9054c907c7b91539283b134ea94511479829d16e68ae8f102fb0a4fc1bd80', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes or following [Assignment: organization-defined","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":312,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes or following [Assignment: organization-defined"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p88-313', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 61', 88, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Potential indicators and possible precursors of insider threat can include behaviors such as inordinate, long-term job dissatisfaction; attempts to gain access to information not required for job performance; unexplained access to financial resources; bullying or harassment of fellow employees; workplace violence; and other serious violations of policies, procedures, directives, regulations, rules, or practices. Literacy training includes how to communicate the concerns of employees and management regarding potential indicators of insider threat through channels established by the organization and in accordance with established policies and procedures. Organizations may consider tailoring insider threat awareness topics to the role.', 'vec_doc-14-nist-sp-800-53-p88-313', 0, 212, 'v2.1.0', '5d01974c50a0b98cc8f2e98ec6cd8a8694c0e5b215b90c470682d9e4feb7aa3e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 61","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":313,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 61"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p88-314', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 61', 88, 'For example, training for managers may be focused on changes in the behavior of team members, while training for employees may be focused on more general observations. Related Controls:  PM-12. (3) LITERACY TRAINING AND AWARENESS | SOCIAL ENGINEERING AND MINING Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining. Discussion:  Social engineering is an attempt to trick an individual into revealing information or taking an action that can be used to breach, compromise, or otherwise adversely impact a system. Social engineering includes phishing, pretexting, impersonation, baiting, quid pro quo, thread-jacking, social media exploitation, and tailgating. Social mining is an attempt to gather information about the organization that may be used to support future attacks.', 'vec_doc-14-nist-sp-800-53-p88-314', 0, 212, 'v2.1.0', '5f0fa2ef741cf3443160ef8f6cc32e753b32991e35b75ebea3a1d4b36eb7e3f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 61","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":314,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 61"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p88-315', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 61', 88, 'Literacy training includes information on how to communicate the concerns of employees and management regarding potential and actual instances of social engineering and data mining through organizational channels based on established policies and procedures. Related Controls:  None. (4) LITERACY TRAINING AND AWARENESS | SUSPICIOUS COMMUNICATIONS AND ANOMALOUS SYSTEM BEHAVIOR Provide literacy training on recognizing suspicious communications and anomalous behavior in organizational systems using [Assignment: organization-defined indicators of malicious code]. Discussion:  A well-trained workforce provides another organizational control that can be employed as part of a defense-in-depth strategy to protect against malicious code coming into organizations via email or the web applications.', 'vec_doc-14-nist-sp-800-53-p88-315', 0, 200, 'v2.1.0', 'e99bbbf5bbcba20087580d6928dcd81f3c57f8ea3c8bffd55237fd83e29208ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 61","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":315,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 61"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p88-316', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 61', 88, 'Personnel are trained to look for indications of potentially suspicious email (e.g., receiving an unexpected email, receiving an email containing strange or poor grammar, or receiving an email from an unfamiliar sender that appears to be from a known sponsor or contractor). Personnel are also trained on how to respond to suspicious email or web communications. For this process to work effectively, personnel are trained and made aware of what constitutes suspicious communications. Training personnel on how to recognize anomalous behaviors in systems can provide organizations with early warning for the presence of malicious code. Recognition of anomalous behavior by organizational personnel can supplement malicious code detection and protection tools and systems employed by organizations. Related Controls:  None. (5) LITERACY TRAINING AND AWARENESS | ADVANCED PERSISTENT THREAT Provide literacy training on the advanced persistent threat.', 'vec_doc-14-nist-sp-800-53-p88-316', 0, 237, 'v2.1.0', 'a7be91ac8abb43a4ac89e7ac4e7c21f66926a1be8674364842e007a4ae84dd46', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 61","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":316,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 61"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p88-317', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 61', 88, 'Discussion:  An effective way to detect advanced persistent threats (APT) and to preclude successful attacks is to provide specific literacy training for individuals. Threat literacy training includes educating individuals on the various ways that APTs can infiltrate the organization (e.g., through websites, emails, advertisement pop-ups, articles, and social', 'vec_doc-14-nist-sp-800-53-p88-317', 0, 91, 'v2.1.0', '508757e826c4016b8ce2fa54c87810fcb594c0cd19f2d092cc4245f29eba6eb2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 61","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":317,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 61"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p89-318', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 62', 89, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 engineering). Effective training includes techniques for recognizing suspicious emails, use of removable systems in non-secure settings, and the potential targeting of individuals at home. Related Controls:  None. (6) LITERACY TRAINING AND AWARENESS | CYBER THREAT ENVIRONMENT (a) Provide literacy training on the cyber threat environment; and (b) Reflect current cyber threat information in system operations. Discussion:  Since threats continue to change over time, threat literacy training by the organization is dynamic. Moreover, threat literacy training is not performed in isolation from the system operations that support organizational mission and business functions. Related Controls:  RA-3. References:  [OMB A-130], [SP 800-50], [SP 800-160-2], [SP 800-181], [ODNI CTF]. AT-3 ROLE-BASED TRAINING Control: a. Provide role-based security and privacy training to personnel with the following roles and responsibilities: [Assignment: organization-defined roles and responsibilities]:', 'vec_doc-14-nist-sp-800-53-p89-318', 0, 271, 'v2.1.0', '8a6873f27cf7f487533d84e9158bdf825b37534294410e42253d4f8a41bd84f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 62","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":318,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 62"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p89-319', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Before authorizing access to the system, information, or performing assigned duties,', 89, 'and [Assignment: organization-defined frequency] thereafter; and', 'vec_doc-14-nist-sp-800-53-p89-319', 0, 16, 'v2.1.0', '5a23ce6b677fd115a648dde10b3c2491b778c272bba730debd04b795ebf45343', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Before authorizing access to the system, information, or performing assigned duties,","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":319,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Before authorizing access to the system, information, or performing assigned duties,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p89-320', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes;', 89, 'b. Update role-based training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and c. Incorporate lessons learned from internal or external security incidents or breaches into role-based training. Discussion:  Organizations determine the content of training based on the assigned roles and responsibilities of individuals as well as the security and privacy requirements of organizations and the systems to which personnel have authorized access, including technical training specifically tailored for assigned duties.', 'vec_doc-14-nist-sp-800-53-p89-320', 0, 145, 'v2.1.0', '3cc5e35d4a8831e4d2dc35d0ce184532e4d715a6220f733a9fd2861cc73dfb5c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes;","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":320,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p89-321', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes;', 89, 'Roles that may require role-based training include senior leaders or management officials (e.g., head of agency/chief executive officer, chief information officer, senior accountable official for risk management, senior agency information security officer, senior agency official for privacy), system owners; authorizing officials; system security officers; privacy officers; acquisition and procurement officials; enterprise architects; systems engineers; software developers; systems security engineers; privacy engineers; system, network, and database administrators; auditors; personnel conducting configuration management activities; personnel performing verification and validation activities; personnel with access to system-level software; control assessors; personnel with contingency planning and incident response duties; personnel with privacy management responsibilities; and personnel with access to personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p89-321', 0, 238, 'v2.1.0', 'f7b8fa95f6f2e75a270bd9b14dda5d1daa07a4a9b518191dd77715441f90f341', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes;","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":321,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p89-322', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. When required by system changes;', 89, 'Comprehensive role-based training addresses management, operational, and technical roles and responsibilities covering physical, personnel, and technical controls. Role-based training also includes policies, procedures, tools, methods, and artifacts for the security and privacy roles defined. Organizations provide the training necessary for individuals to fulfill their responsibilities related to operations and supply chain risk management within the context of organizational security and privacy programs. Role-based training also applies to contractors who provide services to federal agencies. Types of training include web-based and computer-based training, classroom-style training, and hands-on training (including micro-training). Updating role-based', 'vec_doc-14-nist-sp-800-53-p89-322', 0, 191, 'v2.1.0', '66572912d1a9d075cdc01bf7a45b3f5356afdadf143158d63f6177f7e6f5f53a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. When required by system changes;","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":322,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. When required by system changes;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p90-323', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 63', 90, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 training on a regular basis helps to ensure that the content remains relevant and effective. Events that may precipitate an update to role-based training content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  AC-3, AC-17, AC-22, AT-2, AT-4, CP-3, IR-2, IR-4, IR-7, IR-9, PL-4, PM-13, PM-23, PS-7, PS-9, SA-3, SA-8, SA-11, SA-16, SR-5, SR-6, SR-11. Control Enhancements: (1) ROLE-BASED TRAINING | ENVIRONMENTAL CONTROLS Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of environmental controls.', 'vec_doc-14-nist-sp-800-53-p90-323', 0, 220, 'v2.1.0', '98d305a7d55c7107ab549c54b434048f409aa6a831d3e0303152c0c71ddf9bfb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 63","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":323,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 63"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p90-324', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 63', 90, 'Discussion:  Environmental controls include fire suppression and detection devices or systems, sprinkler systems, handheld fire extinguishers, fixed fire hoses, smoke detectors, temperature or humidity, heating, ventilation, air conditioning, and power within the facility. Related Controls:  PE-1, PE-11, PE-13, PE-14, PE-15. (2) ROLE-BASED TRAINING | PHYSICAL SECURITY CONTROLS Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of physical security controls. Discussion:  Physical security controls include physical access control devices, physical intrusion and detection alarms, operating procedures for facility security guards, and monitoring or surveillance equipment. Related Controls:  PE-2, PE-3, PE-4. (3) ROLE-BASED TRAINING | PRACTICAL EXERCISES Provide practical exercises in security and privacy training that reinforce training objectives.', 'vec_doc-14-nist-sp-800-53-p90-324', 0, 243, 'v2.1.0', '86c06370eac87ab6ae05d7e17c0f5a3863df0bf77914b6104d5c43ca874c921d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 63","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":324,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 63"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p90-325', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 63', 90, 'Discussion:  Practical exercises for security include training for software developers that addresses simulated attacks that exploit common software vulnerabilities or spear or whale phishing attacks targeted at senior leaders or executives. Practical exercises for privacy include modules with quizzes on identifying and processing personally identifiable information in various scenarios or scenarios on conducting privacy impact assessments. Related Controls:  None. (4) ROLE-BASED TRAINING | SUSPICIOUS COMMUNICATIONS AND ANOMALOUS SYSTEM BEHAVIOR [Withdrawn: Moved to AT-2(4)]. (5) ROLE-BASED TRAINING | PROCESSING PERSONALLY IDENTIFIABLE INFORMATION Provide [Assignment: organization-defined personnel or roles] with initial and [Assignment: organization-defined frequency] training in the employment and operation of personally identifiable information processing and transparency controls.', 'vec_doc-14-nist-sp-800-53-p90-325', 0, 225, 'v2.1.0', '62fb4e3749c7b093df511cafea9ba5812a84b63632f1a1f21534de8e4cb39563', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 63","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":325,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 63"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p90-326', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 63', 90, 'Discussion:  Personally identifiable information processing and transparency controls include the organization’s authority to process personally identifiable information and personally identifiable information processing purposes. Role-based training for federal agencies addresses the types of information that may constitute personally identifiable information and the risks, considerations, and obligations associated with its processing. Such training also considers the authority to process personally identifiable information documented in privacy policies and notices, system of records notices, computer matching agreements and', 'vec_doc-14-nist-sp-800-53-p90-326', 0, 159, 'v2.1.0', '9ce106e6c9d353549244a06ac49f2a77b5a8d1071147c0de23fffefdb7afde7b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 63","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":326,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 63"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p91-327', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 64', 91, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 notices, privacy impact assessments, [PRIVACT] statements, contracts, information sharing agreements, memoranda of understanding, and/or other documentation. Related Controls:  PT-2, PT-3, PT-5, PT-6. References:  [OMB A-130], [SP 800-50], [SP 800-181]. AT-4 TRAINING RECORDS Control: a. Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training; and b. Retain individual training records for [Assignment: organization-defined time period]. Discussion:  Documentation for specialized training may be maintained by individual supervisors at the discretion of the organization. The National Archives and Records Administration provides guidance on records retention for federal agencies. Related Controls:  AT-2, AT-3, CP-3, IR-2, PM-14, SI-12. Control Enhancements:  None. References:  [OMB A-130].', 'vec_doc-14-nist-sp-800-53-p91-327', 0, 253, 'v2.1.0', '30721f2b1ba5353b7dd4f35e41db1385766a6c49c29cf110db0fafbb78dc2c5f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 64","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":327,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 64"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p91-328', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 64', 91, 'AT-5 CONTACTS WITH SECURITY GROUPS AND ASSOCIATIONS [Withdrawn: Incorporated into PM-15.] AT-6 TRAINING FEEDBACK Control:  Provide feedback on organizational training results to the following personnel [Assignment: organization-defined frequency]: [Assignment: organization-defined personnel]. Discussion:  Training feedback includes awareness training results and role-based training results. Training results, especially failures of personnel in critical roles, can be indicative of a potentially serious problem. Therefore, it is important that senior managers are made aware of such situations so that they can take appropriate response actions. Training feedback supports the evaluation and update of organizational training described in AT-2b and AT-3b. Related Controls:  None. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p91-328', 0, 208, 'v2.1.0', '311eebd647729e55d8bea59ff4e99ee5f67da893b3f7ac9a7783b704bb206199', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 64","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":328,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 64"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p92-329', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.3   AUDIT AND ACCOUNTABILITY', 92, 'Quick link to Audit and Accountability Summary Table AU-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p92-329', 0, 46, 'v2.1.0', 'bdfa7a9ef3565462f2aa3d82b0c8921199dc477726899b9d407145a273e3b6f5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.3   AUDIT AND ACCOUNTABILITY","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":329,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.3   AUDIT AND ACCOUNTABILITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p92-330', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 92, 'level] audit and accountability policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p92-330', 0, 78, 'v2.1.0', '140b9662db04ecdbb4968cf6cee176883743845d3f3e8bef03bc395d324db476', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":330,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p92-331', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the audit and accountability policy and', 92, 'the associated audit and accountability controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the audit and accountability policy and procedures; and c. Review and update the current audit and accountability:', 'vec_doc-14-nist-sp-800-53-p92-331', 0, 72, 'v2.1.0', 'e76eef0679204500868981b493a79a298eef6a60cd7373fd2967f164b18d31da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the audit and accountability policy and","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":331,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the audit and accountability policy and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p92-332', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 92, 'organization-defined events]. Discussion:  Audit and accountability policy and procedures address the controls in the AU family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of audit and accountability policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to audit and accountability policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p92-332', 0, 430, 'v2.1.0', '0f0c2b0298d6d82a9a28a63de7d65e4ff85471efeef21a8559a0b214da9b689f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":332,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p93-333', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 66', 93, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 AU-2 EVENT LOGGING Control: a. Identify the types of events that the system is capable of logging in support of the audit function: [Assignment: organization-defined event types that the system is capable of logging]; b. Coordinate the event logging function with other organizational entities requiring audit- related information to guide and inform the selection criteria for events to be logged; c. Specify the following event types for logging within the system: [Assignment: organization- defined event types (subset of the event types defined in AU-2a.) along with the frequency of (or situation requiring) logging for each identified event type]; d. Provide a rationale for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents; and e. Review and update the event types selected for logging [Assignment: organization-defined frequency].', 'vec_doc-14-nist-sp-800-53-p93-333', 0, 251, 'v2.1.0', '860772f9dfce9c4d6deac7803924aee791e71a87d4bc4850086fb52b919de143', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 66","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":333,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 66"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p93-334', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 66', 93, 'Discussion:  An event is an observable occurrence in a system. The types of events that require logging are those events that are significant and relevant to the security of systems and the privacy of individuals. Event logging also supports specific monitoring and auditing needs. Event types include password changes, failed logons or failed accesses related to systems, security or privacy attribute changes, administrative privilege usage, PIV credential usage, data action changes, query parameters, or external credential usage. In determining the set of event types that require logging, organizations consider the monitoring and auditing appropriate for each of the controls to be implemented. For completeness, event logging includes all protocols that are operational and supported by the system. To balance monitoring and auditing requirements with other system needs, event logging requires identifying the subset of event types that are logged at a given point in time.', 'vec_doc-14-nist-sp-800-53-p93-334', 0, 246, 'v2.1.0', 'e251d642895eb4f8bd6220238de6f4de5b89c0b8690546f36574357f928b0a2e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 66","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":334,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 66"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p93-335', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 66', 93, 'For example, organizations may determine that systems need the capability to log every file access successful and unsuccessful, but not activate that capability except for specific circumstances due to the potential burden on system performance. The types of events that organizations desire to be logged may change. Reviewing and updating the set of logged events is necessary to help ensure that the events remain relevant and continue to support the needs of the organization. Organizations consider how the types of logging events can reveal information about individuals that may give rise to privacy risk and how best to mitigate such risks. For example, there is the potential to reveal personally identifiable information in the audit trail, especially if the logging event is based on patterns or time of usage. Event logging requirements, including the need to log specific event types, may be referenced in other controls and control enhancements.', 'vec_doc-14-nist-sp-800-53-p93-335', 0, 240, 'v2.1.0', '0e9419889115cde5c45985a1875738f1ac56c06f125b7c35c3612b2bbf50ff80', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 66","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":335,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 66"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p93-336', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 66', 93, 'These include AC-2(4), AC-3(10), AC-6(9), AC-17(1), CM-3f, CM-5(1), IA-3(3.b), MA-4(1), MP-4(2), PE-3, PM-21, PT-7, RA-8, SC-7(9), SC-7(15), SI-3(8), SI-4(22), SI-7(8), and SI-10(1). Organizations include event types that are required by applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Audit records can be generated at various levels, including at the packet level as information traverses the network. Selecting the appropriate level of event logging is an important part of a monitoring and auditing capability and can identify the root causes of problems. When defining event types, organizations consider the logging necessary to cover related event types, such as the steps in distributed, transaction-based processes and the actions that occur in service-oriented architectures.', 'vec_doc-14-nist-sp-800-53-p93-336', 0, 209, 'v2.1.0', '5f53a34f20647edc3e6c8f6b7200e49e4b99c2dd53cf16132a5de98f72dd00a9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 66","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":336,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 66"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p93-337', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 66', 93, 'Related Controls:  AC-2, AC-3, AC-6, AC-7, AC-8, AC-16, AC-17, AU-3, AU-4, AU-5, AU-6, AU-7, AU- 11, AU-12, CM-3, CM-5, CM-6, CM-13, IA-3, MA-4, MP-4, PE-3, PM-21, PT-2, PT-7, RA-8, SA-8, SC- 7, SC-18, SI-3, SI-4, SI-7, SI-10, SI-11.', 'vec_doc-14-nist-sp-800-53-p93-337', 0, 59, 'v2.1.0', 'e6c1a1ac2318cdd58c1920319e9221389d90193ba965fa7a3fb4b69c2408f6c1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 66","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":337,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 66"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p94-338', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 67', 94, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) EVENT LOGGING | COMPILATION OF AUDIT RECORDS FROM MULTIPLE SOURCES [Withdrawn: Incorporated into AU-12.] (2) EVENT LOGGING | SELECTION OF AUDIT EVENTS BY COMPONENT [Withdrawn: Incorporated into AU-12.] (3) EVENT LOGGING | REVIEWS AND UPDATES [Withdrawn: Incorporated into AU-2.] (4) EVENT LOGGING | PRIVILEGED FUNCTIONS [Withdrawn: Incorporated into AC-6(9).] References:  [OMB A-130], [SP 800-92]. AU-3 CONTENT OF AUDIT RECORDS Control:  Ensure that audit records contain information that establishes the following: a. What type of event occurred; b. When the event occurred; c. Where the event occurred; d. Source of the event; e. Outcome of the event; and f. Identity of any individuals, subjects, or objects/entities associated with the event.', 'vec_doc-14-nist-sp-800-53-p94-338', 0, 217, 'v2.1.0', '0bb03c993ec599c1b2690986d24dc047d1d12cb437be97145ae3fa533314036d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 67","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":338,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 67"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p94-339', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 67', 94, 'Discussion:  Audit record content that may be necessary to support the auditing function includes event descriptions (item a), time stamps (item b), source and destination addresses (item c), user or process identifiers (items d and f), success or fail indications (item e), and filenames involved (items a, c, e, and f) . Event outcomes include indicators of event success or failure and event-specific results, such as the system security and privacy posture after the event occurred. Organizations consider how audit records can reveal information about individuals that may give rise to privacy risks and how best to mitigate such risks. For example, there is the potential to reveal personally identifiable information in the audit trail, especially if the trail records inputs or is based on patterns or time of usage. Related Controls:  AU-2, AU-8, AU-12, AU-14, MA-4, PL-9, SA-8, SI-7, SI-11.', 'vec_doc-14-nist-sp-800-53-p94-339', 0, 225, 'v2.1.0', '6a43320952960c911c65d688a38c1ef52f9ad2811d41838bff307421f0ebb045', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 67","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":339,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 67"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p94-340', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 67', 94, 'Control Enhancements: (1) CONTENT OF AUDIT RECORDS | ADDITIONAL AUDIT INFORMATION Generate audit records containing the following additional information: [Assignment: organization-defined additional information]. Discussion:  The ability to add information generated in audit records is dependent on system functionality to configure the audit record content. Organizations may consider additional information in audit records including, but not limited to, access control or flow control rules invoked and individual identities of group account users. Organizations may also consider limiting additional audit record information to only information that is explicitly needed for audit requirements. This facilitates the use of audit trails and audit logs by not including information in audit records that could potentially be misleading, make it more difficult to locate information of interest, or increase the risk to individuals'' privacy. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p94-340', 0, 242, 'v2.1.0', '88222f189e2e7ab1a89da90c687217f4b85f95cddcad1922432a747a57906e50', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 67","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":340,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 67"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p95-341', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 68', 95, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (2) CONTENT OF AUDIT RECORDS | CENTRALIZED MANAGEMENT OF PLANNED AUDIT RECORD CONTENT [Withdrawn: Incorporated into PL-9.] (3) CONTENT OF AUDIT RECORDS | LIMIT PERSONALLY IDENTIFIABLE INFORMATION ELEMENTS Limit personally identifiable information contained in audit records to the following elements identified in the privacy risk assessment: [Assignment: organization-defined elements]. Discussion:  Limiting personally identifiable information in audit records when such information is not needed for operational purposes helps reduce the level of privacy risk created by a system. Related Controls:  RA-3. References:  [OMB A-130], [IR 8062]. AU-4 AUDIT LOG STORAGE CAPACITY Control:  Allocate audit log storage capacity to accommodate [Assignment: organization-defined audit log retention requirements].', 'vec_doc-14-nist-sp-800-53-p95-341', 0, 225, 'v2.1.0', '78a4e165feef1d17d3bd28de4604e6fc0b4561a2f5db5eb8023dd4bbb429c24a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 68","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":341,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 68"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p95-342', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 68', 95, 'Discussion:  Organizations consider the types of audit logging to be performed and the audit log processing requirements when allocating audit log storage capacity. Allocating sufficient audit log storage capacity reduces the likelihood of such capacity being exceeded and resulting in the potential loss or reduction of audit logging capability. Related Controls:  AU-2, AU-5, AU-6, AU-7, AU-9, AU-11, AU-12, AU-14, SI-4. Control Enhancements: (1) AUDIT LOG STORAGE CAPACITY | TRANSFER TO ALTERNATE STORAGE Transfer audit logs [Assignment: organization-defined frequency] to a different system, system component, or media other than the system or system component conducting the logging. Discussion:  Audit log transfer, also known as off-loading, is a common process in systems with limited audit log storage capacity and thus supports availability of the audit logs.', 'vec_doc-14-nist-sp-800-53-p95-342', 0, 218, 'v2.1.0', '72b21a3db0de4d9ece25843d4055e6353d3ad897736a752941a5b6d29064b59a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 68","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":342,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 68"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p95-343', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 68', 95, 'The initial audit log storage is only used in a transitory fashion until the system can communicate with the secondary or alternate system allocated to audit log storage, at which point the audit logs are transferred. Transferring audit logs to alternate storage is similar to AU-9(2) in that audit logs are transferred to a different entity. However, the purpose of selecting AU- 9(2) is to protect the confidentiality and integrity of audit records. Organizations can select either control enhancement to obtain the benefit of increased audit log storage capacity and preserving the confidentiality, integrity, and availability of audit records and logs. Related Controls:  None. References:  None. AU-5 RESPONSE TO AUDIT LOGGING PROCESS FAILURES Control: a. Alert [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] in the event of an audit logging process failure; and b.', 'vec_doc-14-nist-sp-800-53-p95-343', 0, 233, 'v2.1.0', '38a378a76722aedd05829574834e62c13ada8c8be077684866844973debefaf4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 68","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":343,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 68"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p95-344', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 68', 95, 'Take the following additional actions: [Assignment: organization-defined additional actions]. Discussion:  Audit logging process failures include software and hardware errors, failures in audit log capturing mechanisms, and reaching or exceeding audit log storage capacity. Organization- defined actions include overwriting oldest audit records, shutting down the system, and stopping', 'vec_doc-14-nist-sp-800-53-p95-344', 0, 96, 'v2.1.0', 'd771087a112033ebd5d973bd6dd3f5026b45dd2749b6fed2d8e74b38ac92e008', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 68","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":344,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 68"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p96-345', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 69', 96, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 the generation of audit records. Organizations may choose to define additional actions for audit logging process failures based on the type of failure, the location of the failure, the severity of the failure, or a combination of such factors. When the audit logging process failure is related to storage, the response is carried out for the audit log storage repository (i.e., the distinct system component where the audit logs are stored), the system on which the audit logs reside, the total audit log storage capacity of the organization (i.e., all audit log storage repositories combined), or all three. Organizations may decide to take no additional actions after alerting designated roles or personnel. Related Controls:  AU-2, AU-4, AU-7, AU-9, AU-11, AU-12, AU-14, SI-4, SI-12.', 'vec_doc-14-nist-sp-800-53-p96-345', 0, 220, 'v2.1.0', '915008a036eb0b23993917ffa169ffd88f1245b7a2ccaa93ca2190f27e4476b2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 69","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":345,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 69"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p96-346', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 69', 96, 'Control Enhancements: (1) RESPONSE TO AUDIT LOGGING PROCESS FAILURES | STORAGE CAPACITY WARNING Provide a warning to [Assignment: organization-defined personnel, roles, and/or locations] within [Assignment: organization-defined time period] when allocated audit log storage volume reaches [Assignment: organization-defined percentage] of repository maximum audit log storage capacity. Discussion:  Organizations may have multiple audit log storage repositories distributed across multiple system components with each repository having different storage volume capacities. Related Controls:  None. (2) RESPONSE TO AUDIT LOGGING PROCESS FAILURES | REAL-TIME ALERTS Provide an alert within [Assignment: organization-defined real-time period] to [Assignment: organization-defined personnel, roles, and/or locations] when the following audit failure events occur: [Assignment: organization-defined audit logging failure events requiring real-time alerts].', 'vec_doc-14-nist-sp-800-53-p96-346', 0, 238, 'v2.1.0', 'a746e9e6cf4ef7b1b5761a521e942af7302eb34a5e0665df40fd98cc9f1f32a5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 69","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":346,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 69"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p96-347', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 69', 96, 'Discussion:  Alerts provide organizations with urgent messages. Real-time alerts provide these messages at information technology speed (i.e., the time from event detection to alert occurs in seconds or less). Related Controls:  None. (3) RESPONSE TO AUDIT LOGGING PROCESS FAILURES | CONFIGURABLE TRAFFIC VOLUME THRESHOLDS Enforce configurable network communications traffic volume thresholds reflecting limits on audit log storage capacity and [Selection: reject; delay] network traffic above those thresholds. Discussion:  Organizations have the capability to reject or delay the processing of network communications traffic if audit logging information about such traffic is determined to exceed the storage capacity of the system audit logging function. The rejection or delay response is triggered by the established organizational traffic volume thresholds that can be adjusted based on changes to audit log storage capacity. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p96-347', 0, 239, 'v2.1.0', '3b626ce2b6c18ab50755d0de2bf827cbe62b793d7ae1be77a014c9fa0df2de99', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 69","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":347,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 69"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p96-348', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 69', 96, '(4) RESPONSE TO AUDIT LOGGING PROCESS FAILURES | SHUTDOWN ON FAILURE Invoke a [Selection: full system shutdown; partial system shutdown; degraded operational mode with limited mission or business functionality available] in the event of [Assignment: organization-defined audit logging failures], unless an alternate audit logging capability exists. Discussion:  Organizations determine the types of audit logging failures that can trigger automatic system shutdowns or degraded operations. Because of the importance of ensuring mission and business continuity, organizations may determine that the nature of the audit logging failure is not so severe that it warrants a complete shutdown of the system', 'vec_doc-14-nist-sp-800-53-p96-348', 0, 176, 'v2.1.0', 'ff4009971de5e476e6a41a0bdf18ce84240b03e8099993507485a08767e81c14', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 69","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":348,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 69"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p97-349', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 70', 97, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 supporting the core organizational mission and business functions. In those instances, partial system shutdowns or operating in a degraded mode with reduced capability may be viable alternatives. Related Controls:  AU-15. (5) RESPONSE TO AUDIT LOGGING PROCESS FAILURES | ALTERNATE AUDIT LOGGING CAPABILITY Provide an alternate audit logging capability in the event of a failure in primary audit logging capability that implements [Assignment: organization-defined alternate audit logging functionality]. Discussion:  Since an alternate audit logging capability may be a short-term protection solution employed until the failure in the primary audit logging capability is corrected, organizations may determine that the alternate audit logging capability need only provide a subset of the primary audit logging functionality that is impacted by the failure. Related Controls:  AU-9. References:  None.', 'vec_doc-14-nist-sp-800-53-p97-349', 0, 248, 'v2.1.0', '5285417f69727ecbb9f717ed45c8a068f82a24da697f7b8f41ba2e6efc8b21b6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 70","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":349,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 70"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p97-350', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 70', 97, 'AU-6 AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING Control: a. Review and analyze system audit records [Assignment: organization-defined frequency] for indications of [Assignment: organization-defined inappropriate or unusual activity] and the potential impact of the inappropriate or unusual activity; b. Report findings to [Assignment: organization-defined personnel or roles]; and c. Adjust the level of audit record review, analysis, and reporting within the system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.', 'vec_doc-14-nist-sp-800-53-p97-350', 0, 152, 'v2.1.0', 'f99a419579619ebcb5fa2874c9d9b32d31062304be641b01d71446d04c103a0a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 70","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":350,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 70"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p97-351', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 70', 97, 'Discussion:  Audit record review, analysis, and reporting covers information security- and privacy- related logging performed by organizations, including logging that results from the monitoring of account usage, remote access, wireless connectivity, mobile device connection, configuration settings, system component inventory, use of maintenance tools and non-local maintenance, physical access, temperature and humidity, equipment delivery and removal, communications at system interfaces, and use of mobile code or Voice over Internet Protocol (VoIP). Findings can be reported to organizational entities that include the incident response team, help desk, and security or privacy offices. If organizations are prohibited from reviewing and analyzing audit records or unable to conduct such activities, the review or analysis may be carried out by other organizations granted such authority.', 'vec_doc-14-nist-sp-800-53-p97-351', 0, 224, 'v2.1.0', '48b85f7f44416ce6dba93b2a3327c0fd4b42f1f850556e8575115a6665d32ef3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 70","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":351,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 70"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p97-352', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 70', 97, 'The frequency, scope, and/or depth of the audit record review, analysis, and reporting may be adjusted to meet organizational needs based on new information received. Related Controls:  AC-2, AC-3, AC-5, AC-6, AC-7, AC-17, AU-7, AU-16, CA-2, CA-7, CM-2, CM-5, CM-6, CM-10, CM-11, IA-2, IA-3, IA-5, IA-8, IR-5, MA-4, MP-4, PE-3, PE-6, RA-5, SA-8, SC-7, SI-3, SI-4, SI-7. Control Enhancements: (1) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | AUTOMATED PROCESS INTEGRATION Integrate audit record review, analysis, and reporting processes using [Assignment: organization-defined automated mechanisms]. Discussion:  Organizational processes that benefit from integrated audit record review, analysis, and reporting include incident response, continuous monitoring, contingency planning, investigation and response to suspicious activities, and Inspector General audits.', 'vec_doc-14-nist-sp-800-53-p97-352', 0, 217, 'v2.1.0', 'c148ce5c43377bdc707ad29443996811f92ce60b0947b0c404b6e71bed039544', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 70","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":352,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 70"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p98-353', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 71', 98, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  PM-7. (2) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | AUTOMATED SECURITY ALERTS [Withdrawn: Incorporated into SI-4.] (3) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CORRELATE AUDIT RECORD REPOSITORIES Analyze and correlate audit records across different repositories to gain organization-wide situational awareness. Discussion:  Organization-wide situational awareness includes awareness across all three levels of risk management (i.e., organizational level, mission/business process level, and information system level) and supports cross-organization awareness. Related Controls:  AU-12, IR-4. (4) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CENTRAL REVIEW AND ANALYSIS Provide and implement the capability to centrally review and analyze audit records from multiple components within the system.', 'vec_doc-14-nist-sp-800-53-p98-353', 0, 230, 'v2.1.0', '6782e2f1ad3682cbe8f52f620e0d6cd86bf9d2beac9b403598675966a517b403', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 71","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":353,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 71"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p98-354', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 71', 98, 'Discussion:  Automated mechanisms for centralized reviews and analyses include Security Information and Event Management products. Related Controls:  AU-2, AU-12. (5) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | INTEGRATED ANALYSIS OF AUDIT RECORDS Integrate analysis of audit records with analysis of [Selection (one or more): vulnerability scanning information; performance data; system monitoring information; [Assignment: organization-defined data/information collected from other sources]] to further enhance the ability to identify inappropriate or unusual activity. Discussion:  Integrated analysis of audit records does not require vulnerability scanning, the generation of performance data, or system monitoring. Rather, integrated analysis requires that the analysis of information generated by scanning, monitoring, or other data collection activities is integrated with the analysis of audit record information.', 'vec_doc-14-nist-sp-800-53-p98-354', 0, 232, 'v2.1.0', '4b7fd118f6f4d958ad84b29a237a7c5764bd27dd3a45149972d947110c16b2f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 71","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":354,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 71"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p98-355', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 71', 98, 'Security Information and Event Management tools can facilitate audit record aggregation or consolidation from multiple system components as well as audit record correlation and analysis. The use of standardized audit record analysis scripts developed by organizations (with localized script adjustments, as necessary) provides more cost-effective approaches for analyzing audit record information collected. The correlation of audit record information with vulnerability scanning information is important in determining the veracity of vulnerability scans of the system and in correlating attack detection events with scanning results. Correlation with performance data can uncover denial-of-service attacks or other types of attacks that result in the unauthorized use of resources. Correlation with system monitoring information can assist in uncovering attacks and in better relating audit information to operational situations. Related Controls:  AU-12, IR-4.', 'vec_doc-14-nist-sp-800-53-p98-355', 0, 241, 'v2.1.0', '3c478f648c9a47d80497e4ecb02c6e8e42323df710f87d2eced10bd73699cd6c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 71","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":355,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 71"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p98-356', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 71', 98, '(6) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CORRELATION WITH PHYSICAL MONITORING Correlate information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity. Discussion:  The correlation of physical audit record information and the audit records from systems may assist organizations in identifying suspicious behavior or supporting evidence of such behavior. For example, the correlation of an individual’s identity for logical access to certain systems with the additional physical security information that the individual was present at the facility when the logical access occurred may be useful in investigations. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p98-356', 0, 194, 'v2.1.0', '9a55b22f39950be8325ba779a0ecfea85a281c5cc62c46ef0427dbd565a7b861', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 71","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":356,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 71"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p99-357', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 72', 99, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (7) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | PERMITTED ACTIONS Specify the permitted actions for each [Selection (one or more): system process; role; user] associated with the review, analysis, and reporting of audit record information. Discussion:  Organizations specify permitted actions for system processes, roles, and users associated with the review, analysis, and reporting of audit records through system account management activities. Specifying permitted actions on audit record information is a way to enforce the principle of least privilege. Permitted actions are enforced by the system and include read, write, execute, append, and delete. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p99-357', 0, 194, 'v2.1.0', 'f9444f012e50fc333e8747e241c1f78cfff9a2d49b8c5b645261dd364bf3e0d7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 72","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":357,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 72"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p99-358', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 72', 99, '(8) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | FULL TEXT ANALYSIS OF PRIVILEGED COMMANDS Perform a full text analysis of logged privileged commands in a physically distinct component or subsystem of the system, or other system that is dedicated to that analysis. Discussion:  Full text analysis of privileged commands requires a distinct environment for the analysis of audit record information related to privileged users without compromising such information on the system where the users have elevated privileges, including the capability to execute privileged commands. Full text analysis refers to analysis that considers the full text of privileged commands (i.e., commands and parameters) as opposed to analysis that considers only the name of the command. Full text analysis includes the use of pattern matching and heuristics. Related Controls:  AU-3, AU-9, AU-11, AU-12.', 'vec_doc-14-nist-sp-800-53-p99-358', 0, 221, 'v2.1.0', 'd448d49e69df17e080492d4f9766aabc719d5c6bbed1131fd7cb06706d38d8e5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 72","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":358,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 72"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p99-359', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 72', 99, '(9) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | CORRELATION WITH INFORMATION FROM NONTECHNICAL SOURCES Correlate information from nontechnical sources with audit record information to enhance organization-wide situational awareness. Discussion:  Nontechnical sources include records that document organizational policy violations related to harassment incidents and the improper use of information assets. Such information can lead to a directed analytical effort to detect potential malicious insider activity. Organizations limit access to information that is available from nontechnical sources due to its sensitive nature. Limited access minimizes the potential for inadvertent release of privacy-related information to individuals who do not have a need to know. The correlation of information from nontechnical sources with audit record information generally occurs only when individuals are suspected of being involved in an incident.', 'vec_doc-14-nist-sp-800-53-p99-359', 0, 236, 'v2.1.0', '9eee11a0e5ad96aba750577507989055394013591757c366c3c51ff22bea1428', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 72","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":359,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 72"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p99-360', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 72', 99, 'Organizations obtain legal advice prior to initiating such actions. Related Controls:  PM-12. (10) AUDIT RECORD REVIEW, ANALYSIS, AND REPORTING | AUDIT LEVEL ADJUSTMENT [Withdrawn: Incorporated into AU-6.] References:  [SP 800-86], [SP 800-101]. AU-7 AUDIT RECORD REDUCTION AND REPORT GENERATION Control:  Provide and implement an audit record reduction and report generation capability that: a. Supports on-demand audit record review, analysis, and reporting requirements and after- the-fact investigations of incidents; and b. Does not alter the original content or time ordering of audit records. Discussion:  Audit record reduction is a process that manipulates collected audit log information and organizes it into a summary format that is more meaningful to analysts. Audit record', 'vec_doc-14-nist-sp-800-53-p99-360', 0, 197, 'v2.1.0', '7e0a238fedb239da2b10e01c4c101542559e91e0a259538542125b6741003e69', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 72","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":360,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 72"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p100-361', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 73', 100, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 reduction and report generation capabilities do not always emanate from the same system or from the same organizational entities that conduct audit logging activities. The audit record reduction capability includes modern data mining techniques with advanced data filters to identify anomalous behavior in audit records. The report generation capability provided by the system can generate customizable reports. Time ordering of audit records can be an issue if the granularity of the timestamp in the record is insufficient. Related Controls:  AC-2, AU-2, AU-3, AU-4, AU-5, AU-6, AU-12, AU-16, CM-5, IA-5, IR-4, PM-12, SI- 4.', 'vec_doc-14-nist-sp-800-53-p100-361', 0, 180, 'v2.1.0', 'd30a29023dfc4fb296bf69918f919a87721b4651e363048d15377c7c97898e43', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 73","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":361,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 73"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p100-362', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 73', 100, 'Control Enhancements: (1) AUDIT RECORD REDUCTION AND REPORT GENERATION | AUTOMATIC PROCESSING Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: [Assignment: organization-defined fields within audit records]. Discussion:  Events of interest can be identified by the content of audit records, including system resources involved, information objects accessed, identities of individuals, event types, event locations, event dates and times, Internet Protocol addresses involved, or event success or failure. Organizations may define event criteria to any degree of granularity required, such as locations selectable by a general networking location or by specific system component. Related Controls:  None. (2) AUDIT RECORD REDUCTION AND REPORT GENERATION | AUTOMATIC SORT AND SEARCH [Withdrawn: Incorporated into AU-7(1).] References:  None. AU-8 TIME STAMPS Control: a.', 'vec_doc-14-nist-sp-800-53-p100-362', 0, 239, 'v2.1.0', '3d9a9d9ce4ec61ece03fd8151747f06a82886101995034c2b9ad29c7bf9e63f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 73","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":362,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 73"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p100-363', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 73', 100, 'Use internal system clocks to generate time stamps for audit records; and b. Record time stamps for audit records that meet [Assignment: organization-defined granularity of time measurement] and that use Coordinated Universal Time, have a fixed local time offset from Coordinated Universal Time, or that include the local time offset as part of the time stamp. Discussion:  Time stamps generated by the system include date and time. Time is commonly expressed in Coordinated Universal Time (UTC), a modern continuation of Greenwich Mean Time (GMT), or local time with an offset from UTC. Granularity of time measurements refers to the degree of synchronization between system clocks and reference clocks (e.g., clocks synchronizing within hundreds of milliseconds or tens of milliseconds). Organizations may define different time granularities for different system components.', 'vec_doc-14-nist-sp-800-53-p100-363', 0, 219, 'v2.1.0', 'd977e766fb6c0162eaa88fec2a8128832637e3e75a3c8eae671676fb60044039', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 73","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":363,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 73"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p100-364', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 73', 100, 'Time service can be critical to other security capabilities such as access control and identification and authentication, depending on the nature of the mechanisms used to support those capabilities. Related Controls:  AU-3, AU-12, AU-14, SC-45. Control Enhancements: (1) TIME STAMPS | SYNCHRONIZATION WITH AUTHORITATIVE TIME SOURCE [Withdrawn: Moved to SC-45(1).] (2) TIME STAMPS | SECONDARY AUTHORITATIVE TIME SOURCE', 'vec_doc-14-nist-sp-800-53-p100-364', 0, 105, 'v2.1.0', '5b630241e13d9d44a53990dc271202fcd0834bde941ea72445591075bc6368c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 73","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":364,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 73"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p101-365', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 74', 101, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Moved to SC-45(2).] References:  None. AU-9 PROTECTION OF AUDIT INFORMATION Control: a. Protect audit information and audit logging tools from unauthorized access, modification, and deletion; and b. Alert [Assignment: organization-defined personnel or roles] upon detection of unauthorized access, modification, or deletion of audit information. Discussion:  Audit information includes all information needed to successfully audit system activity, such as audit records, audit log settings, audit reports, and personally identifiable information. Audit logging tools are those programs and devices used to conduct system audit and logging activities. Protection of audit information focuses on technical protection and limits the ability to access and execute audit logging tools to authorized individuals.', 'vec_doc-14-nist-sp-800-53-p101-365', 0, 228, 'v2.1.0', '1dbc2f98ef9277a868e8a702e628513d2a11b5dbcc925cff48a3ab10aae0ea62', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 74","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":365,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 74"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p101-366', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 74', 101, 'Physical protection of audit information is addressed by both media protection controls and physical and environmental protection controls. Related Controls:  AC-3, AC-6, AU-6, AU-11, AU-14, AU-15, MP-2, MP-4, PE-2, PE-3, PE-6, SA-8, SC-8, SI-4. Control Enhancements: (1) PROTECTION OF AUDIT INFORMATION | HARDWARE WRITE-ONCE MEDIA Write audit trails to hardware-enforced, write-once media. Discussion:  Writing audit trails to hardware-enforced, write-once media applies to the initial generation of audit trails (i.e., the collection of audit records that represents the information to be used for detection, analysis, and reporting purposes) and to the backup of those audit trails. Writing audit trails to hardware-enforced, write-once media does not apply to the initial generation of audit records prior to being written to an audit trail. Write-once, read- many (WORM) media includes Compact Disc-Recordable (CD-R), Blu-Ray Disc Recordable (BD-R), and Digital Versatile Disc-Recordable (DVD-R).', 'vec_doc-14-nist-sp-800-53-p101-366', 0, 251, 'v2.1.0', '856785ff8b110b5ed3135d245500e5ecfe54f51e521d4e0b95a1045d2fad3a8f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 74","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":366,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 74"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p101-367', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 74', 101, 'In contrast, the use of switchable write-protection media, such as tape cartridges, Universal Serial Bus (USB) drives, Compact Disc Re-Writeable (CD-RW), and Digital Versatile Disc-Read Write (DVD-RW) results in write- protected but not write-once media. Related Controls:  AU-4, AU-5. (2) PROTECTION OF AUDIT INFORMATION | STORE ON SEPARATE PHYSICAL SYSTEMS OR COMPONENTS Store audit records [Assignment: organization-defined frequency] in a repository that is part of a physically different system or system component than the system or component being audited. Discussion:  Storing audit records in a repository separate from the audited system or system component helps to ensure that a compromise of the system being audited does not also result in a compromise of the audit records. Storing audit records on separate physical systems or components also preserves the confidentiality and integrity of audit records and facilitates the management of audit records as an organization-wide activity.', 'vec_doc-14-nist-sp-800-53-p101-367', 0, 251, 'v2.1.0', '4aebdf6eac5a1864b9c5da14d62ef6cee719c7abf1717f6578a183f511613cbc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 74","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":367,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 74"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p101-368', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 74', 101, 'Storing audit records on separate systems or components applies to initial generation as well as backup or long-term storage of audit records. Related Controls:  AU-4, AU-5. (3) PROTECTION OF AUDIT INFORMATION | CRYPTOGRAPHIC PROTECTION', 'vec_doc-14-nist-sp-800-53-p101-368', 0, 59, 'v2.1.0', '622866a8c339264ea49f32153bb9c42e1816efecded01808cba19976a2cf4c8f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 74","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":368,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 74"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p102-369', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 75', 102, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Implement cryptographic mechanisms to protect the integrity of audit information and audit tools. Discussion:  Cryptographic mechanisms used for protecting the integrity of audit information include signed hash functions using asymmetric cryptography. This enables the distribution of the public key to verify the hash information while maintaining the confidentiality of the secret key used to generate the hash. Related Controls:  AU-10, SC-12, SC-13. (4) PROTECTION OF AUDIT INFORMATION | ACCESS BY SUBSET OF PRIVILEGED USERS Authorize access to management of audit logging functionality to only [Assignment: organization-defined subset of privileged users or roles]. Discussion:  Individuals or roles with privileged access to a system and who are also the subject of an audit by that system may affect the reliability of the audit information by inhibiting audit activities or modifying audit records.', 'vec_doc-14-nist-sp-800-53-p102-369', 0, 250, 'v2.1.0', '71fecd16f7924f394b6ef3be6a7a4a38a15a471255d660a0c088271bce5f4f41', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 75","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":369,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 75"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p102-370', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 75', 102, 'Requiring privileged access to be further defined between audit-related privileges and other privileges limits the number of users or roles with audit-related privileges. Related Controls:  AC-5. (5) PROTECTION OF AUDIT INFORMATION | DUAL AUTHORIZATION Enforce dual authorization for [Selection (one or more): movement; deletion] of [Assignment: organization-defined audit information]. Discussion:  Organizations may choose different selection options for different types of audit information. Dual authorization mechanisms (also known as two-person control) require the approval of two authorized individuals to execute audit functions. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals. Organizations do not require dual authorization mechanisms when immediate responses are necessary to ensure public and environmental safety. Related Controls:  AC-3.', 'vec_doc-14-nist-sp-800-53-p102-370', 0, 230, 'v2.1.0', 'd964d0fa904bd08dcb9f88560af0dd462179e00bdfe2a5458f34c519dc09fee9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 75","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":370,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 75"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p102-371', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 75', 102, '(6) PROTECTION OF AUDIT INFORMATION | READ-ONLY ACCESS Authorize read-only access to audit information to [Assignment: organization-defined subset of privileged users or roles]. Discussion:  Restricting privileged user or role authorizations to read-only helps to limit the potential damage to organizations that could be initiated by such users or roles, such as deleting audit records to cover up malicious activity. Related Controls:  None. (7) PROTECTION OF AUDIT INFORMATION | STORE ON COMPONENT WITH DIFFERENT OPERATING SYSTEM Store audit information on a component running a different operating system than the system or component being audited. Discussion:  Storing auditing information on a system component running a different operating system reduces the risk of a vulnerability specific to the system, resulting in a compromise of the audit records. Related controls:  AU-4, AU-5, AU-11, SC-29. References:  [FIPS 140-3], [FIPS 180-4], [FIPS 202].', 'vec_doc-14-nist-sp-800-53-p102-371', 0, 240, 'v2.1.0', '25448cfa9fc28847ab57fb351c7778f8e48bfa66d2c9f26fe2bfddff4d21c395', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 75","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":371,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 75"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p103-372', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 76', 103, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 AU-10 NON-REPUDIATION Control:  Provide irrefutable evidence that an individual (or process acting on behalf of an individual) has performed [Assignment: organization-defined actions to be covered by non- repudiation]. Discussion:  Types of individual actions covered by non-repudiation include creating information, sending and receiving messages, and approving information. Non-repudiation protects against claims by authors of not having authored certain documents, senders of not having transmitted messages, receivers of not having received messages, and signatories of not having signed documents. Non-repudiation services can be used to determine if information originated from an individual or if an individual took specific actions (e.g., sending an email, signing a contract, approving a procurement request, or receiving specific information).', 'vec_doc-14-nist-sp-800-53-p103-372', 0, 237, 'v2.1.0', '7a36e57050ef1f7f775882836e813096aed5deae96d579d06d154c3ce7b55178', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 76","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":372,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 76"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p103-373', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 76', 103, 'Organizations obtain non- repudiation services by employing various techniques or mechanisms, including digital signatures and digital message receipts. Related Controls:  AU-9, PM-12, SA-8, SC-8, SC-12, SC-13, SC-16, SC-17, SC-23. Control Enhancements: (1) NON-REPUDIATION | ASSOCIATION OF IDENTITIES (a) Bind the identity of the information producer with the information to [Assignment: organization-defined strength of binding]; and (b) Provide the means for authorized individuals to determine the identity of the producer of the information. Discussion:  Binding identities to the information supports audit requirements that provide organizational personnel with the means to identify who produced specific information in the event of an information transfer. Organizations determine and approve the strength of attribute binding between the information producer and the information based on the security category of the information and other relevant risk factors. Related Controls:  AC-4, AC-16.', 'vec_doc-14-nist-sp-800-53-p103-373', 0, 251, 'v2.1.0', '993d8fdebc6c28a3985ca98c02ad609f0de5e477af5da3c2d804eb018588aba8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 76","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":373,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 76"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p103-374', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 76', 103, '(2) NON-REPUDIATION | VALIDATE BINDING OF INFORMATION PRODUCER IDENTITY (a) Validate the binding of the information producer identity to the information at [Assignment: organization-defined frequency]; and (b) Perform [Assignment: organization-defined actions] in the event of a validation error. Discussion:  Validating the binding of the information producer identity to the information prevents the modification of information between production and review. The validation of bindings can be achieved by, for example, using cryptographic checksums. Organizations determine if validations are in response to user requests or generated automatically. Related Controls:  AC-3, AC-4, AC-16. (3) NON-REPUDIATION | CHAIN OF CUSTODY Maintain reviewer or releaser credentials within the established chain of custody for information reviewed or released.', 'vec_doc-14-nist-sp-800-53-p103-374', 0, 212, 'v2.1.0', '626e392915e79243befc6d594c1539629e0461a93bb3704eaa8c6d47137bb3af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 76","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":374,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 76"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p103-375', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 76', 103, 'Discussion:  Chain of custody is a process that tracks the movement of evidence through its collection, safeguarding, and analysis life cycle by documenting each individual who handled the evidence, the date and time the evidence was collected or transferred, and the purpose for the transfer. If the reviewer is a human or if the review function is automated but separate from the release or transfer function, the system associates the identity of the reviewer of the information to be released with the information and the information label. In the case of human reviews, maintaining the credentials of reviewers or releasers provides', 'vec_doc-14-nist-sp-800-53-p103-375', 0, 160, 'v2.1.0', 'a94084dd6be53efd82b156db28000b3d9c3513bd04f41fa2e204bbb5e815a735', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 76","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":375,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 76"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p104-376', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 77', 104, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 the organization with the means to identify who reviewed and released the information. In the case of automated reviews, it ensures that only approved review functions are used. Related Controls:  AC-4, AC-16. (4) NON-REPUDIATION | VALIDATE BINDING OF INFORMATION REVIEWER IDENTITY (a) Validate the binding of the information reviewer identity to the information at the transfer or release points prior to release or transfer between [Assignment: organization-defined security domains]; and (b) Perform [Assignment: organization-defined actions] in the event of a validation error. Discussion:  Validating the binding of the information reviewer identity to the information at transfer or release points prevents the unauthorized modification of information between review and the transfer or release. The validation of bindings can be achieved by using cryptographic checksums.', 'vec_doc-14-nist-sp-800-53-p104-376', 0, 243, 'v2.1.0', 'f19b10ce05db4d6bbcc6a57d37a618d053100927eeef24e7fa769e67a398698f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 77","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":376,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 77"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p104-377', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 77', 104, 'Organizations determine if validations are in response to user requests or generated automatically. Related Controls:  AC-4, AC-16. (5) NON-REPUDIATION | DIGITAL SIGNATURES [Withdrawn: Incorporated into SI-7.] References:  [FIPS 140-3], [FIPS 180-4], [FIPS 186-4], [FIPS 202], [SP 800-177]. AU-11 AUDIT RECORD RETENTION Control:  Retain audit records for [Assignment: organization-defined time period consistent with records retention policy] to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements. Discussion:  Organizations retain audit records until it is determined that the records are no longer needed for administrative, legal, audit, or other operational purposes. This includes the retention and availability of audit records relative to Freedom of Information Act (FOIA) requests, subpoenas, and law enforcement actions.', 'vec_doc-14-nist-sp-800-53-p104-377', 0, 230, 'v2.1.0', '13bb9b9317b6ee6ca5d31bd2ba14321c4b47773f83884b4d750ee7998a359661', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 77","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":377,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 77"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p104-378', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 77', 104, 'Organizations develop standard categories of audit records relative to such types of actions and standard response processes for each type of action. The National Archives and Records Administration (NARA) General Records Schedules provide federal policy on records retention. Related Controls:  AU-2, AU-4, AU-5, AU-6, AU-9, AU-14, MP-6, RA-5, SI-12. Control Enhancements: (1) AUDIT RECORD RETENTION | LONG-TERM RETRIEVAL CAPABILITY Employ [Assignment: organization-defined measures] to ensure that long-term audit records generated by the system can be retrieved. Discussion:  Organizations need to access and read audit records requiring long-term storage (on the order of years). Measures employed to help facilitate the retrieval of audit records include converting records to newer formats, retaining equipment capable of reading the records, and retaining the necessary documentation to help personnel understand how to interpret the records. Related Controls:  None. References:  [OMB A-130].', 'vec_doc-14-nist-sp-800-53-p104-378', 0, 250, 'v2.1.0', 'bbe8d3f13e9fc59a3c2cb685d43402bcf13b64e135be9917df5be226327429b4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 77","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":378,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 77"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p104-379', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 77', 104, 'AU-12 AUDIT RECORD GENERATION Control:', 'vec_doc-14-nist-sp-800-53-p104-379', 0, 10, 'v2.1.0', 'ec798d3f19a6aee324b0691b4927665dc8d6bc0ac5cdf0e4ac270ce55a913a07', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 77","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":379,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 77"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p105-380', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 78', 105, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Provide audit record generation capability for the event types the system is capable of auditing as defined in AU-2a on [Assignment: organization-defined system components]; b. Allow [Assignment: organization-defined personnel or roles] to select the event types that are to be logged by specific components of the system; and c. Generate audit records for the event types defined in AU-2c that include the audit record content defined in AU-3. Discussion:  Audit records can be generated from many different system components. The event types specified in AU-2d are the event types for which audit logs are to be generated and are a subset of all event types for which the system can generate audit records. Related Controls:  AC-6, AC-17, AU-2, AU-3, AU-4, AU-5, AU-6, AU-7, AU-14, CM-5, MA-4, MP-4, PM-12, SA-8, SC-18, SI-3, SI-4, SI-7, SI-10.', 'vec_doc-14-nist-sp-800-53-p105-380', 0, 236, 'v2.1.0', '762866f5dbea3d5a172bad45c1fe9caa301d7f44720621d07deb3bba91e68a4d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 78","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":380,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 78"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p105-381', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 78', 105, 'Control Enhancements: (1) AUDIT RECORD GENERATION | SYSTEM-WIDE AND TIME-CORRELATED AUDIT TRAIL Compile audit records from [Assignment: organization-defined system components] into a system-wide (logical or physical) audit trail that is time-correlated to within [Assignment: organization-defined level of tolerance for the relationship between time stamps of individual records in the audit trail]. Discussion:  Audit trails are time-correlated if the time stamps in the individual audit records can be reliably related to the time stamps in other audit records to achieve a time ordering of the records within organizational tolerances. Related Controls:  AU-8, SC-45. (2) AUDIT RECORD GENERATION | STANDARDIZED FORMATS Produce a system-wide (logical or physical) audit trail composed of audit records in a standardized format. Discussion:  Audit records that follow common standards promote interoperability and information exchange between devices and systems.', 'vec_doc-14-nist-sp-800-53-p105-381', 0, 241, 'v2.1.0', 'e772927212414b4881240a0a5d0085d9729ffef8825b11e042fa8463671cbe98', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 78","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":381,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 78"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p105-382', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 78', 105, 'Promoting interoperability and information exchange facilitates the production of event information that can be readily analyzed and correlated. If logging mechanisms do not conform to standardized formats, systems may convert individual audit records into standardized formats when compiling system-wide audit trails. Related Controls:  None. (3) AUDIT RECORD GENERATION | CHANGES BY AUTHORIZED INDIVIDUALS Provide and implement the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds]. Discussion:  Permitting authorized individuals to make changes to system logging enables organizations to extend or limit logging as necessary to meet organizational requirements.', 'vec_doc-14-nist-sp-800-53-p105-382', 0, 227, 'v2.1.0', '126ec69c912d4f818948e74c27cd189b07d9f04a8f41bb36e0ce4e7f2898858f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 78","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":382,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 78"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p105-383', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 78', 105, 'Logging that is limited to conserve system resources may be extended (either temporarily or permanently) to address certain threat situations. In addition, logging may be limited to a specific set of event types to facilitate audit reduction, analysis, and reporting. Organizations can establish time thresholds in which logging actions are changed (e.g., near real-time, within minutes, or within hours). Related Controls:  AC-3.', 'vec_doc-14-nist-sp-800-53-p105-383', 0, 108, 'v2.1.0', '78e6e30a4c773795de78397ddffaaada61fc1fd907674e90b4fb2691eca700da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 78","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":383,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 78"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p106-384', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 79', 106, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (4) AUDIT RECORD GENERATION | QUERY PARAMETER AUDITS OF PERSONALLY IDENTIFIABLE INFORMATION Provide and implement the capability for auditing the parameters of user query events for data sets containing personally identifiable information. Discussion:  Query parameters are explicit criteria that an individual or automated system submits to a system to retrieve data. Auditing of query parameters for datasets that contain personally identifiable information augments the capability of an organization to track and understand the access, usage, or sharing of personally identifiable information by authorized personnel. Related Controls:  None. References:  None. AU-13 MONITORING FOR INFORMATION DISCLOSURE Control: a. Monitor [Assignment: organization-defined open-source information and/or information sites] [Assignment: organization-defined frequency] for evidence of unauthorized disclosure of organizational information; and b. If an information disclosure is discovered:', 'vec_doc-14-nist-sp-800-53-p106-384', 0, 268, 'v2.1.0', '8833cfd090f29a74f23cb9a03abf868ad86bf25bfc230bf74577acebab56fc9f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 79","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":384,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 79"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p106-385', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Take the following additional actions: [Assignment: organization-defined additional', 106, 'actions]. Discussion:  Unauthorized disclosure of information is a form of data leakage. Open-source information includes social networking sites and code-sharing platforms and repositories. Examples of organizational information include personally identifiable information retained by the organization or proprietary information generated by the organization. Related Controls:  AC-22, PE-3, PM-12, RA-5, SC-7, SI-20. Control Enhancements: (1) MONITORING FOR INFORMATION DISCLOSURE | USE OF AUTOMATED TOOLS Monitor open-source information and information sites using [Assignment: organization- defined automated mechanisms]. Discussion:  Automated mechanisms include commercial services that provide notifications and alerts to organizations and automated scripts to monitor new posts on websites. Related Controls:  None. (2) MONITORING FOR INFORMATION DISCLOSURE | REVIEW OF MONITORED SITES Review the list of open-source information sites being monitored [Assignment: organization-defined frequency]. Discussion:  Reviewing the current list of open-source information sites being monitored on a regular basis helps to ensure that the selected sites remain relevant. The review also provides the opportunity to add new open-source information sites with the potential to provide evidence of unauthorized disclosure of organizational information. The list of sites monitored can be guided and informed by threat intelligence of other credible sources of information. Related Controls:  None. (3) MONITORING FOR INFORMATION DISCLOSURE | UNAUTHORIZED REPLICATION OF INFORMATION', 'vec_doc-14-nist-sp-800-53-p106-385', 0, 395, 'v2.1.0', '58eef7f5cd21556d402f87cd43c71a6d20a4d7e8159e1735d09ec630e1e0be5a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Take the following additional actions: [Assignment: organization-defined additional","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":385,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Take the following additional actions: [Assignment: organization-defined additional"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p107-386', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 80', 107, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Employ discovery techniques, processes, and tools to determine if external entities are replicating organizational information in an unauthorized manner. Discussion:  The unauthorized use or replication of organizational information by external entities can cause adverse impacts on organizational operations and assets, including damage to reputation. Such activity can include the replication of an organizational website by an adversary or hostile threat actor who attempts to impersonate the web-hosting organization. Discovery tools, techniques, and processes used to determine if external entities are replicating organizational information in an unauthorized manner include scanning external websites, monitoring social media, and training staff to recognize the unauthorized use of organizational information. Related Controls:  None. References:  None. AU-14 SESSION AUDIT Control: a.', 'vec_doc-14-nist-sp-800-53-p107-386', 0, 247, 'v2.1.0', '152f070d93a9481541384c05021b1b533683347818658a3f93a9bd6bd0863928', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 80","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":386,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 80"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p107-387', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 80', 107, 'Provide and implement the capability for [Assignment: organization-defined users or roles] to [Selection (one or more): record; view; hear; log] the content of a user session under [Assignment: organization-defined circumstances]; and b. Develop, integrate, and use session auditing activities in consultation with legal counsel and in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Discussion:  Session audits can include monitoring keystrokes, tracking websites visited, and recording information and/or file transfers. Session audit capability is implemented in addition to event logging and may involve implementation of specialized session capture technology. Organizations consider how session auditing can reveal information about individuals that may give rise to privacy risk as well as how to mitigate those risks.', 'vec_doc-14-nist-sp-800-53-p107-387', 0, 223, 'v2.1.0', '3e60de4e38f953c36d4db1fc25eed65020a621ab7b920671d3e69b112215728a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 80","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":387,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 80"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p107-388', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 80', 107, 'Because session auditing can impact system and network performance, organizations activate the capability under well- defined situations (e.g., the organization is suspicious of a specific individual). Organizations consult with legal counsel, civil liberties officials, and privacy officials to ensure that any legal, privacy, civil rights, or civil liberties issues, including the use of personally identifiable information, are appropriately addressed. Related Controls:  AC-3, AC-8, AU-2, AU-3, AU-4, AU-5, AU-8, AU-9, AU-11, AU-12. Control Enhancements: (1) SESSION AUDIT | SYSTEM START-UP Initiate session audits automatically at system start-up. Discussion:  The automatic initiation of session audits at startup helps to ensure that the information being captured on selected individuals is complete and not subject to compromise through tampering by malicious threat actors. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p107-388', 0, 227, 'v2.1.0', '932c4f3a94088b8d9596199977255a0e4a969c2198eac92071e2a42046bc4c35', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 80","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":388,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 80"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p107-389', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 80', 107, '(2) SESSION AUDIT | CAPTURE AND RECORD CONTENT [Withdrawn: Incorporated into AU-14.] (3) SESSION AUDIT | REMOTE VIEWING AND LISTENING Provide and implement the capability for authorized users to remotely view and hear content related to an established user session in real time. Discussion:  None.', 'vec_doc-14-nist-sp-800-53-p107-389', 0, 75, 'v2.1.0', 'a2a954d820a6877a61e649e49ede3ce03c0aac378f73ac5263713012b8256f4e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 80","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":389,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 80"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p108-390', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 81', 108, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  AC-17. References:  None. AU-15 ALTERNATE AUDIT LOGGING CAPABILITY [Withdrawn: Moved to AU-5(5).] AU-16 CROSS-ORGANIZATIONAL AUDIT LOGGING Control:  Employ [Assignment: organization-defined methods] for coordinating [Assignment: organization-defined audit information] among external organizations when audit information is transmitted across organizational boundaries. Discussion:  When organizations use systems or services of external organizations, the audit logging capability necessitates a coordinated, cross-organization approach. For example, maintaining the identity of individuals who request specific services across organizational boundaries may often be difficult, and doing so may prove to have significant performance and privacy ramifications.', 'vec_doc-14-nist-sp-800-53-p108-390', 0, 218, 'v2.1.0', 'e0852d0f62b6061d634d211a7709e395395c543761dc62072c1396cb6e01da1e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 81","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":390,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 81"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p108-391', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 81', 108, 'Therefore, it is often the case that cross-organizational audit logging simply captures the identity of individuals who issue requests at the initial system, and subsequent systems record that the requests originated from authorized individuals. Organizations consider including processes for coordinating audit information requirements and protection of audit information in information exchange agreements. Related Controls:  AU-3, AU-6, AU-7, CA-3, PT-7. Control Enhancements: (1) CROSS-ORGANIZATIONAL AUDIT LOGGING | IDENTITY PRESERVATION Preserve the identity of individuals in cross-organizational audit trails. Discussion:  Identity preservation is applied when there is a need to be able to trace actions that are performed across organizational boundaries to a specific individual. Related Controls:  IA-2, IA-4, IA-5, IA-8.', 'vec_doc-14-nist-sp-800-53-p108-391', 0, 209, 'v2.1.0', '8750df92a036d6fcf1ec85866d6c9050bb18eeb36def178ae84920dcb822fd7d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 81","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":391,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 81"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p108-392', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 81', 108, '(2) CROSS-ORGANIZATIONAL AUDIT LOGGING | SHARING OF AUDIT INFORMATION Provide cross-organizational audit information to [Assignment: organization-defined organizations] based on [Assignment: organization-defined cross-organizational sharing agreements]. Discussion:  Due to the distributed nature of the audit information, cross-organization sharing of audit information may be essential for effective analysis of the auditing being performed. For example, the audit records of one organization may not provide sufficient information to determine the appropriate or inappropriate use of organizational information resources by individuals in other organizations. In some instances, only individuals’ home organizations have the appropriate knowledge to make such determinations, thus requiring the sharing of audit information among organizations. Related Controls:  IR-4, SI-4.', 'vec_doc-14-nist-sp-800-53-p108-392', 0, 220, 'v2.1.0', '3c30a94a839e177370bdfb55fdde390961d686053b706eb960dde2ccb47800a3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 81","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":392,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 81"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p108-393', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 81', 108, '(3) CROSS-ORGANIZATIONAL AUDITING | DISASSOCIABILITY Implement [Assignment: organization-defined measures] to disassociate individuals from audit information transmitted across organizational boundaries. Discussion:  Preserving identities in audit trails could have privacy ramifications, such as enabling the tracking and profiling of individuals, but may not be operationally necessary. These risks could be further amplified when transmitting information across organizational boundaries. Implementing privacy-enhancing cryptographic techniques can disassociate individuals from audit information and reduce privacy risk while maintaining accountability.', 'vec_doc-14-nist-sp-800-53-p108-393', 0, 165, 'v2.1.0', 'c38f6b46de8f96a5e79bb5dda654aea9b947d9e437634dd4a4f7ffbc3240fb89', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 81","subsection":"UNKNOWN","table_id":null,"page":108,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":393,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 81"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p109-394', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 82', 109, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p109-394', 0, 34, 'v2.1.0', '484a23518e3d666c0053c29a69ecaa2c5a1c6bf623953899e10c28b6d1214fe9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 82","subsection":"UNKNOWN","table_id":null,"page":109,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":394,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 82"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p110-395', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.4   ASSESSMENT, AUTHORIZATION, AND MONITORING', 110, 'Quick link to Assessment, Authorization, and Monitoring Summary Table CA-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p110-395', 0, 51, 'v2.1.0', 'd9014595516f81f22763a324afbf8c42f3f22e50cf2051865f5ec0f31e722197', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.4   ASSESSMENT, AUTHORIZATION, AND MONITORING","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":395,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.4   ASSESSMENT, AUTHORIZATION, AND MONITORING"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p110-396', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 110, 'level] assessment, authorization, and monitoring policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p110-396', 0, 82, 'v2.1.0', '5d6aedbcd3d8b405922254a468b507d8ef34d6b41bf5ff8663fbe5b40faa4b69', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":396,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p110-397', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the assessment, authorization, and', 110, 'monitoring policy and the associated assessment, authorization, and monitoring controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the assessment, authorization, and monitoring policy and procedures; and c. Review and update the current assessment, authorization, and monitoring:', 'vec_doc-14-nist-sp-800-53-p110-397', 0, 90, 'v2.1.0', '9526752f9e295289ddcdaf97d597ec25a4e7aa86f42ab9c223d4c8d3279b08fa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the assessment, authorization, and","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":397,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the assessment, authorization, and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p110-398', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 110, 'organization-defined events]. Discussion:  Assessment, authorization, and monitoring policy and procedures address the controls in the CA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of assessment, authorization, and monitoring policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system- specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to assessment, authorization, and monitoring policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None.', 'vec_doc-14-nist-sp-800-53-p110-398', 0, 426, 'v2.1.0', '904b03fca1589ddeaed99eed2524e8c4631ba1b21db7b0289b0db5d5e133c64b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":110,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":398,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p111-399', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 84', 111, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-53A], [SP 800-100], [SP 800-137], [SP 800-137A], [IR 8062]. CA-2 CONTROL ASSESSMENTS Control: a. Select the appropriate assessor or assessment team for the type of assessment to be conducted; b. Develop a control assessment plan that describes the scope of the assessment including:', 'vec_doc-14-nist-sp-800-53-p111-399', 0, 115, 'v2.1.0', 'f60fc44ef2393e06210c922b9297038dd682b22faf98135b717855eaf6789d0d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 84","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":399,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 84"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p111-400', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Assessment environment, assessment team, and assessment roles and responsibilities;', 111, 'c. Ensure the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment; d. Assess the controls in the system and its environment of operation [Assignment: organization-defined frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security and privacy requirements; e. Produce a control assessment report that document the results of the assessment; and f. Provide the results of the control assessment to [Assignment: organization-defined individuals or roles]. Discussion:  Organizations ensure that control assessors possess the required skills and technical expertise to develop effective assessment plans and to conduct assessments of system-specific, hybrid, common, and program management controls, as appropriate.', 'vec_doc-14-nist-sp-800-53-p111-400', 0, 232, 'v2.1.0', '9ea0015723eeaac538cd1f1e9fe11cbdc4a4f53216c3e13ad6a03848e8ef997e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Assessment environment, assessment team, and assessment roles and responsibilities;","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":400,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Assessment environment, assessment team, and assessment roles and responsibilities;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p111-401', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Assessment environment, assessment team, and assessment roles and responsibilities;', 111, 'The required skills include general knowledge of risk management concepts and approaches as well as comprehensive knowledge of and experience with the hardware, software, and firmware system components implemented. Organizations assess controls in systems and the environments in which those systems operate as part of initial and ongoing authorizations, continuous monitoring, FISMA annual assessments, system design and development, systems security engineering, privacy engineering, and the system development life cycle. Assessments help to ensure that organizations meet information security and privacy requirements, identify weaknesses and deficiencies in the system design and development process, provide essential information needed to make risk-based decisions as part of authorization processes, and comply with vulnerability mitigation procedures. Organizations conduct assessments on the implemented controls as documented in security and privacy plans.', 'vec_doc-14-nist-sp-800-53-p111-401', 0, 242, 'v2.1.0', 'b8e21ee249dd75809528025489523903268feff9da646ed0a7c7f236940b5b08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Assessment environment, assessment team, and assessment roles and responsibilities;","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":401,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Assessment environment, assessment team, and assessment roles and responsibilities;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p111-402', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Assessment environment, assessment team, and assessment roles and responsibilities;', 111, 'Assessments can also be conducted throughout the system development life cycle as part of systems engineering and systems security engineering processes. The design for controls can be assessed as RFPs are developed, responses assessed, and design reviews conducted. If a design to implement controls and subsequent implementation in accordance with the design are assessed during development, the final control testing can be a simple confirmation utilizing previously completed control assessment and aggregating the outcomes. Organizations may develop a single, consolidated security and privacy assessment plan for the system or maintain separate plans. A consolidated assessment plan clearly delineates the roles and responsibilities for control assessment. If multiple organizations participate in assessing a system, a coordinated approach can reduce redundancies and associated costs.', 'vec_doc-14-nist-sp-800-53-p111-402', 0, 223, 'v2.1.0', '63696b524c6351d65c357e69d9f80d7e9be13c217efa7c4d16682b6994b23b18', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Assessment environment, assessment team, and assessment roles and responsibilities;","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":402,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Assessment environment, assessment team, and assessment roles and responsibilities;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p111-403', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Assessment environment, assessment team, and assessment roles and responsibilities;', 111, 'Organizations can use other types of assessment activities, such as vulnerability scanning and system monitoring, to maintain the security and privacy posture of systems during the system', 'vec_doc-14-nist-sp-800-53-p111-403', 0, 47, 'v2.1.0', '9b53b3fbca167b4bd018221bb390719be9e4aa1e04f06273f2d20360446efdc0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Assessment environment, assessment team, and assessment roles and responsibilities;","subsection":"UNKNOWN","table_id":null,"page":111,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":403,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Assessment environment, assessment team, and assessment roles and responsibilities;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p112-404', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 85', 112, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 life cycle. Assessment reports document assessment results in sufficient detail, as deemed necessary by organizations, to determine the accuracy and completeness of the reports and whether the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting requirements. Assessment results are provided to the individuals or roles appropriate for the types of assessments being conducted. For example, assessments conducted in support of authorization decisions are provided to authorizing officials, senior agency officials for privacy, senior agency information security officers, and authorizing official designated representatives.', 'vec_doc-14-nist-sp-800-53-p112-404', 0, 195, 'v2.1.0', '5550ccf912a83d93c0f6d332f728430b20ab9b0ed7da499138baa364ba69c55b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 85","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":404,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 85"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p112-405', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 85', 112, 'To satisfy annual assessment requirements, organizations can use assessment results from the following sources: initial or ongoing system authorizations, continuous monitoring, systems engineering processes, or system development life cycle activities. Organizations ensure that assessment results are current, relevant to the determination of control effectiveness, and obtained with the appropriate level of assessor independence. Existing control assessment results can be reused to the extent that the results are still valid and can also be supplemented with additional assessments as needed. After the initial authorizations, organizations assess controls during continuous monitoring. Organizations also establish the frequency for ongoing assessments in accordance with organizational continuous monitoring strategies. External audits, including audits by external entities such as regulatory agencies, are outside of the scope of CA-2 .', 'vec_doc-14-nist-sp-800-53-p112-405', 0, 237, 'v2.1.0', '36b59cc85fa60f8ca162e2ae2d58bbdd7647136782bff851b738d1dda7c2d603', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 85","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":405,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 85"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p112-406', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 85', 112, 'Related Controls:  AC-20, CA-5, CA-6, CA-7, PM-9, RA-5, RA-10, SA-11, SC-38, SI-3, SI-12, SR-2, SR- 3. Control Enhancements: (1) CONTROL ASSESSMENTS | INDEPENDENT ASSESSORS Employ independent assessors or assessment teams to conduct control assessments. Discussion:  Independent assessors or assessment teams are individuals or groups who conduct impartial assessments of systems. Impartiality means that assessors are free from any perceived or actual conflicts of interest regarding the development, operation, sustainment, or management of the systems under assessment or the determination of control effectiveness. To achieve impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in positions of advocacy for the organizations acquiring their services.', 'vec_doc-14-nist-sp-800-53-p112-406', 0, 238, 'v2.1.0', 'acc342b6f895259f2d940bf9e9fc64b00da6ba58031aee5f6136c3c0d6fe0223', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 85","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":406,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 85"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p112-407', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 85', 112, 'Independent assessments can be obtained from elements within organizations or be contracted to public or private sector entities outside of organizations. Authorizing officials determine the required level of independence based on the security categories of systems and/or the risk to organizational operations, organizational assets, or individuals. Authorizing officials also determine if the level of assessor independence provides sufficient assurance that the results are sound and can be used to make credible, risk-based decisions. Assessor independence determination includes whether contracted assessment services have sufficient independence, such as when system owners are not directly involved in contracting processes or cannot influence the impartiality of the assessors conducting the assessments. During the system design and development phase, having independent assessors is analogous to having independent SMEs involved in design reviews.', 'vec_doc-14-nist-sp-800-53-p112-407', 0, 240, 'v2.1.0', '2afd06dc313796a53701eabd0bff2d8ff6036dc42ad1e0b841891c049aa02a6a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 85","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":407,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 85"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p112-408', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 85', 112, 'When organizations that own the systems are small or the structures of the organizations require that assessments be conducted by individuals that are in the developmental, operational, or management chain of the system owners, independence in assessment processes can be achieved by ensuring that assessment results are carefully reviewed and analyzed by independent teams of experts to validate the completeness, accuracy, integrity, and reliability of the results. Assessments performed for purposes other than to support', 'vec_doc-14-nist-sp-800-53-p112-408', 0, 131, 'v2.1.0', '7d0485c42e9a0579847a063e6f270b8a53dba2d2cd77deabad2876399a18b243', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 85","subsection":"UNKNOWN","table_id":null,"page":112,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":408,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 85"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p113-409', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 86', 113, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 authorization decisions are more likely to be useable for such decisions when performed by assessors with sufficient independence, thereby reducing the need to repeat assessments. Related Controls:  None. (2) CONTROL ASSESSMENTS | SPECIALIZED ASSESSMENTS Include as part of control assessments, [Assignment: organization-defined frequency], [Selection: announced; unannounced], [Selection (one or more): in-depth monitoring; security instrumentation; automated security test cases; vulnerability scanning; malicious user testing; insider threat assessment; performance and load testing; data leakage or data loss assessment; [Assignment: organization-defined other forms of assessment]]. Discussion:  Organizations can conduct specialized assessments, including verification and validation, system monitoring, insider threat assessments, malicious user testing, and other forms of testing.', 'vec_doc-14-nist-sp-800-53-p113-409', 0, 246, 'v2.1.0', 'dc394765184dfa940d5ed10881e2265571ad31aae4ec511879310580abe91846', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 86","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":409,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 86"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p113-410', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 86', 113, 'These assessments can improve readiness by exercising organizational capabilities and indicating current levels of performance as a means of focusing actions to improve security and privacy. Organizations conduct specialized assessments in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Authorizing officials approve the assessment methods in coordination with the organizational risk executive function. Organizations can include vulnerabilities uncovered during assessments into vulnerability remediation processes. Specialized assessments can also be conducted early in the system development life cycle (e.g., during initial design, development, and unit testing). Related Controls:  PE-3, SI-2.', 'vec_doc-14-nist-sp-800-53-p113-410', 0, 192, 'v2.1.0', '79118ffc65b3f7079bc3e61c13832b81f115d7b462b202474c831b46369778d1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 86","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":410,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 86"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p113-411', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 86', 113, '(3) CONTROL ASSESSMENTS | LEVERAGING RESULTS FROM EXTERNAL ORGANIZATIONS Leverage the results of control assessments performed by [Assignment: organization- defined external organization] on [Assignment: organization-defined system] when the assessment meets [Assignment: organization-defined requirements]. Discussion:  Organizations may rely on control assessments of organizational systems by other (external) organizations. Using such assessments and reusing existing assessment evidence can decrease the time and resources required for assessments by limiting the independent assessment activities that organizations need to perform. The factors that organizations consider in determining whether to accept assessment results from external organizations can vary.', 'vec_doc-14-nist-sp-800-53-p113-411', 0, 192, 'v2.1.0', 'fcf4371e3172ec3aa693d86a7f30c782779eab5ec363374b52238a8d4a3a7c57', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 86","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":411,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 86"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p113-412', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 86', 113, 'Such factors include the organization’s past experience with the organization that conducted the assessment, the reputation of the assessment organization, the level of detail of supporting assessment evidence provided, and mandates imposed by applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Accredited testing laboratories that support the Common Criteria Program [ ISO 15408-1], the NIST Cryptographic Module Validation Program (CMVP), or the NIST Cryptographic Algorithm Validation Program (CAVP) can provide independent assessment results that organizations can leverage. Related Controls:  SA-4. References:  [OMB A-130], [FIPS 199], [SP 800-18], [SP 800-37], [SP 800-39], [SP 800-53A], [SP 800-115], [SP 800-137], [IR 8011-1], [IR 8062]. CA-3 INFORMATION EXCHANGE Control: a.', 'vec_doc-14-nist-sp-800-53-p113-412', 0, 208, 'v2.1.0', 'e3a1fe84a9b168b0eae0dcfadd9df388ae781e88d7ca05de050a2575c9e369cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 86","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":412,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 86"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p113-413', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 86', 113, 'Approve and manage the exchange of information between the system and other systems using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements;', 'vec_doc-14-nist-sp-800-53-p113-413', 0, 66, 'v2.1.0', 'e83e4bb5fc0456859f7a415e06c62d2a0b67386d17178b4d1ee6b6ba0888ac16', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 86","subsection":"UNKNOWN","table_id":null,"page":113,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":413,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 86"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p114-414', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 87', 114, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 user agreements; nondisclosure agreements; [Assignment: organization-defined type of agreement]]; b. Document, as part of each exchange agreement, the interface characteristics, security and privacy requirements, controls, and responsibilities for each system, and the impact level of the information communicated; and c. Review and update the agreements [Assignment: organization-defined frequency]. Discussion:  System information exchange requirements apply to information exchanges between two or more systems.', 'vec_doc-14-nist-sp-800-53-p114-414', 0, 152, 'v2.1.0', '7916cbd9c4121959b8a5a1945de4fbe4c23cec11203d02930a2b088f72c90740', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 87","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":414,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 87"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p114-415', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 87', 114, 'System information exchanges include connections via leased lines or virtual private networks, connections to internet service providers, database sharing or exchanges of database transaction information, connections and exchanges with cloud services, exchanges via web-based services, or exchanges of files via file transfer protocols, network protocols (e.g., IPv4, IPv6), email, or other organization-to-organization communications. Organizations consider the risk related to new or increased threats that may be introduced when systems exchange information with other systems that may have different security and privacy requirements and controls. This includes systems within the same organization and systems that are external to the organization. A joint authorization of the systems exchanging information, as described in CA-6(1) or CA-6(2), may help to communicate and reduce risk.', 'vec_doc-14-nist-sp-800-53-p114-415', 0, 223, 'v2.1.0', 'e91ecbbcb6622c9e6779739b9f44fd095e309e278b98cc8609fe74ae91c7cb92', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 87","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":415,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 87"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p114-416', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 87', 114, 'Authorizing officials determine the risk associated with system information exchange and the controls needed for appropriate risk mitigation. The types of agreements selected are based on factors such as the impact level of the information being exchanged, the relationship between the organizations exchanging information (e.g., government to government, government to business, business to business, government or business to service provider, government or business to individual), or the level of access to the organizational system by users of the other system. If systems that exchange information have the same authorizing official, organizations need not develop agreements. Instead, the interface characteristics between the systems (e.g., how the information is being exchanged. how the information is protected) are described in the respective security and privacy plans.', 'vec_doc-14-nist-sp-800-53-p114-416', 0, 221, 'v2.1.0', '72bcfd56b1475c9cc655a315475ef48d1b712fd9dffc3aa457afd863dd6a78fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 87","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":416,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 87"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p114-417', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 87', 114, 'If the systems that exchange information have different authorizing officials within the same organization, the organizations can develop agreements or provide the same information that would be provided in the appropriate agreement type from CA-3a in the respective security and privacy plans for the systems. Organizations may incorporate agreement information into formal contracts, especially for information exchanges established between federal agencies and nonfederal organizations (including service providers, contractors, system developers, and system integrators). Risk considerations include systems that share the same networks. Related Controls:  AC-4,  AC-20, AU-16, CA-6, IA-3, IR-4, PL-2, PT-7, RA-3, SA-9, SC-7, SI-12.', 'vec_doc-14-nist-sp-800-53-p114-417', 0, 184, 'v2.1.0', '3ab7ecb5e369d333cacd53cf491f13886205b8f876c25a70a52335012596afed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 87","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":417,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 87"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p114-418', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 87', 114, 'Control Enhancements: (1) SYSTEM CONNECTIONS | UNCLASSIFIED NATIONAL SECURITY SYSTEM CONNECTIONS [Withdrawn: Moved to SC-7(25).] (2) SYSTEM CONNECTIONS | CLASSIFIED NATIONAL SECURITY SYSTEM CONNECTIONS [Withdrawn: Moved to SC-7(26).] (3) SYSTEM CONNECTIONS | UNCLASSIFIED NON-NATIONAL SECURITY SYSTEM CONNECTIONS [Withdrawn: Moved to SC-7(27).] (4) SYSTEM CONNECTIONS | CONNECTIONS TO PUBLIC NETWORKS [Withdrawn: Moved to SC-7(28).] (5) SYSTEM CONNECTIONS | RESTRICTIONS ON EXTERNAL SYSTEM CONNECTIONS', 'vec_doc-14-nist-sp-800-53-p114-418', 0, 126, 'v2.1.0', 'e5e59badf2b5605d984eae729c6f13cd2a3b3525c555e554991ea92126054c82', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 87","subsection":"UNKNOWN","table_id":null,"page":114,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":418,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 87"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p115-419', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 88', 115, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Moved to SC-7(5).] (6) INFORMATION EXCHANGE | TRANSFER AUTHORIZATIONS Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data. Discussion:  To prevent unauthorized individuals and systems from making information transfers to protected systems, the protected system verifies— via independent means— whether the individual or system attempting to transfer information is authorized to do so. Verification of the authorization to transfer information also applies to control plane traffic (e.g., routing and DNS) and services (e.g., authenticated SMTP relays). Related Controls:  AC-2, AC-3, AC-4.', 'vec_doc-14-nist-sp-800-53-p115-419', 0, 208, 'v2.1.0', 'e0773a1aebcbd87d0801c6470f8dcf6afe47623043e6c9f7256168459cc18a7d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 88","subsection":"UNKNOWN","table_id":null,"page":115,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":419,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 88"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p115-420', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 88', 115, '(7) INFORMATION EXCHANGE |TRANSITIVE INFORMATION EXCHANGES (a) Identify transitive (downstream) information exchanges with other systems through the systems identified in CA-3a; and (b) Take measures to ensure that transitive (downstream) information exchanges cease when the controls on identified transitive (downstream) systems cannot be verified or validated. Discussion:  Transitive or “downstream” information exchanges are information exchanges between the system or systems with which the organizational system exchanges information and other systems. For mission-essential systems, services, and applications, including high value assets, it is necessary to identify such information exchanges. The transparency of the controls or protection measures in place in such downstream systems connected directly or indirectly to organizational systems is essential to understanding the security and privacy risks resulting from those information exchanges.', 'vec_doc-14-nist-sp-800-53-p115-420', 0, 240, 'v2.1.0', '97d8ef9e0a845547e4e90f9daba5b043f99e2bfe53964502c028cbcb8da3b276', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 88","subsection":"UNKNOWN","table_id":null,"page":115,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":420,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 88"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p115-421', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 88', 115, 'Organizational systems can inherit risk from downstream systems through transitive connections and information exchanges, which can make the organizational systems more susceptible to threats, hazards, and adverse impacts. Related Controls:  SC-7. References:  [OMB A-130], [FIPS 199], [SP 800-47]. CA-4 SECURITY CERTIFICATION [Withdrawn: Incorporated into CA-2.] CA-5 PLAN OF ACTION AND MILESTONES Control: a. Develop a plan of action and milestones for the system to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system; and b. Update existing plan of action and milestones [Assignment: organization-defined frequency] based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities.', 'vec_doc-14-nist-sp-800-53-p115-421', 0, 223, 'v2.1.0', '8639cf9ce2b054ced718da7a1f5a8dd159bf15d57e6d7dcdac9e09ebd0fe6f17', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 88","subsection":"UNKNOWN","table_id":null,"page":115,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":421,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 88"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p115-422', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 88', 115, 'Discussion:  Plans of action and milestones are useful for any type of organization to track planned remedial actions. Plans of action and milestones are required in authorization packages and subject to federal reporting requirements established by OMB. Related Controls:  CA-2, CA-7, PM-4, PM-9, RA-7, SI-2, SI-12.', 'vec_doc-14-nist-sp-800-53-p115-422', 0, 79, 'v2.1.0', 'e430f1de4c2c7439e8480aa1a324ff1583eab06e80ac1f9e5303365f5a910cc1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 88","subsection":"UNKNOWN","table_id":null,"page":115,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":422,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 88"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p116-423', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 89', 116, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) PLAN OF ACTION AND MILESTONES | AUTOMATION SUPPORT FOR ACCURACY AND CURRENCY Ensure the accuracy, currency, and availability of the plan of action and milestones for the system using [Assignment: organization-defined automated mechanisms]. Discussion:  Using automated tools helps maintain the accuracy, currency, and availability of the plan of action and milestones and facilitates the coordination and sharing of security and privacy information throughout the organization. Such coordination and information sharing help to identify systemic weaknesses or deficiencies in organizational systems and ensure that appropriate resources are directed at the most critical system vulnerabilities in a timely manner. Related Controls:  None. References:  [OMB A-130], [SP 800-37]. CA-6 AUTHORIZATION Control: a. Assign a senior official as the authorizing official for the system; b. Assign a senior official as the authorizing official for common controls available for inheritance by organizational systems; c. Ensure that the authorizing official for the system, before commencing operations:', 'vec_doc-14-nist-sp-800-53-p116-423', 0, 303, 'v2.1.0', '246f3b5ef125600d93ff70acebeab1db8bf6f16a2fe79bfb7dff91b37220ea14', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 89","subsection":"UNKNOWN","table_id":null,"page":116,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":423,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 89"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p116-424', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Authorizes the system to operate;', 116, 'd. Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems; e. Update the authorizations [Assignment: organization-defined frequency]. Discussion:  Authorizations are official management decisions by senior officials to authorize operation of systems, authorize the use of common controls for inheritance by organizational systems, and explicitly accept the risk to organizational operations and assets, individuals, other organizations, and the Nation based on the implementation of agreed-upon controls. Authorizing officials provide budgetary oversight for organizational systems and common controls or assume responsibility for the mission and business functions supported by those systems or common controls. The authorization process is a federal responsibility, and therefore, authorizing officials must be federal employees.', 'vec_doc-14-nist-sp-800-53-p116-424', 0, 228, 'v2.1.0', '7da83ac83c9700ded7303024291c0889b105a32affebb11573ba8addf69d4a51', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Authorizes the system to operate;","subsection":"UNKNOWN","table_id":null,"page":116,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":424,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Authorizes the system to operate;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p116-425', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Authorizes the system to operate;', 116, 'Authorizing officials are both responsible and accountable for security and privacy risks associated with the operation and use of organizational systems. Nonfederal organizations may have similar processes to authorize systems and senior officials that assume the authorization role and associated responsibilities. Authorizing officials issue ongoing authorizations of systems based on evidence produced from implemented continuous monitoring programs. Robust continuous monitoring programs reduce the need for separate reauthorization processes. Through the employment of comprehensive continuous monitoring processes, the information contained in authorization packages (i.e., security and privacy plans, assessment reports, and plans of action and milestones) is updated on an ongoing basis. This provides authorizing officials, common control providers, and system owners with an up-to-date status of the security and privacy posture of their systems, controls, and operating environments.', 'vec_doc-14-nist-sp-800-53-p116-425', 0, 249, 'v2.1.0', '84b77bf17f27d5c7ffc637f2b63c411d163cf52afbc1817ee57b2f396d155b1b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Authorizes the system to operate;","subsection":"UNKNOWN","table_id":null,"page":116,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":425,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Authorizes the system to operate;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p116-426', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Authorizes the system to operate;', 116, 'To reduce the cost of reauthorization, authorizing officials can leverage the results of continuous monitoring processes to the maximum extent possible as the basis for rendering reauthorization decisions.', 'vec_doc-14-nist-sp-800-53-p116-426', 0, 52, 'v2.1.0', '9f665e30c7c0b690499c2b45b47cf7ed056b7fbda79d05ba29de0cfbe175271f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Authorizes the system to operate;","subsection":"UNKNOWN","table_id":null,"page":116,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":426,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Authorizes the system to operate;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p117-427', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 90', 117, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  CA-2, CA-3, CA-7, PM-9, PM-10, RA-3, SA-10, SI-12. Control Enhancements: (1) AUTHORIZATION | JOINT AUTHORIZATION —  INTRA-ORGANIZATION Employ a joint authorization process for the system that includes multiple authorizing officials from the same organization conducting the authorization. Discussion:  Assigning multiple authorizing officials from the same organization to serve as co-authorizing officials for the system increases the level of independence in the risk-based decision-making process. It also implements the concepts of separation of duties and dual authorization as applied to the system authorization process. The intra-organization joint authorization process is most relevant for connected systems, shared systems, and systems with multiple information owners. Related Controls:  AC-6.', 'vec_doc-14-nist-sp-800-53-p117-427', 0, 229, 'v2.1.0', '2aa6fc019b174a51425a19b2f2988436234b3148da82a547b89709f97904bf71', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 90","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":427,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 90"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p117-428', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 90', 117, '(2) AUTHORIZATION | JOINT AUTHORIZATION —  INTER-ORGANIZATION Employ a joint authorization process for the system that includes multiple authorizing officials with at least one authorizing official from an organization external to the organization conducting the authorization. Discussion:  Assigning multiple authorizing officials, at least one of whom comes from an external organization, to serve as co-authorizing officials for the system increases the level of independence in the risk-based decision-making process. It implements the concepts of separation of duties and dual authorization as applied to the system authorization process. Employing authorizing officials from external organizations to supplement the authorizing official from the organization that owns or hosts the system may be necessary when the external organizations have a vested interest or equities in the outcome of the authorization decision.', 'vec_doc-14-nist-sp-800-53-p117-428', 0, 231, 'v2.1.0', 'b8a992ccd5e383a66c79799165b251668eb1cc97907cda8fa8a5e71f523bcb29', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 90","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":428,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 90"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p117-429', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 90', 117, 'The inter-organization joint authorization process is relevant and appropriate for connected systems, shared systems or services, and systems with multiple information owners. The authorizing officials from the external organizations are key stakeholders of the system undergoing authorization. Related Controls:  AC-6. References:  [OMB A-130], [SP 800-37], [SP 800-137]. CA-7 CONTINUOUS MONITORING Control:  Develop a system-level continuous monitoring strategy and implement continuous monitoring in accordance with the organization-level continuous monitoring strategy that includes: a. Establishing the following system-level metrics to be monitored: [Assignment: organization- defined system-level metrics]; b. Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness; c. Ongoing control assessments in accordance with the continuous monitoring strategy; d.', 'vec_doc-14-nist-sp-800-53-p117-429', 0, 243, 'v2.1.0', '29c0fc18b8a347dd85b538007898e474157accef3639ee1cd4e19fa794db2df8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 90","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":429,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 90"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p117-430', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 90', 117, 'Ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy; e. Correlation and analysis of information generated by control assessments and monitoring; f. Response actions to address results of the analysis of control assessment and monitoring information; and', 'vec_doc-14-nist-sp-800-53-p117-430', 0, 80, 'v2.1.0', 'd5dcffae1df0c591604aa66c80e55d9d01adbbd27c11b1c0faedc0c6300a8d64', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 90","subsection":"UNKNOWN","table_id":null,"page":117,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":430,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 90"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p118-431', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 91', 118, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 g. Reporting the security and privacy status of the system to [Assignment: organization- defined personnel or roles] [Assignment: organization-defined frequency]. Discussion:  Continuous monitoring at the system level facilitates ongoing awareness of the system security and privacy posture to support organizational risk management decisions. The terms “continuous” and “ongoing” imply that organizations assess and monitor their controls and risks at a frequency sufficient to support risk-based decisions. Different types of controls may require different monitoring frequencies. The results of continuous monitoring generate risk response actions by organizations. When monitoring the effectiveness of multiple controls that have been grouped into capabilities, a root-cause analysis may be needed to determine the specific control that has failed.', 'vec_doc-14-nist-sp-800-53-p118-431', 0, 236, 'v2.1.0', 'd578fa9972de31a7fb144aadcb022dbb86fc57d9d2308f4bf7a56fc25e62a723', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 91","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":431,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 91"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p118-432', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 91', 118, 'Continuous monitoring programs allow organizations to maintain the authorizations of systems and common controls in highly dynamic environments of operation with changing mission and business needs, threats, vulnerabilities, and technologies. Having access to security and privacy information on a continuing basis through reports and dashboards gives organizational officials the ability to make effective and timely risk management decisions, including ongoing authorization decisions. Automation supports more frequent updates to hardware, software, and firmware inventories, authorization packages, and other system information. Effectiveness is further enhanced when continuous monitoring outputs are formatted to provide information that is specific, measurable, actionable, relevant, and timely. Continuous monitoring activities are scaled in accordance with the security categories of systems.', 'vec_doc-14-nist-sp-800-53-p118-432', 0, 226, 'v2.1.0', '6b841dda281620b6aa412cd0b6323b15315f07f85e76b5643c603fc6c517f0be', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 91","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":432,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 91"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p118-433', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 91', 118, 'Monitoring requirements, including the need for specific monitoring, may be referenced in other controls and control enhancements, such as AC-2g, AC- 2(7), AC-2(12)(a), AC-2(7)(b), AC-2(7)(c), AC-17(1), AT-4a, AU-13, AU-13(1), AU-13(2), CM-3f, CM- 6d, CM-11c, IR-5, MA-2b, MA-3a, MA-4a, PE-3d, PE-6, PE-14b, PE-16, PE-20, PM-6, PM-23, PM- 31, PS-7e, SA-9c, SR-4, SC-5(3)(b), SC-7a, SC-7(24)(b), SC-18b, SC-43b, and SI-4. Related Controls:  AC-2, AC-6, AC-17, AT-4, AU-6, AU-13, CA-2, CA-5, CA-6, CM-3, CM-4, CM-6, CM-11, IA-5, IR-5, MA-2, MA-3, MA-4, PE-3, PE-6, PE-14, PE-16, PE-20, PL-2, PM-4, PM-6, PM-9, PM-10, PM-12, PM-14, PM-23, PM-28, PM-31, PS-7, PT-7, RA-3, RA-5, RA-7, RA-10, SA-8, SA-9, SA-11, SC-5, SC-7, SC-18, SC-38, SC-43, SI-3, SI-4, SI-12, SR-6. Control Enhancements: (1) CONTINUOUS MONITORING | INDEPENDENT ASSESSMENT Employ independent assessors or assessment teams to monitor the controls in the system on an ongoing basis.', 'vec_doc-14-nist-sp-800-53-p118-433', 0, 236, 'v2.1.0', '42637c77520f136fcbeb49641727e64859af2b23edc0f3d3508bbed38c9c506d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 91","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":433,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 91"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p118-434', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 91', 118, 'Discussion:  Organizations maximize the value of control assessments by requiring that assessments be conducted by assessors with appropriate levels of independence. The level of required independence is based on organizational continuous monitoring strategies. Assessor independence provides a degree of impartiality to the monitoring process. To achieve such impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in advocacy positions for the organizations acquiring their services. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p118-434', 0, 177, 'v2.1.0', '61fcbd9baf789a27d14460c0788c6f91505875f608e01c5fbdd84f830c10ebe6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 91","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":434,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 91"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p118-435', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 91', 118, '(2) CONTINUOUS MONITORING | TYPES OF ASSESSMENTS [Withdrawn: Incorporated into CA-2.] (3) CONTINUOUS MONITORING | TREND ANALYSES Employ trend analyses to determine if control implementations, the frequency of continuous monitoring activities, and the types of activities used in the continuous monitoring process need to be modified based on empirical data.', 'vec_doc-14-nist-sp-800-53-p118-435', 0, 90, 'v2.1.0', 'df1134f7726841fd9394c534c7cefca16a1990de4433e8d66e1c1f820bb3db50', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 91","subsection":"UNKNOWN","table_id":null,"page":118,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":435,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 91"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p119-436', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 92', 119, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Trend analyses include examining recent threat information that addresses the types of threat events that have occurred in the organization or the Federal Government, success rates of certain types of attacks, emerging vulnerabilities in technologies, evolving social engineering techniques, the effectiveness of configuration settings, results from multiple control assessments, and findings from Inspectors General or auditors. Related Controls:  None. (4) CONTINUOUS MONITORING | RISK MONITORING Ensure risk monitoring is an integral part of the continuous monitoring strategy that includes the following: (a) Effectiveness monitoring; (b) Compliance monitoring; and (c) Change monitoring. Discussion:  Risk monitoring is informed by the established organizational risk tolerance. Effectiveness monitoring determines the ongoing effectiveness of the implemented risk response measures.', 'vec_doc-14-nist-sp-800-53-p119-436', 0, 249, 'v2.1.0', '957415a8595aa2edab818a2be97904e215fa2008084bfac15a80847c690efc7b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 92","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":436,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 92"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p119-437', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 92', 119, 'Compliance monitoring verifies that required risk response measures are implemented. It also verifies that security and privacy requirements are satisfied. Change monitoring identifies changes to organizational systems and environments of operation that may affect security and privacy risk. Related Controls:  None. (5) CONTINUOUS MONITORING | CONSISTENCY ANALYSIS Employ the following actions to validate that policies are established and implemented controls are operating in a consistent manner: [Assignment: organization-defined actions]. Discussion:  Security and privacy controls are often added incrementally to a system. As a result, policies for selecting and implementing controls may be inconsistent, and the controls could fail to work together in a consistent or coordinated manner. At a minimum, the lack of consistency and coordination could mean that there are unacceptable security and privacy gaps in the system.', 'vec_doc-14-nist-sp-800-53-p119-437', 0, 233, 'v2.1.0', '456552498adb7be7709d26465c502de6a430709d45ada59b5c76624d5493b9e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 92","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":437,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 92"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p119-438', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 92', 119, 'At worst, it could mean that some of the controls implemented in one location or by one component are actually impeding the functionality of other controls (e.g., encrypting internal network traffic can impede monitoring). In other situations, failing to consistently monitor all implemented network protocols (e.g., a dual stack of IPv4 and IPv6) may create unintended vulnerabilities in the system that could be exploited by adversaries. It is important to validate— through testing, monitoring, and analysis— that the implemented controls are operating in a consistent, coordinated, non-interfering manner. Related Controls:  None. (6) CONTINUOUS MONITORING | AUTOMATION SUPPORT FOR MONITORING Ensure the accuracy, currency, and availability of monitoring results for the system using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p119-438', 0, 211, 'v2.1.0', '506d03cf6e332002995666857708c88aa50aab79bfcdf996090445cfbb343a15', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 92","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":438,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 92"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p119-439', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 92', 119, 'Discussion:  Using automated tools for monitoring helps to maintain the accuracy, currency, and availability of monitoring information which in turns helps to increase the level of ongoing awareness of the system security and privacy posture in support of organizational risk management decisions. Related Controls:  None. References:  [OMB A-130], [SP 800-37], [SP 800-39], [SP 800-53A], [SP 800-115],[SP 800-137], [IR 8011-1], [IR 8062].', 'vec_doc-14-nist-sp-800-53-p119-439', 0, 110, 'v2.1.0', '1dcda9b41649b9db6d5f86a0de36b7c90c8a71c0851cf5a6270b14d9af37de67', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 92","subsection":"UNKNOWN","table_id":null,"page":119,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":439,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 92"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p120-440', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 93', 120, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 CA-8 PENETRATION TESTING Control:  Conduct penetration testing [Assignment: organization-defined frequency] on [Assignment: organization-defined systems or system components]. Discussion:  Penetration testing is a specialized type of assessment conducted on systems or individual system components to identify vulnerabilities that could be exploited by adversaries. Penetration testing goes beyond automated vulnerability scanning and is conducted by agents and teams with demonstrable skills and experience that include technical expertise in network, operating system, and/or application level security. Penetration testing can be used to validate vulnerabilities or determine the degree of penetration resistance of systems to adversaries within specified constraints. Such constraints include time, resources, and skills.', 'vec_doc-14-nist-sp-800-53-p120-440', 0, 230, 'v2.1.0', '5071729a496f043fb93f9604828b477cd795960ffe5b0c40f31765d759c062b7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 93","subsection":"UNKNOWN","table_id":null,"page":120,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":440,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 93"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p120-441', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 93', 120, 'Penetration testing attempts to duplicate the actions of adversaries and provides a more in-depth analysis of security- and privacy-related weaknesses or deficiencies. Penetration testing is especially important when organizations are transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Organizations can use the results of vulnerability analyses to support penetration testing activities. Penetration testing can be conducted internally or externally on the hardware, software, or firmware components of a system and can exercise both physical and technical controls. A standard method for penetration testing includes a pretest analysis based on full knowledge of the system, pretest identification of potential vulnerabilities based on the pretest analysis, and testing designed to determine the exploitability of vulnerabilities. All parties agree to the rules of engagement before commencing penetration testing scenarios.', 'vec_doc-14-nist-sp-800-53-p120-441', 0, 249, 'v2.1.0', 'a3bd2472104532e3304d70b9c37c4d7c1c7e8b3696818853d31cbdf756b1f6c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 93","subsection":"UNKNOWN","table_id":null,"page":120,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":441,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 93"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p120-442', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 93', 120, 'Organizations correlate the rules of engagement for the penetration tests with the tools, techniques, and procedures that are anticipated to be employed by adversaries. Penetration testing may result in the exposure of information that is protected by laws or regulations, to individuals conducting the testing. Rules of engagement, contracts, or other appropriate mechanisms can be used to communicate expectations for how to protect this information. Risk assessments guide the decisions on the level of independence required for the personnel conducting penetration testing. Related Controls:  RA-5, RA-10, SA-11, SR-5, SR-6. Control Enhancements: (1) PENETRATION TESTING | INDEPENDENT PENETRATION TESTING AGENT OR TEAM Employ an independent penetration testing agent or team to perform penetration testing on the system or system components. Discussion:  Independent penetration testing agents or teams are individuals or groups who conduct impartial penetration testing of organizational systems.', 'vec_doc-14-nist-sp-800-53-p120-442', 0, 251, 'v2.1.0', 'f33a8082cf02eb8294f51900133dd89fc8ee9ffc0f757bfe9b69b8ec2eb56dd0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 93","subsection":"UNKNOWN","table_id":null,"page":120,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":442,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 93"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p120-443', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 93', 120, 'Impartiality implies that penetration testing agents or teams are free from perceived or actual conflicts of interest with respect to the development, operation, or management of the systems that are the targets of the penetration testing. CA-2(1) provides additional information on independent assessments that can be applied to penetration testing. Related Controls:  CA-2. (2) PENETRATION TESTING | RED TEAM EXERCISES Employ the following red-team exercises to simulate attempts by adversaries to compromise organizational systems in accordance with applicable rules of engagement: [Assignment: organization-defined red team exercises]. Discussion:  Red team exercises extend the objectives of penetration testing by examining the security and privacy posture of organizations and the capability to implement effective cyber defenses. Red team exercises simulate attempts by adversaries to compromise mission and business functions and provide a comprehensive assessment of the security and', 'vec_doc-14-nist-sp-800-53-p120-443', 0, 249, 'v2.1.0', '3fa531f36cc291c662ef02914e86270f7d59442e5e18839336e57214af66ecd7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 93","subsection":"UNKNOWN","table_id":null,"page":120,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":443,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 93"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p121-444', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 94', 121, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 privacy posture of systems and organizations. Such attempts may include technology-based attacks and social engineering-based attacks. Technology-based attacks include interactions with hardware, software, or firmware components and/or mission and business processes. Social engineering-based attacks include interactions via email, telephone, shoulder surfing, or personal conversations. Red team exercises are most effective when conducted by penetration testing agents and teams with knowledge of and experience with current adversarial tactics, techniques, procedures, and tools. While penetration testing may be primarily laboratory-based testing, organizations can use red team exercises to provide more comprehensive assessments that reflect real-world conditions.', 'vec_doc-14-nist-sp-800-53-p121-444', 0, 216, 'v2.1.0', '2e53c6a38fbb2df6dd75a58e6622f0b8a4f43c299f1586460f53d688cc047579', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 94","subsection":"UNKNOWN","table_id":null,"page":121,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":444,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 94"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p121-445', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 94', 121, 'The results from red team exercises can be used by organizations to improve security and privacy awareness and training and to assess control effectiveness. Related Controls:  None. (3) PENETRATION TESTING | FACILITY PENETRATION TESTING Employ a penetration testing process that includes [Assignment: organization-defined frequency] [Selection: announced; unannounced] attempts to bypass or circumvent controls associated with physical access points to the facility. Discussion:  Penetration testing of physical access points can provide information on critical vulnerabilities in the operating environments of organizational systems. Such information can be used to correct weaknesses or deficiencies in physical controls that are necessary to protect organizational systems. Related Controls:  CA-2, PE-3. References:  None. CA-9 INTERNAL SYSTEM CONNECTIONS Control: a. Authorize internal connections of [Assignment: organization-defined system components or classes of components] to the system; b.', 'vec_doc-14-nist-sp-800-53-p121-445', 0, 251, 'v2.1.0', '0ba5923b8cae4e5107603e0c0abbdd0c1502debc2908ad510e20dab357b9ca87', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 94","subsection":"UNKNOWN","table_id":null,"page":121,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":445,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 94"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p121-446', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 94', 121, 'Document, for each internal connection, the interface characteristics, security and privacy requirements, and the nature of the information communicated; c. Terminate internal system connections after [Assignment: organization-defined conditions]; and d. Review [Assignment: organization-defined frequency] the continued need for each internal connection. Discussion:  Internal system connections are connections between organizational systems and separate constituent system components (i.e., connections between components that are part of the same system) including components used for system development. Intra-system connections include connections with mobile devices, notebook and desktop computers, tablets, printers, copiers, facsimile machines, scanners, sensors, and servers.', 'vec_doc-14-nist-sp-800-53-p121-446', 0, 197, 'v2.1.0', '7da7a33e2e9511508bc9710ecab94b3d5dc6bfb07873272c5e18c9a5b23b6a81', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 94","subsection":"UNKNOWN","table_id":null,"page":121,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":446,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 94"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p121-447', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 94', 121, 'Instead of authorizing each internal system connection individually, organizations can authorize internal connections for a class of system components with common characteristics and/or configurations, including printers, scanners, and copiers with a specified processing, transmission, and storage capability or smart phones and tablets with a specific baseline configuration. The continued need for an internal system connection is reviewed from the perspective of whether it provides support for organizational missions or business functions. Related Controls:  AC-3, AC-4, AC-18, AC-19, CM-2, IA-3, SC-7, SI-12. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p121-447', 0, 160, 'v2.1.0', '4315531d5137f6ec149f871f64c1bbbc530a2a97270bcb934e82e238d5faa26f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 94","subsection":"UNKNOWN","table_id":null,"page":121,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":447,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 94"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p122-448', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 95', 122, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) INTERNAL SYSTEM CONNECTIONS | COMPLIANCE CHECKS Perform security and privacy compliance checks on constituent system components prior to the establishment of the internal connection. Discussion:  Compliance checks include verification of the relevant baseline configuration. Related Controls:  CM-6. References:  [SP 800-124], [IR 8023].', 'vec_doc-14-nist-sp-800-53-p122-448', 0, 109, 'v2.1.0', 'adfc29b6fbb3fb4aabe822e3545955c3260b407494eba240a19662c333e1ab0e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 95","subsection":"UNKNOWN","table_id":null,"page":122,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":448,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 95"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p123-449', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.5   CONFIGURATION MANAGEMENT', 123, 'Quick link to Configuration Management Summary Table CM-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p123-449', 0, 46, 'v2.1.0', '39f2c151ac49cddb408e11432fa9e0c8184b8d349a972dd6fe9751197e709b30', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.5   CONFIGURATION MANAGEMENT","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":449,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.5   CONFIGURATION MANAGEMENT"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p123-450', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 123, 'level] configuration management policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p123-450', 0, 78, 'v2.1.0', 'a60597427c97189d69f3ac70b8c57c5bfcc60f9f9651febd9ffc555d79e29ec8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":450,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p123-451', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the configuration management policy', 123, 'and the associated configuration management controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the configuration management policy and procedures; and c. Review and update the current configuration management:', 'vec_doc-14-nist-sp-800-53-p123-451', 0, 73, 'v2.1.0', '8827a9ce5c14ffc572cf93eda4d06837d3cae718da9d4f5b4839abad38c448d8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the configuration management policy","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":451,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the configuration management policy"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p123-452', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 123, 'organization-defined events]. Discussion:  Configuration management policy and procedures address the controls in the CM family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of configuration management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to configuration management policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SA-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p123-452', 0, 440, 'v2.1.0', '967f457d9c8038d4ad7bb923c534128f226e09735d065784099fb69c63199d3a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":123,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":452,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p124-453', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 97', 124, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 CM-2 BASELINE CONFIGURATION Control: a. Develop, document, and maintain under configuration control, a current baseline configuration of the system; and b. Review and update the baseline configuration of the system:', 'vec_doc-14-nist-sp-800-53-p124-453', 0, 77, 'v2.1.0', '84beb53804a58f7b44d1ce97557541eb3f238aecff6309babd5c0440e9e1a2da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 97","subsection":"UNKNOWN","table_id":null,"page":124,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":453,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 97"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p124-454', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. When system components are installed or upgraded.', 124, 'Discussion:  Baseline configurations for systems and system components include connectivity, operational, and communications aspects of systems. Baseline configurations are documented, formally reviewed, and agreed-upon specifications for systems or configuration items within those systems. Baseline configurations serve as a basis for future builds, releases, or changes to systems and include security and privacy control implementations, operational procedures, information about system components, network topology, and logical placement of components in the system architecture. Maintaining baseline configurations requires creating new baselines as organizational systems change over time. Baseline configurations of systems reflect the current enterprise architecture. Related Controls:  AC-19, AU-6, CA-9, CM-1, CM-3, CM-5, CM-6, CM-8, CM-9, CP-9, CP-10, CP-12, MA-2, PL-8, PM-5, SA-8, SA-10, SA-15, SC-18.', 'vec_doc-14-nist-sp-800-53-p124-454', 0, 229, 'v2.1.0', '63896fb69ca02181067297d3d5f03ff91b71ea1c1deb092e101e4b0add94a9fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. When system components are installed or upgraded.","subsection":"UNKNOWN","table_id":null,"page":124,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":454,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. When system components are installed or upgraded."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p124-455', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. When system components are installed or upgraded.', 124, 'Control Enhancements: (1) BASELINE CONFIGURATION | REVIEWS AND UPDATES [Withdrawn: Incorporated into CM-2.] (2) BASELINE CONFIGURATION | AUTOMATION SUPPORT FOR ACCURACY AND CURRENCY Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms that help organizations maintain consistent baseline configurations for systems include configuration management tools, hardware, software, firmware inventory tools, and network management tools. Automated tools can be used at the organization level, mission and business process level, or system level on workstations, servers, notebook computers, network components, or mobile devices. Tools can be used to track version numbers on operating systems, applications, types of software installed, and current patch levels.', 'vec_doc-14-nist-sp-800-53-p124-455', 0, 227, 'v2.1.0', 'da9dee55983d703c51badde2947ad034d921e673f74207f396438f4db60129cb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. When system components are installed or upgraded.","subsection":"UNKNOWN","table_id":null,"page":124,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":455,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. When system components are installed or upgraded."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p124-456', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. When system components are installed or upgraded.', 124, 'Automation support for accuracy and currency can be satisfied by the implementation of CM-8(2) for organizations that combine system component inventory and baseline configuration activities. Related Controls:  CM-7, IA-3, RA-5. (3) BASELINE CONFIGURATION | RETENTION OF PREVIOUS CONFIGURATIONS Retain [Assignment: organization-defined number] of previous versions of baseline configurations of the system to support rollback. Discussion:  Retaining previous versions of baseline configurations to support rollback include hardware, software, firmware, configuration files, configuration records, and associated documentation. Related Controls:  None. (4) BASELINE CONFIGURATION | UNAUTHORIZED SOFTWARE', 'vec_doc-14-nist-sp-800-53-p124-456', 0, 176, 'v2.1.0', '239686eaaa9dd8a1b635785f18f40c0f8514e29c261331b40b31c14fadfe8eb2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. When system components are installed or upgraded.","subsection":"UNKNOWN","table_id":null,"page":124,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":456,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. When system components are installed or upgraded."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p125-457', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 98', 125, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Incorporated into CM-7(4).] (5) BASELINE CONFIGURATION | AUTHORIZED SOFTWARE [Withdrawn: Incorporated into CM-7(5).] (6) BASELINE CONFIGURATION | DEVELOPMENT AND TEST ENVIRONMENTS Maintain a baseline configuration for system development and test environments that is managed separately from the operational baseline configuration. Discussion:  Establishing separate baseline configurations for development, testing, and operational environments protects systems from unplanned or unexpected events related to development and testing activities. Separate baseline configurations allow organizations to apply the configuration management that is most appropriate for each type of configuration. For example, the management of operational configurations typically emphasizes the need for stability, while the management of development or test configurations requires greater flexibility.', 'vec_doc-14-nist-sp-800-53-p125-457', 0, 247, 'v2.1.0', '7b24eaf8034392c61b35b3e96a9a1bf7f91d0db991d625e9e268863e5b81cb7a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 98","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":457,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 98"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p125-458', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 98', 125, 'Configurations in the test environment mirror configurations in the operational environment to the extent practicable so that the results of the testing are representative of the proposed changes to the operational systems. Separate baseline configurations do not necessarily require separate physical environments. Related Controls:  CM-4, SC-3, SC-7. (7) BASELINE CONFIGURATION | CONFIGURE SYSTEMS AND COMPONENTS FOR HIGH-RISK AREAS (a) Issue [Assignment: organization-defined systems or system components] with [Assignment: organization-defined configurations] to individuals traveling to locations that the organization deems to be of significant risk; and (b) Apply the following controls to the systems or components when the individuals return from travel: [Assignment: organization-defined controls].', 'vec_doc-14-nist-sp-800-53-p125-458', 0, 202, 'v2.1.0', '942e148499e5fbf01c771009e9b94ae0a7118b35a0be720666a500ba87c0edbd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 98","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":458,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 98"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p125-459', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 98', 125, 'Discussion:  When it is known that systems or system components will be in high-risk areas external to the organization, additional controls may be implemented to counter the increased threat in such areas. For example, organizations can take actions for notebook computers used by individuals departing on and returning from travel. Actions include determining the locations that are of concern, defining the required configurations for the components, ensuring that components are configured as intended before travel is initiated, and applying controls to the components after travel is completed. Specially configured notebook computers include computers with sanitized hard drives, limited applications, and more stringent configuration settings. Controls applied to mobile devices upon return from travel include examining the mobile device for signs of physical tampering and purging and reimaging disk drives.', 'vec_doc-14-nist-sp-800-53-p125-459', 0, 230, 'v2.1.0', '1ca2ba50a01160e49ee6d60ee5179ef3750c2c4b5277f795b45e887691bb9b94', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 98","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":459,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 98"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p125-460', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 98', 125, 'Protecting information that resides on mobile devices is addressed in the MP (Media Protection) family. Related Controls:  MP-4, MP-5. References:  [SP 800-124], [SP 800-128]. CM-3 CONFIGURATION CHANGE CONTROL Control: a. Determine and document the types of changes to the system that are configuration- controlled; b. Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses; c. Document configuration change decisions associated with the system; d. Implement approved configuration-controlled changes to the system;', 'vec_doc-14-nist-sp-800-53-p125-460', 0, 158, 'v2.1.0', 'f5e903cec7a88e8c0a7c5ef1a5d96d7ea375c96d9d1eeefd31dc54285b2f7f3c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 98","subsection":"UNKNOWN","table_id":null,"page":125,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":460,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 98"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p126-461', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 99', 126, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 e. Retain records of configuration-controlled changes to the system for [Assignment: organization-defined time period]; f. Monitor and review activities associated with configuration-controlled changes to the system; and g. Coordinate and provide oversight for configuration change control activities through [Assignment: organization-defined configuration change control element] that convenes [Selection (one or more): [Assignment: organization-defined frequency]; when [Assignment: organization-defined configuration change conditions]]. Discussion:  Configuration change control for organizational systems involves the systematic proposal, justification, implementation, testing, review, and disposition of system changes, including system upgrades and modifications.', 'vec_doc-14-nist-sp-800-53-p126-461', 0, 216, 'v2.1.0', '95d6c27e4cf9af879365276920682ab7a1bbdb0017b4cd7df3916c61165479da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 99","subsection":"UNKNOWN","table_id":null,"page":126,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":461,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 99"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p126-462', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 99', 126, 'Configuration change control includes changes to baseline configurations, configuration items of systems, operational procedures, configuration settings for system components, remediate vulnerabilities, and unscheduled or unauthorized changes. Processes for managing configuration changes to systems include Configuration Control Boards or Change Advisory Boards that review and approve proposed changes. For changes that impact privacy risk, the senior agency official for privacy updates privacy impact assessments and system of records notices. For new systems or major upgrades, organizations consider including representatives from the development organizations on the Configuration Control Boards or Change Advisory Boards. Auditing of changes includes activities before and after changes are made to systems and the auditing activities required to implement such changes. See also SA-10.', 'vec_doc-14-nist-sp-800-53-p126-462', 0, 224, 'v2.1.0', '49785713776f773d89ee648fd52f302d860eb96384002875fe3fe5e66e91f2ad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 99","subsection":"UNKNOWN","table_id":null,"page":126,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":462,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 99"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p126-463', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 99', 126, 'Related Controls:  CA-7, CM-2, CM-4, CM-5, CM-6, CM-9, CM-11, IA-3, MA-2, PE-16, PT-6, RA-8, SA-8, SA-10, SC-28, SC-34, SC-37, SI-2, SI-3, SI-4, SI-7, SI-10, SR-11. Control Enhancements: (1) CONFIGURATION CHANGE CONTROL | AUTOMATED DOCUMENTATION, NOTIFICATION, AND PROHIBITION OF CHANGES Use [Assignment: organization-defined automated mechanisms] to: (a) Document proposed changes to the system; (b) Notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval; (c) Highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period]; (d) Prohibit changes to the system until designated approvals are received; (e) Document all changes to the system; and (f) Notify [Assignment: organization-defined personnel] when approved changes to the system are completed. Discussion:  None. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p126-463', 0, 235, 'v2.1.0', '8a4cc295b506121b68034275ec280f61351dc33018e1e19ccec7db2b57ea4d40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 99","subsection":"UNKNOWN","table_id":null,"page":126,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":463,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 99"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p126-464', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 99', 126, '(2) CONFIGURATION CHANGE CONTROL | TESTING, VALIDATION, AND DOCUMENTATION OF CHANGES Test, validate, and document changes to the system before finalizing the implementation of the changes. Discussion:  Changes to systems include modifications to hardware, software, or firmware components and configuration settings defined in CM-6. Organizations ensure that testing does not interfere with system operations that support organizational mission and business functions. Individuals or groups conducting tests understand security and privacy policies and procedures, system security and privacy policies and procedures, and the health, safety, and environmental risks associated with specific facilities or processes. Operational systems', 'vec_doc-14-nist-sp-800-53-p126-464', 0, 184, 'v2.1.0', '37d4c5a9dba689ac30767c11413305c1979e561108abe36c90e9ba73ee4522d7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 99","subsection":"UNKNOWN","table_id":null,"page":126,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":464,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 99"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p127-465', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 100', 127, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 may need to be taken offline, or replicated to the extent feasible, before testing can be conducted. If systems must be taken offline for testing, the tests are scheduled to occur during planned system outages whenever possible. If the testing cannot be conducted on operational systems, organizations employ compensating controls. Related Controls:  None. (3) CONFIGURATION CHANGE CONTROL | AUTOMATED CHANGE IMPLEMENTATION Implement changes to the current system baseline and deploy the updated baseline across the installed base using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated tools can improve the accuracy, consistency, and availability of configuration baseline information. Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization.', 'vec_doc-14-nist-sp-800-53-p127-465', 0, 247, 'v2.1.0', '2d8b8f10420e4d67a61ef78f6dbee3398335691acc8f908b617cc517bd577da5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 100","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":465,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 100"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p127-466', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 100', 127, 'Related Controls:  None. (4) CONFIGURATION CHANGE CONTROL | SECURITY AND PRIVACY REPRESENTATIVES Require [Assignment: organization-defined security and privacy representatives] to be members of the [Assignment: organization-defined configuration change control element]. Discussion:  Information security and privacy representatives include system security officers, senior agency information security officers, senior agency officials for privacy, or system privacy officers. Representation by personnel with information security and privacy expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems.', 'vec_doc-14-nist-sp-800-53-p127-466', 0, 215, 'v2.1.0', '5636c4df6ef50f153185ff51063478c69c6862d04685cc87b70bc3619f225ee9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 100","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":466,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 100"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p127-467', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 100', 127, 'The configuration change control element referred to in the second organization-defined parameter reflects the change control elements defined by organizations in CM-3g. Related Controls:  None. (5) CONFIGURATION CHANGE CONTROL | AUTOMATED SECURITY RESPONSE Implement the following security responses automatically if baseline configurations are changed in an unauthorized manner: [Assignment: organization-defined security responses]. Discussion:  Automated security responses include halting selected system functions, halting system processing, and issuing alerts or notifications to organizational personnel when there is an unauthorized modification of a configuration item. Related Controls:  None. (6) CONFIGURATION CHANGE CONTROL | CRYPTOGRAPHY MANAGEMENT Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: [Assignment: organization-defined controls].', 'vec_doc-14-nist-sp-800-53-p127-467', 0, 230, 'v2.1.0', '1a3f2f9d6e8a2464cf0c41f62cee41f00ee4cb764f35fff1e5596b536abc4e7d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 100","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":467,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 100"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p127-468', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 100', 127, 'Discussion:  The controls referenced in the control enhancement refer to security and privacy controls from the control catalog. Regardless of the cryptographic mechanisms employed, processes and procedures are in place to manage those mechanisms. For example, if system components use certificates for identification and authentication, a process is implemented to address the expiration of those certificates. Related Controls:  SC-12. (7) CONFIGURATION CHANGE CONTROL | REVIEW SYSTEM CHANGES', 'vec_doc-14-nist-sp-800-53-p127-468', 0, 124, 'v2.1.0', '59cec1596e672ebf4b0bf1ecd52a19f2b89d263a6542d7895d13738064b144d5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 100","subsection":"UNKNOWN","table_id":null,"page":127,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":468,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 100"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p128-469', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 101', 128, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Review changes to the system [Assignment: organization-defined frequency] or when [Assignment: organization-defined circumstances] to determine whether unauthorized changes have occurred. Discussion:  Indications that warrant a review of changes to the system and the specific circumstances justifying such reviews may be obtained from activities carried out by organizations during the configuration change process or continuous monitoring process. Related Controls:  AU-6, AU-7, CM-3. (8) CONFIGURATION CHANGE CONTROL | PREVENT OR RESTRICT CONFIGURATION CHANGES Prevent or restrict changes to the configuration of the system under the following circumstances: [Assignment: organization-defined circumstances]. Discussion:  System configuration changes can adversely affect critical system security and privacy functionality. Change restrictions can be enforced through automated mechanisms.', 'vec_doc-14-nist-sp-800-53-p128-469', 0, 246, 'v2.1.0', '6b2cd03f9eba637d4a08ecf5dd514fed0c6871a80410024b74cb689e9f631ae6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 101","subsection":"UNKNOWN","table_id":null,"page":128,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":469,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 101"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p128-470', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 101', 128, 'Related Controls:  None. References:  [SP 800-124], [SP 800-128], [IR 8062]. CM-4 IMPACT ANALYSES Control:  Analyze changes to the system to determine potential security and privacy impacts prior to change implementation. Discussion:  Organizational personnel with security or privacy responsibilities conduct impact analyses. Individuals conducting impact analyses possess the necessary skills and technical expertise to analyze the changes to systems as well as the security or privacy ramifications.', 'vec_doc-14-nist-sp-800-53-p128-470', 0, 126, 'v2.1.0', 'dc9d687d4555da87dd96924e3c07740069eef28e98e70016ae5fe51d08538067', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 101","subsection":"UNKNOWN","table_id":null,"page":128,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":470,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 101"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p128-471', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 101', 128, 'Impact analyses include reviewing security and privacy plans, policies, and procedures to understand control requirements; reviewing system design documentation and operational procedures to understand control implementation and how specific system changes might affect the controls; reviewing the impact of changes on organizational supply chain partners with stakeholders; and determining how potential changes to a system create new risks to the privacy of individuals and the ability of implemented controls to mitigate those risks. Impact analyses also include risk assessments to understand the impact of the changes and determine if additional controls are required. Related Controls:  CA-7, CM-3, CM-8, CM-9, MA-2, RA-3, RA-5, RA-8, SA-5, SA-8, SA-10, SI-2.', 'vec_doc-14-nist-sp-800-53-p128-471', 0, 192, 'v2.1.0', 'dcb3632afb004a370ad3e6b1125367f61e25499028b6a80c0696e7670b23741d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 101","subsection":"UNKNOWN","table_id":null,"page":128,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":471,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 101"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p128-472', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 101', 128, 'Control Enhancements: (1) IMPACT ANALYSES | SEPARATE TEST ENVIRONMENTS Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice. Discussion:  A separate test environment requires an environment that is physically or logically separate and distinct from the operational environment. The separation is sufficient to ensure that activities in the test environment do not impact activities in the operational environment and that information in the operational environment is not inadvertently transmitted to the test environment. Separate environments can be achieved by physical or logical means. If physically separate test environments are not implemented, organizations determine the strength of mechanism required when implementing logical separation. Related Controls:  SA-11, SC-7. (2) IMPACT ANALYSES | VERIFICATION OF CONTROLS', 'vec_doc-14-nist-sp-800-53-p128-472', 0, 249, 'v2.1.0', 'c987584dba99784acff8d657614370e7d32440ea695e0ec52181a8bf221587ec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 101","subsection":"UNKNOWN","table_id":null,"page":128,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":472,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 101"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p129-473', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 102', 129, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system. Discussion:  Implementation in this context refers to installing changed code in the operational system that may have an impact on security or privacy controls. Related Controls:  SA-11, SC-3, SI-6. References:  [SP 800-128]. CM-5 ACCESS RESTRICTIONS FOR CHANGE Control:  Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system. Discussion:  Changes to the hardware, software, or firmware components of systems or the operational procedures related to the system can potentially have significant effects on the security of the systems or individuals’ privacy.', 'vec_doc-14-nist-sp-800-53-p129-473', 0, 233, 'v2.1.0', 'cb50fd8156028c06f88c5c6b281f53010f10322bdf30408cc7d1f8fbbf97f0e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 102","subsection":"UNKNOWN","table_id":null,"page":129,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":473,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 102"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p129-474', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 102', 129, 'Therefore, organizations permit only qualified and authorized individuals to access systems for purposes of initiating changes. Access restrictions include physical and logical access controls (see AC-3 and PE-3), software libraries, workflow automation, media libraries, abstract layers (i.e., changes implemented into external interfaces rather than directly into systems), and change windows (i.e., changes occur only during specified times). Related Controls:  AC-3, AC-5, AC-6, CM-9, PE-3, SC-28, SC-34, SC-37, SI-2, SI-10. Control Enhancements: (1) ACCESS RESTRICTIONS FOR CHANGE | AUTOMATED ACCESS ENFORCEMENT AND AUDIT RECORDS (a) Enforce access restrictions using [Assignment: organization-defined automated mechanisms]; and (b) Automatically generate audit records of the enforcement actions.', 'vec_doc-14-nist-sp-800-53-p129-474', 0, 201, 'v2.1.0', '84e42b7f6870a7c0139e37987bbb1fcaca0c092523cd8eb0877a06d8931d156d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 102","subsection":"UNKNOWN","table_id":null,"page":129,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":474,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 102"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p129-475', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 102', 129, 'Discussion:  Organizations log system accesses associated with applying configuration changes to ensure that configuration change control is implemented and to support after- the-fact actions should organizations discover any unauthorized changes. Related Controls:  AU-2, AU-6, AU-7, AU-12, CM-6, CM-11, SI-12. (2) ACCESS RESTRICTIONS FOR CHANGE | REVIEW SYSTEM CHANGES [Withdrawn: Incorporated into CM-3(7).] (3) ACCESS RESTRICTIONS FOR CHANGE | SIGNED COMPONENTS [Withdrawn: Moved to CM-14.] (4) ACCESS RESTRICTIONS FOR CHANGE | DUAL AUTHORIZATION Enforce dual authorization for implementing changes to [Assignment: organization- defined system components and system-level information]. Discussion:  Organizations employ dual authorization to help ensure that any changes to selected system components and information cannot occur unless two qualified individuals approve and implement such changes.', 'vec_doc-14-nist-sp-800-53-p129-475', 0, 226, 'v2.1.0', '76fea50c5d7d07dee174642216dfeaad3bb4ae8099e42839efed30e1cac497f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 102","subsection":"UNKNOWN","table_id":null,"page":129,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":475,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 102"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p129-476', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 102', 129, 'The two individuals possess the skills and expertise to determine if the proposed changes are correct implementations of approved changes. The individuals are also accountable for the changes. Dual authorization may also be known as two-person control. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals. System-level information includes operational procedures. Related Controls:  AC-2, AC-5, CM-3.', 'vec_doc-14-nist-sp-800-53-p129-476', 0, 115, 'v2.1.0', 'f9f59bcbc6f82f03aafd8848362acf09c09a881d5b1e1ad2efd3e409e45968e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 102","subsection":"UNKNOWN","table_id":null,"page":129,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":476,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 102"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p130-477', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 103', 130, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (5) ACCESS RESTRICTIONS FOR CHANGE | PRIVILEGE LIMITATION FOR PRODUCTION AND OPERATION (a) Limit privileges to change system components and system-related information within a production or operational environment; and (b) Review and reevaluate privileges [Assignment: organization-defined frequency]. Discussion:  In many organizations, systems support multiple mission and business functions. Limiting privileges to change system components with respect to operational systems is necessary because changes to a system component may have far-reaching effects on mission and business processes supported by the system. The relationships between systems and mission/business processes are, in some cases, unknown to developers. System-related information includes operational procedures. Related Controls:  AC-2.', 'vec_doc-14-nist-sp-800-53-p130-477', 0, 226, 'v2.1.0', '15df84a9ada9803a8d7645eb17c25d0676a733db140227e96a17850e33d2fbde', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 103","subsection":"UNKNOWN","table_id":null,"page":130,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":477,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 103"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p130-478', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 103', 130, '(6) ACCESS RESTRICTIONS FOR CHANGE | LIMIT LIBRARY PRIVILEGES Limit privileges to change software resident within software libraries. Discussion:  Software libraries include privileged programs. Related Controls:  AC-2. (7) ACCESS RESTRICTIONS FOR CHANGE | AUTOMATIC IMPLEMENTATION OF SECURITY SAFEGUARDS [Withdrawn: Incorporated into SI-7.] References:  [FIPS 140-3];  [FIPS 186-4]. CM-6 CONFIGURATION SETTINGS Control: a. Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using [Assignment: organization-defined common secure configurations]; b. Implement the configuration settings; c. Identify, document, and approve any deviations from established configuration settings for [Assignment: organization-defined system components] based on [Assignment: organization- defined operational requirements]; and d.', 'vec_doc-14-nist-sp-800-53-p130-478', 0, 232, 'v2.1.0', 'cb2416c4a28679c6c3d9bdbae238623e7fd4fbe57fb9066c8d7ff986959e055c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 103","subsection":"UNKNOWN","table_id":null,"page":130,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":478,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 103"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p130-479', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 103', 130, 'Monitor and control changes to the configuration settings in accordance with organizational policies and procedures. Discussion:  Configuration settings are the parameters that can be changed in the hardware, software, or firmware components of the system that affect the security and privacy posture or functionality of the system. Information technology products for which configuration settings can be defined include mainframe computers, servers, workstations, operating systems, mobile devices, input/output devices, protocols, and applications. Parameters that impact the security posture of systems include registry settings; account, file, or directory permission settings; and settings for functions, protocols, ports, services, and remote connections. Privacy parameters are parameters impacting the privacy posture of systems, including the parameters required to satisfy other privacy controls.', 'vec_doc-14-nist-sp-800-53-p130-479', 0, 227, 'v2.1.0', 'ef9371f9ba0285d5329f90802616c7d689c9f045a483aa635106f2c1c263d5a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 103","subsection":"UNKNOWN","table_id":null,"page":130,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":479,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 103"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p130-480', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 103', 130, 'Privacy parameters include settings for access controls, data processing preferences, and processing and retention permissions. Organizations establish organization-wide configuration settings and subsequently derive specific configuration settings for systems. The established settings become part of the configuration baseline for the system. Common secure configurations (also known as security configuration checklists, lockdown and hardening guides, and security reference guides) provide recognized, standardized, and established benchmarks that stipulate secure configuration settings for information technology', 'vec_doc-14-nist-sp-800-53-p130-480', 0, 155, 'v2.1.0', 'd5fa1ebd6c274c8a0ec30ce5edcccce463a447f94e08b5bca0b969281e28f67a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 103","subsection":"UNKNOWN","table_id":null,"page":130,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":480,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 103"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p131-481', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 104', 131, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 products and platforms as well as instructions for configuring those products or platforms to meet operational requirements. Common secure configurations can be developed by a variety of organizations, including information technology product developers, manufacturers, vendors, federal agencies, consortia, academia, industry, and other organizations in the public and private sectors. Implementation of a common secure configuration may be mandated at the organization level, mission and business process level, system level, or at a higher level, including by a regulatory agency. Common secure configurations include the United States Government Configuration Baseline [USGCB] and security technical implementation guides (STIGs), which affect the implementation of CM-6 and other controls such as AC-19 and CM-7.', 'vec_doc-14-nist-sp-800-53-p131-481', 0, 228, 'v2.1.0', '33eae3ab6092ad0a64c55397f62f0d4d562c0dc1ebbe46e4343fe123d744e2f3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 104","subsection":"UNKNOWN","table_id":null,"page":131,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":481,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 104"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p131-482', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 104', 131, 'The Security Content Automation Protocol (SCAP) and the defined standards within the protocol provide an effective method to uniquely identify, track, and control configuration settings. Related Controls:  AC-3, AC-19, AU-2, AU-6, CA-9, CM-2, CM-3, CM-5, CM-7, CM-11, CP-7, CP-9, CP-10, IA-3, IA-5, PL-8, PL-9, RA-5, SA-4, SA-5, SA-8, SA-9, SC-18, SC-28, SC-43, SI-2, SI-4, SI-6. Control Enhancements: (1) CONFIGURATION SETTINGS | AUTOMATED MANAGEMENT, APPLICATION, AND VERIFICATION Manage, apply, and verify configuration settings for [Assignment: organization-defined system components] using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated tools (e.g., hardening tools, baseline configuration tools) can improve the accuracy, consistency, and availability of configuration settings information.', 'vec_doc-14-nist-sp-800-53-p131-482', 0, 208, 'v2.1.0', '6ef08eba6a0d48453c57758aa3e5b3382679f6ef1e521bd9d85ebf7e7b544a9e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 104","subsection":"UNKNOWN","table_id":null,"page":131,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":482,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 104"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p131-483', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 104', 131, 'Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization. Related Controls:  CA-7. (2) CONFIGURATION SETTINGS | RESPOND TO UNAUTHORIZED CHANGES Take the following actions in response to unauthorized changes to [Assignment: organization-defined configuration settings]: [Assignment: organization-defined actions]. Discussion:  Responses to unauthorized changes to configuration settings include alerting designated organizational personnel, restoring established configuration settings, or— in extreme cases— halting affected system processing. Related Controls:  IR-4, IR-6, SI-7. (3) CONFIGURATION SETTINGS | UNAUTHORIZED CHANGE DETECTION [Withdrawn: Incorporated into SI-7.] (4) CONFIGURATION SETTINGS | CONFORMANCE DEMONSTRATION [Withdrawn: Incorporated into CM-4.] References:  [SP 800-70], [SP 800-126], [SP 800-128], [USGCB], [NCPR], [DOD STIG].', 'vec_doc-14-nist-sp-800-53-p131-483', 0, 243, 'v2.1.0', 'c217117e6be16f89ffb90c3fff1b9aa7c17030a658108c3d48b4200927850aa2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 104","subsection":"UNKNOWN","table_id":null,"page":131,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":483,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 104"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p131-484', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 104', 131, 'CM-7 LEAST FUNCTIONALITY Control: a. Configure the system to provide only [Assignment: organization-defined mission essential capabilities]; and b. Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: [Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services].', 'vec_doc-14-nist-sp-800-53-p131-484', 0, 93, 'v2.1.0', '639d9acc45090e4c48119989d0e5cca68bc3f047b8256116962d08328780cd7f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 104","subsection":"UNKNOWN","table_id":null,"page":131,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":484,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 104"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p132-485', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 105', 132, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Systems provide a wide variety of functions and services. Some of the functions and services routinely provided by default may not be necessary to support essential organizational missions, functions, or operations. Additionally, it is sometimes convenient to provide multiple services from a single system component, but doing so increases risk over limiting the services provided by that single component. Where feasible, organizations limit component functionality to a single function per component. Organizations consider removing unused or unnecessary software and disabling unused or unnecessary physical and logical ports and protocols to prevent unauthorized connection of components, transfer of information, and tunneling.', 'vec_doc-14-nist-sp-800-53-p132-485', 0, 210, 'v2.1.0', 'ae49739c5dfe9fb3055018aa2266f33344f69f62c6e5ad3c9e6c5050acb6bd83', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 105","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":485,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 105"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p132-486', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 105', 132, 'Organizations employ network scanning tools, intrusion detection and prevention systems, and end-point protection technologies, such as firewalls and host-based intrusion detection systems, to identify and prevent the use of prohibited functions, protocols, ports, and services. Least functionality can also be achieved as part of the fundamental design and development of the system (see SA- 8, SC-2, and SC-3). Related Controls:  AC-3, AC-4, CM-2, CM-5, CM-6, CM-11, RA-5, SA-4, SA-5, SA-8, SA-9, SA-15, SC- 2, SC-3, SC-7, SC-37, SI-4. Control Enhancements: (1) LEAST FUNCTIONALITY | PERIODIC REVIEW (a) Review the system [Assignment: organization-defined frequency] to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and (b) Disable or remove [Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure].', 'vec_doc-14-nist-sp-800-53-p132-486', 0, 234, 'v2.1.0', '7becc6dbbdcba69083dee1c03648e84def064a68ca17a4a043b988bad24f2eaf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 105","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":486,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 105"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p132-487', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 105', 132, 'Discussion:  Organizations review functions, ports, protocols, and services provided by systems or system components to determine the functions and services that are candidates for elimination. Such reviews are especially important during transition periods from older technologies to newer technologies (e.g., transition from IPv4 to IPv6). These technology transitions may require implementing the older and newer technologies simultaneously during the transition period and returning to minimum essential functions, ports, protocols, and services at the earliest opportunity. Organizations can either decide the relative security of the function, port, protocol, and/or service or base the security decision on the assessment of other entities. Unsecure protocols include Bluetooth, FTP, and peer-to-peer networking. Related Controls:  AC-18.', 'vec_doc-14-nist-sp-800-53-p132-487', 0, 212, 'v2.1.0', 'a26fd3ff4e8d0d713058307ba0c775468b5bba4cb10e2eab63f9d77336351a36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 105","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":487,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 105"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p132-488', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 105', 132, '(2) LEAST FUNCTIONALITY | PREVENT PROGRAM EXECUTION Prevent program execution in accordance with [Selection (one or more): [Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage]. Discussion:  Prevention of program execution addresses organizational policies, rules of behavior, and/or access agreements that restrict software usage and the terms and conditions imposed by the developer or manufacturer, including software licensing and copyrights. Restrictions include prohibiting auto-execute features, restricting roles allowed to approve program execution, permitting or prohibiting specific software programs, or restricting the number of program instances executed at the same time. Related Controls:  CM-8, PL-4, PL-9, PM-5, PS-6.', 'vec_doc-14-nist-sp-800-53-p132-488', 0, 223, 'v2.1.0', 'b41b50b5be1a9e9af6fb31307c1f2a815f48c3dd20cf5de4b36a3446fd235e7d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 105","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":488,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 105"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p132-489', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 105', 132, '(3) LEAST FUNCTIONALITY | REGISTRATION COMPLIANCE Ensure compliance with [Assignment: organization-defined registration requirements for functions, ports, protocols, and services].', 'vec_doc-14-nist-sp-800-53-p132-489', 0, 45, 'v2.1.0', 'fe1c5ae78a18a656fb3e3a8393bc6847721ed7cf380f6ebb2f07839ef31e24c8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 105","subsection":"UNKNOWN","table_id":null,"page":132,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":489,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 105"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p133-490', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 106', 133, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Organizations use the registration process to manage, track, and provide oversight for systems and implemented functions, ports, protocols, and services. Related Controls:  None. (4) LEAST FUNCTIONALITY | UNAUTHORIZED SOFTWARE —  DENY-BY-EXCEPTION (a) Identify [Assignment: organization-defined software programs not authorized to execute on the system]; (b) Employ an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the system; and (c) Review and update the list of unauthorized software programs [Assignment: organization-defined frequency]. Discussion:  Unauthorized software programs can be limited to specific versions or from a specific source. The concept of prohibiting the execution of unauthorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses.', 'vec_doc-14-nist-sp-800-53-p133-490', 0, 247, 'v2.1.0', 'f0e779b528edc8716115e00ff653447fd7819048de8bea237affce479888820f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 106","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":490,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 106"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p133-491', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 106', 133, 'Related Controls:  CM-6, CM-8, CM-10, PL-9, PM-5. (5) LEAST FUNCTIONALITY | AUTHORIZED SOFTWARE —  ALLOW-BY-EXCEPTION (a) Identify [Assignment: organization-defined software programs authorized to execute on the system]; (b) Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and (c) Review and update the list of authorized software programs [Assignment: organization-defined frequency]. Discussion:  Authorized software programs can be limited to specific versions or from a specific source. To facilitate a comprehensive authorized software process and increase the strength of protection for attacks that bypass application level authorized software, software programs may be decomposed into and monitored at different levels of detail.', 'vec_doc-14-nist-sp-800-53-p133-491', 0, 202, 'v2.1.0', '9d0c12cb46a83502f1fc64daf360c3f4c08ad0ecf05fc9f74fc109f21b64e783', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 106","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":491,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 106"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p133-492', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 106', 133, 'These levels include applications, application programming interfaces, application modules, scripts, system processes, system services, kernel functions, registries, drivers, and dynamic link libraries. The concept of permitting the execution of authorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses. Organizations consider verifying the integrity of authorized software programs using digital signatures, cryptographic checksums, or hash functions. Verification of authorized software can occur either prior to execution or at system startup. The identification of authorized URLs for websites is addressed in CA-3(5) and SC-7. Related Controls:  CM-2, CM-6, CM-8, CM-10, PL-9, PM-5, SA-10, SC-34, SI-7.', 'vec_doc-14-nist-sp-800-53-p133-492', 0, 196, 'v2.1.0', '95502f2e96f4473409ca6044676a61940be18e6379079a9da1bb9fb8e8405b7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 106","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":492,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 106"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p133-493', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 106', 133, '(6) LEAST FUNCTIONALITY | CONFINED ENVIRONMENTS WITH LIMITED PRIVILEGES Require that the following user-installed software execute in a confined physical or virtual machine environment with limited privileges: [Assignment: organization-defined user- installed software]. Discussion:  Organizations identify software that may be of concern regarding its origin or potential for containing malicious code. For this type of software, user installations occur in confined environments of operation to limit or contain damage from malicious code that may be executed. Related Controls:  CM-11, SC-44. (7) LEAST FUNCTIONALITY | CODE EXECUTION IN PROTECTED ENVIRONMENTS', 'vec_doc-14-nist-sp-800-53-p133-493', 0, 166, 'v2.1.0', 'bfad225078d5e5f13bc94be3dc3fe800bde224b6f39a353ba3952364f8582bea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 106","subsection":"UNKNOWN","table_id":null,"page":133,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":493,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 106"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p134-494', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 107', 134, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Allow execution of binary or machine-executable code only in confined physical or virtual machine environments and with the explicit approval of [Assignment: organization- defined personnel or roles] when such code is: (a) Obtained from sources with limited or no warranty; and/or (b) Without the provision of source code. Discussion:  Code execution in protected environments applies to all sources of binary or machine-executable code, including commercial software and firmware and open-source software. Related Controls:  CM-10, SC-44. (8) LEAST FUNCTIONALITY | BINARY OR MACHINE EXECUTABLE CODE (a) Prohibit the use of binary or machine-executable code from sources with limited or no warranty or without the provision of source code; and (b) Allow exceptions only for compelling mission or operational requirements and with the approval of the authorizing official.', 'vec_doc-14-nist-sp-800-53-p134-494', 0, 241, 'v2.1.0', 'b8a0b7e95fb7e877f8c950ad7c3a4ad64295c5a26979a40c215bbb3400a8e643', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 107","subsection":"UNKNOWN","table_id":null,"page":134,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":494,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 107"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p134-495', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 107', 134, 'Discussion:  Binary or machine executable code applies to all sources of binary or machine- executable code, including commercial software and firmware and open-source software. Organizations assess software products without accompanying source code or from sources with limited or no warranty for potential security impacts. The assessments address the fact that software products without the provision of source code may be difficult to review, repair, or extend. In addition, there may be no owners to make such repairs on behalf of organizations. If open-source software is used, the assessments address the fact that there is no warranty, the open-source software could contain back doors or malware, and there may be no support available. Related Controls:  SA-5, SA-22.', 'vec_doc-14-nist-sp-800-53-p134-495', 0, 194, 'v2.1.0', '2c4c6c6842164b5a338620ae0af626d8c69abf9dd717d7e6e06e049e41ca72ec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 107","subsection":"UNKNOWN","table_id":null,"page":134,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":495,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 107"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p134-496', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 107', 134, '(9) LEAST FUNCTIONALITY | PROHIBITING THE USE OF UNAUTHORIZED HARDWARE (a) Identify [Assignment: organization-defined hardware components authorized for system use]; (b) Prohibit the use or connection of unauthorized hardware components; (c) Review and update the list of authorized hardware components [Assignment: organization-defined frequency]. Discussion:  Hardware components provide the foundation for organizational systems and the platform for the execution of authorized software programs. Managing the inventory of hardware components and controlling which hardware components are permitted to be installed or connected to organizational systems is essential in order to provide adequate security. Related Controls:  None. References:  [FIPS 140-3], [FIPS 180-4], [FIPS 186-4], [FIPS 202], [SP 800-167]. CM-8 SYSTEM COMPONENT INVENTORY Control: a. Develop and document an inventory of system components that:', 'vec_doc-14-nist-sp-800-53-p134-496', 0, 230, 'v2.1.0', '81ef20b81ee9de07030bed8ac9f521171fe9f7fe9b561656442328a0f6e9471c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 107","subsection":"UNKNOWN","table_id":null,"page":134,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":496,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 107"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p135-497', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '5. Includes the following information to achieve system component accountability:', 135, '[Assignment: organization-defined information deemed necessary to achieve effective system component accountability]; and b. Review and update the system component inventory [Assignment: organization-defined frequency]. Discussion:  System components are discrete, identifiable information technology assets that include hardware, software, and firmware. Organizations may choose to implement centralized system component inventories that include components from all organizational systems. In such situations, organizations ensure that the inventories include system-specific information required for component accountability. The information necessary for effective accountability of system components includes the system name, software owners, software version numbers, hardware inventory specifications, software license information, and for networked components, the machine names and network addresses across all implemented protocols (e.g., IPv4, IPv6).', 'vec_doc-14-nist-sp-800-53-p135-497', 0, 240, 'v2.1.0', '3df33606fa69661588367d99dd5d5e5a29d8abc728aa2cef97b1c39877504455', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"5. Includes the following information to achieve system component accountability:","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":497,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"5. Includes the following information to achieve system component accountability:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p135-498', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '5. Includes the following information to achieve system component accountability:', 135, 'Inventory specifications include date of receipt, cost, model, serial number, manufacturer, supplier information, component type,  and physical location. Preventing duplicate accounting of system components addresses the lack of accountability that occurs when component ownership and system association is not known, especially in large or complex connected systems. Effective prevention of duplicate accounting of system components necessitates use of a unique identifier for each component. For software inventory, centrally managed software that is accessed via other systems is addressed as a component of the system on which it is installed and managed. Software installed on multiple organizational systems and managed at the system level is addressed for each individual system and may appear more than once in a centralized component inventory, necessitating a system association for each software instance in the centralized inventory to avoid duplicate accounting of components.', 'vec_doc-14-nist-sp-800-53-p135-498', 0, 248, 'v2.1.0', '7c745c514f1aa8e84f13c1dc96aba8e0c76d396bc404630171d2a5d6d11aa44e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"5. Includes the following information to achieve system component accountability:","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":498,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"5. Includes the following information to achieve system component accountability:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p135-499', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '5. Includes the following information to achieve system component accountability:', 135, 'Scanning systems implementing multiple network protocols (e.g., IPv4 and IPv6) can result in duplicate components being identified in different address spaces. The implementation of CM-8(7) can help to eliminate duplicate accounting of components. Related Controls:  CM-2, CM-7, CM-9, CM-10, CM-11, CM-13, CP-2, CP-9, MA-2, MA-6, PE-20, PL- 9, PM-5, SA-4, SA-5, SI-2, SR-4. Control Enhancements: (1) SYSTEM COMPONENT INVENTORY | UPDATES DURING INSTALLATION AND REMOVAL Update the inventory of system components as part of component installations, removals, and system updates. Discussion:  Organizations can improve the accuracy, completeness, and consistency of system component inventories if the inventories are updated as part of component installations or removals or during general system updates. If inventories are not updated at these key times, there is a greater likelihood that the information will not be appropriately captured and documented.', 'vec_doc-14-nist-sp-800-53-p135-499', 0, 239, 'v2.1.0', '9e135cc07e665cc6e45bc2bc86a29cf7b0db897b14563c390e503b54d1587d2f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"5. Includes the following information to achieve system component accountability:","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":499,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"5. Includes the following information to achieve system component accountability:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p135-500', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '5. Includes the following information to achieve system component accountability:', 135, 'System updates include hardware, software, and firmware components. Related Controls:  PM-16. (2) SYSTEM COMPONENT INVENTORY | AUTOMATED MAINTENANCE Maintain the currency, completeness, accuracy, and availability of the inventory of system components using [Assignment: organization-defined automated mechanisms]. Discussion:  Organizations maintain system inventories to the extent feasible. For example, virtual machines can be difficult to monitor because such machines are not visible to the network when not in use. In such cases, organizations maintain as up-to-date, complete, and', 'vec_doc-14-nist-sp-800-53-p135-500', 0, 147, 'v2.1.0', '6f9db3208cbfbb7ba330b103359bfc7b818e544cd1b92f57fba32ce4cc05e01b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"5. Includes the following information to achieve system component accountability:","subsection":"UNKNOWN","table_id":null,"page":135,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":500,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"5. Includes the following information to achieve system component accountability:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p136-501', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 109', 136, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 accurate an inventory as is deemed reasonable. Automated maintenance can be achieved by the implementation of CM-2(2) for organizations that combine system component inventory and baseline configuration activities. Related Controls:  None. (3) SYSTEM COMPONENT INVENTORY | AUTOMATED UNAUTHORIZED COMPONENT DETECTION (a) Detect the presence of unauthorized hardware, software, and firmware components within the system using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency]; and (b) Take the following actions when unauthorized components are detected: [Selection (one or more): disable network access by such components; isolate the components; notify [Assignment: organization-defined personnel or roles]]. Discussion:  Automated unauthorized component detection is applied in addition to the monitoring for unauthorized remote connections and mobile devices.', 'vec_doc-14-nist-sp-800-53-p136-501', 0, 251, 'v2.1.0', 'f9f9dbdcad93d91d2a3c34456063010c0479e14c2b2ed02889ff4489ddc999c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 109","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":501,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 109"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p136-502', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 109', 136, 'Monitoring for unauthorized system components may be accomplished on an ongoing basis or by the periodic scanning of systems for that purpose. Automated mechanisms may also be used to prevent the connection of unauthorized components (see CM-7(9)). Automated mechanisms can be implemented in systems or in separate system components. When acquiring and implementing automated mechanisms, organizations consider whether such mechanisms depend on the ability of the system component to support an agent or supplicant in order to be detected since some types of components do not have or cannot support agents (e.g., IoT devices, sensors). Isolation can be achieved , for example, by placing unauthorized system components in separate domains or subnets or quarantining such components. This type of component isolation is commonly referred to as “sandboxing.” Related Controls:  AC-19, CA-7, RA-5, SC-3, SC-39, SC-44, SI-3, SI-4, SI-7.', 'vec_doc-14-nist-sp-800-53-p136-502', 0, 234, 'v2.1.0', 'a77694415f04f90ca9ebcab7150a90c4cc835ebca3dedbb6d5ecb5b78c10fd8e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 109","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":502,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 109"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p136-503', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 109', 136, '(4) SYSTEM COMPONENT INVENTORY | ACCOUNTABILITY INFORMATION Include in the system component inventory information, a means for identifying by [Selection (one or more): name; position; role], individuals responsible and accountable for administering those components. Discussion:  Identifying individuals who are responsible and accountable for administering system components ensures that the assigned components are properly administered and that organizations can contact those individuals if some action is required (e.g., when the component is determined to be the source of a breach, needs to be recalled or replaced, or needs to be relocated). Related Controls:  AC-3. (5) SYSTEM COMPONENT INVENTORY | NO DUPLICATE ACCOUNTING OF COMPONENTS [Withdrawn: Incorporated into CM-8.] (6) SYSTEM COMPONENT INVENTORY | ASSESSED CONFIGURATIONS AND APPROVED DEVIATIONS Include assessed component configurations and any approved deviations to current deployed configurations in the system component inventory.', 'vec_doc-14-nist-sp-800-53-p136-503', 0, 251, 'v2.1.0', '4692e18782b4fba0c4d4a59d4165b81dd5719b421ec485fc07e40b85d3e8b6af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 109","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":503,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 109"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p136-504', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 109', 136, 'Discussion: Assessed configurations and approved deviations focus on configuration settings established by organizations for system components, the specific components that have been assessed to determine compliance with the required configuration settings, and any approved deviations from established configuration settings. Related Controls:  None. (7) SYSTEM COMPONENT INVENTORY | CENTRALIZED REPOSITORY Provide a centralized repository for the inventory of system components.', 'vec_doc-14-nist-sp-800-53-p136-504', 0, 120, 'v2.1.0', '55ffe9e98ba25a58c1b23c9efc10a9fa440ecb42a4e3cc6e3232c511a075b814', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 109","subsection":"UNKNOWN","table_id":null,"page":136,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":504,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 109"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p137-505', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 110', 137, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Organizations may implement centralized system component inventories that include components from all organizational systems. Centralized repositories of component inventories provide opportunities for efficiencies in accounting for organizational hardware, software, and firmware assets. Such repositories may also help organizations rapidly identify the location and responsible individuals of components that have been compromised, breached, or are otherwise in need of mitigation actions. Organizations ensure that the resulting centralized inventories include system-specific information required for proper component accountability. Related Controls:  None. (8) SYSTEM COMPONENT INVENTORY | AUTOMATED LOCATION TRACKING Support the tracking of system components by geographic location using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p137-505', 0, 240, 'v2.1.0', 'dbb159bca876a3b8be3af5493a29c07911494a7225580eee6750a654f1d1c0b5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 110","subsection":"UNKNOWN","table_id":null,"page":137,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":505,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 110"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p137-506', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 110', 137, 'Discussion:  The use of automated mechanisms to track the location of system components can increase the accuracy of component inventories. Such capability may help organizations rapidly identify the location and responsible individuals of system components that have been compromised, breached, or are otherwise in need of mitigation actions. The use of tracking mechanisms can be coordinated with senior agency officials for privacy if there are implications that affect individual privacy. Related Controls:  None. (9) SYSTEM COMPONENT INVENTORY | ASSIGNMENT OF COMPONENTS TO SYSTEMS (a) Assign system components to a system; and (b) Receive an acknowledgement from [Assignment: organization-defined personnel or roles] of this assignment. Discussion:  System components that are not assigned to a system may be unmanaged, lack the required protection, and become an organizational vulnerability. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p137-506', 0, 231, 'v2.1.0', '2413e62edf06e07ceb518765fddbcc4cd47840116bd19c29e22b8cbee8e6bd40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 110","subsection":"UNKNOWN","table_id":null,"page":137,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":506,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 110"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p137-507', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 110', 137, 'References:  [OMB A-130], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-128], [IR 8011-2], [IR 8011-3]. CM-9 CONFIGURATION MANAGEMENT PLAN Control:  Develop, document, and implement a configuration management plan for the system that: a. Addresses roles, responsibilities, and configuration management processes and procedures; b. Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items; c. Defines the configuration items for the system and places the configuration items under configuration management; d. Is reviewed and approved by [Assignment: organization-defined personnel or roles]; and e. Protects the configuration management plan from unauthorized disclosure and modification. Discussion:  Configuration management activities occur throughout the system development life cycle.', 'vec_doc-14-nist-sp-800-53-p137-507', 0, 226, 'v2.1.0', '0149cc5afded4937b3f0ee2e950c666b76791d326fd60f2c2c2ae08f1ae93874', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 110","subsection":"UNKNOWN","table_id":null,"page":137,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":507,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 110"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p137-508', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 110', 137, 'As such, there are developmental configuration management activities (e.g., the control of code and software libraries) and operational configuration management activities (e.g., control of installed components and how the components are configured). Configuration management plans satisfy the requirements in configuration management policies while being tailored to', 'vec_doc-14-nist-sp-800-53-p137-508', 0, 92, 'v2.1.0', 'e4d065f2a7f7796c6cb381c20b7a824ad1ffd08e73892f149cd28cd502009dcd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 110","subsection":"UNKNOWN","table_id":null,"page":137,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":508,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 110"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p138-509', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 111', 138, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 individual systems. Configuration management plans define processes and procedures for how configuration management is used to support system development life cycle activities. Configuration management plans are generated during the development and acquisition stage of the system development life cycle. The plans describe how to advance changes through change management processes; update configuration settings and baselines; maintain component inventories; control development, test, and operational environments; and develop, release, and update key documents. Organizations can employ templates to help ensure the consistent and timely development and implementation of configuration management plans. Templates can represent a configuration management plan for the organization with subsets of the plan implemented on a system by system basis.', 'vec_doc-14-nist-sp-800-53-p138-509', 0, 236, 'v2.1.0', '3a732118b4f0d5ae1ba7ad01c86a45fd2e506592a326796ca6db35a53d4442d6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 111","subsection":"UNKNOWN","table_id":null,"page":138,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":509,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 111"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p138-510', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 111', 138, 'Configuration management approval processes include the designation of key stakeholders responsible for reviewing and approving proposed changes to systems, and personnel who conduct security and privacy impact analyses prior to the implementation of changes to the systems. Configuration items are the system components, such as the hardware, software, firmware, and documentation to be configuration-managed. As systems continue through the system development life cycle, new configuration items may be identified, and some existing configuration items may no longer need to be under configuration control. Related Controls:  CM-2, CM-3, CM-4, CM-5, CM-8, PL-2, RA-8, SA-10, SI-12. Control Enhancements: (1) CONFIGURATION MANAGEMENT PLAN | ASSIGNMENT OF RESPONSIBILITY Assign responsibility for developing the configuration management process to organizational personnel that are not directly involved in system development.', 'vec_doc-14-nist-sp-800-53-p138-510', 0, 232, 'v2.1.0', 'eaa6d73d7ba4b301b585c325bc2ae72e86a5ef8d397ac6bde99aa739aa3465f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 111","subsection":"UNKNOWN","table_id":null,"page":138,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":510,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 111"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p138-511', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 111', 138, 'Discussion: In the absence of dedicated configuration management teams assigned within organizations, system developers may be tasked with developing configuration management processes using personnel who are not directly involved in system development or system integration. This separation of duties ensures that organizations establish and maintain a sufficient degree of independence between the system development and integration processes and configuration management processes to facilitate quality control and more effective oversight. Related Controls:  None. References:  [SP 800-128]. CM-10 SOFTWARE USAGE RESTRICTIONS Control: a. Use software and associated documentation in accordance with contract agreements and copyright laws; b. Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; and c.', 'vec_doc-14-nist-sp-800-53-p138-511', 0, 219, 'v2.1.0', '76fff30ab1c84c78b3e1c08921a8dd3bd74205c46b5f1f7f9a9c050b77a4d2e7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 111","subsection":"UNKNOWN","table_id":null,"page":138,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":511,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 111"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p138-512', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 111', 138, 'Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work. Discussion:  Software license tracking can be accomplished by manual or automated methods, depending on organizational needs. Examples of contract agreements include software license agreements and non-disclosure agreements. Related Controls:  AC-17, AU-6, CM-7, CM-8, PM-30, SC-7.', 'vec_doc-14-nist-sp-800-53-p138-512', 0, 122, 'v2.1.0', '9b08042665d61b8791303e0df3d81fbafeeba59d79af4f3b76b35513c4245f58', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 111","subsection":"UNKNOWN","table_id":null,"page":138,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":512,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 111"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p139-513', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 112', 139, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) SOFTWARE USAGE RESTRICTIONS | OPEN-SOURCE SOFTWARE Establish the following restrictions on the use of open-source software: [Assignment: organization-defined restrictions]. Discussion:  Open-source software refers to software that is available in source code form. Certain software rights normally reserved for copyright holders are routinely provided under software license agreements that permit individuals to study, change, and improve the software. From a security perspective, the major advantage of open-source software is that it provides organizations with the ability to examine the source code. In some cases, there is an online community associated with the software that inspects, tests,  updates, and reports on issues found in software on an ongoing basis. However, remediating vulnerabilities in open-source software may be problematic.', 'vec_doc-14-nist-sp-800-53-p139-513', 0, 243, 'v2.1.0', '848f98d17e372e6347effb5900048a8933e8e90721fe748b251abd8b489b0b8d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 112","subsection":"UNKNOWN","table_id":null,"page":139,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":513,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 112"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p139-514', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 112', 139, 'There may also be licensing issues associated with open-source software, including the constraints on derivative use of such software. Open-source software that is available only in binary form may increase the level of risk in using such software. Related Controls:  SI-7. References:  None. CM-11 USER-INSTALLED SOFTWARE Control: a. Establish [Assignment: organization-defined policies] governing the installation of software by users; b. Enforce software installation policies through the following methods: [Assignment: organization-defined methods]; and c. Monitor policy compliance [Assignment: organization-defined frequency]. Discussion:  If provided the necessary privileges, users can install software in organizational systems. To maintain control over the software installed, organizations identify permitted and prohibited actions regarding software installation.', 'vec_doc-14-nist-sp-800-53-p139-514', 0, 219, 'v2.1.0', '2b05940b46ea4b05eda4e73e13de580fb19fb9e26561e46a2b733876e8665a08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 112","subsection":"UNKNOWN","table_id":null,"page":139,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":514,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 112"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p139-515', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 112', 139, 'Permitted software installations include updates and security patches to existing software and downloading new applications from organization-approved “app stores.” Prohibited software installations include software with unknown or suspect pedigrees or software that organizations consider potentially malicious. Policies selected for governing user-installed software are organization-developed or provided by some external entity. Policy enforcement methods can include procedural methods and automated methods. Related Controls:  AC-3, AU-6, CM-2, CM-3, CM-5, CM-6, CM-7, CM-8, PL-4, SI-4, SI-7. Control Enhancements: (1) USER-INSTALLED SOFTWARE | ALERTS FOR UNAUTHORIZED INSTALLATIONS [Withdrawn: Incorporated into CM-8(3).] (2) USER-INSTALLED SOFTWARE | SOFTWARE INSTALLATION WITH PRIVILEGED STATUS Allow user installation of software only with explicit privileged status. Discussion:  Privileged status can be obtained, for example, by serving in the role of system administrator.', 'vec_doc-14-nist-sp-800-53-p139-515', 0, 247, 'v2.1.0', '817462a7546b8fc1e3a31bb8d5a1af00f2c2174f7229c552cf9cfb4bdeb5e8cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 112","subsection":"UNKNOWN","table_id":null,"page":139,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":515,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 112"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p139-516', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 112', 139, 'Related Controls:  AC-5, AC-6. (3) USER-INSTALLED SOFTWARE | AUTOMATED ENFORCEMENT AND MONITORING', 'vec_doc-14-nist-sp-800-53-p139-516', 0, 25, 'v2.1.0', '99e6665981a81578602db3cf17814987ec146ffb492e50bdd983ecddf0b7722a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 112","subsection":"UNKNOWN","table_id":null,"page":139,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":516,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 112"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p140-517', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 113', 140, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Enforce and monitor compliance with software installation policies using [Assignment: organization-defined automated mechanisms]. Discussion:  Organizations enforce and monitor compliance with software installation policies using automated mechanisms to more quickly detect and respond to unauthorized software installation which can be an indicator of an internal or external hostile attack. Related Controls:  None. References:  None. CM-12 INFORMATION LOCATION Control: a. Identify and document the location of [Assignment: organization-defined information] and the specific system components on which the information is processed and stored; b. Identify and document the users who have access to the system and system components where the information is processed and stored; and c. Document changes to the location (i.e., system or system components) where the information is processed and stored.', 'vec_doc-14-nist-sp-800-53-p140-517', 0, 249, 'v2.1.0', '3889ebfe733b4b98c0f1c4461035c7ccc08e6144c60c67b8b8af9c9c1d7ea5c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 113","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":517,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 113"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p140-518', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 113', 140, 'Discussion:  Information location addresses the need to understand where information is being processed and stored. Information location includes identifying where specific information types and information reside in system components and how information is being processed so that information flow can be understood and adequate protection and policy management provided for such information and system components. The security category of the information is also a factor in determining the controls necessary to protect the information and the system component where the information resides (see FIPS 199). The location of the information and system components is also a factor in the architecture and design of the system (see SA-4, SA-8, SA-17). Related Controls:  AC-2, AC-3, AC-4, AC-6, AC-23, CM-8, PM-5, RA-2, SA-4, SA-8, SA-17, SC-4, SC- 16, SC-28, SI-4, SI-7.', 'vec_doc-14-nist-sp-800-53-p140-518', 0, 218, 'v2.1.0', '14d6fa7186fcdc7835a9aa76b8dcf20a486d1d6f022645bc108ef22ae0d2e3ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 113","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":518,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 113"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p140-519', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 113', 140, 'Control Enhancements: (1) INFORMATION LOCATION | AUTOMATED TOOLS TO SUPPORT INFORMATION LOCATION Use automated tools to identify [Assignment: organization-defined information by information type] on [Assignment: organization-defined system components] to ensure controls are in place to protect organizational information and individual privacy. Discussion:  The use of automated tools helps to increase the effectiveness and efficiency of the information location capability implemented within the system. Automation also helps organizations manage the data produced during information location activities and share such information across the organization. The output of automated information location tools can be used to guide and inform system architecture and design decisions. Related Controls:  None. References:  [FIPS 199], [SP 800-60-1], [SP 800-60-2]. CM-13 DATA ACTION MAPPING Control:  Develop and document a map of system data actions.', 'vec_doc-14-nist-sp-800-53-p140-519', 0, 238, 'v2.1.0', '55416160280b64a1a2b8839e99d55e3b6927977bbf5f69fb1007fa776a57ffe0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 113","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":519,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 113"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p140-520', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 113', 140, 'Discussion:  Data actions are system operations that process personally identifiable information. The processing of such information encompasses the full information life cycle, which includes collection, generation, transformation, use, disclosure, retention, and disposal. A map of system', 'vec_doc-14-nist-sp-800-53-p140-520', 0, 73, 'v2.1.0', '4962942b6586e9bc9e2f15648dd293659a430cc4fd02b7c8363cda48d908efe4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 113","subsection":"UNKNOWN","table_id":null,"page":140,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":520,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 113"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p141-521', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 114', 141, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 data actions includes discrete data actions, elements of personally identifiable information being processed in the data actions, system components involved in the data actions, and the owners or operators of the system components. Understanding what personally identifiable information is being processed (e.g., the sensitivity of the personally identifiable information), how personally identifiable information is being processed (e.g., if the data action is visible to the individual or is processed in another part of the system), and by whom (e.g., individuals may have different privacy perceptions based on the entity that is processing the personally identifiable information) provides a number of contextual factors that are important to assessing the degree of privacy risk created by the system.', 'vec_doc-14-nist-sp-800-53-p141-521', 0, 225, 'v2.1.0', 'f0275e21d90bbedf9eba3efe4babecbf9372c7de8b286b14a124a334e46d6171', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 114","subsection":"UNKNOWN","table_id":null,"page":141,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":521,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 114"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p141-522', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 114', 141, 'Data maps can be illustrated in different ways, and the level of detail may vary based on the mission and business needs of the organization. The data map may be an overlay of any system design artifact that the organization is using. The development of this map may necessitate coordination between the privacy and security programs regarding the covered data actions and the components that are identified as part of the system. Related Controls:  AC-3, CM-4, CM-12, PM-5, PM-27, PT-2, PT-3, RA-3, RA-8 . CM-14 SIGNED COMPONENTS Control:  Prevent the installation of [Assignment: organization-defined software and firmware components] without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.', 'vec_doc-14-nist-sp-800-53-p141-522', 0, 194, 'v2.1.0', '14edfedd72b77a213add2b1f80203fa6fef9bb8b9b4027b480682a917c173185', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 114","subsection":"UNKNOWN","table_id":null,"page":141,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":522,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 114"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p141-523', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 114', 141, 'Discussion:  Software and firmware components prevented from installation unless signed with recognized and approved certificates include software and firmware version updates, patches, service packs, device drivers, and basic input/output system updates. Organizations can identify applicable software and firmware components by type, by specific items, or a combination of both. Digital signatures and organizational verification of such signatures is a method of code authentication. Related Controls:  CM-7, SC-12, SC-13, SI-7. References:  [IR 8062].', 'vec_doc-14-nist-sp-800-53-p141-523', 0, 139, 'v2.1.0', '044f69d3475f838a091b555d86291093f49c3490577aac1fdc7b75259b066e8b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 114","subsection":"UNKNOWN","table_id":null,"page":141,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":523,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 114"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p142-524', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.6   CONTINGENCY PLANNING', 142, 'Quick link to Contingency Planning Summary Table CP-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p142-524', 0, 45, 'v2.1.0', '3cca57545d033b033f68609064d4f7b63278d477d8a48d1f89457c5287630eff', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.6   CONTINGENCY PLANNING","subsection":"UNKNOWN","table_id":null,"page":142,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":524,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.6   CONTINGENCY PLANNING"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p142-525', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 142, 'level] contingency planning policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p142-525', 0, 77, 'v2.1.0', '24fce078b059a9f5d25917466d5c341efc943d69f742f33a5c69b56d07cbf528', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":142,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":525,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p142-526', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the contingency planning policy and the', 142, 'associated contingency planning controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the contingency planning policy and procedures; and c. Review and update the current contingency planning:', 'vec_doc-14-nist-sp-800-53-p142-526', 0, 68, 'v2.1.0', '33d25a0efe065bbf0cf074efd22f39fd81fcdc0af8b049666d4e592ae822e5cd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the contingency planning policy and the","subsection":"UNKNOWN","table_id":null,"page":142,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":526,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the contingency planning policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p142-527', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 142, 'organization-defined events]. Discussion:  Contingency planning policy and procedures address the controls in the CP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of contingency planning policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to contingency planning policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [SP 800-12], [SP 800-30], [SP 800-34], [SP 800-39], [SP 800-50], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p142-527', 0, 430, 'v2.1.0', '3a1b9d4b522e90d4052bfd5649377fe1ba49f7c2edad6620b4c0d9b8216d93cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":142,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":527,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-528', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 116', 143, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 CP-2 CONTINGENCY PLAN Control: a. Develop a contingency plan for the system that:', 'vec_doc-14-nist-sp-800-53-p143-528', 0, 44, 'v2.1.0', '105f81f91530dbfb8e9b4738ea4e071bedfde7dd2e3ffb4a7d1a8ded95095c7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 116","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":528,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 116"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-529', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Addresses maintaining essential mission and business functions despite a system', 143, 'disruption, compromise, or failure;', 'vec_doc-14-nist-sp-800-53-p143-529', 0, 9, 'v2.1.0', '312e8d59c677cf451092a07207b0dfddcdc7b080a4b86df2a7c4e2eb6c132d14', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Addresses maintaining essential mission and business functions despite a system","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":529,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Addresses maintaining essential mission and business functions despite a system"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-530', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '5. Addresses eventual, full system restoration without deterioration of the controls', 143, 'originally planned and implemented;', 'vec_doc-14-nist-sp-800-53-p143-530', 0, 9, 'v2.1.0', 'e8bf7ebbda2e1ab377a0d2088fae76fea7047284b7e64866933b6675162e7e7b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"5. Addresses eventual, full system restoration without deterioration of the controls","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":530,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"5. Addresses eventual, full system restoration without deterioration of the controls"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-531', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];', 143, 'b. Distribute copies of the contingency plan to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements]; c. Coordinate contingency planning activities with incident handling activities; d. Review the contingency plan for the system [Assignment: organization-defined frequency]; e. Update the contingency plan to address changes to the organization, system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing; f. Communicate contingency plan changes to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements]; g. Incorporate lessons learned from contingency plan testing, training, or actual contingency activities into contingency testing and training; and h. Protect the contingency plan from unauthorized disclosure and modification.', 'vec_doc-14-nist-sp-800-53-p143-531', 0, 235, 'v2.1.0', '9dd0bb324d202ea09b2dbcead21bf1f7482dec1263a18fef0c56dddb4353e8ed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":531,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-532', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];', 143, 'Discussion:  Contingency planning for systems is part of an overall program for achieving continuity of operations for organizational mission and business functions. Contingency planning addresses system restoration and implementation of alternative mission or business processes when systems are compromised or breached. Contingency planning is considered throughout the system development life cycle and is a fundamental part of the system design. Systems can be designed for redundancy, to provide backup capabilities, and for resilience. Contingency plans reflect the degree of restoration required for organizational systems since not all systems need to fully recover to achieve the level of continuity of operations desired. System recovery objectives reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, organizational risk tolerance, and system impact level.', 'vec_doc-14-nist-sp-800-53-p143-532', 0, 229, 'v2.1.0', '5cfa0a6a1837411d91f254813022564eebb9f18ad4b9555591107cd1c11d626b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":532,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p143-533', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];', 143, 'Actions addressed in contingency plans include orderly system degradation, system shutdown, fallback to a manual mode, alternate information flows, and operating in modes reserved for when systems are under attack. By coordinating contingency planning with incident handling activities, organizations ensure that the necessary planning activities are in place and activated in the event of an incident. Organizations consider whether continuity of operations during an incident conflicts with the capability to automatically disable the system, as specified in IR-4(5). Incident response planning is part of contingency planning for organizations and is addressed in the IR (Incident Response) family.', 'vec_doc-14-nist-sp-800-53-p143-533', 0, 176, 'v2.1.0', 'b64a577bbb0d729b955c4b3f53c41bd24b883f41a230b02b5378df617106d504', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];","subsection":"UNKNOWN","table_id":null,"page":143,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":533,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"7. Is reviewed and approved by [Assignment: organization-defined personnel or roles];"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p144-534', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 117', 144, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  CP-3, CP-4, CP-6, CP-7, CP-8, CP-9, CP-10, CP-11, CP-13, IR-4, IR-6, IR-8, IR-9, MA-6, MP-2, MP-4, MP-5, PL-2, PM-8, PM-11, SA-15, SA-20, SC-7, SC-23, SI-12. Control Enhancements: (1) CONTINGENCY PLAN | COORDINATE WITH RELATED PLANS Coordinate contingency plan development with organizational elements responsible for related plans. Discussion:  Plans that are related to contingency plans include Business Continuity Plans, Disaster Recovery Plans, Critical Infrastructure Plans, Continuity of Operations Plans, Crisis Communications Plans, Insider Threat Implementation Plans, Data Breach Response Plans, Cyber Incident Response Plans, Breach Response Plans, and Occupant Emergency Plans. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p144-534', 0, 207, 'v2.1.0', '1329ba8672ad19d7d4875b23d101194d8cd8cba8ee6e6ac1d00ba93440e3e4f7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 117","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":534,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 117"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p144-535', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 117', 144, '(2) CONTINGENCY PLAN | CAPACITY PLANNING Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations. Discussion:  Capacity planning is needed because different threats can result in a reduction of the available processing, telecommunications, and support services intended to support essential mission and business functions. Organizations anticipate degraded operations during contingency operations and factor the degradation into capacity planning. For capacity planning, environmental support refers to any environmental factor for which the organization determines that it needs to provide support in a contingency situation, even if in a degraded state. Such determinations are based on an organizational assessment of risk, system categorization (impact level), and organizational risk tolerance. Related Controls:  PE-11, PE-12, PE-13, PE-14, PE-18, SC-5.', 'vec_doc-14-nist-sp-800-53-p144-535', 0, 242, 'v2.1.0', '3d3e8670accbb6861e060ef966e62a3c8bd826c7cabffff4ab8ddf3dba32d7f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 117","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":535,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 117"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p144-536', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 117', 144, '(3) CONTINGENCY PLAN | RESUME MISSION AND BUSINESS FUNCTIONS Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation. Discussion:  Organizations may choose to conduct contingency planning activities to resume mission and business functions as part of business continuity planning or as part of business impact analyses. Organizations prioritize the resumption of mission and business functions. The time period for resuming mission and business functions may be dependent on the severity and extent of the disruptions to the system and its supporting infrastructure. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p144-536', 0, 177, 'v2.1.0', 'f80ada922ab91266b1879768f97b1cbf860a610d26241cb0b7a5b4bc895b6bcd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 117","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":536,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 117"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p144-537', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 117', 144, '(4) CONTINGENCY PLAN | RESUME ALL MISSION AND BUSINESS FUNCTIONS [Withdrawn: Incorporated into CP-2(3).] (5) CONTINGENCY PLAN | CONTINUE MISSION AND BUSINESS FUNCTIONS Plan for the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites. Discussion:  Organizations may choose to conduct the contingency planning activities to continue mission and business functions as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency. Related Controls:  None. (6) CONTINGENCY PLAN | ALTERNATE PROCESSING AND STORAGE SITES', 'vec_doc-14-nist-sp-800-53-p144-537', 0, 216, 'v2.1.0', '3ba6c991fa0db9319d0ed8870e7c8b0ca9f2dc7732cf39ebcdd4af778807e2c5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 117","subsection":"UNKNOWN","table_id":null,"page":144,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":537,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 117"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p145-538', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 118', 145, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Plan for the transfer of [Selection: all; essential] mission and business functions to alternate processing and/or storage sites with minimal or no loss of operational continuity and sustain that continuity through system restoration to primary processing and/or storage sites. Discussion:  Organizations may choose to conduct contingency planning activities for alternate processing and storage sites as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency. Related Controls:  None. (7) CONTINGENCY PLAN | COORDINATE WITH EXTERNAL SERVICE PROVIDERS Coordinate the contingency plan with the contingency plans of external service providers to ensure that contingency requirements can be satisfied.', 'vec_doc-14-nist-sp-800-53-p145-538', 0, 243, 'v2.1.0', 'fb7a8380f0521fb83f85ae2f0499f184c339feb534cec4643d40b209b9a34cba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 118","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":538,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 118"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p145-539', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 118', 145, 'Discussion:  When the capability of an organization to carry out its mission and business functions is dependent on external service providers, developing a comprehensive and timely contingency plan may become more challenging. When mission and business functions are dependent on external service providers, organizations coordinate contingency planning activities with the external entities to ensure that the individual plans reflect the overall contingency needs of the organization. Related Controls:  SA-9. (8) CONTINGENCY PLAN | IDENTIFY CRITICAL ASSETS Identify critical system assets supporting [Selection: all; essential] mission and business functions. Discussion:  Organizations may choose to identify critical assets as part of criticality analysis, business continuity planning, or business impact analyses.', 'vec_doc-14-nist-sp-800-53-p145-539', 0, 206, 'v2.1.0', '2e3488d1fed6b11930a5b7012f4d139402dc1bbe6c24ea4a907e407681dbf82b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 118","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":539,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 118"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p145-540', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 118', 145, 'Organizations identify critical system assets so that additional controls can be employed (beyond the controls routinely implemented) to help ensure that organizational mission and business functions can continue to be conducted during contingency operations. The identification of critical information assets also facilitates the prioritization of organizational resources. Critical system assets include technical and operational aspects. Technical aspects include system components, information technology services, information technology products, and mechanisms. Operational aspects include procedures (i.e., manually executed operations) and personnel (i.e., individuals operating technical controls and/or executing manual procedures). Organizational program protection plans can assist in identifying critical assets. If critical assets are resident within or supported by external service providers, organizations consider implementing CP-2(7) as a control enhancement.', 'vec_doc-14-nist-sp-800-53-p145-540', 0, 245, 'v2.1.0', '2be668e6ec541a763296b44ee6ec4ce6107a37882ba5010f26a59056fd28d838', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 118","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":540,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 118"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p145-541', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 118', 145, 'Related Controls:  CM-8, RA-9. References:  [SP 800-34], [IR 8179]. CP-3 CONTINGENCY TRAINING Control: a. Provide contingency training to system users consistent with assigned roles and responsibilities:', 'vec_doc-14-nist-sp-800-53-p145-541', 0, 51, 'v2.1.0', 'e004fbaa21bc08feb9f3b5e08657820dba88a233421e6520177268a0b6d8188f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 118","subsection":"UNKNOWN","table_id":null,"page":145,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":541,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 118"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p146-542', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 146, 'b. Review and update contingency training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]. Discussion:  Contingency training provided by organizations is linked to the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail is included in such training. For example, some individuals may only need to know when and where to report for duty during contingency operations and if normal duties are affected; system administrators may require additional training on how to establish systems at alternate processing and storage sites; and organizational officials may receive more specific training on how to conduct mission-essential functions in designated off-site locations and how to establish communications with other governmental entities for purposes of coordination on contingency- related activities.', 'vec_doc-14-nist-sp-800-53-p146-542', 0, 234, 'v2.1.0', '27a6133044db9efadc42ff87ec8808408070a2df6b6fc6c55d70db3309efc926', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":542,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p146-543', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 146, 'Training for contingency roles or responsibilities reflects the specific continuity requirements in the contingency plan. Events that may precipitate an update to contingency training content include, but are not limited to, contingency plan testing or an actual contingency (lessons learned), assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. At the discretion of the organization, participation in a contingency plan test or exercise, including lessons learned sessions subsequent to the test or exercise, may satisfy contingency plan training requirements. Related Controls:  AT-2, AT-3, AT-4, CP-2, CP-4, CP-8, IR-2, IR-4, IR-9. Control Enhancements: (1) CONTINGENCY TRAINING | SIMULATED EVENTS Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations.', 'vec_doc-14-nist-sp-800-53-p146-543', 0, 234, 'v2.1.0', '9486242a2290d4d3b9100425be7043704303ba216629747fdda4985cff75bb02', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":543,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p146-544', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 146, 'Discussion:  The use of simulated events creates an environment for personnel to experience actual threat events, including cyber-attacks that disable websites, ransomware attacks that encrypt organizational data on servers, hurricanes that damage or destroy organizational facilities, or hardware or software failures. Related Controls:  None. (2) CONTINGENCY TRAINING | MECHANISMS USED IN TRAINING ENVIRONMENTS Employ mechanisms used in operations to provide a more thorough and realistic contingency training environment. Discussion:  Operational mechanisms refer to processes that have been established to accomplish an organizational goal or a system that supports a particular organizational mission or business objective. Actual mission and business processes, systems, and/or facilities may be used to generate simulated events and enhance the realism of simulated events during contingency training. Related Controls:  None. References:  [SP 800-50]. CP-4 CONTINGENCY PLAN TESTING Control: a.', 'vec_doc-14-nist-sp-800-53-p146-544', 0, 251, 'v2.1.0', '2bc3efdb17aac0489e9c7e9556e0f6eed7dd87892444e41ebac235ff0e5a7c61', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":544,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p146-545', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 146, 'Test the contingency plan for the system [Assignment: organization-defined frequency] using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: [Assignment: organization-defined tests]. b. Review the contingency plan test results; and', 'vec_doc-14-nist-sp-800-53-p146-545', 0, 71, 'v2.1.0', '5cfb0bbbbcf0a2606fe4f7d3c86cd68859342317aa5772de38d9e30c3731c744', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":146,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":545,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p147-546', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 120', 147, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 c. Initiate corrective actions, if needed. Discussion:  Methods for testing contingency plans to determine the effectiveness of the plans and identify potential weaknesses include checklists, walk-through and tabletop exercises, simulations (parallel or full interrupt), and comprehensive exercises. Organizations conduct testing based on the requirements in contingency plans and include a determination of the effects on organizational operations, assets, and individuals due to contingency operations. Organizations have flexibility and discretion in the breadth, depth, and timelines of corrective actions. Related Controls:  AT-3, CP-2, CP-3, CP-8, CP-9, IR-3, IR-4, PL-2, PM-14, SR-2. Control Enhancements: (1) CONTINGENCY PLAN TESTING | COORDINATE WITH RELATED PLANS Coordinate contingency plan testing with organizational elements responsible for related plans.', 'vec_doc-14-nist-sp-800-53-p147-546', 0, 241, 'v2.1.0', '99c09c020b4b5423e266af34bc488b2aadaed2b89d28dccecd62514b91886c9c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 120","subsection":"UNKNOWN","table_id":null,"page":147,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":546,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 120"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p147-547', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 120', 147, 'Discussion:  Plans related to contingency planning for organizational systems include Business Continuity Plans, Disaster Recovery Plans, Continuity of Operations Plans, Crisis Communications Plans, Critical Infrastructure Plans, Cyber Incident Response Plans, and Occupant Emergency Plans. Coordination of contingency plan testing does not require organizations to create organizational elements to handle related plans or to align such elements with specific plans. However, it does require that if such organizational elements are responsible for related plans, organizations coordinate with those elements. Related Controls:  IR-8, PM-8. (2) CONTINGENCY PLAN TESTING | ALTERNATE PROCESSING SITE Test the contingency plan at the alternate processing site: (a) To familiarize contingency personnel with the facility and available resources; and (b) To evaluate the capabilities of the alternate processing site to support contingency operations.', 'vec_doc-14-nist-sp-800-53-p147-547', 0, 237, 'v2.1.0', '3b3c204658db3e272047b7a7dbbbf25d9cd5f1fc089261ca3aff8c6514237d61', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 120","subsection":"UNKNOWN","table_id":null,"page":147,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":547,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 120"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p147-548', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 120', 147, 'Discussion:  Conditions at the alternate processing site may be significantly different than the conditions at the primary site. Having the opportunity to visit the alternate site and experience the actual capabilities available at the site can provide valuable information on potential vulnerabilities that could affect essential organizational mission and business functions. The on-site visit can also provide an opportunity to refine the contingency plan to address the vulnerabilities discovered during testing. Related Controls:  CP-7. (3) CONTINGENCY PLAN TESTING | AUTOMATED TESTING Test the contingency plan using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms facilitate thorough and effective testing of contingency plans by providing more complete coverage of contingency issues, selecting more realistic test scenarios and environments, and effectively stressing the system and supported mission and business functions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p147-548', 0, 251, 'v2.1.0', 'a31881fbad9ff9911963d97c860084d4e5de406196841a259bcadef0f3b0e509', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 120","subsection":"UNKNOWN","table_id":null,"page":147,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":548,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 120"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p147-549', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 120', 147, '(4) CONTINGENCY PLAN TESTING | FULL RECOVERY AND RECONSTITUTION Include a full recovery and reconstitution of the system to a known state as part of contingency plan testing. Discussion:  Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes', 'vec_doc-14-nist-sp-800-53-p147-549', 0, 89, 'v2.1.0', 'cdf54d868d7929971799623776a628a660c2091568a17f3e0502b1d645b3b0c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 120","subsection":"UNKNOWN","table_id":null,"page":147,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":549,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 120"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p148-550', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 121', 148, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 activities for returning systems to fully operational states. Organizations establish a known state for systems that includes system state information for hardware, software programs, and data. Preserving system state information facilitates system restart and return to the operational mode of organizations with less disruption of mission and business processes. Related Controls:  CP-10, SC-24. (5) CONTINGENCY PLAN TESTING | SELF-CHALLENGE Employ [Assignment: organization-defined mechanisms] to [Assignment: organization- defined system or system component] to disrupt and adversely affect the system or system component. Discussion:  Often, the best method of assessing system resilience is to disrupt the system in some manner.', 'vec_doc-14-nist-sp-800-53-p148-550', 0, 207, 'v2.1.0', 'ed226744cca5c62657c73aff7b7e022eabf982138b88ad83c56bb64fa7d6ad81', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 121","subsection":"UNKNOWN","table_id":null,"page":148,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":550,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 121"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p148-551', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 121', 148, 'The mechanisms used by the organization could disrupt system functions or system services in many ways, including terminating or disabling critical system components, changing the configuration of system components, degrading critical functionality (e.g., restricting network bandwidth), or altering privileges. Automated, on-going, and simulated cyber-attacks and service disruptions can reveal unexpected functional dependencies and help the organization determine its ability to ensure resilience in the face of an actual cyber- attack. Related Controls:  None. References:  [FIPS 199], [SP 800-34], [SP 800-84], [SP 800-160-2]. CP-5 CONTINGENCY PLAN UPDATE [Withdrawn: Incorporated into CP-2.] CP-6 ALTERNATE STORAGE SITE Control: a. Establish an alternate storage site, including necessary agreements to permit the storage and retrieval of system backup information; and b. Ensure that the alternate storage site provides controls equivalent to that of the primary site.', 'vec_doc-14-nist-sp-800-53-p148-551', 0, 244, 'v2.1.0', '10df01e573b0656635fc600a641c77685c0f68152758284f3ee4dcf5108b6f7a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 121","subsection":"UNKNOWN","table_id":null,"page":148,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":551,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 121"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p148-552', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 121', 148, 'Discussion:  Alternate storage sites are geographically distinct from primary storage sites and maintain duplicate copies of information and data if the primary storage site is not available. Similarly, alternate processing sites provide processing capability if the primary processing site is not available. Geographically distributed architectures that support contingency requirements may be considered alternate storage sites. Items covered by alternate storage site agreements include environmental conditions at the alternate sites, access rules for systems and facilities, physical and environmental protection requirements, and coordination of delivery and retrieval of backup media. Alternate storage sites reflect the requirements in contingency plans so that organizations can maintain essential mission and business functions despite compromise, failure, or disruption in organizational systems. Related Controls:  CP-2, CP-7, CP-8, CP-9, CP-10, MP-4, MP-5, PE-3, SC-36, SI-13.', 'vec_doc-14-nist-sp-800-53-p148-552', 0, 248, 'v2.1.0', '88347aa8f3e8ffe99cf57f1fcd90a544a31cd88c5eef8b87331a875e830cafa1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 121","subsection":"UNKNOWN","table_id":null,"page":148,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":552,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 121"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p148-553', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 121', 148, 'Control Enhancements: (1) ALTERNATE STORAGE SITE | SEPARATION FROM PRIMARY SITE Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats. Discussion:  Threats that affect alternate storage sites are defined in organizational risk assessments and include natural disasters, structural failures, hostile attacks, and errors of', 'vec_doc-14-nist-sp-800-53-p148-553', 0, 102, 'v2.1.0', '965a3dbdb3dd4373c159de30113ee56a37d49a824cc1b6e38eab71f7fb2a1b50', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 121","subsection":"UNKNOWN","table_id":null,"page":148,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":553,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 121"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p149-554', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 122', 149, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate storage sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant. Related Controls:  RA-3. (2) ALTERNATE STORAGE SITE | RECOVERY TIME AND RECOVERY POINT OBJECTIVES Configure the alternate storage site to facilitate recovery operations in accordance with recovery time and recovery point objectives. Discussion:  Organizations establish recovery time and recovery point objectives as part of contingency planning. Configuration of the alternate storage site includes physical facilities and the systems supporting recovery operations that ensure accessibility and correct execution. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p149-554', 0, 231, 'v2.1.0', '7b0a9c876aab7d8160396fad725936aa4901b7eae9a2e8329767b965ac6b9bce', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 122","subsection":"UNKNOWN","table_id":null,"page":149,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":554,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 122"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p149-555', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 122', 149, '(3) ALTERNATE STORAGE SITE | ACCESSIBILITY Identify potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster and outline explicit mitigation actions. Discussion:  Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk. Explicit mitigation actions include duplicating backup information at other alternate storage sites if access problems occur at originally designated alternate sites or planning for physical access to retrieve backup information if electronic accessibility to the alternate site is disrupted. Related Controls:  RA-3. References:  [SP 800-34]. CP-7 ALTERNATE PROCESSING SITE Control: a.', 'vec_doc-14-nist-sp-800-53-p149-555', 0, 198, 'v2.1.0', '73aba8c797a58e33baa0fc368827c2476aa16795bf8f87577efcc414f7cd59f8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 122","subsection":"UNKNOWN","table_id":null,"page":149,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":555,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 122"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p149-556', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 122', 149, 'Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] when the primary processing capabilities are unavailable; b. Make available at the alternate processing site, the equipment and supplies required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; and c. Provide controls at the alternate processing site that are equivalent to those at the primary site. Discussion:  Alternate processing sites are geographically distinct from primary processing sites and provide processing capability if the primary processing site is not available.', 'vec_doc-14-nist-sp-800-53-p149-556', 0, 231, 'v2.1.0', '1b808d8ae9226bdc70561fe523c10b5512042dbffb9f372617aae5b649ac5aae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 122","subsection":"UNKNOWN","table_id":null,"page":149,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":556,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 122"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p149-557', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 122', 149, 'The alternate processing capability may be addressed using a physical processing site or other alternatives, such as failover to a cloud-based service provider or other internally or externally provided processing service. Geographically distributed architectures that support contingency requirements may also be considered alternate processing sites. Controls that are covered by alternate processing site agreements include the environmental conditions at alternate sites, access rules, physical and environmental protection requirements, and the coordination for the transfer and assignment of personnel. Requirements are allocated to alternate processing sites', 'vec_doc-14-nist-sp-800-53-p149-557', 0, 167, 'v2.1.0', '219103c8ce2ec1d1fcb5df66e78596f705069c27f89f1c75f281d4df7567e3ed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 122","subsection":"UNKNOWN","table_id":null,"page":149,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":557,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 122"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p150-558', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 123', 150, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 that reflect the requirements in contingency plans to maintain essential mission and business functions despite disruption, compromise, or failure in organizational systems. Related Controls:  CP-2, CP-6, CP-8, CP-9, CP-10, MA-6, PE-3, PE-11, PE-12, PE-17, SC-36, SI-13. Control Enhancements: (1) ALTERNATE PROCESSING SITE | SEPARATION FROM PRIMARY SITE Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats. Discussion:  Threats that affect alternate processing sites are defined in organizational assessments of risk and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate processing sites based on the types of threats that are of concern.', 'vec_doc-14-nist-sp-800-53-p150-558', 0, 247, 'v2.1.0', '37647efbc918c5f4200105fecafafff79a87bdaf9cf73adb9f846d53b2f53bbe', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 123","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":558,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 123"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p150-559', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 123', 150, 'For threats such as hostile attacks, the degree of separation between sites is less relevant. Related Controls:  RA-3. (2) ALTERNATE PROCESSING SITE | ACCESSIBILITY Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions. Discussion:  Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk. Related Controls:  RA-3. (3) ALTERNATE PROCESSING SITE | PRIORITY OF SERVICE Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).', 'vec_doc-14-nist-sp-800-53-p150-559', 0, 195, 'v2.1.0', 'b10d48e172229de767b50b55f0a783481f31881974c3768999509126bd7eca74', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 123","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":559,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 123"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p150-560', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 123', 150, 'Discussion:  Priority of service agreements refer to negotiated agreements with service providers that ensure that organizations receive priority treatment consistent with their availability requirements and the availability of information resources for logical alternate processing and/or at the physical alternate processing site. Organizations establish recovery time objectives as part of contingency planning. Related Controls:  None. (4) ALTERNATE PROCESSING SITE | PREPARATION FOR USE Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions. Discussion:  Site preparation includes establishing configuration settings for systems at the alternate processing site consistent with the requirements for such settings at the primary site and ensuring that essential supplies and logistical considerations are in place. Related Controls:  CM-2, CM-6, CP-4.', 'vec_doc-14-nist-sp-800-53-p150-560', 0, 236, 'v2.1.0', 'dba620285e0aeb6296bc9a0779844403ba5d779196c3699c911c584a5e678498', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 123","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":560,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 123"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p150-561', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 123', 150, '(5) ALTERNATE PROCESSING SITE | EQUIVALENT INFORMATION SECURITY SAFEGUARDS [Withdrawn: Incorporated into CP-7.] (6) ALTERNATE PROCESSING SITE | INABILITY TO RETURN TO PRIMARY SITE Plan and prepare for circumstances that preclude returning to the primary processing site. Discussion:  There may be situations that preclude an organization from returning to the primary processing site such as if a natural disaster (e.g., flood or a hurricane) damaged or', 'vec_doc-14-nist-sp-800-53-p150-561', 0, 114, 'v2.1.0', 'b0f1797e2d861cd8d8a6da7e79ac24eb2d151a8ac35774b5eaa82ba9f8dc4aad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 123","subsection":"UNKNOWN","table_id":null,"page":150,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":561,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 123"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p151-562', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 124', 151, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 destroyed a facility and it was determined that rebuilding in the same location was not prudent. Related Controls:  None. References:  [SP 800-34]. CP-8 TELECOMMUNICATIONS SERVICES Control:  Establish alternate telecommunications services, including necessary agreements to permit the resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites. Discussion:  Telecommunications services (for data and voice) for primary and alternate processing and storage sites are in scope for CP-8.', 'vec_doc-14-nist-sp-800-53-p151-562', 0, 203, 'v2.1.0', '5f749d1777ebcf76acef62154cfb3cb67295103ac7a2f3b57b32f377c67de670', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 124","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":562,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 124"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p151-563', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 124', 151, 'Alternate telecommunications services reflect the continuity requirements in contingency plans to maintain essential mission and business functions despite the loss of primary telecommunications services. Organizations may specify different time periods for primary or alternate sites. Alternate telecommunications services include additional organizational or commercial ground-based circuits or lines, network-based approaches to telecommunications, or the use of satellites. Organizations consider factors such as availability, quality of service, and access when entering into alternate telecommunications agreements. Related Controls:  CP-2, CP-6, CP-7, CP-11, SC-7.', 'vec_doc-14-nist-sp-800-53-p151-563', 0, 168, 'v2.1.0', '9a75f922e3480f0fab983e6f8ad142fedc465337d824ea4d742868cd45f86a29', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 124","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":563,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 124"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p151-564', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 124', 151, 'Control Enhancements: (1) TELECOMMUNICATIONS SERVICES | PRIORITY OF SERVICE PROVISIONS (a) Develop primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and (b) Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier. Discussion:  Organizations consider the potential mission or business impact in situations where telecommunications service providers are servicing other organizations with similar priority of service provisions.', 'vec_doc-14-nist-sp-800-53-p151-564', 0, 183, 'v2.1.0', 'fd7cecb3b0c958acf1b8d6a9f3be5d1aa5fe9fd9c93909b0a697cf784d2a5ac0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 124","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":564,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 124"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p151-565', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 124', 151, 'Telecommunications Service Priority (TSP) is a Federal Communications Commission (FCC) program that directs telecommunications service providers (e.g., wireline and wireless phone companies) to give preferential treatment to users enrolled in the program when they need to add new lines or have their lines restored following a disruption of service, regardless of the cause. The FCC sets the rules and policies for the TSP program, and the Department of Homeland Security manages the TSP program. The TSP program is always in effect and not contingent on a major disaster or attack taking place. Federal sponsorship is required to enroll in the TSP program. Related Controls:  None. (2) TELECOMMUNICATIONS SERVICES | SINGLE POINTS OF FAILURE Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.', 'vec_doc-14-nist-sp-800-53-p151-565', 0, 223, 'v2.1.0', '0ff4c9befd6c71c8fd8cbe3efc68ff69856187940056d242f6c1c10b51b671d1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 124","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":565,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 124"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p151-566', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 124', 151, 'Discussion:  In certain circumstances, telecommunications service providers or services may share the same physical lines, which increases the vulnerability of a single failure point. It is important to have provider transparency for the actual physical transmission capability for telecommunication services.', 'vec_doc-14-nist-sp-800-53-p151-566', 0, 78, 'v2.1.0', 'c4fa4302387a5effeffa986edc278d8853d935d66db873fb8502b541fd8754a1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 124","subsection":"UNKNOWN","table_id":null,"page":151,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":566,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 124"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p152-567', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 125', 152, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (3) TELECOMMUNICATIONS SERVICES | SEPARATION OF PRIMARY AND ALTERNATE PROVIDERS Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats. Discussion:  Threats that affect telecommunications services are defined in organizational assessments of risk and include natural disasters, structural failures, cyber or physical attacks, and errors of omission or commission. Organizations can reduce common susceptibilities by minimizing shared infrastructure among telecommunications service providers and achieving sufficient geographic separation between services. Organizations may consider using a single service provider in situations where the service provider can provide alternate telecommunications services that meet the separation needs addressed in the risk assessment.', 'vec_doc-14-nist-sp-800-53-p152-567', 0, 247, 'v2.1.0', 'f6237cb55f47552aba85a52a55cc471e91804d72c22233bab8f76ae706affd48', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 125","subsection":"UNKNOWN","table_id":null,"page":152,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":567,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 125"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p152-568', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 125', 152, 'Related Controls:  None. (4) TELECOMMUNICATIONS SERVICES | PROVIDER CONTINGENCY PLAN (a) Require primary and alternate telecommunications service providers to have contingency plans; (b) Review provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtain evidence of contingency testing and training by providers [Assignment: organization-defined frequency]. Discussion:  Reviews of provider contingency plans consider the proprietary nature of such plans. In some situations, a summary of provider contingency plans may be sufficient evidence for organizations to satisfy the review requirement. Telecommunications service providers may also participate in ongoing disaster recovery exercises in coordination with the Department of Homeland Security and state and local governments. Organizations may use these types of activities to satisfy evidentiary requirements related to service provider contingency plan reviews, testing, and training.', 'vec_doc-14-nist-sp-800-53-p152-568', 0, 249, 'v2.1.0', '9a725274208ec6e8d7ffe6eb4ecf7f19cc2dcb36d6dd4897cda0de4a9267b7f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 125","subsection":"UNKNOWN","table_id":null,"page":152,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":568,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 125"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p152-569', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 125', 152, 'Related Controls:  CP-3, CP-4. (5) TELECOMMUNICATIONS SERVICES | ALTERNATE TELECOMMUNICATION SERVICE TESTING Test alternate telecommunication services [Assignment: organization-defined frequency]. Discussion:  Alternate telecommunications services testing is arranged through contractual agreements with service providers. The testing may occur in parallel with normal operations to ensure that there is no degradation in organizational missions or functions. Related Controls:  CP-3. References:  [SP 800-34]. CP-9 SYSTEM BACKUP Control: a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives]; b. Conduct backups of system-level information contained in the system [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];', 'vec_doc-14-nist-sp-800-53-p152-569', 0, 233, 'v2.1.0', '4244fc9970ed07f748937037b40cd8949e53d0e5a15d494ebaa854305e334d8d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 125","subsection":"UNKNOWN","table_id":null,"page":152,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":569,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 125"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p153-570', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 126', 153, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 c. Conduct backups of system documentation, including security- and privacy-related documentation [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives]; and d. Protect the confidentiality, integrity, and availability of backup information. Discussion:  System-level information includes system state information, operating system software, middleware, application software, and licenses. User-level information includes information other than system-level information. Mechanisms employed to protect the integrity of system backups include digital signatures and cryptographic hashes. Protection of system backup information while in transit is addressed by MP-5 and SC-8. System backups reflect the requirements in contingency plans as well as other organizational requirements for backing up information.', 'vec_doc-14-nist-sp-800-53-p153-570', 0, 238, 'v2.1.0', 'f1220b1e82f95b96d89e24933a1b018e8b2afd5447b1c4bfc39fd93d7b1eb6c1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 126","subsection":"UNKNOWN","table_id":null,"page":153,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":570,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 126"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p153-571', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 126', 153, 'Organizations may be subject to laws, executive orders, directives, regulations, or policies with requirements regarding specific categories of information (e.g., personal health information). Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements. Related Controls:  CP-2, CP-6, CP-10, MP-4, MP-5, SC-8, SC-12, SC-13, SI-4, SI-13. Control Enhancements: (1) SYSTEM BACKUP | TESTING FOR RELIABILITY AND INTEGRITY Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity. Discussion:  Organizations need assurance that backup information can be reliably retrieved. Reliability pertains to the systems and system components where the backup information is stored, the operations used to retrieve the information, and the integrity of the information being retrieved. Independent and specialized tests can be used for each of the aspects of reliability.', 'vec_doc-14-nist-sp-800-53-p153-571', 0, 246, 'v2.1.0', '74f665a51a80b68c6eddf14c9b9f12cbe9204d0f00d18cc1bcf93bd8c68efb62', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 126","subsection":"UNKNOWN","table_id":null,"page":153,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":571,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 126"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p153-572', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 126', 153, 'For example, decrypting and transporting (or transmitting) a random sample of backup files from the alternate storage or backup site and comparing the information to the same information at the primary processing site can provide such assurance. Related Controls:  CP-4. (2) SYSTEM BACKUP | TEST RESTORATION USING SAMPLING Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing. Discussion:  Organizations need assurance that system functions can be restored correctly and can support established organizational missions. To ensure that the selected system functions are thoroughly exercised during contingency plan testing, a sample of backup information is retrieved to determine whether the functions are operating as intended. Organizations can determine the sample size for the functions and backup information based on the level of assurance needed. Related Controls:  CP-4.', 'vec_doc-14-nist-sp-800-53-p153-572', 0, 236, 'v2.1.0', '6d6d5af69255bb437120d5861bd63c9c4d6a43787fa6b8454d8289de4b17dc70', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 126","subsection":"UNKNOWN","table_id":null,"page":153,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":572,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 126"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p153-573', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 126', 153, '(3) SYSTEM BACKUP | SEPARATE STORAGE FOR CRITICAL INFORMATION Store backup copies of [Assignment: organization-defined critical system software and other security-related information] in a separate facility or in a fire rated container that is not collocated with the operational system. Discussion:  Separate storage for critical information applies to all critical information regardless of the type of backup storage media. Critical system software includes operating systems, middleware, cryptographic key management systems, and intrusion detection systems. Security-related information includes inventories of system hardware, software, and firmware components. Alternate storage sites, including geographically distributed architectures, serve as separate storage facilities for organizations. Organizations may', 'vec_doc-14-nist-sp-800-53-p153-573', 0, 205, 'v2.1.0', 'e2627615b9a1fba46b673860b70eeca10ead2d88a2d35131ae8cd45ba556a0a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 126","subsection":"UNKNOWN","table_id":null,"page":153,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":573,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 126"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p154-574', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 127', 154, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 provide separate storage by implementing automated backup processes at alternative storage sites (e.g., data centers). The General Services Administration (GSA) establishes standards and specifications for security and fire rated containers. Related Controls:  CM-2, CM-6, CM-8. (4) SYSTEM BACKUP | PROTECTION FROM UNAUTHORIZED MODIFICATION [Withdrawn: Incorporated into CP-9.] (5) SYSTEM BACKUP | TRANSFER TO ALTERNATE STORAGE SITE Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives]. Discussion:  System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media. Related Controls:  CP-7, MP-3, MP-4, MP-5.', 'vec_doc-14-nist-sp-800-53-p154-574', 0, 229, 'v2.1.0', 'd9d371f85fded9e0c0a2a4e7f76fbd73ee8f8b670742e2749485ba6c9108e52e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 127","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":574,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 127"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p154-575', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 127', 154, '(6) SYSTEM BACKUP | REDUNDANT SECONDARY SYSTEM Conduct system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations. Discussion:  The effect of system backup can be achieved by maintaining a redundant secondary system that mirrors the primary system, including the replication of information. If this type of redundancy is in place and there is sufficient geographic separation between the two systems, the secondary system can also serve as the alternate processing site. Related Controls:  CP-7. (7) SYSTEM BACKUP | DUAL AUTHORIZATION FOR DELETION OR DESTRUCTION Enforce dual authorization for the deletion or destruction of [Assignment: organization- defined backup information]. Discussion:  Dual authorization ensures that deletion or destruction of backup information cannot occur unless two qualified individuals carry out the task.', 'vec_doc-14-nist-sp-800-53-p154-575', 0, 242, 'v2.1.0', 'dc290214d9c99ca96c15190bdfa5f918051d2ec1240e415183ac562ab3caa731', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 127","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":575,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 127"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p154-576', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 127', 154, 'Individuals deleting or destroying backup information possess the skills or expertise to determine if the proposed deletion or destruction of information reflects organizational policies and procedures. Dual authorization may also be known as two-person control. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals. Related Controls:  AC-3, AC-5, MP-2. (8) SYSTEM BACKUP | CRYPTOGRAPHIC PROTECTION Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of [Assignment: organization-defined backup information]. Discussion:  The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of backup information. The strength of mechanisms selected is commensurate with the security category or classification of the information. Cryptographic protection applies to system backup information in storage at both primary and alternate locations.', 'vec_doc-14-nist-sp-800-53-p154-576', 0, 245, 'v2.1.0', '0261e35f3f8d1f35423185abdde52f8150bf95f231f78e880ee3598538cde63e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 127","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":576,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 127"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p154-577', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 127', 154, 'Organizations that implement cryptographic mechanisms to protect information at rest also consider cryptographic key management solutions. Related Controls:  SC-12, SC-13, SC-28. References:  [FIPS 140-3], [FIPS 186-4], [SP 800-34], [SP 800-130], [SP 800-152].', 'vec_doc-14-nist-sp-800-53-p154-577', 0, 65, 'v2.1.0', '3c66e0454fd4c67691468d4cefb27a2985d7531ce89e0cb07d5ae85ecd5de589', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 127","subsection":"UNKNOWN","table_id":null,"page":154,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":577,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 127"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p155-578', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 128', 155, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 CP-10 SYSTEM RECOVERY AND RECONSTITUTION Control:  Provide for the recovery and reconstitution of the system to a known state within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] after a disruption, compromise, or failure. Discussion:  Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes activities for returning systems to fully operational states. Recovery and reconstitution operations reflect mission and business priorities; recovery point, recovery time, and reconstitution objectives; and organizational metrics consistent with contingency plan requirements. Reconstitution includes the deactivation of interim system capabilities that may have been needed during recovery operations.', 'vec_doc-14-nist-sp-800-53-p155-578', 0, 240, 'v2.1.0', '4a74753d971b26bb5a26308a8bc604032ba0407f412eeed91e5480e1288c6e20', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 128","subsection":"UNKNOWN","table_id":null,"page":155,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":578,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 128"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p155-579', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 128', 155, 'Reconstitution also includes assessments of fully restored system capabilities, reestablishment of continuous monitoring activities, system reauthorization (if required), and activities to prepare the system and organization for future disruptions, breaches, compromises, or failures. Recovery and reconstitution capabilities can include automated mechanisms and manual procedures. Organizations establish recovery time and recovery point objectives as part of contingency planning. Related Controls:  CP-2, CP-4, CP-6, CP-7, CP-9, IR-4, SA-8, SC-24, SI-13. Control Enhancements: (1) SYSTEM RECOVERY AND RECONSTITUTION | CONTINGENCY PLAN TESTING [Withdrawn: Incorporated into CP-4.] (2) SYSTEM RECOVERY AND RECONSTITUTION | TRANSACTION RECOVERY Implement transaction recovery for systems that are transaction-based. Discussion:  Transaction-based systems include database management systems and transaction processing systems.', 'vec_doc-14-nist-sp-800-53-p155-579', 0, 232, 'v2.1.0', '6ed2a08f09601e22014bc3a1a6e3f6d51b164c2d280c362481ff8f5a4468585f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 128","subsection":"UNKNOWN","table_id":null,"page":155,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":579,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 128"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p155-580', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 128', 155, 'Mechanisms supporting transaction recovery include transaction rollback and transaction journaling. Related Controls:  None. (3) SYSTEM RECOVERY AND RECONSTITUTION | COMPENSATING SECURITY CONTROLS [Withdrawn: Addressed through tailoring.] (4) SYSTEM RECOVERY AND RECONSTITUTION | RESTORE WITHIN TIME PERIOD Provide the capability to restore system components within [Assignment: organization- defined restoration time periods] from configuration-controlled and integrity-protected information representing a known, operational state for the components. Discussion:  Restoration of system components includes reimaging, which restores the components to known, operational states. Related Controls:  CM-2, CM-6. (5) SYSTEM RECOVERY AND RECONSTITUTION | FAILOVER CAPABILITY [Withdrawn: Incorporated into SI-13.] (6) SYSTEM RECOVERY AND RECONSTITUTION | COMPONENT PROTECTION Protect system components used for recovery and reconstitution.', 'vec_doc-14-nist-sp-800-53-p155-580', 0, 234, 'v2.1.0', 'c838a4eecf79813feadc6432d0ea264bbc60554cef1a5813e6ca5805d22e4c90', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 128","subsection":"UNKNOWN","table_id":null,"page":155,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":580,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 128"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p155-581', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 128', 155, 'Discussion:  Protection of system recovery and reconstitution components (i.e., hardware, firmware, and software) includes physical and technical controls. Backup and restoration components used for recovery and reconstitution include router tables, compilers, and other system software. Related Controls:  AC-3, AC-6, MP-2, MP-4, PE-3, PE-6.', 'vec_doc-14-nist-sp-800-53-p155-581', 0, 86, 'v2.1.0', '9fdd2b39ed64c94a6b58db7b888653ec9084f4130af1ec11bb174cc98b22ae0b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 128","subsection":"UNKNOWN","table_id":null,"page":155,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":581,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 128"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p156-582', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 129', 156, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 References:  [SP 800-34]. CP-11 ALTERNATE COMMUNICATIONS PROTOCOLS Control:  Provide the capability to employ [Assignment: organization-defined alternative communications protocols] in support of maintaining continuity of operations. Discussion:  Contingency plans and the contingency training or testing associated with those plans incorporate an alternate communications protocol capability as part of establishing resilience in organizational systems. Switching communications protocols may affect software applications and operational aspects of systems. Organizations assess the potential side effects of introducing alternate communications protocols prior to implementation. Related Controls:  CP-2, CP-8, CP-13. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p156-582', 0, 215, 'v2.1.0', '53d976c2281790b36690823ed6a750f0fc65169ed2560217f7a37e3667c10f71', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 129","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":582,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 129"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p156-583', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 129', 156, 'CP-12 SAFE MODE Control:  When [Assignment: organization-defined conditions] are detected, enter a safe mode of operation with [Assignment: organization-defined restrictions of safe mode of operation]. Discussion:  For systems that support critical mission and business functions— including military operations, civilian space operations, nuclear power plant operations, and air traffic control operations (especially real-time operational environments)— organizations can identify certain conditions under which those systems revert to a predefined safe mode of operation. The safe mode of operation, which can be activated either automatically or manually, restricts the operations that systems can execute when those conditions are encountered. Restriction includes allowing only selected functions to execute that can be carried out under limited power or with reduced communications bandwidth. Related Controls:  CM-2, SA-8, SC-24, SI-13, SI-17. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p156-583', 0, 250, 'v2.1.0', '952c0c9232c92977ad7b56b7d15660236c12e8875edb9760e72754b941b0f3ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 129","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":583,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 129"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p156-584', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 129', 156, 'CP-13 ALTERNATIVE SECURITY MECHANISMS Control:  Employ [Assignment: organization-defined alternative or supplemental security mechanisms] for satisfying [Assignment: organization-defined security functions] when the primary means of implementing the security function is unavailable or compromised. Discussion:  Use of alternative security mechanisms supports system resiliency, contingency planning, and continuity of operations. To ensure mission and business continuity, organizations can implement alternative or supplemental security mechanisms. The mechanisms may be less effective than the primary mechanisms. However, having the capability to readily employ alternative or supplemental mechanisms enhances mission and business continuity that might otherwise be adversely impacted if operations had to be curtailed until the primary means of implementing the functions was restored.', 'vec_doc-14-nist-sp-800-53-p156-584', 0, 223, 'v2.1.0', 'f48259630a49bd3b24ef650f1cb3cb445b0492a93f03ff68f930495faa03f1a5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 129","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":584,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 129"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p156-585', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 129', 156, 'Given the cost and level of effort required to provide such alternative capabilities, the alternative or supplemental mechanisms are only applied to critical security capabilities provided by systems, system components, or system services. For example, an organization may issue one-time pads to senior executives, officials, and system administrators if multi-factor tokens— the standard means for achieving secure authentication— are compromised. Related Controls:  CP-2, CP-11, SI-13.', 'vec_doc-14-nist-sp-800-53-p156-585', 0, 122, 'v2.1.0', '39b65f4d437d8a5899570cb2f7a38e204f2fcb9187e182f722a87ddec5d81199', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 129","subsection":"UNKNOWN","table_id":null,"page":156,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":585,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 129"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p157-586', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 130', 157, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None References:  None.', 'vec_doc-14-nist-sp-800-53-p157-586', 0, 35, 'v2.1.0', '308f8d7686ba917c92ad84f25245ab427314cf2b898a881c9737ca5e92f3af6b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 130","subsection":"UNKNOWN","table_id":null,"page":157,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":586,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 130"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p158-587', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.7   IDENTIFICATION AND AUTHENTICATION', 158, 'Quick link to Identification and Authentication Summary Table IA-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p158-587', 0, 49, 'v2.1.0', '019e62dd8dbaed95b15a33939c13740e072b4852ee7a30e7dd6987139113ba95', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.7   IDENTIFICATION AND AUTHENTICATION","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":587,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.7   IDENTIFICATION AND AUTHENTICATION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p158-588', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 158, 'level] identification and authentication policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p158-588', 0, 80, 'v2.1.0', '2138c0cb74676f51ebea31b8e3a9a711422a05309a76ed7bf77d64ed037143ad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":588,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p158-589', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the identification and authentication', 158, 'policy and the associated identification and authentication controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the identification and authentication policy and procedures; and c. Review and update the current identification and authentication:', 'vec_doc-14-nist-sp-800-53-p158-589', 0, 82, 'v2.1.0', '261aca8203976ed2aee41bf942fe4e30168a00e9605bc44d36f6dad3f18e7d09', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the identification and authentication","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":589,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the identification and authentication"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p158-590', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 158, 'organization-defined events]. Discussion:  Identification and authentication policy and procedures address the controls in the IA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of identification and authentication policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed.', 'vec_doc-14-nist-sp-800-53-p158-590', 0, 249, 'v2.1.0', '18805259bd2f65157a179b2240f68efc1e909af458112fc029c968109e326c33', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":590,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p158-591', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 158, 'Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to identification and authentication policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  AC-1, PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [FIPS 201-2], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-63-3], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4], [SP 800-100], [IR 7874].', 'vec_doc-14-nist-sp-800-53-p158-591', 0, 213, 'v2.1.0', '437e855c3da06d38e179bf70df3c8c52e980bb0e2210ca4136b89f5c40aca887', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":158,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":591,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p159-592', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 132', 159, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 IA-2 IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) Control:  Uniquely identify and authenticate organizational users and associate that unique identification with processes acting on behalf of those users. Discussion:  Organizations can satisfy the identification and authentication requirements by complying with the requirements in [HSPD 12]. Organizational users include employees or individuals who organizations consider to have an equivalent status to employees (e.g., contractors and guest researchers). Unique identification and authentication of users applies to all accesses other than those that are explicitly identified in AC-14 and that occur through the authorized use of group authenticators without individual authentication.', 'vec_doc-14-nist-sp-800-53-p159-592', 0, 212, 'v2.1.0', '41daf7d10c08f12db25f71d809e33f6f686b06dcdf2340812f74e5200f6f950e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 132","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":592,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 132"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p159-593', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 132', 159, 'Since processes execute on behalf of groups and roles, organizations may require unique identification of individuals in group accounts or for detailed accountability of individual activity. Organizations employ passwords, physical authenticators, or biometrics to authenticate user identities or, in the case of multi-factor authentication, some combination thereof. Access to organizational systems is defined as either local access or network access. Local access is any access to organizational systems by users or processes acting on behalf of users, where access is obtained through direct connections without the use of networks. Network access is access to organizational systems by users (or processes acting on behalf of users) where access is obtained through network connections (i.e., nonlocal accesses). Remote access is a type of network access that involves communication through external networks. Internal networks include local area networks and wide area networks.', 'vec_doc-14-nist-sp-800-53-p159-593', 0, 246, 'v2.1.0', '2f8181016f213c37580c1cd0248fcbebfba8aab172d92f679a1fc621597ad104', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 132","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":593,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 132"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p159-594', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 132', 159, 'The use of encrypted virtual private networks for network connections between organization- controlled endpoints and non-organization-controlled endpoints may be treated as internal networks with respect to protecting the confidentiality and integrity of information traversing the network. Identification and authentication requirements for non-organizational users are described in IA-8 . Related Controls:  AC-2, AC-3, AC-4, AC-14, AC-17, AC-18, AU-1, AU-6, IA-4, IA-5, IA-8, MA-4, MA- 5, PE-2, PL-4, SA-4, SA-8. Control Enhancements: (1) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | MULTI-FACTOR AUTHENTICATION TO PRIVILEGED ACCOUNTS Implement multi-factor authentication for access to privileged accounts. Discussion:  Multi-factor authentication requires the use of two or more different factors to achieve authentication.', 'vec_doc-14-nist-sp-800-53-p159-594', 0, 211, 'v2.1.0', '771b279a9b50934a33a7502d060725322fccd49c87598fbc0f02ea8966db7048', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 132","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":594,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 132"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p159-595', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 132', 159, 'The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification (PIV) card or the Department of Defense (DoD) Common Access Card (CAC). In addition to authenticating users at the system level (i.e., at logon), organizations may employ authentication mechanisms at the application level, at their discretion, to provide increased security. Regardless of the type of access (i.e., local, network, remote), privileged accounts are authenticated using multi-factor options appropriate for the level of risk.', 'vec_doc-14-nist-sp-800-53-p159-595', 0, 231, 'v2.1.0', '49a3108adc37cc676f0fd557c1c474fe8d680b0293c4798a9a175690deee0247', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 132","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":595,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 132"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p159-596', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 132', 159, 'Organizations can add additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access. Related Controls:  AC-5, AC-6. (2) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | MULTI-FACTOR AUTHENTICATION TO NON-PRIVILEGED ACCOUNTS', 'vec_doc-14-nist-sp-800-53-p159-596', 0, 74, 'v2.1.0', '1c0e5debe310119b992f64dc6c1c32525e00e3aaa5fe675488e60813ca008f3c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 132","subsection":"UNKNOWN","table_id":null,"page":159,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":596,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 132"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p160-597', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 133', 160, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Implement multi-factor authentication for access to non-privileged accounts. Discussion:  Multi-factor authentication requires the use of two or more different factors to achieve authentication. The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification card or the DoD Common Access Card.', 'vec_doc-14-nist-sp-800-53-p160-597', 0, 202, 'v2.1.0', 'd79a8dd2b999c823af57de6b37eec628c48a16889f54f67795f8a13b181f31e4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 133","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":597,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 133"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p160-598', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 133', 160, 'In addition to authenticating users at the system level, organizations may also employ authentication mechanisms at the application level, at their discretion, to provide increased information security. Regardless of the type of access (i.e., local, network, remote), non- privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can provide additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access. Related Controls:  AC-5.', 'vec_doc-14-nist-sp-800-53-p160-598', 0, 137, 'v2.1.0', 'edd0331a18673dabe39b9a17e7fce676a5e1891849e4fb47b4ec2eb97d1a162c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 133","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":598,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 133"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p160-599', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 133', 160, '(3) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | LOCAL ACCESS TO PRIVILEGED ACCOUNTS [Withdrawn: Incorporated into IA-2(1).] (4) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | LOCAL ACCESS TO NON- PRIVILEGED ACCOUNTS [Withdrawn: Incorporated into IA-2(2).] (5) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | INDIVIDUAL AUTHENTICATION WITH GROUP AUTHENTICATION When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources. Discussion:  Individual authentication prior to shared group authentication mitigates the risk of using group accounts or authenticators. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p160-599', 0, 180, 'v2.1.0', '7ac33ee30229d79330920d6e228625f856b2b47ec7e64dd1fa1e4ff1a8a88316', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 133","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":599,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 133"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p160-600', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 133', 160, '(6) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | ACCESS TO ACCOUNTS — SEPARATE DEVICE Implement multi-factor authentication for [Selection (one or more): local; network; remote] access to [Selection (one or more): privileged accounts; non-privileged accounts] such that: (a) One of the factors is provided by a device separate from the system gaining access; and (b) The device meets [Assignment: organization-defined strength of mechanism requirements]. Discussion:  The purpose of requiring a device that is separate from the system to which the user is attempting to gain access for one of the factors during multi-factor authentication is to reduce the likelihood of compromising authenticators or credentials stored on the system. Adversaries may be able to compromise such authenticators or credentials and subsequently impersonate authorized users.', 'vec_doc-14-nist-sp-800-53-p160-600', 0, 218, 'v2.1.0', '2eab155b2b9ecc6c6e2de94221b083720992064c230195f619b1d02f5d0d5685', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 133","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":600,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 133"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p160-601', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 133', 160, 'Implementing one of the factors on a separate device (e.g., a hardware token), provides a greater strength of mechanism and an increased level of assurance in the authentication process. Related Controls:  AC-6.', 'vec_doc-14-nist-sp-800-53-p160-601', 0, 53, 'v2.1.0', '216083f81c5e4a30ea285dc8a3c50e6cdb1b759ca7af7a292ed7bd6a9669a374', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 133","subsection":"UNKNOWN","table_id":null,"page":160,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":601,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 133"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p161-602', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 134', 161, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (7) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | NETWORK ACCESS TO NON- PRIVILEGED ACCOUNTS —  SEPARATE DEVICE [Withdrawn: Incorporated into IA-2(6).] (8) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | ACCESS TO ACCOUNTS — REPLAY RESISTANT Implement replay-resistant authentication mechanisms for access to [Selection (one or more): privileged accounts; non-privileged accounts]. Discussion:  Authentication processes resist replay attacks if it is impractical to achieve successful authentications by replaying previous authentication messages. Replay-resistant techniques include protocols that use nonces or challenges such as time synchronous or cryptographic authenticators. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p161-602', 0, 206, 'v2.1.0', '361bafd6bf078e26333430ca7c85cfebebf3036e06967438b935bbae85101476', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 134","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":602,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 134"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p161-603', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 134', 161, '(9) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | NETWORK ACCESS TO NON- PRIVILEGED ACCOUNTS —  REPLAY RESISTANT [Withdrawn: Incorporated into IA-2(8).] (10) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | SINGLE SIGN-ON Provide a single sign-on capability for [Assignment: organization-defined system accounts and services]. Discussion:  Single sign-on enables users to log in once and gain access to multiple system resources. Organizations consider the operational efficiencies provided by single sign-on capabilities with the risk introduced by allowing access to multiple systems via a single authentication event. Single sign-on can present opportunities to improve system security, for example by providing the ability to add multi-factor authentication for applications and systems (existing and new) that may not be able to natively support multi-factor authentication. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p161-603', 0, 232, 'v2.1.0', 'ba6046696a9e13c23c777f6931eddd08706c759c547706936e7eea4c38e9f8bf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 134","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":603,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 134"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p161-604', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 134', 161, '(11) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | REMOTE ACCESS —  SEPARATE DEVICE [Withdrawn: Incorporated into IA-2(6).] (12) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | ACCEPTANCE OF PIV CREDENTIALS Accept and electronically verify Personal Identity Verification-compliant credentials. Discussion:  Acceptance of Personal Identity Verification (PIV)-compliant credentials applies to organizations implementing logical access control and physical access control systems. PIV-compliant credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidance documents. The adequacy and reliability of PIV card issuers are authorized using [SP 800-79-2]. Acceptance of PIV-compliant credentials includes derived PIV credentials, the use of which is addressed in [SP 800-166]. The DOD Common Access Card (CAC) is an example of a PIV credential. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p161-604', 0, 237, 'v2.1.0', '0d2f3d57351411d524bcd24a08c41c28a574ddaad4ae9cd9acd25827e3740636', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 134","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":604,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 134"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p161-605', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 134', 161, '(13) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | OUT-OF-BAND AUTHENTICATION Implement the following out-of-band authentication mechanisms under [Assignment: organization-defined conditions]: [Assignment: organization-defined out-of-band authentication].', 'vec_doc-14-nist-sp-800-53-p161-605', 0, 67, 'v2.1.0', '7dc17f304af8312bfc6bb88d3002e3d57fe0c385cdb3628c4d853e44934d6df9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 134","subsection":"UNKNOWN","table_id":null,"page":161,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":605,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 134"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p162-606', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 135', 162, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion: Out-of-band authentication refers to the use of two separate communication paths to identify and authenticate users or devices to an information system. The first path (i.e., the in-band path) is used to identify and authenticate users or devices and is generally the path through which information flows. The second path (i.e., the out-of-band path) is used to independently verify the authentication and/or requested action. For example, a user authenticates via a notebook computer to a remote server to which the user desires access and requests some action of the server via that communication path. Subsequently, the server contacts the user via the user’s cell phone to verify that the requested action originated from the user. The user may confirm the intended action to an individual on the telephone or provide an authentication code via the telephone.', 'vec_doc-14-nist-sp-800-53-p162-606', 0, 242, 'v2.1.0', '9a82e1e4ee5eaca7b20c7036314b96f6bc974d61c52189f673df28f19a3cae53', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 135","subsection":"UNKNOWN","table_id":null,"page":162,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":606,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 135"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p162-607', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 135', 162, 'Out-of-band authentication can be used to mitigate actual or suspected “man-in the-middle” attacks. The conditions or criteria for activation include suspicious activities, new threat indicators, elevated threat levels, or the impact or classification level of information in requested transactions. Related Controls:  IA-10, IA-11, SC-37. References:  [FIPS 140-3], [FIPS 201-2], [FIPS 202], [SP 800-63-3], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4], [SP 800-79-2], [SP 800-156], [SP 800-166], [IR 7539], [IR 7676], [IR 7817], [IR 7849], [IR 7870], [IR 7874], [IR 7966]. IA-3 DEVICE IDENTIFICATION AND AUTHENTICATION Control:  Uniquely identify and authenticate [Assignment: organization-defined devices and/or types of devices] before establishing a [Selection (one or more): local; remote; network] connection. Discussion:  Devices that require unique device-to-device identification and authentication are defined by type, device, or a combination of type and device.', 'vec_doc-14-nist-sp-800-53-p162-607', 0, 243, 'v2.1.0', 'd5a2813c005a8a3024ffd11892e258a8f87d4967ccfd1925636d66224dbf613d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 135","subsection":"UNKNOWN","table_id":null,"page":162,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":607,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 135"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p162-608', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 135', 162, 'Organization-defined device types include devices that are not owned by the organization. Systems use shared known information (e.g., Media Access Control [MAC], Transmission Control Protocol/Internet Protocol [TCP/IP] addresses) for device identification or organizational authentication solutions (e.g., Institute of Electrical and Electronics Engineers (IEEE) 802.1x and Extensible Authentication Protocol [EAP], RADIUS server with EAP-Transport Layer Security [TLS] authentication, Kerberos) to identify and authenticate devices on local and wide area networks. Organizations determine the required strength of authentication mechanisms based on the security categories of systems and mission or business requirements. Because of the challenges of implementing device authentication on a large scale, organizations can restrict the application of the control to a limited number/type of devices based on mission or business needs.', 'vec_doc-14-nist-sp-800-53-p162-608', 0, 234, 'v2.1.0', 'f116950232b2bd8aca6726ce7414f16e9bfe43af717adcad4ba97c143f0ff200', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 135","subsection":"UNKNOWN","table_id":null,"page":162,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":608,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 135"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p162-609', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 135', 162, 'Related Controls:  AC-17, AC-18, AC-19, AU-6, CA-3, CA-9, IA-4, IA-5, IA-9, IA-11, SI-4. Control Enhancements: (1) DEVICE IDENTIFICATION AND AUTHENTICATION | CRYPTOGRAPHIC BIDIRECTIONAL AUTHENTICATION Authenticate [Assignment: organization-defined devices and/or types of devices] before establishing [Selection (one or more): local; remote; network] connection using bidirectional authentication that is cryptographically based. Discussion:  A local connection is a connection with a device that communicates without the use of a network. A network connection is a connection with a device that communicates through a network. A remote connection is a connection with a device that communicates through an external network. Bidirectional authentication provides stronger protection to validate the identity of other devices for connections that are of greater risk. Related Controls:  SC-8, SC-12, SC-13. (2) DEVICE IDENTIFICATION AND AUTHENTICATION | CRYPTOGRAPHIC BIDIRECTIONAL NETWORK AUTHENTICATION', 'vec_doc-14-nist-sp-800-53-p162-609', 0, 251, 'v2.1.0', 'd012ce996bbfc41e34af91f8812586c285ecf7b3c918f863c151d88ef739161b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 135","subsection":"UNKNOWN","table_id":null,"page":162,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":609,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 135"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p163-610', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 136', 163, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Incorporated into IA-3(1).] (3) DEVICE IDENTIFICATION AND AUTHENTICATION | DYNAMIC ADDRESS ALLOCATION (a) Where addresses are allocated dynamically, standardize dynamic address allocation lease information and the lease duration assigned to devices in accordance with [Assignment: organization-defined lease information and lease duration]; and (b) Audit lease information when assigned to a device. Discussion:  The Dynamic Host Configuration Protocol (DHCP) is an example of a means by which clients can dynamically receive network address assignments. Related Controls:  AU-2. (4) DEVICE IDENTIFICATION AND AUTHENTICATION | DEVICE ATTESTATION Handle device identification and authentication based on attestation by [Assignment: organization-defined configuration management process].', 'vec_doc-14-nist-sp-800-53-p163-610', 0, 223, 'v2.1.0', '91fed722c012d24e2ce2507a9d2bca9fc5c71917a338c4f4a00ec022847cbf33', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 136","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":610,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 136"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p163-611', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 136', 163, 'Discussion:  Device attestation refers to the identification and authentication of a device based on its configuration and known operating state. Device attestation can be determined via a cryptographic hash of the device. If device attestation is the means of identification and authentication, then it is important that patches and updates to the device are handled via a configuration management process such that the patches and updates are done securely and do not disrupt identification and authentication to other devices. Related Controls:  CM-2, CM-3, CM-6. References:  None. IA-4 IDENTIFIER MANAGEMENT Control:  Manage system identifiers by: a. Receiving authorization from [Assignment: organization-defined personnel or roles] to assign an individual, group, role, service, or device identifier; b. Selecting an identifier that identifies an individual, group, role, service, or device; c. Assigning the identifier to the intended individual, group, role, service, or device; and d.', 'vec_doc-14-nist-sp-800-53-p163-611', 0, 249, 'v2.1.0', 'd998c2f24be10465e6c79d9565699a7d0127888fe340ac58b9b9f52901558b2e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 136","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":611,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 136"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p163-612', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 136', 163, 'Preventing reuse of identifiers for [Assignment: organization-defined time period]. Discussion:  Common device identifiers include Media Access Control (MAC) addresses, Internet Protocol (IP) addresses, or device-unique token identifiers. The management of individual identifiers is not applicable to shared system accounts. Typically, individual identifiers are the usernames of the system accounts assigned to those individuals. In such instances, the account management activities of AC-2 use account names provided by IA-4. Identifier management also addresses individual identifiers not necessarily associated with system accounts. Preventing the reuse of identifiers implies preventing the assignment of previously used individual, group, role, service, or device identifiers to different individuals, groups, roles, services, or devices. Related Controls:  AC-5, IA-2, IA-3, IA-5, IA-8, IA-9, IA-12, MA-4, PE-2, PE-3, PE-4, PL-4, PM-12, PS- 3, PS-4, PS-5, SC-37.', 'vec_doc-14-nist-sp-800-53-p163-612', 0, 243, 'v2.1.0', 'fc4bf088b7795a473f3285d499c3493c7f50567c647f4cdb2b0532779d6a9591', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 136","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":612,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 136"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p163-613', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 136', 163, 'Control Enhancements: (1) IDENTIFIER MANAGEMENT | PROHIBIT ACCOUNT IDENTIFIERS AS PUBLIC IDENTIFIERS Prohibit the use of system account identifiers that are the same as public identifiers for individual accounts. Discussion:  Prohibiting account identifiers as public identifiers applies to any publicly disclosed account identifier used for communication such as, electronic mail and instant', 'vec_doc-14-nist-sp-800-53-p163-613', 0, 98, 'v2.1.0', '0b090d6e2fb4a746e281cf476eaac6508b4385df054d1ec5ec26756d598e13ef', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 136","subsection":"UNKNOWN","table_id":null,"page":163,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":613,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 136"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p164-614', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 137', 164, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 messaging. Prohibiting the use of systems account identifiers that are the same as some public identifier, such as the individual identifier section of an electronic mail address, makes it more difficult for adversaries to guess user identifiers. Prohibiting account identifiers as public identifiers without the implementation of other supporting controls only complicates guessing of identifiers. Additional protections are required for authenticators and credentials to protect the account. Related Controls:  AT-2, PT-7.', 'vec_doc-14-nist-sp-800-53-p164-614', 0, 154, 'v2.1.0', 'f7677695b586b3915b71fea4b15d9e3113d463a58ebab3e82ee532399bd9bb3a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 137","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":614,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 137"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p164-615', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 137', 164, '(2) IDENTIFIER MANAGEMENT | SUPERVISOR AUTHORIZATION [Withdrawn: Incorporated into IA-12(1).] (3) IDENTIFIER MANAGEMENT | MULTIPLE FORMS OF CERTIFICATION [Withdrawn: Incorporated into IA-12(2).] (4) IDENTIFIER MANAGEMENT | IDENTIFY USER STATUS Manage individual identifiers by uniquely identifying each individual as [Assignment: organization-defined characteristic identifying individual status]. Discussion:  Characteristics that identify the status of individuals include contractors, foreign nationals, and non-organizational users. Identifying the status of individuals by these characteristics provides additional information about the people with whom organizational personnel are communicating. For example, it might be useful for a government employee to know that one of the individuals on an email message is a contractor. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p164-615', 0, 215, 'v2.1.0', '78a8071c261d45798c42d4202a96256ca5e375a84e2538a9182a7b6554922324', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 137","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":615,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 137"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p164-616', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 137', 164, '(5) IDENTIFIER MANAGEMENT | DYNAMIC MANAGEMENT Manage individual identifiers dynamically in accordance with [Assignment: organization- defined dynamic identifier policy]. Discussion:  In contrast to conventional approaches to identification that presume static accounts for preregistered users, many distributed systems establish identifiers at runtime for entities that were previously unknown. When identifiers are established at runtime for previously unknown entities, organizations can anticipate and provision for the dynamic establishment of identifiers. Pre-established trust relationships and mechanisms with appropriate authorities to validate credentials and related identifiers are essential. Related Controls:  AC-16. (6) IDENTIFIER MANAGEMENT | CROSS-ORGANIZATION MANAGEMENT Coordinate with the following external organizations for cross-organization management of identifiers: [Assignment: organization-defined external organizations].', 'vec_doc-14-nist-sp-800-53-p164-616', 0, 238, 'v2.1.0', '7207c58e65d296f4ece77c18f0dbd4471492ca2572f71f167da09b34d8981058', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 137","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":616,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 137"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p164-617', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 137', 164, 'Discussion:  Cross-organization identifier management provides the capability to identify individuals, groups, roles, or devices when conducting cross-organization activities involving the processing, storage, or transmission of information. Related Controls:  AU-16, IA-2, IA-5. (7) IDENTIFIER MANAGEMENT | IN-PERSON REGISTRATION [Withdrawn: Incorporated into IA-12(4).] (8) IDENTIFIER MANAGEMENT | PAIRWISE PSEUDONYMOUS IDENTIFIERS Generate pairwise pseudonymous identifiers. Discussion:  A pairwise pseudonymous identifier is an opaque unguessable subscriber identifier generated by an identity provider for use at a specific individual relying party. Generating distinct pairwise pseudonymous identifiers with no identifying information about a subscriber discourages subscriber activity tracking and profiling beyond the operational', 'vec_doc-14-nist-sp-800-53-p164-617', 0, 210, 'v2.1.0', '2793a1e4d2f15e941b34c51135de1ae5c235457c4a31f9213a390962376d46ba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 137","subsection":"UNKNOWN","table_id":null,"page":164,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":617,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 137"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p165-618', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 138', 165, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 requirements established by an organization. The pairwise pseudonymous identifiers are unique to each relying party except in situations where relying parties can show a demonstrable relationship justifying an operational need for correlation, or all parties consent to being correlated in such a manner. Related Controls:  IA-5. (9) IDENTIFIER MANAGEMENT | ATTRIBUTE MAINTENANCE AND PROTECTION Maintain the attributes for each uniquely identified individual, device, or service in [Assignment: organization-defined protected central storage]. Discussion:  For each of the entities covered in IA-2, IA-3, IA-8, and IA-9 , it is important to maintain the attributes for each authenticated entity on an ongoing basis in a central (protected) store. Related Controls:  None. References:  [FIPS 201-2], [SP 800-63-3], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4].', 'vec_doc-14-nist-sp-800-53-p165-618', 0, 238, 'v2.1.0', '5cf393fa79e12e2db74643cda26ff6a027f85e1d6f824e305e26ed59494933b2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 138","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":618,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 138"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p165-619', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 138', 165, 'IA-5 AUTHENTICATOR MANAGEMENT Control:  Manage system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, service, or device receiving the authenticator; b. Establishing initial authenticator content for any authenticators issued by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost or compromised or damaged authenticators, and for revoking authenticators; e. Changing default authenticators prior to first use; f. Changing or refreshing authenticators [Assignment: organization-defined time period by authenticator type] or when [Assignment: organization-defined events] occur; g. Protecting authenticator content from unauthorized disclosure and modification; h.', 'vec_doc-14-nist-sp-800-53-p165-619', 0, 228, 'v2.1.0', '14b56c69daba5892ad388a17b1876b1b8aea553a033970d97e0f3400bfb21650', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 138","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":619,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 138"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p165-620', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 138', 165, 'Requiring individuals to take, and having devices implement, specific controls to protect authenticators; and i. Changing authenticators for group or role accounts when membership to those accounts changes. Discussion:  Authenticators include passwords, cryptographic devices, biometrics, certificates, one-time password devices, and ID badges. Device authenticators include certificates and passwords. Initial authenticator content is the actual content of the authenticator (e.g., the initial password). In contrast, the requirements for authenticator content contain specific criteria or characteristics (e.g., minimum password length). Developers may deliver system components with factory default authentication credentials (i.e., passwords) to allow for initial installation and configuration. Default authentication credentials are often well known, easily discoverable, and present a significant risk.', 'vec_doc-14-nist-sp-800-53-p165-620', 0, 228, 'v2.1.0', '7ba70e9d243eec66daeaa09a0b65b61f3dc56da859a7b58f729d18fac48c3ee3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 138","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":620,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 138"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p165-621', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 138', 165, 'The requirement to protect individual authenticators may be implemented via control PL-4 or PS-6 for authenticators in the possession of individuals and by controls AC-3, AC-6, and SC-28 for authenticators stored in organizational systems, including passwords stored in hashed or encrypted formats or files containing encrypted or hashed passwords accessible with administrator privileges. Systems support authenticator management by organization-defined settings and restrictions for various authenticator characteristics (e.g., minimum password length, validation time window for', 'vec_doc-14-nist-sp-800-53-p165-621', 0, 146, 'v2.1.0', 'a6f52fbb7fc2c9cbeb172ba00ac52940b19e66dcbbd230d39629caef7ce2be85', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 138","subsection":"UNKNOWN","table_id":null,"page":165,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":621,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 138"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p166-622', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 139', 166, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 time synchronous one-time tokens, and number of allowed rejections during the verification stage of biometric authentication). Actions can be taken to safeguard individual authenticators, including maintaining possession of authenticators, not sharing authenticators with others, and immediately reporting lost, stolen, or compromised authenticators. Authenticator management includes issuing and revoking authenticators for temporary access when no longer needed. Related Controls:  AC-3, AC-6, CM-6, IA-2, IA-4, IA-7, IA-8, IA-9, MA-4, PE-2, PL-4, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p166-622', 0, 164, 'v2.1.0', 'ba9f739abd4dc8a18d81c3f40412a9d935e05e5742490be044a72dfc99e8d14c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 139","subsection":"UNKNOWN","table_id":null,"page":166,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":622,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 139"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p166-623', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 139', 166, 'Control Enhancements: (1) AUTHENTICATOR MANAGEMENT | PASSWORD-BASED AUTHENTICATION For password-based authentication: (a) Maintain a list of commonly-used, expected, or compromised passwords and update the list [Assignment: organization-defined frequency] and when organizational passwords are suspected to have been compromised directly or indirectly; (b) Verify, when users create or update passwords, that the passwords are not found on the list of commonly-used, expected, or compromised passwords in IA-5(1)(a); (c) Transmit passwords only over cryptographically-protected channels; (d) Store passwords using an approved salted key derivation function, preferably using a keyed hash; (e) Require immediate selection of a new password upon account recovery; (f) Allow user selection of long passwords and passphrases, including spaces and all printable characters; (g) Employ automated tools to assist the user in selecting strong password authenticators; and (h) Enforce the following composition and complexity rules: [Assignment: organization- defined composition and complexity rules].', 'vec_doc-14-nist-sp-800-53-p166-623', 0, 274, 'v2.1.0', 'ed2e457c91639fd685b02cc524f7739c6b9faaf61f684f9d93046588ffcaab36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 139","subsection":"UNKNOWN","table_id":null,"page":166,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":623,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 139"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p166-624', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 139', 166, 'Discussion:  Password-based authentication applies to passwords regardless of whether they are used in single-factor or multi-factor authentication. Long passwords or passphrases are preferable over shorter passwords. Enforced composition rules provide marginal security benefits while decreasing usability. However, organizations may choose to establish certain rules for password generation (e.g., minimum character length for long passwords) under certain circumstances and can enforce this requirement in IA-5(1)(h). Account recovery can occur, for example, in situations when a password is forgotten. Cryptographically protected passwords include salted one-way cryptographic hashes of passwords. The list of commonly used, compromised, or expected passwords includes passwords obtained from previous breach corpuses, dictionary words, and repetitive or sequential characters. The list includes context-specific words, such as the name of the service, username, and derivatives thereof.', 'vec_doc-14-nist-sp-800-53-p166-624', 0, 248, 'v2.1.0', '09ad3cbb863e6629c8ab206aef9b95e79b6a0c4fc4020f9f8bb3bc2998300a36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 139","subsection":"UNKNOWN","table_id":null,"page":166,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":624,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 139"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p166-625', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 139', 166, 'Related Controls:  IA-6. (2) AUTHENTICATOR MANAGEMENT | PUBLIC KEY-BASED AUTHENTICATION (a) For public key-based authentication: (1) Enforce authorized access to the corresponding private key; and (2) Map the authenticated identity to the account of the individual or group; and (b) When public key infrastructure (PKI) is used: (1) Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information; and (2) Implement a local cache of revocation data to support path discovery and validation.', 'vec_doc-14-nist-sp-800-53-p166-625', 0, 145, 'v2.1.0', 'a45e6c984d2e8ec26ce0338707c5f5e80d585152ee699030aebcc37693cbc97f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 139","subsection":"UNKNOWN","table_id":null,"page":166,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":625,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 139"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p167-626', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 140', 167, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Public key cryptography is a valid authentication mechanism for individuals, machines, and devices. For PKI solutions, status information for certification paths includes certificate revocation lists or certificate status protocol responses. For PIV cards, certificate validation involves the construction and verification of a certification path to the Common Policy Root trust anchor, which includes certificate policy processing. Implementing a local cache of revocation data to support path discovery and validation also supports system availability in situations where organizations are unable to access revocation information via the network. Related Controls:  IA-3, SC-17.', 'vec_doc-14-nist-sp-800-53-p167-626', 0, 197, 'v2.1.0', '946fb4fbe04760cd5693fdb55014e4cee7d53bc29c7e5eab51e0d266d7386c1b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 140","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":626,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 140"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p167-627', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 140', 167, '(3) AUTHENTICATOR MANAGEMENT | IN-PERSON OR TRUSTED EXTERNAL PARTY REGISTRATION [Withdrawn: Incorporated into IA-12(4).] (4) AUTHENTICATOR MANAGEMENT | AUTOMATED SUPPORT FOR PASSWORD STRENGTH DETERMINATION [Withdrawn: Incorporated into IA-5(1).] (5) AUTHENTICATOR MANAGEMENT | CHANGE AUTHENTICATORS PRIOR TO DELIVERY Require developers and installers of system components to provide unique authenticators or change default authenticators prior to delivery and installation. Discussion:  Changing authenticators prior to the delivery and installation of system components extends the requirement for organizations to change default authenticators upon system installation by requiring developers and/or installers to provide unique authenticators or change default authenticators for system components prior to delivery and/or installation. However, it typically does not apply to developers of commercial off-the- shelf information technology products.', 'vec_doc-14-nist-sp-800-53-p167-627', 0, 238, 'v2.1.0', '2597b57a2d1e93ac17ede712ada5898ca86dfaf1847f791783100a39ac8c5b7d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 140","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":627,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 140"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p167-628', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 140', 167, 'Requirements for unique authenticators can be included in acquisition documents prepared by organizations when procuring systems or system components. Related Controls:  None. (6) AUTHENTICATOR MANAGEMENT | PROTECTION OF AUTHENTICATORS Protect authenticators commensurate with the security category of the information to which use of the authenticator permits access. Discussion:  For systems that contain multiple security categories of information without reliable physical or logical separation between categories, authenticators used to grant access to the systems are protected commensurate with the highest security category of information on the systems. Security categories of information are determined as part of the security categorization process. Related Controls:  RA-2. (7) AUTHENTICATOR MANAGEMENT | NO EMBEDDED UNENCRYPTED STATIC AUTHENTICATORS Ensure that unencrypted static authenticators are not embedded in applications or other forms of static storage.', 'vec_doc-14-nist-sp-800-53-p167-628', 0, 244, 'v2.1.0', 'a1c54a017dd41137df00ec39b04feb1f8e07c534a592873487ca0581b2d1f830', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 140","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":628,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 140"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p167-629', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 140', 167, 'Discussion:  In addition to applications, other forms of static storage include access scripts and function keys. Organizations exercise caution when determining whether embedded or stored authenticators are in encrypted or unencrypted form. If authenticators are used in the manner stored, then those representations are considered unencrypted authenticators. Related Controls:  None. (8) AUTHENTICATOR MANAGEMENT | MULTIPLE SYSTEM ACCOUNTS Implement [Assignment: organization-defined security controls] to manage the risk of compromise due to individuals having accounts on multiple systems.', 'vec_doc-14-nist-sp-800-53-p167-629', 0, 149, 'v2.1.0', 'c1fb48dd92ce5c6b35256df99fffce0802af0d04f7eb0dfec27a3415e5c6e985', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 140","subsection":"UNKNOWN","table_id":null,"page":167,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":629,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 140"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p168-630', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 141', 168, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  When individuals have accounts on multiple systems and use the same authenticators such as passwords, there is the risk that a compromise of one account may lead to the compromise of other accounts. Alternative approaches include having different authenticators (passwords) on all systems, employing a single sign-on or federation mechanism, or using some form of one-time passwords on all systems. Organizations can also use rules of behavior (see PL-4) and access agreements (see PS-6) to mitigate the risk of multiple system accounts. Related Controls:  PS-6. (9) AUTHENTICATOR MANAGEMENT | FEDERATED CREDENTIAL MANAGEMENT Use the following external organizations to federate credentials: [Assignment: organization-defined external organizations].', 'vec_doc-14-nist-sp-800-53-p168-630', 0, 214, 'v2.1.0', '0649f6325c9ad37d10afd2f79c2ef6c3a9a361b0381a0e4f74e48ea2e84c55ae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 141","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":630,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 141"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p168-631', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 141', 168, 'Discussion:  Federation provides organizations with the capability to authenticate individuals and devices when conducting cross-organization activities involving the processing, storage, or transmission of information. Using a specific list of approved external organizations for authentication helps to ensure that those organizations are vetted and trusted. Related Controls:  AU-7, AU-16. (10) AUTHENTICATOR MANAGEMENT | DYNAMIC CREDENTIAL BINDING Bind identities and authenticators dynamically using the following rules: [Assignment: organization-defined binding rules]. Discussion:  Authentication requires some form of binding between an identity and the authenticator that is used to confirm the identity. In conventional approaches, binding is established by pre-provisioning both the identity and the authenticator to the system.', 'vec_doc-14-nist-sp-800-53-p168-631', 0, 210, 'v2.1.0', '6e60e48f8b8b9f659a4d7a6554997c57e9b71e33f979cb1d7d170ad6f5ea187d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 141","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":631,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 141"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p168-632', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 141', 168, 'For example, the binding between a username (i.e., identity) and a password (i.e., authenticator) is accomplished by provisioning the identity and authenticator as a pair in the system. New authentication techniques allow the binding between the identity and the authenticator to be implemented external to a system. For example, with smartcard credentials, the identity and authenticator are bound together on the smartcard. Using these credentials, systems can authenticate identities that have not been pre-provisioned, dynamically provisioning the identity after authentication. In these situations, organizations can anticipate the dynamic provisioning of identities. Pre-established trust relationships and mechanisms with appropriate authorities to validate identities and related credentials are essential. Related Controls:  AU-16, IA-5.', 'vec_doc-14-nist-sp-800-53-p168-632', 0, 212, 'v2.1.0', '5a89a01dda68a52c8282c30b7bc046e23a68d16393e1255a56a02baeaacd7d19', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 141","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":632,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 141"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p168-633', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 141', 168, '(11) AUTHENTICATOR MANAGEMENT | HARDWARE TOKEN-BASED AUTHENTICATION [Withdrawn: Incorporated into IA-2(1) and IA-2(2).] (12) AUTHENTICATOR MANAGEMENT | BIOMETRIC AUTHENTICATION PERFORMANCE For biometric-based authentication, employ mechanisms that satisfy the following biometric quality requirements [Assignment: organization-defined biometric quality requirements]. Discussion:  Unlike password-based authentication, which provides exact matches of user- input passwords to stored passwords, biometric authentication does not provide exact matches. Depending on the type of biometric and the type of collection mechanism, there is likely to be some divergence from the presented biometric and the stored biometric that serves as the basis for comparison. Matching performance is the rate at which a biometric algorithm correctly results in a match for a genuine user and rejects other users.', 'vec_doc-14-nist-sp-800-53-p168-633', 0, 224, 'v2.1.0', '1919c7872616608f597f7cff2da684e64d4f1c11e3c1eaa16dc1921588dd05e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 141","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":633,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 141"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p168-634', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 141', 168, 'Biometric performance requirements include the match rate, which reflects the accuracy of the biometric matching algorithm used by a system. Related Controls:  AC-7.', 'vec_doc-14-nist-sp-800-53-p168-634', 0, 42, 'v2.1.0', '1dddcf7815cee34ed443afe5d24e697eef4a36e7f145359311b129b6d2cf0d89', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 141","subsection":"UNKNOWN","table_id":null,"page":168,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":634,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 141"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p169-635', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 142', 169, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (13) AUTHENTICATOR MANAGEMENT | EXPIRATION OF CACHED AUTHENTICATORS Prohibit the use of cached authenticators after [Assignment: organization-defined time period]. Discussion:  Cached authenticators are used to authenticate to the local machine when the network is not available. If cached authentication information is out of date, the validity of the authentication information may be questionable. Related Controls:  None. (14) AUTHENTICATOR MANAGEMENT | MANAGING CONTENT OF PKI TRUST STORES For PKI-based authentication, employ an organization-wide methodology for managing the content of PKI trust stores installed across all platforms, including networks, operating systems, browsers, and applications. Discussion:  An organization-wide methodology for managing the content of PKI trust stores helps improve the accuracy and currency of PKI-based authentication credentials across the organization.', 'vec_doc-14-nist-sp-800-53-p169-635', 0, 249, 'v2.1.0', 'f1b56fa0820a1533d7201bba2691e3271c4558f6b414c5fac9468356b0eaddb5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 142","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":635,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 142"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p169-636', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 142', 169, 'Related Controls:  None. (15) AUTHENTICATOR MANAGEMENT | GSA-APPROVED PRODUCTS AND SERVICES Use only General Services Administration-approved products and services for identity, credential, and access management. Discussion:  General Services Administration (GSA)-approved products and services are products and services that have been approved through the GSA conformance program, where applicable, and posted to the GSA Approved Products List. GSA provides guidance for teams to design and build functional and secure systems that comply with Federal Identity, Credential, and Access Management (FICAM) policies, technologies, and implementation patterns. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p169-636', 0, 171, 'v2.1.0', '3a9b7ef382c1cc2cda07effdfcb43231f3b1c1786fd0c38e71fc4eb677fc1355', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 142","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":636,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 142"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p169-637', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 142', 169, '(16) AUTHENTICATOR MANAGEMENT | IN-PERSON OR TRUSTED EXTERNAL PARTY AUTHENTICATOR ISSUANCE Require that the issuance of [Assignment: organization-defined types of and/or specific authenticators] be conducted [Selection: in person; by a trusted external party] before [Assignment: organization-defined registration authority] with authorization by [Assignment: organization-defined personnel or roles]. Discussion:  Issuing authenticators in person or by a trusted external party enhances and reinforces the trustworthiness of the identity proofing process. Related Controls:  IA-12. (17) AUTHENTICATOR MANAGEMENT | PRESENTATION ATTACK DETECTION FOR BIOMETRIC AUTHENTICATORS Employ presentation attack detection mechanisms for biometric-based authentication. Discussion:  Biometric characteristics do not constitute secrets.', 'vec_doc-14-nist-sp-800-53-p169-637', 0, 206, 'v2.1.0', '8e1ace8647e77b82ca82dafd1ab70d0e3bea41168cb3130de8e9ceea8c440de6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 142","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":637,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 142"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p169-638', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 142', 169, 'Such characteristics can be obtained by online web accesses, taking a picture of someone with a camera phone to obtain facial images with or without their knowledge, lifting from objects that someone has touched (e.g., a latent fingerprint), or capturing a high-resolution image (e.g., an iris pattern). Presentation attack detection technologies including liveness detection, can mitigate the risk of these types of attacks by making it difficult to produce artifacts intended to defeat the biometric sensor. Related Controls:  AC-7. (18) AUTHENTICATOR MANAGEMENT | PASSWORD MANAGERS', 'vec_doc-14-nist-sp-800-53-p169-638', 0, 146, 'v2.1.0', 'bb791e638a245500b79f8d64af4849224a34679c30fc9298d153106ae77c4cc7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 142","subsection":"UNKNOWN","table_id":null,"page":169,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":638,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 142"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p170-639', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 143', 170, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (a) Employ [Assignment: organization-defined password managers] to generate and manage passwords; and (b) Protect the passwords using [Assignment: organization-defined controls]. Discussion:  For systems where static passwords are employed, it is often a challenge to ensure that the passwords are suitably complex and that the same passwords are not employed on multiple systems. A password manager is a solution to this problem as it automatically generates and stores strong and different passwords for various accounts. A potential risk of using password managers is that adversaries can target the collection of passwords generated by the password manager. Therefore, the collection of passwords requires protection including encrypting the passwords (see IA-5(1)(d)) and storing the collection offline in a token. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p170-639', 0, 234, 'v2.1.0', '9012be5bdc0fe889eea40b8cf5de5b174fbfd66a233bb4fd753acf7afb29bd0c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 143","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":639,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 143"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p170-640', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 143', 170, 'References:  [FIPS 140-3], [FIPS 180-4], [FIPS 201-2], [FIPS 202], [SP 800-63-3], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4], [IR 7539], [IR 7817], [IR 7849], [IR 7870], [IR 8040]. IA-6 AUTHENTICATION FEEDBACK Control:  Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals. Discussion:  Authentication feedback from systems does not provide information that would allow unauthorized individuals to compromise authentication mechanisms. For some types of systems, such as desktops or notebooks with relatively large monitors, the threat (referred to as shoulder surfing) may be significant. For other types of systems, such as mobile devices with small displays, the threat may be less significant and is balanced against the increased likelihood of typographic input errors due to small keyboards. Thus, the means for obscuring authentication feedback is selected accordingly.', 'vec_doc-14-nist-sp-800-53-p170-640', 0, 249, 'v2.1.0', 'c42c27b6cd4219169581fef83886edcd1cc45cfd3a0d56116243c8fece03f348', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 143","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":640,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 143"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p170-641', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 143', 170, 'Obscuring authentication feedback includes displaying asterisks when users type passwords into input devices or displaying feedback for a very limited time before obscuring it. Related Controls:  AC-3. Control Enhancements:  None. References:  None. IA-7 CRYPTOGRAPHIC MODULE AUTHENTICATION Control:  Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, executive orders, directives, policies, regulations, standards, and guidelines for such authentication. Discussion:  Authentication mechanisms may be required within a cryptographic module to authenticate an operator accessing the module and to verify that the operator is authorized to assume the requested role and perform services within that role. Related Controls:  AC-3, IA-5, SA-4, SC-12, SC-13. Control Enhancements:  None. References:  [FIPS 140-3].', 'vec_doc-14-nist-sp-800-53-p170-641', 0, 218, 'v2.1.0', 'f0c78df45ed06c41326fba968f758e5bdc59b533baccee96eea7f4b6b5c9ec8d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 143","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":641,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 143"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p170-642', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 143', 170, 'IA-8 IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) Control:  Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users.', 'vec_doc-14-nist-sp-800-53-p170-642', 0, 49, 'v2.1.0', '99b643dc2e7b7a7cb514fb4b14dea588b7e93bb2e0083cb42d8ea02baaaa1be0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 143","subsection":"UNKNOWN","table_id":null,"page":170,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":642,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 143"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p171-643', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 144', 171, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Non-organizational users include system users other than organizational users explicitly covered by IA-2. Non-organizational users are uniquely identified and authenticated for accesses other than those explicitly identified and documented in AC-14. Identification and authentication of non-organizational users accessing federal systems may be required to protect federal, proprietary, or privacy-related information (with exceptions noted for national security systems). Organizations consider many factors— including security, privacy, scalability, and practicality— when balancing the need to ensure ease of use for access to federal information and systems with the need to protect and adequately mitigate risk. Related Controls:  AC-2, AC-6, AC-14, AC-17, AC-18, AU-6, IA-2, IA-4, IA-5, IA-10, IA-11, MA-4, RA- 3, SA-4, SC-8.', 'vec_doc-14-nist-sp-800-53-p171-643', 0, 234, 'v2.1.0', 'a955245e0a5bcd8e0c11eb77139c1510f07ba20311fdc87cb2480872c0b9c475', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 144","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":643,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 144"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p171-644', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 144', 171, 'Control Enhancements: (1) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | ACCEPTANCE OF PIV CREDENTIALS FROM OTHER AGENCIES Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies. Discussion:  Acceptance of Personal Identity Verification (PIV) credentials from other federal agencies applies to both logical and physical access control systems. PIV credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidelines. The adequacy and reliability of PIV card issuers are addressed and authorized using [SP 800-79-2]. Related Controls:  PE-3. (2) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | ACCEPTANCE OF EXTERNAL AUTHENTICATORS (a) Accept only external authenticators that are NIST-compliant; and (b) Document and maintain a list of accepted external authenticators.', 'vec_doc-14-nist-sp-800-53-p171-644', 0, 229, 'v2.1.0', 'b12df3efd15e201636150218dab8c9e99b7dc06d6a1543edac9a741895cf4795', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 144","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":644,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 144"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p171-645', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 144', 171, 'Discussion:  Acceptance of only NIST-compliant external authenticators applies to organizational systems that are accessible to the public (e.g., public-facing websites). External authenticators are issued by nonfederal government entities and are compliant with [SP 800-63B]. Approved external authenticators meet or exceed the minimum Federal Government-wide technical, security, privacy, and organizational maturity requirements. Meeting or exceeding Federal requirements allows Federal Government relying parties to trust external authenticators in connection with an authentication transaction at a specified authenticator assurance level. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p171-645', 0, 168, 'v2.1.0', '333500cca1e1e9c7da0bc1f5bf56c3b2739efa6f48013432b3e762c1632dbb36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 144","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":645,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 144"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p171-646', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 144', 171, '(3) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | USE OF FICAM-APPROVED PRODUCTS [Withdrawn: Incorporated into IA-8(2).] (4) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | USE OF DEFINED PROFILES Conform to the following profiles for identity management [Assignment: organization- defined identity management profiles]. Discussion:  Organizations define profiles for identity management based on open identity management standards. To ensure that open identity management standards are viable, robust, reliable, sustainable, and interoperable as documented, the Federal Government assesses and scopes the standards and technology implementations against applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p171-646', 0, 202, 'v2.1.0', 'd61e0e60ff187de7389b1acb8a678fe4e0311a4ba461352d9e499bd8b4b74ccf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 144","subsection":"UNKNOWN","table_id":null,"page":171,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":646,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 144"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p172-647', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 145', 172, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (5) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | ACCEPTANCE OF PIV-I CREDENTIALS Accept and verify federated or PKI credentials that meet [Assignment: organization- defined policy]. Discussion:  Acceptance of PIV-I credentials can be implemented by PIV, PIV-I, and other commercial or external identity providers. The acceptance and verification of PIV-I-compliant credentials apply to both logical and physical access control systems. The acceptance and verification of PIV-I credentials address nonfederal issuers of identity cards that desire to interoperate with United States Government PIV systems and that can be trusted by Federal Government-relying parties. The X.509 certificate policy for the Federal Bridge Certification Authority (FBCA) addresses PIV-I requirements. The PIV-I card is commensurate with the PIV credentials as defined in cited references.', 'vec_doc-14-nist-sp-800-53-p172-647', 0, 245, 'v2.1.0', 'dc9a8db594d05b4afb185b408b34aef34f2939d1eb9a75e24c3f959aa437f1ac', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 145","subsection":"UNKNOWN","table_id":null,"page":172,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":647,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 145"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p172-648', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 145', 172, 'PIV-I credentials are the credentials issued by a PIV-I provider whose PIV-I certificate policy maps to the Federal Bridge PIV-I Certificate Policy. A PIV-I provider is cross-certified with the FBCA (directly or through another PKI bridge) with policies that have been mapped and approved as meeting the requirements of the PIV-I policies defined in the FBCA certificate policy. Related Controls:  None. (6) IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) | DISASSOCIABILITY Implement the following measures to disassociate user attributes or identifier assertion relationships among individuals, credential service providers, and relying parties: [Assignment: organization-defined measures]. Discussion:  Federated identity solutions can create increased privacy risks due to the tracking and profiling of individuals.', 'vec_doc-14-nist-sp-800-53-p172-648', 0, 208, 'v2.1.0', '2ff1fbeeb2a8ea064dac293df24de77219b6063b4bcfa2cb502e9423ca1a25db', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 145","subsection":"UNKNOWN","table_id":null,"page":172,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":648,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 145"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p172-649', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 145', 172, 'Using identifier mapping tables or cryptographic techniques to blind credential service providers and relying parties from each other or to make identity attributes less visible to transmitting parties can reduce these privacy risks. Related Controls:  None. References:  [OMB A-130], [FED PKI], [FIPS 201-2], [SP 800-63-3], [SP 800-79-2], [SP 800-116], [IR 8062]. IA-9 SERVICE IDENTIFICATION AND AUTHENTICATION Control:  Uniquely identify and authenticate [Assignment: organization-defined system services and applications] before establishing communications with devices, users, or other services or applications. Discussion:  Services that may require identification and authentication include web applications using digital certificates or services or applications that query a database. Identification and authentication methods for system services and applications include information or code signing, provenance graphs, and electronic signatures that indicate the sources of services.', 'vec_doc-14-nist-sp-800-53-p172-649', 0, 248, 'v2.1.0', '410ecd573c6486f19d00b24a12bd9a44afc57b92897d0b939fc84fc5c82af421', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 145","subsection":"UNKNOWN","table_id":null,"page":172,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":649,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 145"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p172-650', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 145', 172, 'Decisions regarding the validity of identification and authentication claims can be made by services separate from the services acting on those decisions. This can occur in distributed system architectures. In such situations, the identification and authentication decisions (instead of actual identifiers and authentication data) are provided to the services that need to act on those decisions. Related Controls:  IA-3, IA-4, IA-5, SC-8. Control Enhancements: (1) SERVICE IDENTIFICATION AND AUTHENTICATION | INFORMATION EXCHANGE [Withdrawn: Incorporated into IA-9.]', 'vec_doc-14-nist-sp-800-53-p172-650', 0, 142, 'v2.1.0', 'c8529e896c1a63c55fff45e83d5817144242c93bafe3f02526ed9eea1e71a68e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 145","subsection":"UNKNOWN","table_id":null,"page":172,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":650,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 145"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p173-651', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 146', 173, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (2) SERVICE IDENTIFICATION AND AUTHENTICATION | TRANSMISSION OF DECISIONS [Withdrawn: Incorporated into IA-9.] References:  None. IA-10 ADAPTIVE AUTHENTICATION Control:  Require individuals accessing the system to employ [Assignment: organization-defined supplemental authentication techniques or mechanisms] under specific [Assignment: organization-defined circumstances or situations]. Discussion:  Adversaries may compromise individual authentication mechanisms employed by organizations and subsequently attempt to impersonate legitimate users. To address this threat, organizations may employ specific techniques or mechanisms and establish protocols to assess suspicious behavior.', 'vec_doc-14-nist-sp-800-53-p173-651', 0, 195, 'v2.1.0', '32e7e01c70f509dc45125b42f0af19720eeeb18f24555b0fd12fb9abec145df5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 146","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":651,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 146"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p173-652', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 146', 173, 'Suspicious behavior may include accessing information that individuals do not typically access as part of their duties, roles, or responsibilities; accessing greater quantities of information than individuals would routinely access; or attempting to access information from suspicious network addresses. When pre-established conditions or triggers occur, organizations can require individuals to provide additional authentication information. Another potential use for adaptive authentication is to increase the strength of mechanism based on the number or types of records being accessed. Adaptive authentication does not replace and is not used to avoid the use of multi-factor authentication mechanisms but can augment implementations of multi-factor authentication. Related Controls:  IA-2, IA-8. Control Enhancements:  None. References:  [SP 800-63-3].', 'vec_doc-14-nist-sp-800-53-p173-652', 0, 215, 'v2.1.0', '0f0c45319c5ebe1900a6a597b2bfd69cf63a4fdc92efed75d9a55cc9b3d9c305', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 146","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":652,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 146"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p173-653', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 146', 173, 'IA-11 RE-AUTHENTICATION Control:  Require users to re-authenticate when [Assignment: organization-defined circumstances or situations requiring re-authentication]. Discussion:  In addition to the re-authentication requirements associated with device locks, organizations may require re-authentication of individuals in certain situations, including when roles, authenticators or credentials change, when security categories of systems change, when the execution of privileged functions occurs, after a fixed time period, or periodically. Related Controls:  AC-3, AC-11, IA-2, IA-3, IA-4, IA-8. Control Enhancements:  None. References:  None. IA-12 IDENTITY PROOFING Control: a. Identity proof users that require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines; b. Resolve user identities to a unique individual; and c. Collect, validate, and verify identity evidence.', 'vec_doc-14-nist-sp-800-53-p173-653', 0, 243, 'v2.1.0', 'fc586783ae5cea823b34de899eaf9fed60713a32fbec34938e15d564d0a45bd6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 146","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":653,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 146"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p173-654', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 146', 173, 'Discussion:  Identity proofing is the process of collecting, validating, and verifying a user’s identity information for the purposes of establishing credentials for accessing a system. Identity proofing is intended to mitigate threats to the registration of users and the establishment of', 'vec_doc-14-nist-sp-800-53-p173-654', 0, 73, 'v2.1.0', '43d8e287e8db16c91923013b7cf9014cb37ef1b2e8a1fdc26115f4fabc32fe9d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 146","subsection":"UNKNOWN","table_id":null,"page":173,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":654,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 146"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p174-655', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 147', 174, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 their accounts. Standards and guidelines specifying identity assurance levels for identity proofing include [SP 800-63-3] and [SP 800-63A]. Organizations may be subject to laws, executive orders, directives, regulations, or policies that address the collection of identity evidence. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements. Related Controls:  AC-5, IA-1, IA-2, IA-3, IA-4, IA-5,  IA-6, IA-8. Control Enhancements: (1) IDENTITY PROOFING | SUPERVISOR AUTHORIZATION Require that the registration process to receive an account for logical access includes supervisor or sponsor authorization.', 'vec_doc-14-nist-sp-800-53-p174-655', 0, 191, 'v2.1.0', '3988189be1b5415ac9609dd5b664bbd126db2b67cd2ecb8b38aa1b388431d2f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 147","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":655,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 147"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p174-656', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 147', 174, 'Discussion:  Including supervisor or sponsor authorization as part of the registration process provides an additional level of scrutiny to ensure that the user’s management chain is aware of the account, the account is essential to carry out organizational missions and functions, and the user’s privileges are appropriate for the anticipated responsibilities and authorities within the organization. Related Controls:  None. (2) IDENTITY PROOFING | IDENTITY EVIDENCE Require evidence of individual identification be presented to the registration authority. Discussion:  Identity evidence, such as documentary evidence or a combination of documents and biometrics, reduces the likelihood of individuals using fraudulent identification to establish an identity or at least increases the work factor of potential adversaries. The forms of acceptable evidence are consistent with the risks to the systems, roles, and privileges associated with the user’s account. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p174-656', 0, 247, 'v2.1.0', '0f0526c1617dd871a6a832171d20152fea69764b155bdee75b2725a67fbf65f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 147","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":656,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 147"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p174-657', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 147', 174, '(3) IDENTITY PROOFING | IDENTITY EVIDENCE VALIDATION AND VERIFICATION Require that the presented identity evidence be validated and verified through [Assignment: organizational defined methods of validation and verification]. Discussion:  Validation and verification of identity evidence increases the assurance that accounts and identifiers are being established for the correct user and authenticators are being bound to that user. Validation refers to the process of confirming that the evidence is genuine and authentic, and the data contained in the evidence is correct, current, and related to an individual. Verification confirms and establishes a linkage between the claimed identity and the actual existence of the user presenting the evidence. Acceptable methods for validating and verifying identity evidence are consistent with the risks to the systems, roles, and privileges associated with the users account. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p174-657', 0, 237, 'v2.1.0', '32727b8c08bbe7b169287ff0a15239795a9484dcec670cde836d5f96fa82e1b0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 147","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":657,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 147"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p174-658', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 147', 174, '(4) IDENTITY PROOFING | IN-PERSON VALIDATION AND VERIFICATION Require that the validation and verification of identity evidence be conducted in person before a designated registration authority. Discussion:  In-person proofing reduces the likelihood of fraudulent credentials being issued because it requires the physical presence of individuals, the presentation of physical identity documents, and actual face-to-face interactions with designated registration authorities. Related Controls:  None. (5) IDENTITY PROOFING | ADDRESS CONFIRMATION', 'vec_doc-14-nist-sp-800-53-p174-658', 0, 136, 'v2.1.0', '41de24812012fdc941f7078f357b99776e0408675bbcdc57d29f1df4d1a87b60', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 147","subsection":"UNKNOWN","table_id":null,"page":174,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":658,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 147"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p175-659', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 148', 175, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Require that a [Selection: registration code; notice of proofing] be delivered through an out-of-band channel to verify the users address (physical or digital) of record. Discussion:  To make it more difficult for adversaries to pose as legitimate users during the identity proofing process, organizations can use out-of-band methods to ensure that the individual associated with an address of record is the same individual that participated in the registration. Confirmation can take the form of a temporary enrollment code or a notice of proofing. The delivery address for these artifacts is obtained from records and not self- asserted by the user. The address can include a physical or digital address. A home address is an example of a physical address. Email addresses and telephone numbers are examples of digital addresses. Related Controls:  IA-12. (6) IDENTITY PROOFING | ACCEPT EXTERNALLY-PROOFED IDENTITIES Accept externally-proofed identities at [Assignment: organization-defined identity assurance level]. Discussion:  To limit unnecessary re-proofing of identities, particularly of non-PIV users, organizations accept proofing conducted at a commensurate level of assurance by other agencies or organizations. Proofing is consistent with organizational security policy and the identity assurance level appropriate for the system, application, or information accessed. Accepting externally-proofed identities is a fundamental component of managing federated identities across agencies and organizations. Related Controls:  IA-3, IA-4, IA-5, IA-8. References:  [FIPS 201-2], [SP 800-63-3], [SP 800-63A], [SP 800-79-2].', 'vec_doc-14-nist-sp-800-53-p175-659', 0, 431, 'v2.1.0', '86411123262fe8e6597a126202d819fbe3beb90d1cabc9c502076568a5d6c5be', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 148","subsection":"UNKNOWN","table_id":null,"page":175,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":659,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 148"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p176-660', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.8   INCIDENT RESPONSE', 176, 'Quick link to Incident Response Summary Table IR-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p176-660', 0, 45, 'v2.1.0', '5df7fe94628513c62c7159c53c85d0cd9bfec4ab5c86c8efec37cfed835b033f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.8   INCIDENT RESPONSE","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":660,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.8   INCIDENT RESPONSE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p176-661', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 176, 'level] incident response policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p176-661', 0, 76, 'v2.1.0', 'b55191d2a7d81419578bf1a30b169d1b2a5337aa798a5b1297e164da405e5169', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":661,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p176-662', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the incident response policy and the', 176, 'associated incident response controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the incident response policy and procedures; and c. Review and update the current incident response:', 'vec_doc-14-nist-sp-800-53-p176-662', 0, 66, 'v2.1.0', '028e64b2a0d07fa55361d22ce2ce89b161e78540c823ceb5eb2fa2d752a06ba9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the incident response policy and the","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":662,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the incident response policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p176-663', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 176, 'organization-defined events]. Discussion:  Incident response policy and procedures address the controls in the IR family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of incident response policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to incident response policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-50], [SP 800-61], [SP 800-83], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p176-663', 0, 435, 'v2.1.0', '9ec16440acb41f34b0f9dd230d1f5ff086573ec740cdd213cb2d9e0765a8b4a5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":176,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":663,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p177-664', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 150', 177, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 IR-2 INCIDENT RESPONSE TRAINING Control: a. Provide incident response training to system users consistent with assigned roles and responsibilities:', 'vec_doc-14-nist-sp-800-53-p177-664', 0, 60, 'v2.1.0', '2164c7051d2c00dda294ce11fbef4fd8182976c21e0eb042afd17874a3deecf3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 150","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":664,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 150"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p177-665', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Within [Assignment: organization-defined time period] of assuming an incident response', 177, 'role or responsibility or acquiring system access;', 'vec_doc-14-nist-sp-800-53-p177-665', 0, 13, 'v2.1.0', '1c6c22f9148a7ca7390b1b81c27ddb4e19158ed7e008c4850de8af866a06533d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Within [Assignment: organization-defined time period] of assuming an incident response","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":665,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Within [Assignment: organization-defined time period] of assuming an incident response"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p177-666', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 177, 'b. Review and update incident response training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]. Discussion:  Incident response training is associated with the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail are included in such training. For example, users may only need to know who to call or how to recognize an incident; system administrators may require additional training on how to handle incidents; and incident responders may receive more specific training on forensics, data collection techniques, reporting, system recovery, and system restoration. Incident response training includes user training in identifying and reporting suspicious activities from external and internal sources. Incident response training for users may be provided as part of AT-2 or AT-3.', 'vec_doc-14-nist-sp-800-53-p177-666', 0, 228, 'v2.1.0', '16b1ffd0c5ac867772b55733b4a4125511cf07f3ee098ef2162c322b1c922272', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":666,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p177-667', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 177, 'Events that may precipitate an update to incident response training content include, but are not limited to, incident response plan testing or response to an actual incident (lessons learned), assessment or audit findings, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  AT-2, AT-3, AT-4, CP-3, IR-3, IR-4, IR-8, IR-9. Control Enhancements: (1) INCIDENT RESPONSE TRAINING | SIMULATED EVENTS Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations. Discussion:  Organizations establish requirements for responding to incidents in incident response plans. Incorporating simulated events into incident response training helps to ensure that personnel understand their individual responsibilities and what specific actions to take in crisis situations. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p177-667', 0, 233, 'v2.1.0', 'e78e726029a2f6ce8a1d1355e27bc6b2be80ecdd402eee39f6bf99384500038a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":667,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p177-668', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. [Assignment: organization-defined frequency] thereafter; and', 177, '(2) INCIDENT RESPONSE TRAINING | AUTOMATED TRAINING ENVIRONMENTS Provide an incident response training environment using [Assignment: organization- defined automated mechanisms]. Discussion:  Automated mechanisms can provide a more thorough and realistic incident response training environment. This can be accomplished, for example, by providing more complete coverage of incident response issues, selecting more realistic training scenarios and environments, and stressing the response capability. Related Controls:  None. (3) INCIDENT RESPONSE TRAINING | BREACH Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.', 'vec_doc-14-nist-sp-800-53-p177-668', 0, 176, 'v2.1.0', '3fd872dd1ef452d84931823d32a6a83d35320a3b375a0abe98a08f83e330f229', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. [Assignment: organization-defined frequency] thereafter; and","subsection":"UNKNOWN","table_id":null,"page":177,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":668,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. [Assignment: organization-defined frequency] thereafter; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p178-669', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 151', 178, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  For federal agencies, an incident that involves personally identifiable information is considered a breach. A breach results in the loss of control, compromise, unauthorized disclosure, unauthorized acquisition, or a similar occurrence where a person other than an authorized user accesses or potentially accesses personally identifiable information or an authorized user accesses or potentially accesses such information for other than authorized purposes. The incident response training emphasizes the obligation of individuals to report both confirmed and suspected breaches involving information in any medium or form, including paper, oral, and electronic. Incident response training includes tabletop exercises that simulate a breach. See IR-2(1). Related Controls:  None. References:  [OMB M-17-12], [SP 800-50].', 'vec_doc-14-nist-sp-800-53-p178-669', 0, 231, 'v2.1.0', '664039f51c19e90ec0f834dd3c40f6938a94c85e6a11e38d929733242fbdff65', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 151","subsection":"UNKNOWN","table_id":null,"page":178,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":669,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 151"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p178-670', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 151', 178, 'IR-3 INCIDENT RESPONSE TESTING Control:  Test the effectiveness of the incident response capability for the system [Assignment: organization-defined frequency] using the following tests: [Assignment: organization-defined tests]. Discussion:  Organizations test incident response capabilities to determine their effectiveness and identify potential weaknesses or deficiencies. Incident response testing includes the use of checklists, walk-through or tabletop exercises, and simulations (parallel or full interrupt). Incident response testing can include a determination of the effects on organizational operations and assets and individuals due to incident response. The use of qualitative and quantitative data aids in determining the effectiveness of incident response processes. Related Controls:  CP-3, CP-4, IR-2, IR-4, IR-8, PM-14.', 'vec_doc-14-nist-sp-800-53-p178-670', 0, 210, 'v2.1.0', 'f34e6268f1acff6a594e72613f2f97a19385947c2f001c5d2c81b85068ef4463', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 151","subsection":"UNKNOWN","table_id":null,"page":178,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":670,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 151"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p178-671', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 151', 178, 'Control Enhancements: (1) INCIDENT RESPONSE TESTING | AUTOMATED TESTING Test the incident response capability using [Assignment: organization-defined automated mechanisms]. Discussion:  Organizations use automated mechanisms to more thoroughly and effectively test incident response capabilities. This can be accomplished by providing more complete coverage of incident response issues, selecting realistic test scenarios and environments, and stressing the response capability. Related Controls:  None. (2) INCIDENT RESPONSE TESTING | COORDINATION WITH RELATED PLANS Coordinate incident response testing with organizational elements responsible for related plans. Discussion:  Organizational plans related to incident response testing include business continuity plans, disaster recovery plans, continuity of operations plans, contingency plans, crisis communications plans, critical infrastructure plans, and occupant emergency plans. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p178-671', 0, 241, 'v2.1.0', '0265302680afdf36248d24d111b6af04663eb674ead5a0b4d654bbf247569d75', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 151","subsection":"UNKNOWN","table_id":null,"page":178,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":671,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 151"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p178-672', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 151', 178, '(3) INCIDENT RESPONSE TESTING | CONTINUOUS IMPROVEMENT Use qualitative and quantitative data from testing to: (a) Determine the effectiveness of incident response processes; (b) Continuously improve incident response processes; and (c) Provide incident response measures and metrics that are accurate, consistent, and in a reproducible format.', 'vec_doc-14-nist-sp-800-53-p178-672', 0, 86, 'v2.1.0', '89d5d87d5f9709f46b9dd45f492c671e3fd540eb9ed9768752e671ed49d535ec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 151","subsection":"UNKNOWN","table_id":null,"page":178,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":672,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 151"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p179-673', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 152', 179, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  To help incident response activities function as intended, organizations may use metrics and evaluation criteria to assess incident response programs as part of an effort to continually improve response performance. These efforts facilitate improvement in incident response efficacy and lessen the impact of incidents. Related Controls:  None. References:  [OMB A-130], [SP 800-84], [SP 800-115]. IR-4 INCIDENT HANDLING Control: a. Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery; b. Coordinate incident handling activities with contingency planning activities; c. Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; and d.', 'vec_doc-14-nist-sp-800-53-p179-673', 0, 251, 'v2.1.0', '5dca23c7156d56c58c1a7749a270ff10d527a35774f61881be016dd07b2622b3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 152","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":673,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 152"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p179-674', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 152', 179, 'Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization. Discussion:  Organizations recognize that incident response capabilities are dependent on the capabilities of organizational systems and the mission and business processes being supported by those systems. Organizations consider incident response as part of the definition, design, and development of mission and business processes and systems. Incident-related information can be obtained from a variety of sources, including audit monitoring, physical access monitoring, and network monitoring; user or administrator reports; and reported supply chain events.', 'vec_doc-14-nist-sp-800-53-p179-674', 0, 175, 'v2.1.0', '9b8b5b721c4716c9a6c0a87b8d21efeb8d051f5c8896cc6e34f31aa31746d978', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 152","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":674,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 152"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p179-675', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 152', 179, 'An effective incident handling capability includes coordination among many organizational entities (e.g., mission or business owners, system owners, authorizing officials, human resources offices, physical security offices, personnel security offices, legal departments, risk executive [function], operations personnel, procurement offices). Suspected security incidents include the receipt of suspicious email communications that can contain malicious code. Suspected supply chain incidents include the insertion of counterfeit hardware or malicious code into organizational systems or system components. For federal agencies, an incident that involves personally identifiable information is considered a breach.', 'vec_doc-14-nist-sp-800-53-p179-675', 0, 179, 'v2.1.0', '64eef0907d9af84f953ff7e6ec348560211ce6e95a45ef367ffb7e63189509c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 152","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":675,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 152"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p179-676', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 152', 179, 'A breach results in unauthorized disclosure, the loss of control, unauthorized acquisition, compromise, or a similar occurrence where a person other than an authorized user accesses or potentially accesses personally identifiable information or an authorized user accesses or potentially accesses such information for other than authorized purposes. Related Controls:  AC-19, AU-6, AU-7, CM-6, CP-2, CP-3, CP-4, IR-2, IR-3, IR-5, IR-6, IR-8, PE-6, PL- 2, PM-12, SA-8, SC-5, SC-7, SI-3, SI-4, SI-7. Control Enhancements: (1) INCIDENT HANDLING | AUTOMATED INCIDENT HANDLING PROCESSES Support the incident handling process using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms that support incident handling processes include online incident management systems and tools that support the collection of live response data, full network packet capture, and forensic analysis. Related Controls:  None. (2) INCIDENT HANDLING | DYNAMIC RECONFIGURATION', 'vec_doc-14-nist-sp-800-53-p179-676', 0, 247, 'v2.1.0', 'dd04d65d595c11cb7a9c2afe0c1f843af89e88d4d9e59dd39005de52a80ad0af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 152","subsection":"UNKNOWN","table_id":null,"page":179,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":676,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 152"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p180-677', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 153', 180, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Include the following types of dynamic reconfiguration for [Assignment: organization- defined system components] as part of the incident response capability: [Assignment: organization-defined types of dynamic reconfiguration]. Discussion:  Dynamic reconfiguration includes changes to router rules, access control lists, intrusion detection or prevention system parameters, and filter rules for guards or firewalls. Organizations may perform dynamic reconfiguration of systems to stop attacks, misdirect attackers, and isolate components of systems, thus limiting the extent of the damage from breaches or compromises. Organizations include specific time frames for achieving the reconfiguration of systems in the definition of the reconfiguration capability, considering the potential need for rapid response to effectively address cyber threats. Related Controls:  AC-2, AC-4, CM-2.', 'vec_doc-14-nist-sp-800-53-p180-677', 0, 244, 'v2.1.0', '5504032bfc4f0a557a18ae221a55e4a2e02473c49841a5b177f43bb4b437261a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 153","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":677,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 153"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p180-678', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 153', 180, '(3) INCIDENT HANDLING | CONTINUITY OF OPERATIONS Identify [Assignment: organization-defined classes of incidents] and take the following actions in response to those incidents to ensure continuation of organizational mission and business functions: [Assignment: organization-defined actions to take in response to classes of incidents]. Discussion:  Classes of incidents include malfunctions due to design or implementation errors and omissions, targeted malicious attacks, and untargeted malicious attacks. Incident response actions include orderly system degradation, system shutdown, fall back to manual mode or activation of alternative technology whereby the system operates differently, employing deceptive measures, alternate information flows, or operating in a mode that is reserved for when systems are under attack.', 'vec_doc-14-nist-sp-800-53-p180-678', 0, 207, 'v2.1.0', 'e13002ba35c8e589d51fc43527ddff95e6a34670c54d101abff9b7461d2ff307', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 153","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":678,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 153"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p180-679', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 153', 180, 'Organizations consider whether continuity of operations requirements during an incident conflict with the capability to automatically disable the system as specified as part of IR-4(5). Related Controls:  None. (4) INCIDENT HANDLING | INFORMATION CORRELATION Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response. Discussion:  Sometimes, a threat event, such as a hostile cyber-attack, can only be observed by bringing together information from different sources, including various reports and reporting procedures established by organizations. Related Controls:  None. (5) INCIDENT HANDLING | AUTOMATIC DISABLING OF SYSTEM Implement a configurable capability to automatically disable the system if [Assignment: organization-defined security violations] are detected.', 'vec_doc-14-nist-sp-800-53-p180-679', 0, 215, 'v2.1.0', 'b702e6058d9c4fec068d1bf7fdf7c5a9f9e3bab1780576aa064dfede76b80c87', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 153","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":679,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 153"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p180-680', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 153', 180, 'Discussion:  Organizations consider whether the capability to automatically disable the system conflicts with continuity of operations requirements specified as part of CP-2 or IR- 4(3). Security violations include cyber-attacks that have compromised the integrity of the system or exfiltrated organizational information and serious errors in software programs that could adversely impact organizational missions or functions or jeopardize the safety of individuals. Related Controls:  None. (6) INCIDENT HANDLING | INSIDER THREATS Implement an incident handling capability for incidents involving insider threats. Discussion:  Explicit focus on handling incidents involving insider threats provides additional emphasis on this type of threat and the need for specific incident handling capabilities to provide appropriate and timely responses.', 'vec_doc-14-nist-sp-800-53-p180-680', 0, 211, 'v2.1.0', '4891451660e7688ff58659be11da22b52d95df2cd2cc5f714fe19ba943d96690', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 153","subsection":"UNKNOWN","table_id":null,"page":180,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":680,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 153"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p181-681', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 154', 181, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (7) INCIDENT HANDLING | INSIDER THREATS —  INTRA-ORGANIZATION COORDINATION Coordinate an incident handling capability for insider threats that includes the following organizational entities [Assignment: organization-defined entities]. Discussion:  Incident handling for insider threat incidents (e.g., preparation, detection and analysis, containment, eradication, and recovery) requires coordination among many organizational entities, including mission or business owners, system owners, human resources offices, procurement offices, personnel offices, physical security offices, senior agency information security officer, operations personnel, risk executive (function), senior agency official for privacy, and legal counsel. In addition, organizations may require external support from federal, state, and local law enforcement agencies. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p181-681', 0, 246, 'v2.1.0', 'c72a24b7953be7b47beaefb7f108f11271c7c7d97023480e473b57eb6a0581cd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 154","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":681,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 154"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p181-682', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 154', 181, '(8) INCIDENT HANDLING | CORRELATION WITH EXTERNAL ORGANIZATIONS Coordinate with [Assignment: organization-defined external organizations] to correlate and share [Assignment: organization-defined incident information] to achieve a cross- organization perspective on incident awareness and more effective incident responses. Discussion:  The coordination of incident information with external organizations— including mission or business partners, military or coalition partners, customers, and developers— can provide significant benefits. Cross-organizational coordination can serve as an important risk management capability. This capability allows organizations to leverage information from a variety of sources to effectively respond to incidents and breaches that could potentially affect the organization’s operations, assets, and individuals. Related Controls:  AU-16, PM-16.', 'vec_doc-14-nist-sp-800-53-p181-682', 0, 221, 'v2.1.0', '5a251c6ac1639b12776d15bbacdc1aec561bd18fe63a75924cb7746b46a5b93f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 154","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":682,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 154"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p181-683', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 154', 181, '(9) INCIDENT HANDLING | DYNAMIC RESPONSE CAPABILITY Employ [Assignment: organization-defined dynamic response capabilities] to respond to incidents. Discussion:  The dynamic response capability addresses the timely deployment of new or replacement organizational capabilities in response to incidents. This includes capabilities implemented at the mission and business process level and at the system level. Related Controls:  None. (10) INCIDENT HANDLING | SUPPLY CHAIN COORDINATION Coordinate incident handling activities involving supply chain events with other organizations involved in the supply chain. Discussion:  Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers.', 'vec_doc-14-nist-sp-800-53-p181-683', 0, 199, 'v2.1.0', '7a6dcc72ae8bfaee20918dd5dcee5dac567441e4a85b65724eb367cb6802ea43', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 154","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":683,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 154"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p181-684', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 154', 181, 'Supply chain incidents can occur anywhere through or to the supply chain and include compromises or breaches that involve primary or sub-tier providers, information technology products, system components, development processes or personnel, and distribution processes or warehousing facilities. Organizations consider including processes for protecting and sharing incident information in information exchange agreements and their obligations for reporting incidents to government oversight bodies (e.g., Federal Acquisition Security Council). Related Controls:  CA-3, MA-2, SA-9, SR-8. (11) INCIDENT HANDLING | INTEGRATED INCIDENT RESPONSE TEAM Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in [Assignment: organization-defined time period].', 'vec_doc-14-nist-sp-800-53-p181-684', 0, 206, 'v2.1.0', 'd382638e827f7fb64fced82fdf78228e514aa99605d9e6eec8c1bfbc1d8a33e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 154","subsection":"UNKNOWN","table_id":null,"page":181,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":684,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 154"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p182-685', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 155', 182, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  An integrated incident response team is a team of experts that assesses, documents, and responds to incidents so that organizational systems and networks can recover quickly and implement the necessary controls to avoid future incidents. Incident response team personnel include forensic and malicious code analysts, tool developers, systems security and privacy engineers, and real-time operations personnel. The incident handling capability includes performing rapid forensic preservation of evidence and analysis of and response to intrusions. For some organizations, the incident response team can be a cross-organizational entity.', 'vec_doc-14-nist-sp-800-53-p182-685', 0, 185, 'v2.1.0', '4d6623ffb46a308bbaf4d8ca3b2678d53d5fe8e0b4a6e9ed8647f853dc4f1b37', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 155","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":685,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 155"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p182-686', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 155', 182, 'An integrated incident response team facilitates information sharing and allows organizational personnel (e.g., developers, implementers, and operators) to leverage team knowledge of the threat and implement defensive measures that enable organizations to deter intrusions more effectively. Moreover, integrated teams promote the rapid detection of intrusions, the development of appropriate mitigations, and the deployment of effective defensive measures. For example, when an intrusion is detected, the integrated team can rapidly develop an appropriate response for operators to implement, correlate the new incident with information on past intrusions, and augment ongoing cyber intelligence development. Integrated incident response teams are better able to identify adversary tactics, techniques, and procedures that are linked to the operations tempo or specific mission and business functions and to define responsive actions in a way that does not disrupt those mission and business functions.', 'vec_doc-14-nist-sp-800-53-p182-686', 0, 251, 'v2.1.0', 'f5524b2e73695f1d1fb1a69cc789d58e241b0e3448ac617b8899d4a4fa20cdc7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 155","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":686,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 155"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p182-687', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 155', 182, 'Incident response teams can be distributed within organizations to make the capability resilient. Related Controls:  AT-3. (12) INCIDENT HANDLING | MALICIOUS CODE AND FORENSIC ANALYSIS Analyze malicious code and/or other residual artifacts remaining in the system after the incident. Discussion:  When conducted carefully in an isolated environment, analysis of malicious code and other residual artifacts of a security incident or breach can give the organization insight into adversary tactics, techniques, and procedures. It can also indicate the identity or some defining characteristics of the adversary. In addition, malicious code analysis can help the organization develop responses to future incidents. Related Controls:  None. (13) INCIDENT HANDLING | BEHAVIOR ANALYSIS Analyze anomalous or suspected adversarial behavior in or related to [Assignment: organization-defined environments or resources].', 'vec_doc-14-nist-sp-800-53-p182-687', 0, 228, 'v2.1.0', '7e3e46f211c2db2fcb1af4fbd5d596d472d415b59e598e9e67d33c7b50680365', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 155","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":687,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 155"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p182-688', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 155', 182, 'Discussion:  If the organization maintains a deception environment, an analysis of behaviors in that environment, including resources targeted by the adversary and timing of the incident or event, can provide insight into adversarial tactics, techniques, and procedures. External to a deception environment, the analysis of anomalous adversarial behavior (e.g., changes in system performance or usage patterns) or suspected behavior (e.g., changes in searches for the location of specific resources) can give the organization such insight. Related Controls:  None. (14) INCIDENT HANDLING | SECURITY OPERATIONS CENTER Establish and maintain a security operations center. Discussion:  A security operations center (SOC) is the focal point for security operations and computer network defense for an organization. The purpose of the SOC is to defend and monitor an organization’s systems and networks (i.e., cyber infrastructure) on an ongoing basis.', 'vec_doc-14-nist-sp-800-53-p182-688', 0, 237, 'v2.1.0', 'b51b39b3e30f4667339df1c949768a958355ebef4604d08f4a4a0109aeffcad9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 155","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":688,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 155"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p182-689', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 155', 182, 'The SOC is also responsible for detecting, analyzing, and responding to cybersecurity incidents in a timely manner. The organization staffs the SOC with skilled technical and', 'vec_doc-14-nist-sp-800-53-p182-689', 0, 44, 'v2.1.0', 'c548ae07aa756fa56de39437bc63d0a0c3ab41c12d81c4d980fccf9a5c6f6282', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 155","subsection":"UNKNOWN","table_id":null,"page":182,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":689,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 155"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p183-690', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 156', 183, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 operational personnel (e.g., security analysts, incident response personnel, systems security engineers) and implements a combination of technical, management, and operational controls (including monitoring, scanning, and forensics tools) to monitor, fuse, correlate, analyze, and respond to threat and security-relevant event data from multiple sources. These sources include perimeter defenses, network devices (e.g., routers, switches), and endpoint agent data feeds. The SOC provides a holistic situational awareness capability to help organizations determine the security posture of the system and organization. A SOC capability can be obtained in a variety of ways. Larger organizations may implement a dedicated SOC while smaller organizations may employ third-party organizations to provide such a capability. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p183-690', 0, 234, 'v2.1.0', '1b2d29c531b18e923fde3e2a4fa96d6d9fa5256d3d6d35df889daa0c4569c3a4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 156","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":690,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 156"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p183-691', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 156', 183, '(15) INCIDENT HANDLING | PUBLIC RELATIONS AND REPUTATION REPAIR (a) Manage public relations associated with an incident; and (b) Employ measures to repair the reputation of the organization. Discussion:  It is important for an organization to have a strategy in place for addressing incidents that have been brought to the attention of the general public, have cast the organization in a negative light, or have affected the organization’s constituents (e.g., partners, customers). Such publicity can be extremely harmful to the organization and affect its ability to carry out its mission and business functions. Taking proactive steps to repair the organization’s reputation is an essential aspect of reestablishing the trust and confidence of its constituents. Related Controls:  None. References:  [FASC18], [41 CFR 201], [OMB M-17-12], [SP 800-61], [SP 800-86], [SP 800-101], [SP 800-150], [SP 800-160-2], [SP 800-184], [IR 7559]. IR-5 INCIDENT MONITORING Control:  Track and document incidents.', 'vec_doc-14-nist-sp-800-53-p183-691', 0, 250, 'v2.1.0', 'fabe5ff7bad2e561427aa217744a022b655f6ba8354d5ad766994b8a5cd0e6ef', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 156","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":691,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 156"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p183-692', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 156', 183, 'Discussion:  Documenting incidents includes maintaining records about each incident, the status of the incident, and other pertinent information necessary for forensics as well as evaluating incident details, trends, and handling. Incident information can be obtained from a variety of sources, including network monitoring, incident reports, incident response teams, user complaints, supply chain partners, audit monitoring, physical access monitoring, and user and administrator reports. IR-4 provides information on the types of incidents that are appropriate for monitoring. Related Controls:  AU-6, AU-7, IR-4, IR-6, IR-8, PE-6, PM-5, SC-5, SC-7, SI-3, SI-4, SI-7. Control Enhancements: (1) INCIDENT MONITORING | AUTOMATED TRACKING, DATA COLLECTION, AND ANALYSIS Track incidents and collect and analyze incident information using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p183-692', 0, 223, 'v2.1.0', '5df5dfe1745b9742ba890fccf94bac82722756208b9bdb8f80f9736a399612e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 156","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":692,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 156"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p183-693', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 156', 183, 'Discussion:  Automated mechanisms for tracking incidents and collecting and analyzing incident information include Computer Incident Response Centers or other electronic databases of incidents and network monitoring devices. Related Controls:  None. References:  [SP 800-61].', 'vec_doc-14-nist-sp-800-53-p183-693', 0, 69, 'v2.1.0', '8a78b90ccb14cfffa7a3ac9e52818d22e1879756ddd84888b5347db63f6f356d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 156","subsection":"UNKNOWN","table_id":null,"page":183,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":693,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 156"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p184-694', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 157', 184, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 IR-6 INCIDENT REPORTING Control: a. Require personnel to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period]; and b. Report incident information to [Assignment: organization-defined authorities]. Discussion:  The types of incidents reported, the content and timeliness of the reports, and the designated reporting authorities reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Incident information can inform risk assessments, control effectiveness assessments, security requirements for acquisitions, and selection criteria for technology products. Related Controls:  CM-6, CP-2, IR-4, IR-5, IR-8, IR-9. Control Enhancements: (1) INCIDENT REPORTING | AUTOMATED REPORTING Report incidents using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p184-694', 0, 245, 'v2.1.0', 'b7d7a8222ab458a4922422b5299a5243ba662110bcad80db901d0cd25db10252', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 157","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":694,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 157"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p184-695', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 157', 184, 'Discussion:  The recipients of incident reports are specified in IR-6b. Automated reporting mechanisms include email, posting on websites (with automatic updates), and automated incident response tools and programs. Related Controls:  IR-7. (2) INCIDENT REPORTING | VULNERABILITIES RELATED TO INCIDENTS Report system vulnerabilities associated with reported incidents to [Assignment: organization-defined personnel or roles]. Discussion:  Reported incidents that uncover system vulnerabilities are analyzed by organizational personnel including system owners, mission and business owners, senior agency information security officers, senior agency officials for privacy, authorizing officials, and the risk executive (function). The analysis can serve to prioritize and initiate mitigation actions to address the discovered system vulnerability. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p184-695', 0, 218, 'v2.1.0', '79583b6507202759f5768ee8efeb66e9006df83d3a2544aa7f02efed1debdfdc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 157","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":695,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 157"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p184-696', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 157', 184, '(3) INCIDENT REPORTING | SUPPLY CHAIN COORDINATION Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident. Discussion:  Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Entities that provide supply chain governance include the Federal Acquisition Security Council (FASC). Supply chain incidents include compromises or breaches that involve information technology products, system components, development processes or personnel, distribution processes, or warehousing facilities. Organizations determine the appropriate information to share and consider the value gained from informing external organizations about supply chain incidents, including the ability to improve processes or to identify the root cause of an incident.', 'vec_doc-14-nist-sp-800-53-p184-696', 0, 251, 'v2.1.0', '0fcfdcf5f895426965925443cd6e28b755c513083ca1a13dae0b2f0a15fdbf1a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 157","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":696,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 157"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p184-697', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 157', 184, 'Related Controls:  SR-8. References:  [FASC18], [41 CFR 201], [USCERT IR], [SP 800-61].', 'vec_doc-14-nist-sp-800-53-p184-697', 0, 22, 'v2.1.0', 'a4f8e1335fa2105b5a9c70aa75c0d5051ba0fcb961a09559ba3819877c7974d2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 157","subsection":"UNKNOWN","table_id":null,"page":184,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":697,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 157"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p185-698', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 158', 185, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 IR-7 INCIDENT RESPONSE ASSISTANCE Control:  Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents. Discussion:  Incident response support resources provided by organizations include help desks, assistance groups, automated ticketing systems to open and track incident response tickets, and access to forensics services or consumer redress services, when required. Related Controls:  AT-2, AT-3, IR-4, IR-6, IR-8, PM-22, PM-26, SA-9, SI-18. Control Enhancements: (1) INCIDENT RESPONSE ASSISTANCE | AUTOMATION SUPPORT FOR AVAILABILITY OF INFORMATION AND SUPPORT Increase the availability of incident response information and support using [Assignment: organization-defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p185-698', 0, 235, 'v2.1.0', 'fa769cb77cc658a5eb2e013adc72038b903f943d124b9e70a8ef63005a8c06ce', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 158","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":698,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 158"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p185-699', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 158', 185, 'Discussion:  Automated mechanisms can provide a push or pull capability for users to obtain incident response assistance. For example, individuals may have access to a website to query the assistance capability, or the assistance capability can proactively send incident response information to users (general distribution or targeted) as part of increasing understanding of current response capabilities and support. Related Controls:  None. (2) INCIDENT RESPONSE ASSISTANCE | COORDINATION WITH EXTERNAL PROVIDERS (a) Establish a direct, cooperative relationship between its incident response capability and external providers of system protection capability; and (b) Identify organizational incident response team members to the external providers. Discussion:  External providers of a system protection capability include the Computer Network Defense program within the U.S. Department of Defense.', 'vec_doc-14-nist-sp-800-53-p185-699', 0, 225, 'v2.1.0', 'e9612e85a628dea3f03639b73a620e1e28623dcd4f8473d8a44cf45ad1cbd2d8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 158","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":699,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 158"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p185-700', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 158', 185, 'External providers help to protect, monitor, analyze, detect, and respond to unauthorized activity within organizational information systems and networks. It may be beneficial to have agreements in place with external providers to clarify the roles and responsibilities of each party before an incident occurs. Related Controls:  None. References:  [OMB A-130], [IR 7559]. IR-8 INCIDENT RESPONSE PLAN Control: a. Develop an incident response plan that:', 'vec_doc-14-nist-sp-800-53-p185-700', 0, 113, 'v2.1.0', '19d58a10f8f71fa78c6642c8ce7de194825cfa80a7b918d5148e758d87fcc203', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 158","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":700,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 158"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p185-701', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Meets the unique requirements of the organization, which relate to mission, size,', 185, 'structure, and functions;', 'vec_doc-14-nist-sp-800-53-p185-701', 0, 7, 'v2.1.0', '0247f77d307069950b72a025619eba43c6af5b8b7c104b35adc50f2520c48eb0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Meets the unique requirements of the organization, which relate to mission, size,","subsection":"UNKNOWN","table_id":null,"page":185,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":701,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Meets the unique requirements of the organization, which relate to mission, size,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-702', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '7. Defines the resources and management support needed to effectively maintain and', 186, 'mature an incident response capability;', 'vec_doc-14-nist-sp-800-53-p186-702', 0, 10, 'v2.1.0', '84929a4fcd35cc1670fd3e6ed74e8c4985b9b74c2393d419dbfbda8c97f65f70', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"7. Defines the resources and management support needed to effectively maintain and","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":702,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"7. Defines the resources and management support needed to effectively maintain and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-703', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '9. Is reviewed and approved by [Assignment: organization-defined personnel or roles]', 186, '[Assignment: organization-defined frequency]; and', 'vec_doc-14-nist-sp-800-53-p186-703', 0, 13, 'v2.1.0', '1cbda092fb198116b075f6c9fcf77be08a60f69c22b70abf0bd225bb8a1d0eee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"9. Is reviewed and approved by [Assignment: organization-defined personnel or roles]","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":703,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"9. Is reviewed and approved by [Assignment: organization-defined personnel or roles]"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-704', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '10. Explicitly designates responsibility for incident response to [Assignment: organization-', 186, 'defined entities, personnel, or roles]. b. Distribute copies of the incident response plan to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements]; c. Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing; d. Communicate incident response plan changes to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements]; and e. Protect the incident response plan from unauthorized disclosure and modification. Discussion:  It is important that organizations develop and implement a coordinated approach to incident response. Organizational mission and business functions determine the structure of incident response capabilities.', 'vec_doc-14-nist-sp-800-53-p186-704', 0, 216, 'v2.1.0', 'e13e25a913f49de1984de85d6a7bdd4b69cd591136081f2bba3a2761a7a52d68', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"10. Explicitly designates responsibility for incident response to [Assignment: organization-","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":704,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"10. Explicitly designates responsibility for incident response to [Assignment: organization-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-705', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '10. Explicitly designates responsibility for incident response to [Assignment: organization-', 186, 'As part of the incident response capabilities, organizations consider the coordination and sharing of information with external organizations, including external service providers and other organizations involved in the supply chain. For incidents involving personally identifiable information (i.e., breaches), include a process to determine whether notice to oversight organizations or affected individuals is appropriate and provide that notice accordingly. Related Controls:  AC-2, CP-2, CP-4, IR-4, IR-7, IR-9, PE-6, PL-2, SA-15, SI-12, SR-8.', 'vec_doc-14-nist-sp-800-53-p186-705', 0, 137, 'v2.1.0', '0dcd8be282dcb93447c026aa73d6007b4dea0d0486bbe0889bdf17508c701861', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"10. Explicitly designates responsibility for incident response to [Assignment: organization-","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":705,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"10. Explicitly designates responsibility for incident response to [Assignment: organization-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-706', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '10. Explicitly designates responsibility for incident response to [Assignment: organization-', 186, 'Control Enhancements: (1) INCIDENT RESPONSE PLAN | BREACHES Include the following in the Incident Response Plan for breaches involving personally identifiable information: (a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed; (b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and (c) Identification of applicable privacy requirements. Discussion:  Organizations may be required by law, regulation, or policy to follow specific procedures relating to breaches, including notice to individuals, affected organizations, and oversight bodies; standards of harm; and mitigation or other specific requirements. Related Controls:  PT-1, PT-2, PT-3, PT-4, PT-5, PT-7. References:  [OMB A-130], [SP 800-61], [OMB M-17-12]. IR-9 INFORMATION SPILLAGE RESPONSE Control:  Respond to information spills by: a.', 'vec_doc-14-nist-sp-800-53-p186-706', 0, 247, 'v2.1.0', 'b25451529dad25ce02c578f37d1fbdad9965f68ca70b02c9bb02aacc4f3f70c4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"10. Explicitly designates responsibility for incident response to [Assignment: organization-","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":706,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"10. Explicitly designates responsibility for incident response to [Assignment: organization-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p186-707', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '10. Explicitly designates responsibility for incident response to [Assignment: organization-', 186, 'Assigning [Assignment: organization-defined personnel or roles] with responsibility for responding to information spills;', 'vec_doc-14-nist-sp-800-53-p186-707', 0, 31, 'v2.1.0', 'ef843c714439d23f9974167bb6b040d556c9474570466837b7f2e16e639c1503', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"10. Explicitly designates responsibility for incident response to [Assignment: organization-","subsection":"UNKNOWN","table_id":null,"page":186,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":707,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"10. Explicitly designates responsibility for incident response to [Assignment: organization-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p187-708', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 160', 187, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Identifying the specific information involved in the system contamination; c. Alerting [Assignment: organization-defined personnel or roles] of the information spill using a method of communication not associated with the spill; d. Isolating the contaminated system or system component; e. Eradicating the information from the contaminated system or component; f. Identifying other systems or system components that may have been subsequently contaminated; and g. Performing the following additional actions: [Assignment: organization-defined actions]. Discussion:  Information spillage refers to instances where information is placed on systems that are not authorized to process such information. Information spills occur when information that is thought to be a certain classification or impact level is transmitted to a system and subsequently is determined to be of a higher classification or impact level.', 'vec_doc-14-nist-sp-800-53-p187-708', 0, 252, 'v2.1.0', '6d27513eccc38c630f91919580553f6ca09a9837f90d2ea0a368474b37a3ff76', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 160","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":708,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 160"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p187-709', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 160', 187, 'At that point, corrective action is required. The nature of the response is based on the classification or impact level of the spilled information, the security capabilities of the system, the specific nature of the contaminated storage media, and the access authorizations of individuals with authorized access to the contaminated system. The methods used to communicate information about the spill after the fact do not involve methods directly associated with the actual spill to minimize the risk of further spreading the contamination before such contamination is isolated and eradicated. Related Controls:  CP-2, IR-6, PM-26, PM-27, PT-2, PT-3, PT-7, RA-7. Control Enhancements: (1) INFORMATION SPILLAGE RESPONSE | RESPONSIBLE PERSONNEL [Withdrawn: Incorporated into IR-9.] (2) INFORMATION SPILLAGE RESPONSE | TRAINING Provide information spillage response training [Assignment: organization-defined frequency].', 'vec_doc-14-nist-sp-800-53-p187-709', 0, 230, 'v2.1.0', '8006a1ce7b36af0f088ab23ba4635d85525b090531344b8a65e6cb7a21938bb0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 160","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":709,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 160"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p187-710', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 160', 187, 'Discussion:  Organizations establish requirements for responding to information spillage incidents in incident response plans. Incident response training on a regular basis helps to ensure that organizational personnel understand their individual responsibilities and what specific actions to take when spillage incidents occur. Related Controls:  AT-2, AT-3, CP-3, IR-2. (3) INFORMATION SPILLAGE RESPONSE | POST-SPILL OPERATIONS Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: [Assignment: organization-defined procedures]. Discussion:  Corrective actions for systems contaminated due to information spillages may be time-consuming. Personnel may not have access to the contaminated systems while corrective actions are being taken, which may potentially affect their ability to conduct organizational business. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p187-710', 0, 250, 'v2.1.0', 'a7d7cc3c7dec6229eec290ba6abc42b965bf6192524e9e393607d585c6f9a26c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 160","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":710,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 160"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p187-711', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 160', 187, '(4) INFORMATION SPILLAGE RESPONSE | EXPOSURE TO UNAUTHORIZED PERSONNEL Employ the following controls for personnel exposed to information not within assigned access authorizations: [Assignment: organization-defined controls]. Discussion:  Controls include ensuring that personnel who are exposed to spilled information are made aware of the laws, executive orders, directives, regulations, policies, standards,', 'vec_doc-14-nist-sp-800-53-p187-711', 0, 103, 'v2.1.0', 'f00cf9ddf50108bb7b28c0a132f616869b5e6e90a89fd46099adab37dcfd5ad2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 160","subsection":"UNKNOWN","table_id":null,"page":187,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":711,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 160"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p188-712', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 161', 188, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and guidelines regarding the information and the restrictions imposed based on exposure to such information. Related Controls:  None. References:  None. IR-10 INTEGRATED INFORMATION SECURITY ANALYSIS TEAM [Withdrawn: Moved to IR-4(11).]', 'vec_doc-14-nist-sp-800-53-p188-712', 0, 82, 'v2.1.0', '327256fc74db1db37031ab8183573013b110754a72441cbb605a1addb411efe6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 161","subsection":"UNKNOWN","table_id":null,"page":188,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":712,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 161"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p189-713', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.9   MAINTENANCE', 189, 'Quick link to Maintenance Summary Table MA-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p189-713', 0, 43, 'v2.1.0', '4f0c218a7993ede3e08e3746b14e1a7709064291e62ae0e3a9d2cb9ba8f83e3c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.9   MAINTENANCE","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":713,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.9   MAINTENANCE"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p189-714', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 189, 'level] maintenance policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p189-714', 0, 75, 'v2.1.0', '3907608790cdc2d9b5c6476ca2bb9e45795f5f709634bfce3c17d3501e6a3a10', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":714,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p189-715', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the maintenance policy and the', 189, 'associated maintenance controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the maintenance policy and procedures; and c. Review and update the current maintenance:', 'vec_doc-14-nist-sp-800-53-p189-715', 0, 61, 'v2.1.0', '9d58b107fb8a321e9a7a40c17290130a11c379df69370f80a69728bef0915676', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the maintenance policy and the","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":715,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the maintenance policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p189-716', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 189, 'organization-defined events]. Discussion:  Maintenance policy and procedures address the controls in the MA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of maintenance policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to maintenance policy and procedures assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p189-716', 0, 421, 'v2.1.0', '0a72a5a53bc5444785d66d8b0ec9fce4b53fc736e598dd22322e6841de5ec0cf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":189,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":716,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p190-717', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 163', 190, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 MA-2 CONTROLLED MAINTENANCE Control: a. Schedule, document, and review records of maintenance, repair, and replacement on system components in accordance with manufacturer or vendor specifications and/or organizational requirements; b. Approve and monitor all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location; c. Require that [Assignment: organization-defined personnel or roles] explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement; d. Sanitize equipment to remove the following information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement: [Assignment: organization-defined information]; e.', 'vec_doc-14-nist-sp-800-53-p190-717', 0, 239, 'v2.1.0', '022693c4918c1281f9f776612493cc4674a03067c6598fc95465d52620a3255b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 163","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":717,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 163"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p190-718', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 163', 190, 'Check all potentially impacted controls to verify that the controls are still functioning properly following maintenance, repair, or replacement actions; and f. Include the following information in organizational maintenance records: [Assignment: organization-defined information]. Discussion:  Controlling system maintenance addresses the information security aspects of the system maintenance program and applies to all types of maintenance to system components conducted by local or nonlocal entities. Maintenance includes peripherals such as scanners, copiers, and printers. Information necessary for creating effective maintenance records includes the date and time of maintenance, a description of the maintenance performed, names of the individuals or group performing the maintenance, name of the escort, and system components or equipment that are removed or replaced. Organizations consider supply chain-related risks associated with replacement components for systems.', 'vec_doc-14-nist-sp-800-53-p190-718', 0, 245, 'v2.1.0', '6bc965c475899c9303deca1bd707ae6bc15dfb2269cc49004b3ca8b20a6022ff', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 163","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":718,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 163"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p190-719', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 163', 190, 'Related Controls:  CM-2,  CM-3, CM-4, CM-5, CM-8, MA-4, MP-6, PE-16, SI-2, SR-3, SR-4, SR-11. Control Enhancements: (1) CONTROLLED MAINTENANCE | RECORD CONTENT [Withdrawn: Incorporated into MA-2.] (2) CONTROLLED MAINTENANCE | AUTOMATED MAINTENANCE ACTIVITIES (a) Schedule, conduct, and document maintenance, repair, and replacement actions for the system using [Assignment: organization-defined automated mechanisms]; and (b) Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed. Discussion:  The use of automated mechanisms to manage and control system maintenance programs and activities helps to ensure the generation of timely, accurate, complete, and consistent maintenance records. Related Controls:  MA-3. References:  [OMB A-130], [IR 8023]. MA-3 MAINTENANCE TOOLS Control: a. Approve, control, and monitor the use of system maintenance tools; and', 'vec_doc-14-nist-sp-800-53-p190-719', 0, 239, 'v2.1.0', 'c30fa4b842dc5c69037186ef821267ca51453f790d831ce80c13db8b1ff8be6d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 163","subsection":"UNKNOWN","table_id":null,"page":190,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":719,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 163"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p191-720', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 164', 191, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Review previously approved system maintenance tools [Assignment: organization-defined frequency]. Discussion:  Approving, controlling, monitoring, and reviewing maintenance tools address security-related issues associated with maintenance tools that are not within system authorization boundaries and are used specifically for diagnostic and repair actions on organizational systems. Organizations have flexibility in determining roles for the approval of maintenance tools and how that approval is documented. A periodic review of maintenance tools facilitates the withdrawal of approval for outdated, unsupported, irrelevant, or no-longer- used tools. Maintenance tools can include hardware, software, and firmware items and may be pre-installed, brought in with maintenance personnel on media, cloud-based, or downloaded from a website.', 'vec_doc-14-nist-sp-800-53-p191-720', 0, 234, 'v2.1.0', 'b363de18a7edb7165841077d0d236304037dd11c8be7346c1a8e1ca33d80fe4b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 164","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":720,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 164"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p191-721', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 164', 191, 'Such tools can be vehicles for transporting malicious code, either intentionally or unintentionally, into a facility and subsequently into systems. Maintenance tools can include hardware and software diagnostic test equipment and packet sniffers. The hardware and software components that support maintenance and are a part of the system (including the software implementing utilities such as “ping,” “ls,” “ipconfig,” or the hardware and software implementing the monitoring port of an Ethernet switch) are not addressed by maintenance tools. Related Controls:  MA-2, PE-16. Control Enhancements: (1) MAINTENANCE TOOLS | INSPECT TOOLS Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications. Discussion:  Maintenance tools can be directly brought into a facility by maintenance personnel or downloaded from a vendor’s website.', 'vec_doc-14-nist-sp-800-53-p191-721', 0, 219, 'v2.1.0', 'f2289c51c75e35cd14d3ff24b4e73855ba50e373d8fafeef58015d4146d79c38', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 164","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":721,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 164"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p191-722', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 164', 191, 'If, upon inspection of the maintenance tools, organizations determine that the tools have been modified in an improper manner or the tools contain malicious code, the incident is handled consistent with organizational policies and procedures for incident handling. Related Controls:  SI-7. (2) MAINTENANCE TOOLS | INSPECT MEDIA Check media containing diagnostic and test programs for malicious code before the media are used in the system. Discussion:  If, upon inspection of media containing maintenance, diagnostic, and test programs, organizations determine that the media contains malicious code, the incident is handled consistent with organizational incident handling policies and procedures. Related Controls:  SI-3.', 'vec_doc-14-nist-sp-800-53-p191-722', 0, 181, 'v2.1.0', 'b1a2d2436cbcbada88ca8f8c2c5533baf4143cd17b2ee3e2f7f778a54c0ae9bc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 164","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":722,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 164"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p191-723', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 164', 191, '(3) MAINTENANCE TOOLS | PREVENT UNAUTHORIZED REMOVAL Prevent the removal of maintenance equipment containing organizational information by: (a) Verifying that there is no organizational information contained on the equipment; (b) Sanitizing or destroying the equipment; (c) Retaining the equipment within the facility; or (d) Obtaining an exemption from [Assignment: organization-defined personnel or roles] explicitly authorizing removal of the equipment from the facility. Discussion:  Organizational information includes all information owned by organizations and any information provided to organizations for which the organizations serve as information stewards. Related Controls:  MP-6.', 'vec_doc-14-nist-sp-800-53-p191-723', 0, 173, 'v2.1.0', '343ef06992ac5096c9f8cdc6d472888aeff9b8ff09f319dae0454090682a16a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 164","subsection":"UNKNOWN","table_id":null,"page":191,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":723,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 164"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p192-724', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 165', 192, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (4) MAINTENANCE TOOLS | RESTRICTED TOOL USE Restrict the use of maintenance tools to authorized personnel only. Discussion:  Restricting the use of maintenance tools to only authorized personnel applies to systems that are used to carry out maintenance functions. Related Controls:  AC-3, AC-5, AC-6. (5) MAINTENANCE TOOLS | EXECUTION WITH PRIVILEGE Monitor the use of maintenance tools that execute with increased privilege. Discussion:  Maintenance tools that execute with increased system privilege can result in unauthorized access to organizational information and assets that would otherwise be inaccessible. Related Controls:  AC-3, AC-6. (6) MAINTENANCE TOOLS | SOFTWARE UPDATES AND PATCHES Inspect maintenance tools to ensure the latest software updates and patches are installed.', 'vec_doc-14-nist-sp-800-53-p192-724', 0, 221, 'v2.1.0', '58b7936e28e7e72e3b0c29b5244d01068bd8ea32a0983c560123be25a9be8918', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 165","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":724,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 165"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p192-725', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 165', 192, 'Discussion:  Maintenance tools using outdated and/or unpatched software can provide a threat vector for adversaries and result in a significant vulnerability for organizations. Related Controls:  AC-3, AC-6. References:  [SP 800-88]. MA-4 NONLOCAL MAINTENANCE Control: a. Approve and monitor nonlocal maintenance and diagnostic activities; b. Allow the use of nonlocal maintenance and diagnostic tools only as consistent with organizational policy and documented in the security plan for the system; c. Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions; d. Maintain records for nonlocal maintenance and diagnostic activities; and e. Terminate session and network connections when nonlocal maintenance is completed. Discussion:  Nonlocal maintenance and diagnostic activities are conducted by individuals who communicate through either an external or internal network.', 'vec_doc-14-nist-sp-800-53-p192-725', 0, 229, 'v2.1.0', 'c50619a59de6d3844ca34c84b39fa8a69dce8e55cf6024c027999407a7e4b265', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 165","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":725,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 165"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p192-726', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 165', 192, 'Local maintenance and diagnostic activities are carried out by individuals who are physically present at the system location and not communicating across a network connection. Authentication techniques used to establish nonlocal maintenance and diagnostic sessions reflect the network access requirements in IA-2. Strong authentication requires authenticators that are resistant to replay attacks and employ multi-factor authentication. Strong authenticators include PKI where certificates are stored on a token protected by a password, passphrase, or biometric. Enforcing requirements in MA-4 is accomplished, in part, by other controls. [SP 800-63B] provides additional guidance on strong authentication and authenticators. Related Controls:  AC-2, AC-3, AC-6, AC-17, AU-2, AU-3, IA-2, IA-4, IA-5, IA-8, MA-2, MA-5, PL-2, SC-7, SC-10.', 'vec_doc-14-nist-sp-800-53-p192-726', 0, 209, 'v2.1.0', '11e2a379d7bb9f086cbde0ac67391f81ebd7764e768d06b82186eb43cb310fdd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 165","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":726,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 165"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p192-727', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 165', 192, 'Control Enhancements: (1) NONLOCAL MAINTENANCE | LOGGING AND REVIEW (a) Log [Assignment: organization-defined audit events] for nonlocal maintenance and diagnostic sessions; and', 'vec_doc-14-nist-sp-800-53-p192-727', 0, 45, 'v2.1.0', '30071dddb3a1f45880a35461b9d07ede6cea2b4cc91df7948cb978f4f2e313ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 165","subsection":"UNKNOWN","table_id":null,"page":192,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":727,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 165"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p193-728', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 166', 193, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior. Discussion:  Audit logging for nonlocal maintenance is enforced by AU-2. Audit events are defined in AU-2a. Related Controls:  AU-6, AU-12.', 'vec_doc-14-nist-sp-800-53-p193-728', 0, 84, 'v2.1.0', '757722c640d2cc211121616997f6b90ef232d826d816ddd9e14922be657e9a37', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 166","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":728,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 166"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p193-729', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 166', 193, '(2) NONLOCAL MAINTENANCE | DOCUMENT NONLOCAL MAINTENANCE [Withdrawn: Incorporated into MA-1 and MA-4.] (3) NONLOCAL MAINTENANCE | COMPARABLE SECURITY AND SANITIZATION (a) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or (b) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system. Discussion:  Comparable security capability on systems, diagnostic tools, and equipment providing maintenance services implies that the implemented controls on those systems, tools, and equipment are at least as comprehensive as the controls on the system being serviced. Related Controls:  MP-6, SI-3, SI-7.', 'vec_doc-14-nist-sp-800-53-p193-729', 0, 250, 'v2.1.0', '07dea44dcb0f5448b4bec606458dada42cee1bee0e698b0d0bbf628a43b0ca24', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 166","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":729,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 166"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p193-730', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 166', 193, '(4) NONLOCAL MAINTENANCE | AUTHENTICATION AND SEPARATION OF MAINTENANCE SESSIONS Protect nonlocal maintenance sessions by: (a) Employing [Assignment: organization-defined authenticators that are replay resistant]; and (b) Separating the maintenance sessions from other network sessions with the system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths. Discussion:  Communications paths can be logically separated using encryption. Related Controls:  None. (5) NONLOCAL MAINTENANCE | APPROVALS AND NOTIFICATIONS (a) Require the approval of each nonlocal maintenance session by [Assignment: organization-defined personnel or roles]; and (b) Notify the following personnel or roles of the date and time of planned nonlocal maintenance: [Assignment: organization-defined personnel or roles]. Discussion:  Notification may be performed by maintenance personnel.', 'vec_doc-14-nist-sp-800-53-p193-730', 0, 229, 'v2.1.0', '5a9a792cd0cad744b31967cdb4e2abce7ccd8fe0ceb1f34a4a480136471f64ec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 166","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":730,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 166"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p193-731', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 166', 193, 'Approval of nonlocal maintenance is accomplished by personnel with sufficient information security and system knowledge to determine the appropriateness of the proposed maintenance. Related Controls:  None. (6) NONLOCAL MAINTENANCE | CRYPTOGRAPHIC PROTECTION Implement the following cryptographic mechanisms to protect the integrity and confidentiality of nonlocal maintenance and diagnostic communications: [Assignment: organization-defined cryptographic mechanisms]. Discussion:  Failure to protect nonlocal maintenance and diagnostic communications can result in unauthorized individuals gaining access to organizational information. Unauthorized', 'vec_doc-14-nist-sp-800-53-p193-731', 0, 163, 'v2.1.0', 'c11dc9de237b0f8ac9253cdb04f2f4efe2cb9ecf177e4e6a6d12639ebce45830', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 166","subsection":"UNKNOWN","table_id":null,"page":193,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":731,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 166"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p194-732', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 167', 194, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 access during remote maintenance sessions can result in a variety of hostile actions, including malicious code insertion, unauthorized changes to system parameters, and exfiltration of organizational information. Such actions can result in the loss or degradation of mission or business capabilities. Related Controls:  SC-8, SC-12, SC-13. (7) NONLOCAL MAINTENANCE | DISCONNECT VERIFICATION Verify session and network connection termination after the completion of nonlocal maintenance and diagnostic sessions. Discussion:  Verifying the termination of a connection once maintenance is completed ensures that connections established during nonlocal maintenance and diagnostic sessions have been terminated and are no longer available for use. Related Controls:  AC-12. References:  [FIPS 140-3], [FIPS 197], [FIPS 201-2], [SP 800-63-3], [SP 800-88]. MA-5 MAINTENANCE PERSONNEL Control: a.', 'vec_doc-14-nist-sp-800-53-p194-732', 0, 245, 'v2.1.0', 'bb9a6ac6f03bbda4bf9602bba2d37a5aff565004b51d0e75431b4bffa7c63f34', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 167","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":732,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 167"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p194-733', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 167', 194, 'Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel; b. Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; and c. Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations. Discussion:  Maintenance personnel refers to individuals who perform hardware or software maintenance on organizational systems, while PE-2 addresses physical access for individuals whose maintenance duties place them within the physical protection perimeter of the systems. Technical competence of supervising individuals relates to the maintenance performed on the systems, while having required access authorizations refers to maintenance on and near the systems.', 'vec_doc-14-nist-sp-800-53-p194-733', 0, 233, 'v2.1.0', '31d3b3ff8cbbdf2056ffe4a762a4c59dff17701bac900f92f778d721533b54ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 167","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":733,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 167"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p194-734', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 167', 194, 'Individuals not previously identified as authorized maintenance personnel— such as information technology manufacturers, vendors, systems integrators, and consultants— may require privileged access to organizational systems, such as when they are required to conduct maintenance activities with little or no notice. Based on organizational assessments of risk, organizations may issue temporary credentials to these individuals. Temporary credentials may be for one-time use or for very limited time periods. Related Controls:  AC-2, AC-3, AC-5, AC-6, IA-2, IA-8, MA-4, MP-2, PE-2, PE-3, PS-7, RA-3. Control Enhancements: (1) MAINTENANCE PERSONNEL | INDIVIDUALS WITHOUT APPROPRIATE ACCESS (a) Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S.', 'vec_doc-14-nist-sp-800-53-p194-734', 0, 202, 'v2.1.0', '7bdf434774fc85f14ba8c0a71a9c6ae3a27fd85891e8edb69cc3bfa50620558c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 167","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":734,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 167"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p194-735', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 167', 194, 'citizens, that include the following requirements: (1) Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified; and (2) Prior to initiating maintenance or diagnostic activities by personnel who do not have needed access authorizations, clearances or formal access approvals, all', 'vec_doc-14-nist-sp-800-53-p194-735', 0, 142, 'v2.1.0', 'f9a5d4bc72bb9f609cb2ad3bf0b64d9eee47880196b373d6ad86f8b963076877', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 167","subsection":"UNKNOWN","table_id":null,"page":194,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":735,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 167"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p195-736', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 168', 195, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 volatile information storage components within the system are sanitized and all nonvolatile storage media are removed or physically disconnected from the system and secured; and (b) Develop and implement [Assignment: organization-defined alternate controls] in the event a system component cannot be sanitized, removed, or disconnected from the system. Discussion:  Procedures for individuals who lack appropriate security clearances or who are not U.S. citizens are intended to deny visual and electronic access to classified or controlled unclassified information contained on organizational systems. Procedures for the use of maintenance personnel can be documented in security plans for the systems. Related Controls:  MP-6, PL-2.', 'vec_doc-14-nist-sp-800-53-p195-736', 0, 207, 'v2.1.0', '990398ca504e23f7f9ba4a0937ecf79bbbb1254cafce9019a04be918e7ecc9be', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 168","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":736,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 168"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p195-737', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 168', 195, '(2) MAINTENANCE PERSONNEL | SECURITY CLEARANCES FOR CLASSIFIED SYSTEMS Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information possess security clearances and formal access approvals for at least the highest classification level and for compartments of information on the system. Discussion:  Personnel who conduct maintenance on organizational systems may be exposed to classified information during the course of their maintenance activities. To mitigate the inherent risk of such exposure, organizations use maintenance personnel that are cleared (i.e., possess security clearances) to the classification level of the information stored on the system. Related Controls:  PS-3. (3) MAINTENANCE PERSONNEL | CITIZENSHIP REQUIREMENTS FOR CLASSIFIED SYSTEMS Verify that personnel performing maintenance and diagnostic activities on a system processing, storing, or transmitting classified information are U.S. citizens.', 'vec_doc-14-nist-sp-800-53-p195-737', 0, 251, 'v2.1.0', '5b7fb58bd13ab99e78106f9c2827f73f591d9742f86b5fbe88c67d971aec7524', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 168","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":737,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 168"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p195-738', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 168', 195, 'Discussion:  Personnel who conduct maintenance on organizational systems may be exposed to classified information during the course of their maintenance activities. If access to classified information on organizational systems is restricted to U.S. citizens, the same restriction is applied to personnel performing maintenance on those systems. Related Controls:  PS-3. (4) MAINTENANCE PERSONNEL | FOREIGN NATIONALS Ensure that: (a) Foreign nationals with appropriate security clearances are used to conduct maintenance and diagnostic activities on classified systems only when the systems are jointly owned and operated by the United States and foreign allied governments, or owned and operated solely by foreign allied governments; and (b) Approvals, consents, and detailed operational conditions regarding the use of foreign nationals to conduct maintenance and diagnostic activities on classified systems are fully documented within Memoranda of Agreements.', 'vec_doc-14-nist-sp-800-53-p195-738', 0, 241, 'v2.1.0', '97f9898959bc165251452f5b56d68aaa108c7b041624ff7c404b6a67f58bed6c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 168","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":738,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 168"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p195-739', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 168', 195, 'Discussion:  Personnel who conduct maintenance and diagnostic activities on organizational systems may be exposed to classified information. If non-U.S. citizens are permitted to perform maintenance and diagnostics activities on classified systems, then additional vetting is required to ensure agreements and restrictions are not being violated. Related Controls:  PS-3. (5) MAINTENANCE PERSONNEL | NON-SYSTEM MAINTENANCE', 'vec_doc-14-nist-sp-800-53-p195-739', 0, 106, 'v2.1.0', '203a73f3175f34ed301013b63f8a50774a160e91b7e5bb6246973c0153c9516c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 168","subsection":"UNKNOWN","table_id":null,"page":195,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":739,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 168"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p196-740', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 169', 196, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Ensure that non-escorted personnel performing maintenance activities not directly associated with the system but in the physical proximity of the system, have required access authorizations. Discussion:  Personnel who perform maintenance activities in other capacities not directly related to the system include physical plant personnel and custodial personnel. Related Controls:  None. References:  None. MA-6 TIMELY MAINTENANCE Control:  Obtain maintenance support and/or spare parts for [Assignment: organization-defined system components] within [Assignment: organization-defined time period] of failure. Discussion:  Organizations specify the system components that result in increased risk to organizational operations and assets, individuals, other organizations, or the Nation when the functionality provided by those components is not operational.', 'vec_doc-14-nist-sp-800-53-p196-740', 0, 237, 'v2.1.0', '29df7c29047a6a1bc285501bb198d2d020cae0be0f818eca6248adb93d4af611', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 169","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":740,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 169"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p196-741', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 169', 196, 'Organizational actions to obtain maintenance support include having appropriate contracts in place. Related Controls:  CM-8, CP-2, CP-7, RA-7, SA-15, SI-13, SR-2, SR-3, SR-4. Control Enhancements: (1) TIMELY MAINTENANCE | PREVENTIVE MAINTENANCE Perform preventive maintenance on [Assignment: organization-defined system components] at [Assignment: organization-defined time intervals]. Discussion:  Preventive maintenance includes proactive care and the servicing of system components to maintain organizational equipment and facilities in satisfactory operating condition. Such maintenance provides for the systematic inspection, tests, measurements, adjustments, parts replacement, detection, and correction of incipient failures either before they occur or before they develop into major defects. The primary goal of preventive maintenance is to avoid or mitigate the consequences of equipment failures.', 'vec_doc-14-nist-sp-800-53-p196-741', 0, 227, 'v2.1.0', '1e760fb3bd127a0cc1e4f60ca0d5e566b24309a864058154db900d6650b03978', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 169","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":741,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 169"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p196-742', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 169', 196, 'Preventive maintenance is designed to preserve and restore equipment reliability by replacing worn components before they fail. Methods of determining what preventive (or other) failure management policies to apply include original equipment manufacturer recommendations; statistical failure records; expert opinion; maintenance that has already been conducted on similar equipment; requirements of codes, laws, or regulations within a jurisdiction; or measured values and performance indications. Related Controls:  None. (2) TIMELY MAINTENANCE | PREDICTIVE MAINTENANCE Perform predictive maintenance on [Assignment: organization-defined system components] at [Assignment: organization-defined time intervals]. Discussion:  Predictive maintenance evaluates the condition of equipment by performing periodic or continuous (online) equipment condition monitoring.', 'vec_doc-14-nist-sp-800-53-p196-742', 0, 216, 'v2.1.0', 'ad04bcc94898b54e2c4dd18f16a7c44a52f46f0dbf83a8183747bbd1c002aeee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 169","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":742,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 169"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p196-743', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 169', 196, 'The goal of predictive maintenance is to perform maintenance at a scheduled time when the maintenance activity is most cost-effective and before the equipment loses performance within a threshold. The predictive component of predictive maintenance stems from the objective of predicting the future trend of the equipment''s condition. The predictive maintenance approach employs principles of statistical process control to determine at what point in the future maintenance activities will be appropriate. Most predictive maintenance inspections are performed while equipment is in service, thus minimizing disruption of normal system operations. Predictive maintenance can result in substantial cost savings and higher system reliability. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p196-743', 0, 191, 'v2.1.0', 'e23072ed0db53b6fbf2f6086e6b30f0ffdba54a08dbe3f4daf49fd19aa8667c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 169","subsection":"UNKNOWN","table_id":null,"page":196,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":743,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 169"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p197-744', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 170', 197, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (3) TIMELY MAINTENANCE | AUTOMATED SUPPORT FOR PREDICTIVE MAINTENANCE Transfer predictive maintenance data to a maintenance management system using [Assignment: organization-defined automated mechanisms]. Discussion:  A computerized maintenance management system maintains a database of information about the maintenance operations of organizations and automates the processing of equipment condition data to trigger maintenance planning, execution, and reporting. Related Controls:  None. References:  None. MA-7 FIELD MAINTENANCE Control:  Restrict or prohibit field maintenance on [Assignment: organization-defined systems or system components] to [Assignment: organization-defined trusted maintenance facilities]. Discussion:  Field maintenance is the type of maintenance conducted on a system or system component after the system or component has been deployed to a specific site (i.e., operational environment). In certain instances, field maintenance (i.e., local maintenance at the site) may not be executed with the same degree of rigor or with the same quality control checks as depot maintenance. For critical systems designated as such by the organization, it may be necessary to restrict or prohibit field maintenance at the local site and require that such maintenance be conducted in trusted facilities with additional controls. Related Controls:  MA-2, MA-4, MA-5. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p197-744', 0, 380, 'v2.1.0', 'affa5182c7a118b5ed50d169e4807b2a65409c21de7ecad94d43739bfd24b9b0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 170","subsection":"UNKNOWN","table_id":null,"page":197,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":744,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 170"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p198-745', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.10   MEDIA PROTECTION', 198, 'Quick link to Media Protection Summary Table MP-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p198-745', 0, 44, 'v2.1.0', '3996782d3eae146362b095a317c9776d9aba694145a1ad12c15be33b499c09db', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.10   MEDIA PROTECTION","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":745,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.10   MEDIA PROTECTION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p198-746', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 198, 'level] media protection policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p198-746', 0, 76, 'v2.1.0', '586cca6bc3733ccd04398864b18c823881abe2be7ddbfe949f98dc3f803b097a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":746,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p198-747', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the media protection policy and the', 198, 'associated media protection controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the media protection policy and procedures; and c. Review and update the current media protection:', 'vec_doc-14-nist-sp-800-53-p198-747', 0, 65, 'v2.1.0', '33ee39c31cb05773b973efb2f7c09fce1e7507354a3a2d08e9df6aa4e8d7effb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the media protection policy and the","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":747,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the media protection policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p198-748', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 198, 'organization-defined events]. Discussion:  Media protection policy and procedures address the controls in the MP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of media protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to media protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p198-748', 0, 427, 'v2.1.0', '02fa118d7123d7dcf2403f84d4a701269cf18e7794223c0370f9e2a21c87894a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":198,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":748,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p199-749', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 172', 199, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 MP-2 MEDIA ACCESS Control:  Restrict access to [Assignment: organization-defined types of digital and/or non-digital media] to [Assignment: organization-defined personnel or roles]. Discussion:  System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Denying access to patient medical records in a community hospital unless the individuals seeking access to such records are authorized healthcare providers is an example of restricting access to non-digital media. Limiting access to the design specifications stored on compact discs in the media library to individuals on the system development team is an example of restricting access to digital media.', 'vec_doc-14-nist-sp-800-53-p199-749', 0, 243, 'v2.1.0', '22973e7e8f2c7990f7f7f4df26c2a0d5903e18cf7d8dd210c232da7884b8259b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 172","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":749,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 172"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p199-750', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 172', 199, 'Related Controls:  AC-19, AU-9, CP-2, CP-9, CP-10, MA-5, MP-4, MP-6, PE-2, PE-3, SC-12, SC-13, SC-34, SI-12. Control Enhancements: (1) MEDIA ACCESS | AUTOMATED RESTRICTED ACCESS [Withdrawn: Incorporated into MP-4(2).] (2) MEDIA ACCESS | CRYPTOGRAPHIC PROTECTION [Withdrawn: Incorporated into SC-28(1).] References:  [OMB A-130], [FIPS 199], [SP 800-111]. MP-3 MEDIA MARKING Control: a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempt [Assignment: organization-defined types of system media] from marking if the media remain within [Assignment: organization-defined controlled areas]. Discussion:  Security marking refers to the application or use of human-readable security attributes. Digital media includes diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), flash drives, compact discs, and digital versatile discs.', 'vec_doc-14-nist-sp-800-53-p199-750', 0, 242, 'v2.1.0', 'c3707646e93695854477c758f780e75642ad56c3e70a77df2ce5a859571a2c2b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 172","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":750,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 172"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p199-751', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 172', 199, 'Non- digital media includes paper and microfilm. Controlled unclassified information is defined by the National Archives and Records Administration along with the appropriate safeguarding and dissemination requirements for such information and is codified in [32 CFR 2002]. Security markings are generally not required for media that contains information determined by organizations to be in the public domain or to be publicly releasable. Some organizations may require markings for public information indicating that the information is publicly releasable. System media marking reflects applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Related Controls:  AC-16, CP-9, MP-5, PE-22, SI-12. Control Enhancements:  None. References:  [EO 13556], [32 CFR 2002], [FIPS 199]. MP-4 MEDIA STORAGE Control:', 'vec_doc-14-nist-sp-800-53-p199-751', 0, 212, 'v2.1.0', '09f2d2052a370f44f8731041301853be5d2a7cfdd5179fbac0c3088d26dc0803', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 172","subsection":"UNKNOWN","table_id":null,"page":199,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":751,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 172"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p200-752', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 173', 200, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Physically control and securely store [Assignment: organization-defined types of digital and/or non-digital media] within [Assignment: organization-defined controlled areas]; and b. Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures. Discussion:  System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Physically controlling stored media includes conducting inventories, ensuring procedures are in place to allow individuals to check out and return media to the library, and maintaining accountability for stored media.', 'vec_doc-14-nist-sp-800-53-p200-752', 0, 232, 'v2.1.0', '04a1734417dade3cbdcfdfcd8665f0f8fb7339b03cecd44d8b71738d4d692165', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 173","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":752,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 173"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p200-753', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 173', 200, 'Secure storage includes a locked drawer, desk, or cabinet or a controlled media library. The type of media storage is commensurate with the security category or classification of the information on the media. Controlled areas are spaces that provide physical and procedural controls to meet the requirements established for protecting information and systems. Fewer controls may be needed for media that contains information determined to be in the public domain, publicly releasable, or have limited adverse impacts on organizations, operations, or individuals if accessed by other than authorized personnel. In these situations, physical access controls provide adequate protection. Related Controls:  AC-19, CP-2, CP-6, CP-9, CP-10, MP-2, MP-7, PE-3, PL-2, SC-12, SC-13, SC-28, SC-34, SI-12.', 'vec_doc-14-nist-sp-800-53-p200-753', 0, 199, 'v2.1.0', '3b5c6e1c068c28363d056ecfe491a5ed84bb27ae8e063598f7032569dced3d08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 173","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":753,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 173"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p200-754', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 173', 200, 'Control Enhancements: (1) MEDIA STORAGE | CRYPTOGRAPHIC PROTECTION [Withdrawn: Incorporated into SC-28(1).] (2) MEDIA STORAGE | AUTOMATED RESTRICTED ACCESS Restrict access to media storage areas and log access attempts and access granted using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms include keypads, biometric readers, or card readers on the external entries to media storage areas. Related Controls:  AC-3, AU-2, AU-6, AU-9, AU-12, PE-3. References:  [FIPS 199], [SP 800-56A], [SP 800-56B], [SP 800-56C], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-111]. MP-5 MEDIA TRANSPORT Control: a. Protect and control [Assignment: organization-defined types of system media] during transport outside of controlled areas using [Assignment: organization-defined controls]; b. Maintain accountability for system media during transport outside of controlled areas; c. Document activities associated with the transport of system media; and d.', 'vec_doc-14-nist-sp-800-53-p200-754', 0, 248, 'v2.1.0', '8432a9035c3b048f57a4cdc5a50936fd3cdecdcef6e808b7daa1461f9ee8ee06', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 173","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":754,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 173"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p200-755', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 173', 200, 'Restrict the activities associated with the transport of system media to authorized personnel. Discussion:  System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state and magnetic), compact discs, and digital versatile discs. Non-digital media includes microfilm and paper. Controlled areas are spaces for which organizations provide physical or procedural controls to meet requirements established for protecting information and systems. Controls to protect media during transport include cryptography and locked containers. Cryptographic', 'vec_doc-14-nist-sp-800-53-p200-755', 0, 164, 'v2.1.0', 'fa493ad38c863a4ec70430708889ad2f813bc772d4d71cf625ad6d6f9c8fc392', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 173","subsection":"UNKNOWN","table_id":null,"page":200,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":755,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 173"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p201-756', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 174', 201, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 mechanisms can provide confidentiality and integrity protections depending on the mechanisms implemented. Activities associated with media transport include releasing media for transport, ensuring that media enters the appropriate transport processes, and the actual transport. Authorized transport and courier personnel may include individuals external to the organization. Maintaining accountability of media during transport includes restricting transport activities to authorized personnel and tracking and/or obtaining records of transport activities as the media moves through the transportation system to prevent and detect loss, destruction, or tampering. Organizations establish documentation requirements for activities associated with the transport of system media in accordance with organizational assessments of risk.', 'vec_doc-14-nist-sp-800-53-p201-756', 0, 231, 'v2.1.0', '7b87a60d7e6c0c63f0263cd19c2a13622e1573a09cd0f62f944f1bee862c002f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 174","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":756,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 174"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p201-757', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 174', 201, 'Organizations maintain the flexibility to define record-keeping methods for the different types of media transport as part of a system of transport-related records. Related Controls:  AC-7, AC-19, CP-2, CP-9, MP-3, MP-4, PE-16, PL-2, SC-12, SC-13, SC-28, SC-34. Control Enhancements: (1) MEDIA TRANSPORT | PROTECTION OUTSIDE OF CONTROLLED AREAS [Withdrawn: Incorporated into MP-5.] (2) MEDIA TRANSPORT | DOCUMENTATION OF ACTIVITIES [Withdrawn: Incorporated into MP-5.] (3) MEDIA TRANSPORT | CUSTODIANS Employ an identified custodian during transport of system media outside of controlled areas. Discussion:  Identified custodians provide organizations with specific points of contact during the media transport process and facilitate individual accountability. Custodial responsibilities can be transferred from one individual to another if an unambiguous custodian is identified. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p201-757', 0, 227, 'v2.1.0', '009a8c2844991649937db1b899922d99110c90b5aaa6a780bc3148dde77ce056', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 174","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":757,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 174"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p201-758', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 174', 201, '(4) MEDIA TRANSPORT | CRYPTOGRAPHIC PROTECTION [Withdrawn: Incorporated into SC-28(1).] References:  [FIPS 199], [SP 800-60-1], [SP 800-60-2]. MP-6 MEDIA SANITIZATION Control: a. Sanitize [Assignment: organization-defined system media] prior to disposal, release out of organizational control, or release for reuse using [Assignment: organization-defined sanitization techniques and procedures]; and b. Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information. Discussion:   Media sanitization applies to all digital and non-digital system media subject to disposal or reuse, whether or not the media is considered removable. Examples include digital media in scanners, copiers, printers, notebook computers, workstations, network components, mobile devices, and non-digital media (e.g., paper and microfilm).', 'vec_doc-14-nist-sp-800-53-p201-758', 0, 223, 'v2.1.0', '0925d73a3f1650ce32d56266524801f28e75631093ac924dff2ef995cc9ad37c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 174","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":758,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 174"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p201-759', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 174', 201, 'The sanitization process removes information from system media such that the information cannot be retrieved or reconstructed. Sanitization techniques— including clearing, purging, cryptographic erase, de- identification of personally identifiable information, and destruction— prevent the disclosure of information to unauthorized individuals when such media is reused or released for disposal. Organizations determine the appropriate sanitization methods, recognizing that destruction is sometimes necessary when other methods cannot be applied to media requiring sanitization.', 'vec_doc-14-nist-sp-800-53-p201-759', 0, 145, 'v2.1.0', '82690acdb268188c48429f63c0f4b3ca79121b1bac2477f2f30d75c3e97d0bbe', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 174","subsection":"UNKNOWN","table_id":null,"page":201,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":759,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 174"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p202-760', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 175', 202, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Organizations use discretion on the employment of approved sanitization techniques and procedures for media that contains information deemed to be in the public domain or publicly releasable or information deemed to have no adverse impact on organizations or individuals if released for reuse or disposal. Sanitization of non-digital media includes destruction, removing a classified appendix from an otherwise unclassified document, or redacting selected sections or words from a document by obscuring the redacted sections or words in a manner equivalent in effectiveness to removing them from the document. NSA standards and policies control the sanitization process for media that contains classified information. NARA policies control the sanitization process for controlled unclassified information. Related Controls:  AC-3, AC-7, AU-11, MA-2, MA-3, MA-4, MA-5, PM-22, SI-12, SI-18, SI-19, SR-11.', 'vec_doc-14-nist-sp-800-53-p202-760', 0, 249, 'v2.1.0', 'ed723fbd63216df3b76fea32c4d1a7dd1d404e743a5d41bb8594b73f1a2d4d7f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 175","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":760,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 175"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p202-761', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 175', 202, 'Control Enhancements: (1) MEDIA SANITIZATION | REVIEW, APPROVE, TRACK, DOCUMENT, AND VERIFY Review, approve, track, document, and verify media sanitization and disposal actions. Discussion:  Organizations review and approve media to be sanitized to ensure compliance with records retention policies. Tracking and documenting actions include listing personnel who reviewed and approved sanitization and disposal actions, types of media sanitized, files stored on the media, sanitization methods used, date and time of the sanitization actions, personnel who performed the sanitization, verification actions taken and personnel who performed the verification, and the disposal actions taken. Organizations verify that the sanitization of the media was effective prior to disposal. Related Controls:  None. (2) MEDIA SANITIZATION | EQUIPMENT TESTING Test sanitization equipment and procedures [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved.', 'vec_doc-14-nist-sp-800-53-p202-761', 0, 249, 'v2.1.0', '8c1f0681bc1894a6dda56c6e4b98ee6cdeac2e288dcc75a6e58c0e69060d847c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 175","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":761,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 175"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p202-762', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 175', 202, 'Discussion:  Testing of sanitization equipment and procedures may be conducted by qualified and authorized external entities, including federal agencies or external service providers. Related Controls:  None. (3) MEDIA SANITIZATION | NONDESTRUCTIVE TECHNIQUES Apply nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the system under the following circumstances: [Assignment: organization-defined circumstances requiring sanitization of portable storage devices]. Discussion:  Portable storage devices include external or removable hard disk drives (e.g., solid state, magnetic), optical discs, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks. Portable storage devices can be obtained from untrustworthy sources and contain malicious code that can be inserted into or transferred to organizational systems through USB ports or other entry portals.', 'vec_doc-14-nist-sp-800-53-p202-762', 0, 240, 'v2.1.0', '1545bf2297150f477c571ac3991387e29bab28ddee698a3b94372655afc460c3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 175","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":762,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 175"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p202-763', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 175', 202, 'While scanning storage devices is recommended, sanitization provides additional assurance that such devices are free of malicious code. Organizations consider nondestructive sanitization of portable storage devices when the devices are purchased from manufacturers or vendors prior to initial use or when organizations cannot maintain a positive chain of custody for the devices. Related Controls:  None. (4) MEDIA SANITIZATION | CONTROLLED UNCLASSIFIED INFORMATION [Withdrawn: Incorporated into MP-6.] (5) MEDIA SANITIZATION | CLASSIFIED INFORMATION', 'vec_doc-14-nist-sp-800-53-p202-763', 0, 138, 'v2.1.0', '022322e95cfc971caafaf20c631e9bd0b067636324c995e6aaa020007ae1f074', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 175","subsection":"UNKNOWN","table_id":null,"page":202,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":763,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 175"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p203-764', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 176', 203, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Incorporated into MP-6.] (6) MEDIA SANITIZATION | MEDIA DESTRUCTION [Withdrawn: Incorporated into MP-6.] (7) MEDIA SANITIZATION | DUAL AUTHORIZATION Enforce dual authorization for the sanitization of [Assignment: organization-defined system media]. Discussion:  Organizations employ dual authorization to help ensure that system media sanitization cannot occur unless two technically qualified individuals conduct the designated task. Individuals who sanitize system media possess sufficient skills and expertise to determine if the proposed sanitization reflects applicable federal and organizational standards, policies, and procedures. Dual authorization also helps to ensure that sanitization occurs as intended, protecting against errors and false claims of having performed the sanitization actions. Dual authorization may also be known as two-person control.', 'vec_doc-14-nist-sp-800-53-p203-764', 0, 243, 'v2.1.0', 'a7914412c75bfaa8a2e19c8939d1f3538c0de6718f3ab6d44baad4dcb1ca29d9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 176","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":764,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 176"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p203-765', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 176', 203, 'To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals. Related Controls:  AC-3, MP-2. (8) MEDIA SANITIZATION | REMOTE PURGING OR WIPING OF INFORMATION Provide the capability to purge or wipe information from [Assignment: organization- defined systems or system components] [Selection: remotely; under the following conditions: [Assignment: organization-defined conditions]]. Discussion:  Remote purging or wiping of information protects information on organizational systems and system components if systems or components are obtained by unauthorized individuals. Remote purge or wipe commands require strong authentication to help mitigate the risk of unauthorized individuals purging or wiping the system, component, or device. The purge or wipe function can be implemented in a variety of ways, including by overwriting data or information multiple times or by destroying the key necessary to decrypt encrypted data. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p203-765', 0, 251, 'v2.1.0', '16ee931d51233175427f489e6007360635956d487086aec481753f3861eeb3d2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 176","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":765,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 176"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p203-766', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 176', 203, 'References:  [32 CFR 2002], [OMB A-130], [NARA CUI], [FIPS 199], [SP 800-60-1], [SP 800-60-2], [SP 800-88], [SP 800-124], [IR 8023], [NSA MEDIA]. MP-7 MEDIA USE Control: a. [Selection: Restrict; Prohibit] the use of [Assignment: organization-defined types of system media] on [Assignment: organization-defined systems or system components] using [Assignment: organization-defined controls]; and b. Prohibit the use of portable storage devices in organizational systems when such devices have no identifiable owner. Discussion:  System media includes both digital and non-digital media. Digital media includes diskettes, magnetic tapes, flash drives, compact discs, digital versatile discs, and removable hard disk drives. Non-digital media includes paper and microfilm. Media use protections also apply to mobile devices with information storage capabilities.', 'vec_doc-14-nist-sp-800-53-p203-766', 0, 215, 'v2.1.0', '2e297ee3e333867e421a2bafe0911e66caa55acb9bfdaf04d9d4d9beefe1c64b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 176","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":766,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 176"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p203-767', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 176', 203, 'In contrast to MP-2, which restricts user access to media, MP-7 restricts the use of certain types of media on systems, for example, restricting or prohibiting the use of flash drives or external hard disk drives. Organizations use technical and nontechnical controls to restrict the use of system media. Organizations may restrict the use of portable storage devices, for example, by using physical cages on workstations to prohibit access to certain external ports or disabling or removing the ability to insert, read, or', 'vec_doc-14-nist-sp-800-53-p203-767', 0, 131, 'v2.1.0', '87510a2781c47ebb63c0df194880179be5b01600e32f1f25a1a84389a7d934a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 176","subsection":"UNKNOWN","table_id":null,"page":203,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":767,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 176"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p204-768', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 177', 204, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 write to such devices. Organizations may also limit the use of portable storage devices to only approved devices, including devices provided by the organization, devices provided by other approved organizations, and devices that are not personally owned. Finally, organizations may restrict the use of portable storage devices based on the type of device, such as by prohibiting the use of writeable, portable storage devices and implementing this restriction by disabling or removing the capability to write to such devices. Requiring identifiable owners for storage devices reduces the risk of using such devices by allowing organizations to assign responsibility for addressing known vulnerabilities in the devices. Related Controls:  AC-19, AC-20, PL-4, PM-12, SC-34, SC-41 .', 'vec_doc-14-nist-sp-800-53-p204-768', 0, 218, 'v2.1.0', '08b2a22e50aa0b79c1b8ee9a09912fa4c94e8fc47ccc275d6d508d930b2c51f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 177","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":768,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 177"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p204-769', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 177', 204, 'Control Enhancements: (1) MEDIA USE | PROHIBIT USE WITHOUT OWNER [Withdrawn: Incorporated into MP-7.] (2) MEDIA USE | PROHIBIT USE OF SANITIZATION-RESISTANT MEDIA Prohibit the use of sanitization-resistant media in organizational systems. Discussion:  Sanitization resistance refers to how resistant media are to non-destructive sanitization techniques with respect to the capability to purge information from media. Certain types of media do not support sanitization commands, or if supported, the interfaces are not supported in a standardized way across these devices. Sanitization-resistant media includes compact flash, embedded flash on boards and devices, solid state drives, and USB removable media. Related Controls:  MP-6. References:  [FIPS 199], [SP 800-111]. MP-8 MEDIA DOWNGRADING Control: a.', 'vec_doc-14-nist-sp-800-53-p204-769', 0, 202, 'v2.1.0', '9542d118628a056ee4e631ae6a556b795e73df49017d6c524d29ecaa13b783d0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 177","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":769,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 177"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p204-770', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 177', 204, 'Establish [Assignment: organization-defined system media downgrading process] that includes employing downgrading mechanisms with strength and integrity commensurate with the security category or classification of the information; b. Verify that the system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information; c. Identify [Assignment: organization-defined system media requiring downgrading]; and d. Downgrade the identified system media using the established process. Discussion:  Media downgrading applies to digital and non-digital media subject to release outside of the organization, whether the media is considered removable or not.', 'vec_doc-14-nist-sp-800-53-p204-770', 0, 201, 'v2.1.0', '281b019995ebc8af9a02b8ce97e2a58b97c27fc9017d5b80cbe77c400527e329', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 177","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":770,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 177"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p204-771', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 177', 204, 'When applied to system media, the downgrading process removes information from the media, typically by security category or classification level, such that the information cannot be retrieved or reconstructed. Downgrading of media includes redacting information to enable wider release and distribution. Downgrading ensures that empty space on the media is devoid of information. Related Controls:  None. Control Enhancements: (1) MEDIA DOWNGRADING | DOCUMENTATION OF PROCESS Document system media downgrading actions.', 'vec_doc-14-nist-sp-800-53-p204-771', 0, 130, 'v2.1.0', '46027ea52582f2fd8bd5c39907c9416bbd58e1ce4d8ec1db5d8889389b832b24', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 177","subsection":"UNKNOWN","table_id":null,"page":204,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":771,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 177"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p205-772', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 178', 205, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Organizations can document the media downgrading process by providing information, such as the downgrading technique employed, the identification number of the downgraded media, and the identity of the individual that authorized and/or performed the downgrading action. Related Controls:  None. (2) MEDIA DOWNGRADING | EQUIPMENT TESTING Test downgrading equipment and procedures [Assignment: organization-defined frequency] to ensure that downgrading actions are being achieved. Discussion:  None. Related Controls:  None. (3) MEDIA DOWNGRADING | CONTROLLED UNCLASSIFIED INFORMATION Downgrade system media containing controlled unclassified information prior to public release. Discussion:  The downgrading of controlled unclassified information uses approved sanitization tools, techniques, and procedures. Related Controls:  None. (4) MEDIA DOWNGRADING | CLASSIFIED INFORMATION Downgrade system media containing classified information prior to release to individuals without required access authorizations. Discussion:  Downgrading of classified information uses approved sanitization tools, techniques, and procedures to transfer information confirmed to be unclassified from classified systems to unclassified media. Related Controls:  None. References:  [32 CFR 2002], [NSA MEDIA].', 'vec_doc-14-nist-sp-800-53-p205-772', 0, 348, 'v2.1.0', '28ae1684660730e0cf7facf694f968055fee8a839aeb3e4024bd8dde1a559332', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 178","subsection":"UNKNOWN","table_id":null,"page":205,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":772,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 178"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p206-773', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.11   PHYSICAL AND ENVIRONMENTAL PROTECTION', 206, 'Quick link to Physical and Environmental Protection Summary Table PE-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p206-773', 0, 50, 'v2.1.0', '6cd89b78c1c981af9ed62af89caa981fd572427829edfeb99c23318b69fb4b00', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.11   PHYSICAL AND ENVIRONMENTAL PROTECTION","subsection":"UNKNOWN","table_id":null,"page":206,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":773,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.11   PHYSICAL AND ENVIRONMENTAL PROTECTION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p206-774', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 206, 'level] physical and environmental protection policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p206-774', 0, 81, 'v2.1.0', '00e0339715edffb9a7aca5b7fb118784c78ad69f249c1ce6afac7a70e3654778', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":206,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":774,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p206-775', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the physical and environmental', 206, 'protection policy and the associated physical and environmental protection controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures; and c. Review and update the current physical and environmental protection:', 'vec_doc-14-nist-sp-800-53-p206-775', 0, 87, 'v2.1.0', '331f418ad8048a9aab27dd8430afc0a824436a94ba7350c73dddc56c2091395e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the physical and environmental","subsection":"UNKNOWN","table_id":null,"page":206,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":775,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the physical and environmental"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p206-776', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 206, 'organization-defined events]. Discussion:  Physical and environmental protection policy and procedures address the controls in the PE family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of physical and environmental protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to physical and environmental protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  AT-3, PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p206-776', 0, 441, 'v2.1.0', '3ad33ca51ad1e3fc77b66c0357e32ccf517598a9ad980c67b6ca3a2c1c76d898', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":206,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":776,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p207-777', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 180', 207, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PE-2 PHYSICAL ACCESS AUTHORIZATIONS Control: a. Develop, approve, and maintain a list of individuals with authorized access to the facility where the system resides; b. Issue authorization credentials for facility access; c. Review the access list detailing authorized facility access by individuals [Assignment: organization-defined frequency]; and d. Remove individuals from the facility access list when access is no longer required. Discussion:  Physical access authorizations apply to employees and visitors. Individuals with permanent physical access authorization credentials are not considered visitors. Authorization credentials include ID badges, identification cards, and smart cards. Organizations determine the strength of authorization credentials needed consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'vec_doc-14-nist-sp-800-53-p207-777', 0, 244, 'v2.1.0', 'a861c196d99deeb5efec4b8831b3549baa5f4ce40642ea41f74688f9f49aedc9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 180","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":777,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 180"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p207-778', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 180', 207, 'Physical access authorizations may not be necessary to access certain areas within facilities that are designated as publicly accessible. Related Controls:  AT-3, AU-9, IA-4, MA-5, MP-2, PE-3, PE-4, PE-5, PE-8, PM-12, PS-3, PS-4, PS-5, PS-6. Control Enhancements: (1) PHYSICAL ACCESS AUTHORIZATIONS | ACCESS BY POSITION OR ROLE Authorize physical access to the facility where the system resides based on position or role. Discussion:  Role-based facility access includes access by authorized permanent and regular/routine maintenance personnel, duty officers, and emergency medical staff. Related Controls:  AC-2, AC-3, AC-6. (2) PHYSICAL ACCESS AUTHORIZATIONS | TWO FORMS OF IDENTIFICATION Require two forms of identification from the following forms of identification for visitor access to the facility where the system resides: [Assignment: organization-defined list of acceptable forms of identification].', 'vec_doc-14-nist-sp-800-53-p207-778', 0, 228, 'v2.1.0', '319f7b1129073a8a74789ad9afe3837a2cfe9299d20fe286ba314e152ebab349', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 180","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":778,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 180"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p207-779', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 180', 207, 'Discussion:  Acceptable forms of identification include passports, REAL ID-compliant drivers’ licenses, and Personal Identity Verification (PIV) cards. For gaining access to facilities using automated mechanisms, organizations may use PIV cards, key cards, PINs, and biometrics. Related Controls:  IA-2, IA-4, IA-5. (3) PHYSICAL ACCESS AUTHORIZATIONS | RESTRICT UNESCORTED ACCESS Restrict unescorted access to the facility where the system resides to personnel with [Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization- defined physical access authorizations]].', 'vec_doc-14-nist-sp-800-53-p207-779', 0, 193, 'v2.1.0', '0ee302c99249a8861aaa76eeaa0a91fee7ab28ea9e5880ed8e2d8a0075ec618e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 180","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":779,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 180"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p207-780', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 180', 207, 'Discussion:  Individuals without required security clearances, access approvals, or need to know are escorted by individuals with appropriate physical access authorizations to ensure that information is not exposed or otherwise compromised. Related Controls:  PS-2, PS-6. References:  [FIPS 201-2], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4].', 'vec_doc-14-nist-sp-800-53-p207-780', 0, 86, 'v2.1.0', 'e05445c7d9e2df262e143cf98fa32226803e51c31a98ad2c20b95686651ab334', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 180","subsection":"UNKNOWN","table_id":null,"page":207,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":780,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 180"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p208-781', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 181', 208, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PE-3 PHYSICAL ACCESS CONTROL Control: a. Enforce physical access authorizations at [Assignment: organization-defined entry and exit points to the facility where the system resides] by:', 'vec_doc-14-nist-sp-800-53-p208-781', 0, 69, 'v2.1.0', '05c94553d6048a05cfa3a436c89260df756783bba399522c1f1fe34b1d2de630', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 181","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":781,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 181"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p208-782', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:', 208, 'organization-defined physical access control systems or devices]; guards]; b. Maintain physical access audit logs for [Assignment: organization-defined entry or exit points]; c. Control access to areas within the facility designated as publicly accessible by implementing the following controls: [Assignment: organization-defined physical access controls]; d. Escort visitors and control visitor activity [Assignment: organization-defined circumstances requiring visitor escorts and control of visitor activity]; e. Secure keys, combinations, and other physical access devices; f. Inventory [Assignment: organization-defined physical access devices] every [Assignment: organization-defined frequency]; and g. Change combinations and keys [Assignment: organization-defined frequency] and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated. Discussion:  Physical access control applies to employees and visitors.', 'vec_doc-14-nist-sp-800-53-p208-782', 0, 250, 'v2.1.0', 'eb8271bd0a8eaaf8a584cd4a3903c00a876613ab01bc74756fd2fdde4f155a13', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":782,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p208-783', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:', 208, 'Individuals with permanent physical access authorizations are not considered visitors. Physical access controls for publicly accessible areas may include physical access control logs/records, guards, or physical access devices and barriers to prevent movement from publicly accessible areas to non-public areas. Organizations determine the types of guards needed, including professional security staff, system users, or administrative staff. Physical access devices include keys, locks, combinations, biometric readers, and card readers. Physical access control systems comply with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Organizations have flexibility in the types of audit logs employed. Audit logs can be procedural, automated, or some combination thereof. Physical access points can include facility access points, interior access points to systems that require supplemental access controls, or both.', 'vec_doc-14-nist-sp-800-53-p208-783', 0, 241, 'v2.1.0', '722b7176ff94bac4e9d17bd8a347097610bca876534d4cee3ef101642d148c23', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":783,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p208-784', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:', 208, 'Components of systems may be in areas designated as publicly accessible with organizations controlling access to the components. Related Controls:  AT-3, AU-2, AU-6, AU-9, AU-13, CP-10, IA-3, IA-8, MA-5, MP-2, MP-4, PE-2, PE- 4, PE-5, PE-8, PS-2, PS-3, PS-6, PS-7, RA-3, SC-28, SI-4, SR-3. Control Enhancements: (1) PHYSICAL ACCESS CONTROL | SYSTEM ACCESS Enforce physical access authorizations to the system in addition to the physical access controls for the facility at [Assignment: organization-defined physical spaces containing one or more components of the system]. Discussion:  Control of physical access to the system provides additional physical security for those areas within facilities where there is a concentration of system components. Related Controls:  None. (2) PHYSICAL ACCESS CONTROL | FACILITY AND SYSTEMS', 'vec_doc-14-nist-sp-800-53-p208-784', 0, 207, 'v2.1.0', 'e708c039fe3f18fd4f21aac1b345528a89ffc96964d9ff124af70bb71e1df9f6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:","subsection":"UNKNOWN","table_id":null,"page":208,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":784,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Controlling ingress and egress to the facility using [Selection (one or more): [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p209-785', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 182', 209, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Perform security checks [Assignment: organization-defined frequency] at the physical perimeter of the facility or system for exfiltration of information or removal of system components. Discussion:  Organizations determine the extent, frequency, and/or randomness of security checks to adequately mitigate risk associated with exfiltration. Related Controls:  AC-4, SC-7. (3) PHYSICAL ACCESS CONTROL | CONTINUOUS GUARDS Employ guards to control [Assignment: organization-defined physical access points] to the facility where the system resides 24 hours per day, 7 days per week. Discussion:  Employing guards at selected physical access points to the facility provides a more rapid response capability for organizations. Guards also provide the opportunity for human surveillance in areas of the facility not covered by video surveillance. Related Controls:  CP-6, CP-7, PE-6.', 'vec_doc-14-nist-sp-800-53-p209-785', 0, 242, 'v2.1.0', 'a6354cccdfb4d3ee1e2e2581085db3f22da87b5f7cf054063482ae8005c9148f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 182","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":785,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 182"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p209-786', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 182', 209, '(4) PHYSICAL ACCESS CONTROL | LOCKABLE CASINGS Use lockable physical casings to protect [Assignment: organization-defined system components] from unauthorized physical access. Discussion:  The greatest risk from the use of portable devices— such as smart phones, tablets, and notebook computers— is theft. Organizations can employ lockable, physical casings to reduce or eliminate the risk of equipment theft. Such casings come in a variety of sizes, from units that protect a single notebook computer to full cabinets that can protect multiple servers, computers, and peripherals. Lockable physical casings can be used in conjunction with cable locks or lockdown plates to prevent the theft of the locked casing containing the computer equipment. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p209-786', 0, 193, 'v2.1.0', 'c532a6d88f0377638580c2c2d821b0d862b116780958ef6655691f1bba76db2d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 182","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":786,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 182"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p209-787', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 182', 209, '(5) PHYSICAL ACCESS CONTROL | TAMPER PROTECTION Employ [Assignment: organization-defined anti-tamper technologies] to [Selection (one or more): detect; prevent] physical tampering or alteration of [Assignment: organization- defined hardware components] within the system. Discussion:  Organizations can implement tamper detection and prevention at selected hardware components or implement tamper detection at some components and tamper prevention at other components. Detection and prevention activities can employ many types of anti-tamper technologies, including tamper-detection seals and anti-tamper coatings. Anti-tamper programs help to detect hardware alterations through counterfeiting and other supply chain-related risks. Related Controls:  SA-16, SR-9, SR-11. (6) PHYSICAL ACCESS CONTROL | FACILITY PENETRATION TESTING [Withdrawn: Incorporated into CA-8.] (7) PHYSICAL ACCESS CONTROL | PHYSICAL BARRIERS Limit access using physical barriers.', 'vec_doc-14-nist-sp-800-53-p209-787', 0, 239, 'v2.1.0', 'd89afde842b5c848644cae0df380e0e35f655ceedd3bbe76da12a5c2224ba810', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 182","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":787,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 182"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p209-788', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 182', 209, 'Discussion:  Physical barriers include bollards, concrete slabs, jersey walls, and hydraulic active vehicle barriers. Related Controls:  None. (8) PHYSICAL ACCESS CONTROL | ACCESS CONTROL VESTIBULES Employ access control vestibules at [Assignment: organization-defined locations within the facility].', 'vec_doc-14-nist-sp-800-53-p209-788', 0, 75, 'v2.1.0', 'e20d27029b6f01f96d620040e94a9081708878f53846e33d7692908ef32a9aaa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 182","subsection":"UNKNOWN","table_id":null,"page":209,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":788,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 182"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p210-789', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 183', 210, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  An access control vestibule is part of a physical access control system that typically provides a space between two sets of interlocking doors. Vestibules are designed to prevent unauthorized individuals from following authorized individuals into facilities with controlled access. This activity, also known as piggybacking or tailgating, results in unauthorized access to the facility. Interlocking door controllers can be used to limit the number of individuals who enter controlled access points and to provide containment areas while authorization for physical access is verified. Interlocking door controllers can be fully automated (i.e., controlling the opening and closing of the doors) or partially automated (i.e., using security guards to control the number of individuals entering the containment area). Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p210-789', 0, 237, 'v2.1.0', '8b3a3650fb9f108dc6ae06f03cfcfd9cf3df5afa32ece00d768a0b6d4fa240dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 183","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":789,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 183"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p210-790', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 183', 210, 'References:  [FIPS 201-2], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4], [SP 800-116]. PE-4 ACCESS CONTROL FOR TRANSMISSION Control:  Control physical access to [Assignment: organization-defined system distribution and transmission lines] within organizational facilities using [Assignment: organization-defined security controls]. Discussion:  Security controls applied to system distribution and transmission lines prevent accidental damage, disruption, and physical tampering. Such controls may also be necessary to prevent eavesdropping or modification of unencrypted transmissions. Security controls used to control physical access to system distribution and transmission lines include disconnected or locked spare jacks, locked wiring closets, protection of cabling by conduit or cable trays, and wiretapping sensors. Related Controls:  AT-3, IA-4, MP-2, MP-4, PE-2, PE-3, PE-5, PE-9, SC-7, SC-8. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p210-790', 0, 238, 'v2.1.0', '9634c46193e5c40832b493ce856da1a0f448f2d613205a1f1f0912cecff5ae32', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 183","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":790,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 183"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p210-791', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 183', 210, 'PE-5 ACCESS CONTROL FOR OUTPUT DEVICES Control:  Control physical access to output from [Assignment: organization-defined output devices] to prevent unauthorized individuals from obtaining the output. Discussion:  Controlling physical access to output devices includes placing output devices in locked rooms or other secured areas with keypad or card reader access controls and allowing access to authorized individuals only, placing output devices in locations that can be monitored by personnel, installing monitor or screen filters, and using headphones. Examples of output devices include monitors, printers, scanners, audio devices, facsimile machines, and copiers. Related Controls:  PE-2, PE-3, PE-4, PE-18. Control Enhancements: (1) ACCESS CONTROL FOR OUTPUT DEVICES | ACCESS TO OUTPUT BY AUTHORIZED INDIVIDUALS [Withdrawn: Incorporated into PE-5.] (2) ACCESS CONTROL FOR OUTPUT DEVICES | LINK TO INDIVIDUAL IDENTITY Link individual identity to receipt of output from output devices.', 'vec_doc-14-nist-sp-800-53-p210-791', 0, 248, 'v2.1.0', 'd22eccb0ac9901653c40cdaa6f99e7fd28a58b378af5b5325026c7d862fb37e9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 183","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":791,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 183"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p210-792', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 183', 210, 'Discussion:  Methods for linking individual identity to the receipt of output from output devices include installing security functionality on facsimile machines, copiers, and printers. Such functionality allows organizations to implement authentication on output devices prior to the release of output to individuals.', 'vec_doc-14-nist-sp-800-53-p210-792', 0, 80, 'v2.1.0', '99d25c9293a5282267daf368f523a98e05f73303afdbdadf7aaf8396fa70dbe0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 183","subsection":"UNKNOWN","table_id":null,"page":210,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":792,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 183"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p211-793', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 184', 211, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (3) ACCESS CONTROL FOR OUTPUT DEVICES | MARKING OUTPUT DEVICES [Withdrawn: Incorporated into PE-22.] References:  [IR 8023]. PE-6 MONITORING PHYSICAL ACCESS Control: a. Monitor physical access to the facility where the system resides to detect and respond to physical security incidents; b. Review physical access logs [Assignment: organization-defined frequency] and upon occurrence of [Assignment: organization-defined events or potential indications of events]; and c. Coordinate results of reviews and investigations with the organizational incident response capability. Discussion:  Physical access monitoring includes publicly accessible areas within organizational facilities. Examples of physical access monitoring include the employment of guards, video surveillance equipment (i.e., cameras), and sensor devices.', 'vec_doc-14-nist-sp-800-53-p211-793', 0, 235, 'v2.1.0', 'f63b26a58d50c2fd0b04b83f394fb1205454499a2c47bdd4929cc024b52b59e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 184","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":793,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 184"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p211-794', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 184', 211, 'Reviewing physical access logs can help identify suspicious activity, anomalous events, or potential threats. The reviews can be supported by audit logging controls, such as AU-2, if the access logs are part of an automated system. Organizational incident response capabilities include investigations of physical security incidents and responses to the incidents. Incidents include security violations or suspicious physical access activities. Suspicious physical access activities include accesses outside of normal work hours, repeated accesses to areas not normally accessed, accesses for unusual lengths of time, and out-of-sequence accesses. Related Controls:  AU-2, AU-6, AU-9, AU-12, CA-7, CP-10, IR-4, IR-8. Control Enhancements: (1) MONITORING PHYSICAL ACCESS | INTRUSION ALARMS AND SURVEILLANCE EQUIPMENT Monitor physical access to the facility where the system resides using physical intrusion alarms and surveillance equipment.', 'vec_doc-14-nist-sp-800-53-p211-794', 0, 235, 'v2.1.0', 'f67db62c94883eee9d3a0f1e0a96a6af26f4d7d229ca8284521117fdefd51522', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 184","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":794,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 184"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p211-795', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 184', 211, 'Discussion:  Physical intrusion alarms can be employed to alert security personnel when unauthorized access to the facility is attempted. Alarm systems work in conjunction with physical barriers, physical access control systems, and security guards by triggering a response when these other forms of security have been compromised or breached. Physical intrusion alarms can include different types of sensor devices, such as motion sensors, contact sensors, and broken glass sensors. Surveillance equipment includes video cameras installed at strategic locations throughout the facility. Related Controls:  None. (2) MONITORING PHYSICAL ACCESS | AUTOMATED INTRUSION RECOGNITION AND RESPONSES Recognize [Assignment: organization-defined classes or types of intrusions] and initiate [Assignment: organization-defined response actions] using [Assignment: organization- defined automated mechanisms].', 'vec_doc-14-nist-sp-800-53-p211-795', 0, 224, 'v2.1.0', '5a41afb7bb1b773b55e39219aea4dc60f72fd8cf022089c74f2b9eab5796513e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 184","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":795,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 184"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p211-796', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 184', 211, 'Discussion:  Response actions can include notifying selected organizational personnel or law enforcement personnel. Automated mechanisms implemented to initiate response actions include system alert notifications, email and text messages, and activating door locking mechanisms. Physical access monitoring can be coordinated with intrusion detection', 'vec_doc-14-nist-sp-800-53-p211-796', 0, 88, 'v2.1.0', '41799e9e070331f9d1bfccee892f18c9148018c6d7dc82a2c3f720ce030e8b7a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 184","subsection":"UNKNOWN","table_id":null,"page":211,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":796,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 184"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p212-797', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 185', 212, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 systems and system monitoring capabilities to provide integrated threat coverage for the organization. Related Controls:  SI-4. (3) MONITORING PHYSICAL ACCESS | VIDEO SURVEILLANCE (a) Employ video surveillance of [Assignment: organization-defined operational areas]; (b) Review video recordings [Assignment: organization-defined frequency]; and (c) Retain video recordings for [Assignment: organization-defined time period]. Discussion:  Video surveillance focuses on recording activity in specified areas for the purposes of subsequent review, if circumstances so warrant. Video recordings are typically reviewed to detect anomalous events or incidents. Monitoring the surveillance video is not required, although organizations may choose to do so. There may be legal considerations when performing and retaining video surveillance, especially if such surveillance is in a public location. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p212-797', 0, 252, 'v2.1.0', 'eadd1e035210596fd1f1941e09c2fb4540d434e25fb8861fbc6f22adb84e8960', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 185","subsection":"UNKNOWN","table_id":null,"page":212,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":797,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 185"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p212-798', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 185', 212, '(4) MONITORING PHYSICAL ACCESS | MONITORING PHYSICAL ACCESS TO SYSTEMS Monitor physical access to the system in addition to the physical access monitoring of the facility at [Assignment: organization-defined physical spaces containing one or more components of the system]. Discussion:  Monitoring physical access to systems provides additional monitoring for those areas within facilities where there is a concentration of system components, including server rooms, media storage areas, and communications centers. Physical access monitoring can be coordinated with intrusion detection systems and system monitoring capabilities to provide comprehensive and integrated threat coverage for the organization. Related Controls:  None. References:  None. PE-7 VISITOR CONTROL [Withdrawn: Incorporated into PE-2 and PE-3.] PE-8 VISITOR ACCESS RECORDS Control: a. Maintain visitor access records to the facility where the system resides for [Assignment: organization-defined time period]; b.', 'vec_doc-14-nist-sp-800-53-p212-798', 0, 247, 'v2.1.0', '12087aacef16d2590ca8b00d09dc7aa0564c8c6f667c996957e819d640fe7679', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 185","subsection":"UNKNOWN","table_id":null,"page":212,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":798,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 185"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p212-799', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 185', 212, 'Review visitor access records [Assignment: organization-defined frequency]; and c. Report anomalies in visitor access records to [Assignment: organization-defined personnel]. Discussion:  Visitor access records include the names and organizations of individuals visiting, visitor signatures, forms of identification, dates of access, entry and departure times, purpose of visits, and the names and organizations of individuals visited. Access record reviews determine if access authorizations are current and are still required to support organizational mission and business functions. Access records are not required for publicly accessible areas. Related Controls:  PE-2, PE-3, PE-6. Control Enhancements: (1) VISITOR ACCESS RECORDS | AUTOMATED RECORDS MAINTENANCE AND REVIEW', 'vec_doc-14-nist-sp-800-53-p212-799', 0, 195, 'v2.1.0', 'f7ca985b673d728268084e1f7548a14ce7e09767117bbddade29120b3848ee53', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 185","subsection":"UNKNOWN","table_id":null,"page":212,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":799,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 185"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p213-800', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 186', 213, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Maintain and review visitor access records using [Assignment: organization-defined automated mechanisms]. Discussion:  Visitor access records may be stored and maintained in a database management system that is accessible by organizational personnel. Automated access to such records facilitates record reviews on a regular basis to determine if access authorizations are current and still required to support organizational mission and business functions. Related Controls:  None. (2) VISITOR ACCESS RECORDS | PHYSICAL ACCESS RECORDS [Withdrawn: Incorporated into PE-2.] (3) VISITOR ACCESS RECORDS | LIMIT PERSONALLY IDENTIFIABLE INFORMATION ELEMENTS Limit personally identifiable information contained in visitor access records to the following elements identified in the privacy risk assessment: [Assignment: organization- defined elements].', 'vec_doc-14-nist-sp-800-53-p213-800', 0, 234, 'v2.1.0', '66e0862406598ce18b3eecdc59d2b696b5dfd5c9d34393062fc51b0a374d5689', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 186","subsection":"UNKNOWN","table_id":null,"page":213,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":800,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 186"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p213-801', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 186', 213, 'Discussion:  Organizations may have requirements that specify the contents of visitor access records. Limiting personally identifiable information in visitor access records when such information is not needed for operational purposes helps reduce the level of privacy risk created by a system. Related Controls:  RA-3, SA-8. References:  None. PE-9 POWER EQUIPMENT AND CABLING Control:  Protect power equipment and power cabling for the system from damage and destruction. Discussion:  Organizations determine the types of protection necessary for the power equipment and cabling employed at different locations that are both internal and external to organizational facilities and environments of operation. Types of power equipment and cabling include internal cabling and uninterruptable power sources in offices or data centers, generators and power cabling outside of buildings, and power sources for self-contained components such as satellites, vehicles, and other deployable systems.', 'vec_doc-14-nist-sp-800-53-p213-801', 0, 248, 'v2.1.0', '7a7fe51d0fcdbec124cf679a6e4f1d0eb7c2ee37707a46eff140ad709bb47eae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 186","subsection":"UNKNOWN","table_id":null,"page":213,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":801,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 186"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p213-802', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 186', 213, 'Related Controls:  PE-4. Control Enhancements: (1) POWER EQUIPMENT AND CABLING | REDUNDANT CABLING Employ redundant power cabling paths that are physically separated by [Assignment: organization-defined distance]. Discussion:  Physically separate and redundant power cables ensure that power continues to flow in the event that one of the cables is cut or otherwise damaged. Related Controls:  None. (2) POWER EQUIPMENT AND CABLING | AUTOMATIC VOLTAGE CONTROLS Employ automatic voltage controls for [Assignment: organization-defined critical system components]. Discussion:  Automatic voltage controls can monitor and control voltage. Such controls include voltage regulators, voltage conditioners, and voltage stabilizers. Related Controls:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p213-802', 0, 192, 'v2.1.0', '8902592e9480f16ee0cec014396a58d4b1cc1a6091a39d126d3c501d490ee74e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 186","subsection":"UNKNOWN","table_id":null,"page":213,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":802,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 186"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p214-803', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 187', 214, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PE-10 EMERGENCY SHUTOFF Control: a. Provide the capability of shutting off power to [Assignment: organization-defined system or individual system components] in emergency situations; b. Place emergency shutoff switches or devices in [Assignment: organization-defined location by system or system component] to facilitate access for authorized personnel; and c. Protect emergency power shutoff capability from unauthorized activation. Discussion:  Emergency power shutoff primarily applies to organizational facilities that contain concentrations of system resources, including data centers, mainframe computer rooms, server rooms, and areas with computer-controlled machinery. Related Controls:  PE-15. Control Enhancements: (1) EMERGENCY SHUTOFF | ACCIDENTAL AND UNAUTHORIZED ACTIVATION [Withdrawn: Incorporated into PE-10.] References:  None.', 'vec_doc-14-nist-sp-800-53-p214-803', 0, 234, 'v2.1.0', 'e724feae8806f14d67070dba816afeac113d13b6b0c881a2a3165bfe0e248187', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 187","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":803,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 187"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p214-804', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 187', 214, 'PE-11 EMERGENCY POWER Control:  Provide an uninterruptible power supply to facilitate [Selection (one or more): an orderly shutdown of the system; transition of the system to long-term alternate power] in the event of a primary power source loss. Discussion:  An uninterruptible power supply (UPS) is an electrical system or mechanism that provides emergency power when there is a failure of the main power source. A UPS is typically used to protect computers, data centers, telecommunication equipment, or other electrical equipment where an unexpected power disruption could cause injuries, fatalities, serious mission or business disruption, or loss of data or information. A UPS differs from an emergency power system or backup generator in that the UPS provides near-instantaneous protection from unanticipated power interruptions from the main power source by providing energy stored in batteries, supercapacitors, or flywheels.', 'vec_doc-14-nist-sp-800-53-p214-804', 0, 234, 'v2.1.0', 'c336d30a9fd80ed1c7be97b1a7d4d9ed52ff828b05248100372f363d13203c5a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 187","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":804,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 187"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p214-805', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 187', 214, 'The battery duration of a UPS is relatively short but provides sufficient time to start a standby power source, such as a backup generator, or properly shut down the system. Related Controls:  AT-3, CP-2, CP-7. Control Enhancements: (1) EMERGENCY POWER | ALTERNATE POWER SUPPLY —  MINIMAL OPERATIONAL CAPABILITY Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that can maintain minimally required operational capability in the event of an extended loss of the primary power source. Discussion:  Provision of an alternate power supply with minimal operating capability can be satisfied by accessing a secondary commercial power supply or other external power supply. Related Controls:  None. (2) EMERGENCY POWER | ALTERNATE POWER SUPPLY —  SELF-CONTAINED Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that is: (a) Self-contained;', 'vec_doc-14-nist-sp-800-53-p214-805', 0, 238, 'v2.1.0', '3d04cec0f6b7c27d75dc87805b1153e4264882460b3037403db1e943901268c1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 187","subsection":"UNKNOWN","table_id":null,"page":214,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":805,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 187"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p215-806', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 188', 215, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Not reliant on external power generation; and (c) Capable of maintaining [Selection: minimally required operational capability; full operational capability] in the event of an extended loss of the primary power source. Discussion:  The provision of a long-term, self-contained power supply can be satisfied by using one or more generators with sufficient capacity to meet the needs of the organization. Related Controls:  None. References:  None. PE-12 EMERGENCY LIGHTING Control:  Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility. Discussion:  The provision of emergency lighting applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms.', 'vec_doc-14-nist-sp-800-53-p215-806', 0, 248, 'v2.1.0', 'f55d5494179d69552509a795708dab357bbddf64cc5d6bcc01a26fe35945c91e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 188","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":806,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 188"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p215-807', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 188', 215, 'Emergency lighting provisions for the system are described in the contingency plan for the organization. If emergency lighting for the system fails or cannot be provided, organizations consider alternate processing sites for power-related contingencies. Related Controls:  CP-2, CP-7. Control Enhancements: (1) EMERGENCY LIGHTING | ESSENTIAL MISSION AND BUSINESS FUNCTIONS Provide emergency lighting for all areas within the facility supporting essential mission and business functions. Discussion:  Organizations define their essential missions and functions. Related Controls:  None. References:  None. PE-13 FIRE PROTECTION Control:  Employ and maintain fire detection and suppression systems that are supported by an independent energy source. Discussion:  The provision of fire detection and suppression systems applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms.', 'vec_doc-14-nist-sp-800-53-p215-807', 0, 245, 'v2.1.0', '8110d18761cf8cc1db17c61eca247baa295bc89d49046e42631e9e3fcb72e918', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 188","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":807,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 188"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p215-808', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 188', 215, 'Fire detection and suppression systems that may require an independent energy source include sprinkler systems and smoke detectors. An independent energy source is an energy source, such as a microgrid, that is separate, or can be separated, from the energy sources providing power for the other parts of the facility. Related Controls:  AT-3. Control Enhancements: (1) FIRE PROTECTION | DETECTION SYSTEMS —  AUTOMATIC ACTIVATION AND NOTIFICATION Employ fire detection systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders] in the event of a fire. Discussion:  Organizations can identify personnel, roles, and emergency responders if individuals on the notification list need to have access authorizations or clearances (e.g., to enter to facilities where access is restricted due to the classification or impact level of', 'vec_doc-14-nist-sp-800-53-p215-808', 0, 232, 'v2.1.0', '44cecda59a9144370858aee7b8f9082d32c0c411d4df42da0b8bdb8c5171b11a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 188","subsection":"UNKNOWN","table_id":null,"page":215,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":808,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 188"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p216-809', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 189', 216, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire. Related Controls:  None. (2) FIRE PROTECTION | SUPPRESSION SYSTEMS —  AUTOMATIC ACTIVATION AND NOTIFICATION (a) Employ fire suppression systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders]; and (b) Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis.', 'vec_doc-14-nist-sp-800-53-p216-809', 0, 170, 'v2.1.0', 'db8f1d0bc9d4e64f337aeef1d9dc1834f7fe4198f4e6a7b23e4a23d7bf64f35f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 189","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":809,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 189"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p216-810', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 189', 216, 'Discussion:  Organizations can identify specific personnel, roles, and emergency responders if individuals on the notification list need to have appropriate access authorizations and/or clearances (e.g., to enter to facilities where access is restricted due to the impact level or classification of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire. Related Controls:  None. (3) FIRE PROTECTION | AUTOMATIC FIRE SUPPRESSION [Withdrawn: Incorporated into PE-13(2).] (4) FIRE PROTECTION | INSPECTIONS Ensure that the facility undergoes [Assignment: organization-defined frequency] fire protection inspections by authorized and qualified inspectors and identified deficiencies are resolved within [Assignment: organization-defined time period].', 'vec_doc-14-nist-sp-800-53-p216-810', 0, 218, 'v2.1.0', 'bec717f9fcdf856493a1fe6d1c0659c3aaf700b4c594e83301427db41da94e43', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 189","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":810,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 189"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p216-811', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 189', 216, 'Discussion:  Authorized and qualified personnel within the jurisdiction of the organization include state, county, and city fire inspectors and fire marshals. Organizations provide escorts during inspections in situations where the systems that reside within the facilities contain sensitive information. Related Controls:  None. References:  None. PE-14 ENVIRONMENTAL CONTROLS Control: a. Maintain [Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]] levels within the facility where the system resides at [Assignment: organization-defined acceptable levels]; and b. Monitor environmental control levels [Assignment: organization-defined frequency]. Discussion:  The provision of environmental controls applies primarily to organizational facilities that contain concentrations of system resources (e.g., data centers, mainframe computer rooms, and server rooms).', 'vec_doc-14-nist-sp-800-53-p216-811', 0, 235, 'v2.1.0', '79bc2b384b2d8acb22b4747af522abfad00b0243d2a3c0ee3cbf67245a099eb9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 189","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":811,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 189"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p216-812', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 189', 216, 'Insufficient environmental controls, especially in very harsh environments, can have a significant adverse impact on the availability of systems and system components that are needed to support organizational mission and business functions. Related Controls:  AT-3, CP-2. Control Enhancements: (1) ENVIRONMENTAL CONTROLS | AUTOMATIC CONTROLS', 'vec_doc-14-nist-sp-800-53-p216-812', 0, 86, 'v2.1.0', 'f101d7118fec001b9621a6bf61f71599f93578bd4458f17039ade41a7429b60d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 189","subsection":"UNKNOWN","table_id":null,"page":216,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":812,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 189"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p217-813', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 190', 217, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Employ the following automatic environmental controls in the facility to prevent fluctuations potentially harmful to the system: [Assignment: organization-defined automatic environmental controls]. Discussion:  The implementation of automatic environmental controls provides an immediate response to environmental conditions that can damage, degrade, or destroy organizational systems or systems components. Related Controls:  None. (2) ENVIRONMENTAL CONTROLS | MONITORING WITH ALARMS AND NOTIFICATIONS Employ environmental control monitoring that provides an alarm or notification of changes potentially harmful to personnel or equipment to [Assignment: organization- defined personnel or roles]. Discussion:  The alarm or notification may be an audible alarm or a visual message in real time to personnel or roles defined by the organization.', 'vec_doc-14-nist-sp-800-53-p217-813', 0, 234, 'v2.1.0', 'd8d8577514b18c1deb14b828370a9f39777bdbaeecc660fd5c47d0b419c15f9d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 190","subsection":"UNKNOWN","table_id":null,"page":217,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":813,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 190"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p217-814', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 190', 217, 'Such alarms and notifications can help minimize harm to individuals and damage to organizational assets by facilitating a timely incident response. Related Controls:  None. References:  None. PE-15 WATER DAMAGE PROTECTION Control:  Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel. Discussion:  The provision of water damage protection primarily applies to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Isolation valves can be employed in addition to or in lieu of master shutoff valves to shut off water supplies in specific areas of concern without affecting entire organizations. Related Controls:  AT-3, PE-10.', 'vec_doc-14-nist-sp-800-53-p217-814', 0, 209, 'v2.1.0', '159f1fac0b475c1c36c671112df7dd110a919b7fe8530eb04721e70fab8a5344', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 190","subsection":"UNKNOWN","table_id":null,"page":217,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":814,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 190"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p217-815', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 190', 217, 'Control Enhancements: (1) WATER DAMAGE PROTECTION | AUTOMATION SUPPORT Detect the presence of water near the system and alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms include notification systems, water detection sensors, and alarms. Related Controls:  None. References:  None. PE-16 DELIVERY AND REMOVAL Control: a. Authorize and control [Assignment: organization-defined types of system components] entering and exiting the facility; and b. Maintain records of the system components. Discussion:  Enforcing authorizations for entry and exit of system components may require restricting access to delivery areas and isolating the areas from the system and media libraries. Related Controls:  CM-3, CM-8, MA-2, MA-3, MP-5, PE-20, SR-2, SR-3, SR-4, SR-6.', 'vec_doc-14-nist-sp-800-53-p217-815', 0, 216, 'v2.1.0', 'e4398feca151f343aea3eafee7896a875fc3048496895f76ea30e1abe9610278', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 190","subsection":"UNKNOWN","table_id":null,"page":217,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":815,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 190"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p218-816', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 191', 218, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None. References:  None. PE-17 ALTERNATE WORK SITE Control: a. Determine and document the [Assignment: organization-defined alternate work sites] allowed for use by employees; b. Employ the following controls at alternate work sites: [Assignment: organization-defined controls]; c. Assess the effectiveness of controls at alternate work sites; and d. Provide a means for employees to communicate with information security and privacy personnel in case of incidents. Discussion:  Alternate work sites include government facilities or the private residences of employees. While distinct from alternative processing sites, alternate work sites can provide readily available alternate locations during contingency operations. Organizations can define different sets of controls for specific alternate work sites or types of sites depending on the work-related activities conducted at the sites.', 'vec_doc-14-nist-sp-800-53-p218-816', 0, 252, 'v2.1.0', '5cf4f9093cc1b5e38340841dbbfd501e955c251e023a6a11d47bdd0d00ab1dba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 191","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":816,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 191"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p218-817', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 191', 218, 'Implementing and assessing the effectiveness of organization-defined controls and providing a means to communicate incidents at alternate work sites supports the contingency planning activities of organizations. Related Controls:  AC-17, AC-18, CP-7. Control Enhancements:  None. References:  [SP 800-46]. PE-18 LOCATION OF SYSTEM COMPONENTS Control:  Position system components within the facility to minimize potential damage from [Assignment: organization-defined physical and environmental hazards] and to minimize the opportunity for unauthorized access. Discussion:  Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. Organizations consider the location of entry points where unauthorized individuals, while not being granted access, might nonetheless be near systems.', 'vec_doc-14-nist-sp-800-53-p218-817', 0, 237, 'v2.1.0', '6c472fa4b37ac8515700b44d5d900aa57e3b04b8ae6345bd8d7499494e53f182', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 191","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":817,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 191"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p218-818', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 191', 218, 'Such proximity can increase the risk of unauthorized access to organizational communications using wireless packet sniffers or microphones, or unauthorized disclosure of information. Related Controls:  CP-2, PE-5, PE-19, PE-20, RA-3. (1) LOCATION OF SYSTEM COMPONENTS | FACILITY SITE [Withdrawn: Moved to PE-23.] References:  None. PE-19 INFORMATION LEAKAGE Control:  Protect the system from information leakage due to electromagnetic signals emanations. Discussion:  Information leakage is the intentional or unintentional release of data or information to an untrusted environment from electromagnetic signals emanations. The security categories', 'vec_doc-14-nist-sp-800-53-p218-818', 0, 162, 'v2.1.0', '9051fff8163feb7b690978d2b78828be9f6e3c09c872cf7a837f535d1e0598d1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 191","subsection":"UNKNOWN","table_id":null,"page":218,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":818,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 191"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p219-819', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 192', 219, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 or classifications of systems (with respect to confidentiality), organizational security policies, and risk tolerance guide the selection of controls employed to protect systems against information leakage due to electromagnetic signals emanations. Related Controls:  AC-18, PE-18, PE-20. Control Enhancements: (1) INFORMATION LEAKAGE | NATIONAL EMISSIONS POLICIES AND PROCEDURES Protect system components, associated data communications, and networks in accordance with national Emissions Security policies and procedures based on the security category or classification of the information. Discussion:  Emissions Security (EMSEC) policies include the former TEMPEST policies. Related Controls:  None. References:  [FIPS 199].', 'vec_doc-14-nist-sp-800-53-p219-819', 0, 205, 'v2.1.0', '8d10bd003bf7b6af6ca7813050d125bee9a9ef5fd7689f1f3f4a6f6a74fc1670', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 192","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":819,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 192"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p219-820', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 192', 219, 'PE-20 ASSET MONITORING AND TRACKING Control:  Employ [Assignment: organization-defined asset location technologies] to track and monitor the location and movement of [Assignment: organization-defined assets] within [Assignment: organization-defined controlled areas]. Discussion:  Asset location technologies can help ensure that critical assets— including vehicles, equipment, and system components— remain in authorized locations. Organizations consult with the Office of the General Counsel and senior agency official for privacy regarding the deployment and use of asset location technologies to address potential privacy concerns. Related Controls:  CM-8, PE-16, PM-8. Control Enhancements:  None. References:  None. PE-21 ELECTROMAGNETIC PULSE PROTECTION Control:  Employ [Assignment: organization-defined protective measures] against electromagnetic pulse damage for [Assignment: organization-defined systems and system components].', 'vec_doc-14-nist-sp-800-53-p219-820', 0, 235, 'v2.1.0', '675392364b3367b404f06c1cbdcb063935fe9e9297ccb807c4863123167f7d2b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 192","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":820,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 192"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p219-821', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 192', 219, 'Discussion:  An electromagnetic pulse (EMP) is a short burst of electromagnetic energy that is spread over a range of frequencies. Such energy bursts may be natural or man-made. EMP interference may be disruptive or damaging to electronic equipment. Protective measures used to mitigate EMP risk include shielding, surge suppressors, ferro-resonant transformers, and earth grounding. EMP protection may be especially significant for systems and applications that are part of the U.S. critical infrastructure. Related Controls:  PE-18, PE-19. Control Enhancements:  None. References:  None. PE-22 COMPONENT MARKING Control: Mark [Assignment: organization-defined system hardware components] indicating the impact level or classification level of the information permitted to be processed, stored, or transmitted by the hardware component.', 'vec_doc-14-nist-sp-800-53-p219-821', 0, 210, 'v2.1.0', 'f8a883a781bb2c1d71992476b2a30c3776be8d54ddda3041531b3f08dd1eeea4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 192","subsection":"UNKNOWN","table_id":null,"page":219,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":821,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 192"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p220-822', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 193', 220, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Hardware components that may require marking include input and output devices. Input devices include desktop and notebook computers, keyboards, tablets, and smart phones. Output devices include printers, monitors/video displays, facsimile machines, scanners, copiers, and audio devices. Permissions controlling output to the output devices are addressed in AC-3 or AC-4. Components are marked to indicate the impact level or classification level of the system to which the devices are connected, or the impact level or classification level of the information permitted to be output. Security marking refers to the use of human-readable security attributes. Security labeling refers to the use of security attributes for internal system data structures.', 'vec_doc-14-nist-sp-800-53-p220-822', 0, 215, 'v2.1.0', '8334551453da1f8d69bb75439e90e4a39d094aef4be5e296e5216f82eb580156', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 193","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":822,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 193"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p220-823', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 193', 220, 'Security marking is generally not required for hardware components that process, store, or transmit information determined by organizations to be in the public domain or to be publicly releasable. However, organizations may require markings for hardware components that process, store, or transmit public information in order to indicate that such information is publicly releasable. Marking of system hardware components reflects applicable laws, executive orders, directives, policies, regulations, and standards. Related Controls:  AC-3, AC-4,  AC-16, MP-3. Control Enhancements:  None. References:  [IR 8023]. PE-23 FACILITY LOCATION Control: a. Plan the location or site of the facility where the system resides considering physical and environmental hazards; and b. For existing facilities, consider the physical and environmental hazards in the organizational risk management strategy.', 'vec_doc-14-nist-sp-800-53-p220-823', 0, 223, 'v2.1.0', '442ec3f9796eca6ece84581851ae1d265a763847684d06806821a1d4506b07aa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 193","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":823,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 193"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p220-824', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 193', 220, 'Discussion:  Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. The location of system components within the facility is addressed in PE-18. Related Controls:  CP-2, PE-18, PE-19, PM-8, PM-9, RA-3. References:  None.', 'vec_doc-14-nist-sp-800-53-p220-824', 0, 97, 'v2.1.0', '57303152c1a72f2ca1153b2dd54c378fb44cc48555bcf0a56e44702e64997519', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 193","subsection":"UNKNOWN","table_id":null,"page":220,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":824,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 193"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p221-825', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.12   PLANNING', 221, 'Quick link to Planning Summary Table PL-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p221-825', 0, 42, 'v2.1.0', '3e58373de3c576c5715b6ddb81636a4dcfff68f60825b1186383c95bfd21f9bc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.12   PLANNING","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":825,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.12   PLANNING"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p221-826', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 221, 'level] planning policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p221-826', 0, 74, 'v2.1.0', '78371d72bc3f8b5110a261541a6c091829c70d6ff1a5c9cc215e015410a5f52c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":826,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p221-827', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the planning policy and the associated', 221, 'planning controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the planning policy and procedures; and c. Review and update the current planning:', 'vec_doc-14-nist-sp-800-53-p221-827', 0, 56, 'v2.1.0', 'a56aa895ad42ac61b2105d50139cc04267b5746fa16e5d732ada70a630fb6ec3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the planning policy and the associated","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":827,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the planning policy and the associated"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p221-828', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 221, 'organization-defined events]. Discussion:  Planning policy and procedures for the controls in the PL family implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on their development. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission level or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to planning policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-18], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p221-828', 0, 417, 'v2.1.0', '4e73b86e69ce353ab3d457b647737095215a9e1a2178f19e7141d14cd8451bbe', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":221,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":828,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-829', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 195', 222, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PL-2 SYSTEM SECURITY AND PRIVACY PLANS Control: a. Develop security and privacy plans for the system that:', 'vec_doc-14-nist-sp-800-53-p222-829', 0, 50, 'v2.1.0', 'c3744b483b3e26fcfcceb32acbb33e91c55851985f479e2a9538e24cfd5b8007', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 195","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":829,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 195"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-830', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '8. Provide the results of a privacy risk assessment for systems processing personally', 222, 'identifiable information;', 'vec_doc-14-nist-sp-800-53-p222-830', 0, 7, 'v2.1.0', '5de0742d003dc63a94599b46a652b17304c68e998181febabb14d3995b3fabf2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"8. Provide the results of a privacy risk assessment for systems processing personally","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":830,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"8. Provide the results of a privacy risk assessment for systems processing personally"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-831', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '9. Describe the operational environment for the system and any dependencies on or', 222, 'connections to other systems or system components;', 'vec_doc-14-nist-sp-800-53-p222-831', 0, 13, 'v2.1.0', 'd297fb33a22019ca84ca04a176f2591ee74ad965af0d605d4dd66192123820dd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"9. Describe the operational environment for the system and any dependencies on or","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":831,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"9. Describe the operational environment for the system and any dependencies on or"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-832', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '12. Describe the controls in place or planned for meeting the security and privacy', 222, 'requirements, including a rationale for any tailoring decisions;', 'vec_doc-14-nist-sp-800-53-p222-832', 0, 16, 'v2.1.0', '3608bc89a08f1bb3c7324bf250b55c23820f9d95dfc510d5d9a55197efc85a35', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"12. Describe the controls in place or planned for meeting the security and privacy","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":832,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"12. Describe the controls in place or planned for meeting the security and privacy"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-833', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '14. Include security- and privacy-related activities affecting the system that require planning', 222, 'and coordination with [Assignment: organization-defined individuals or groups]; and', 'vec_doc-14-nist-sp-800-53-p222-833', 0, 21, 'v2.1.0', 'dd083daea6a090478ed87aa6e6db375d267a43df351b566818528c8b21fc4570', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"14. Include security- and privacy-related activities affecting the system that require planning","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":833,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"14. Include security- and privacy-related activities affecting the system that require planning"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p222-834', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '15. Are reviewed and approved by the authorizing official or designated representative', 222, 'prior to plan implementation. b. Distribute copies of the plans and communicate subsequent changes to the plans to [Assignment: organization-defined personnel or roles]; c. Review the plans [Assignment: organization-defined frequency]; d. Update the plans to address changes to the system and environment of operation or problems identified during plan implementation or control assessments; and e. Protect the plans from unauthorized disclosure and modification. Discussion:  System security and privacy plans are scoped to the system and system components within the defined authorization boundary and contain an overview of the security and privacy requirements for the system and the controls selected to satisfy the requirements. The plans describe the intended application of each selected control in the context of the system with a sufficient level of detail to correctly implement the control and to subsequently assess the effectiveness of the control. The control documentation describes how system-specific and hybrid controls are implemented and the plans and expectations regarding the functionality of the system. System security and privacy plans can also be used in the design and development of systems in support of life cycle-based security and privacy engineering processes. System security and privacy plans are living documents that are updated and adapted throughout the system development life cycle (e.g., during capability determination, analysis of alternatives, requests for proposal, and design reviews).', 'vec_doc-14-nist-sp-800-53-p222-834', 0, 384, 'v2.1.0', '59d37ce47c6943aa964b3603f8982ef3bfe442cecd3f8c409bcad608f233be7b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"15. Are reviewed and approved by the authorizing official or designated representative","subsection":"UNKNOWN","table_id":null,"page":222,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":834,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"15. Are reviewed and approved by the authorizing official or designated representative"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p223-835', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 196', 223, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 relevant to organizations during the system development life cycle and the relationship between requirements and controls. Organizations may develop a single, integrated security and privacy plan or maintain separate plans. Security and privacy plans relate security and privacy requirements to a set of controls and control enhancements. The plans describe how the controls and control enhancements meet the security and privacy requirements but do not provide detailed, technical descriptions of the design or implementation of the controls and control enhancements.', 'vec_doc-14-nist-sp-800-53-p223-835', 0, 165, 'v2.1.0', '28e61f3b8645786c3a52bbc226067633aa4e48395a78f3614c3558c94c1164cf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 196","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":835,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 196"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p223-836', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 196', 223, 'Security and privacy plans contain sufficient information (including specifications of control parameter values for selection and assignment operations explicitly or by reference) to enable a design and implementation that is unambiguously compliant with the intent of the plans and subsequent determinations of risk to organizational operations and assets, individuals, other organizations, and the Nation if the plan is implemented. Security and privacy plans need not be single documents. The plans can be a collection of various documents, including documents that already exist. Effective security and privacy plans make extensive use of references to policies, procedures, and additional documents, including design and implementation specifications where more detailed information can be obtained.', 'vec_doc-14-nist-sp-800-53-p223-836', 0, 201, 'v2.1.0', 'd0d88ccea5f20cea9e16b98485e589f9cb4c652aa468a4846a33c3eeac8ec90e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 196","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":836,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 196"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p223-837', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 196', 223, 'The use of references helps reduce the documentation associated with security and privacy programs and maintains the security- and privacy-related information in other established management and operational areas, including enterprise architecture, system development life cycle, systems engineering, and acquisition. Security and privacy plans need not contain detailed contingency plan or incident response plan information but can instead provide— explicitly or by reference— sufficient information to define what needs to be accomplished by those plans. Security- and privacy-related activities that may require coordination and planning with other individuals or groups within the organization include assessments, audits, inspections, hardware and software maintenance, acquisition and supply chain risk management, patch management, and contingency plan testing. Planning and coordination include emergency and nonemergency (i.e., planned or non-urgent unplanned) situations.', 'vec_doc-14-nist-sp-800-53-p223-837', 0, 246, 'v2.1.0', '558e8836f71afab53614d201f75ae78ce47e248757422e081fdfa02b4fd14280', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 196","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":837,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 196"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p223-838', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 196', 223, 'The process defined by organizations to plan and coordinate security- and privacy-related activities can also be included in other documents, as appropriate. Related Controls:  AC-2, AC-6, AC-14, AC-17, AC-20, CA-2, CA-3, CA-7, CM-9, CM-13, CP-2, CP-4, IR-4, IR-8, MA-4, MA-5, MP-4, MP-5, PL-7, PL-8, PL-10, PL-11, PM-1, PM-7, PM-8, PM-9, PM-10, PM-11, RA-3, RA-8, RA-9, SA-5, SA-17, SA-22, SI-12, SR-2, SR-4. Control Enhancements: (1) SYSTEM SECURITY AND PRIVACY PLANS | CONCEPT OF OPERATIONS [Withdrawn: Incorporated into PL-7.] (2) SYSTEM SECURITY AND PRIVACY PLANS | FUNCTIONAL ARCHITECTURE [Withdrawn: Incorporated into PL-8.] (3) SYSTEM SECURITY AND PRIVACY PLANS | PLAN AND COORDINATE WITH OTHER ORGANIZATIONAL ENTITIES [Withdrawn: Incorporated into PL-2.] References:  [OMB A-130], [SP 800-18], [SP 800-37], [SP 800-160-1], [SP 800-160-2]. PL-3 SYSTEM SECURITY PLAN UPDATE [Withdrawn: Incorporated into PL-2.]', 'vec_doc-14-nist-sp-800-53-p223-838', 0, 230, 'v2.1.0', '7e3a663f963a7b92bed7798de752fbf5f2bb6d9f44404646a136414026d7ed43', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 196","subsection":"UNKNOWN","table_id":null,"page":223,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":838,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 196"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p224-839', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 197', 224, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PL-4 RULES OF BEHAVIOR Control: a. Establish and provide to individuals requiring access to the system, the rules that describe their responsibilities and expected behavior for information and system usage, security, and privacy; b. Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system; c. Review and update the rules of behavior [Assignment: organization-defined frequency]; and d. Require individuals who have acknowledged a previous version of the rules of behavior to read and re-acknowledge [Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated]. Discussion:  Rules of behavior represent a type of access agreement for organizational users.', 'vec_doc-14-nist-sp-800-53-p224-839', 0, 236, 'v2.1.0', '13d7e0e72401c52859d7653a000b762bdc31a793dca1b5756fa0f3e283fd1a56', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 197","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":839,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 197"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p224-840', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 197', 224, 'Other types of access agreements include nondisclosure agreements, conflict-of-interest agreements, and acceptable use agreements (see PS-6). Organizations consider rules of behavior based on individual user roles and responsibilities and differentiate between rules that apply to privileged users and rules that apply to general users. Establishing rules of behavior for some types of non-organizational users, including individuals who receive information from federal systems, is often not feasible given the large number of such users and the limited nature of their interactions with the systems. Rules of behavior for organizational and non-organizational users can also be established in AC-8. The related controls section provides a list of controls that are relevant to organizational rules of behavior.', 'vec_doc-14-nist-sp-800-53-p224-840', 0, 203, 'v2.1.0', 'dd4e317349e1d1b6ef27e99e4a09130bcd6eb22e2f59015a872effc3b3443b82', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 197","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":840,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 197"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p224-841', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 197', 224, 'PL-4b, the documented acknowledgment portion of the control, may be satisfied by the literacy training and awareness and role-based training programs conducted by organizations if such training includes rules of behavior. Documented acknowledgements for rules of behavior include electronic or physical signatures and electronic agreement check boxes or radio buttons. Related Controls:  AC-2, AC-6, AC-8, AC-9, AC-17, AC-18, AC-19, AC-20, AT-2, AT-3, CM-11, IA-2, IA-4, IA-5, MP-7, PS-6, PS-8, SA-5, SI-12. Control Enhancements: (1) RULES OF BEHAVIOR | SOCIAL MEDIA AND EXTERNAL SITE/APPLICATION USAGE RESTRICTIONS Include in the rules of behavior, restrictions on: (a) Use of social media, social networking sites, and external sites/applications; (b) Posting organizational information on public websites; and (c) Use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications.', 'vec_doc-14-nist-sp-800-53-p224-841', 0, 245, 'v2.1.0', '58bb848d0839668b2453a6e21bf9483c516aab8789dd57a62ca4ad77b54535b1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 197","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":841,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 197"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p224-842', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 197', 224, 'Discussion:  Social media, social networking, and external site/application usage restrictions address rules of behavior related to the use of social media, social networking, and external sites when organizational personnel are using such sites for official duties or in the conduct of official business, when organizational information is involved in social media and social networking transactions, and when personnel access social media and networking sites from organizational systems. Organizations also address specific rules that prevent unauthorized entities from obtaining non-public organizational information from social media and networking sites either directly or through inference. Non-public information includes personally identifiable information and system account information. Related Controls:  AC-22, AU-13. References:  [OMB A-130], [SP 800-18].', 'vec_doc-14-nist-sp-800-53-p224-842', 0, 218, 'v2.1.0', '9448140bca01d24b7798e24a16c859a39c8c0405db367e7e7718c52c9d3f2872', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 197","subsection":"UNKNOWN","table_id":null,"page":224,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":842,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 197"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p225-843', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 198', 225, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PL-5 PRIVACY IMPACT ASSESSMENT [Withdrawn: Incorporated into RA-8.] PL-6 SECURITY-RELATED ACTIVITY PLANNING [Withdrawn: Incorporated into PL-2.] PL-7 CONCEPT OF OPERATIONS Control: a. Develop a Concept of Operations (CONOPS) for the system describing how the organization intends to operate the system from the perspective of information security and privacy; and b. Review and update the CONOPS [Assignment: organization-defined frequency]. Discussion:  The CONOPS may be included in the security or privacy plans for the system or in other system development life cycle documents. The CONOPS is a living document that requires updating throughout the system development life cycle. For example, during system design reviews, the concept of operations is checked to ensure that it remains consistent with the design for controls, the system architecture, and the operational procedures. Changes to the CONOPS are reflected in ongoing updates to the security and privacy plans, security and privacy architectures, and other organizational documents, such as procurement specifications, system development life cycle documents, and systems engineering documents. Related Controls:  PL-2, SA-2, SI-12. Control Enhancements:  None. References:  [OMB A-130]. PL-8 SECURITY AND PRIVACY ARCHITECTURES Control: a. Develop security and privacy architectures for the system that:', 'vec_doc-14-nist-sp-800-53-p225-843', 0, 366, 'v2.1.0', '313ae3418edc15b40c3a4cfc5e366488cb79cdcf4f02f6acaf3a858b69b88490', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 198","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":843,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 198"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p225-844', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Describe the requirements and approach to be taken for protecting the confidentiality,', 225, 'integrity, and availability of organizational information;', 'vec_doc-14-nist-sp-800-53-p225-844', 0, 15, 'v2.1.0', '048a7896a76b68b87bd38809bd9389188c60063dd5fa23ff3d3bea09c7c1f0db', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Describe the requirements and approach to be taken for protecting the confidentiality,","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":844,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Describe the requirements and approach to be taken for protecting the confidentiality,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p225-845', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Describe the requirements and approach to be taken for processing personally', 225, 'identifiable information to minimize privacy risk to individuals;', 'vec_doc-14-nist-sp-800-53-p225-845', 0, 17, 'v2.1.0', 'e54d3b62eb3900eb42b331bbb0b4e06f88952a539726082ff9f9e122c4753b91', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Describe the requirements and approach to be taken for processing personally","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":845,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Describe the requirements and approach to be taken for processing personally"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p225-846', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Describe any assumptions about, and dependencies on, external systems and services;', 225, 'b. Review and update the architectures [Assignment: organization-defined frequency] to reflect changes in the enterprise architecture; and c. Reflect planned architecture changes in security and privacy plans, Concept of Operations (CONOPS), criticality analysis, organizational procedures, and procurements and acquisitions. Discussion:  The security and privacy architectures at the system level are consistent with the organization-wide security and privacy architectures described in PM-7, which are integral to and developed as part of the enterprise architecture. The architectures include an architectural description, the allocation of security and privacy functionality (including controls), security- and privacy-related information for external interfaces, information being exchanged across the interfaces, and the protection mechanisms associated with each interface. The architectures can', 'vec_doc-14-nist-sp-800-53-p225-846', 0, 226, 'v2.1.0', '609a88bbffa1302860e9778876827945a3b3ecccbd871edf35f47f192f5fc2b0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Describe any assumptions about, and dependencies on, external systems and services;","subsection":"UNKNOWN","table_id":null,"page":225,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":846,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Describe any assumptions about, and dependencies on, external systems and services;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p226-847', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 199', 226, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 also include other information, such as user roles and the access privileges assigned to each role; security and privacy requirements; types of information processed, stored, and transmitted by the system; supply chain risk management requirements; restoration priorities of information and system services; and other protection needs. [SP 800-160-1] provides guidance on the use of security architectures as part of the system development life cycle process. [OMB M-19-03] requires the use of the systems security engineering concepts described in [SP 800-160-1] for high value assets.', 'vec_doc-14-nist-sp-800-53-p226-847', 0, 170, 'v2.1.0', '140469a4bfd613deb9729a75b6b71d110584b691c883ebebd2a8b6255574dd26', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 199","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":847,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 199"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p226-848', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 199', 226, 'Security and privacy architectures are reviewed and updated throughout the system development life cycle, from analysis of alternatives through review of the proposed architecture in the RFP responses to the design reviews before and during implementation (e.g., during preliminary design reviews and critical design reviews). In today’s modern computing architectures, it is becoming less common for organizations to control all information resources. There may be key dependencies on external information services and service providers. Describing such dependencies in the security and privacy architectures is necessary for developing a comprehensive mission and business protection strategy. Establishing, developing, documenting, and maintaining under configuration control a baseline configuration for organizational systems is critical to implementing and maintaining effective architectures.', 'vec_doc-14-nist-sp-800-53-p226-848', 0, 225, 'v2.1.0', 'e8aeadccb07b09f1b25bd53380aa2ffbc924d1c389bd21ea5ede041163f96493', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 199","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":848,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 199"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p226-849', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 199', 226, 'The development of the architectures is coordinated with the senior agency information security officer and the senior agency official for privacy to ensure that the controls needed to support security and privacy requirements are identified and effectively implemented. In many circumstances, there may be no distinction between the security and privacy architecture for a system. In other circumstances, security objectives may be adequately satisfied, but privacy objectives may only be partially satisfied by the security requirements. In these cases, consideration of the privacy requirements needed to achieve satisfaction will result in a distinct privacy architecture. The documentation, however, may simply reflect the combined architectures. PL-8 is primarily directed at organizations to ensure that architectures are developed for the system and, moreover, that the architectures are integrated with or tightly coupled to the enterprise architecture.', 'vec_doc-14-nist-sp-800-53-p226-849', 0, 241, 'v2.1.0', '56037eb9114da10c55cdc840ccc4603814524eae4e430f38835759112fe4622a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 199","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":849,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 199"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p226-850', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 199', 226, 'In contrast, SA-17 is primarily directed at the external information technology product and system developers and integrators. SA-17, which is complementary to PL-8, is selected when organizations outsource the development of systems or components to external entities and when there is a need to demonstrate consistency with the organization’s enterprise architecture and security and privacy architectures. Related Controls:  CM-2, CM-6, PL-2, PL-7, PL-9, PM-5, PM-7, RA-9, SA-3, SA-5, SA-8, SA-17, SC-7. Control Enhancements: (1) SECURITY AND PRIVACY ARCHITECTURES | DEFENSE IN DEPTH Design the security and privacy architectures for the system using a defense-in-depth approach that: (a) Allocates [Assignment: organization-defined controls] to [Assignment: organization- defined locations and architectural layers]; and (b) Ensures that the allocated controls operate in a coordinated and mutually reinforcing manner.', 'vec_doc-14-nist-sp-800-53-p226-850', 0, 231, 'v2.1.0', '7511238608919a7965af7ab6a598dbd4d98fdfa36668bd8c64b478d19492f142', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 199","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":850,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 199"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p226-851', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 199', 226, 'Discussion:  Organizations strategically allocate security and privacy controls in the security and privacy architectures so that adversaries must overcome multiple controls to achieve their objective. Requiring adversaries to defeat multiple controls makes it more difficult to attack information resources by increasing the work factor of the adversary; it also increases the likelihood of detection. The coordination of allocated controls is essential to ensure that an attack that involves one control does not create adverse, unintended consequences by interfering with other controls. Unintended consequences can include system lockout and', 'vec_doc-14-nist-sp-800-53-p226-851', 0, 162, 'v2.1.0', 'f7e395ef7f351c9a8d913e55348cd9d1b9b9f4132653c5893b98a6db1b819d9d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 199","subsection":"UNKNOWN","table_id":null,"page":226,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":851,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 199"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p227-852', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 200', 227, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 cascading alarms. The placement of controls in systems and organizations is an important activity that requires thoughtful analysis. The value of organizational assets is an important consideration in providing additional layering. Defense-in-depth architectural approaches include modularity and layering (see SA-8(3)), separation of system and user functionality (see SC-2), and security function isolation (see SC-3). Related Controls:  SC-2, SC-3, SC-29, SC-36. (2) SECURITY AND PRIVACY ARCHITECTURES | SUPPLIER DIVERSITY Require that [Assignment: organization-defined controls] allocated to [Assignment: organization-defined locations and architectural layers] are obtained from different suppliers. Discussion:  Information technology products have different strengths and weaknesses. Providing a broad spectrum of products complements the individual offerings.', 'vec_doc-14-nist-sp-800-53-p227-852', 0, 240, 'v2.1.0', 'e2c27debc0a811c4547e599a1748886a2c6e8a9db702ab6f024619cccf2ae47b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 200","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":852,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 200"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p227-853', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 200', 227, 'For example, vendors offering malicious code protection typically update their products at different times, often developing solutions for known viruses, Trojans, or worms based on their priorities and development schedules. By deploying different products at different locations, there is an increased likelihood that at least one of the products will detect the malicious code. With respect to privacy, vendors may offer products that track personally identifiable information in systems. Products may use different tracking methods. Using multiple products may result in more assurance that personally identifiable information is inventoried. Related Controls:  SC-29, SR-3. References:  [OMB A-130], [SP 800-160-1], [SP 800-160-2]. PL-9 CENTRAL MANAGEMENT Control:  Centrally manage [Assignment: organization-defined controls and related processes]. Discussion:  Central management refers to organization-wide management and implementation of selected controls and processes.', 'vec_doc-14-nist-sp-800-53-p227-853', 0, 245, 'v2.1.0', '1899d251b7f0c3d1201ccc17139c2b25faefd244cacb016b8abadc022321c287', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 200","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":853,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 200"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p227-854', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 200', 227, 'This includes planning, implementing, assessing, authorizing, and monitoring the organization-defined, centrally managed controls and processes. As the central management of controls is generally associated with the concept of common (inherited) controls, such management promotes and facilitates standardization of control implementations and management and the judicious use of organizational resources. Centrally managed controls and processes may also meet independence requirements for assessments in support of initial and ongoing authorizations to operate and as part of organizational continuous monitoring. Automated tools (e.g., security information and event management tools or enterprise security monitoring and management tools) can improve the accuracy, consistency, and availability of information associated with centrally managed controls and processes.', 'vec_doc-14-nist-sp-800-53-p227-854', 0, 218, 'v2.1.0', '3669a271448e3098ef2483e997b3b5ea562a6e3a86779b8dea1165624ac10d6d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 200","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":854,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 200"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p227-855', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 200', 227, 'Automation can also provide data aggregation and data correlation capabilities; alerting mechanisms; and dashboards to support risk-based decision-making within the organization. As part of the control selection processes, organizations determine the controls that may be suitable for central management based on resources and capabilities. It is not always possible to centrally manage every aspect of a control. In such cases, the control can be treated as a hybrid control with the control managed and implemented centrally or at the system level.', 'vec_doc-14-nist-sp-800-53-p227-855', 0, 138, 'v2.1.0', '8d7d93f3c0ee88ed8840fdaeecc832c840a7dbb1d501192118a9924e630faba4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 200","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":855,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 200"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p227-856', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 200', 227, 'The controls and control enhancements that are candidates for full or partial central management include but are not limited to: AC-2(1), AC-2(2), AC-2(3), AC-2(4), AC-4(all), AC-17(1), AC-17(2), AC-17(3), AC- 17(9), AC-18(1), AC-18(3), AC-18(4), AC-18(5), AC-19(4), AC-22, AC-23, AT-2(1), AT-2(2), AT-3(1), AT-3(2), AT-3(3), AT-4, AU-3, AU-6(1), AU-6(3), AU-6(5), AU-6(6), AU-6(9), AU-7(1), AU-7(2), AU- 11, AU-13, AU-16, CA-2(1), CA-2(2), CA-2(3), CA-3(1), CA-3(2), CA-3(3), CA-7(1), CA-9, CM-2(2), CM-3(1), CM-3(4), CM-4, CM-6, CM-6(1), CM-7(2), CM-7(4), CM-7(5), CM-8(all), CM-9(1), CM-10, CM-11, CP-7(all), CP-8(all), SC-43, SI-2, SI-3, SI-4(all), SI-7, SI-8.', 'vec_doc-14-nist-sp-800-53-p227-856', 0, 166, 'v2.1.0', 'a74759f3ac3cdb62339414f6a5a179bf1076e6b58dcc0bb6974c3556edb5fe9c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 200","subsection":"UNKNOWN","table_id":null,"page":227,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":856,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 200"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p228-857', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 201', 228, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  PL-8, PM-9. Control Enhancements:  None. References:  [OMB A-130], [SP 800-37]. PL-10 BASELINE SELECTION Control:  Select a control baseline for the system. Discussion:  Control baselines are predefined sets of controls specifically assembled to address the protection needs of a group, organization, or community of interest. Controls are chosen for baselines to either satisfy mandates imposed by laws, executive orders, directives, regulations, policies, standards, and guidelines or address threats common to all users of the baseline under the assumptions specific to the baseline. Baselines represent a starting point for the protection of individuals’ privacy, information, and information systems with subsequent tailoring actions to manage risk in accordance with mission, business, or other constraints (see PL-11). Federal control baselines are provided in [SP 800-53B].', 'vec_doc-14-nist-sp-800-53-p228-857', 0, 248, 'v2.1.0', 'de9896cfdcd5c67532f4309b89c19b10aac81254ff269c6d726c2c633a471193', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 201","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":857,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 201"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p228-858', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 201', 228, 'The selection of a control baseline is determined by the needs of stakeholders. Stakeholder needs consider mission and business requirements as well as mandates imposed by applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. For example, the control baselines in [SP 800-53B] are based on the requirements from [FISMA] and [PRIVACT]. The requirements, along with the NIST standards and guidelines implementing the legislation, direct organizations to select one of the control baselines after the reviewing the information types and the information that is processed, stored, and transmitted on the system; analyzing the potential adverse impact of the loss or compromise of the information or system on the organization’s operations and assets, individuals, other organizations, or the Nation; and considering the results from system and organizational risk assessments. [CNSSI 1253] provides guidance on control baselines for national security systems.', 'vec_doc-14-nist-sp-800-53-p228-858', 0, 250, 'v2.1.0', 'cfe20e6577d8928b7d36bc21dbb4ed4e369584421ee2f05d8ca077d8a9cec583', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 201","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":858,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 201"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p228-859', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 201', 228, 'Related Controls:  PL-2, PL-11, RA-2, RA-3, SA-8. Control Enhancements:  None. References:  [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-53B], [SP 800- 60-1], [SP 800-60-2], [SP 800-160-1], [CNSSI 1253]. PL-11 BASELINE TAILORING Control:  Tailor the selected control baseline by applying specified tailoring actions. Discussion:  The concept of tailoring allows organizations to specialize or customize a set of baseline controls by applying a defined set of tailoring actions. Tailoring actions facilitate such specialization and customization by allowing organizations to develop security and privacy plans that reflect their specific mission and business functions, the environments where their systems operate, the threats and vulnerabilities that can affect their systems, and any other conditions or situations that can impact their mission or business success. Tailoring guidance is provided in [ SP 800-53B].', 'vec_doc-14-nist-sp-800-53-p228-859', 0, 236, 'v2.1.0', '77dfb0f421556eacea8446c51d1c590b6fd3c3f9362f0b095e2187d0bda13060', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 201","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":859,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 201"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p228-860', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 201', 228, 'Tailoring a control baseline is accomplished by identifying and designating common controls, applying scoping considerations, selecting compensating controls, assigning values to control parameters, supplementing the control baseline with additional controls as needed, and providing information for control implementation. The general tailoring actions in [SP 800-53B] can be supplemented with additional actions based on the needs of organizations. Tailoring actions can be applied to the baselines in [SP 800-53B] in accordance with the security and privacy requirements from [FISMA], [PRIVACT], and [OMB A-130]. Alternatively, other communities of interest adopting different control baselines can apply the tailoring actions in [SP 800-53B] to specialize or customize the controls that represent the specific needs and concerns of those entities.', 'vec_doc-14-nist-sp-800-53-p228-860', 0, 213, 'v2.1.0', 'c7a03b759a161f446a6239b173176cf2f782af29853ab28cf2016b5a05b3aeeb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 201","subsection":"UNKNOWN","table_id":null,"page":228,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":860,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 201"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p229-861', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 202', 229, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  PL-10, RA-2, RA-3, RA-9, SA-8. Control Enhancements:  None. References:  [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-53B], [SP 800- 60-1], [SP 800-60-2], [SP 800-160-1], [CNSSI 1253].', 'vec_doc-14-nist-sp-800-53-p229-861', 0, 81, 'v2.1.0', 'e6ab03df1db201739d1d75175b1bf83997371562953b08b17e7a78b9963fe182', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 202","subsection":"UNKNOWN","table_id":null,"page":229,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":861,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 202"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-862', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.13   PROGRAM MANAGEMENT', 230, 'Quick link to Program Management Summary Table PM-1 INFORMATION SECURITY PROGRAM PLAN Control: a. Develop and disseminate an organization-wide information security program plan that:', 'vec_doc-14-nist-sp-800-53-p230-862', 0, 46, 'v2.1.0', '9cae166848feb8ee9de971fd72100287ca377fd6e5142c815b55136ab274b8da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.13   PROGRAM MANAGEMENT","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":862,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.13   PROGRAM MANAGEMENT"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-863', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Provides an overview of the requirements for the security program and a description of', 230, 'the security program management controls and common controls in place or planned for meeting those requirements;', 'vec_doc-14-nist-sp-800-53-p230-863', 0, 28, 'v2.1.0', 'd18a86b406c31a47f21f1378e8e825fe5aa48086d9b3c994abc4ff3148cb5274', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Provides an overview of the requirements for the security program and a description of","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":863,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Provides an overview of the requirements for the security program and a description of"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-864', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Includes the identification and assignment of roles, responsibilities, management', 230, 'commitment, coordination among organizational entities, and compliance;', 'vec_doc-14-nist-sp-800-53-p230-864', 0, 18, 'v2.1.0', '09d0dce2634c4fbda9430c1dbbb74622a8f96284ea477d1be3844a1aee8c12bc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Includes the identification and assignment of roles, responsibilities, management","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":864,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Includes the identification and assignment of roles, responsibilities, management"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-865', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Is approved by a senior official with responsibility and accountability for the risk being', 230, 'incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; b. Review and update the organization-wide information security program plan [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and c. Protect the information security program plan from unauthorized disclosure and modification.', 'vec_doc-14-nist-sp-800-53-p230-865', 0, 111, 'v2.1.0', '6e38c27acb90d9ba8e36689e0abf72ee26d191b3e10868add6823f5d3d52e3a3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Is approved by a senior official with responsibility and accountability for the risk being","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":865,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Is approved by a senior official with responsibility and accountability for the risk being"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-866', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Is approved by a senior official with responsibility and accountability for the risk being', 230, 'Discussion:  An information security program plan is a formal document that provides an overview of the security requirements for an organization-wide information security program PROGRAM MANAGEMENT CONTROLS [FISMA], [ PRIVACT], and [ OMB A -130] require federal agencies to develop, implement, and provide oversight for organization-wide information security and privacy p rograms to help ensure the confidentiality, integrity, and availability of federal information processed, stored, and transmitted by federal information systems and to protect individual privacy. The program management (PM) controls described in this section are implemented at the organization level and not direct ed at individual information  systems. The PM  controls have been designed to facilitate organizational compliance with applicable federal laws, e xecutive orders, directives, policies, regulations, and standards.', 'vec_doc-14-nist-sp-800-53-p230-866', 0, 226, 'v2.1.0', '6eb57db2eca735c1ad2d88cfc0c0fc6bab1e5f6b3fa69f729feafd9a2593cab6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Is approved by a senior official with responsibility and accountability for the risk being","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":866,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Is approved by a senior official with responsibility and accountability for the risk being"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p230-867', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Is approved by a senior official with responsibility and accountability for the risk being', 230, 'The controls are independent of [ FIPS 200] impact levels and, therefore, are not associated with the control baselines described in [SP 800-53B]. Organizations document program management controls in the information security and privacy program plans. The organization-wide information security program plan (see PM-1) and privacy program plan (see PM-18) supplement system security and privacy plans (see PL-2) developed for organizational information systems. Together, the system security and privacy plans for the individual information systems and the information security and privacy program  plans cover the totality of security and privacy controls employed by the organization.', 'vec_doc-14-nist-sp-800-53-p230-867', 0, 172, 'v2.1.0', '80d4f110dbcf6f7b097241bf968507e957cc78397c56dff357efc8e943d6fd8a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Is approved by a senior official with responsibility and accountability for the risk being","subsection":"UNKNOWN","table_id":null,"page":230,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":867,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Is approved by a senior official with responsibility and accountability for the risk being"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p231-868', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 204', 231, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and describes the program management controls and common controls in place or planned for meeting those requirements. An information security program plan can be represented in a single document or compilations of documents. Privacy program plans and supply chain risk management plans are addressed separately in PM-18 and SR-2, respectively. An information security program plan documents implementation details about program management and common controls. The plan provides sufficient information about the controls (including specification of parameters for assignment and selection operations, explicitly or by reference) to enable implementations that are unambiguously compliant with the intent of the plan and a determination of the risk to be incurred if the plan is implemented as intended.', 'vec_doc-14-nist-sp-800-53-p231-868', 0, 224, 'v2.1.0', '184ea8349a332fd7a686694f0f663e8fd2dd805e00b53fdf3181ebce45e2098d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 204","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":868,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 204"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p231-869', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 204', 231, 'Updates to information security program plans include organizational changes and problems identified during plan implementation or control assessments. Program management controls may be implemented at the organization level or the mission or business process level, and are essential for managing the organization’s information security program. Program management controls are distinct from common, system-specific, and hybrid controls because program management controls are independent of any particular system. Together, the individual system security plans and the organization-wide information security program plan provide complete coverage for the security controls employed within the organization. Common controls available for inheritance by organizational systems are documented in an appendix to the organization’s information security program plan unless the controls are included in a separate security plan for a system.', 'vec_doc-14-nist-sp-800-53-p231-869', 0, 235, 'v2.1.0', 'e62ada5617c2eb74ac4795dfef6656ba5e4b21665ce42da22668676cd3611f3f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 204","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":869,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 204"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p231-870', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 204', 231, 'The organization-wide information security program plan indicates which separate security plans contain descriptions of common controls. Events that may precipitate an update to the information security program plan include, but are not limited to, organization-wide assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  PL-2, PM-18, PM-30, RA-9, SI-12, SR-2. Control Enhancements:  None. References:  [FISMA], [OMB A-130], [SP 800-37], [SP 800-39]. PM-2 INFORMATION SECURITY PROGRAM LEADERSHIP ROLE Control:  Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program. Discussion:  The senior agency information security officer is an organizational official.', 'vec_doc-14-nist-sp-800-53-p231-870', 0, 228, 'v2.1.0', '21159ba878ac799fcec3bd239caa8d58831fde5d6042e562607bd30a68b629f6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 204","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":870,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 204"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p231-871', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 204', 231, 'For federal agencies (as defined by applicable laws, executive orders, regulations, directives, policies, and standards), this official is the senior agency information security officer. Organizations may also refer to this official as the senior information security officer or chief information security officer. Related Controls:  None. Control Enhancements:  None. References:  [OMB M-17-25], [SP 800-37], [SP 800-39], [SP 800-181]. PM-3 INFORMATION SECURITY AND PRIVACY RESOURCES Control:', 'vec_doc-14-nist-sp-800-53-p231-871', 0, 124, 'v2.1.0', '932726f37da5745e81f8de79e3b5bf1af32451b22a299a31f636713291635904', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 204","subsection":"UNKNOWN","table_id":null,"page":231,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":871,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 204"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p232-872', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 205', 232, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Include the resources needed to implement the information security and privacy programs in capital planning and investment requests and document all exceptions to this requirement; b. Prepare documentation required for addressing information security and privacy programs in capital planning and investment requests in accordance with applicable laws, executive orders, directives, policies, regulations, standards; and c. Make available for expenditure, the planned information security and privacy resources. Discussion:  Organizations consider establishing champions for information security and privacy and, as part of including the necessary resources, assign specialized expertise and resources as needed. Organizations may designate and empower an Investment Review Board or similar group to manage and provide oversight for the information security and privacy aspects of the capital planning and investment control process. Related Controls:  PM-4, SA-2. Control Enhancements:  None. References:  [OMB A-130]. PM-4 PLAN OF ACTION AND MILESTONES PROCESS Control: a. Implement a process to ensure that plans of action and milestones for the information security, privacy, and supply chain risk management programs and associated organizational systems:', 'vec_doc-14-nist-sp-800-53-p232-872', 0, 339, 'v2.1.0', '4985cdc3ad338815eeac219b263433a1d24df673d12c4475a2c05e15e150870a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 205","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":872,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 205"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p232-873', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Document the remedial information security, privacy, and supply chain risk', 232, 'management actions to adequately respond to risk to organizational operations and assets, individuals, other organizations, and the Nation; and', 'vec_doc-14-nist-sp-800-53-p232-873', 0, 36, 'v2.1.0', '8a4f991fce72f9fe56709ad30ab2d7b6258f2c636e3f32faf3ca26ca171a901f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Document the remedial information security, privacy, and supply chain risk","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":873,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Document the remedial information security, privacy, and supply chain risk"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p232-874', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Are reported in accordance with established reporting requirements.', 232, 'b. Review plans of action and milestones for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions. Discussion:  The plan of action and milestones is a key organizational document and is subject to reporting requirements established by the Office of Management and Budget. Organizations develop plans of action and milestones with an organization-wide perspective, prioritizing risk response actions and ensuring consistency with the goals and objectives of the organization. Plan of action and milestones updates are based on findings from control assessments and continuous monitoring activities. There can be multiple plans of action and milestones corresponding to the information system level, mission/business process level, and organizational/governance level. While plans of action and milestones are required for federal organizations, other types of organizations can help reduce risk by documenting and tracking planned remediations. Specific guidance on plans of action and milestones at the system level is provided in CA-5. Related Controls:  CA-5, CA-7, PM-3, RA-7, SI-12. Control Enhancements:  None. References:  [PRIVACT], [OMB A-130], [SP 800-37].', 'vec_doc-14-nist-sp-800-53-p232-874', 0, 308, 'v2.1.0', 'cf8aa85a74208902ab509ea1cf3057c72b8ab23190aeb458be1f19db736b4031', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Are reported in accordance with established reporting requirements.","subsection":"UNKNOWN","table_id":null,"page":232,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":874,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Are reported in accordance with established reporting requirements."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p233-875', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 206', 233, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PM-5 SYSTEM INVENTORY Control:  Develop and update [Assignment: organization-defined frequency] an inventory of organizational systems. Discussion:  [OMB A-130] provides guidance on developing systems inventories and associated reporting requirements. System inventory refers to an organization-wide inventory of systems, not system components as described in CM-8. Related Controls:  None. Control Enhancements: (1) SYSTEM INVENTORY | INVENTORY OF PERSONALLY IDENTIFIABLE INFORMATION Establish, maintain, and update [Assignment: organization-defined frequency] an inventory of all systems, applications, and projects that process personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p233-875', 0, 190, 'v2.1.0', '7f80cff5eaa5bd453b34fb42f26cf3fc5b2cb2e7a3529d455828efabcfd4b0fe', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 206","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":875,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 206"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p233-876', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 206', 233, 'Discussion:  An inventory of systems, applications, and projects that process personally identifiable information supports the mapping of data actions, providing individuals with privacy notices, maintaining accurate personally identifiable information, and limiting the processing of personally identifiable information when such information is not needed for operational purposes. Organizations may use this inventory to ensure that systems only process the personally identifiable information for authorized purposes and that this processing is still relevant and necessary for the purpose specified therein. Related Controls:  AC-3,  CM-8, CM-12, CM-13, PL-8, PM-22, PT-3, PT-5, SI-12, SI-18. References:  [OMB A-130], [IR 8062]. PM-6 MEASURES OF PERFORMANCE Control:  Develop, monitor, and report on the results of information security and privacy measures of performance.', 'vec_doc-14-nist-sp-800-53-p233-876', 0, 220, 'v2.1.0', 'd95891bd7db641272ae6a10c4e54af7a98c6874771854ff974848a8cf017666c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 206","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":876,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 206"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p233-877', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 206', 233, 'Discussion:  Measures of performance are outcome-based metrics used by an organization to measure the effectiveness or efficiency of the information security and privacy programs and the controls employed in support of the program. To facilitate security and privacy risk management, organizations consider aligning measures of performance with the organizational risk tolerance as defined in the risk management strategy. Related Controls:  CA-7, PM-9. Control Enhancements:  None. References:  [OMB A-130], [SP 800-37], [SP 800-39], [SP 800-55], [SP 800-137]. PM-7 ENTERPRISE ARCHITECTURE Control:  Develop and maintain an enterprise architecture with consideration for information security, privacy, and the resulting risk to organizational operations and assets, individuals, other organizations, and the Nation.', 'vec_doc-14-nist-sp-800-53-p233-877', 0, 204, 'v2.1.0', 'bac4b337839b1f0b3cdc523cc9dbd953bba383ed480891280e9491c81eae4520', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 206","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":877,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 206"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p233-878', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 206', 233, 'Discussion:  The integration of security and privacy requirements and controls into the enterprise architecture helps to ensure that security and privacy considerations are addressed throughout the system development life cycle and are explicitly related to the organization’s mission and business processes. The process of security and privacy requirements integration also embeds into the enterprise architecture and the organization’s security and privacy architectures consistent with the organizational risk management strategy. For PM-7, security and privacy architectures are developed at a system-of-systems level, representing all organizational', 'vec_doc-14-nist-sp-800-53-p233-878', 0, 164, 'v2.1.0', '401cf007fe1e65c191b1c5dba7e51c01a3c847dc8a74b571c07d1bcda35eba42', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 206","subsection":"UNKNOWN","table_id":null,"page":233,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":878,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 206"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p234-879', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 207', 234, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 systems. For PL-8, the security and privacy architectures are developed at a level that represents an individual system. The system-level architectures are consistent with the security and privacy architectures defined for the organization. Security and privacy requirements and control integration are most effectively accomplished through the rigorous application of the Risk Management Framework [SP 800-37] and supporting security standards and guidelines. Related Controls:  AU-6, PL-2, PL-8, PM-11, RA-2, SA-3, SA-8, SA-17. Control Enhancements: (1) ENTERPRISE ARCHITECTURE | OFFLOADING Offload [Assignment: organization-defined non-essential functions or services] to other systems, system components, or an external provider. Discussion:  Not every function or service that a system provides is essential to organizational mission or business functions.', 'vec_doc-14-nist-sp-800-53-p234-879', 0, 239, 'v2.1.0', '57c9919621d1536d0ec148bc128cf65ad02cbcba3703a5ccd88f115b8b3c872d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 207","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":879,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 207"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p234-880', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 207', 234, 'Printing or copying is an example of a non- essential but supporting service for an organization. Whenever feasible, such supportive but non-essential functions or services are not co-located with the functions or services that support essential mission or business functions. Maintaining such functions on the same system or system component increases the attack surface of the organization’s mission- essential functions or services. Moving supportive but non-essential functions to a non- critical system, system component, or external provider can also increase efficiency by putting those functions or services under the control of individuals or providers who are subject matter experts in the functions or services. Related Controls:  SA-8. References:  [OMB A-130], [SP 800-37], [SP 800-39], [SP 800-160-1], [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p234-880', 0, 208, 'v2.1.0', '7a41dc4b763aa334e7296a09db16cb2636dff77d392a4b5152c8e7dbd4004757', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 207","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":880,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 207"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p234-881', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 207', 234, 'PM-8 CRITICAL INFRASTRUCTURE PLAN Control:  Address information security and privacy issues in the development, documentation, and updating of a critical infrastructure and key resources protection plan. Discussion:  Protection strategies are based on the prioritization of critical assets and resources. The requirement and guidance for defining critical infrastructure and key resources and for preparing an associated critical infrastructure protection plan are found in applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Related Controls:  CP-2, CP-4, PE-18, PL-2, PM-9, PM-11, PM-18, RA-3, SI-12. Control Enhancements:  None. References:  [EO 13636], [OMB A-130], [HSPD 7], [DHS NIPP]. PM-9 RISK MANAGEMENT STRATEGY Control: a. Develops a comprehensive strategy to manage:', 'vec_doc-14-nist-sp-800-53-p234-881', 0, 206, 'v2.1.0', 'fce3f15dd1f94212be68d5abf80fc4a54cd6f76373b58af0e7b0c90f94a8026f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 207","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":881,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 207"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p234-882', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Security risk to organizational operations and assets, individuals, other organizations,', 234, 'and the Nation associated with the operation and use of organizational systems; and', 'vec_doc-14-nist-sp-800-53-p234-882', 0, 21, 'v2.1.0', '48077dfa97884196a89bdaa7d99c39efffea8b51db8232d1af13a0122412f2d6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Security risk to organizational operations and assets, individuals, other organizations,","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":882,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Security risk to organizational operations and assets, individuals, other organizations,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p234-883', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Privacy risk to individuals resulting from the authorized processing of personally', 234, 'identifiable information; b. Implement the risk management strategy consistently across the organization; and c. Review and update the risk management strategy [Assignment: organization-defined frequency] or as required, to address organizational changes.', 'vec_doc-14-nist-sp-800-53-p234-883', 0, 64, 'v2.1.0', 'bd490680f8cb6d9722c9b36ac7129018eaac3472bd5341b6eba756731b918d14', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Privacy risk to individuals resulting from the authorized processing of personally","subsection":"UNKNOWN","table_id":null,"page":234,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":883,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Privacy risk to individuals resulting from the authorized processing of personally"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p235-884', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 208', 235, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  An organization-wide risk management strategy includes an expression of the security and privacy risk tolerance for the organization, security and privacy risk mitigation strategies, acceptable risk assessment methodologies, a process for evaluating security and privacy risk across the organization with respect to the organization’s risk tolerance, and approaches for monitoring risk over time. The senior accountable official for risk management (agency head or designated official) aligns information security management processes with strategic, operational, and budgetary planning processes. The risk executive function, led by the senior accountable official for risk management, can facilitate consistent application of the risk management strategy organization-wide.', 'vec_doc-14-nist-sp-800-53-p235-884', 0, 220, 'v2.1.0', '735a067a2da4bfdd487285e303e32d757658bf05a9a5a8f8b760a6da632d447f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 208","subsection":"UNKNOWN","table_id":null,"page":235,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":884,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 208"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p235-885', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 208', 235, 'The risk management strategy can be informed by security and privacy risk-related inputs from other sources, both internal and external to the organization, to ensure that the strategy is broad-based and comprehensive. The supply chain risk management strategy described in PM-30 can also provide useful inputs to the organization- wide risk management strategy. Related Controls:  AC-1, AU-1, AT-1, CA-1, CA-2, CA-5, CA-6, CA-7, CM-1, CP-1, IA-1, IR-1, MA-1, MP-1, PE-1, PL-1, PL-2, PM-2, PM-8, PM-18, PM-28, PM-30, PS-1, PT-1, PT-2, PT-3, RA-1, RA-3, RA-9, SA-1, SA-4, SC-1, SC-38, SI-1, SI-12, SR-1, SR-2. Control Enhancements:  None. References:  [OMB A-130], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-161], [IR 8023]. PM-10 AUTHORIZATION PROCESS Control: a. Manage the security and privacy state of organizational systems and the environments in which those systems operate through authorization processes; b.', 'vec_doc-14-nist-sp-800-53-p235-885', 0, 230, 'v2.1.0', '9b6a9cd35fb1e73676d6125b127f858dd43b2260cff92088a5e2b1e6c55c5e1d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 208","subsection":"UNKNOWN","table_id":null,"page":235,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":885,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 208"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p235-886', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 208', 235, 'Designate individuals to fulfill specific roles and responsibilities within the organizational risk management process; and c. Integrate the authorization processes into an organization-wide risk management program. Discussion:  Authorization processes for organizational systems and environments of operation require the implementation of an organization-wide risk management process and associated security and privacy standards and guidelines. Specific roles for risk management processes include a risk executive (function) and designated authorizing officials for each organizational system and common control provider. The authorization processes for the organization are integrated with continuous monitoring processes to facilitate ongoing understanding and acceptance of security and privacy risks to organizational operations, organizational assets, individuals, other organizations, and the Nation. Related Controls:  CA-6, CA-7, PL-2. Control Enhancements:  None.', 'vec_doc-14-nist-sp-800-53-p235-886', 0, 244, 'v2.1.0', '30c2c29c5d90b6c36aad167928d7c2bb48309ce0adc5c68ee15cc73391fca268', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 208","subsection":"UNKNOWN","table_id":null,"page":235,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":886,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 208"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p235-887', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 208', 235, 'References:  [SP 800-37], [SP 800-39], [SP 800-181]. PM-11 MISSION AND BUSINESS PROCESS DEFINITION Control: a. Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, other organizations, and the Nation; and b. Determine information protection and personally identifiable information processing needs arising from the defined mission and business processes; and', 'vec_doc-14-nist-sp-800-53-p235-887', 0, 126, 'v2.1.0', '2f12b6fc3156639998bce55b2009a495d2f89d323490c839ef6821127a909734', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 208","subsection":"UNKNOWN","table_id":null,"page":235,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":887,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 208"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p236-888', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 209', 236, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 c. Review and revise the mission and business processes [Assignment: organization-defined frequency]. Discussion:  Protection needs are technology-independent capabilities that are required to counter threats to organizations, individuals, systems, and the Nation through the compromise of information (i.e., loss of confidentiality, integrity, availability, or privacy). Information protection and personally identifiable information processing needs are derived from the mission and business needs defined by organizational stakeholders, the mission and business processes designed to meet those needs, and the organizational risk management strategy. Information protection and personally identifiable information processing needs determine the required controls for the organization and the systems.', 'vec_doc-14-nist-sp-800-53-p236-888', 0, 224, 'v2.1.0', 'aed475f4f6cd92123968c2578c44e108d5bc43a3c2ec7173625a55c3bb49ca66', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 209","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":888,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 209"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p236-889', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 209', 236, 'Inherent to defining protection and personally identifiable information processing needs is an understanding of the adverse impact that could result if a compromise or breach of information occurs. The categorization process is used to make such potential impact determinations. Privacy risks to individuals can arise from the compromise of personally identifiable information, but they can also arise as unintended consequences or a byproduct of the processing of personally identifiable information at any stage of the information life cycle. Privacy risk assessments are used to prioritize the risks that are created for individuals from system processing of personally identifiable information. These risk assessments enable the selection of the required privacy controls for the organization and systems. Mission and business process definitions and the associated protection requirements are documented in accordance with organizational policies and procedures.', 'vec_doc-14-nist-sp-800-53-p236-889', 0, 242, 'v2.1.0', 'cac5944f799194cc3f7d1faefa19e55ca1d40162f0583eec72fe1fe16a649435', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 209","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":889,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 209"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p236-890', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 209', 236, 'Related Controls:  CP-2, PL-2, PM-7, PM-8, RA-2, RA-3, RA-9, SA-2. Control Enhancements:  None. References:  [OMB A-130], [FIPS 199],[SP 800-39], [SP 800-60-1], [SP 800-60-2], [SP 800-160-1]. PM-12 INSIDER THREAT PROGRAM Control:  Implement an insider threat program that includes a cross-discipline insider threat incident handling team. Discussion:  Organizations that handle classified information are required, under Executive Order 13587 [EO 13587] and the National Insider Threat Policy [ODNI NITP], to establish insider threat programs. The same standards and guidelines that apply to insider threat programs in classified environments can also be employed effectively to improve the security of controlled unclassified and other information in non-national security systems.', 'vec_doc-14-nist-sp-800-53-p236-890', 0, 196, 'v2.1.0', '3a7c3ef7f1c5890728881ae18d1c10c55453bc53d57f74e17f22635e50cf2735', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 209","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":890,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 209"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p236-891', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 209', 236, 'Insider threat programs include controls to detect and prevent malicious insider activity through the centralized integration and analysis of both technical and nontechnical information to identify potential insider threat concerns. A senior official is designated by the department or agency head as the responsible individual to implement and provide oversight for the program. In addition to the centralized integration and analysis capability, insider threat programs require organizations to prepare department or agency insider threat policies and implementation plans, conduct host-based user monitoring of individual employee activities on government-owned classified computers, provide insider threat awareness training to employees, receive access to information from offices in the department or agency for insider threat analysis, and conduct self-assessments of department or agency insider threat posture.', 'vec_doc-14-nist-sp-800-53-p236-891', 0, 230, 'v2.1.0', 'e25fc8efa05c493acc132c5c5db9821654c54cf2677ba93b637b16c1cc6bf42e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 209","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":891,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 209"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p236-892', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 209', 236, 'Insider threat programs can leverage the existence of incident handling teams that organizations may already have in place, such as computer security incident response teams. Human resources records are especially important in this effort, as there is compelling evidence to show that some types of insider crimes are often preceded by nontechnical behaviors in the workplace, including ongoing patterns of disgruntled behavior and conflicts with coworkers and other colleagues. These precursors can guide organizational officials in more focused, targeted monitoring efforts. However, the use of human resource records could raise significant concerns for privacy. The', 'vec_doc-14-nist-sp-800-53-p236-892', 0, 168, 'v2.1.0', 'e6e25378e90e24a8b2506e664f7ab44ae85d768a9802c872210e1c70cbdafd08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 209","subsection":"UNKNOWN","table_id":null,"page":236,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":892,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 209"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p237-893', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 210', 237, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 participation of a legal team, including consultation with the senior agency official for privacy, ensures that monitoring activities are performed in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  AC-6, AT-2, AU-6, AU-7, AU-10, AU-12, AU-13, CA-7, IA-4, IR-4, MP-7, PE-2, PM- 16, PS-3, PS-4, PS-5, PS-7, PS-8, SC-7, SC-38, SI-4, PM-14. Control Enhancements:  None. References:  [EO 13587], [NITP12], [ODNI NITP]. PM-13 SECURITY AND PRIVACY WORKFORCE Control:  Establish a security and privacy workforce development and improvement program.', 'vec_doc-14-nist-sp-800-53-p237-893', 0, 180, 'v2.1.0', '025ab00de143852b635590a605ed63206d12515fafd1cb4cd12d2ff973da91a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 210","subsection":"UNKNOWN","table_id":null,"page":237,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":893,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 210"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p237-894', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 210', 237, 'Discussion:  Security and privacy workforce development and improvement programs include defining the knowledge, skills, and abilities needed to perform security and privacy duties and tasks; developing role-based training programs for individuals assigned security and privacy roles and responsibilities; and providing standards and guidelines for measuring and building individual qualifications for incumbents and applicants for security- and privacy-related positions. Such workforce development and improvement programs can also include security and privacy career paths to encourage security and privacy professionals to advance in the field and fill positions with greater responsibility. The programs encourage organizations to fill security- and privacy- related positions with qualified personnel.', 'vec_doc-14-nist-sp-800-53-p237-894', 0, 202, 'v2.1.0', '41111cca7b22246cf3cf349e5f637cbe718c99d0c0bb750c1e813500a5b0c9d2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 210","subsection":"UNKNOWN","table_id":null,"page":237,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":894,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 210"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p237-895', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 210', 237, 'Security and privacy workforce development and improvement programs are complementary to organizational security awareness and training programs and focus on developing and institutionalizing the core security and privacy capabilities of personnel needed to protect organizational operations, assets, and individuals. Related Controls:  AT-2, AT-3. Control Enhancements:  None. References:  [OMB A-130], [SP 800-181]. PM-14 TESTING, TRAINING, AND MONITORING Control: a. Implement a process for ensuring that organizational plans for conducting security and privacy testing, training, and monitoring activities associated with organizational systems:', 'vec_doc-14-nist-sp-800-53-p237-895', 0, 163, 'v2.1.0', 'c609fa523919d84aeb350bc108ff3c1046104f5d1b73b34d925d9a32b3353e51', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 210","subsection":"UNKNOWN","table_id":null,"page":237,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":895,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 210"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p237-896', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Continue to be executed; and', 237, 'b. Review testing, training, and monitoring plans for consistency with the organizational risk management strategy and organization-wide priorities for risk response actions. Discussion:  A process for organization-wide security and privacy testing, training, and monitoring helps ensure that organizations provide oversight for testing, training, and monitoring activities and that those activities are coordinated. With the growing importance of continuous monitoring programs, the implementation of information security and privacy across the three levels of the risk management hierarchy and the widespread use of common controls, organizations coordinate and consolidate the testing and monitoring activities that are routinely conducted as part of ongoing assessments supporting a variety of controls. Security and privacy training activities, while focused on individual systems and specific roles, require coordination across all organizational elements. Testing, training, and monitoring plans and activities are informed by current threat and vulnerability assessments. Related Controls:  AT-2, AT-3, CA-7, CP-4, IR-3, PM-12, SI-4.', 'vec_doc-14-nist-sp-800-53-p237-896', 0, 286, 'v2.1.0', '560456595306e7aa1025e0775055a6fc7f7b3d2f54f21412f37708af5a7721e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Continue to be executed; and","subsection":"UNKNOWN","table_id":null,"page":237,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":896,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Continue to be executed; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p238-897', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 211', 238, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None. References:  [OMB A-130], [SP 800-37], [SP 800-39], [SP 800-53A], [SP 800-115], [SP 800-137]. PM-15 SECURITY AND PRIVACY GROUPS AND ASSOCIATIONS Control:  Establish and institutionalize contact with selected groups and associations within the security and privacy communities: a. To facilitate ongoing security and privacy education and training for organizational personnel; b. To maintain currency with recommended security and privacy practices, techniques, and technologies; and c. To share current security and privacy information, including threats, vulnerabilities, and incidents. Discussion:  Ongoing contact with security and privacy groups and associations is important in an environment of rapidly changing technologies and threats.', 'vec_doc-14-nist-sp-800-53-p238-897', 0, 216, 'v2.1.0', '7fdd688b8dbf53bd7c91c4ef4f4a8c0cac640351bcd06a06777ee5eb7c295123', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 211","subsection":"UNKNOWN","table_id":null,"page":238,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":897,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 211"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p238-898', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 211', 238, 'Groups and associations include special interest groups, professional associations, forums, news groups, users’ groups, and peer groups of security and privacy professionals in similar organizations. Organizations select security and privacy groups and associations based on mission and business functions. Organizations share threat, vulnerability, and incident information as well as contextual insights, compliance techniques, and privacy problems consistent with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Related Controls:  SA-11, SI-5. Control Enhancements:  None. References:  [OMB A-130]. PM-16 THREAT AWARENESS PROGRAM Control:  Implement a threat awareness program that includes a cross-organization information- sharing capability for threat intelligence.', 'vec_doc-14-nist-sp-800-53-p238-898', 0, 205, 'v2.1.0', '235babf5a51a09dd16b143349922dd583221751a6c3f78122fd2a264ac5b14bb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 211","subsection":"UNKNOWN","table_id":null,"page":238,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":898,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 211"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p238-899', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 211', 238, 'Discussion:  Because of the constantly changing and increasing sophistication of adversaries, especially the advanced persistent threat (APT), it may be more likely that adversaries can successfully breach or compromise organizational systems. One of the best techniques to address this concern is for organizations to share threat information, including threat events (i.e., tactics, techniques, and procedures) that organizations have experienced, mitigations that organizations have found are effective against certain types of threats, and threat intelligence (i.e., indications and warnings about threats). Threat information sharing may be bilateral or multilateral. Bilateral threat sharing includes government-to-commercial and government-to- government cooperatives. Multilateral threat sharing includes organizations taking part in threat- sharing consortia. Threat information may require special agreements and protection, or it may be freely shared. Related Controls:  IR-4, PM-12.', 'vec_doc-14-nist-sp-800-53-p238-899', 0, 249, 'v2.1.0', '62f1671249b8379d98924df826ee9155c9d29a4674ec58f19f9206fa21964ea2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 211","subsection":"UNKNOWN","table_id":null,"page":238,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":899,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 211"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p238-900', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 211', 238, 'Control Enhancements: (1) THREAT AWARENESS PROGRAM | AUTOMATED MEANS FOR SHARING THREAT INTELLIGENCE Employ automated mechanisms to maximize the effectiveness of sharing threat intelligence information. Discussion:  To maximize the effectiveness of monitoring, it is important to know what threat observables and indicators the sensors need to be searching for. By using well-', 'vec_doc-14-nist-sp-800-53-p238-900', 0, 94, 'v2.1.0', 'bba911daf9471cd7a297b815e7daea8484e62e18bab6c621058a6599c2a83a35', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 211","subsection":"UNKNOWN","table_id":null,"page":238,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":900,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 211"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p239-901', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 212', 239, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 established frameworks, services, and automated tools, organizations improve their ability to rapidly share and feed the relevant threat detection signatures into monitoring tools. Related Controls:  None. References:  None. PM-17 PROTECTING CONTROLLED UNCLASSIFIED INFORMATION ON EXTERNAL SYSTEMS Control: a. Establish policy and procedures to ensure that requirements for the protection of controlled unclassified information that is processed, stored or transmitted on external systems, are implemented in accordance with applicable laws, executive orders, directives, policies, regulations, and standards; and b. Review and update the policy and procedures [Assignment: organization-defined frequency]. Discussion:  Controlled unclassified information is defined by the National Archives and Records Administration along with the safeguarding and dissemination requirements for such information and is codified in [ 32 CFR 2002] and, specifically for systems external to the federal organization, 32 CFR 2002.14h. The policy prescribes the specific use and conditions to be implemented in accordance with organizational procedures, including via its contracting processes. Related Controls:  CA-6, PM-10. Control Enhancements:  None. References:  [32 CFR 2002], [SP 800-171], [SP 800-172], [NARA CUI]. PM-18 PRIVACY PROGRAM PLAN Control: a. Develop and disseminate an organization-wide privacy program plan that provides an overview of the agency’s privacy program, and:', 'vec_doc-14-nist-sp-800-53-p239-901', 0, 392, 'v2.1.0', '8fc6049c635429a2acea8761294b708d4fbb79b59889cb30d43a58b08e9efcd9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 212","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":901,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 212"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p239-902', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Includes a description of the structure of the privacy program and the resources', 239, 'dedicated to the privacy program;', 'vec_doc-14-nist-sp-800-53-p239-902', 0, 9, 'v2.1.0', 'fd6d164b5b6fbf18cce420c9fed171c79bf33cc03a59b13a53e5ac1052cfa199', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Includes a description of the structure of the privacy program and the resources","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":902,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Includes a description of the structure of the privacy program and the resources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p239-903', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Provides an overview of the requirements for the privacy program and a description of', 239, 'the privacy program management controls and common controls in place or planned for meeting those requirements;', 'vec_doc-14-nist-sp-800-53-p239-903', 0, 28, 'v2.1.0', 'deb70ed8b1a65fe74716c696ee550c6ac369c516cadd299cefc6a20ff6c3b2a7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Provides an overview of the requirements for the privacy program and a description of","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":903,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Provides an overview of the requirements for the privacy program and a description of"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p239-904', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Includes the role of the senior agency official for privacy and the identification and', 239, 'assignment of roles of other privacy officials and staff and their responsibilities;', 'vec_doc-14-nist-sp-800-53-p239-904', 0, 21, 'v2.1.0', '4be05b7a2f62552fbf35ff3fc99d489c5fd32cb4a5f15d6b78383b9f0da1b323', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Includes the role of the senior agency official for privacy and the identification and","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":904,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Includes the role of the senior agency official for privacy and the identification and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p239-905', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '6. Is approved by a senior official with responsibility and accountability for the privacy risk', 239, 'being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; and b. Update the plan [Assignment: organization-defined frequency] and to address changes in federal privacy laws and policy and organizational changes and problems identified during plan implementation or privacy control assessments.', 'vec_doc-14-nist-sp-800-53-p239-905', 0, 102, 'v2.1.0', 'd022fd9b929460cb7bf877ceb17263eed41f5b11afb6d91e2efea50fccc520d0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"6. Is approved by a senior official with responsibility and accountability for the privacy risk","subsection":"UNKNOWN","table_id":null,"page":239,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":905,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"6. Is approved by a senior official with responsibility and accountability for the privacy risk"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p240-906', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 213', 240, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  A privacy program plan is a formal document that provides an overview of an organization’s privacy program, including a description of the structure of the privacy program, the resources dedicated to the privacy program, the role of the senior agency official for privacy and other privacy officials and staff, the strategic goals and objectives of the privacy program, and the program management controls and common controls in place or planned for meeting applicable privacy requirements and managing privacy risks. Privacy program plans can be represented in single documents or compilations of documents. The senior agency official for privacy is responsible for designating which privacy controls the organization will treat as program management, common, system-specific, and hybrid controls.', 'vec_doc-14-nist-sp-800-53-p240-906', 0, 226, 'v2.1.0', 'bb8c6496a539409ca556f5204e8be9a12b100fd86431e9804d48c2d241befadd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 213","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":906,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 213"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p240-907', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 213', 240, 'Privacy program plans provide sufficient information about the privacy program management and common controls (including the specification of parameters and assignment and selection operations explicitly or by reference) to enable control implementations that are unambiguously compliant with the intent of the plans and a determination of the risk incurred if the plans are implemented as intended. Program management controls are generally implemented at the organization level and are essential for managing the organization’s privacy program. Program management controls are distinct from common, system-specific, and hybrid controls because program management controls are independent of any particular information system. Together, the privacy plans for individual systems and the organization-wide privacy program plan provide complete coverage for the privacy controls employed within the organization.', 'vec_doc-14-nist-sp-800-53-p240-907', 0, 228, 'v2.1.0', 'be6f047b647125e49ac888ad87d18fe83c9856c2ba3cdf8dcbf6ddb98717a1e5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 213","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":907,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 213"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p240-908', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 213', 240, 'Common controls are documented in an appendix to the organization’s privacy program plan unless the controls are included in a separate privacy plan for a system. The organization-wide privacy program plan indicates which separate privacy plans contain descriptions of privacy controls. Related Controls:  PM-8, PM-9, PM-19. Control Enhancements:  None. References:  [PRIVACT], [OMB A-130]. PM-19 PRIVACY PROGRAM LEADERSHIP ROLE Control:  Appoint a senior agency official for privacy with the authority, mission, accountability, and resources to coordinate, develop, and implement, applicable privacy requirements and manage privacy risks through the organization-wide privacy program. Discussion: The privacy officer is an organizational official. For federal agencies— as defined by applicable laws, executive orders, directives, regulations, policies, standards, and guidelines— this official is designated as the senior agency official for privacy.', 'vec_doc-14-nist-sp-800-53-p240-908', 0, 238, 'v2.1.0', '03c255064f0fd74464e1f4af95abaeb949f23a1fc908c485a3bb9c6947e54fad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 213","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":908,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 213"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p240-909', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 213', 240, 'Organizations may also refer to this official as the chief privacy officer. The senior agency official for privacy also has roles on the data management board (see PM-23) and the data integrity board (see PM-24). Related Controls:  PM-18, PM-20, PM-23, PM-24, PM-27. Control Enhancements:  None. References:  [OMB A-130]. PM-20 DISSEMINATION OF PRIVACY PROGRAM INFORMATION Control:  Maintain a central resource webpage on the organization’s principal public website that serves as a central source of information about the organization’s privacy program and that: a. Ensures that the public has access to information about organizational privacy activities and can communicate with its senior agency official for privacy;', 'vec_doc-14-nist-sp-800-53-p240-909', 0, 181, 'v2.1.0', '7492263ffb771a11efc97f6f79c68e44ba22da9bc175ac22191db3dec614defa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 213","subsection":"UNKNOWN","table_id":null,"page":240,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":909,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 213"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p241-910', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 214', 241, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Ensures that organizational privacy practices and reports are publicly available; and c. Employs publicly facing email addresses and/or phone lines to enable the public to provide feedback and/or direct questions to privacy offices regarding privacy practices. Discussion:  For federal agencies, the webpage is located at www.[agency].gov/privacy. Federal agencies include public privacy impact assessments, system of records notices, computer matching notices and agreements, [PRIVACT] exemption and implementation rules, privacy reports, privacy policies, instructions for individuals making an access or amendment request, email addresses for questions/complaints, blogs, and periodic publications. Related Controls:  AC-3,  PM-19, PT-5, PT-6, PT-7, RA-8.', 'vec_doc-14-nist-sp-800-53-p241-910', 0, 214, 'v2.1.0', '0fd81eb246454d27639e624366ce9839cc5c4aa6f6d9a38c01355dd37c99f495', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 214","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":910,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 214"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p241-911', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 214', 241, 'Control Enhancements: (1) DISSEMINATION OF PRIVACY PROGRAM INFORMATION | PRIVACY POLICIES ON WEBSITES, APPLICATIONS, AND DIGITAL SERVICES Develop and post privacy policies on all external-facing websites, mobile applications, and other digital services, that: (a) Are written in plain language and organized in a way that is easy to understand and navigate; (b) Provide information needed by the public to make an informed decision about whether and how to interact with the organization; and (c) Are updated whenever the organization makes a substantive change to the practices it describes and includes a time/date stamp to inform the public of the date of the most recent changes. Discussion:  Organizations post privacy policies on all external-facing websites, mobile applications, and other digital services. Organizations post a link to the relevant privacy policy on any known, major entry points to the website, application, or digital service.', 'vec_doc-14-nist-sp-800-53-p241-911', 0, 239, 'v2.1.0', 'e9732f7a933c4f9e6911bfb9919361c82cd458343cc6966e95e1b3fbac0e0169', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 214","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":911,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 214"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p241-912', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 214', 241, 'In addition, organizations provide a link to the privacy policy on any webpage that collects personally identifiable information. Organizations may be subject to applicable laws, executive orders, directives, regulations, or policies that require the provision of specific information to the public. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements. Related Controls:  None. References:  [PRIVACT], [OMB A-130], [OMB M-17-06]. PM-21 ACCOUNTING OF DISCLOSURES Control: a. Develop and maintain an accurate accounting of disclosures of personally identifiable information, including:', 'vec_doc-14-nist-sp-800-53-p241-912', 0, 164, 'v2.1.0', '29225e61633a4531af64ec5df5eb48bba1535948a99f95b4029655c4e65bfc69', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 214","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":912,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 214"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p241-913', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Name and address, or other contact information of the individual or organization to', 241, 'which the disclosure was made; b. Retain the accounting of disclosures for the length of the time the personally identifiable information is maintained or five years after the disclosure is made, whichever is longer; and c. Make the accounting of disclosures available to the individual to whom the personally identifiable information relates upon request.', 'vec_doc-14-nist-sp-800-53-p241-913', 0, 89, 'v2.1.0', 'ec80b222dac918de00987305a6663507839c5ae9cf83be3cc609280723d22ec6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Name and address, or other contact information of the individual or organization to","subsection":"UNKNOWN","table_id":null,"page":241,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":913,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Name and address, or other contact information of the individual or organization to"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p242-914', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 215', 242, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The purpose of accounting of disclosures is to allow individuals to learn to whom their personally identifiable information has been disclosed, to provide a basis for subsequently advising recipients of any corrected or disputed personally identifiable information, and to provide an audit trail for subsequent reviews of organizational compliance with conditions for disclosures. For federal agencies, keeping an accounting of disclosures is required by the [PRIVACT]; agencies should consult with their senior agency official for privacy and legal counsel on this requirement and be aware of the statutory exceptions and OMB guidance relating to the provision. Organizations can use any system for keeping notations of disclosures, if it can construct from such a system, a document listing of all disclosures along with the required information.', 'vec_doc-14-nist-sp-800-53-p242-914', 0, 239, 'v2.1.0', 'b166bf0a182cdbcad2d9800f9f61ce27587838a54d2f3045f84ffcddcdf8bfdb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 215","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":914,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 215"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p242-915', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 215', 242, 'Automated mechanisms can be used by organizations to determine when personally identifiable information is disclosed, including commercial services that provide notifications and alerts. Accounting of disclosures may also be used to help organizations verify compliance with applicable privacy statutes and policies governing the disclosure or dissemination of information and dissemination restrictions. Related Controls:  AC-3, AU-2, PT-2. Control Enhancements:  None. References:  [PRIVACT], [OMB A-130]. PM-22 PERSONALLY IDENTIFIABLE INFORMATION QUALITY MANAGEMENT Control:  Develop and document organization-wide policies and procedures for: a. Reviewing for the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle; b. Correcting or deleting inaccurate or outdated personally identifiable information; c.', 'vec_doc-14-nist-sp-800-53-p242-915', 0, 220, 'v2.1.0', 'b312a29390c9764430a41a828c12fca34a2046a1058c53ad435bb321e1479046', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 215","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":915,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 215"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p242-916', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 215', 242, 'Disseminating notice of corrected or deleted personally identifiable information to individuals or other appropriate entities; and d. Appeals of adverse decisions on correction or deletion requests. Discussion:  Personally identifiable information quality management includes steps that organizations take to confirm the accuracy and relevance of personally identifiable information throughout the information life cycle. The information life cycle includes the creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposition of personally identifiable information. Organizational policies and procedures for personally identifiable information quality management are important because inaccurate or outdated personally identifiable information maintained by organizations may cause problems for individuals.', 'vec_doc-14-nist-sp-800-53-p242-916', 0, 212, 'v2.1.0', 'b8179ba3e0176507bfe4e45d294dee2b0bccd6b264ad5dc05499297c6781b3a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 215","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":916,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 215"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p242-917', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 215', 242, 'Organizations consider the quality of personally identifiable information involved in business functions where inaccurate information may result in adverse decisions or the denial of benefits and services, or the disclosure of the information may cause stigmatization. Correct information, in certain circumstances, can cause problems for individuals that outweigh the benefits of organizations maintaining the information. Organizations consider creating policies and procedures for the removal of such information. The senior agency official for privacy ensures that practical means and mechanisms exist and are accessible for individuals or their authorized representatives to seek the correction or deletion of personally identifiable information. Processes for correcting or deleting data are clearly defined and publicly available.', 'vec_doc-14-nist-sp-800-53-p242-917', 0, 210, 'v2.1.0', '4426097764e74c17df24c54bf6555be35565686b760e54b6fb648f769723b885', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 215","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":917,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 215"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p242-918', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 215', 242, 'Organizations use discretion in determining whether data is to be deleted or corrected based on the scope of requests, the changes sought, and the impact of the changes. Additionally, processes include the provision of responses to individuals of decisions to deny requests for correction or deletion. The responses include the reasons for the decisions, a means', 'vec_doc-14-nist-sp-800-53-p242-918', 0, 91, 'v2.1.0', '9c0676f37858b5b56a9028f4824260fa29e0beac21418c1d3cd42d34bbbfa01d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 215","subsection":"UNKNOWN","table_id":null,"page":242,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":918,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 215"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p243-919', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 216', 243, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 to record individual objections to the decisions, and a means of requesting reviews of the initial determinations. Organizations notify individuals or their designated representatives when their personally identifiable information is corrected or deleted to provide transparency and confirm the completed action. Due to the complexity of data flows and storage, other entities may need to be informed of the correction or deletion. Notice supports the consistent correction and deletion of personally identifiable information across the data ecosystem. Related Controls:  PM-23, SI-18. Control Enhancements:  None. References:  [OMB A-130], [OMB M-19-15], [SP 800-188]. PM-23 DATA GOVERNANCE BODY Control:  Establish a Data Governance Body consisting of [Assignment: organization-defined roles] with [Assignment: organization-defined responsibilities].', 'vec_doc-14-nist-sp-800-53-p243-919', 0, 236, 'v2.1.0', '03b3f13c5b5a2b44e27e413da694e46d87b458dbda1af42651d785d3a15c5809', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 216","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":919,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 216"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p243-920', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 216', 243, 'Discussion:  A Data Governance Body can help ensure that the organization has coherent policies and the ability to balance the utility of data with security and privacy requirements. The Data Governance Body establishes policies, procedures, and standards that facilitate data governance so that data, including personally identifiable information, is effectively managed and maintained in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidance. Responsibilities can include developing and implementing guidelines that support data modeling, quality, integrity, and the de-identification needs of personally identifiable information across the information life cycle as well as reviewing and approving applications to release data outside of the organization, archiving the applications and the released data, and performing post-release monitoring to ensure that the assumptions made as part of the data release continue to be valid.', 'vec_doc-14-nist-sp-800-53-p243-920', 0, 248, 'v2.1.0', '506204aa33709d375f3756aacd1423bbf79f868172ae129c792cb4e7e4450e08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 216","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":920,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 216"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p243-921', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 216', 243, 'Members include the chief information officer, senior agency information security officer, and senior agency official for privacy. Federal agencies are required to establish a Data Governance Body with specific roles and responsibilities in accordance with the [ EVIDACT] and policies set forth under [OMB M-19-23]. Related Controls:  AT-2, AT-3, PM-19, PM-22, PM-24, PT-7, SI-4, SI-19. Control Enhancements:  None. References:  [EVIDACT], [OMB A-130], [OMB M-19-23], [SP 800-188]. PM-24 DATA INTEGRITY BOARD Control:  Establish a Data Integrity Board to: a. Review proposals to conduct or participate in a matching program; and b. Conduct an annual review of all matching programs in which the agency has participated.', 'vec_doc-14-nist-sp-800-53-p243-921', 0, 180, 'v2.1.0', 'b669798c72dbc2299229449b9530a4ba2fb10416b6015c44205958bc749be493', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 216","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":921,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 216"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p243-922', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 216', 243, 'Discussion:  A Data Integrity Board is the board of senior officials designated by the head of a federal agency and is responsible for, among other things, reviewing the agency’s proposals to conduct or participate in a matching program and conducting an annual review of all matching programs in which the agency has participated. As a general matter, a matching program is a computerized comparison of records from two or more automated [ PRIVACT] systems of records or an automated system of records and automated records maintained by a non-federal agency (or agent thereof). A matching program either pertains to Federal benefit programs or Federal personnel or payroll records. At a minimum, the Data Integrity Board includes the Inspector General of the agency, if any, and the senior agency official for privacy. Related Controls:  AC-4, PM-19, PM-23, PT-2, PT-8.', 'vec_doc-14-nist-sp-800-53-p243-922', 0, 218, 'v2.1.0', 'a2164aa893bfe8d2e1e191615c96233ae296e836cd819d4c8ae78ee96e9761fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 216","subsection":"UNKNOWN","table_id":null,"page":243,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":922,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 216"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p244-923', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 217', 244, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None. References:  [PRIVACT], [OMB A-130], [OMB A-108]. PM-25 MINIMIZATION OF PERSONALLY IDENTIFIABLE INFORMATION USED IN TESTING, TRAINING, AND RESEARCH Control: a. Develop, document, and implement policies and procedures that address the use of personally identifiable information for internal testing, training, and research; b. Limit or minimize the amount of personally identifiable information used for internal testing, training, and research purposes; c. Authorize the use of personally identifiable information when such information is required for internal testing, training, and research; and d. Review and update policies and procedures [Assignment: organization-defined frequency]. Discussion:  The use of personally identifiable information in testing, research, and training increases the risk of unauthorized disclosure or misuse of such information.', 'vec_doc-14-nist-sp-800-53-p244-923', 0, 246, 'v2.1.0', '111e673a1d29b7044f34ac74a4e9e148fe5fb3ded9346d489783cc017b89b24b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 217","subsection":"UNKNOWN","table_id":null,"page":244,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":923,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 217"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p244-924', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 217', 244, 'Organizations consult with the senior agency official for privacy and/or legal counsel to ensure that the use of personally identifiable information in testing, training, and research is compatible with the original purpose for which it was collected. When possible, organizations use placeholder data to avoid exposure of personally identifiable information when conducting testing, training, and research. Related Controls:  PM-23, PT-3, SA-3, SA-8, SI-12. Control Enhancements:  None. References:  [OMB A-130]. PM-26 COMPLAINT MANAGEMENT Control:  Implement a process for receiving and responding to complaints, concerns, or questions from individuals about the organizational security and privacy practices that includes: a. Mechanisms that are easy to use and readily accessible by the public; b. All information necessary for successfully filing complaints; c. Tracking mechanisms to ensure all complaints received are reviewed and addressed within [Assignment: organization-defined time period]; d.', 'vec_doc-14-nist-sp-800-53-p244-924', 0, 252, 'v2.1.0', 'ea017c042cf06b7f23fb345a0b5c1e2f42bb1250b1a4a426d1e4daec4ec7e00b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 217","subsection":"UNKNOWN","table_id":null,"page":244,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":924,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 217"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p244-925', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 217', 244, 'Acknowledgement of receipt of complaints, concerns, or questions from individuals within [Assignment: organization-defined time period]; and e. Response to complaints, concerns, or questions from individuals within [Assignment: organization-defined time period]. Discussion:  Complaints, concerns, and questions from individuals can serve as valuable sources of input to organizations and ultimately improve operational models, uses of technology, data collection practices, and controls. Mechanisms that can be used by the public include telephone hotline, email, or web-based forms. The information necessary for successfully filing complaints includes contact information for the senior agency official for privacy or other official designated to receive complaints. Privacy complaints may also include personally identifiable information which is handled in accordance with relevant policies and processes. Related Controls:  IR-7, IR-9, PM-22, SI-18.', 'vec_doc-14-nist-sp-800-53-p244-925', 0, 239, 'v2.1.0', '882a1f0423cc1a16bf37ffee4e7ef027dac646f34f4140390fcf9bd11dcc2b0d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 217","subsection":"UNKNOWN","table_id":null,"page":244,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":925,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 217"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p245-926', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 218', 245, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None. References:  [OMB A-130]. PM-27 PRIVACY REPORTING Control: a. Develop [Assignment: organization-defined privacy reports] and disseminate to:', 'vec_doc-14-nist-sp-800-53-p245-926', 0, 66, 'v2.1.0', '90bda42947e9f29630d5e4efba1d25f542ee8fd9dc987c58b98c6ba23223495b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 218","subsection":"UNKNOWN","table_id":null,"page":245,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":926,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 218"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p245-927', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Assignment: organization-defined oversight bodies] to demonstrate accountability with', 245, 'statutory, regulatory, and policy privacy mandates; and', 'vec_doc-14-nist-sp-800-53-p245-927', 0, 14, 'v2.1.0', '9fa229c58fdd1acc43a2d9701248920b93a957afa149cf8fef33683645e73893', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Assignment: organization-defined oversight bodies] to demonstrate accountability with","subsection":"UNKNOWN","table_id":null,"page":245,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":927,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Assignment: organization-defined oversight bodies] to demonstrate accountability with"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p245-928', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. [Assignment: organization-defined officials] and other personnel with responsibility for', 245, 'monitoring privacy program compliance; and b. Review and update privacy reports [Assignment: organization-defined frequency]. Discussion:  Through internal and external reporting, organizations promote accountability and transparency in organizational privacy operations. Reporting can also help organizations to determine progress in meeting privacy compliance requirements and privacy controls, compare performance across the federal government, discover vulnerabilities, identify gaps in policy and implementation, and identify models for success. For federal agencies, privacy reports include annual senior agency official for privacy reports to OMB, reports to Congress required by Implementing Regulations of the 9/11 Commission Act, and other public reports required by law, regulation, or policy, including internal policies of organizations. The senior agency official for privacy consults with legal counsel, where appropriate, to ensure that organizations meet all applicable privacy reporting requirements. Related Controls:  IR-9, PM-19. Control Enhancements:  None. References:  [FISMA], [OMB A-130], [OMB A-108]. PM-28 RISK FRAMING Control: a. Identify and document:', 'vec_doc-14-nist-sp-800-53-p245-928', 0, 296, 'v2.1.0', 'f7a3ddba30621c72cbbbdf694c75ed8abb882c09d5f30df32e3c078882406add', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. [Assignment: organization-defined officials] and other personnel with responsibility for","subsection":"UNKNOWN","table_id":null,"page":245,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":928,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. [Assignment: organization-defined officials] and other personnel with responsibility for"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p245-929', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Organizational risk tolerance;', 245, 'b. Distribute the results of risk framing activities to [Assignment: organization-defined personnel]; and c. Review and update risk framing considerations [Assignment: organization-defined frequency]. Discussion:  Risk framing is most effective when conducted at the organization level and in consultation with stakeholders throughout the organization including mission, business, and system owners. The assumptions, constraints, risk tolerance, priorities, and trade-offs identified as part of the risk framing process inform the risk management strategy, which in turn informs the conduct of risk assessment, risk response, and risk monitoring activities. Risk framing results are shared with organizational personnel, including mission and business owners, information', 'vec_doc-14-nist-sp-800-53-p245-929', 0, 193, 'v2.1.0', '49d60ab1bea66bfbab87c3a8168579bf3a07d8569fff47f664104fdfd8054adf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Organizational risk tolerance;","subsection":"UNKNOWN","table_id":null,"page":245,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":929,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Organizational risk tolerance;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p246-930', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 219', 246, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 owners or stewards, system owners, authorizing officials, senior agency information security officer, senior agency official for privacy, and senior accountable official for risk management. Related Controls:  CA-7, PM-9, RA-3, RA-7. Control Enhancements:  None. References:  [OMB A-130], [SP 800-39]. PM-29 RISK MANAGEMENT PROGRAM LEADERSHIP ROLES Control: a. Appoint a Senior Accountable Official for Risk Management to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; and b. Establish a Risk Executive (function) to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization. Discussion:  The senior accountable official for risk management leads the risk executive (function) in organization-wide risk management activities.', 'vec_doc-14-nist-sp-800-53-p246-930', 0, 245, 'v2.1.0', 'f00221e0a513c46353d531f106875e1535e8e9c3e2543523ba4a6f611fcd8e90', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 219","subsection":"UNKNOWN","table_id":null,"page":246,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":930,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 219"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p246-931', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 219', 246, 'Related Controls:  PM-2, PM-19. Control Enhancements:  None. References:  [SP 800-37], [SP 800-181]. PM-30 SUPPLY CHAIN RISK MANAGEMENT STRATEGY Control: a. Develop an organization-wide strategy for managing supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services; b. Implement the supply chain risk management strategy consistently across the organization; and c. Review and update the supply chain risk management strategy on [Assignment: organization-defined frequency] or as required, to address organizational changes.', 'vec_doc-14-nist-sp-800-53-p246-931', 0, 153, 'v2.1.0', '998c1e3c1572587353b8710e1f07ca20dd43c454545cf00d92171893e31ab2b7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 219","subsection":"UNKNOWN","table_id":null,"page":246,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":931,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 219"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p246-932', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 219', 246, 'Discussion:  An organization-wide supply chain risk management strategy includes an unambiguous expression of the supply chain risk appetite and tolerance for the organization, acceptable supply chain risk mitigation strategies or controls, a process for consistently evaluating and monitoring supply chain risk, approaches for implementing and communicating the supply chain risk management strategy, and the associated roles and responsibilities. Supply chain risk management includes considerations of the security and privacy risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services. The supply chain risk management strategy can be incorporated into the organization’s overarching risk management strategy and can guide and inform supply chain policies and system-level supply chain risk management plans.', 'vec_doc-14-nist-sp-800-53-p246-932', 0, 221, 'v2.1.0', 'd1616dcd8171e0ac3c1a14fe2269c7183c775f8b20f205badfc2922db098f6aa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 219","subsection":"UNKNOWN","table_id":null,"page":246,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":932,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 219"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p246-933', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 219', 246, 'In addition, the use of a risk executive function can facilitate a consistent, organization-wide application of the supply chain risk management strategy. The supply chain risk management strategy is implemented at the organization and mission/business levels, whereas the supply chain risk management plan (see SR-2) is implemented at the system level. Related Controls:  CM-10, PM-9, SR-1, SR-2, SR-3, SR-4, SR-5, SR-6, SR-7, SR-8, SR-9, SR-11. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p246-933', 0, 117, 'v2.1.0', 'bf4c50b76daef3a8bda9e60835f2dc44ba62aa1a5ac3be01225e5424d4bc17c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 219","subsection":"UNKNOWN","table_id":null,"page":246,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":933,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 219"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p247-934', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 220', 247, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) SUPPLY CHAIN RISK MANAGEMENT STRATEGY | SUPPLIERS OF CRITICAL OR MISSION-ESSENTIAL ITEMS Identify, prioritize, and assess suppliers of critical or mission-essential technologies, products, and services. Discussion:  The identification and prioritization of suppliers of critical or mission-essential technologies, products, and services is paramount to the mission/business success of organizations. The assessment of suppliers is conducted using supplier reviews (see SR-6) and supply chain risk assessment processes (see RA-3(1)). An analysis of supply chain risk can help an organization identify systems or components for which additional supply chain risk mitigations are required. Related Controls:  RA-3, SR-6. References:  [PRIVACT], [FASC18], [EO 13873], [41 CFR 201], [OMB A-130], [OMB M-17-06] [CNSSD 505], [ISO 27036], [ISO 20243], [SP 800-161], [IR 8272].', 'vec_doc-14-nist-sp-800-53-p247-934', 0, 241, 'v2.1.0', '56ea2e15ca7b5b0fcfaeee05e1c03fec9270c41a4cfd40a44f3f78fc0f8a5eb3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 220","subsection":"UNKNOWN","table_id":null,"page":247,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":934,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 220"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p247-935', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 220', 247, 'PM-31 CONTINUOUS MONITORING STRATEGY Control:  Develop an organization-wide continuous monitoring strategy and implement continuous monitoring programs that include: a. Establishing the following organization-wide metrics to be monitored: [Assignment: organization-defined metrics]; b. Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness; c. Ongoing monitoring of organizationally-defined metrics in accordance with the continuous monitoring strategy; d. Correlation and analysis of information generated by control assessments and monitoring; e. Response actions to address results of the analysis of control assessment and monitoring information; and f. Reporting the security and privacy status of organizational systems to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency].', 'vec_doc-14-nist-sp-800-53-p247-935', 0, 235, 'v2.1.0', 'b4d7d84df01ec3ca0544c9e75550d38619920ffea08712daf781188a6f104a3e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 220","subsection":"UNKNOWN","table_id":null,"page":247,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":935,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 220"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p247-936', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 220', 247, 'Discussion:  Continuous monitoring at the organization level facilitates ongoing awareness of the security and privacy posture across the organization to support organizational risk management decisions. The terms “continuous” and “ongoing” imply that organizations assess and monitor their controls and risks at a frequency sufficient to support risk-based decisions. Different types of controls may require different monitoring frequencies. The results of continuous monitoring guide and inform risk response actions by organizations. Continuous monitoring programs allow organizations to maintain the authorizations of systems and common controls in highly dynamic environments of operation with changing mission and business needs, threats, vulnerabilities, and technologies.', 'vec_doc-14-nist-sp-800-53-p247-936', 0, 195, 'v2.1.0', 'c9a36eb443cbcf238465d8f6f15df33eca7955b473d42f07873f094c809e3bfd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 220","subsection":"UNKNOWN","table_id":null,"page":247,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":936,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 220"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p247-937', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 220', 247, 'Having access to security- and privacy-related information on a continuing basis through reports and dashboards gives organizational officials the capability to make effective, timely, and informed risk management decisions, including ongoing authorization decisions. To further facilitate security and privacy risk management, organizations consider aligning organization-defined monitoring metrics with organizational risk tolerance as defined in the risk management strategy. Monitoring requirements, including the need for monitoring, may be referenced in other controls and control enhancements such as, AC-2g, AC-2(7), AC-2(12)(a), AC-2(7)(b), AC-2(7)(c), AC-17(1), AT-4a, AU-13, AU-13(1), AU-13(2), CA-7, CM-3f, CM-6d, CM-11c, IR-5, MA-2b, MA-3a, MA-4a, PE-3d, PE-6, PE-14b, PE-16, PE-20, PM-6, PM-23, PS-7e, SA-9c, SC- 5(3)(b), SC-7a, SC-7(24)(b), SC-18b, SC-43b, SI-4.', 'vec_doc-14-nist-sp-800-53-p247-937', 0, 220, 'v2.1.0', 'cc7f9f963fd96f0ef52868cef0342e1f4cc6f87ec90cc6de696574643ea57f49', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 220","subsection":"UNKNOWN","table_id":null,"page":247,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":937,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 220"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p247-938', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 220', 247, 'Related Controls:  AC-2, AC-6, AC-17, AT-4, AU-6, AU-13, CA-2, CA-5, CA-6, CA-7, CM-3, CM-4, CM-6, CM-11, IA-5, IR-5, MA-2, MA-3, MA-4, PE-3, PE-6, PE-14, PE-16, PE-20, PL-2, PM-4, PM-6,', 'vec_doc-14-nist-sp-800-53-p247-938', 0, 47, 'v2.1.0', '9a626d1357ab2adc8800d5e93bdd13c56384246badf5eefd192bd1e455935255', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 220","subsection":"UNKNOWN","table_id":null,"page":247,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":938,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 220"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p248-939', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 221', 248, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PM-9, PM-10, PM-12, PM-14, PM-23, PM-28, PS-7, PT-7, RA-3, RA-5, RA-7, SA-9, SA-11, SC-5, SC- 7, SC-18, SC-38, SC-43, SI-3, SI-4, SI-12, SR-2, SR-4. References:  [SP 800-37], [SP 800-39], [SP 800-137], [SP 800-137A]. PM-32 PURPOSING Control:  Analyze [Assignment: organization-defined systems or systems components] supporting mission essential services or functions to ensure that the information resources are being used consistent with their intended purpose. Discussion:  Systems are designed to support a specific mission or business function. However, over time, systems and system components may be used to support services and functions that are outside of the scope of the intended mission or business functions. This can result in exposing information resources to unintended environments and uses that can significantly increase threat exposure. In doing so, the systems are more vulnerable to compromise, which can ultimately impact the services and functions for which they were intended. This is especially impactful for mission-essential services and functions. By analyzing resource use, organizations can identify such potential exposures. Related Controls:  CA-7, PL-2, RA-3, RA-9. Control Enhancements:  None. References:  [SP 800-160-1], [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p248-939', 0, 342, 'v2.1.0', '8d45a09157adc9919c82237fc8fc4a84ed805b71d7566d94956b6dc842c2ab16', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 221","subsection":"UNKNOWN","table_id":null,"page":248,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":939,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 221"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p249-940', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.14   PERSONNEL SECURITY', 249, 'Quick link to Personnel Security Summary Table PS-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p249-940', 0, 45, 'v2.1.0', '626fcdc4e01b5ea54625f3bf0f1e65433f14bd3c138cd06c75ba5ae1ee6818b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.14   PERSONNEL SECURITY","subsection":"UNKNOWN","table_id":null,"page":249,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":940,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.14   PERSONNEL SECURITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p249-941', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 249, 'level] personnel security policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p249-941', 0, 76, 'v2.1.0', '6b35d0f441726c654a54dffacdd3dde51635b0fb66e1b4cd657ea0acbd322b56', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":249,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":941,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p249-942', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the personnel security policy and the', 249, 'associated personnel security controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personnel security policy and procedures; and c. Review and update the current personnel security:', 'vec_doc-14-nist-sp-800-53-p249-942', 0, 67, 'v2.1.0', '1dd1d63561107b19fc14dc38fdb59bc1ef28073ce482932e76cb439aed088ad5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the personnel security policy and the","subsection":"UNKNOWN","table_id":null,"page":249,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":942,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the personnel security policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p249-943', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 249, 'organization-defined events]. Discussion:  Personnel security policy and procedures for the controls in the PS family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on their development. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission level or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to personnel security policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p249-943', 0, 420, 'v2.1.0', 'c98b7ee9894437d988029b745db5bce3a21bf2addc673adca5962fb9b452f2e1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":249,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":943,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p250-944', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 223', 250, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PS-2 POSITION RISK DESIGNATION Control: a. Assign a risk designation to all organizational positions; b. Establish screening criteria for individuals filling those positions; and c. Review and update position risk designations [Assignment: organization-defined frequency]. Discussion:  Position risk designations reflect Office of Personnel Management (OPM) policy and guidance. Proper position designation is the foundation of an effective and consistent suitability and personnel security program. The Position Designation System (PDS) assesses the duties and responsibilities of a position to determine the degree of potential damage to the efficiency or integrity of the service due to misconduct of an incumbent of a position and establishes the risk level of that position.', 'vec_doc-14-nist-sp-800-53-p250-944', 0, 218, 'v2.1.0', '9a9667e5573b1540accd3f1828ecddfe30c644e3797d4539738a8c8717026b42', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 223","subsection":"UNKNOWN","table_id":null,"page":250,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":944,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 223"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p250-945', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 223', 250, 'The PDS assessment also determines if the duties and responsibilities of the position present the potential for position incumbents to bring about a material adverse effect on national security and the degree of that potential effect, which establishes the sensitivity level of a position. The results of the assessment determine what level of investigation is conducted for a position. Risk designations can guide and inform the types of authorizations that individuals receive when accessing organizational information and information systems. Position screening criteria include explicit information security role appointment requirements. Parts 1400 and 731 of Title 5, Code of Federal Regulations, establish the requirements for organizations to evaluate relevant covered positions for a position sensitivity and position risk designation commensurate with the duties and responsibilities of those positions. Related Controls:  AC-5, AT-3, PE-2, PE-3, PL-2, PS-3, PS-6, SA-5, SA-21, SI-12.', 'vec_doc-14-nist-sp-800-53-p250-945', 0, 249, 'v2.1.0', '26c6b1cc526320fd490096015962b99476c78bf7ca225fb4742f389ce574cfb4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 223","subsection":"UNKNOWN","table_id":null,"page":250,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":945,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 223"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p250-946', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 223', 250, 'Control Enhancements:  None. References:  [5 CFR 731], [SP 800-181]. PS-3 PERSONNEL SCREENING Control: a. Screen individuals prior to authorizing access to the system; and b. Rescreen individuals in accordance with [Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening]. Discussion:  Personnel screening and rescreening activities reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, and specific criteria established for the risk designations of assigned positions. Examples of personnel screening include background investigations and agency checks. Organizations may define different rescreening conditions and frequencies for personnel accessing systems based on types of information processed, stored, or transmitted by the systems. Related Controls:  AC-2, IA-4, MA-5, PE-2, PM-12, PS-2, PS-6, PS-7, SA-21.', 'vec_doc-14-nist-sp-800-53-p250-946', 0, 236, 'v2.1.0', '029a5fa4dcb6fb96b4dc7d50120f095cc0758e4f1928fa97fccaed3b934b4278', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 223","subsection":"UNKNOWN","table_id":null,"page":250,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":946,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 223"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p250-947', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 223', 250, 'Control Enhancements: (1) PERSONNEL SCREENING | CLASSIFIED INFORMATION Verify that individuals accessing a system processing, storing, or transmitting classified information are cleared and indoctrinated to the highest classification level of the information to which they have access on the system. Discussion:  Classified information is the most sensitive information that the Federal Government processes, stores, or transmits. It is imperative that individuals have the requisite security clearances and system access authorizations prior to gaining access to such', 'vec_doc-14-nist-sp-800-53-p250-947', 0, 142, 'v2.1.0', 'e8144620e9e0180aff73c78045f83d665bf362eeffb22478a1db2d3b281961f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 223","subsection":"UNKNOWN","table_id":null,"page":250,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":947,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 223"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p251-948', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 224', 251, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 information. Access authorizations are enforced by system access controls (see AC-3) and flow controls (see AC-4). Related Controls:  AC-3, AC-4. (2) PERSONNEL SCREENING | FORMAL INDOCTRINATION Verify that individuals accessing a system processing, storing, or transmitting types of classified information that require formal indoctrination, are formally indoctrinated for all the relevant types of information to which they have access on the system. Discussion:  Types of classified information that require formal indoctrination include Special Access Program (SAP), Restricted Data (RD), and Sensitive Compartmented Information (SCI). Related Controls:  AC-3, AC-4.', 'vec_doc-14-nist-sp-800-53-p251-948', 0, 191, 'v2.1.0', '0d2b7bb6413c2d5f57be59b03f46d8bfbe7936815770142dfa5c784510e9c09c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 224","subsection":"UNKNOWN","table_id":null,"page":251,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":948,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 224"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p251-949', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 224', 251, '(3) PERSONNEL SCREENING | INFORMATION REQUIRING SPECIAL PROTECTIVE MEASURES Verify that individuals accessing a system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy [Assignment: organization-defined additional personnel screening criteria]. Discussion:  Organizational information that requires special protection includes controlled unclassified information. Personnel security criteria include position sensitivity background screening requirements. Related Controls:  None. (4) PERSONNEL SCREENING | CITIZENSHIP REQUIREMENTS Verify that individuals accessing a system processing, storing, or transmitting [Assignment: organization-defined information types] meet [Assignment: organization-defined citizenship requirements]. Discussion:  None. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p251-949', 0, 230, 'v2.1.0', '3f2fe4aeca32515c1a934649de6989b13704b704229926b9f40df5b764c93e5e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 224","subsection":"UNKNOWN","table_id":null,"page":251,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":949,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 224"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p251-950', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 224', 251, 'References:  [EO 13526], [EO 13587], [FIPS 199], [FIPS 201-2], [SP 800-60-1], [SP 800-60-2], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4]. PS-4 PERSONNEL TERMINATION Control:  Upon termination of individual employment: a. Disable system access within [Assignment: organization-defined time period]; b. Terminate or revoke any authenticators and credentials associated with the individual; c. Conduct exit interviews that include a discussion of [Assignment: organization-defined information security topics]; d. Retrieve all security-related organizational system-related property; and e. Retain access to organizational information and systems formerly controlled by terminated individual. Discussion:  System property includes hardware authentication tokens, system administration technical manuals, keys, identification cards, and building passes.', 'vec_doc-14-nist-sp-800-53-p251-950', 0, 213, 'v2.1.0', '21202c9c1c3dc24b81fd01ef0e0632ba76de16593f0b6d82dbc43afd92033937', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 224","subsection":"UNKNOWN","table_id":null,"page":251,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":950,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 224"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p251-951', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 224', 251, 'Exit interviews ensure that terminated individuals understand the security constraints imposed by being former employees and that proper accountability is achieved for system-related property. Security topics at exit interviews include reminding individuals of nondisclosure agreements and potential limitations on future employment. Exit interviews may not always be possible for some individuals, including', 'vec_doc-14-nist-sp-800-53-p251-951', 0, 102, 'v2.1.0', '3accaf14fc86398dabd51c6811b2e12cddadfd4de1bd8372cba910468292110d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 224","subsection":"UNKNOWN","table_id":null,"page":251,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":951,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 224"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p252-952', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 225', 252, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 in cases related to the unavailability of supervisors, illnesses, or job abandonment. Exit interviews are important for individuals with security clearances. The timely execution of termination actions is essential for individuals who have been terminated for cause. In certain situations, organizations consider disabling the system accounts of individuals who are being terminated prior to the individuals being notified. Related Controls:  AC-2, IA-4, PE-2, PM-12, PS-6, PS-7. Control Enhancements: (1) PERSONNEL TERMINATION | POST-EMPLOYMENT REQUIREMENTS (a) Notify terminated individuals of applicable, legally binding post-employment requirements for the protection of organizational information; and (b) Require terminated individuals to sign an acknowledgment of post-employment requirements as part of the organizational termination process.', 'vec_doc-14-nist-sp-800-53-p252-952', 0, 236, 'v2.1.0', '91c5312804aaaae8f83dfec301ace32bec046c779ed479aabf48517d08eb9613', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 225","subsection":"UNKNOWN","table_id":null,"page":252,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":952,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 225"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p252-953', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 225', 252, 'Discussion:  Organizations consult with the Office of the General Counsel regarding matters of post-employment requirements on terminated individuals. Related Controls:  None. (2) PERSONNEL TERMINATION | AUTOMATED ACTIONS Use [Assignment: organization-defined automated mechanisms] to [Selection (one or more): notify [Assignment: organization-defined personnel or roles] of individual termination actions; disable access to system resources]. Discussion:  In organizations with many employees, not all personnel who need to know about termination actions receive the appropriate notifications, or if such notifications are received, they may not occur in a timely manner. Automated mechanisms can be used to send automatic alerts or notifications to organizational personnel or roles when individuals are terminated. Such automatic alerts or notifications can be conveyed in a variety of ways, including via telephone, electronic mail, text message, or websites.', 'vec_doc-14-nist-sp-800-53-p252-953', 0, 241, 'v2.1.0', 'b959f54faef95f831e3fae0412ed835a70e385fdcb19d520c229d9369c6fb203', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 225","subsection":"UNKNOWN","table_id":null,"page":252,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":953,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 225"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p252-954', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 225', 252, 'Automated mechanisms can also be employed to quickly and thoroughly disable access to system resources after an employee is terminated. Related Controls:  None. References:  None. PS-5 PERSONNEL TRANSFER Control: a. Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiate [Assignment: organization-defined transfer or reassignment actions] within [Assignment: organization-defined time period following the formal transfer action]; c. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period].', 'vec_doc-14-nist-sp-800-53-p252-954', 0, 213, 'v2.1.0', 'b8808502511bb60214d08a57d7d26d7901aec774572c048b0bd670ff84858991', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 225","subsection":"UNKNOWN","table_id":null,"page":252,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":954,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 225"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p252-955', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 225', 252, 'Discussion:  Personnel transfer applies when reassignments or transfers of individuals are permanent or of such extended duration as to make the actions warranted. Organizations define actions appropriate for the types of reassignments or transfers, whether permanent or extended. Actions that may be required for personnel transfers or reassignments to other positions within', 'vec_doc-14-nist-sp-800-53-p252-955', 0, 94, 'v2.1.0', '36d70e7c47c8cc9cdce937470bbfdb35b0fd32416c2e482ecfb530d223be60f7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 225","subsection":"UNKNOWN","table_id":null,"page":252,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":955,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 225"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p253-956', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 226', 253, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 organizations include returning old and issuing new keys, identification cards, and building passes; closing system accounts and establishing new accounts; changing system access authorizations (i.e., privileges); and providing for access to official records to which individuals had access at previous work locations and in previous system accounts. Related Controls:  AC-2, IA-4, PE-2, PM-12, PS-4, PS-7. Control Enhancements:  None. References:  None. PS-6 ACCESS AGREEMENTS Control: a. Develop and document access agreements for organizational systems; b. Review and update the access agreements [Assignment: organization-defined frequency]; and c. Verify that individuals requiring access to organizational information and systems:', 'vec_doc-14-nist-sp-800-53-p253-956', 0, 207, 'v2.1.0', '1c97612e5a00cfa89b197d281b7b9049ccd99e56886fe14182bc0518b7fc0421', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 226","subsection":"UNKNOWN","table_id":null,"page":253,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":956,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 226"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p253-957', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Re-sign access agreements to maintain access to organizational systems when access', 253, 'agreements have been updated or [Assignment: organization-defined frequency]. Discussion:  Access agreements include nondisclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements. Signed access agreements include an acknowledgement that individuals have read, understand, and agree to abide by the constraints associated with organizational systems to which access is authorized. Organizations can use electronic signatures to acknowledge access agreements unless specifically prohibited by organizational policy. Related Controls:  AC-17, PE-2, PL-4, PS-2, PS-3, PS-6, PS-7, PS-8, SA-21, SI-12. Control Enhancements: (1) ACCESS AGREEMENTS | INFORMATION REQUIRING SPECIAL PROTECTION [Withdrawn: Incorporated into PS-3.] (2) ACCESS AGREEMENTS | CLASSIFIED INFORMATION REQUIRING SPECIAL PROTECTION Verify that access to classified information requiring special protection is granted only to individuals who: (a) Have a valid access authorization that is demonstrated by assigned official government duties; (b) Satisfy associated personnel security criteria; and (c) Have read, understood, and signed a nondisclosure agreement. Discussion:  Classified information that requires special protection includes collateral information, Special Access Program (SAP) information, and Sensitive Compartmented Information (SCI). Personnel security criteria reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  None. (3) ACCESS AGREEMENTS | POST-EMPLOYMENT REQUIREMENTS (a) Notify individuals of applicable, legally binding post-employment requirements for protection of organizational information; and', 'vec_doc-14-nist-sp-800-53-p253-957', 0, 427, 'v2.1.0', '06d0674934260c7c06d3cbc34a7320c2123480f5ed27ea3a4e8f4ab1dffdd135', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Re-sign access agreements to maintain access to organizational systems when access","subsection":"UNKNOWN","table_id":null,"page":253,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":957,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Re-sign access agreements to maintain access to organizational systems when access"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p254-958', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 227', 254, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Require individuals to sign an acknowledgment of these requirements, if applicable, as part of granting initial access to covered information. Discussion:  Organizations consult with the Office of the General Counsel regarding matters of post-employment requirements on terminated individuals. Related Controls:  PS-4. References:  None. PS-7 EXTERNAL PERSONNEL SECURITY Control: a. Establish personnel security requirements, including security roles and responsibilities for external providers; b. Require external providers to comply with personnel security policies and procedures established by the organization; c. Document personnel security requirements; d.', 'vec_doc-14-nist-sp-800-53-p254-958', 0, 190, 'v2.1.0', '1f53b3031a508194337f1a50e15e81a61978a5ca5bd42eb5aab33f0e5e27c62e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 227","subsection":"UNKNOWN","table_id":null,"page":254,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":958,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 227"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p254-959', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 227', 254, 'Require external providers to notify [Assignment: organization-defined personnel or roles] of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within [Assignment: organization- defined time period]; and e. Monitor provider compliance with personnel security requirements. Discussion:  External provider refers to organizations other than the organization operating or acquiring the system. External providers include service bureaus, contractors, and other organizations that provide system development, information technology services, testing or assessment services, outsourced applications, and network/security management. Organizations explicitly include personnel security requirements in acquisition-related documents. External providers may have personnel working at organizational facilities with credentials, badges, or system privileges issued by organizations.', 'vec_doc-14-nist-sp-800-53-p254-959', 0, 243, 'v2.1.0', 'bd63b07ddea9120791b25587e3f497a42f244fdad566ca9b62f09c9ee6c77eff', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 227","subsection":"UNKNOWN","table_id":null,"page":254,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":959,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 227"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p254-960', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 227', 254, 'Notifications of external personnel changes ensure the appropriate termination of privileges and credentials. Organizations define the transfers and terminations deemed reportable by security-related characteristics that include functions, roles, and the nature of credentials or privileges associated with transferred or terminated individuals. Related Controls:  AT-2, AT-3, MA-5, PE-3, PS-2, PS-3, PS-4, PS-5, PS-6, SA-5, SA-9, SA-21. Control Enhancements:  None. References:  [SP 800-35], [SP 800-63-3]. PS-8 PERSONNEL SANCTIONS Control: a. Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; and b. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.', 'vec_doc-14-nist-sp-800-53-p254-960', 0, 234, 'v2.1.0', '7def8bed33e7df42be3c85975587ab46d8571120c004d6481ffc4e559ae661ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 227","subsection":"UNKNOWN","table_id":null,"page":254,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":960,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 227"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p254-961', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 227', 254, 'Discussion:  Organizational sanctions reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Sanctions processes are described in access agreements and can be included as part of general personnel policies for organizations and/or specified in security and privacy policies. Organizations consult with the Office of the General Counsel regarding matters of employee sanctions.', 'vec_doc-14-nist-sp-800-53-p254-961', 0, 107, 'v2.1.0', '913d0ef9b58f54bf543ccae3e626a1d74cad8da3a3293b9165021490661d2d37', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 227","subsection":"UNKNOWN","table_id":null,"page":254,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":961,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 227"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p255-962', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE    PAGE 228', 255, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  All XX-1 Controls, PL-4, PM-12, PS-6, PT-1. Control Enhancements:  None. References:  None. PS-9 POSITION DESCRIPTIONS Control:  Incorporate security and privacy roles and responsibilities into organizational position descriptions. Discussion:  Specification of security and privacy roles in individual organizational position descriptions facilitates clarity in understanding the security or privacy responsibilities associated with the roles and the role-based security and privacy training requirements for the roles. Related Controls:  None. Control Enhancements:  None. References:  [SP 800-181].', 'vec_doc-14-nist-sp-800-53-p255-962', 0, 178, 'v2.1.0', 'd8f259e0748fc104fe8766ce062c90b04b8f40fbecaed5852f4c68d90b25ea2d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE    PAGE 228","subsection":"UNKNOWN","table_id":null,"page":255,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":962,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE    PAGE 228"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p256-963', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.15   PERSONALLY IDENTIFIABLE INFORMATION PROCESSING AND', 256, 'TRANSPARENCY Quick link to Personally Identifiable Information Processing and Transparency table PT-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p256-963', 0, 57, 'v2.1.0', '2c6402e8235cf6b5a4cefb5e70dfa957f6693614a0bf4055d30691b0d8775d69', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.15   PERSONALLY IDENTIFIABLE INFORMATION PROCESSING AND","subsection":"UNKNOWN","table_id":null,"page":256,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":963,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.15   PERSONALLY IDENTIFIABLE INFORMATION PROCESSING AND"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p256-964', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 256, 'level] personally identifiable information processing and transparency policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p256-964', 0, 88, 'v2.1.0', 'ff7414118a030c31ee40d3868da0f92ca0e80d72715e11d0b0c83008ff597a0b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":256,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":964,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p256-965', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the personally identifiable information', 256, 'processing and transparency policy and the associated personally identifiable information processing and transparency controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personally identifiable information processing and transparency policy and procedures; and c. Review and update the current personally identifiable information processing and transparency:', 'vec_doc-14-nist-sp-800-53-p256-965', 0, 111, 'v2.1.0', '40834ed9ecd3861eff3f74228e6048451c01aaeb2396241e999927188ecb26ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the personally identifiable information","subsection":"UNKNOWN","table_id":null,"page":256,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":965,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the personally identifiable information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p256-966', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 256, 'organization-defined events]. Discussion:  Personally identifiable information processing and transparency policy and procedures address the controls in the PT family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of personally identifiable information processing and transparency policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to personally identifiable information processing and transparency policy and procedures include assessment or audit findings, breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.', 'vec_doc-14-nist-sp-800-53-p256-966', 0, 420, 'v2.1.0', '6c6d428fe5d15c9300f35c64fb374329e2b2aa842789e6f8275e4d846adbeac4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":256,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":966,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p257-967', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 230', 257, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. Control Enhancements:  None. References:  [OMB A-130]. PT-2 AUTHORITY TO PROCESS PERSONALLY IDENTIFIABLE INFORMATION Control: a. Determine and document the [Assignment: organization-defined authority] that permits the [Assignment: organization-defined processing] of personally identifiable information; and b. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is authorized. Discussion:  The processing of personally identifiable information is an operation or set of operations that the information system or organization performs with respect to personally identifiable information across the information life cycle. Processing includes but is not limited to creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal.', 'vec_doc-14-nist-sp-800-53-p257-967', 0, 237, 'v2.1.0', '33d70208237262d15287821fe65205f089dffdba7939f9131ca6552027023516', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 230","subsection":"UNKNOWN","table_id":null,"page":257,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":967,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 230"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p257-968', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 230', 257, 'Processing operations also include logging, generation, and transformation, as well as analysis techniques, such as data mining. Organizations may be subject to laws, executive orders, directives, regulations, or policies that establish the organization’s authority and thereby limit certain types of processing of personally identifiable information or establish other requirements related to the processing. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such authority, particularly if the organization is subject to multiple jurisdictions or sources of authority. For organizations whose processing is not determined according to legal authorities, the organization’s policies and determinations govern how they process personally identifiable information. While processing of personally identifiable information may be legally permissible, privacy risks may still arise.', 'vec_doc-14-nist-sp-800-53-p257-968', 0, 234, 'v2.1.0', '5889eb859b42680efb67b2336aa9fc76ef1fc7c5d6f93b0dcb7cea23b2b4f1b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 230","subsection":"UNKNOWN","table_id":null,"page":257,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":968,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 230"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p257-969', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 230', 257, 'Privacy risk assessments can identify the privacy risks associated with the authorized processing of personally identifiable information and support solutions to manage such risks. Organizations consider applicable requirements and organizational policies to determine how to document this authority. For federal agencies, the authority to process personally identifiable information is documented in privacy policies and notices, system of records notices, privacy impact assessments, [PRIVACT] statements, computer matching agreements and notices, contracts, information sharing agreements, memoranda of understanding, and other documentation. Organizations take steps to ensure that personally identifiable information is only processed for authorized purposes, including training organizational personnel on the authorized processing of personally identifiable information and monitoring and auditing organizational use of personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p257-969', 0, 241, 'v2.1.0', '4557c2f2e31c67ca11bf506ac14ade62425c53ab6a7662c4d20a8b71ecec592a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 230","subsection":"UNKNOWN","table_id":null,"page":257,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":969,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 230"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p257-970', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 230', 257, 'Related Controls:  AC-2, AC-3, CM-13, IR-9, PM-9, PM-24, PT-1, PT-3, PT-5, PT-6, RA-3, RA-8, SI- 12, SI-18. Control Enhancements: (1) AUTHORITY TO PROCESS PERSONALLY IDENTIFIABLE INFORMATION | DATA TAGGING Attach data tags containing [Assignment: organization-defined authorized processing] to [Assignment: organization-defined elements of personally identifiable information]. Discussion:  Data tags support the tracking and enforcement of authorized processing by conveying the types of processing that are authorized along with the relevant elements of', 'vec_doc-14-nist-sp-800-53-p257-970', 0, 139, 'v2.1.0', '778b6133bd5fcab870c17351fb23d2f68e069abbdc36027440d38287ca6a7758', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 230","subsection":"UNKNOWN","table_id":null,"page":257,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":970,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 230"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p258-971', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 231', 258, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 personally identifiable information throughout the system. Data tags may also support the use of automated tools. Related Controls:  AC-16, CA-6, CM-12, PM-5, PM-22, PT-4, SC-16, SC-43, SI-10, SI-15, SI-19. (2) AUTHORITY TO PROCESS PERSONALLY IDENTIFIABLE INFORMATION | AUTOMATION Manage enforcement of the authorized processing of personally identifiable information using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms augment verification that only authorized processing is occurring. Related Controls:  CA-6, CM-12, PM-5, PM-22, PT-4, SC-16, SC-43, SI-10, SI-15, SI-19. References:  [PRIVACT], [OMB A-130], [IR 8112]. PT-3 PERSONALLY IDENTIFIABLE INFORMATION PROCESSING PURPOSES Control: a. Identify and document the [Assignment: organization-defined purpose(s)] for processing personally identifiable information; b.', 'vec_doc-14-nist-sp-800-53-p258-971', 0, 240, 'v2.1.0', '4320ab3c22dc7869af5bbc643acbd91ad04aab759f9088415025ad72f2dde221', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 231","subsection":"UNKNOWN","table_id":null,"page":258,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":971,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 231"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p258-972', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 231', 258, 'Describe the purpose(s) in the public privacy notices and policies of the organization; c. Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is compatible with the identified purpose(s); and d. Monitor changes in processing personally identifiable information and implement [Assignment: organization-defined mechanisms] to ensure that any changes are made in accordance with [Assignment: organization-defined requirements]. Discussion:  Identifying and documenting the purpose for processing provides organizations with a basis for understanding why personally identifiable information may be processed. The term “process” includes every step of the information life cycle, including creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal.', 'vec_doc-14-nist-sp-800-53-p258-972', 0, 213, 'v2.1.0', 'e3bc21f6223ae1d598f6ab55573e71ab78c43b09d5380642cd0c52e5c5126df7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 231","subsection":"UNKNOWN","table_id":null,"page":258,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":972,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 231"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p258-973', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 231', 258, 'Identifying and documenting the purpose of processing is a prerequisite to enabling owners and operators of the system and individuals whose information is processed by the system to understand how the information will be processed. This enables individuals to make informed decisions about their engagement with information systems and organizations and to manage their privacy interests. Once the specific processing purpose has been identified, the purpose is described in the organization’s privacy notices, policies, and any related privacy compliance documentation, including privacy impact assessments, system of records notices, [ PRIVACT] statements, computer matching notices, and other applicable Federal Register notices. Organizations take steps to help ensure that personally identifiable information is processed only for identified purposes, including training organizational personnel and monitoring and auditing organizational processing of personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p258-973', 0, 249, 'v2.1.0', 'f8ad6c2c1664d901aa469448410854352856f7cfb85bb60a8eed1d2ca16cecf1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 231","subsection":"UNKNOWN","table_id":null,"page":258,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":973,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 231"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p258-974', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 231', 258, 'Organizations monitor for changes in personally identifiable information processing. Organizational personnel consult with the senior agency official for privacy and legal counsel to ensure that any new purposes that arise from changes in processing are compatible with the purpose for which the information was collected, or if the new purpose is not compatible, implement mechanisms in accordance with defined requirements to allow for the new processing, if appropriate. Mechanisms may include obtaining consent from individuals, revising privacy policies, or other measures to manage privacy risks that arise from changes in personally identifiable information processing purposes. Related Controls:  AC-2, AC-3, AT-3, CM-13, IR-9, PM-9, PM-25, PT-2, PT-5, PT-6, PT-7, RA-8, SC- 43, SI-12, SI-18.', 'vec_doc-14-nist-sp-800-53-p258-974', 0, 200, 'v2.1.0', '9b0eb4da9c70c1dbf3dc0c10f9bc5b14e3fde047b6902609263051e67fc77075', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 231","subsection":"UNKNOWN","table_id":null,"page":258,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":974,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 231"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p259-975', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 232', 259, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) PERSONALLY IDENTIFIABLE INFORMATION PROCESSING PURPOSES | DATA TAGGING Attach data tags containing the following purposes to [Assignment: organization-defined elements of personally identifiable information]: [Assignment: organization-defined processing purposes]. Discussion:  Data tags support the tracking of processing purposes by conveying the purposes along with the relevant elements of personally identifiable information throughout the system. By conveying the processing purposes in a data tag along with the personally identifiable information as the information transits a system, a system owner or operator can identify whether a change in processing would be compatible with the identified and documented purposes. Data tags may also support the use of automated tools. Related Controls:  CA-6, CM-12, PM-5, PM-22, SC-16, SC-43, SI-10, SI-15, SI-19.', 'vec_doc-14-nist-sp-800-53-p259-975', 0, 246, 'v2.1.0', '8e160fc71c678988864e804ff377920b255f73a333830a347affdf5849ef4948', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 232","subsection":"UNKNOWN","table_id":null,"page":259,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":975,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 232"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p259-976', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 232', 259, '(2) PERSONALLY IDENTIFIABLE INFORMATION PROCESSING PURPOSES | AUTOMATION Track processing purposes of personally identifiable information using [Assignment: organization-defined automated mechanisms]. Discussion:  Automated mechanisms augment tracking of the processing purposes. Related Controls:  CA-6, CM-12, PM-5, PM-22, SC-16, SC-43, SI-10, SI-15, SI-19. References:  [PRIVACT], [OMB A-130], [IR 8112]. PT-4 CONSENT Control:  Implement [Assignment: organization-defined tools or mechanisms] for individuals to consent to the processing of their personally identifiable information prior to its collection that facilitate individuals’ informed decision-making. Discussion:  Consent allows individuals to participate in making decisions about the processing of their information and transfers some of the risk that arises from the processing of personally identifiable information from the organization to an individual.', 'vec_doc-14-nist-sp-800-53-p259-976', 0, 231, 'v2.1.0', '644f63922dd3b6ed0f3f751c82aaaaf44f966950a76dc3e272fc364ca5937afd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 232","subsection":"UNKNOWN","table_id":null,"page":259,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":976,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 232"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p259-977', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 232', 259, 'Consent may be required by applicable laws, executive orders, directives, regulations, policies, standards, or guidelines. Otherwise, when selecting consent as a control, organizations consider whether individuals can be reasonably expected to understand and accept the privacy risks that arise from their authorization. Organizations consider whether other controls may more effectively mitigate privacy risk either alone or in conjunction with consent. Organizations also consider any demographic or contextual factors that may influence the understanding or behavior of individuals with respect to the processing carried out by the system or organization. When soliciting consent from individuals, organizations consider the appropriate mechanism for obtaining consent, including the type of consent (e.g., opt-in, opt-out), how to properly authenticate and identity proof individuals and how to obtain consent through electronic means.', 'vec_doc-14-nist-sp-800-53-p259-977', 0, 235, 'v2.1.0', '14d99d88c14cf78a86dfc885339a6b7a35c0018b1e57e14da482e73180430f54', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 232","subsection":"UNKNOWN","table_id":null,"page":259,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":977,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 232"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p259-978', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 232', 259, 'In addition, organizations consider providing a mechanism for individuals to revoke consent once it has been provided, as appropriate. Finally, organizations consider usability factors to help individuals understand the risks being accepted when providing consent, including the use of plain language and avoiding technical jargon. Related Controls:  AC-16, PT-2, PT-5. Control Enhancements: (1) CONSENT | TAILORED CONSENT Provide [Assignment: organization-defined mechanisms] to allow individuals to tailor processing permissions to selected elements of personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p259-978', 0, 148, 'v2.1.0', '8096fd36573cb2978ce0dc75176294cb3a9edfe4c4115728c2b31eb0a57fc06d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 232","subsection":"UNKNOWN","table_id":null,"page":259,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":978,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 232"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p260-979', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 233', 260, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion: While some processing may be necessary for the basic functionality of the product or service, other processing may not. In these circumstances, organizations allow individuals to select how specific personally identifiable information elements may be processed. More tailored consent may help reduce privacy risk, increase individual satisfaction, and avoid adverse behaviors, such as abandonment of the product or service. Related Controls:  PT-2. (2) CONSENT | JUST-IN-TIME CONSENT Present [Assignment: organization-defined consent mechanisms] to individuals at [Assignment: organization-defined frequency] and in conjunction with [Assignment: organization-defined personally identifiable information processing].', 'vec_doc-14-nist-sp-800-53-p260-979', 0, 205, 'v2.1.0', '23b759f6fa56477e648b033f63305b488d26e640135e171ab834fc4e97c348dd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 233","subsection":"UNKNOWN","table_id":null,"page":260,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":979,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 233"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p260-980', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 233', 260, 'Discussion:  Just-in-time consent enables individuals to participate in how their personally identifiable information is being processed at the time or in conjunction with specific types of data processing when such participation may be most useful to the individual. Individual assumptions about how personally identifiable information is being processed might not be accurate or reliable if time has passed since the individual last gave consent or the type of processing creates significant privacy risk. Organizations use discretion to determine when to use just-in-time consent and may use supporting information on demographics, focus groups, or surveys to learn more about individuals’ privacy interests and concerns. Related Controls:  PT-2. (3) CONSENT | REVOCATION Implement [Assignment: organization-defined tools or mechanisms] for individuals to revoke consent to the processing of their personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p260-980', 0, 235, 'v2.1.0', '0e2c7d0b15525a45f39ac105915fb92db9b67dd771095cb07340caf1c2863ea4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 233","subsection":"UNKNOWN","table_id":null,"page":260,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":980,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 233"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p260-981', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 233', 260, 'Discussion: Revocation of consent enables individuals to exercise control over their initial consent decision when circumstances change. Organizations consider usability factors in enabling easy-to-use revocation capabilities. Related Controls:  PT-2. References:  [PRIVACT], [OMB A-130], [SP 800-63-3]. PT-5 PRIVACY NOTICE Control:  Provide notice to individuals about the processing of personally identifiable information that: a. Is available to individuals upon first interacting with an organization, and subsequently at [Assignment: organization-defined frequency]; b. Is clear and easy-to-understand, expressing information about personally identifiable information processing in plain language; c. Identifies the authority that authorizes the processing of personally identifiable information; d. Identifies the purposes for which personally identifiable information is to be processed; and e. Includes [Assignment: organization-defined information].', 'vec_doc-14-nist-sp-800-53-p260-981', 0, 240, 'v2.1.0', '4c858f33cebbea26377c2e1684fe2c14912f15973c16d5dfb85b94f9cf6e1623', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 233","subsection":"UNKNOWN","table_id":null,"page":260,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":981,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 233"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p260-982', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 233', 260, 'Discussion:  Privacy notices help inform individuals about how their personally identifiable information is being processed by the system or organization. Organizations use privacy notices to inform individuals about how, under what authority, and for what purpose their personally identifiable information is processed, as well as other information such as choices individuals might have with respect to that processing and other parties with whom information is shared. Laws, executive orders, directives, regulations, or policies may require that privacy notices include specific elements or be provided in specific formats. Federal agency personnel consult with the senior agency official for privacy and legal counsel regarding when and where to provide', 'vec_doc-14-nist-sp-800-53-p260-982', 0, 190, 'v2.1.0', 'e2aa4f72c36cc3cdb9bfe2645a37700b7c6e019aa36143a80b14179fc3c6233d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 233","subsection":"UNKNOWN","table_id":null,"page":260,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":982,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 233"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p261-983', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 234', 261, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 privacy notices, as well as elements to include in privacy notices and required formats. In circumstances where laws or government-wide policies do not require privacy notices, organizational policies and determinations may require privacy notices and may serve as a source of the elements to include in privacy notices. Privacy risk assessments identify the privacy risks associated with the processing of personally identifiable information and may help organizations determine appropriate elements to include in a privacy notice to manage such risks. To help individuals understand how their information is being processed, organizations write materials in plain language and avoid technical jargon. Related Controls:  PM-20, PM-22, PT-2, PT-3, PT-4, PT-7, RA-3, SC-42, SI-18.', 'vec_doc-14-nist-sp-800-53-p261-983', 0, 218, 'v2.1.0', '428624ec15bf33c5c887a7bae94c7c787e071d035626e6f96744265a3c969d11', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 234","subsection":"UNKNOWN","table_id":null,"page":261,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":983,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 234"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p261-984', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 234', 261, 'Control Enhancements: (1) PRIVACY NOTICE | JUST-IN-TIME NOTICE Present notice of personally identifiable information processing to individuals at a time and location where the individual provides personally identifiable information or in conjunction with a data action, or [Assignment: organization-defined frequency]. Discussion:  Just-in-time notices inform individuals of how organizations process their personally identifiable information at a time when such notices may be most useful to the individuals. Individual assumptions about how personally identifiable information will be processed might not be accurate or reliable if time has passed since the organization last presented notice or the circumstances under which the individual was last provided notice have changed. A just-in-time notice can explain data actions that organizations have identified as potentially giving rise to greater privacy risk for individuals.', 'vec_doc-14-nist-sp-800-53-p261-984', 0, 233, 'v2.1.0', 'e1a779693e137986f5ecae20e40e29a8c8be41702fbfb0f5f2e8c5faa7318386', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 234","subsection":"UNKNOWN","table_id":null,"page":261,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":984,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 234"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p261-985', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 234', 261, 'Organizations can use a just-in-time notice to update or remind individuals about specific data actions as they occur or highlight specific changes that occurred since last presenting notice. A just-in-time notice can be used in conjunction with just-in-time consent to explain what will occur if consent is declined. Organizations use discretion to determine when to use a just-in-time notice and may use supporting information on user demographics, focus groups, or surveys to learn about users’ privacy interests and concerns. Related Controls:  PM-21. (2) PRIVACY NOTICE | PRIVACY ACT STATEMENTS Include Privacy Act statements on forms that collect information that will be maintained in a Privacy Act system of records, or provide Privacy Act statements on separate forms that can be retained by individuals.', 'vec_doc-14-nist-sp-800-53-p261-985', 0, 204, 'v2.1.0', '8e09b410918748436e99fabcd3927feef8418b8f0c53cce49de41ef46b79158e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 234","subsection":"UNKNOWN","table_id":null,"page":261,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":985,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 234"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p261-986', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 234', 261, 'Discussion:  If a federal agency asks individuals to supply information that will become part of a system of records, the agency is required to provide a [PRIVACT] statement on the form used to collect the information or on a separate form that can be retained by the individual. The agency provides a [PRIVACT] statement in such circumstances regardless of whether the information will be collected on a paper or electronic form, on a website, on a mobile application, over the telephone, or through some other medium. This requirement ensures that the individual is provided with sufficient information about the request for information to make an informed decision on whether or not to respond.', 'vec_doc-14-nist-sp-800-53-p261-986', 0, 175, 'v2.1.0', '3185b3c18a713b233a8cc2095aa948cf299fa67dea0331530e48452c9bb2ffbb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 234","subsection":"UNKNOWN","table_id":null,"page":261,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":986,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 234"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p261-987', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 234', 261, '[PRIVACT] statements provide formal notice to individuals of the authority that authorizes the solicitation of the information; whether providing the information is mandatory or voluntary; the principal purpose(s) for which the information is to be used; the published routine uses to which the information is subject; the effects on the individual, if any, of not providing all or any part of the information requested; and an appropriate citation and link to the relevant system of records notice. Federal agency personnel consult with the senior agency official for privacy and legal counsel regarding the notice provisions of the [ PRIVACT]. Related Controls:  PT-6.', 'vec_doc-14-nist-sp-800-53-p261-987', 0, 168, 'v2.1.0', '4d213113e27fb714808418ef4f672a12a580032a2b467f9941dff3f10f4a0be1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 234","subsection":"UNKNOWN","table_id":null,"page":261,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":987,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 234"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p262-988', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 235', 262, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements:  None. References:  [PRIVACT], [OMB A-130], [OMB A-108]. PT-6 SYSTEM OF RECORDS NOTICE Control:  For systems that process information that will be maintained in a Privacy Act system of records: a. Draft system of records notices in accordance with OMB guidance and submit new and significantly modified system of records notices to the OMB and appropriate congressional committees for advance review; b. Publish system of records notices in the Federal Register; and c. Keep system of records notices accurate, up-to-date, and scoped in accordance with policy. Discussion:  The [PRIVACT] requires that federal agencies publish a system of records notice in the Federal Register upon the establishment and/or modification of a [PRIVACT] system of records.', 'vec_doc-14-nist-sp-800-53-p262-988', 0, 217, 'v2.1.0', '9d7ab077fb681fb32bdb90b671964595417937d6a7a04be65bd0e4b5c3d3ba40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 235","subsection":"UNKNOWN","table_id":null,"page":262,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":988,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 235"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p262-989', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 235', 262, 'As a general matter, a system of records notice is required when an agency maintains a group of any records under the control of the agency from which information is retrieved by the name of an individual or by some identifying number, symbol, or other identifier. The notice describes the existence and character of the system and identifies the system of records, the purpose(s) of the system, the authority for maintenance of the records, the categories of records maintained in the system, the categories of individuals about whom records are maintained, the routine uses to which the records are subject, and additional details about the system as described in [OMB A-108]. Related Controls:  AC-3, PM-20, PT-2, PT-3, PT-5.', 'vec_doc-14-nist-sp-800-53-p262-989', 0, 182, 'v2.1.0', 'fbabf4e9185589a73ef131753ef766a0280a42e9e7ebdee4bbcc3b0f24de3158', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 235","subsection":"UNKNOWN","table_id":null,"page":262,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":989,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 235"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p262-990', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 235', 262, 'Control Enhancements: (1) SYSTEM OF RECORDS NOTICE | ROUTINE USES Review all routine uses published in the system of records notice at [Assignment: organization-defined frequency] to ensure continued accuracy, and to ensure that routine uses continue to be compatible with the purpose for which the information was collected. Discussion:  A [PRIVACT] routine use is a particular kind of disclosure of a record outside of the federal agency maintaining the system of records. A routine use is an exception to the [PRIVACT] prohibition on the disclosure of a record in a system of records without the prior written consent of the individual to whom the record pertains. To qualify as a routine use, the disclosure must be for a purpose that is compatible with the purpose for which the information was originally collected.', 'vec_doc-14-nist-sp-800-53-p262-990', 0, 206, 'v2.1.0', '30664b88042f4391f97e88a4001f78fabf84153999f04fc552ebf141279b7c96', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 235","subsection":"UNKNOWN","table_id":null,"page":262,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":990,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 235"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p262-991', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 235', 262, 'The [ PRIVACT] requires agencies to describe each routine use of the records maintained in the system of records, including the categories of users of the records and the purpose of the use. Agencies may only establish routine uses by explicitly publishing them in the relevant system of records notice. Related Controls:  None. (2) SYSTEM OF RECORDS NOTICE | EXEMPTION RULES Review all Privacy Act exemptions claimed for the system of records at [Assignment: organization-defined frequency] to ensure they remain appropriate and necessary in accordance with law, that they have been promulgated as regulations, and that they are accurately described in the system of records notice. Discussion:  The [PRIVACT ] includes two sets of provisions that allow federal agencies to claim exemptions from certain requirements in the statute. In certain circumstances, these provisions allow agencies to promulgate regulations to exempt a system of records from select provisions of the [PRIVACT].', 'vec_doc-14-nist-sp-800-53-p262-991', 0, 247, 'v2.1.0', '1abbdc8dfe603b14beaac84177c90f107e17c8181009a4f5a8a3efe38804258a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 235","subsection":"UNKNOWN","table_id":null,"page":262,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":991,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 235"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p262-992', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 235', 262, 'At a minimum, organizations’ [PRIVACT] exemption', 'vec_doc-14-nist-sp-800-53-p262-992', 0, 12, 'v2.1.0', '688b4230ae974d8c8e8184b974b8085c249c833cb1fd92e62a5e0ee3e7a4ef8a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 235","subsection":"UNKNOWN","table_id":null,"page":262,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":992,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 235"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p263-993', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 236', 263, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 regulations include the specific name(s) of any system(s) of records that will be exempt, the specific provisions of the [PRIVACT] from which the system(s) of records is to be exempted, the reasons for the exemption, and an explanation for why the exemption is both necessary and appropriate. Related Controls:  None. References:  [PRIVACT], [OMB A-108]. PT-7 SPECIFIC CATEGORIES OF PERSONALLY IDENTIFIABLE INFORMATION Control: Apply [Assignment: organization-defined processing conditions] for specific categories of personally identifiable information. Discussion:  Organizations apply any conditions or protections that may be necessary for specific categories of personally identifiable information. These conditions may be required by laws, executive orders, directives, regulations, policies, standards, or guidelines.', 'vec_doc-14-nist-sp-800-53-p263-993', 0, 229, 'v2.1.0', '68c1530d8861922b87be2b57355006c1a4a3e268a2ab0350c99c0f38e5c9c77e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 236","subsection":"UNKNOWN","table_id":null,"page":263,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":993,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 236"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p263-994', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 236', 263, 'The requirements may also come from the results of privacy risk assessments that factor in contextual changes that may result in an organizational determination that a particular category of personally identifiable information is particularly sensitive or raises particular privacy risks. Organizations consult with the senior agency official for privacy and legal counsel regarding any protections that may be necessary. Related Controls:  IR-9, PT-2, PT-3, RA-3.', 'vec_doc-14-nist-sp-800-53-p263-994', 0, 116, 'v2.1.0', 'cc0759173ada16291b03137dd995bdadf0915cf252a9a79a9bd7d6f60b5bb800', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 236","subsection":"UNKNOWN","table_id":null,"page":263,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":994,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 236"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p263-995', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 236', 263, 'Control Enhancements: (1) SPECIFIC CATEGORIES OF PERSONALLY IDENTIFIABLE INFORMATION | SOCIAL SECURITY NUMBERS When a system processes Social Security numbers: (a) Eliminate unnecessary collection, maintenance, and use of Social Security numbers, and explore alternatives to their use as a personal identifier; (b) Do not deny any individual any right, benefit, or privilege provided by law because of such individual’s refusal to disclose his or her Social Security number; and (c) Inform any individual who is asked to disclose his or her Social Security number whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it. Discussion:  Federal law and policy establish specific requirements for organizations’ processing of Social Security numbers.', 'vec_doc-14-nist-sp-800-53-p263-995', 0, 210, 'v2.1.0', 'db7cab9dc6775876fbcb818a8d522aa80003ac9e628eb11eedcc38700bb24006', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 236","subsection":"UNKNOWN","table_id":null,"page":263,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":995,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 236"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p263-996', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 236', 263, 'Organizations take steps to eliminate unnecessary uses of Social Security numbers and other sensitive information and observe any particular requirements that apply. Related Controls:  IA-4. (2) SPECIFIC CATEGORIES OF PERSONALLY IDENTIFIABLE INFORMATION | FIRST AMENDMENT INFORMATION Prohibit the processing of information describing how any individual exercises rights guaranteed by the First Amendment unless expressly authorized by statute or by the individual or unless pertinent to and within the scope of an authorized law enforcement activity. Discussion:  The [PRIVACT] limits agencies’ ability to process information that describes how individuals exercise rights guaranteed by the First Amendment. Organizations consult with the senior agency official for privacy and legal counsel regarding these requirements. Related Controls:  None. References:  [PRIVACT], [OMB A-130], [OMB A-108], [NARA CUI].', 'vec_doc-14-nist-sp-800-53-p263-996', 0, 227, 'v2.1.0', '31259f4c89a509afcb9948a8794a4081f9afef1fdbad774424ac5a1346c3d4c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 236","subsection":"UNKNOWN","table_id":null,"page":263,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":996,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 236"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p264-997', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 237', 264, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 PT-8 COMPUTER MATCHING REQUIREMENTS Control:  When a system or organization processes information for the purpose of conducting a matching program: a. Obtain approval from the Data Integrity Board to conduct the matching program; b. Develop and enter into a computer matching agreement; c. Publish a matching notice in the Federal Register; d. Independently verify the information produced by the matching program before taking adverse action against an individual, if required; and e. Provide individuals with notice and an opportunity to contest the findings before taking adverse action against an individual. Discussion:  The [PRIVACT] establishes requirements for federal and non-federal agencies if they engage in a matching program. In general, a matching program is a computerized comparison of records from two or more automated [PRIVACT] systems of records or an automated system of records and automated records maintained by a non-federal agency (or agent thereof). A matching program either pertains to federal benefit programs or federal personnel or payroll records. A federal benefit match is performed to determine or verify eligibility for payments under federal benefit programs or to recoup payments or delinquent debts under federal benefit programs. A matching program involves not just the matching activity itself but also the investigative follow-up and ultimate action, if any. Related Controls: PM-24. Control Enhancements: None. References:  [PRIVACT], [CMPPA], [OMB A-130], [OMB A-108].', 'vec_doc-14-nist-sp-800-53-p264-997', 0, 402, 'v2.1.0', '045699c2732ef0da016e2af8830a82cf948b3dd4499eb6facc743f3380a9be19', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 237","subsection":"UNKNOWN","table_id":null,"page":264,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":997,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 237"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p265-998', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.16   RISK ASSESSMENT', 265, 'Quick link to Risk Assessment Summary Table RA-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p265-998', 0, 44, 'v2.1.0', 'd6374d6d8e9881fb804f5cc81812fca2c0e4235309be9921ba5f113703ac30e9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.16   RISK ASSESSMENT","subsection":"UNKNOWN","table_id":null,"page":265,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":998,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.16   RISK ASSESSMENT"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p265-999', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 265, 'level] risk assessment policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p265-999', 0, 76, 'v2.1.0', '9725d6634813b6ec386503e9fbcc59cb0517f666e668a2db6908c0056c9222f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":265,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":999,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p265-1000', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the risk assessment policy and the', 265, 'associated risk assessment controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the risk assessment policy and procedures; and c. Review and update the current risk assessment:', 'vec_doc-14-nist-sp-800-53-p265-1000', 0, 64, 'v2.1.0', 'dc6c57c512a6257626282c39b00c65fd86b884de1667f373a43aacb17ba9afb9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the risk assessment policy and the","subsection":"UNKNOWN","table_id":null,"page":265,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1000,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the risk assessment policy and the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p265-1001', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 265, 'organization-defined events]. Discussion:  Risk assessment policy and procedures address the controls in the RA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of risk assessment policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to risk assessment policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p265-1001', 0, 423, 'v2.1.0', 'cb8dbca8e7b1261a4397d640ce0dfe7edb51f437c563f1fe712bab76146fdf36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":265,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1001,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p266-1002', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 239', 266, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 RA-2 SECURITY CATEGORIZATION Control: a. Categorize the system and information it processes, stores, and transmits; b. Document the security categorization results, including supporting rationale, in the security plan for the system; and c. Verify that the authorizing official or authorizing official designated representative reviews and approves the security categorization decision. Discussion:  Security categories describe the potential adverse impacts or negative consequences to organizational operations, organizational assets, and individuals if organizational information and systems are compromised through a loss of confidentiality, integrity, or availability. Security categorization is also a type of asset loss characterization in systems security engineering processes that is carried out throughout the system development life cycle.', 'vec_doc-14-nist-sp-800-53-p266-1002', 0, 236, 'v2.1.0', '464cc268b617de2dde55061a80c424125a313c991f7de5cb4ac8500ed2638cd8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 239","subsection":"UNKNOWN","table_id":null,"page":266,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1002,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 239"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p266-1003', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 239', 266, 'Organizations can use privacy risk assessments or privacy impact assessments to better understand the potential adverse effects on individuals. [ CNSSI 1253] provides additional guidance on categorization for national security systems. Organizations conduct the security categorization process as an organization-wide activity with the direct involvement of chief information officers, senior agency information security officers, senior agency officials for privacy, system owners, mission and business owners, and information owners or stewards. Organizations consider the potential adverse impacts to other organizations and, in accordance with [USA PATRIOT] and Homeland Security Presidential Directives, potential national-level adverse impacts. Security categorization processes facilitate the development of inventories of information assets and, along with CM-8, mappings to specific system components where information is processed, stored, or transmitted.', 'vec_doc-14-nist-sp-800-53-p266-1003', 0, 242, 'v2.1.0', '6a2c518bc886168d7551f7a5e5ebab51c10f31ec110669a32a90897adc30ec46', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 239","subsection":"UNKNOWN","table_id":null,"page":266,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1003,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 239"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p266-1004', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 239', 266, 'The security categorization process is revisited throughout the system development life cycle to ensure that the security categories remain accurate and relevant. Related Controls:  CM-8, MP-4, PL-2, PL-10, PL-11, PM-7, RA-3, RA-5, RA-7, RA-8, SA-8, SC-7, SC- 38, SI-12. Control Enhancements: (1) SECURITY CATEGORIZATION | IMPACT-LEVEL PRIORITIZATION Conduct an impact-level prioritization of organizational systems to obtain additional granularity on system impact levels. Discussion:  Organizations apply the “high-water mark” concept to each system categorized in accordance with [FIPS 199], resulting in systems designated as low impact, moderate impact, or high impact. Organizations that desire additional granularity in the system impact designations for risk-based decision-making, can further partition the systems into sub- categories of the initial system categorization.', 'vec_doc-14-nist-sp-800-53-p266-1004', 0, 221, 'v2.1.0', 'a71989c61431c7ea52949ad62dcad4e20d835ea115601db55b2567aa381b07af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 239","subsection":"UNKNOWN","table_id":null,"page":266,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1004,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 239"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p266-1005', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 239', 266, 'For example, an impact-level prioritization on a moderate-impact system can produce three new sub-categories: low-moderate systems, moderate-moderate systems, and high-moderate systems. Impact-level prioritization and the resulting sub-categories of the system give organizations an opportunity to focus their investments related to security control selection and the tailoring of control baselines in responding to identified risks. Impact-level prioritization can also be used to determine those systems that may be of heightened interest or value to adversaries or represent a critical loss to the federal enterprise, sometimes described as high value assets. For such high value assets, organizations may be more focused on complexity, aggregation, and information exchanges. Systems with high value assets can be prioritized by partitioning high-impact systems into low-high systems, moderate-high systems, and high-high systems.', 'vec_doc-14-nist-sp-800-53-p266-1005', 0, 234, 'v2.1.0', 'aaaf326b2c7c20e09e032186a251a6232fe1fa949daf7b8fc8bc7cfbe29858c0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 239","subsection":"UNKNOWN","table_id":null,"page":266,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1005,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 239"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p267-1006', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 240', 267, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Alternatively, organizations can apply the guidance in [CNSSI 1253] for security objective- related categorization. Related Controls:  None. References:  [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-60-1], [SP 800- 60-2], [SP 800-160-1], [CNSSI 1253], [NARA CUI]. RA-3 RISK ASSESSMENT Control: a. Conduct a risk assessment, including:', 'vec_doc-14-nist-sp-800-53-p267-1006', 0, 113, 'v2.1.0', 'e7acb57f1fa3b7ee6fade91d314ab4152632330793e4434b8355c99b04915ff0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 240","subsection":"UNKNOWN","table_id":null,"page":267,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1006,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 240"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p267-1007', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Determining the likelihood and magnitude of harm from unauthorized access, use,', 267, 'disclosure, disruption, modification, or destruction of the system, the information it processes, stores, or transmits, and any related information; and', 'vec_doc-14-nist-sp-800-53-p267-1007', 0, 38, 'v2.1.0', '82f95436159c74d326978697161d09d793f07f119c5613d7134e64bea0d2880f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Determining the likelihood and magnitude of harm from unauthorized access, use,","subsection":"UNKNOWN","table_id":null,"page":267,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1007,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Determining the likelihood and magnitude of harm from unauthorized access, use,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p267-1008', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Determining the likelihood and impact of adverse effects on individuals arising from the', 267, 'processing of personally identifiable information; b. Integrate risk assessment results and risk management decisions from the organization and mission or business process perspectives with system-level risk assessments; c. Document risk assessment results in [Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]]; d. Review risk assessment results [Assignment: organization-defined frequency]; e. Disseminate risk assessment results to [Assignment: organization-defined personnel or roles]; and f. Update the risk assessment [Assignment: organization-defined frequency] or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system. Discussion:  Risk assessments consider threats, vulnerabilities, likelihood, and impact to organizational operations and assets, individuals, other organizations, and the Nation.', 'vec_doc-14-nist-sp-800-53-p267-1008', 0, 242, 'v2.1.0', '15f5cc05efadf0d21838ce2adbffc63dad31e2c2a5d9c05cf788041f60fe074c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Determining the likelihood and impact of adverse effects on individuals arising from the","subsection":"UNKNOWN","table_id":null,"page":267,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1008,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Determining the likelihood and impact of adverse effects on individuals arising from the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p267-1009', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Determining the likelihood and impact of adverse effects on individuals arising from the', 267, 'Risk assessments also consider risk from external parties, including contractors who operate systems on behalf of the organization, individuals who access organizational systems, service providers, and outsourcing entities. Organizations can conduct risk assessments at all three levels in the risk management hierarchy (i.e., organization level, mission/business process level, or information system level) and at any stage in the system development life cycle. Risk assessments can also be conducted at various steps in the Risk Management Framework, including preparation, categorization, control selection, control implementation, control assessment, authorization, and control monitoring. Risk assessment is an ongoing activity carried out throughout the system development life cycle. Risk assessments can also address information related to the system, including system design, the intended use of the system, testing results, and supply chain-related information or artifacts.', 'vec_doc-14-nist-sp-800-53-p267-1009', 0, 246, 'v2.1.0', 'cb99c47defaadb82298178e0eb203ec252180cfd2568ee8ceecb8d7f5f51c354', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Determining the likelihood and impact of adverse effects on individuals arising from the","subsection":"UNKNOWN","table_id":null,"page":267,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1009,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Determining the likelihood and impact of adverse effects on individuals arising from the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p267-1010', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Determining the likelihood and impact of adverse effects on individuals arising from the', 267, 'Risk assessments can play an important role in control selection processes, particularly during the application of tailoring guidance and in the earliest phases of capability determination. Related Controls:  CA-3, CA-6, CM-4, CM-13, CP-6, CP-7, IA-8, MA-5, PE-3, PE-8, PE-18, PL-2, PL- 10, PL-11, PM-8, PM-9, PM-28, PT-2, PT-7, RA-2, RA-5, RA-7, SA-8, SA-9, SC-38, SI-12. Control Enhancements: (1) RISK ASSESSMENT | SUPPLY CHAIN RISK ASSESSMENT', 'vec_doc-14-nist-sp-800-53-p267-1010', 0, 112, 'v2.1.0', 'd7fa0b28531d53f7cca685eb92c7a9b38b3b2d382ab2e5745e9f6930d0037fc8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Determining the likelihood and impact of adverse effects on individuals arising from the","subsection":"UNKNOWN","table_id":null,"page":267,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1010,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Determining the likelihood and impact of adverse effects on individuals arising from the"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p268-1011', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 241', 268, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (a) Assess supply chain risks associated with [Assignment: organization-defined systems, system components, and system services]; and (b) Update the supply chain risk assessment [Assignment: organization-defined frequency], when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain. Discussion:  Supply chain-related events include disruption, use of defective components, insertion of counterfeits, theft, malicious development practices, improper delivery practices, and insertion of malicious code.', 'vec_doc-14-nist-sp-800-53-p268-1011', 0, 181, 'v2.1.0', '26b69f3bd5a95bc0b230c7522af199f85bf009b3fcb52604b372c973019225d3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 241","subsection":"UNKNOWN","table_id":null,"page":268,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1011,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 241"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p268-1012', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 241', 268, 'These events can have a significant impact on the confidentiality, integrity, or availability of a system and its information and, therefore, can also adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, and the Nation. The supply chain-related events may be unintentional or malicious and can occur at any point during the system life cycle. An analysis of supply chain risk can help an organization identify systems or components for which additional supply chain risk mitigations are required. Related Controls:  RA-2, RA-9, PM-17, PM-30, SR-2. (2) RISK ASSESSMENT | USE OF ALL-SOURCE INTELLIGENCE Use all-source intelligence to assist in the analysis of risk. Discussion:  Organizations employ all-source intelligence to inform engineering, acquisition, and risk management decisions.', 'vec_doc-14-nist-sp-800-53-p268-1012', 0, 223, 'v2.1.0', '66ae2f7e2ca5a511028c0d740a96fb8a9242f65c5fb168eb65796050699071af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 241","subsection":"UNKNOWN","table_id":null,"page":268,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1012,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 241"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p268-1013', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 241', 268, 'All-source intelligence consists of information derived from all available sources, including publicly available or open-source information, measurement and signature intelligence, human intelligence, signals intelligence, and imagery intelligence. All-source intelligence is used to analyze the risk of vulnerabilities (both intentional and unintentional) from development, manufacturing, and delivery processes, people, and the environment. The risk analysis may be performed on suppliers at multiple tiers in the supply chain sufficient to manage risks. Organizations may develop agreements to share all-source intelligence information or resulting decisions with other organizations, as appropriate. Related Controls:  None. (3) RISK ASSESSMENT | DYNAMIC THREAT AWARENESS Determine the current cyber threat environment on an ongoing basis using [Assignment: organization-defined means].', 'vec_doc-14-nist-sp-800-53-p268-1013', 0, 223, 'v2.1.0', 'e71db857d3f747957f3da8df86a8affd5aef02a601e3bc5a5923deb9122efdf6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 241","subsection":"UNKNOWN","table_id":null,"page":268,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1013,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 241"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p268-1014', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 241', 268, 'Discussion:  The threat awareness information that is gathered feeds into the organization’s information security operations to ensure that procedures are updated in response to the changing threat environment. For example, at higher threat levels, organizations may change the privilege or authentication thresholds required to perform certain operations. Related Controls:  AT-2. (4) RISK ASSESSMENT | PREDICTIVE CYBER ANALYTICS Employ the following advanced automation and analytics capabilities to predict and identify risks to [Assignment: organization-defined systems or system components]: [Assignment: organization-defined advanced automation and analytics capabilities]. Discussion:  A properly resourced Security Operations Center (SOC) or Computer Incident Response Team (CIRT) may be overwhelmed by the volume of information generated by the proliferation of security tools and appliances unless it employs advanced automation and analytics to analyze the data.', 'vec_doc-14-nist-sp-800-53-p268-1014', 0, 244, 'v2.1.0', '86843d174106a609fc7b501ba30bc375aa09b253fa681764c6ecb983eefc8d93', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 241","subsection":"UNKNOWN","table_id":null,"page":268,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1014,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 241"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p268-1015', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 241', 268, 'Advanced automation and analytics capabilities are typically supported by artificial intelligence concepts, including machine learning. Examples include Automated Threat Discovery and Response (which includes broad-based collection, context- based analysis, and adaptive response capabilities), automated workflow operations, and machine assisted decision tools. Note, however, that sophisticated adversaries may be able', 'vec_doc-14-nist-sp-800-53-p268-1015', 0, 105, 'v2.1.0', '86e49c478ef17909694fa5fcbd40afe8d2b636a587b73bc24382ad58c12ce87b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 241","subsection":"UNKNOWN","table_id":null,"page":268,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1015,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 241"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p269-1016', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 242', 269, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 to extract information related to analytic parameters and retrain the machine learning to classify malicious activity as benign. Accordingly, machine learning is augmented by human monitoring to ensure that sophisticated adversaries are not able to conceal their activities. Related Controls:  None. References:  [OMB A-130], [SP 800-30], [SP 800-39], [SP 800-161], [IR 8023], [IR 8062], [IR 8272]. RA-4 RISK ASSESSMENT UPDATE [Withdrawn: Incorporated into RA-3.] RA-5 VULNERABILITY MONITORING AND SCANNING Control: a. Monitor and scan for vulnerabilities in the system and hosted applications [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported; b. Employ vulnerability monitoring tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for:', 'vec_doc-14-nist-sp-800-53-p269-1016', 0, 268, 'v2.1.0', '2551d561f949ffaf92a0ba1b6a8528f98c9fd238a2952bb0575b4f3aeafc7c8c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 242","subsection":"UNKNOWN","table_id":null,"page":269,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1016,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 242"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p269-1017', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Measuring vulnerability impact;', 269, 'c. Analyze vulnerability scan reports and results from vulnerability monitoring; d. Remediate legitimate vulnerabilities [Assignment: organization-defined response times] in accordance with an organizational assessment of risk; e. Share information obtained from the vulnerability monitoring process and control assessments with [Assignment: organization-defined personnel or roles] to help eliminate similar vulnerabilities in other systems; and f. Employ vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned. Discussion:  Security categorization of information and systems guides the frequency and comprehensiveness of vulnerability monitoring (including scans). Organizations determine the required vulnerability monitoring for system components, ensuring that the potential sources of vulnerabilities— such as infrastructure components (e.g., switches, routers, guards, sensors), networked printers, scanners, and copiers— are not overlooked.', 'vec_doc-14-nist-sp-800-53-p269-1017', 0, 251, 'v2.1.0', '05106bac13b025b53b85066714066da312b2ffdabc424c91347820bad99053e4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Measuring vulnerability impact;","subsection":"UNKNOWN","table_id":null,"page":269,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1017,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Measuring vulnerability impact;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p269-1018', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Measuring vulnerability impact;', 269, 'The capability to readily update vulnerability monitoring tools as new vulnerabilities are discovered and announced and as new scanning methods are developed helps to ensure that new vulnerabilities are not missed by employed vulnerability monitoring tools. The vulnerability monitoring tool update process helps to ensure that potential vulnerabilities in the system are identified and addressed as quickly as possible. Vulnerability monitoring and analyses for custom software may require additional approaches, such as static analysis, dynamic analysis, binary analysis, or a hybrid of the three approaches. Organizations can use these analysis approaches in source code reviews and in a variety of tools, including web-based application scanners, static analysis tools, and binary analyzers.', 'vec_doc-14-nist-sp-800-53-p269-1018', 0, 199, 'v2.1.0', '2091fe1db62d377d69bde0295b24bab236a109581235493ce280d464d1dae864', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Measuring vulnerability impact;","subsection":"UNKNOWN","table_id":null,"page":269,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1018,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Measuring vulnerability impact;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p269-1019', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Measuring vulnerability impact;', 269, 'Vulnerability monitoring includes scanning for patch levels; scanning for functions, ports, protocols, and services that should not be accessible to users or devices; and scanning for flow control mechanisms that are improperly configured or operating incorrectly. Vulnerability', 'vec_doc-14-nist-sp-800-53-p269-1019', 0, 70, 'v2.1.0', '6ef695577a46950f46f8fa76cbdb2d6064bad0d82b8fa49d21261028d0d64477', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Measuring vulnerability impact;","subsection":"UNKNOWN","table_id":null,"page":269,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1019,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Measuring vulnerability impact;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p270-1020', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 243', 270, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 monitoring may also include continuous vulnerability monitoring tools that use instrumentation to continuously analyze components. Instrumentation-based tools may improve accuracy and may be run throughout an organization without scanning. Vulnerability monitoring tools that facilitate interoperability include tools that are Security Content Automated Protocol (SCAP)- validated. Thus, organizations consider using scanning tools that express vulnerabilities in the Common Vulnerabilities and Exposures (CVE) naming convention and that employ the Open Vulnerability Assessment Language (OVAL) to determine the presence of vulnerabilities. Sources for vulnerability information include the Common Weakness Enumeration (CWE) listing and the National Vulnerability Database (NVD). Control assessments, such as red team exercises, provide additional sources of potential vulnerabilities for which to scan.', 'vec_doc-14-nist-sp-800-53-p270-1020', 0, 249, 'v2.1.0', '231cf4b94e2fa03ac14579b452e72ecb077785e69a4ff5129b8e2f8c1bc96057', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 243","subsection":"UNKNOWN","table_id":null,"page":270,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1020,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 243"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p270-1021', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 243', 270, 'Organizations also consider using scanning tools that express vulnerability impact by the Common Vulnerability Scoring System (CVSS). Vulnerability monitoring includes a channel and process for receiving reports of security vulnerabilities from the public at-large. Vulnerability disclosure programs can be as simple as publishing a monitored email address or web form that can receive reports, including notification authorizing good-faith research and disclosure of security vulnerabilities. Organizations generally expect that such research is happening with or without their authorization and can use public vulnerability disclosure channels to increase the likelihood that discovered vulnerabilities are reported directly to the organization for remediation. Organizations may also employ the use of financial incentives (also known as “bug bounties”) to further encourage external security researchers to report discovered vulnerabilities.', 'vec_doc-14-nist-sp-800-53-p270-1021', 0, 237, 'v2.1.0', '421a044708fe5953d01d8a4a08294f00a52b60a33c3e51841a4b1b9729c81c0f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 243","subsection":"UNKNOWN","table_id":null,"page":270,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1021,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 243"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p270-1022', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 243', 270, 'Bug bounty programs can be tailored to the organization’s needs. Bounties can be operated indefinitely or over a defined period of time and can be offered to the general public or to a curated group. Organizations may run public and private bounties simultaneously and could choose to offer partially credentialed access to certain participants in order to evaluate security vulnerabilities from privileged vantage points. Related Controls:  CA-2, CA-7, CA-8, CM-2, CM-4, CM-6, CM-8, RA-2, RA-3, SA-11, SA-15, SC-38 , SI-2, SI-3, SI-4, SI-7, SR-11. Control Enhancements: (1) VULNERABILITY MONITORING AND SCANNING | UPDATE TOOL CAPABILITY [Withdrawn: Incorporated into RA-5.] (2) VULNERABILITY MONITORING AND SCANNING | UPDATE VULNERABILITIES TO BE SCANNED Update the system vulnerabilities to be scanned [Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported].', 'vec_doc-14-nist-sp-800-53-p270-1022', 0, 238, 'v2.1.0', '3de87121882dacd871fe8f8d0b71510e549d37ffae7b2fc55adb92a748392374', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 243","subsection":"UNKNOWN","table_id":null,"page":270,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1022,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 243"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p270-1023', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 243', 270, 'Discussion:  Due to the complexity of modern software, systems, and other factors, new vulnerabilities are discovered on a regular basis. It is important that newly discovered vulnerabilities are added to the list of vulnerabilities to be scanned to ensure that the organization can take steps to mitigate those vulnerabilities in a timely manner. Related Controls:  SI-5. (3) VULNERABILITY MONITORING AND SCANNING | BREADTH AND DEPTH OF COVERAGE Define the breadth and depth of vulnerability scanning coverage. Discussion:  The breadth of vulnerability scanning coverage can be expressed as a percentage of components within the system, by the particular types of systems, by the criticality of systems, or by the number of vulnerabilities to be checked. Conversely, the depth of vulnerability scanning coverage can be expressed as the level of the system design that the organization intends to monitor (e.g., component, module, subsystem, element).', 'vec_doc-14-nist-sp-800-53-p270-1023', 0, 238, 'v2.1.0', 'ecb50953555ce87e0e30cc8681083d8ede2895f0365dff6515cbc0ca1f53fe1e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 243","subsection":"UNKNOWN","table_id":null,"page":270,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1023,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 243"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p271-1024', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 244', 271, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Organizations can determine the sufficiency of vulnerability scanning coverage with regard to its risk tolerance and other factors. Scanning tools and how the tools are configured may affect the depth and coverage. Multiple scanning tools may be needed to achieve the desired depth and coverage. [SP 800-53A] provides additional information on the breadth and depth of coverage. Related Controls:  None. (4) VULNERABILITY MONITORING AND SCANNING | DISCOVERABLE INFORMATION Determine information about the system that is discoverable and take [Assignment: organization-defined corrective actions]. Discussion:  Discoverable information includes information that adversaries could obtain without compromising or breaching the system, such as by collecting information that the system is exposing or by conducting extensive web searches.', 'vec_doc-14-nist-sp-800-53-p271-1024', 0, 232, 'v2.1.0', '2c699915002cd14228ed8187a3965ab6e2e28e5fa2b07ac25161a6998d296523', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 244","subsection":"UNKNOWN","table_id":null,"page":271,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1024,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 244"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p271-1025', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 244', 271, 'Corrective actions include notifying appropriate organizational personnel, removing designated information, or changing the system to make the designated information less relevant or attractive to adversaries. This enhancement excludes intentionally discoverable information that may be part of a decoy capability (e.g., honeypots, honeynets, or deception nets) deployed by the organization. Related Controls:  AU-13, SC-26. (5) VULNERABILITY MONITORING AND SCANNING | PRIVILEGED ACCESS Implement privileged access authorization to [Assignment: organization-defined system components] for [Assignment: organization-defined vulnerability scanning activities]. Discussion:  In certain situations, the nature of the vulnerability scanning may be more intrusive, or the system component that is the subject of the scanning may contain classified or controlled unclassified information, such as personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p271-1025', 0, 232, 'v2.1.0', '4402ad96e43d891afb1cf83cbb0136a49b5a39248b9e6b9c5471c69a040efa9d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 244","subsection":"UNKNOWN","table_id":null,"page":271,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1025,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 244"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p271-1026', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 244', 271, 'Privileged access authorization to selected system components facilitates more thorough vulnerability scanning and protects the sensitive nature of such scanning. Related Controls:  None. (6) VULNERABILITY MONITORING AND SCANNING | AUTOMATED TREND ANALYSES Compare the results of multiple vulnerability scans using [Assignment: organization- defined automated mechanisms]. Discussion:  Using automated mechanisms to analyze multiple vulnerability scans over time can help determine trends in system vulnerabilities and identify patterns of attack. Related Controls:  None. (7) VULNERABILITY MONITORING AND SCANNING | AUTOMATED DETECTION AND NOTIFICATION OF UNAUTHORIZED COMPONENTS [Withdrawn: Incorporated into CM-8.] (8) VULNERABILITY MONITORING AND SCANNING | REVIEW HISTORIC AUDIT LOGS Review historic audit logs to determine if a vulnerability identified in a [Assignment: organization-defined system] has been previously exploited within an [Assignment: organization-defined time period].', 'vec_doc-14-nist-sp-800-53-p271-1026', 0, 249, 'v2.1.0', '1e22e47ed8a5b5d1c69367449008d138d272852d3473ce97e5d909b1b8cd62b3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 244","subsection":"UNKNOWN","table_id":null,"page":271,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1026,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 244"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p271-1027', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 244', 271, 'Discussion:  Reviewing historic audit logs to determine if a recently detected vulnerability in a system has been previously exploited by an adversary can provide important information for forensic analyses. Such analyses can help identify, for example, the extent of a previous intrusion, the trade craft employed during the attack, organizational information exfiltrated or modified, mission or business capabilities affected, and the duration of the attack. Related Controls:  AU-6, AU-11.', 'vec_doc-14-nist-sp-800-53-p271-1027', 0, 123, 'v2.1.0', '0cdb2ccfc919038c3005427811578892eb6509b90d7179da9ac243dd5887315d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 244","subsection":"UNKNOWN","table_id":null,"page":271,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1027,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 244"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p272-1028', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 245', 272, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (9) VULNERABILITY MONITORING AND SCANNING | PENETRATION TESTING AND ANALYSES [Withdrawn: Incorporated into CA-8.] (10) VULNERABILITY MONITORING AND SCANNING | CORRELATE SCANNING INFORMATION Correlate the output from vulnerability scanning tools to determine the presence of multi- vulnerability and multi-hop attack vectors. Discussion:  An attack vector is a path or means by which an adversary can gain access to a system in order to deliver malicious code or exfiltrate information. Organizations can use attack trees to show how hostile activities by adversaries interact and combine to produce adverse impacts or negative consequences to systems and organizations. Such information, together with correlated data from vulnerability scanning tools, can provide greater clarity regarding multi-vulnerability and multi-hop attack vectors.', 'vec_doc-14-nist-sp-800-53-p272-1028', 0, 233, 'v2.1.0', '29e0d96efa3608c944d027b35d1aea846c302d78c36edbb898a8e534a21aab65', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 245","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1028,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 245"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p272-1029', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 245', 272, 'The correlation of vulnerability scanning information is especially important when organizations are transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). During such transitions, some system components may inadvertently be unmanaged and create opportunities for adversary exploitation. Related Controls:  None. (11) VULNERABILITY MONITORING AND SCANNING | PUBLIC DISCLOSURE PROGRAM Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components. Discussion:  The reporting channel is publicly discoverable and contains clear language authorizing good-faith research and the disclosure of vulnerabilities to the organization. The organization does not condition its authorization on an expectation of indefinite non- disclosure to the public by the reporting entity but may request a specific time period to properly remediate the vulnerability. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p272-1029', 0, 250, 'v2.1.0', '4b5d3d003aa13a8cac9932d57b5a335ddf794d85a2cb993e519f0f897d90edac', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 245","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1029,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 245"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p272-1030', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 245', 272, 'References:  [ISO 29147], [SP 800-40], [SP 800-53A], [SP 800-70], [SP 800-115], [SP 800-126], [IR 7788], [IR 8011-4], [IR 8023]. RA-6 TECHNICAL SURVEILLANCE COUNTERMEASURES SURVEY Control:  Employ a technical surveillance countermeasures survey at [Assignment: organization- defined locations] [Selection (one or more): [Assignment: organization-defined frequency]; when the following events or indicators occur: [Assignment: organization-defined events or indicators]]. Discussion:  A technical surveillance countermeasures survey is a service provided by qualified personnel to detect the presence of technical surveillance devices and hazards and to identify technical security weaknesses that could be used in the conduct of a technical penetration of the surveyed facility.', 'vec_doc-14-nist-sp-800-53-p272-1030', 0, 195, 'v2.1.0', 'c0e4c01d785d7c834e42075cc78771d4ccd24bdc9aad5c0ba60a6640e8f6903c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 245","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1030,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 245"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p272-1031', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 245', 272, 'Technical surveillance countermeasures surveys also provide evaluations of the technical security posture of organizations and facilities and include visual, electronic, and physical examinations of surveyed facilities, internally and externally. The surveys also provide useful input for risk assessments and information regarding organizational exposure to potential adversaries. Related Controls:  None. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p272-1031', 0, 114, 'v2.1.0', 'a2157ffd0c9824a9c976c471d5b8cb4600170b4828a27402243d9f1fd1d9f886', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 245","subsection":"UNKNOWN","table_id":null,"page":272,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1031,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 245"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p273-1032', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 246', 273, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 RA-7 RISK RESPONSE Control:  Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance. Discussion:  Organizations have many options for responding to risk including mitigating risk by implementing new controls or strengthening existing controls, accepting risk with appropriate justification or rationale, sharing or transferring risk, or avoiding risk. The risk tolerance of the organization influences risk response decisions and actions. Risk response addresses the need to determine an appropriate response to risk before generating a plan of action and milestones entry. For example, the response may be to accept risk or reject risk, or it may be possible to mitigate the risk immediately so that a plan of action and milestones entry is not needed. However, if the risk response is to mitigate the risk, and the mitigation cannot be completed immediately, a plan of action and milestones entry is generated. Related Controls:  CA-5, IR-9, PM-4, PM-28, RA-2, RA-3, SR-2. Control Enhancements:  None. References:  [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-160-1]. RA-8 PRIVACY IMPACT ASSESSMENTS Control:  Conduct privacy impact assessments for systems, programs, or other activities before: a. Developing or procuring information technology that processes personally identifiable information; and b. Initiating a new collection of personally identifiable information that:', 'vec_doc-14-nist-sp-800-53-p273-1032', 0, 394, 'v2.1.0', '05f27fb4250729479ce258e6d02954927f2bd6ce983d2461233720f32e8c512e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 246","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1032,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 246"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p273-1033', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Includes personally identifiable information permitting the physical or virtual (online)', 273, 'contacting of a specific individual, if identical questions have been posed to, or identical reporting requirements imposed on, ten or more individuals, other than agencies, instrumentalities, or employees of the federal government. Discussion:  A privacy impact assessment is an analysis of how personally identifiable information is handled to ensure that handling conforms to applicable privacy requirements, determine the privacy risks associated with an information system or activity, and evaluate ways to mitigate privacy risks. A privacy impact assessment is both an analysis and a formal document that details the process and the outcome of the analysis. Organizations conduct and develop a privacy impact assessment with sufficient clarity and specificity to demonstrate that the organization fully considered privacy and incorporated appropriate privacy protections from the earliest stages of the organization’s activity and throughout the information life cycle.', 'vec_doc-14-nist-sp-800-53-p273-1033', 0, 244, 'v2.1.0', '05e6973109347c2e053e6c8f250d663ab69b15bd13f84aea8b50b709152568cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Includes personally identifiable information permitting the physical or virtual (online)","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1033,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Includes personally identifiable information permitting the physical or virtual (online)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p273-1034', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Includes personally identifiable information permitting the physical or virtual (online)', 273, 'In order to conduct a meaningful privacy impact assessment, the organization’s senior agency official for privacy works closely with program managers, system owners, information technology experts, security officials, counsel, and other relevant organization personnel. Moreover, a privacy impact assessment is not a time-restricted activity that is limited to a particular milestone or stage of the information system or personally identifiable information life cycles. Rather, the privacy analysis continues throughout the system and personally identifiable information life cycles. Accordingly, a privacy impact assessment is a living document that organizations update whenever changes to the information technology, changes to the organization’s practices, or other factors alter the privacy risks associated with the use of such information technology. To conduct the privacy impact assessment, organizations can use security and privacy risk assessments.', 'vec_doc-14-nist-sp-800-53-p273-1034', 0, 241, 'v2.1.0', '8f84d989fcc8333a423b9786483ce1fd823be37830dea18bb5800ec3d25a1134', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Includes personally identifiable information permitting the physical or virtual (online)","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1034,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Includes personally identifiable information permitting the physical or virtual (online)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p273-1035', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Includes personally identifiable information permitting the physical or virtual (online)', 273, 'Organizations may also use other related processes that may have different names,', 'vec_doc-14-nist-sp-800-53-p273-1035', 0, 21, 'v2.1.0', '39788339edfc42de0ebf3ce13e9c63eb6f65ad7a0222bb85a2489a717bc1bfa9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Includes personally identifiable information permitting the physical or virtual (online)","subsection":"UNKNOWN","table_id":null,"page":273,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1035,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Includes personally identifiable information permitting the physical or virtual (online)"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p274-1036', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 247', 274, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 including privacy threshold analyses. A privacy impact assessment can also serve as notice to the public regarding the organization’s practices with respect to privacy. Although conducting and publishing privacy impact assessments may be required by law, organizations may develop such policies in the absence of applicable laws. For federal agencies, privacy impact assessments may be required by [EGOV]; agencies should consult with their senior agency official for privacy and legal counsel on this requirement and be aware of the statutory exceptions and OMB guidance relating to the provision. Related Controls:  CM-4, CM-9, CM-13, PT-2, PT-3, PT-5, RA-1, RA-2, RA-3, RA-7. Control Enhancements:  None. References:  [EGOV], [OMB A-130], [OMB M-03-22].', 'vec_doc-14-nist-sp-800-53-p274-1036', 0, 212, 'v2.1.0', 'fd5cc39d5064891e7d1b47e1bf721100e86f68e4ca59b8c1d9f08847abd6f932', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 247","subsection":"UNKNOWN","table_id":null,"page":274,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1036,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 247"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p274-1037', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 247', 274, 'RA-9 CRITICALITY ANALYSIS Control:  Identify critical system components and functions by performing a criticality analysis for [Assignment: organization-defined systems, system components, or system services] at [Assignment: organization-defined decision points in the system development life cycle]. Discussion:  Not all system components, functions, or services necessarily require significant protections. For example, criticality analysis is a key tenet of supply chain risk management and informs the prioritization of protection activities. The identification of critical system components and functions considers applicable laws, executive orders, regulations, directives, policies, standards, system functionality requirements, system and component interfaces, and system and component dependencies. Systems engineers conduct a functional decomposition of a system to identify mission-critical functions and components.', 'vec_doc-14-nist-sp-800-53-p274-1037', 0, 232, 'v2.1.0', 'cb6953198a9bdf2f3bb2888ce0b5bf61895aab5e3cfa8ecd27e571c4b1a07861', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 247","subsection":"UNKNOWN","table_id":null,"page":274,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1037,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 247"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p274-1038', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 247', 274, 'The functional decomposition includes the identification of organizational missions supported by the system, decomposition into the specific functions to perform those missions, and traceability to the hardware, software, and firmware components that implement those functions, including when the functions are shared by many components within and  external to the system. The operational environment of a system or a system component may impact the criticality, including the connections to and dependencies on cyber-physical systems, devices, system-of- systems, and outsourced IT services. System components that allow unmediated access to critical system components or functions are considered critical due to the inherent vulnerabilities that such components create. Component and function criticality are assessed in terms of the impact of a component or function failure on the organizational missions that are supported by the system that contains the components and functions.', 'vec_doc-14-nist-sp-800-53-p274-1038', 0, 247, 'v2.1.0', 'bc034fc8cf9989b59022b3aae0160fa58d778d5a8851b39fc163b43fce858142', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 247","subsection":"UNKNOWN","table_id":null,"page":274,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1038,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 247"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p274-1039', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 247', 274, 'Criticality analysis is performed when an architecture or design is being developed, modified, or upgraded. If such analysis is performed early in the system development life cycle, organizations may be able to modify the system design to reduce the critical nature of these components and functions, such as by adding redundancy or alternate paths into the system design. Criticality analysis can also influence the protection measures required by development contractors. In addition to criticality analysis for systems, system components, and system services, criticality analysis of information is an important consideration. Such analysis is conducted as part of security categorization in RA-2. Related Controls:  CP-2, PL-2, PL-8, PL-11, PM-1, PM-11, RA-2, SA-8, SA-15, SA-20, SR-5. Control Enhancements:  None. References:  [IR 8179]. RA-10 THREAT HUNTING Control:', 'vec_doc-14-nist-sp-800-53-p274-1039', 0, 218, 'v2.1.0', 'c4e23a2c48ee6e419d9b2e2149072eaa0c3e1e1da47bc6230c73e5a26a52a13e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 247","subsection":"UNKNOWN","table_id":null,"page":274,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1039,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 247"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p275-1040', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 248', 275, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Establish and maintain a cyber threat hunting capability to:', 'vec_doc-14-nist-sp-800-53-p275-1040', 0, 39, 'v2.1.0', '50f13dc8976aa4b56d1f84d116790c51430f3459136d4a77426a28459e47a75f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 248","subsection":"UNKNOWN","table_id":null,"page":275,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1040,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 248"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p275-1041', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Detect, track, and disrupt threats that evade existing controls; and', 275, 'b. Employ the threat hunting capability [Assignment: organization-defined frequency]. Discussion:  Threat hunting is an active means of cyber defense in contrast to traditional protection measures, such as firewalls, intrusion detection and prevention systems, quarantining malicious code in sandboxes, and Security Information and Event Management technologies and systems. Cyber threat hunting involves proactively searching organizational systems, networks, and infrastructure for advanced threats. The objective is to track and disrupt cyber adversaries as early as possible in the attack sequence and to measurably improve the speed and accuracy of organizational responses. Indications of compromise include unusual network traffic, unusual file changes, and the presence of malicious code. Threat hunting teams leverage existing threat intelligence and may create new threat intelligence, which is shared with peer organizations, Information Sharing and Analysis Organizations (ISAO), Information Sharing and Analysis Centers (ISAC), and relevant government departments and agencies. Related Controls:  CA-2, CA-7, CA-8, RA-3, RA-5, RA-6, SI-4. Control Enhancements:  None. References:  [SP 800-30].', 'vec_doc-14-nist-sp-800-53-p275-1041', 0, 302, 'v2.1.0', '7641336ccd65122172b0d27be47ac53f400bc1ff3a3346bc63a8e099d2436bc3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Detect, track, and disrupt threats that evade existing controls; and","subsection":"UNKNOWN","table_id":null,"page":275,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1041,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Detect, track, and disrupt threats that evade existing controls; and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p276-1042', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.17   SYSTEM AND SERVICES ACQUISITION', 276, 'Quick link to System and Services Acquisition Summary Table SA-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p276-1042', 0, 48, 'v2.1.0', 'ae138432d5adc6188c85e3404dfb7406a5c53d2d859810aaf8f316f90522bf0d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.17   SYSTEM AND SERVICES ACQUISITION","subsection":"UNKNOWN","table_id":null,"page":276,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1042,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.17   SYSTEM AND SERVICES ACQUISITION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p276-1043', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 276, 'level] system and services acquisition policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p276-1043', 0, 80, 'v2.1.0', '88ce56ad98e2d8c3cc41339ab5d6c98fcfe19f4104c7c4e230b5a464fe272826', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":276,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1043,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p276-1044', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the system and services acquisition', 276, 'policy and the associated system and services acquisition controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and services acquisition policy and procedures; and c. Review and update the current system and services acquisition:', 'vec_doc-14-nist-sp-800-53-p276-1044', 0, 80, 'v2.1.0', '55729e6ab461b1fd72ca8c72c88db77b2abedc52d842dcfe78a2649ae145b0c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the system and services acquisition","subsection":"UNKNOWN","table_id":null,"page":276,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1044,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the system and services acquisition"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p276-1045', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 276, 'organization-defined events]. Discussion:  System and services acquisition policy and procedures address the controls in the SA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and services acquisition policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and services acquisition policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SA-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-30], [SP 800-39], [SP 800-100], [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p276-1045', 0, 441, 'v2.1.0', '46ab42e0c36ed01f698ae37b75816ff259ad0c253f1a5675c280e3475c647c17', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":276,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1045,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p277-1046', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 250', 277, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-2 ALLOCATION OF RESOURCES Control: a. Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning; b. Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; and c. Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation. Discussion:  Resource allocation for information security and privacy includes funding for system and services acquisition, sustainment, and supply chain-related risks throughout the system development life cycle. Related Controls:  PL-7, PM-3, PM-11, SA-9, SR-3, SR-5. Control Enhancements:  None. References:  [OMB A-130], [SP 800-37], [SP 800-160-1]. SA-3 SYSTEM DEVELOPMENT LIFE CYCLE Control: a.', 'vec_doc-14-nist-sp-800-53-p277-1046', 0, 248, 'v2.1.0', '964d7fd864ea4166081f1050cef56d9dfc108fe220a62d44ec140430a5a07064', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 250","subsection":"UNKNOWN","table_id":null,"page":277,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1046,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 250"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p277-1047', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 250', 277, 'Acquire, develop, and manage the system using [Assignment: organization-defined system development life cycle] that incorporates information security and privacy considerations; b. Define and document information security and privacy roles and responsibilities throughout the system development life cycle; c. Identify individuals having information security and privacy roles and responsibilities; and d. Integrate the organizational information security and privacy risk management process into system development life cycle activities. Discussion:  A system development life cycle process provides the foundation for the successful development, implementation, and operation of organizational systems. The integration of security and privacy considerations early in the system development life cycle is a foundational principle of systems security engineering and privacy engineering.', 'vec_doc-14-nist-sp-800-53-p277-1047', 0, 222, 'v2.1.0', 'bb175b6b4869cdd49066e87849122cc75cf4aa1e32e230c3886d237fa3254864', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 250","subsection":"UNKNOWN","table_id":null,"page":277,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1047,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 250"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p277-1048', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 250', 277, 'To apply the required controls within the system development life cycle requires a basic understanding of information security and privacy, threats, vulnerabilities, adverse impacts, and risk to critical mission and business functions. The security engineering principles in SA-8 help individuals properly design, code, and test systems and system components. Organizations include qualified personnel (e.g., senior agency information security officers, senior agency officials for privacy, security and privacy architects, and security and privacy engineers) in system development life cycle processes to ensure that established security and privacy requirements are incorporated into organizational systems. Role-based security and privacy training programs can ensure that individuals with key security and privacy roles and responsibilities have the experience, skills, and expertise to conduct assigned system development life cycle activities.', 'vec_doc-14-nist-sp-800-53-p277-1048', 0, 238, 'v2.1.0', 'ae924ce4fee4e3deda9c5635cc4edebb8f6b78c4b68b48c3fa5002f748eab160', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 250","subsection":"UNKNOWN","table_id":null,"page":277,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1048,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 250"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p277-1049', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 250', 277, 'The effective integration of security and privacy requirements into enterprise architecture also helps to ensure that important security and privacy considerations are addressed throughout the system life cycle and that those considerations are directly related to organizational mission and business processes. This process also facilitates the integration of the information security and privacy architectures into the enterprise architecture, consistent with the risk management strategy of the organization. Because the system development life cycle involves multiple organizations, (e.g., external suppliers, developers, integrators, service providers), acquisition', 'vec_doc-14-nist-sp-800-53-p277-1049', 0, 168, 'v2.1.0', 'cab0c8405b55cad7f51be3656032c2db78fb29300f90f26927698e442bce05a9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 250","subsection":"UNKNOWN","table_id":null,"page":277,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1049,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 250"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p278-1050', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 251', 278, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and supply chain risk management functions and controls play significant roles in the effective management of the system during the life cycle. Related Controls:  AT-3, PL-8, PM-7, SA-4, SA-5, SA-8, SA-11, SA-15, SA-17, SA-22, SR-3, SR-4, SR- 5, SR-9. Control Enhancements: (1) SYSTEM DEVELOPMENT LIFE CYCLE | MANAGE PREPRODUCTION ENVIRONMENT Protect system preproduction environments commensurate with risk throughout the system development life cycle for the system, system component, or system service. Discussion:  The preproduction environment includes development, test, and integration environments. The program protection planning processes established by the Department of Defense are examples of managing the preproduction environment for defense contractors. Criticality analysis and the application of controls on developers also contribute to a more secure system development environment.', 'vec_doc-14-nist-sp-800-53-p278-1050', 0, 249, 'v2.1.0', '1dbada2161c471f2a8b22ba8efb2a345587d4776f3094fb084524b6a5cb41441', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 251","subsection":"UNKNOWN","table_id":null,"page":278,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1050,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 251"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p278-1051', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 251', 278, 'Related Controls:  CM-2, CM-4, RA-3, RA-9, SA-4. (2) SYSTEM DEVELOPMENT LIFE CYCLE | USE OF LIVE OR OPERATIONAL DATA (a) Approve, document, and control the use of live data in preproduction environments for the system, system component, or system service; and (b) Protect preproduction environments for the system, system component, or system service at the same impact or classification level as any live data in use within the preproduction environments. Discussion:  Live data is also referred to as operational data. The use of live or operational data in preproduction (i.e., development, test, and integration) environments can result in significant risks to organizations. In addition, the use of personally identifiable information in testing, research, and training increases the risk of unauthorized disclosure or misuse of such information. Therefore, it is important for the organization to manage any additional risks that may result from the use of live or operational data.', 'vec_doc-14-nist-sp-800-53-p278-1051', 0, 247, 'v2.1.0', 'b8fb2aab4794f96206736066e439f7dcbf99a48ca7c677fe05e4bd16e0979443', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 251","subsection":"UNKNOWN","table_id":null,"page":278,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1051,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 251"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p278-1052', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 251', 278, 'Organizations can minimize such risks by using test or dummy data during the design, development, and testing of systems, system components, and system services. Risk assessment techniques may be used to determine if the risk of using live or operational data is acceptable. Related Controls:  PM-25, RA-3. (3) SYSTEM DEVELOPMENT LIFE CYCLE | TECHNOLOGY REFRESH Plan for and implement a technology refresh schedule for the system throughout the system development life cycle. Discussion:  Technology refresh planning may encompass hardware, software, firmware, processes, personnel skill sets, suppliers, service providers, and facilities. The use of obsolete or nearing obsolete technology may increase the security and privacy risks associated with unsupported components, counterfeit or repurposed components, components unable to implement security or privacy requirements, slow or inoperable components, components from untrusted sources, inadvertent personnel error, or increased complexity.', 'vec_doc-14-nist-sp-800-53-p278-1052', 0, 250, 'v2.1.0', '3e209f6875b1ef91fcb7ebe9ddb1c3a3d0c52bdfe6e139eef852e47e9f9646e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 251","subsection":"UNKNOWN","table_id":null,"page":278,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1052,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 251"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p278-1053', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 251', 278, 'Technology refreshes typically occur during the operations and maintenance stage of the system development life cycle. Related Controls:  MA-6. References:  [OMB A-130], [SP 800-30], [SP 800-37], [SP 800-160-1], [SP 800-171], [SP 800-172].', 'vec_doc-14-nist-sp-800-53-p278-1053', 0, 60, 'v2.1.0', '8237e4077683ea97a76e29f528cd1e6411de26c07012614927bfcbe3351e48f1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 251","subsection":"UNKNOWN","table_id":null,"page":278,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1053,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 251"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p279-1054', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 252', 279, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-4 ACQUISITION PROCESS Control:  Include the following requirements, descriptions, and criteria, explicitly or by reference, using [Selection (one or more): standardized contract language; [Assignment: organization- defined contract language]] in the acquisition contract for the system, system component, or system service: a. Security and privacy functional requirements; b. Strength of mechanism requirements; c. Security and privacy assurance requirements; d. Controls needed to satisfy the security and privacy requirements. e. Security and privacy documentation requirements; f. Requirements for protecting security and privacy documentation; g. Description of the system development environment and environment in which the system is intended to operate; h. Allocation of responsibility or identification of parties responsible for information security, privacy, and supply chain risk management; and i.', 'vec_doc-14-nist-sp-800-53-p279-1054', 0, 251, 'v2.1.0', 'b358325cc728f9b9e09d4b7c6158b3148dee3753e143a95af503b0084bf48f4a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 252","subsection":"UNKNOWN","table_id":null,"page":279,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1054,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 252"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p279-1055', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 252', 279, 'Acceptance criteria. Discussion:  Security and privacy functional requirements are typically derived from the high- level security and privacy requirements described in SA-2. The derived requirements include security and privacy capabilities, functions, and mechanisms. Strength requirements associated with such capabilities, functions, and mechanisms include degree of correctness, completeness, resistance to tampering or bypass, and resistance to direct attack. Assurance requirements include development processes, procedures, and methodologies as well as the evidence from development and assessment activities that provide grounds for confidence that the required functionality is implemented and possesses the required strength of mechanism. [SP 800-160-1] describes the process of requirements engineering as part of the system development life cycle.', 'vec_doc-14-nist-sp-800-53-p279-1055', 0, 215, 'v2.1.0', '755d942ffd171f34125b99deb54d4a89e11f92ef153c440bc9a58663ee79a090', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 252","subsection":"UNKNOWN","table_id":null,"page":279,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1055,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 252"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p279-1056', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 252', 279, 'Controls can be viewed as descriptions of the safeguards and protection capabilities appropriate for achieving the particular security and privacy objectives of the organization and for reflecting the security and privacy requirements of stakeholders. Controls are selected and implemented in order to satisfy system requirements and include developer and organizational responsibilities. Controls can include technical, administrative, and physical aspects. In some cases, the selection and implementation of a control may necessitate additional specification by the organization in the form of derived requirements or instantiated control parameter values. The derived requirements and control parameter values may be necessary to provide the appropriate level of implementation detail for controls within the system development life cycle. Security and privacy documentation requirements address all stages of the system development life cycle.', 'vec_doc-14-nist-sp-800-53-p279-1056', 0, 237, 'v2.1.0', '7b9d13b04dcf791da345db865498f946d07b51931740cd8d0283d02e39cd7187', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 252","subsection":"UNKNOWN","table_id":null,"page":279,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1056,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 252"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p279-1057', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 252', 279, 'Documentation provides user and administrator guidance for the implementation and operation of controls. The level of detail required in such documentation is based on the security categorization or classification level of the system and the degree to which organizations depend on the capabilities, functions, or mechanisms to meet risk response expectations. Requirements can include mandated configuration settings that specify allowed functions, ports, protocols, and services. Acceptance criteria for systems, system components, and system services are defined in the same manner as the criteria for any organizational acquisition or procurement. Related Controls:  CM-6, CM-8, PS-7, SA-3, SA-5, SA-8, SA-11, SA-15, SA-16, SA-17, SA-21, SR-3 , SR-5. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p279-1057', 0, 194, 'v2.1.0', 'b8da8177622029a964522e3dfdd152a9a926b3c25bc55e4457bae590e17286fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 252","subsection":"UNKNOWN","table_id":null,"page":279,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1057,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 252"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p280-1058', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 253', 280, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) ACQUISITION PROCESS | FUNCTIONAL PROPERTIES OF CONTROLS Require the developer of the system, system component, or system service to provide a description of the functional properties of the controls to be implemented. Discussion:  Functional properties of security and privacy controls describe the functionality (i.e., security or privacy capability, functions, or mechanisms) visible at the interfaces of the controls and specifically exclude functionality and data structures internal to the operation of the controls. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p280-1058', 0, 161, 'v2.1.0', '27311630ec9836fea80aeedb59d1ef651fc79c768975a97f68aeb7fa21a8f4f8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 253","subsection":"UNKNOWN","table_id":null,"page":280,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1058,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 253"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p280-1059', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 253', 280, '(2) ACQUISITION PROCESS | DESIGN AND IMPLEMENTATION INFORMATION FOR CONTROLS Require the developer of the system, system component, or system service to provide design and implementation information for the controls that includes: [Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information]] at [Assignment: organization-defined level of detail]. Discussion:  Organizations may require different levels of detail in the documentation for the design and implementation of controls in organizational systems, system components, or system services based on mission and business requirements, requirements for resiliency and trustworthiness, and requirements for analysis and testing. Systems can be partitioned into multiple subsystems. Each subsystem within the system can contain one or more modules.', 'vec_doc-14-nist-sp-800-53-p280-1059', 0, 240, 'v2.1.0', 'd5ac578f62fa1a937c10bc52a15b205f758fc17cd4727fcc95fb503b11e4ba82', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 253","subsection":"UNKNOWN","table_id":null,"page":280,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1059,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 253"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p280-1060', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 253', 280, 'The high-level design for the system is expressed in terms of subsystems and the interfaces between subsystems providing security-relevant functionality. The low-level design for the system is expressed in terms of modules and the interfaces between modules providing security-relevant functionality. Design and implementation documentation can include manufacturer, version, serial number, verification hash signature, software libraries used, date of purchase or download, and the vendor or download source. Source code and hardware schematics are referred to as the implementation representation of the system. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p280-1060', 0, 160, 'v2.1.0', '987154e3ef1c6d9fcd490fb9ffd5786f37ad8cd024828c5a3c4bd2ba222d0c3a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 253","subsection":"UNKNOWN","table_id":null,"page":280,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1060,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 253"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p280-1061', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 253', 280, '(3) ACQUISITION PROCESS | DEVELOPMENT METHODS, TECHNIQUES, AND PRACTICES Require the developer of the system, system component, or system service to demonstrate the use of a system development life cycle process that includes: (a) [Assignment: organization-defined systems engineering methods]; (b) [Assignment: organization-defined [Selection (one or more): systems security; privacy] engineering methods]; and (c) [Assignment: organization-defined software development methods; testing, evaluation, assessment, verification, and validation methods; and quality control processes]. Discussion:  Following a system development life cycle that includes state-of-the-practice software development methods, systems engineering methods, systems security and privacy engineering methods, and quality control processes helps to reduce the number and severity of latent errors within systems, system components, and system services.', 'vec_doc-14-nist-sp-800-53-p280-1061', 0, 232, 'v2.1.0', '99ccfa97ebfa3715625e353476eed17a8b2710cbc18759b0fbdaf2058f88a5f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 253","subsection":"UNKNOWN","table_id":null,"page":280,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1061,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 253"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p280-1062', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 253', 280, 'Reducing the number and severity of such errors reduces the number of vulnerabilities in those systems, components, and services. Transparency in the methods and techniques that developers select and implement for systems engineering, systems security and privacy engineering, software development, component and system assessments, and quality control processes provides an increased level of assurance in the trustworthiness of the system, system component, or system service being acquired. Related Controls:  None. (4) ACQUISITION PROCESS | ASSIGNMENT OF COMPONENTS TO SYSTEMS', 'vec_doc-14-nist-sp-800-53-p280-1062', 0, 145, 'v2.1.0', 'edf5beb9c2506a63c4b982ec0de5288efa5605bbd550cc13e5c7148db88cadba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 253","subsection":"UNKNOWN","table_id":null,"page":280,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1062,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 253"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p281-1063', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 254', 281, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Incorporated into CM-8(9).] (5) ACQUISITION PROCESS | SYSTEM, COMPONENT, AND SERVICE CONFIGURATIONS Require the developer of the system, system component, or system service to: (a) Deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented; and (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade. Discussion:  Examples of security configurations include the U.S. Government Configuration Baseline (USGCB), Security Technical Implementation Guides (STIGs), and any limitations on functions, ports, protocols, and services. Security characteristics can include requiring that default passwords have been changed. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p281-1063', 0, 216, 'v2.1.0', '2c2df3f0c9a5d9b6fd2747f3f51645ea41eea67ed692bfab26f196ccfec54c30', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 254","subsection":"UNKNOWN","table_id":null,"page":281,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1063,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 254"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p281-1064', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 254', 281, '(6) ACQUISITION PROCESS | USE OF INFORMATION ASSURANCE PRODUCTS (a) Employ only government off-the-shelf or commercial off-the-shelf information assurance and information assurance-enabled information technology products that compose an NSA-approved solution to protect classified information when the networks used to transmit the information are at a lower classification level than the information being transmitted; and (b) Ensure that these products have been evaluated and/or validated by NSA or in accordance with NSA-approved procedures. Discussion:  Commercial off-the-shelf IA or IA-enabled information technology products used to protect classified information by cryptographic means may be required to use NSA- approved key management. See [NSA CSFC]. Related Controls:  SC-8, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p281-1064', 0, 201, 'v2.1.0', 'b09bb4ab1fe16ee1c069e3af4cf4f5a33a8c483ebf5e1b239b32640635ffb2d3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 254","subsection":"UNKNOWN","table_id":null,"page":281,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1064,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 254"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p281-1065', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 254', 281, '(7) ACQUISITION PROCESS | NIAP-APPROVED PROTECTION PROFILES (a) Limit the use of commercially provided information assurance and information assurance-enabled information technology products to those products that have been successfully evaluated against a National Information Assurance partnership (NIAP)- approved Protection Profile for a specific technology type, if such a profile exists; and (b) Require, if no NIAP-approved Protection Profile exists for a specific technology type but a commercially provided information technology product relies on cryptographic functionality to enforce its security policy, that the cryptographic module is FIPS- validated or NSA-approved. Discussion:  See [NIAP CCEVS] for additional information on NIAP. See [NIST CMVP ] for additional information on FIPS-validated cryptographic modules. Related Controls:  IA-7, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p281-1065', 0, 218, 'v2.1.0', 'b1c412375492e1e94f3a9653dec10e966fb7965cb809c60595698bd35e1ccb5c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 254","subsection":"UNKNOWN","table_id":null,"page":281,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1065,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 254"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p281-1066', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 254', 281, '(8) ACQUISITION PROCESS | CONTINUOUS MONITORING PLAN FOR CONTROLS Require the developer of the system, system component, or system service to produce a plan for continuous monitoring of control effectiveness that is consistent with the continuous monitoring program of the organization. Discussion:  The objective of continuous monitoring plans is to determine if the planned, required, and deployed controls within the system, system component, or system service continue to be effective over time based on the inevitable changes that occur. Developer continuous monitoring plans include a sufficient level of detail such that the information can be incorporated into continuous monitoring programs implemented by organizations. Continuous monitoring plans can include the types of control assessment and monitoring', 'vec_doc-14-nist-sp-800-53-p281-1066', 0, 204, 'v2.1.0', '981f25dfd78411cf01073d4e291e76c183c21fd8ac7def1cfbf5f6e396e9943e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 254","subsection":"UNKNOWN","table_id":null,"page":281,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1066,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 254"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p282-1067', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 255', 282, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 activities planned, frequency of control monitoring, and actions to be taken when controls fail or become ineffective. Related Controls:  CA-7. (9) ACQUISITION PROCESS | FUNCTIONS, PORTS, PROTOCOLS, AND SERVICES IN USE Require the developer of the system, system component, or system service to identify the functions, ports, protocols, and services intended for organizational use. Discussion:  The identification of functions, ports, protocols, and services early in the system development life cycle (e.g., during the initial requirements definition and design stages) allows organizations to influence the design of the system, system component, or system service.', 'vec_doc-14-nist-sp-800-53-p282-1067', 0, 190, 'v2.1.0', 'f41f18a49f02710529e19d60f0bea1c5ec8d8a98d6b01d95f7db1e0e89711877', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 255","subsection":"UNKNOWN","table_id":null,"page":282,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1067,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 255"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p282-1068', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 255', 282, 'This early involvement in the system development life cycle helps organizations avoid or minimize the use of functions, ports, protocols, or services that pose unnecessarily high risks and understand the trade-offs involved in blocking specific ports, protocols, or services or requiring system service providers to do so. Early identification of functions, ports, protocols, and services avoids costly retrofitting of controls after the system, component, or system service has been implemented. SA-9 describes the requirements for external system services. Organizations identify which functions, ports, protocols, and services are provided from external sources. Related Controls:  CM-7, SA-9. (10) ACQUISITION PROCESS | USE OF APPROVED PIV PRODUCTS Employ only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational systems.', 'vec_doc-14-nist-sp-800-53-p282-1068', 0, 233, 'v2.1.0', 'fb87113fa7e3892b892a4ff6a9a5773a2f9d5a1b8ff0de67a818efbff90bf938', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 255","subsection":"UNKNOWN","table_id":null,"page":282,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1068,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 255"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p282-1069', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 255', 282, 'Discussion:  Products on the FIPS 201-approved products list meet NIST requirements for Personal Identity Verification (PIV) of Federal Employees and Contractors. PIV cards are used for multi-factor authentication in systems and organizations. Related Controls:  IA-2, IA-8, PM-9. (11) ACQUISITION PROCESS | SYSTEM OF RECORDS Include [Assignment: organization-defined Privacy Act requirements] in the acquisition contract for the operation of a system of records on behalf of an organization to accomplish an organizational mission or function. Discussion: When, by contract, an organization provides for the operation of a system of records to accomplish an organizational mission or function, the organization, consistent with its authority, causes the requirements of the [PRIVACT] to be applied to the system of records. Related Controls:  PT-6.', 'vec_doc-14-nist-sp-800-53-p282-1069', 0, 213, 'v2.1.0', '72385b87bdd963dcd0e6ba33d49769c1677774a43e78f6271b6e95749fcdf78f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 255","subsection":"UNKNOWN","table_id":null,"page":282,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1069,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 255"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p282-1070', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 255', 282, '(12) ACQUISITION PROCESS | DATA OWNERSHIP (a) Include organizational data ownership requirements in the acquisition contract; and (b) Require all data to be removed from the contractor’s system and returned to the organization within [Assignment: organization-defined time frame]. Discussion: Contractors who operate a system that contains data owned by an organization initiating the contract have policies and procedures in place to remove the data from their systems and/or return the data in a time frame defined by the contract. Related Controls:  None. References:  [PRIVACT], [OMB A-130], [ISO 15408-1], [ISO 15408-2], [ISO 15408-3], [ISO 29148], [FIPS 140-3], [FIPS 201-2], [SP 800-35], [SP 800-37], [SP 800-70], [SP 800-73-4], [SP 800-137], [SP 800-160-1], [SP 800-161], [IR 7539], [IR 7622], [IR 7676], [IR 7870], [IR 8062], [NIAP CCEVS], [NSA CSFC].', 'vec_doc-14-nist-sp-800-53-p282-1070', 0, 215, 'v2.1.0', 'a3c6f737810c9223ceeb8d9cc415b424f9e89ecdb90866e6f91348021695eec7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 255","subsection":"UNKNOWN","table_id":null,"page":282,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1070,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 255"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1071', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 256', 283, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-5 SYSTEM DOCUMENTATION Control: a. Obtain or develop administrator documentation for the system, system component, or system service that describes:', 'vec_doc-14-nist-sp-800-53-p283-1071', 0, 61, 'v2.1.0', 'b0efec746253e2f0f08eccd216cc0dd19f07ab21d7c00be5b101398dd68e717d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 256","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1071,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 256"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1072', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. Known vulnerabilities regarding configuration and use of administrative or privileged', 283, 'functions; b. Obtain or develop user documentation for the system, system component, or system service that describes:', 'vec_doc-14-nist-sp-800-53-p283-1072', 0, 30, 'v2.1.0', 'f5be9951f2d65e4c87cc1a0bd73799706ea12e6e0eb6d2ef9b25afb58137b9a9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. Known vulnerabilities regarding configuration and use of administrative or privileged","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1072,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. Known vulnerabilities regarding configuration and use of administrative or privileged"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1073', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. User-accessible security and privacy functions and mechanisms and how to effectively', 283, 'use those functions and mechanisms;', 'vec_doc-14-nist-sp-800-53-p283-1073', 0, 9, 'v2.1.0', '2ded14aba51102d7861b3f17cdb881d9a5d20d9ca5daf3231edc78257635181d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. User-accessible security and privacy functions and mechanisms and how to effectively","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1073,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. User-accessible security and privacy functions and mechanisms and how to effectively"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1074', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Methods for user interaction, which enables individuals to use the system, component,', 283, 'or service in a more secure manner and protect individual privacy; and', 'vec_doc-14-nist-sp-800-53-p283-1074', 0, 18, 'v2.1.0', '002138480449c322e37b111f64b06f789ea5b431ce6660ea0551d848419f2395', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Methods for user interaction, which enables individuals to use the system, component,","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1074,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Methods for user interaction, which enables individuals to use the system, component,"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1075', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. User responsibilities in maintaining the security of the system, component, or service', 283, 'and privacy of individuals; c. Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent and take [Assignment: organization-defined actions] in response; and d. Distribute documentation to [Assignment: organization-defined personnel or roles]. Discussion:  System documentation helps personnel understand the implementation and operation of controls. Organizations consider establishing specific measures to determine the quality and completeness of the content provided. System documentation may be used to support the management of supply chain risk, incident response, and other functions. Personnel or roles that require documentation include system owners, system security officers, and system administrators. Attempts to obtain documentation include contacting manufacturers or suppliers and conducting web-based searches.', 'vec_doc-14-nist-sp-800-53-p283-1075', 0, 230, 'v2.1.0', '966427a90567a8d385281aa234f939eafb8f575117c89ed5be896480901968e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. User responsibilities in maintaining the security of the system, component, or service","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1075,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. User responsibilities in maintaining the security of the system, component, or service"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1076', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. User responsibilities in maintaining the security of the system, component, or service', 283, 'The inability to obtain documentation may occur due to the age of the system or component or the lack of support from developers and contractors. When documentation cannot be obtained, organizations may need to recreate the documentation if it is essential to the implementation or operation of the controls. The protection provided for the documentation is commensurate with the security category or classification of the system. Documentation that addresses system vulnerabilities may require an increased level of protection. Secure operation of the system includes initially starting the system and resuming secure system operation after a lapse in system operation. Related Controls:  CM-4, CM-6, CM-7, CM-8, PL-2, PL-4, PL-8, PS-2, SA-3, SA-4, SA-8, SA-9, SA-10, SA-11, SA-15, SA-16, SA-17, SI-12, SR-3.', 'vec_doc-14-nist-sp-800-53-p283-1076', 0, 203, 'v2.1.0', 'cb22e1f9b4b247b2121e2a7c174a63e6d6a24bcb08a90bbc09aa1383bd4232d2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. User responsibilities in maintaining the security of the system, component, or service","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1076,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. User responsibilities in maintaining the security of the system, component, or service"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p283-1077', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3. User responsibilities in maintaining the security of the system, component, or service', 283, 'Control Enhancements: (1) SYSTEM DOCUMENTATION | FUNCTIONAL PROPERTIES OF SECURITY CONTROLS [Withdrawn: Incorporated into SA-4(1).] (2) SYSTEM DOCUMENTATION | SECURITY-RELEVANT EXTERNAL SYSTEM INTERFACES [Withdrawn: Incorporated into SA-4(2).] (3) SYSTEM DOCUMENTATION | HIGH-LEVEL DESIGN [Withdrawn: Incorporated into SA-4(2).]', 'vec_doc-14-nist-sp-800-53-p283-1077', 0, 82, 'v2.1.0', 'f668d884ffc9afb802a580d16024cfe840f1e723bdad8444a0ec0a381f5a216f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3. User responsibilities in maintaining the security of the system, component, or service","subsection":"UNKNOWN","table_id":null,"page":283,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1077,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3. User responsibilities in maintaining the security of the system, component, or service"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p284-1078', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 257', 284, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (4) SYSTEM DOCUMENTATION | LOW-LEVEL DESIGN [Withdrawn: Incorporated into SA-4(2).] (5) SYSTEM DOCUMENTATION | SOURCE CODE [Withdrawn: Incorporated into SA-4(2).] References:  [SP 800-160-1]. SA-6 SOFTWARE USAGE RESTRICTIONS [Withdrawn: Incorporated into CM-10 and SI-7.] SA-7 USER-INSTALLED SOFTWARE [Withdrawn: Incorporated into CM-11 and SI-7.] SA-8 SECURITY AND PRIVACY ENGINEERING PRINCIPLES Control:  Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components: [Assignment: organization-defined systems security and privacy engineering principles]. Discussion:  Systems security and privacy engineering principles are closely related to and implemented throughout the system development life cycle (see SA-3).', 'vec_doc-14-nist-sp-800-53-p284-1078', 0, 233, 'v2.1.0', '8e8f8b8402478bf5536b9d6840bf84dbd4dd91611a11431e1487750b9f2c2e49', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 257","subsection":"UNKNOWN","table_id":null,"page":284,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1078,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 257"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p284-1079', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 257', 284, 'Organizations can apply systems security and privacy engineering principles to new systems under development or to systems undergoing upgrades. For existing systems, organizations apply systems security and privacy engineering principles to system upgrades and modifications to the extent feasible, given the current state of hardware, software, and firmware components within those systems. The application of systems security and privacy engineering principles helps organizations develop trustworthy, secure, and resilient systems and reduces the susceptibility to disruptions, hazards, threats, and the creation of privacy problems for individuals.', 'vec_doc-14-nist-sp-800-53-p284-1079', 0, 163, 'v2.1.0', '2a1b8d7d1a7b6c8fb7ba2a49e6095d56ff662360233954b38f78f179c3ddeec1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 257","subsection":"UNKNOWN","table_id":null,"page":284,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1079,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 257"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p284-1080', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 257', 284, 'Examples of system security engineering principles include: developing layered protections; establishing security and privacy policies, architecture, and controls as the foundation for design and development; incorporating security and privacy requirements into the system development life cycle; delineating physical and logical security boundaries; ensuring that developers are trained on how to build secure software; tailoring controls to meet organizational needs; and performing threat modeling to identify use cases, threat agents, attack vectors and patterns, design patterns, and compensating controls needed to mitigate risk. Organizations that apply systems security and privacy engineering concepts and principles can facilitate the development of trustworthy, secure systems, system components, and system services; reduce risk to acceptable levels; and make informed risk management decisions.', 'vec_doc-14-nist-sp-800-53-p284-1080', 0, 227, 'v2.1.0', '1e1a895eeddbedf12ad2112bfe265963b920ed5b93d1e551bbdeb9b1c1a461b6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 257","subsection":"UNKNOWN","table_id":null,"page":284,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1080,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 257"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p284-1081', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 257', 284, 'System security engineering principles can also be used to protect against certain supply chain risks, including incorporating tamper-resistant hardware into a design. Related Controls:  PL-8, PM-7, RA-2, RA-3, RA-9, SA-3, SA-4, SA-15, SA-17, SA-20, SC-2, SC-3, SC- 32, SC-39, SR-2, SR-3, SR-4, SR-5. Control Enhancements: (1) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | CLEAR ABSTRACTIONS Implement the security design principle of clear abstractions. Discussion:  The principle of clear abstractions states that a system has simple, well-defined interfaces and functions that provide a consistent and intuitive view of the data and how the data is managed. The clarity, simplicity, necessity, and sufficiency of the system interfaces—', 'vec_doc-14-nist-sp-800-53-p284-1081', 0, 185, 'v2.1.0', '4911eddb6cf5fb0dfe12837595d9b8219a5d7d0a2f62268cdc23d4bf19c557f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 257","subsection":"UNKNOWN","table_id":null,"page":284,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1081,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 257"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p285-1082', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 258', 285, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 combined with a precise definition of their functional behavior— promotes ease of analysis, inspection, and testing as well as the correct and secure use of the system. The clarity of an abstraction is subjective. Examples that reflect the application of this principle include avoidance of redundant, unused interfaces; information hiding; and avoidance of semantic overloading of interfaces or their parameters. Information hiding (i.e., representation- independent programming), is a design discipline used to ensure that the internal representation of information in one system component is not visible to another system component invoking or calling the first component, such that the published abstraction is not influenced by how the data may be managed internally. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p285-1082', 0, 223, 'v2.1.0', '339deb60ec775ac4a081502b85fef3d29827dac7504ecdad9eda85db6f2301c7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 258","subsection":"UNKNOWN","table_id":null,"page":285,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1082,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 258"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p285-1083', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 258', 285, '(2) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | LEAST COMMON MECHANISM Implement the security design principle of least common mechanism in [Assignment: organization-defined systems or system components]. Discussion:  The principle of least common mechanism states that the amount of mechanism common to more than one user and depended on by all users is minimized [POPEK74]. Mechanism minimization implies that different components of a system refrain from using the same mechanism to access a system resource. Every shared mechanism (especially a mechanism involving shared variables) represents a potential information path between users and is designed with care to ensure that it does not unintentionally compromise security [SALTZER75]. Implementing the principle of least common mechanism helps to reduce the adverse consequences of sharing the system state among different programs.', 'vec_doc-14-nist-sp-800-53-p285-1083', 0, 223, 'v2.1.0', '9338bc4775554cb1ca85e4b52d867dca605c6e76bd7f4e95947c5292ee69131b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 258","subsection":"UNKNOWN","table_id":null,"page":285,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1083,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 258"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p285-1084', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 258', 285, 'A single program that corrupts a shared state (including shared variables) has the potential to corrupt other programs that are dependent on the state. The principle of least common mechanism also supports the principle of simplicity of design and addresses the issue of covert storage channels [LAMPSON73]. Related Controls:  None. (3) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | MODULARITY AND LAYERING Implement the security design principles of modularity and layering in [Assignment: organization-defined systems or system components]. Discussion:  The principles of modularity and layering are fundamental across system engineering disciplines. Modularity and layering derived from functional decomposition are effective in managing system complexity by making it possible to comprehend the structure of the system. Modular decomposition, or refinement in system design, is challenging and resists general statements of principle.', 'vec_doc-14-nist-sp-800-53-p285-1084', 0, 235, 'v2.1.0', '307a6f5e7c305d53eca03a062f8ce1bed58789fca001db90d2b4b15a2e358d00', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 258","subsection":"UNKNOWN","table_id":null,"page":285,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1084,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 258"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p285-1085', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 258', 285, 'Modularity serves to isolate functions and related data structures into well-defined logical units. Layering allows the relationships of these units to be better understood so that dependencies are clear and undesired complexity can be avoided. The security design principle of modularity extends functional modularity to include considerations based on trust, trustworthiness, privilege, and security policy. Security-informed modular decomposition includes the allocation of policies to systems in a network, separation of system applications into processes with distinct address spaces, allocation of system policies to layers, and separation of processes into subjects with distinct privileges based on hardware-supported privilege domains. Related Controls:  SC-2, SC-3. (4) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | PARTIALLY ORDERED DEPENDENCIES Implement the security design principle of partially ordered dependencies in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p285-1085', 0, 250, 'v2.1.0', 'a1d830ba1cbdc6ed6a3e62b66c005b8ea5ebf51185d9078fb4f1dec7c3b3fa91', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 258","subsection":"UNKNOWN","table_id":null,"page":285,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1085,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 258"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p285-1086', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 258', 285, 'Discussion:  The principle of partially ordered dependencies states that the synchronization, calling, and other dependencies in the system are partially ordered. A fundamental concept in system design is layering, whereby the system is organized into well-defined, functionally', 'vec_doc-14-nist-sp-800-53-p285-1086', 0, 70, 'v2.1.0', '53c9106acbc0fb237f3efdceda8308bcf9064305b815240bbf952dead6b99653', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 258","subsection":"UNKNOWN","table_id":null,"page":285,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1086,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 258"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p286-1087', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 259', 286, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 related modules or components. The layers are linearly ordered with respect to inter-layer dependencies, such that higher layers are dependent on lower layers. While providing functionality to higher layers, some layers can be self-contained and not dependent on lower layers. While a partial ordering of all functions in a given system may not be possible, if circular dependencies are constrained to occur within layers, the inherent problems of circularity can be more easily managed. Partially ordered dependencies and system layering contribute significantly to the simplicity and coherency of the system design. Partially ordered dependencies also facilitate system testing and analysis. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p286-1087', 0, 203, 'v2.1.0', 'da6021620b6bb0da8f09b2d98367f71f587c22519896cd186ce9c99bc030e47c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 259","subsection":"UNKNOWN","table_id":null,"page":286,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1087,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 259"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p286-1088', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 259', 286, '(5) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | EFFICIENTLY MEDIATED ACCESS Implement the security design principle of efficiently mediated access in [Assignment: organization-defined systems or system components]. Discussion:  The principle of efficiently mediated access states that policy enforcement mechanisms utilize the least common mechanism available while satisfying stakeholder requirements within expressed constraints. The mediation of access to system resources (i.e., CPU, memory, devices, communication ports, services, infrastructure, data, and information) is often the predominant security function of secure systems. It also enables the realization of protections for the capability provided to stakeholders by the system. Mediation of resource access can result in performance bottlenecks if the system is not designed correctly. For example, by using hardware mechanisms, efficiently mediated access can be achieved.', 'vec_doc-14-nist-sp-800-53-p286-1088', 0, 235, 'v2.1.0', 'fd57f0bc21d261d71fab985103f2e80df52c46b4926bef579a3f960e44cc0329', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 259","subsection":"UNKNOWN","table_id":null,"page":286,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1088,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 259"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p286-1089', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 259', 286, 'Once access to a low-level resource such as memory has been obtained, hardware protection mechanisms can ensure that out-of-bounds access does not occur. Related Controls:  AC-25. (6) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | MINIMIZED SHARING Implement the security design principle of minimized sharing in [Assignment: organization-defined systems or system components]. Discussion:  The principle of minimized sharing states that no computer resource is shared between system components (e.g., subjects, processes, functions) unless it is absolutely necessary to do so. Minimized sharing helps to simplify system design and implementation. In order to protect user-domain resources from arbitrary active entities, no resource is shared unless that sharing has been explicitly requested and granted. The need for resource sharing can be motivated by the design principle of least common mechanism in the case of internal entities or driven by stakeholder requirements.', 'vec_doc-14-nist-sp-800-53-p286-1089', 0, 244, 'v2.1.0', '374d3c12e9be2a727152daeca6b5b2c319822bb88c5966ff9ab03e8c50b12e40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 259","subsection":"UNKNOWN","table_id":null,"page":286,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1089,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 259"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p286-1090', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 259', 286, 'However, internal sharing is carefully designed to avoid performance and covert storage and timing channel problems. Sharing via common mechanism can increase the susceptibility of data and information to unauthorized access, disclosure, use, or modification and can adversely affect the inherent capability provided by the system. To minimize sharing induced by common mechanisms, such mechanisms can be designed to be reentrant or virtualized to preserve separation. Moreover, the use of global data to share information is carefully scrutinized. The lack of encapsulation may obfuscate relationships among the sharing entities. Related Controls:  SC-31. (7) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | REDUCED COMPLEXITY Implement the security design principle of reduced complexity in [Assignment: organization-defined systems or system components]. Discussion:  The principle of reduced complexity states that the system design is as simple and small as possible.', 'vec_doc-14-nist-sp-800-53-p286-1090', 0, 243, 'v2.1.0', 'f44ca4431f6c367baad2da36250c04bb71dc19def698b6d5ff6435a6fb3388f4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 259","subsection":"UNKNOWN","table_id":null,"page":286,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1090,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 259"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p286-1091', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 259', 286, 'A small and simple design is more understandable, more analyzable, and less prone to error. The reduced complexity principle applies to any aspect of a system, but it has particular importance for security due to the various analyses performed to obtain evidence about the emergent security property of the system. For such analyses to be', 'vec_doc-14-nist-sp-800-53-p286-1091', 0, 85, 'v2.1.0', '279be39e755ceb58f51b459b8e446e07db6ec0b9e0abee81eeb3fb7eb9a9d913', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 259","subsection":"UNKNOWN","table_id":null,"page":286,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1091,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 259"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p287-1092', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 260', 287, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 successful, a small and simple design is essential. Application of the principle of reduced complexity contributes to the ability of system developers to understand the correctness and completeness of system security functions. It also facilitates the identification of potential vulnerabilities. The corollary of reduced complexity states that the simplicity of the system is directly related to the number of vulnerabilities it will contain; that is, simpler systems contain fewer vulnerabilities. An benefit of reduced complexity is that it is easier to understand whether the intended security policy has been captured in the system design and that fewer vulnerabilities are likely to be introduced during engineering development.', 'vec_doc-14-nist-sp-800-53-p287-1092', 0, 207, 'v2.1.0', 'c47df0243c37c80b410458f5d1e6123777d8a64b237f5601e3f491e5cdf0c106', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 260","subsection":"UNKNOWN","table_id":null,"page":287,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1092,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 260"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p287-1093', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 260', 287, 'An additional benefit is that any such conclusion about correctness, completeness, and the existence of vulnerabilities can be reached with a higher degree of assurance in contrast to conclusions reached in situations where the system design is inherently more complex. Transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6) may require implementing the older and newer technologies simultaneously during the transition period. This may result in a temporary increase in system complexity during the transition. Related Controls:  None. (8) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SECURE EVOLVABILITY Implement the security design principle of secure evolvability in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p287-1093', 0, 196, 'v2.1.0', 'bd6de42876608a7ef24e78245c72e64e712ed8d72d897ed91301edaa3e22272a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 260","subsection":"UNKNOWN","table_id":null,"page":287,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1093,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 260"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p287-1094', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 260', 287, 'Discussion:  The principle of secure evolvability states that a system is developed to facilitate the maintenance of its security properties when there are changes to the system’s structure, interfaces, interconnections (i.e., system architecture), functionality, or configuration (i.e., security policy enforcement). Changes include a new, enhanced, or upgraded system capability; maintenance and sustainment activities; and reconfiguration. Although it is not possible to plan for every aspect of system evolution, system upgrades and changes can be anticipated by analyses of mission or business strategic direction, anticipated changes in the threat environment, and anticipated maintenance and sustainment needs. It is unrealistic to expect that complex systems remain secure in contexts not envisioned during development, whether such contexts are related to the operational environment or to usage.', 'vec_doc-14-nist-sp-800-53-p287-1094', 0, 227, 'v2.1.0', '3843506f682df188ab9c10fd8e156f06a7a6347904ab7ccbbc41de81c8fe3484', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 260","subsection":"UNKNOWN","table_id":null,"page":287,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1094,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 260"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p287-1095', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 260', 287, 'A system may be secure in some new contexts, but there is no guarantee that its emergent behavior will always be secure. It is easier to build trustworthiness into a system from the outset, and it follows that the sustainment of system trustworthiness requires planning for change as opposed to adapting in an ad hoc or non-methodical manner. The benefits of this principle include reduced vendor life cycle costs, reduced cost of ownership, improved system security, more effective management of security risk, and less risk uncertainty. Related Controls:  CM-3. (9) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | TRUSTED COMPONENTS Implement the security design principle of trusted components in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p287-1095', 0, 191, 'v2.1.0', '366b1443a1d19ec21a78c7d901e7f803fcee751d278b7816ab2ef5905cf2f285', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 260","subsection":"UNKNOWN","table_id":null,"page":287,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1095,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 260"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p287-1096', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 260', 287, 'Discussion:  The principle of trusted components states that a component is trustworthy to at least a level commensurate with the security dependencies it supports (i.e., how much it is trusted to perform its security functions by other components). This principle enables the composition of components such that trustworthiness is not inadvertently diminished and the trust is not consequently misplaced. Ultimately, this principle demands some metric by which the trust in a component and the trustworthiness of a component can be measured on the same abstract scale. The principle of trusted components is particularly relevant when considering systems and components in which there are complex chains of trust dependencies. A trust dependency is also referred to as a trust relationship and there may be chains of trust relationships.', 'vec_doc-14-nist-sp-800-53-p287-1096', 0, 210, 'v2.1.0', 'a911b1b1e7e9552b2981ecc87b882276c6c817a2000d466d3137877e43f8e6e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 260","subsection":"UNKNOWN","table_id":null,"page":287,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1096,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 260"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p288-1097', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 261', 288, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 The principle of trusted components also applies to a compound component that consists of subcomponents (e.g., a subsystem), which may have varying levels of trustworthiness. The conservative assumption is that the trustworthiness of a compound component is that of its least trustworthy subcomponent. It may be possible to provide a security engineering rationale that the trustworthiness of a particular compound component is greater than the conservative assumption. However, any such rationale reflects logical reasoning based on a clear statement of the trustworthiness objectives as well as relevant and credible evidence. The trustworthiness of a compound component is not the same as increased application of defense-in-depth layering within the component or a replication of components.', 'vec_doc-14-nist-sp-800-53-p288-1097', 0, 222, 'v2.1.0', 'fade6b266260776ec07dcc5953bc8f991070f31b73cdb26775f4dc620ccd84ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 261","subsection":"UNKNOWN","table_id":null,"page":288,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1097,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 261"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p288-1098', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 261', 288, 'Defense-in- depth techniques do not increase the trustworthiness of the whole above that of the least trustworthy component. Related Controls:  None. (10) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | HIERARCHICAL TRUST Implement the security design principle of hierarchical trust in [Assignment: organization- defined systems or system components]. Discussion:  The principle of hierarchical trust for components builds on the principle of trusted components and states that the security dependencies in a system will form a partial ordering if they preserve the principle of trusted components. The partial ordering provides the basis for trustworthiness reasoning or an assurance case (assurance argument) when composing a secure system from heterogeneously trustworthy components. To analyze a system composed of heterogeneously trustworthy components for its trustworthiness, it is essential to eliminate circular dependencies with regard to the trustworthiness.', 'vec_doc-14-nist-sp-800-53-p288-1098', 0, 242, 'v2.1.0', '2eeab5eacb3274a9749b82592d87bd42a6b56e44dae5ffb44014f2b2fc40cd1b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 261","subsection":"UNKNOWN","table_id":null,"page":288,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1098,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 261"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p288-1099', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 261', 288, 'If a more trustworthy component located in a lower layer of the system were to depend on a less trustworthy component in a higher layer, this would, in effect, put the components in the same “less trustworthy” equivalence class per the principle of trusted components. Trust relationships, or chains of trust, can have various manifestations. For example, the root certificate of a certificate hierarchy is the most trusted node in the hierarchy, whereas the leaves in the hierarchy may be the least trustworthy nodes. Another example occurs in a layered high-assurance system where the security kernel (including the hardware base), which is located at the lowest layer of the system, is the most trustworthy component. The principle of hierarchical trust, however, does not prohibit the use of overly trustworthy components.', 'vec_doc-14-nist-sp-800-53-p288-1099', 0, 207, 'v2.1.0', 'e7e59c46894ec96ae52d2330ccbf6a35d0ae755f3c6d1bc75bf732cd676839ee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 261","subsection":"UNKNOWN","table_id":null,"page":288,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1099,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 261"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p288-1100', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 261', 288, 'There may be cases in a system of low trustworthiness where it is reasonable to employ a highly trustworthy component rather than one that is less trustworthy (e.g., due to availability or other cost-benefit driver). For such a case, any dependency of the highly trustworthy component upon a less trustworthy component does not degrade the trustworthiness of the resulting low-trust system. Related Controls:  None. (11) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | INVERSE MODIFICATION THRESHOLD Implement the security design principle of inverse modification threshold in [Assignment: organization-defined systems or system components]. Discussion:  The principle of inverse modification threshold builds on the principle of trusted components and the principle of hierarchical trust and states that the degree of protection provided to a component is commensurate with its trustworthiness.', 'vec_doc-14-nist-sp-800-53-p288-1100', 0, 224, 'v2.1.0', '78cca4db13f1d492a1c941e8abb12b6d14d3549bdaaaff266f224373aaa62eec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 261","subsection":"UNKNOWN","table_id":null,"page":288,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1100,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 261"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p288-1101', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 261', 288, 'As the trust placed in a component increases, the protection against unauthorized modification of the component also increases to the same degree. Protection from unauthorized modification can come in the form of the component’s own self-protection and innate trustworthiness, or it can come from the protections afforded to the component from other elements or attributes of the security architecture (to include protections in the environment of operation). Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p288-1101', 0, 121, 'v2.1.0', 'fecbaaf123dc419e3410cc18a29b22e3feb72ef8bac02770e3902de0bb60ac14', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 261","subsection":"UNKNOWN","table_id":null,"page":288,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1101,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 261"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p289-1102', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 262', 289, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (12) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | HIERARCHICAL PROTECTION Implement the security design principle of hierarchical protection in [Assignment: organization-defined systems or system components]. Discussion:  The principle of hierarchical protection states that a component need not be protected from more trustworthy components. In the degenerate case of the most trusted component, it protects itself from all other components. For example, if an operating system kernel is deemed the most trustworthy component in a system, then it protects itself from all untrusted applications it supports, but the applications, conversely, do not need to protect themselves from the kernel. The trustworthiness of users is a consideration for applying the principle of hierarchical protection.', 'vec_doc-14-nist-sp-800-53-p289-1102', 0, 223, 'v2.1.0', 'fb70c51e91e5928a280725c7c872af93d752267c5532643fb8745e94f48c70eb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 262","subsection":"UNKNOWN","table_id":null,"page":289,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1102,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 262"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p289-1103', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 262', 289, 'A trusted system need not protect itself from an equally trustworthy user, reflecting use of untrusted systems in “system high” environments where users are highly trustworthy and where other protections are put in place to bound and protect the “system high” execution environment. Related Controls:  None. (13) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | MINIMIZED SECURITY ELEMENTS Implement the security design principle of minimized security elements in [Assignment: organization-defined systems or system components]. Discussion:  The principle of minimized security elements states that the system does not have extraneous trusted components. The principle of minimized security elements has two aspects: the overall cost of security analysis and the complexity of security analysis. Trusted components are generally costlier to construct and implement, owing to the increased rigor of development processes. Trusted components require greater security analysis to qualify their trustworthiness.', 'vec_doc-14-nist-sp-800-53-p289-1103', 0, 251, 'v2.1.0', '519673d02dc016c21b1501b395b529e87299229053ce258bb9424263e9525f1c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 262","subsection":"UNKNOWN","table_id":null,"page":289,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1103,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 262"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p289-1104', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 262', 289, 'Thus, to reduce the cost and decrease the complexity of the security analysis, a system contains as few trustworthy components as possible. The analysis of the interaction of trusted components with other components of the system is one of the most important aspects of system security verification. If the interactions between components are unnecessarily complex, the security of the system will also be more difficult to ascertain than one whose internal trust relationships are simple and elegantly constructed. In general, fewer trusted components result in fewer internal trust relationships and a simpler system. Related Controls:  None. (14) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | LEAST PRIVILEGE Implement the security design principle of least privilege in [Assignment: organization- defined systems or system components]. Discussion:  The principle of least privilege states that each system component is allocated sufficient privileges to accomplish its specified functions but no more.', 'vec_doc-14-nist-sp-800-53-p289-1104', 0, 252, 'v2.1.0', '1cf2859fc06a6603e171962cfbe3275e226fc62a5fbdb15e521d5e43e3af835a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 262","subsection":"UNKNOWN","table_id":null,"page":289,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1104,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 262"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p289-1105', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 262', 289, 'Applying the principle of least privilege limits the scope of the component’s actions, which has two desirable effects: the security impact of a failure, corruption, or misuse of the component will have a minimized security impact, and the security analysis of the component will be simplified. Least privilege is a pervasive principle that is reflected in all aspects of the secure system design. Interfaces used to invoke component capability are available to only certain subsets of the user population, and component design supports a sufficiently fine granularity of privilege decomposition. For example, in the case of an audit mechanism, there may be an interface for the audit manager, who configures the audit settings; an interface for the audit operator, who ensures that audit data is safely collected and stored; and, finally, yet another interface for the audit reviewer, who only has need to view the audit data that has been collected but no need to perform operations on that data.', 'vec_doc-14-nist-sp-800-53-p289-1105', 0, 250, 'v2.1.0', 'de42501c4705fbd858950dfc275afa5f00ad19858da1e81b5381de5da20c0bae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 262","subsection":"UNKNOWN","table_id":null,"page":289,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1105,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 262"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p289-1106', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 262', 289, 'In addition to its manifestations at the system interface, least privilege can be used as a guiding principle for the internal structure of the system itself. One aspect of internal least privilege is to construct modules so that only the elements encapsulated by the module are', 'vec_doc-14-nist-sp-800-53-p289-1106', 0, 70, 'v2.1.0', 'a9a8ce4b117e126952de7042a84c5aea318fdefad5772c0ea1d8b960d78fb2ad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 262","subsection":"UNKNOWN","table_id":null,"page":289,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1106,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 262"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p290-1107', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 263', 290, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 directly operated on by the functions within the module. Elements external to a module that may be affected by the module’s operation are indirectly accessed through interaction (e.g., via a function call) with the module that contains those elements. Another aspect of internal least privilege is that the scope of a given module or component includes only those system elements that are necessary for its functionality and that the access modes for the elements (e.g., read, write) are minimal. Related Controls:  AC-6, CM-7. (15) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | PREDICATE PERMISSION Implement the security design principle of predicate permission in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p290-1107', 0, 206, 'v2.1.0', '0be8b7e268d7a66069d783a2da4f236a1ab8699a9ea934987fef9036dc87fc02', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 263","subsection":"UNKNOWN","table_id":null,"page":290,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1107,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 263"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p290-1108', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 263', 290, 'Discussion:  The principle of predicate permission states that system designers consider requiring multiple authorized entities to provide consent before a highly critical operation or access to highly sensitive data, information, or resources is allowed to proceed. [ SALTZER75] originally named predicate permission the separation of privilege. It is also equivalent to separation of duty. The division of privilege among multiple parties decreases the likelihood of abuse and provides the safeguard that no single accident, deception, or breach of trust is sufficient to enable an unrecoverable action that can lead to significantly damaging effects.', 'vec_doc-14-nist-sp-800-53-p290-1108', 0, 164, 'v2.1.0', '01a368040e5a722d8c089c65a8ed9f636ae6cb03c5752eddc61a662799af08f3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 263","subsection":"UNKNOWN","table_id":null,"page":290,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1108,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 263"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p290-1109', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 263', 290, 'The design options for such a mechanism may require simultaneous action (e.g., the firing of a nuclear weapon requires two different authorized individuals to give the correct command within a small time window) or a sequence of operations where each successive action is enabled by some prior action, but no single individual is able to enable more than one action. Related Controls:  AC-5. (16) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SELF-RELIANT TRUSTWORTHINESS Implement the security design principle of self-reliant trustworthiness in [Assignment: organization-defined systems or system components]. Discussion:  The principle of self-reliant trustworthiness states that systems minimize their reliance on other systems for their own trustworthiness. A system is trustworthy by default, and any connection to an external entity is used to supplement its function.', 'vec_doc-14-nist-sp-800-53-p290-1109', 0, 219, 'v2.1.0', '52666fbc79141d227080f35cccefae62dddb5c6375f244e35d4c81b9551c3539', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 263","subsection":"UNKNOWN","table_id":null,"page":290,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1109,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 263"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p290-1110', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 263', 290, 'If a system were required to maintain a connection with another external entity in order to maintain its trustworthiness, then that system would be vulnerable to malicious and non-malicious threats that could result in the loss or degradation of that connection. The benefit of the principle of self-reliant trustworthiness is that the isolation of a system will make it less vulnerable to attack. A corollary to this principle relates to the ability of the system (or system component) to operate in isolation and then resynchronize with other components when it is rejoined with them. Related Controls:  None. (17) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SECURE DISTRIBUTED COMPOSITION Implement the security design principle of secure distributed composition in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p290-1110', 0, 209, 'v2.1.0', '0c021be818d37130b5091e60d68b4390b60a8821a76b86822328db18adea8acc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 263","subsection":"UNKNOWN","table_id":null,"page":290,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1110,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 263"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p290-1111', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 263', 290, 'Discussion:  The principle of secure distributed composition states that the composition of distributed components that enforce the same system security policy result in a system that enforces that policy at least as well as the individual components do. Many of the design principles for secure systems deal with how components can or should interact. The need to create or enable a capability from the composition of distributed components can magnify the relevancy of these principles. In particular, the translation of security policy from a stand-alone to a distributed system or a system-of-systems can have unexpected or emergent results. Communication protocols and distributed data consistency mechanisms help to ensure consistent policy enforcement across a distributed system. To ensure a', 'vec_doc-14-nist-sp-800-53-p290-1111', 0, 200, 'v2.1.0', '280711f51fadb58b112181c50e936de4f4ef5f67d28346209f8569756c6b7e9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 263","subsection":"UNKNOWN","table_id":null,"page":290,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1111,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 263"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p291-1112', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 264', 291, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 system-wide level of assurance of correct policy enforcement, the security architecture of a distributed composite system is thoroughly analyzed. Related Controls:  None. (18) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | TRUSTED COMMUNICATIONS CHANNELS Implement the security design principle of trusted communications channels in [Assignment: organization-defined systems or system components]. Discussion:  The principle of trusted communication channels states that when composing a system where there is a potential threat to communications between components (i.e., the interconnections between components), each communication channel is trustworthy to a level commensurate with the security dependencies it supports (i.e., how much it is trusted by other components to perform its security functions).', 'vec_doc-14-nist-sp-800-53-p291-1112', 0, 225, 'v2.1.0', '882155baf47bb0cb11af3aaeb29dc96e6cfdf5af24def67217ef9ba8db4e09fa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 264","subsection":"UNKNOWN","table_id":null,"page":291,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1112,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 264"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p291-1113', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 264', 291, 'Trusted communication channels are achieved by a combination of restricting access to the communication channel (to ensure an acceptable match in the trustworthiness of the endpoints involved in the communication) and employing end-to-end protections for the data transmitted over the communication channel (to protect against interception and modification and to further increase the assurance of proper end-to-end communication). Related Controls:  SC-8, SC-12, SC-13. (19) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | CONTINUOUS PROTECTION Implement the security design principle of continuous protection in [Assignment: organization-defined systems or system components]. Discussion:  The principle of continuous protection states that components and data used to enforce the security policy have uninterrupted protection that is consistent with the security policy and the security architecture assumptions.', 'vec_doc-14-nist-sp-800-53-p291-1113', 0, 229, 'v2.1.0', '6e90bec1eff1639f037c129747968667da997de8676a2a59806a508fcbaa193c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 264","subsection":"UNKNOWN","table_id":null,"page":291,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1113,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 264"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p291-1114', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 264', 291, 'No assurances that the system can provide the confidentiality, integrity, availability, and privacy protections for its design capability can be made if there are gaps in the protection. Any assurances about the ability to secure a delivered capability require that data and information are continuously protected. That is, there are no periods during which data and information are left unprotected while under control of the system (i.e., during the creation, storage, processing, or communication of the data and information, as well as during system initialization, execution, failure, interruption, and shutdown).', 'vec_doc-14-nist-sp-800-53-p291-1114', 0, 155, 'v2.1.0', '575d3b7352c377b783a298ece23213fe9531e6304b95b6696ab1ba222683e6ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 264","subsection":"UNKNOWN","table_id":null,"page":291,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1114,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 264"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p291-1115', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 264', 291, 'Continuous protection requires adherence to the precepts of the reference monitor concept (i.e., every request is validated by the reference monitor; the reference monitor is able to protect itself from tampering; and sufficient assurance of the correctness and completeness of the mechanism can be ascertained from analysis and testing) and the principle of secure failure and recovery (i.e., preservation of a secure state during error, fault, failure, and successful attack; preservation of a secure state during recovery to normal, degraded, or alternative operational modes). Continuous protection also applies to systems designed to operate in varying configurations, including those that deliver full operational capability and degraded-mode configurations that deliver partial operational capability.', 'vec_doc-14-nist-sp-800-53-p291-1115', 0, 202, 'v2.1.0', 'aebfd854898a0f6e28f52daa2319b5013a51f3925fde899a6865f6cecbf7c7f3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 264","subsection":"UNKNOWN","table_id":null,"page":291,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1115,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 264"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p291-1116', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 264', 291, 'The continuous protection principle requires that changes to the system security policies be traceable to the operational need that drives the configuration and be verifiable (i.e., it is possible to verify that the proposed changes will not put the system into an insecure state). Insufficient traceability and verification may lead to inconsistent states or protection discontinuities due to the complex or undecidable nature of the problem. The use of pre-verified configuration definitions that reflect the new security policy enables analysis to determine that a transition from old to new policies is essentially atomic and that any residual effects from the old policy are guaranteed to not conflict with the new policy. The ability to demonstrate continuous protection is rooted in the clear articulation of life cycle protection needs as stakeholder security requirements. Related Controls:  AC-25 .', 'vec_doc-14-nist-sp-800-53-p291-1116', 0, 227, 'v2.1.0', 'b3af62e93014669807c96a47468fb65296142a66364d557514f47c0aa5b5bc0e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 264","subsection":"UNKNOWN","table_id":null,"page":291,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1116,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 264"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p292-1117', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 265', 292, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (20) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SECURE METADATA MANAGEMENT Implement the security design principle of secure metadata management in [Assignment: organization-defined systems or system components]. Discussion:  The principle of secure metadata management states that metadata are “first class” objects with respect to security policy when the policy requires either complete protection of information or that the security subsystem be self-protecting. The principle of secure metadata management is driven by the recognition that a system, subsystem, or component cannot achieve self-protection unless it protects the data it relies on for correct execution. Data is generally not interpreted by the system that stores it. It may have semantic value (i.e., it comprises information) to users and programs that process the data.', 'vec_doc-14-nist-sp-800-53-p292-1117', 0, 235, 'v2.1.0', '6b068da5738a71d9132ed1e6246cf17aaaabf239afef4ac50b5d29ae330ae38c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 265","subsection":"UNKNOWN","table_id":null,"page":292,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1117,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 265"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p292-1118', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 265', 292, 'In contrast, metadata is information about data, such as a file name or the date when the file was created. Metadata is bound to the target data that it describes in a way that the system can interpret, but it need not be stored inside of or proximate to its target data. There may be metadata whose target is itself metadata (e.g., the classification level or impact level of a file name), including self-referential metadata. The apparent secondary nature of metadata can lead to neglect of its legitimate need for protection, resulting in a violation of the security policy that includes the exfiltration of information. A particular concern associated with insufficient protections for metadata is associated with multilevel secure (MLS) systems. MLS systems mediate access by a subject to an object based on relative sensitivity levels. It follows that all subjects and objects in the scope of control of the MLS system are either directly labeled or indirectly attributed with sensitivity levels.', 'vec_doc-14-nist-sp-800-53-p292-1118', 0, 251, 'v2.1.0', '6eef9e6b0a92e8409d25491352fafa5c42835008cc99101346faef8103194b08', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 265","subsection":"UNKNOWN","table_id":null,"page":292,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1118,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 265"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p292-1119', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 265', 292, 'The corollary of labeled metadata for MLS systems states that objects containing metadata are labeled. As with protection needs assessments for data, attention is given to ensure that the confidentiality and integrity protections are individually assessed, specified, and allocated to metadata, as would be done for mission, business, and system data. Related Controls:  None. (21) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SELF-ANALYSIS Implement the security design principle of self-analysis in [Assignment: organization- defined systems or system components]. Discussion:  The principle of self-analysis states that a system component is able to assess its internal state and functionality to a limited extent at various stages of execution, and that this self-analysis capability is commensurate with the level of trustworthiness invested in the system. At the system level, self-analysis can be achieved through hierarchical assessments of trustworthiness established in a bottom-up fashion.', 'vec_doc-14-nist-sp-800-53-p292-1119', 0, 251, 'v2.1.0', 'ae3e126f41fecd3ae2a99935d2917a05eabfe9c72896e260db69c152e7354ff6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 265","subsection":"UNKNOWN","table_id":null,"page":292,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1119,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 265"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p292-1120', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 265', 292, 'In this approach, the lower-level components check for data integrity and correct functionality (to a limited extent) of higher- level components. For example, trusted boot sequences involve a trusted lower-level component that attests to the trustworthiness of the next higher-level components so that a transitive chain of trust can be established. At the root, a component attests to itself, which usually involves an axiomatic or environmentally enforced assumption about its integrity. Results of the self-analyses can be used to guard against externally induced errors, internal malfunction, or transient errors. By following this principle, some simple malfunctions or errors can be detected without allowing the effects of the error or malfunction to propagate outside of the component. Further, the self-test can be used to attest to the configuration of the component, detecting any potential conflicts in configuration with respect to the expected configuration. Related Controls:  CA-7.', 'vec_doc-14-nist-sp-800-53-p292-1120', 0, 250, 'v2.1.0', '0cf90ff5ea87099cc161ba5198c62e98090bdac26f6ccca1f4ef7dce85ff9316', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 265","subsection":"UNKNOWN","table_id":null,"page":292,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1120,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 265"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p292-1121', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 265', 292, '(22) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | ACCOUNTABILITY AND TRACEABILITY', 'vec_doc-14-nist-sp-800-53-p292-1121', 0, 21, 'v2.1.0', 'bb1d08bba984b382b79c71337ef4fd2919712342edc6f2d1019bc2d5f7925b16', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 265","subsection":"UNKNOWN","table_id":null,"page":292,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1121,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 265"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p293-1122', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 266', 293, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Implement the security design principle of accountability and traceability in [Assignment: organization-defined systems or system components]. Discussion:  The principle of accountability and traceability states that it is possible to trace security-relevant actions (i.e., subject-object interactions) to the entity on whose behalf the action is being taken. The principle of accountability and traceability requires a trustworthy infrastructure that can record details about actions that affect system security (e.g., an audit subsystem). To record the details about actions, the system is able to uniquely identify the entity on whose behalf the action is being carried out and also record the relevant sequence of actions that are carried out. The accountability policy also requires that audit trail itself be protected from unauthorized access and modification.', 'vec_doc-14-nist-sp-800-53-p293-1122', 0, 240, 'v2.1.0', 'c1e67cb29870acfe12af75cb2523aac0ce26a3292d0fe6ac19ef36465fc18137', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 266","subsection":"UNKNOWN","table_id":null,"page":293,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1122,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 266"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p293-1123', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 266', 293, 'The principle of least privilege assists in tracing the actions to particular entities, as it increases the granularity of accountability. Associating specific actions with system entities, and ultimately with users, and making the audit trail secure against unauthorized access and modifications provide non-repudiation because once an action is recorded, it is not possible to change the audit trail. Another important function that accountability and traceability serves is in the routine and forensic analysis of events associated with the violation of security policy. Analysis of audit logs may provide additional information that may be helpful in determining the path or component that allowed the violation of the security policy and the actions of individuals associated with the violation of the security policy. Related Controls:  AC-6, AU-2, AU-3, AU-6, AU-9, AU-10, AU-12, IA-2, IR-4.', 'vec_doc-14-nist-sp-800-53-p293-1123', 0, 225, 'v2.1.0', '66b5f478b2071c26d98871dd41b83c8f1ce18d5a261d2e93d2607816e2c34810', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 266","subsection":"UNKNOWN","table_id":null,"page":293,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1123,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 266"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p293-1124', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 266', 293, '(23) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SECURE DEFAULTS Implement the security design principle of secure defaults in [Assignment: organization- defined systems or system components]. Discussion:  The principle of secure defaults states that the default configuration of a system (including its constituent subsystems, components, and mechanisms) reflects a restrictive and conservative enforcement of security policy. The principle of secure defaults applies to the initial (i.e., default) configuration of a system as well as to the security engineering and design of access control and other security functions that follow a “deny unless explicitly authorized” strategy.', 'vec_doc-14-nist-sp-800-53-p293-1124', 0, 171, 'v2.1.0', '09ba5a0437c2901f5256865e1ecacff532aee7f90983d257044724b501914db0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 266","subsection":"UNKNOWN","table_id":null,"page":293,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1124,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 266"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p293-1125', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 266', 293, 'The initial configuration aspect of this principle requires that any “as shipped” configuration of a system, subsystem, or system component does not aid in the violation of the security policy and can prevent the system from operating in the default configuration for those cases where the security policy itself requires configuration by the operational user. Restrictive defaults mean that the system will operate “as-shipped” with adequate self- protection and be able to prevent security breaches before the intended security policy and system configuration is established. In cases where the protection provided by the “as- shipped” product is inadequate, stakeholders assess the risk of using it prior to establishing a secure initial state. Adherence to the principle of secure defaults guarantees that a system is established in a secure state upon successfully completing initialization.', 'vec_doc-14-nist-sp-800-53-p293-1125', 0, 224, 'v2.1.0', 'd628a57d98288d07fca2c11889547fff7e79e24cd482331e66fe9fd5a0e719e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 266","subsection":"UNKNOWN","table_id":null,"page":293,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1125,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 266"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p293-1126', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 266', 293, 'In situations where the system fails to complete initialization, either it will perform a requested operation using secure defaults or it will not perform the operation. Refer to the principles of continuous protection and secure failure and recovery that parallel this principle to provide the ability to detect and recover from failure. The security engineering approach to this principle states that security mechanisms deny requests unless the request is found to be well-formed and consistent with the security policy. The insecure alternative is to allow a request unless it is shown to be inconsistent with the policy. In a large system, the conditions that are satisfied to grant a request that is denied by default are often far more compact and complete than those that would need to be checked in order to deny a request that is granted by default. Related Controls:  CM-2, CM-6, SA-4.', 'vec_doc-14-nist-sp-800-53-p293-1126', 0, 224, 'v2.1.0', '490b500cc94d4a899624d293ec6da149776c32e9bf0daa3b4fa98649c5c342ca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 266","subsection":"UNKNOWN","table_id":null,"page":293,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1126,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 266"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p294-1127', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 267', 294, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (24) SECURITY AND PRIVACY ENGINEERING PRINCIPLES |SECURE FAILURE AND RECOVERY Implement the security design principle of secure failure and recovery in [Assignment: organization-defined systems or system components]. Discussion:  The principle of secure failure and recovery states that neither a failure in a system function or mechanism nor any recovery action in response to failure leads to a violation of security policy. The principle of secure failure and recovery parallels the principle of continuous protection to ensure that a system is capable of detecting (within limits) actual and impending failure at any stage of its operation (i.e., initialization, normal operation, shutdown, and maintenance) and to take appropriate steps to ensure that security policies are not violated.', 'vec_doc-14-nist-sp-800-53-p294-1127', 0, 221, 'v2.1.0', '9bbbfce437aa48934d73dc8d70fd9f39ea3813d88509edb0ef4695203450cf53', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 267","subsection":"UNKNOWN","table_id":null,"page":294,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1127,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 267"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p294-1128', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 267', 294, 'In addition, when specified, the system is capable of recovering from impending or actual failure to resume normal, degraded, or alternative secure operations while ensuring that a secure state is maintained such that security policies are not violated. Failure is a condition in which the behavior of a component deviates from its specified or expected behavior for an explicitly documented input. Once a failed security function is detected, the system may reconfigure itself to circumvent the failed component while maintaining security and provide all or part of the functionality of the original system, or it may completely shut itself down to prevent any further violation of security policies. For this to occur, the reconfiguration functions of the system are designed to ensure continuous enforcement of security policy during the various phases of reconfiguration.', 'vec_doc-14-nist-sp-800-53-p294-1128', 0, 219, 'v2.1.0', 'a46c313b62a662cf92946bc44b699465ba7bcdb1efdec8c6ad5e701e036a8991', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 267","subsection":"UNKNOWN","table_id":null,"page":294,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1128,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 267"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p294-1129', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 267', 294, 'Another technique that can be used to recover from failures is to perform a rollback to a secure state (which may be the initial state) and then either shutdown or replace the service or component that failed such that secure operations may resume. Failure of a component may or may not be detectable to the components using it. The principle of secure failure indicates that components fail in a state that denies rather than grants access. For example, a nominally “atomic” operation interrupted before completion does not violate security policy and is designed to handle interruption events by employing higher-level atomicity and rollback mechanisms (e.g., transactions). If a service is being used, its atomicity properties are well-documented and characterized so that the component availing itself of that service can detect and handle interruption events appropriately.', 'vec_doc-14-nist-sp-800-53-p294-1129', 0, 220, 'v2.1.0', '568c2ab34d5ff05f5adc7575bf0f9554087428dbc24c81f30da3a8ec18a55874', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 267","subsection":"UNKNOWN","table_id":null,"page":294,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1129,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 267"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p294-1130', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 267', 294, 'For example, a system is designed to gracefully respond to disconnection and support resynchronization and data consistency after disconnection. Failure protection strategies that employ replication of policy enforcement mechanisms, sometimes called defense in depth, can allow the system to continue in a secure state even when one mechanism has failed to protect the system. If the mechanisms are similar, however, the additional protection may be illusory, as the adversary can simply attack in series. Similarly, in a networked system, breaking the security on one system or service may enable an attacker to do the same on other similar replicated systems and services. By employing multiple protection mechanisms whose features are significantly different, the possibility of attack replication or repetition can be reduced. Analyses are conducted to weigh the costs and benefits of such redundancy techniques against increased resource usage and adverse effects on the overall system performance.', 'vec_doc-14-nist-sp-800-53-p294-1130', 0, 251, 'v2.1.0', '038a79bdccda7f75ec2a92de38a6a4c66dbbb072ef1511ed2fb8890d6089bc81', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 267","subsection":"UNKNOWN","table_id":null,"page":294,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1130,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 267"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p294-1131', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 267', 294, 'Additional analyses are conducted as the complexity of these mechanisms increases, as could be the case for dynamic behaviors. Increased complexity generally reduces trustworthiness. When a resource cannot be continuously protected, it is critical to detect and repair any security breaches before the resource is once again used in a secure context. Related Controls:  CP-10, CP-12, SC-7, SC-8, SC-24, SI-13 . (25) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | ECONOMIC SECURITY Implement the security design principle of economic security in [Assignment: organization- defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p294-1131', 0, 153, 'v2.1.0', 'abb6618146fa18389b0732eff73596d0bb5cec0f0ad4ae2b1db2735bae2059fd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 267","subsection":"UNKNOWN","table_id":null,"page":294,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1131,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 267"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p295-1132', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 268', 295, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The principle of economic security states that security mechanisms are not costlier than the potential damage that could occur from a security breach. This is the security-relevant form of the cost-benefit analyses used in risk management. The cost assumptions of cost-benefit analysis prevent the system designer from incorporating security mechanisms of greater strength than necessary, where strength of mechanism is proportional to cost. The principle of economic security also requires analysis of the benefits of assurance relative to the cost of that assurance in terms of the effort expended to obtain relevant and credible evidence as well as the necessary analyses to assess and draw trustworthiness and risk conclusions from the evidence. Related Controls:  RA-3.', 'vec_doc-14-nist-sp-800-53-p295-1132', 0, 220, 'v2.1.0', '89279211b3d65583e5353de278ff41095d446070306abd123233aa09ae4d4897', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 268","subsection":"UNKNOWN","table_id":null,"page":295,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1132,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 268"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p295-1133', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 268', 295, '(26) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | PERFORMANCE SECURITY Implement the security design principle of performance security in [Assignment: organization-defined systems or system components]. Discussion:  The principle of performance security states that security mechanisms are constructed so that they do not degrade system performance unnecessarily. Stakeholder and system design requirements for performance and security are precisely articulated and prioritized. For the system implementation to meet its design requirements and be found acceptable to stakeholders (i.e., validation against stakeholder requirements), the designers adhere to the specified constraints that capability performance needs place on protection needs.', 'vec_doc-14-nist-sp-800-53-p295-1133', 0, 187, 'v2.1.0', '312db63fac79b84274d2fc3b0d60a9b434e75ca548008d3d48e1d4dd4c334244', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 268","subsection":"UNKNOWN","table_id":null,"page":295,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1133,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 268"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p295-1134', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 268', 295, 'The overall impact of computationally intensive security services (e.g., cryptography) are assessed and demonstrated to pose no significant impact to higher-priority performance considerations or are deemed to provide an acceptable trade-off of performance for trustworthy protection. The trade-off considerations include less computationally intensive security services unless they are unavailable or insufficient. The insufficiency of a security service is determined by functional capability and strength of mechanism. The strength of mechanism is selected with respect to security requirements, performance-critical overhead issues (e.g., cryptographic key management), and an assessment of the capability of the threat. The principle of performance security leads to the incorporation of features that help in the enforcement of security policy but incur minimum overhead, such as low-level hardware mechanisms upon which higher-level services can be built.', 'vec_doc-14-nist-sp-800-53-p295-1134', 0, 241, 'v2.1.0', '66524a25f5afb6f4531c7c8b29c868846042afcf620846ca0c28e279ebaadfe5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 268","subsection":"UNKNOWN","table_id":null,"page":295,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1134,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 268"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p295-1135', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 268', 295, 'Such low-level mechanisms are usually very specific, have very limited functionality, and are optimized for performance. For example, once access rights to a portion of memory is granted, many systems use hardware mechanisms to ensure that all further accesses involve the correct memory address and access mode. Application of this principle reinforces the need to design security into the system from the ground up and to incorporate simple mechanisms at the lower layers that can be used as building blocks for higher-level mechanisms. Related Controls:  SC-12, SC-13, SI-2, SI-7 . (27) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | HUMAN FACTORED SECURITY Implement the security design principle of human factored security in [Assignment: organization-defined systems or system components].', 'vec_doc-14-nist-sp-800-53-p295-1135', 0, 199, 'v2.1.0', '5cf3718018af0ac26d8d82755fb0d7ed2bce8d17307fc610d58689a970c6a05a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 268","subsection":"UNKNOWN","table_id":null,"page":295,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1135,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 268"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p295-1136', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 268', 295, 'Discussion:  The principle of human factored security states that the user interface for security functions and supporting services is intuitive, user-friendly, and provides feedback for user actions that affect such policy and its enforcement. The mechanisms that enforce security policy are not intrusive to the user and are designed not to degrade user efficiency. Security policy enforcement mechanisms also provide the user with meaningful, clear, and relevant feedback and warnings when insecure choices are being made. Particular attention is given to interfaces through which personnel responsible for system administration and operation configure and set up the security policies. Ideally, these personnel are able to', 'vec_doc-14-nist-sp-800-53-p295-1136', 0, 182, 'v2.1.0', 'ae0daa3f7a401f7dd3f25550784afbb27bd9da375948aa837790726d56b9d915', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 268","subsection":"UNKNOWN","table_id":null,"page":295,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1136,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 268"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p296-1137', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 269', 296, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 understand the impact of their choices. Personnel with system administrative and operational responsibilities are able to configure systems before start-up and administer them during runtime with confidence that their intent is correctly mapped to the system’s mechanisms. Security services, functions, and mechanisms do not impede or unnecessarily complicate the intended use of the system. There is a trade-off between system usability and the strictness necessary for security policy enforcement. If security mechanisms are frustrating or difficult to use, then users may disable them, avoid them, or use them in ways inconsistent with the security requirements and protection needs that the mechanisms were designed to satisfy. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p296-1137', 0, 212, 'v2.1.0', '345ae24551d35aa5af50a58a0dcfab7b986b28dc5413da9bcfb09f23e188d8e4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 269","subsection":"UNKNOWN","table_id":null,"page":296,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1137,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 269"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p296-1138', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 269', 296, '(28) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | ACCEPTABLE SECURITY Implement the security design principle of acceptable security in [Assignment: organization-defined systems or system components]. Discussion:  The principle of acceptable security requires that the level of privacy and performance that the system provides is consistent with the users’ expectations. The perception of personal privacy may affect user behavior, morale, and effectiveness. Based on the organizational privacy policy and the system design, users should be able to restrict their actions to protect their privacy. When systems fail to provide intuitive interfaces or meet privacy and performance expectations, users may either choose to completely avoid the system or use it in ways that may be inefficient or even insecure. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p296-1138', 0, 209, 'v2.1.0', '314979fbdbcbb107b96a921f35a822dbacf3f39bd5b5758f07aa0ab31b049a5d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 269","subsection":"UNKNOWN","table_id":null,"page":296,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1138,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 269"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p296-1139', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 269', 296, '(29) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | REPEATABLE AND DOCUMENTED PROCEDURES Implement the security design principle of repeatable and documented procedures in [Assignment: organization-defined systems or system components]. Discussion:  The principle of repeatable and documented procedures states that the techniques and methods employed to construct a system component permit the same component to be completely and correctly reconstructed at a later time. Repeatable and documented procedures support the development of a component that is identical to the component created earlier, which may be in widespread use. In the case of other system artifacts (e.g., documentation and testing results), repeatability supports consistency and the ability to inspect the artifacts. Repeatable and documented procedures can be introduced at various stages within the system development life cycle and contribute to the ability to evaluate assurance claims for the system.', 'vec_doc-14-nist-sp-800-53-p296-1139', 0, 245, 'v2.1.0', 'a4743660c27077b718cb4aed3320a72ccd80ff47848305712adf5a19ccf267f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 269","subsection":"UNKNOWN","table_id":null,"page":296,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1139,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 269"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p296-1140', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 269', 296, 'Examples include systematic procedures for code development and review, procedures for the configuration management of development tools and system artifacts, and procedures for system delivery. Related Controls:  CM-1, SA-1, SA-10, SA-11, SA-15, SA-17, SC-1, SI-1. (30) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | PROCEDURAL RIGOR Implement the security design principle of procedural rigor in [Assignment: organization- defined systems or system components]. Discussion:  The principle of procedural rigor states that the rigor of a system life cycle process is commensurate with its intended trustworthiness. Procedural rigor defines the scope, depth, and detail of the system life cycle procedures. Rigorous system life cycle procedures contribute to the assurance that the system is correct and free of unintended functionality in several ways. First, the procedures impose checks and balances on the life cycle process such that the introduction of unspecified functionality is prevented.', 'vec_doc-14-nist-sp-800-53-p296-1140', 0, 249, 'v2.1.0', 'daa0e5c39f77d8e50ed7fc943aabf5201972e816b266bf4cdb45f6f0f105e73f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 269","subsection":"UNKNOWN","table_id":null,"page":296,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1140,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 269"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p296-1141', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 269', 296, 'Second, rigorous procedures applied to systems security engineering activities that produce specifications and other system design documents contribute to the ability to understand', 'vec_doc-14-nist-sp-800-53-p296-1141', 0, 45, 'v2.1.0', 'ef2a59666685d693e92e20d623bd22ca9e5a94dcda3e6b8f2a76b6cfc2eafb53', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 269","subsection":"UNKNOWN","table_id":null,"page":296,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1141,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 269"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p297-1142', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 270', 297, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 the system as it has been built rather than trusting that the component, as implemented, is the authoritative (and potentially misleading) specification. Finally, modifications to an existing system component are easier when there are detailed specifications that describe its current design instead of studying source code or schematics to try to understand how it works. Procedural rigor helps ensure that security functional and assurance requirements have been satisfied, and it contributes to a better-informed basis for the determination of trustworthiness and risk posture. Procedural rigor is commensurate with the degree of assurance desired for the system. If the required trustworthiness of the system is low, a high level of procedural rigor may add unnecessary cost, whereas when high trustworthiness is critical, the cost of high procedural rigor is merited. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p297-1142', 0, 248, 'v2.1.0', 'f15203b7884a26037e9e9c9caafbd86b16075867e8684fd4d488c1c835f47a84', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 270","subsection":"UNKNOWN","table_id":null,"page":297,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1142,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 270"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p297-1143', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 270', 297, '(31) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SECURE SYSTEM MODIFICATION Implement the security design principle of secure system modification in [Assignment: organization-defined systems or system components]. Discussion:  The principle of secure system modification states that system modification maintains system security with respect to the security requirements and risk tolerance of stakeholders. Upgrades or modifications to systems can transform secure systems into systems that are not secure. The procedures for system modification ensure that if the system is to maintain its trustworthiness, the same rigor that was applied to its initial development is applied to any system changes. Because modifications can affect the ability of the system to maintain its secure state, a careful security analysis of the modification is needed prior to its implementation and deployment. This principle parallels the principle of secure evolvability. Related Controls:  CM-3, CM-4.', 'vec_doc-14-nist-sp-800-53-p297-1143', 0, 247, 'v2.1.0', 'ee9bd2647c37d5862cf190090563cbd2ad2be428e8824aa8f62ffe52be2a1862', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 270","subsection":"UNKNOWN","table_id":null,"page":297,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1143,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 270"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p297-1144', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 270', 297, '(32) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | SUFFICIENT DOCUMENTATION Implement the security design principle of sufficient documentation in [Assignment: organization-defined systems or system components]. Discussion:  The principle of sufficient documentation states that organizational personnel with responsibilities to interact with the system are provided with adequate documentation and other information such that the personnel contribute to rather than detract from system security. Despite attempts to comply with principles such as human factored security and acceptable security, systems are inherently complex, and the design intent for the use of security mechanisms and the ramifications of the misuse or misconfiguration of security mechanisms are not always intuitively obvious. Uninformed and insufficiently trained users can introduce vulnerabilities due to errors of omission and commission.', 'vec_doc-14-nist-sp-800-53-p297-1144', 0, 229, 'v2.1.0', '05e7692c0c89614cbf50a0db9aaef96fd958e663a0726cc23e36451401a16289', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 270","subsection":"UNKNOWN","table_id":null,"page":297,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1144,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 270"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p297-1145', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 270', 297, 'The availability of documentation and training can help to ensure a knowledgeable cadre of personnel, all of whom have a critical role in the achievement of principles such as continuous protection. Documentation is written clearly and supported by training that provides security awareness and understanding of security-relevant responsibilities. Related Controls:  AT-2, AT-3, SA-5. (33) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | MINIMIZATION Implement the privacy principle of minimization using [Assignment: organization-defined processes]. Discussion: The principle of minimization states that organizations should only process personally identifiable information that is directly relevant and necessary to accomplish an authorized purpose and should only maintain personally identifiable information for as long as is necessary to accomplish the purpose. Organizations have processes in place, consistent with applicable laws and policies, to implement the principle of minimization.', 'vec_doc-14-nist-sp-800-53-p297-1145', 0, 249, 'v2.1.0', 'c50bf6c95ad9585994285e3712da5e6542ff205bcfc2c5670fcdd17773de9ad5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 270","subsection":"UNKNOWN","table_id":null,"page":297,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1145,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 270"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p298-1146', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 271', 298, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  PE-8, PM-25, SC-42, SI-12. References:  [PRIVACT], [OMB A-130], [FIPS 199], [FIPS 200], [SP 800-37], [SP 800-53A], [SP 800- 60-1], [SP 800-60-2], [SP 800-160-1], [IR 8062]. SA-9 EXTERNAL SYSTEM SERVICES Control: a. Require that providers of external system services comply with organizational security and privacy requirements and employ the following controls: [Assignment: organization-defined controls]; b. Define and document organizational oversight and user roles and responsibilities with regard to external system services; and c. Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis: [Assignment: organization-defined processes, methods, and techniques].', 'vec_doc-14-nist-sp-800-53-p298-1146', 0, 215, 'v2.1.0', 'd65c8df3f8877a1052909eb108f4a43bc2da50da9101d8dd2e623bd25a4d204b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 271","subsection":"UNKNOWN","table_id":null,"page":298,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1146,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 271"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p298-1147', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 271', 298, 'Discussion:  External system services are provided by an external provider, and the organization has no direct control over the implementation of the required controls or the assessment of control effectiveness. Organizations establish relationships with external service providers in a variety of ways, including through business partnerships, contracts, interagency agreements, lines of business arrangements, licensing agreements, joint ventures, and supply chain exchanges. The responsibility for managing risks from the use of external system services remains with authorizing officials. For services external to organizations, a chain of trust requires that organizations establish and retain a certain level of confidence that each provider in the consumer-provider relationship provides adequate protection for the services rendered. The extent and nature of this chain of trust vary based on relationships between organizations and the external providers.', 'vec_doc-14-nist-sp-800-53-p298-1147', 0, 241, 'v2.1.0', 'fea2031ccc501e9370c01bcc53e238f2d00643568522101fb86b21b1a4d4b7f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 271","subsection":"UNKNOWN","table_id":null,"page":298,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1147,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 271"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p298-1148', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 271', 298, 'Organizations document the basis for the trust relationships so that the relationships can be monitored. External system services documentation includes government, service providers, end user security roles and responsibilities, and service-level agreements. Service-level agreements define the expectations of performance for implemented controls, describe measurable outcomes, and identify remedies and response requirements for identified instances of noncompliance. Related Controls:  AC-20, CA-3, CP-2, IR-4, IR-7, PL-10, PL-11, PS-7, SA-2, SA-4, SR-3, SR-5. Control Enhancements: (1) EXTERNAL SYSTEM SERVICES | RISK ASSESSMENTS AND ORGANIZATIONAL APPROVALS (a) Conduct an organizational assessment of risk prior to the acquisition or outsourcing of information security services; and (b) Verify that the acquisition or outsourcing of dedicated information security services is approved by [Assignment: organization-defined personnel or roles].', 'vec_doc-14-nist-sp-800-53-p298-1148', 0, 238, 'v2.1.0', 'fdf8a56700c57740a7134d49405499741fb64af864ef1fb9a2fb03299c18161e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 271","subsection":"UNKNOWN","table_id":null,"page":298,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1148,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 271"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p298-1149', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 271', 298, 'Discussion:  Information security services include the operation of security devices, such as firewalls or key management services as well as incident monitoring, analysis, and response. Risks assessed can include system, mission or business, security, privacy, or supply chain risks. Related Controls:  CA-6, RA-3, RA-8. (2) EXTERNAL SYSTEM SERVICES | IDENTIFICATION OF FUNCTIONS, PORTS, PROTOCOLS, AND SERVICES Require providers of the following external system services to identify the functions, ports, protocols, and other services required for the use of such services: [Assignment: organization-defined external system services].', 'vec_doc-14-nist-sp-800-53-p298-1149', 0, 159, 'v2.1.0', 'e999f2568f3f0a892f8dfcfd65a4a652c7fa119143bdab2b7861254cf79ce8f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 271","subsection":"UNKNOWN","table_id":null,"page":298,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1149,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 271"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p299-1150', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 272', 299, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Information from external service providers regarding the specific functions, ports, protocols, and services used in the provision of such services can be useful when the need arises to understand the trade-offs involved in restricting certain functions and services or blocking certain ports and protocols. Related Controls:  CM-6, CM-7. (3) EXTERNAL SYSTEM SERVICES | ESTABLISH AND MAINTAIN TRUST RELATIONSHIP WITH PROVIDERS Establish, document, and maintain trust relationships with external service providers based on the following requirements, properties, factors, or conditions: [Assignment: organization-defined security and privacy requirements, properties, factors, or conditions defining acceptable trust relationships].', 'vec_doc-14-nist-sp-800-53-p299-1150', 0, 209, 'v2.1.0', '45f8dd7cadcebe236fb597587fc569124dee25eccd900611cca2abf2b2e5125d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 272","subsection":"UNKNOWN","table_id":null,"page":299,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1150,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 272"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p299-1151', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 272', 299, 'Discussion:  Trust relationships between organizations and external service providers reflect the degree of confidence that the risk from using external services is at an acceptable level. Trust relationships can help organizations gain increased levels of confidence that service providers are providing adequate protection for the services rendered and can also be useful when conducting incident response or when planning for upgrades or obsolescence. Trust relationships can be complicated due to the potentially large number of entities participating in the consumer-provider interactions, subordinate relationships and levels of trust, and types of interactions between the parties. In some cases, the degree of trust is based on the level of control that organizations can exert on external service providers regarding the controls necessary for the protection of the service, information, or individual privacy and the evidence brought forth as to the effectiveness of the implemented controls.', 'vec_doc-14-nist-sp-800-53-p299-1151', 0, 251, 'v2.1.0', '1c6abfd00fce1332c88f47237e28f0ff30a1b4ba3df919ddcf21c9b294827ee8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 272","subsection":"UNKNOWN","table_id":null,"page":299,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1151,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 272"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p299-1152', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 272', 299, 'The level of control is established by the terms and conditions of the contracts or service-level agreements. Related Controls:  SR-2. (4) EXTERNAL SYSTEM SERVICES |CONSISTENT INTERESTS OF CONSUMERS AND PROVIDERS Take the following actions to verify that the interests of [Assignment: organization- defined external service providers] are consistent with and reflect organizational interests: [Assignment: organization-defined actions]. Discussion:  As organizations increasingly use external service providers, it is possible that the interests of the service providers may diverge from organizational interests. In such situations, simply having the required technical, management, or operational controls in place may not be sufficient if the providers that implement and manage those controls are not operating in a manner consistent with the interests of the consuming organizations.', 'vec_doc-14-nist-sp-800-53-p299-1152', 0, 222, 'v2.1.0', '49c39d72c84f607f97d1e4c04bb83fec249a0662d2288b720a5a5d6a03890fac', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 272","subsection":"UNKNOWN","table_id":null,"page":299,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1152,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 272"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p299-1153', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 272', 299, 'Actions that organizations take to address such concerns include requiring background checks for selected service provider personnel; examining ownership records; employing only trustworthy service providers, such as providers with which organizations have had successful trust relationships; and conducting routine, periodic, unscheduled visits to service provider facilities. Related Controls:  None. (5) EXTERNAL SYSTEM SERVICES | PROCESSING, STORAGE, AND SERVICE LOCATION Restrict the location of [Selection (one or more): information processing; information or data; system services] to [Assignment: organization-defined locations] based on [Assignment: organization-defined requirements or conditions]. Discussion:  The location of information processing, information and data storage, or system services can have a direct impact on the ability of organizations to successfully execute their mission and business functions.', 'vec_doc-14-nist-sp-800-53-p299-1153', 0, 233, 'v2.1.0', '34038699e3701e7dd112fefd9833821aeb6711055dbc7cc613840247fe6df3dd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 272","subsection":"UNKNOWN","table_id":null,"page":299,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1153,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 272"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p299-1154', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 272', 299, 'The impact occurs when external providers control the location of processing, storage, or services. The criteria that external providers use for the selection of processing, storage, or service locations may be different from the criteria that organizations use. For example, organizations may desire that data or information storage', 'vec_doc-14-nist-sp-800-53-p299-1154', 0, 84, 'v2.1.0', 'f98bb4e1c0443cd57ead4946f81073b7e4d1b299b6542d22119710321101b780', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 272","subsection":"UNKNOWN","table_id":null,"page":299,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1154,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 272"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p300-1155', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 273', 300, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 locations be restricted to certain locations to help facilitate incident response activities in case of information security incidents or breaches. Incident response activities, including forensic analyses and after-the-fact investigations, may be adversely affected by the governing laws, policies, or protocols in the locations where processing and storage occur and/or the locations from which system services emanate. Related Controls:  SA-5, SR-4. (6) EXTERNAL SYSTEM SERVICES | ORGANIZATION-CONTROLLED CRYPTOGRAPHIC KEYS Maintain exclusive control of cryptographic keys for encrypted material stored or transmitted through an external system. Discussion:  Maintaining exclusive control of cryptographic keys in an external system prevents decryption of organizational data by external system staff.', 'vec_doc-14-nist-sp-800-53-p300-1155', 0, 224, 'v2.1.0', '1273ee5b2b37854e55c079a37664e11d3fad1981d79c97e365565ed2f996db39', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 273","subsection":"UNKNOWN","table_id":null,"page":300,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1155,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 273"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p300-1156', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 273', 300, 'Organizational control of cryptographic keys can be implemented by encrypting and decrypting data inside the organization as data is sent to and received from the external system or by employing a component that permits encryption and decryption functions to be local to the external system but allows exclusive organizational access to the encryption keys. Related Controls:  SC-12, SC-13, SI-4. (7) EXTERNAL SYSTEM SERVICES | ORGANIZATION-CONTROLLED INTEGRITY CHECKING Provide the capability to check the integrity of information while it resides in the external system. Discussion:  Storage of organizational information in an external system could limit visibility into the security status of its data. The ability of the organization to verify and validate the integrity of its stored data without transferring it out of the external system provides such visibility. Related Controls:  SI-7. (8) EXTERNAL SYSTEM SERVICES | PROCESSING AND STORAGE LOCATION —  U.S.', 'vec_doc-14-nist-sp-800-53-p300-1156', 0, 242, 'v2.1.0', 'fa3a4dbbe9a711efaaee4f5d400fdb9a3b59a6676ad3d76c8f7920adde5867f6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 273","subsection":"UNKNOWN","table_id":null,"page":300,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1156,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 273"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p300-1157', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 273', 300, 'JURISDICTION Restrict the geographic location of information processing and data storage to facilities located within in the legal jurisdictional boundary of the United States. Discussion:  The geographic location of information processing and data storage can have a direct impact on the ability of organizations to successfully execute their mission and business functions. A compromise or breach of high impact information and systems can have severe or catastrophic adverse impacts on organizational assets and operations, individuals, other organizations, and the Nation. Restricting the processing and storage of high-impact information to facilities within the legal jurisdictional boundary of the United States provides greater control over such processing and storage. Related Controls:  SA-5, SR-4. References:  [OMB A-130], [SP 800-35], [SP 800-160-1], [SP 800-161], [SP 800-171].', 'vec_doc-14-nist-sp-800-53-p300-1157', 0, 223, 'v2.1.0', '734362a143cc545ff0634310a5fe2a2ca5ca1e871ef08d79a732444938a088e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 273","subsection":"UNKNOWN","table_id":null,"page":300,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1157,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 273"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p300-1158', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 273', 300, 'SA-10 DEVELOPER CONFIGURATION MANAGEMENT Control:  Require the developer of the system, system component, or system service to: a. Perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal]; b. Document, manage, and control the integrity of changes to [Assignment: organization- defined configuration items under configuration management]; c. Implement only organization-approved changes to the system, component, or service;', 'vec_doc-14-nist-sp-800-53-p300-1158', 0, 130, 'v2.1.0', 'e36591c737900707209af1fd9675365edb6aa7cda43f63bb2691aa6951b30f22', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 273","subsection":"UNKNOWN","table_id":null,"page":300,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1158,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 273"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p301-1159', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 274', 301, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 d. Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service and report findings to [Assignment: organization-defined personnel]. Discussion:  Organizations consider the quality and completeness of configuration management activities conducted by developers as direct evidence of applying effective security controls. Controls include protecting the master copies of material used to generate security-relevant portions of the system hardware, software, and firmware from unauthorized modification or destruction. Maintaining the integrity of changes to the system, system component, or system service requires strict configuration control throughout the system development life cycle to track authorized changes and prevent unauthorized changes.', 'vec_doc-14-nist-sp-800-53-p301-1159', 0, 249, 'v2.1.0', '3db6e8f54c82eef80386f3c4d6ac5be21aef28c305d5935efabf1316a0a5cdd8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 274","subsection":"UNKNOWN","table_id":null,"page":301,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1159,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 274"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p301-1160', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 274', 301, 'The configuration items that are placed under configuration management include the formal model; the functional, high-level, and low-level design specifications; other design data; implementation documentation; source code and hardware schematics; the current running version of the object code; tools for comparing new versions of security-relevant hardware descriptions and source code with previous versions; and test fixtures and documentation. Depending on the mission and business needs of organizations and the nature of the contractual relationships in place, developers may provide configuration management support during the operations and maintenance stage of the system development life cycle. Related Controls:  CM-2, CM-3, CM-4, CM-7, CM-9, SA-4, SA-5, SA-8, SA-15, SI-2, SR-3, SR-4, SR-5, SR-6.', 'vec_doc-14-nist-sp-800-53-p301-1160', 0, 203, 'v2.1.0', '97cee6a25255798426bdfac709a4ba046e1758fd931696cd26e7fc290ac1d81e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 274","subsection":"UNKNOWN","table_id":null,"page":301,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1160,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 274"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p301-1161', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 274', 301, 'Control Enhancements: (1) DEVELOPER CONFIGURATION MANAGEMENT | SOFTWARE AND FIRMWARE INTEGRITY VERIFICATION Require the developer of the system, system component, or system service to enable integrity verification of software and firmware components. Discussion:  Software and firmware integrity verification allows organizations to detect unauthorized changes to software and firmware components using developer-provided tools, techniques, and mechanisms. The integrity checking mechanisms can also address counterfeiting of software and firmware components. Organizations verify the integrity of software and firmware components, for example, through secure one-way hashes provided by developers. Delivered software and firmware components also include any updates to such components. Related Controls:  SI-7, SR-11.', 'vec_doc-14-nist-sp-800-53-p301-1161', 0, 205, 'v2.1.0', '1779179e6b4521c45573e4ca9e696dd088ca7fcb5dec0c7773bedd9f8e5f69fd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 274","subsection":"UNKNOWN","table_id":null,"page":301,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1161,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 274"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p301-1162', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 274', 301, '(2) DEVELOPER CONFIGURATION MANAGEMENT | ALTERNATIVE CONFIGURATION MANAGEMENT PROCESSES Provide an alternate configuration management process using organizational personnel in the absence of a dedicated developer configuration management team. Discussion:  Alternate configuration management processes may be required when organizations use commercial off-the-shelf information technology products. Alternate configuration management processes include organizational personnel who review and approve proposed changes to systems, system components, and system services and conduct security and privacy impact analyses prior to the implementation of changes to systems, components, or services. Related Controls:  None. (3) DEVELOPER CONFIGURATION MANAGEMENT | HARDWARE INTEGRITY VERIFICATION Require the developer of the system, system component, or system service to enable integrity verification of hardware components.', 'vec_doc-14-nist-sp-800-53-p301-1162', 0, 230, 'v2.1.0', 'e5592c9f8b341da21a39fd38ad820429098faa32fc639b49534cb6501eafa7ad', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 274","subsection":"UNKNOWN","table_id":null,"page":301,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1162,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 274"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p302-1163', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 275', 302, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Hardware integrity verification allows organizations to detect unauthorized changes to hardware components using developer-provided tools, techniques, methods, and mechanisms. Organizations may verify the integrity of hardware components with hard-to- copy labels, verifiable serial numbers provided by developers, and by requiring the use of anti-tamper technologies. Delivered hardware components also include hardware and firmware updates to such components. Related Controls:  SI-7. (4) DEVELOPER CONFIGURATION MANAGEMENT | TRUSTED GENERATION Require the developer of the system, system component, or system service to employ tools for comparing newly generated versions of security-relevant hardware descriptions, source code, and object code with previous versions.', 'vec_doc-14-nist-sp-800-53-p302-1163', 0, 219, 'v2.1.0', '977b987c42e334e2d4922146c7715d5c77103272820a915b61a0b7ab0628abec', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 275","subsection":"UNKNOWN","table_id":null,"page":302,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1163,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 275"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p302-1164', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 275', 302, 'Discussion:  The trusted generation of descriptions, source code, and object code addresses authorized changes to hardware, software, and firmware components between versions during development. The focus is on the efficacy of the configuration management process by the developer to ensure that newly generated versions of security-relevant hardware descriptions, source code, and object code continue to enforce the security policy for the system, system component, or system service. In contrast, SA-10(1) and SA-10(3) allow organizations to detect unauthorized changes to hardware, software, and firmware components using tools, techniques, or mechanisms provided by developers. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p302-1164', 0, 177, 'v2.1.0', '60c76b42523a6e7dc71d08c84ea787129649296ef568a8074dfc3dd8b0be8808', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 275","subsection":"UNKNOWN","table_id":null,"page":302,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1164,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 275"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p302-1165', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 275', 302, '(5) DEVELOPER CONFIGURATION MANAGEMENT | MAPPING INTEGRITY FOR VERSION CONTROL Require the developer of the system, system component, or system service to maintain the integrity of the mapping between the master build data describing the current version of security-relevant hardware, software, and firmware and the on-site master copy of the data for the current version. Discussion:  Mapping integrity for version control addresses changes to hardware, software, and firmware components during both initial development and system development life cycle updates. Maintaining the integrity between the master copies of security-relevant hardware, software, and firmware (including designs, hardware drawings, source code) and the equivalent data in master copies in operational environments is essential to ensuring the availability of organizational systems that support critical mission and business functions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p302-1165', 0, 235, 'v2.1.0', '001b3ab2392dc7b1ec2a2179eb94ae9fa0bc0a0edc85f52bf9679effc798e795', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 275","subsection":"UNKNOWN","table_id":null,"page":302,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1165,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 275"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p302-1166', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 275', 302, '(6) DEVELOPER CONFIGURATION MANAGEMENT | TRUSTED DISTRIBUTION Require the developer of the system, system component, or system service to execute procedures for ensuring that security-relevant hardware, software, and firmware updates distributed to the organization are exactly as specified by the master copies. Discussion:  The trusted distribution of security-relevant hardware, software, and firmware updates help to ensure that the updates are correct representations of the master copies maintained by the developer and have not been tampered with during distribution. Related Controls:  None. (7) DEVELOPER CONFIGURATION MANAGEMENT | SECURITY AND PRIVACY REPRESENTATIVES Require [Assignment: organization-defined security and privacy representatives] to be included in the [Assignment: organization-defined configuration change management and control process].', 'vec_doc-14-nist-sp-800-53-p302-1166', 0, 217, 'v2.1.0', 'ca3d9fadc4471977ff1d03f2216e08b172f2e99ac459f44cabe51ee98743cac4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 275","subsection":"UNKNOWN","table_id":null,"page":302,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1166,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 275"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p302-1167', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 275', 302, 'Discussion: Information security and privacy representatives can include system security officers, senior agency information security officers, senior agency officials for privacy, and system privacy officers. Representation by personnel with information security and privacy', 'vec_doc-14-nist-sp-800-53-p302-1167', 0, 69, 'v2.1.0', '4a06e6968fd21a21543071280111cc59b6cabd67aba1b220732f001316c03987', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 275","subsection":"UNKNOWN","table_id":null,"page":302,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1167,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 275"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p303-1168', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 276', 303, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems. The configuration change management and control process in this control enhancement refers to the change management and control process defined by organizations in SA-10b. Related Controls:  None. References:  [FIPS 140-3], [FIPS 180-4], [FIPS 202], [SP 800-128], [SP 800-160-1]. SA-11 DEVELOPER TESTING AND EVALUATION Control:  Require the developer of the system, system component, or system service, at all post- design stages of the system development life cycle, to: a. Develop and implement a plan for ongoing security and privacy control assessments; b.', 'vec_doc-14-nist-sp-800-53-p303-1168', 0, 243, 'v2.1.0', 'aa2278029434fe8c7be6cac13824d83a6c5ea8519717a807fe9e5c2e74acbf57', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 276","subsection":"UNKNOWN","table_id":null,"page":303,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1168,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 276"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p303-1169', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 276', 303, 'Perform [Selection (one or more): unit; integration; system; regression] testing/evaluation [Assignment: organization-defined frequency] at [Assignment: organization-defined depth and coverage]; c. Produce evidence of the execution of the assessment plan and the results of the testing and evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during testing and evaluation. Discussion:  Developmental testing and evaluation confirms that the required controls are implemented correctly, operating as intended, enforcing the desired security and privacy policies, and meeting established security and privacy requirements. Security properties of systems and the privacy of individuals may be affected by the interconnection of system components or changes to those components. The interconnections or changes— including upgrading or replacing applications, operating systems, and firmware— may adversely affect previously implemented controls.', 'vec_doc-14-nist-sp-800-53-p303-1169', 0, 247, 'v2.1.0', '4780bc7ee0fbf8ef94b644caf3290846c1ca66915c1905246a009cfbb1968c0f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 276","subsection":"UNKNOWN","table_id":null,"page":303,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1169,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 276"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p303-1170', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 276', 303, 'Ongoing assessment during development allows for additional types of testing and evaluation that developers can conduct to reduce or eliminate potential flaws. Testing custom software applications may require approaches such as manual code review, security architecture review, and penetration testing, as well as and static analysis, dynamic analysis, binary analysis, or a hybrid of the three analysis approaches. Developers can use the analysis approaches, along with security instrumentation and fuzzing, in a variety of tools and in source code reviews. The security and privacy assessment plans include the specific activities that developers plan to carry out, including the types of analyses, testing, evaluation, and reviews of software and firmware components; the degree of rigor to be applied; the frequency of the ongoing testing and evaluation; and the types of artifacts produced during those processes.', 'vec_doc-14-nist-sp-800-53-p303-1170', 0, 230, 'v2.1.0', '01724eeea363cf208764fc5f716c582a5402b4bb655705a6937ec41f8bd30db2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 276","subsection":"UNKNOWN","table_id":null,"page":303,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1170,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 276"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p303-1171', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 276', 303, 'The depth of testing and evaluation refers to the rigor and level of detail associated with the assessment process. The coverage of testing and evaluation refers to the scope (i.e., number and type) of the artifacts included in the assessment process. Contracts specify the acceptance criteria for security and privacy assessment plans, flaw remediation processes, and the evidence that the plans and processes have been diligently applied. Methods for reviewing and protecting assessment plans, evidence, and documentation are commensurate with the security category or classification level of the system. Contracts may specify protection requirements for documentation. Related Controls:  CA-2, CA-7, CM-4, SA-3, SA-4, SA-5, SA-8, SA-15, SA-17, SI-2, SR-5, SR-6, SR-7. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p303-1171', 0, 198, 'v2.1.0', '0807cd0283c19041f87ac5d7c983b9a3efd8466edc3bc87c8827c5caea389029', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 276","subsection":"UNKNOWN","table_id":null,"page":303,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1171,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 276"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p304-1172', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 277', 304, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) DEVELOPER TESTING AND EVALUATION | STATIC CODE ANALYSIS Require the developer of the system, system component, or system service to employ static code analysis tools to identify common flaws and document the results of the analysis. Discussion:  Static code analysis provides a technology and methodology for security reviews and includes checking for weaknesses in the code as well as for the incorporation of libraries or other included code with known vulnerabilities or that are out-of-date and not supported. Static code analysis can be used to identify vulnerabilities and enforce secure coding practices. It is most effective when used early in the development process, when each code change can automatically be scanned for potential weaknesses. Static code analysis can provide clear remediation guidance and identify defects for developers to fix.', 'vec_doc-14-nist-sp-800-53-p304-1172', 0, 239, 'v2.1.0', 'df1db94a2064b582e496e2b37e508d76725b5e1624572df5dc6c0d222257120c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 277","subsection":"UNKNOWN","table_id":null,"page":304,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1172,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 277"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p304-1173', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 277', 304, 'Evidence of the correct implementation of static analysis can include aggregate defect density for critical defect types, evidence that defects were inspected by developers or security professionals, and evidence that defects were remediated. A high density of ignored findings, commonly referred to as false positives, indicates a potential problem with the analysis process or the analysis tool. In such cases, organizations weigh the validity of the evidence against evidence from other sources. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p304-1173', 0, 131, 'v2.1.0', 'e4a3b3b03acc72b6c43aa8b6a3a648df4d8ba18fadc15f650d53568474d6c729', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 277","subsection":"UNKNOWN","table_id":null,"page":304,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1173,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 277"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p304-1174', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 277', 304, '(2) DEVELOPER TESTING AND EVALUATION | THREAT MODELING AND VULNERABILITY ANALYSES Require the developer of the system, system component, or system service to perform threat modeling and vulnerability analyses during development and the subsequent testing and evaluation of the system, component, or service that: (a) Uses the following contextual information: [Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels]; (b) Employs the following tools and methods: [Assignment: organization-defined tools and methods]; (c) Conducts the modeling and analyses at the following level of rigor: [Assignment: organization-defined breadth and depth of modeling and analyses]; and (d) Produces evidence that meets the following acceptance criteria: [Assignment: organization-defined acceptance criteria].', 'vec_doc-14-nist-sp-800-53-p304-1174', 0, 221, 'v2.1.0', 'a3d4e0a822119c196dd3fce50ec9e163f37693eb276ac75f979a747d2c0c316f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 277","subsection":"UNKNOWN","table_id":null,"page":304,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1174,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 277"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p304-1175', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 277', 304, 'Discussion:  Systems, system components, and system services may deviate significantly from the functional and design specifications created during the requirements and design stages of the system development life cycle. Therefore, updates to threat modeling and vulnerability analyses of those systems, system components, and system services during development and prior to delivery are critical to the effective operation of those systems, components, and services. Threat modeling and vulnerability analyses at this stage of the system development life cycle ensure that design and implementation changes have been accounted for and that vulnerabilities created because of those changes have been reviewed and mitigated. Related controls: PM-15, RA-3, RA-5.', 'vec_doc-14-nist-sp-800-53-p304-1175', 0, 190, 'v2.1.0', 'b2fe1e0b6974abf0c07e03db10f3ef671c8d211fe4df1c21c8e4e99257341b0d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 277","subsection":"UNKNOWN","table_id":null,"page":304,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1175,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 277"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p304-1176', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 277', 304, '(3) DEVELOPER TESTING AND EVALUATION | INDEPENDENT VERIFICATION OF ASSESSMENT PLANS AND EVIDENCE (a) Require an independent agent satisfying [Assignment: organization-defined independence criteria] to verify the correct implementation of the developer security and privacy assessment plans and the evidence produced during testing and evaluation; and', 'vec_doc-14-nist-sp-800-53-p304-1176', 0, 88, 'v2.1.0', '1c9c80993da7142aa3512eeff97caf517bf192b8d2e4bfd0c00d9260d6093880', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 277","subsection":"UNKNOWN","table_id":null,"page":304,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1176,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 277"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p305-1177', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 278', 305, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Verify that the independent agent is provided with sufficient information to complete the verification process or granted the authority to obtain such information. Discussion:  Independent agents have the qualifications— including the expertise, skills, training, certifications, and experience— to verify the correct implementation of developer security and privacy assessment plans. Related Controls:  AT-3, RA-5. (4) DEVELOPER TESTING AND EVALUATION | MANUAL CODE REVIEWS Require the developer of the system, system component, or system service to perform a manual code review of [Assignment: organization-defined specific code] using the following processes, procedures, and/or techniques: [Assignment: organization-defined processes, procedures, and/or techniques]. Discussion:  Manual code reviews are usually reserved for the critical software and firmware components of systems.', 'vec_doc-14-nist-sp-800-53-p305-1177', 0, 246, 'v2.1.0', '0347572215a00cd585d440101cf427f8bf86d10eb8f1f75746db0d81d543f169', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 278","subsection":"UNKNOWN","table_id":null,"page":305,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1177,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 278"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p305-1178', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 278', 305, 'Manual code reviews are effective at identifying weaknesses that require knowledge of the application’s requirements or context that, in most cases, is unavailable to automated analytic tools and techniques, such as static and dynamic analysis. The benefits of manual code review include the ability to verify access control matrices against application controls and review detailed aspects of cryptographic implementations and controls. Related Controls:  None. (5) DEVELOPER TESTING AND EVALUATION | PENETRATION TESTING Require the developer of the system, system component, or system service to perform penetration testing: (a) At the following level of rigor: [Assignment: organization-defined breadth and depth of testing]; and (b) Under the following constraints: [Assignment: organization-defined constraints].', 'vec_doc-14-nist-sp-800-53-p305-1178', 0, 205, 'v2.1.0', 'f99859ecdf7cd2d0fca5f16092585f906946653397668324d347aa95521f9b61', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 278","subsection":"UNKNOWN","table_id":null,"page":305,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1178,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 278"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p305-1179', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 278', 305, 'Discussion:  Penetration testing is an assessment methodology in which assessors, using all available information technology product or system documentation and working under specific constraints, attempt to circumvent the implemented security and privacy features of information technology products and systems. Useful information for assessors who conduct penetration testing includes product and system design specifications, source code, and administrator and operator manuals. Penetration testing can include white-box, gray-box, or black-box testing with analyses performed by skilled professionals who simulate adversary actions. The objective of penetration testing is to discover vulnerabilities in systems, system components, and services that result from implementation errors, configuration faults, or other operational weaknesses or deficiencies.', 'vec_doc-14-nist-sp-800-53-p305-1179', 0, 215, 'v2.1.0', '621f45ec20e414141c0c0b82284171eb1a24c729027db6a74b793b9d740854df', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 278","subsection":"UNKNOWN","table_id":null,"page":305,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1179,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 278"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p305-1180', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 278', 305, 'Penetration tests can be performed in conjunction with automated and manual code reviews to provide a greater level of analysis than would ordinarily be possible. When user session information and other personally identifiable information is captured or recorded during penetration testing, such information is handled appropriately to protect privacy. Related Controls:  CA-8, PM-14, PM-25, PT-2, SA-3, SI-2, SI-6. (6) DEVELOPER TESTING AND EVALUATION | ATTACK SURFACE REVIEWS Require the developer of the system, system component, or system service to perform attack surface reviews. Discussion:  Attack surfaces of systems and system components are exposed areas that make those systems more vulnerable to attacks. Attack surfaces include any accessible areas where weaknesses or deficiencies in the hardware, software, and firmware components provide opportunities for adversaries to exploit vulnerabilities.', 'vec_doc-14-nist-sp-800-53-p305-1180', 0, 228, 'v2.1.0', 'b972746cd8bd3307127c2c2e20e7765a33ec015396ecc7716a7dfd1164abb28b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 278","subsection":"UNKNOWN","table_id":null,"page":305,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1180,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 278"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p305-1181', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 278', 305, 'Attack surface reviews ensure that developers analyze the design and implementation changes to systems and', 'vec_doc-14-nist-sp-800-53-p305-1181', 0, 27, 'v2.1.0', '37db21dc995088795f5a797f9d2130ee23f210f9b4a160f14b2c2de03f3d69e9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 278","subsection":"UNKNOWN","table_id":null,"page":305,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1181,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 278"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p306-1182', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 279', 306, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 mitigate attack vectors generated as a result of the changes. The correction of identified flaws includes deprecation of unsafe functions. Related Controls:  SA-15. (7) DEVELOPER TESTING AND EVALUATION | VERIFY SCOPE OF TESTING AND EVALUATION Require the developer of the system, system component, or system service to verify that the scope of testing and evaluation provides complete coverage of the required controls at the following level of rigor: [Assignment: organization-defined breadth and depth of testing and evaluation]. Discussion:  Verifying that testing and evaluation provides complete coverage of required controls can be accomplished by a variety of analytic techniques ranging from informal to formal. Each of these techniques provides an increasing level of assurance that corresponds to the degree of formality of the analysis.', 'vec_doc-14-nist-sp-800-53-p306-1182', 0, 235, 'v2.1.0', '96e9579f5e2e4595afd3487672e5c221f9889ca5fbe1dad7bee878d4e287a84b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 279","subsection":"UNKNOWN","table_id":null,"page":306,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1182,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 279"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p306-1183', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 279', 306, 'Rigorously demonstrating control coverage at the highest levels of assurance can be achieved using formal modeling and analysis techniques, including correlation between control implementation and corresponding test cases. Related Controls:  SA-15. (8) DEVELOPER TESTING AND EVALUATION | DYNAMIC CODE ANALYSIS Require the developer of the system, system component, or system service to employ dynamic code analysis tools to identify common flaws and document the results of the analysis. Discussion:  Dynamic code analysis provides runtime verification of software programs using tools capable of monitoring programs for memory corruption, user privilege issues, and other potential security problems. Dynamic code analysis employs runtime tools to ensure that security functionality performs in the way it was designed. A type of dynamic analysis, known as fuzz testing, induces program failures by deliberately introducing malformed or random data into software programs.', 'vec_doc-14-nist-sp-800-53-p306-1183', 0, 244, 'v2.1.0', 'e2c07267f2e5f536510a675d3edfc6635a59b7f993143fa195b56a6936241603', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 279","subsection":"UNKNOWN","table_id":null,"page":306,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1183,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 279"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p306-1184', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 279', 306, 'Fuzz testing strategies are derived from the intended use of applications and the functional and design specifications for the applications. To understand the scope of dynamic code analysis and the assurance provided, organizations may also consider conducting code coverage analysis (i.e., checking the degree to which the code has been tested using metrics such as percent of subroutines tested or percent of program statements called during execution of the test suite) and/or concordance analysis (i.e., checking for words that are out of place in software code, such as non-English language words or derogatory terms). Related Controls:  None. (9) DEVELOPER TESTING AND EVALUATION | INTERACTIVE APPLICATION SECURITY TESTING Require the developer of the system, system component, or system service to employ interactive application security testing tools to identify flaws and document the results.', 'vec_doc-14-nist-sp-800-53-p306-1184', 0, 226, 'v2.1.0', '16b8bf431ea4b95cd269c162e87df67562f5f7478e8454c5147027fd22452396', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 279","subsection":"UNKNOWN","table_id":null,"page":306,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1184,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 279"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p306-1185', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 279', 306, 'Discussion: Interactive (also known as instrumentation-based) application security testing is a method of detecting vulnerabilities by observing applications as they run during testing. The use of instrumentation relies on direct measurements of the actual running applications and uses access to the code, user interaction, libraries, frameworks, backend connections, and configurations to directly measure control effectiveness. When combined with analysis techniques, interactive application security testing can identify a broad range of potential vulnerabilities and confirm control effectiveness. Instrumentation-based testing works in real time and can be used continuously throughout the system development life cycle. Related Controls:  None. References:  [ISO 15408-3], [SP 800-30], [SP 800-53A], [SP 800-154], [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p306-1185', 0, 209, 'v2.1.0', '53d7036ad0dc8dd5c5deaf0167695e5d82ae8d82759a42e2ef95029969ebd137', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 279","subsection":"UNKNOWN","table_id":null,"page":306,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1185,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 279"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p307-1186', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 280', 307, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-12 SUPPLY CHAIN PROTECTION [Withdrawn: Incorporated into SR Family.] Control Enhancements: (1) SUPPLY CHAIN PROTECTION | ACQUISITION STRATEGIES / TOOLS / METHODS [Withdrawn: Moved to SR-5.] (2) SUPPLY CHAIN PROTECTION | SUPPLIER REVIEWS [Withdrawn: Moved to SR-6.] (3) SUPPLY CHAIN PROTECTION | TRUSTED SHIPPING AND WAREHOUSING [Withdrawn: Incorporated into SR-3.] (4) SUPPLY CHAIN PROTECTION | DIVERSITY OF SUPPLIERS [Withdrawn: Moved to SR-3(1).] (5) SUPPLY CHAIN PROTECTION | LIMITATION OF HARM [Withdrawn: Moved to SR-3(2).] (6) SUPPLY CHAIN PROTECTION | MINIMIZING PROCUREMENT TIME [Withdrawn: Incorporated into SR-5(1).] (7) SUPPLY CHAIN PROTECTION | ASSESSMENTS PRIOR TO SELECTION / ACCEPTANCE / UPDATE [Withdrawn: Moved to SR-5(2).] (8) SUPPLY CHAIN PROTECTION | USE OF ALL-SOURCE INTELLIGENCE [Withdrawn: Incorporated into RA-3(2).] (9) SUPPLY CHAIN PROTECTION | OPERATIONS SECURITY [Withdrawn: Moved to SR-7.] (10) SUPPLY CHAIN PROTECTION | VALIDATE AS GENUINE AND NOT ALTERED [Withdrawn: Moved to SR-4(3).] (11) SUPPLY CHAIN PROTECTION | PENETRATION TESTING / ANALYSIS OF ELEMENTS, PROCESSES, AND ACTORS [Withdrawn: Moved to SR-6(1).] (12) SUPPLY CHAIN PROTECTION | INTER-ORGANIZATIONAL AGREEMENTS [Withdrawn: Moved to SR-8.] (13) SUPPLY CHAIN PROTECTION | CRITICAL INFORMATION SYSTEM COMPONENTS [Withdrawn: Incorporated into MA-6 and RA-9.] (14) SUPPLY CHAIN PROTECTION | IDENTITY AND TRACEABILITY [Withdrawn: Moved to SR-4(1) and SR-4(2).] (15) SUPPLY CHAIN PROTECTION | PROCESSES TO ADDRESS WEAKNESSES OR DEFICIENCIES [Withdrawn: Incorporated into SR-3.] SA-13 TRUSTWORTHINESS [Withdrawn: Incorporated into SA-8.]', 'vec_doc-14-nist-sp-800-53-p307-1186', 0, 431, 'v2.1.0', 'ac73c000ff7cad535ce111ce41962cc10d9940c127a9a259ebdac7f554d200f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 280","subsection":"UNKNOWN","table_id":null,"page":307,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1186,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 280"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p308-1187', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 281', 308, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-14 CRITICALITY ANALYSIS [Withdrawn: Incorporated into RA-9.] Control Enhancements: (1) CRITICALITY ANALYSIS | CRITICAL COMPONENTS WITH NO VIABLE ALTERNATIVE SOURCING [Withdrawn: Incorporated into SA-20.] SA-15 DEVELOPMENT PROCESS, STANDARDS, AND TOOLS Control: a. Require the developer of the system, system component, or system service to follow a documented development process that:', 'vec_doc-14-nist-sp-800-53-p308-1187', 0, 120, 'v2.1.0', '6fc2b17b578e71d740ae05db4fa3cde42067ca3e1df3072f90e7f4f026999093', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 281","subsection":"UNKNOWN","table_id":null,"page":308,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1187,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 281"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p308-1188', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Documents, manages, and ensures the integrity of changes to the process and/or tools', 308, 'used in development; and b. Review the development process, standards, tools, tool options, and tool configurations [Assignment: organization-defined frequency] to determine if the process, standards, tools, tool options and tool configurations selected and employed can satisfy the following security and privacy requirements: [Assignment: organization-defined security and privacy requirements]. Discussion:  Development tools include programming languages and computer-aided design systems. Reviews of development processes include the use of maturity models to determine the potential effectiveness of such processes. Maintaining the integrity of changes to tools and processes facilitates effective supply chain risk assessment and mitigation. Such integrity requires configuration control throughout the system development life cycle to track authorized changes and prevent unauthorized changes. Related Controls:  MA-6, SA-3, SA-4, SA-8, SA-10, SA-11, SR-3, SR-4, SR-5, SR-6, SR-9.', 'vec_doc-14-nist-sp-800-53-p308-1188', 0, 247, 'v2.1.0', '3a77dc8e288d6c037fe42290b2e6dac36e324d8538d20e53f283a612fd33634f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools","subsection":"UNKNOWN","table_id":null,"page":308,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1188,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p308-1189', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Documents, manages, and ensures the integrity of changes to the process and/or tools', 308, 'Control Enhancements: (1) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | QUALITY METRICS Require the developer of the system, system component, or system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics [Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery]. Discussion:  Organizations use quality metrics to establish acceptable levels of system quality. Metrics can include quality gates, which are collections of completion criteria or sufficiency standards that represent the satisfactory execution of specific phases of the system development project. For example, a quality gate may require the elimination of all compiler warnings or a determination that such warnings have no impact on the effectiveness of required security or privacy capabilities.', 'vec_doc-14-nist-sp-800-53-p308-1189', 0, 235, 'v2.1.0', '2a25d595885ec361686fcc771ce786335d694f938d3bcc19d0bc5b93a8053f67', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools","subsection":"UNKNOWN","table_id":null,"page":308,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1189,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p308-1190', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '4. Documents, manages, and ensures the integrity of changes to the process and/or tools', 308, 'During the execution phases of development projects, quality gates provide clear, unambiguous indications of progress. Other metrics apply to the entire development project. Metrics can include defining the severity thresholds of vulnerabilities in accordance with organizational risk tolerance, such', 'vec_doc-14-nist-sp-800-53-p308-1190', 0, 75, 'v2.1.0', 'eb615ea59bb409101587a23054aea50d95d2e58b93ad87ef98c8d330da1597de', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools","subsection":"UNKNOWN","table_id":null,"page":308,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1190,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"4. Documents, manages, and ensures the integrity of changes to the process and/or tools"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p309-1191', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 282', 309, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 as requiring no known vulnerabilities in the delivered system with a Common Vulnerability Scoring System (CVSS) severity of medium or high. Related Controls:  None. (2) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | SECURITY AND PRIVACY TRACKING TOOLS Require the developer of the system, system component, or system service to select and employ security and privacy tracking tools for use during the development process. Discussion:  System development teams select and deploy security and privacy tracking tools, including vulnerability or work item tracking systems that facilitate assignment, sorting, filtering, and tracking of completed work items or tasks associated with development processes. Related Controls:  SA-11.', 'vec_doc-14-nist-sp-800-53-p309-1191', 0, 204, 'v2.1.0', 'cd19c1a099056e5933b03d7ccc91cf119288b4e6a6f737cd03c5ab3e300688e5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 282","subsection":"UNKNOWN","table_id":null,"page":309,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1191,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 282"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p309-1192', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 282', 309, '(3) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | CRITICALITY ANALYSIS Require the developer of the system, system component, or system service to perform a criticality analysis: (a) At the following decision points in the system development life cycle: [Assignment: organization-defined decision points in the system development life cycle]; and (b) At the following level of rigor: [Assignment: organization-defined breadth and depth of criticality analysis]. Discussion:  Criticality analysis performed by the developer provides input to the criticality analysis performed by organizations. Developer input is essential to organizational criticality analysis because organizations may not have access to detailed design documentation for system components that are developed as commercial off-the-shelf products. Such design documentation includes functional specifications, high-level designs, low-level designs, source code, and hardware schematics.', 'vec_doc-14-nist-sp-800-53-p309-1192', 0, 238, 'v2.1.0', 'b17de7c24298fdbb6ceb7d6a8e92a746bde9cc62c36d7b5dece483d4ec1f0492', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 282","subsection":"UNKNOWN","table_id":null,"page":309,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1192,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 282"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p309-1193', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 282', 309, 'Criticality analysis is important for organizational systems that are designated as high value assets. High value assets can be moderate- or high-impact systems due to heightened adversarial interest or potential adverse effects on the federal enterprise. Developer input is especially important when organizations conduct supply chain criticality analyses. Related Controls:  RA-9. (4) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | THREAT MODELING AND VULNERABILITY ANALYSIS [Withdrawn: Incorporated into SA-11(2).] (5) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | ATTACK SURFACE REDUCTION Require the developer of the system, system component, or system service to reduce attack surfaces to [Assignment: organization-defined thresholds]. Discussion:  Attack surface reduction is closely aligned with threat and vulnerability analyses and system architecture and design.', 'vec_doc-14-nist-sp-800-53-p309-1193', 0, 217, 'v2.1.0', 'cf4282daee016f3b7131c45a16c062ff5cd91793da71e288874668ba26494675', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 282","subsection":"UNKNOWN","table_id":null,"page":309,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1193,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 282"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p309-1194', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 282', 309, 'Attack surface reduction is a means of reducing risk to organizations by giving attackers less opportunity to exploit weaknesses or deficiencies (i.e., potential vulnerabilities) within systems, system components, and system services. Attack surface reduction includes implementing the concept of layered defenses, applying the principles of least privilege and least functionality, applying secure software development practices, deprecating unsafe functions, reducing entry points available to unauthorized users, reducing the amount of code that executes, and eliminating application programming interfaces (APIs) that are vulnerable to attacks. Related Controls:  AC-6, CM-7, RA-3, SA-11. (6) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | CONTINUOUS IMPROVEMENT', 'vec_doc-14-nist-sp-800-53-p309-1194', 0, 191, 'v2.1.0', 'd81e264f6d6f90a988566f8c52a2423b48eb5e26f510d19a44795189fc0d7086', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 282","subsection":"UNKNOWN","table_id":null,"page":309,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1194,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 282"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p310-1195', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 283', 310, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Require the developer of the system, system component, or system service to implement an explicit process to continuously improve the development process. Discussion:  Developers of systems, system components, and system services consider the effectiveness and efficiency of their development processes for meeting quality objectives and addressing the security and privacy capabilities in current threat environments. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p310-1195', 0, 134, 'v2.1.0', '5b74a07bf9a0974a4048ce2f8075a8ba124b60730fa0d5b8aede99d184147c37', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 283","subsection":"UNKNOWN","table_id":null,"page":310,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1195,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 283"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p310-1196', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 283', 310, '(7) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | AUTOMATED VULNERABILITY ANALYSIS Require the developer of the system, system component, or system service [Assignment: organization-defined frequency] to: (a) Perform an automated vulnerability analysis using [Assignment: organization-defined tools]; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to [Assignment: organization-defined personnel or roles]. Discussion:  Automated tools can be more effective at analyzing exploitable weaknesses or deficiencies in large and complex systems, prioritizing vulnerabilities by severity, and providing recommendations for risk mitigations. Related Controls:  RA-5, SA-11.', 'vec_doc-14-nist-sp-800-53-p310-1196', 0, 208, 'v2.1.0', '5f191e5767b30a65adcae845ce4012b4b4417eb981bb9cb16329786c63949967', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 283","subsection":"UNKNOWN","table_id":null,"page":310,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1196,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 283"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p310-1197', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 283', 310, '(8) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | REUSE OF THREAT AND VULNERABILITY INFORMATION Require the developer of the system, system component, or system service to use threat modeling and vulnerability analyses from similar systems, components, or services to inform the current development process. Discussion:  Analysis of vulnerabilities found in similar software applications can inform potential design and implementation issues for systems under development. Similar systems or system components may exist within developer organizations. Vulnerability information is available from a variety of public and private sector sources, including the NIST National Vulnerability Database. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p310-1197', 0, 180, 'v2.1.0', 'aac08339288ec57f39d5640e427799fd8442570d861d5be4e6c1d15e167eb60c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 283","subsection":"UNKNOWN","table_id":null,"page":310,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1197,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 283"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p310-1198', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 283', 310, '(9) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | USE OF LIVE DATA [Withdrawn: Incorporated into SA-3(2).] (10) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | INCIDENT RESPONSE PLAN Require the developer of the system, system component, or system service to provide, implement, and test an incident response plan. Discussion:  The incident response plan provided by developers may provide information not readily available to organizations and be incorporated into organizational incident response plans. Developer information may also be extremely helpful, such as when organizations respond to vulnerabilities in commercial off-the-shelf products. Related Controls:  IR-8. (11) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | ARCHIVE SYSTEM OR COMPONENT Require the developer of the system or system component to archive the system or component to be released or delivered together with the corresponding evidence supporting the final security and privacy review.', 'vec_doc-14-nist-sp-800-53-p310-1198', 0, 239, 'v2.1.0', '68ab0ca2cf17b1b393dc69c5288807f560b22dd5bfa02058122676f5b45a63b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 283","subsection":"UNKNOWN","table_id":null,"page":310,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1198,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 283"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p311-1199', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 284', 311, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Archiving system or system components requires the developer to retain key development artifacts, including hardware specifications, source code, object code, and relevant documentation from the development process that can provide a readily available configuration baseline for system and component upgrades or modifications. Related Controls:  CM-2. (12) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | MINIMIZE PERSONALLY IDENTIFIABLE INFORMATION Require the developer of the system or system component to minimize the use of personally identifiable information in development and test environments. Discussion:  Organizations can minimize the risk to an individual’s privacy by using techniques such as de-identification or synthetic data. Limiting the use of personally identifiable information in development and test environments helps reduce the level of privacy risk created by a system.', 'vec_doc-14-nist-sp-800-53-p311-1199', 0, 250, 'v2.1.0', '4302fde16c4bc86ec3e2e1667ff928b264f73da0c580cc397225c78915675685', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 284","subsection":"UNKNOWN","table_id":null,"page":311,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1199,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 284"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p311-1200', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 284', 311, 'Related Controls:  PM-25, SA-3, SA-8. References:  [SP 800-160-1], [IR 8179]. SA-16 DEVELOPER-PROVIDED TRAINING Control:  Require the developer of the system, system component, or system service to provide the following training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms: [Assignment: organization-defined training]. Discussion:  Developer-provided training applies to external and internal (in-house) developers. Training personnel is essential to ensuring the effectiveness of the controls implemented within organizational systems. Types of training include web-based and computer-based training, classroom-style training, and hands-on training (including micro-training). Organizations can also request training materials from developers to conduct in-house training or offer self-training to organizational personnel.', 'vec_doc-14-nist-sp-800-53-p311-1200', 0, 223, 'v2.1.0', 'c73557c335afd413001e4c481affa11490b33169d79eeb6599ea36f833e28f2c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 284","subsection":"UNKNOWN","table_id":null,"page":311,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1200,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 284"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p311-1201', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 284', 311, 'Organizations determine the type of training necessary and may require different types of training for different security and privacy functions, controls, and mechanisms. Related Controls:  AT-2, AT-3, PE-3, SA-4, SA-5. Control Enhancements:  None. References:  None. SA-17 DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN Control:  Require the developer of the system, system component, or system service to produce a design specification and security and privacy architecture that: a. Is consistent with the organization’s security and privacy architecture that is an integral part the organization’s enterprise architecture; b. Accurately and completely describes the required security and privacy functionality, and the allocation of controls among physical and logical components; and c. Expresses how individual security and privacy functions, mechanisms, and services work together to provide required security and privacy capabilities and a unified approach to protection.', 'vec_doc-14-nist-sp-800-53-p311-1201', 0, 247, 'v2.1.0', '8cf114adb0eac7ce38b2f781ce8cb1b8a59a3db4ae32b88ef8251c6e65895fdc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 284","subsection":"UNKNOWN","table_id":null,"page":311,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1201,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 284"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p311-1202', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 284', 311, 'Discussion:  Developer security and privacy architecture and design are directed at external developers, although they could also be applied to internal (in-house) development. In contrast, PL-8 is directed at internal developers to ensure that organizations develop a security and privacy', 'vec_doc-14-nist-sp-800-53-p311-1202', 0, 73, 'v2.1.0', '481fe14b5845d2e1f0b3d8268c01fd57deeb1e6c6e1efc367cc15b190d55bb29', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 284","subsection":"UNKNOWN","table_id":null,"page":311,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1202,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 284"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p312-1203', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 285', 312, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 architecture that is integrated with the enterprise architecture. The distinction between SA-17 and PL-8 is especially important when organizations outsource the development of systems, system components, or system services and when there is a requirement to demonstrate consistency with the enterprise architecture and security and privacy architecture of the organization. [ISO 15408-2], [ISO 15408-3], and [SP 800-160-1] provide information on security architecture and design, including formal policy models, security-relevant components, formal and informal correspondence, conceptually simple design, and structuring for least privilege and testing. Related Controls:  PL-2, PL-8, PM-7, SA-3, SA-4, SA-8, SC-7.', 'vec_doc-14-nist-sp-800-53-p312-1203', 0, 202, 'v2.1.0', '4572ceeff1f2dd5aafc429a208990801afc5246ccbb98c482d66b2742dcadbdb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 285","subsection":"UNKNOWN","table_id":null,"page":312,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1203,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 285"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p312-1204', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 285', 312, 'Control Enhancements: (1) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | FORMAL POLICY MODEL Require the developer of the system, system component, or system service to: (a) Produce, as an integral part of the development process, a formal policy model describing the [Assignment: organization-defined elements of organizational security and privacy policy] to be enforced; and (b) Prove that the formal policy model is internally consistent and sufficient to enforce the defined elements of the organizational security and privacy policy when implemented. Discussion:  Formal models describe specific behaviors or security and privacy policies using formal languages, thus enabling the correctness of those behaviors and policies to be formally proven. Not all components of systems can be modeled. Generally, formal specifications are scoped to the behaviors or policies of interest, such as nondiscretionary access control policies.', 'vec_doc-14-nist-sp-800-53-p312-1204', 0, 237, 'v2.1.0', '83767bc880dfa1f8b3816f72659f526b2a5d42f14d6d4828bbccbbe9f5f6a5fb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 285","subsection":"UNKNOWN","table_id":null,"page":312,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1204,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 285"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p312-1205', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 285', 312, 'Organizations choose the formal modeling language and approach based on the nature of the behaviors and policies to be described and the available tools. Related Controls:  AC-3, AC-4, AC-25. (2) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | SECURITY-RELEVANT COMPONENTS Require the developer of the system, system component, or system service to: (a) Define security-relevant hardware, software, and firmware; and (b) Provide a rationale that the definition for security-relevant hardware, software, and firmware is complete. Discussion:  The security-relevant hardware, software, and firmware represent the portion of the system, component, or service that is trusted to perform correctly to maintain required security properties. Related Controls:  AC-25, SA-5.', 'vec_doc-14-nist-sp-800-53-p312-1205', 0, 194, 'v2.1.0', '5eb9edc4b2aa67305da04164e85b0a180aac8b302f8e7b118d450de45e810843', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 285","subsection":"UNKNOWN","table_id":null,"page":312,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1205,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 285"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p312-1206', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 285', 312, '(3) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | FORMAL CORRESPONDENCE Require the developer of the system, system component, or system service to: (a) Produce, as an integral part of the development process, a formal top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via proof to the extent feasible with additional informal demonstration as necessary, that the formal top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the formal top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware;', 'vec_doc-14-nist-sp-800-53-p312-1206', 0, 184, 'v2.1.0', '3f5d41ac0f441f1f282f044c0ab5e778e7a97a241b0cb2736ccdc83ffa3d47c8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 285","subsection":"UNKNOWN","table_id":null,"page":312,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1206,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 285"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p313-1207', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 286', 313, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (d) Show that the formal top-level specification is an accurate description of the implemented security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the formal top-level specification but strictly internal to the security- relevant hardware, software, and firmware. Discussion:  Correspondence is an important part of the assurance gained through modeling. It demonstrates that the implementation is an accurate transformation of the model, and that any additional code or implementation details that are present have no impact on the behaviors or policies being modeled.', 'vec_doc-14-nist-sp-800-53-p313-1207', 0, 191, 'v2.1.0', '8e4055e8aa82d23078d731ed123001cb212f5e9feb4369ac7df53d9be6ebf355', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 286","subsection":"UNKNOWN","table_id":null,"page":313,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1207,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 286"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p313-1208', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 286', 313, 'Formal methods can be used to show that the high- level security properties are satisfied by the formal system description, and that the formal system description is correctly implemented by a description of some lower level, including a hardware description. Consistency between the formal top-level specification and the formal policy models is generally not amenable to being fully proven. Therefore, a combination of formal and informal methods may be needed to demonstrate such consistency. Consistency between the formal top-level specification and the actual implementation may require the use of an informal demonstration due to limitations on the applicability of formal methods to prove that the specification accurately reflects the implementation. Hardware, software, and firmware mechanisms internal to security-relevant components include mapping registers and direct memory input and output. Related Controls:  AC-3, AC-4, AC-25, SA-4, SA-5.', 'vec_doc-14-nist-sp-800-53-p313-1208', 0, 239, 'v2.1.0', 'd9dbfba66244c3a188b40b237ef4162ed4693e77b6fcae80682664c21da609e7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 286","subsection":"UNKNOWN","table_id":null,"page":313,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1208,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 286"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p313-1209', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 286', 313, '(4) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | INFORMAL CORRESPONDENCE Require the developer of the system, system component, or system service to: (a) Produce, as an integral part of the development process, an informal descriptive top- level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via [Selection: informal demonstration; convincing argument with formal methods as feasible] that the descriptive top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the descriptive top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the descriptive top-level specification is an accurate description of the interfaces to security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the descriptive top-level specification but strictly internal to the security- relevant hardware, software, and firmware.', 'vec_doc-14-nist-sp-800-53-p313-1209', 0, 287, 'v2.1.0', '93270c2dd87ca8150ba672ab42772948bcae751c8e2416b2339e15b4640543a8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 286","subsection":"UNKNOWN","table_id":null,"page":313,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1209,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 286"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p313-1210', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 286', 313, 'Discussion:  Correspondence is an important part of the assurance gained through modeling. It demonstrates that the implementation is an accurate transformation of the model, and that additional code or implementation detail has no impact on the behaviors or policies being modeled. Consistency between the descriptive top-level specification (i.e., high- level/low-level design) and the formal policy model is generally not amenable to being fully proven. Therefore, a combination of formal and informal methods may be needed to show such consistency. Hardware, software, and firmware mechanisms strictly internal to security-relevant hardware, software, and firmware include mapping registers and direct memory input and output. Related Controls:  AC-3, AC-4, AC-25, SA-4, SA-5. (5) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | CONCEPTUALLY SIMPLE DESIGN Require the developer of the system, system component, or system service to:', 'vec_doc-14-nist-sp-800-53-p313-1210', 0, 237, 'v2.1.0', 'eed1f41020a6a3483dc4efe8f8958a9dd2de08ba74688d061a44c65d76fe29fc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 286","subsection":"UNKNOWN","table_id":null,"page":313,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1210,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 286"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p314-1211', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 287', 314, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (a) Design and structure the security-relevant hardware, software, and firmware to use a complete, conceptually simple protection mechanism with precisely defined semantics; and (b) Internally structure the security-relevant hardware, software, and firmware with specific regard for this mechanism. Discussion:  The principle of reduced complexity states that the system design is as simple and small as possible (see SA-8(7)). A small and simple design is easier to understand and analyze and is also less prone to error (see AC-25, SA-8(13)). The principle of reduced complexity applies to any aspect of a system, but it has particular importance for security due to the various analyses performed to obtain evidence about the emergent security property of the system. For such analyses to be successful, a small and simple design is essential.', 'vec_doc-14-nist-sp-800-53-p314-1211', 0, 235, 'v2.1.0', '2e7e0566bfa17bfa56dfb880971e0b2c4048a46cc9ed91fe41acecf17ef7fac2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 287","subsection":"UNKNOWN","table_id":null,"page":314,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1211,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 287"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p314-1212', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 287', 314, 'Application of the principle of reduced complexity contributes to the ability of system developers to understand the correctness and completeness of system security functions and facilitates the identification of potential vulnerabilities. The corollary of reduced complexity states that the simplicity of the system is directly related to the number of vulnerabilities it will contain. That is, simpler systems contain fewer vulnerabilities. An important benefit of reduced complexity is that it is easier to understand whether the security policy has been captured in the system design and that fewer vulnerabilities are likely to be introduced during engineering development. An additional benefit is that any such conclusion about correctness, completeness, and existence of vulnerabilities can be reached with a higher degree of assurance in contrast to conclusions reached in situations where the system design is inherently more complex. Related Controls:  AC-25, SA-8, SC-3.', 'vec_doc-14-nist-sp-800-53-p314-1212', 0, 246, 'v2.1.0', '78c68dc1bfa3531081e82fa9356a608c30410b1828b52662e4d69becdcd45288', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 287","subsection":"UNKNOWN","table_id":null,"page":314,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1212,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 287"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p314-1213', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 287', 314, '(6) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | STRUCTURE FOR TESTING Require the developer of the system, system component, or system service to structure security-relevant hardware, software, and firmware to facilitate testing. Discussion:  Applying the security design principles in [SP 800-160-1] promotes complete, consistent, and comprehensive testing and evaluation of systems, system components, and services. The thoroughness of such testing contributes to the evidence produced to generate an effective assurance case or argument as to the trustworthiness of the system, system component, or service. Related Controls:  SA-5, SA-11. (7) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | STRUCTURE FOR LEAST PRIVILEGE Require the developer of the system, system component, or system service to structure security-relevant hardware, software, and firmware to facilitate controlling access with least privilege.', 'vec_doc-14-nist-sp-800-53-p314-1213', 0, 235, 'v2.1.0', '4bc79e901a5c7b7d0f5d9ae46d11a52000d27a5eb8bf72fe2a6bba7bf1d47653', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 287","subsection":"UNKNOWN","table_id":null,"page":314,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1213,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 287"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p314-1214', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 287', 314, 'Discussion:  The principle of least privilege states that each component is allocated sufficient privileges to accomplish its specified functions but no more (see SA-8(14)). Applying the principle of least privilege limits the scope of the component’s actions, which has two desirable effects. First, the security impact of a failure, corruption, or misuse of the system component results in a minimized security impact. Second, the security analysis of the component is simplified. Least privilege is a pervasive principle that is reflected in all aspects of the secure system design. Interfaces used to invoke component capability are available to only certain subsets of the user population, and component design supports a sufficiently fine granularity of privilege decomposition.', 'vec_doc-14-nist-sp-800-53-p314-1214', 0, 196, 'v2.1.0', '5eb9444d9184866594c5679b4858dacb9722e30abc8e4c6f88483272bb9ce3dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 287","subsection":"UNKNOWN","table_id":null,"page":314,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1214,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 287"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p314-1215', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 287', 314, 'For example, in the case of an audit mechanism, there may be an interface for the audit manager, who configures the audit settings; an interface for the audit operator, who ensures that audit data is safely collected and stored; and, finally, yet another interface for the audit reviewer, who only has a need to view the audit data that has been collected but no need to perform operations on that data.', 'vec_doc-14-nist-sp-800-53-p314-1215', 0, 101, 'v2.1.0', 'e68c690a5e59e9354f38a603aa40c0bebb8053d55004409e74e76dd6d7c49b18', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 287","subsection":"UNKNOWN","table_id":null,"page":314,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1215,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 287"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p315-1216', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 288', 315, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 In addition to its manifestations at the system interface, least privilege can be used as a guiding principle for the internal structure of the system itself. One aspect of internal least privilege is to construct modules so that only the elements encapsulated by the module are directly operated upon by the functions within the module. Elements external to a module that may be affected by the module’s operation are indirectly accessed through interaction (e.g., via a function call) with the module that contains those elements. Another aspect of internal least privilege is that the scope of a given module or component includes only those system elements that are necessary for its functionality, and the access modes to the elements (e.g., read, write) are minimal. Related Controls:  AC-5, AC-6, SA-8.', 'vec_doc-14-nist-sp-800-53-p315-1216', 0, 226, 'v2.1.0', '8a61d95f5c39abb2eac7479a76b42d2efba639aa6d61a515bb6312911aa70e41', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 288","subsection":"UNKNOWN","table_id":null,"page":315,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1216,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 288"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p315-1217', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 288', 315, '(8) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | ORCHESTRATION Design [Assignment: organization-defined critical systems or system components] with coordinated behavior to implement the following capabilities: [Assignment: organization- defined capabilities, by system or component]. Discussion:  Security resources that are distributed, located at different layers or in different system elements, or are implemented to support different aspects of trustworthiness can interact in unforeseen or incorrect ways. Adverse consequences can include cascading failures, interference, or coverage gaps. Coordination of the behavior of security resources (e.g., by ensuring that one patch is installed across all resources before making a configuration change that assumes that the patch is propagated) can avert such negative interactions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p315-1217', 0, 218, 'v2.1.0', '641575e166300bb12577d9a741cb83ef376a8bf456d4cff822374c9ccf480ef7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 288","subsection":"UNKNOWN","table_id":null,"page":315,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1217,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 288"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p315-1218', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 288', 315, '(9) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | DESIGN DIVERSITY Use different designs for [Assignment: organization-defined critical systems or system components] to satisfy a common set of requirements or to provide equivalent functionality. Discussion:  Design diversity is achieved by supplying the same requirements specification to multiple developers, each of whom is responsible for developing a variant of the system or system component that meets the requirements. Variants can be in software design, in hardware design, or in both hardware and a software design.', 'vec_doc-14-nist-sp-800-53-p315-1218', 0, 147, 'v2.1.0', '70ca8e6c8f9b8d8c52627e782cad1ab1dac55581a833d44037bc6a5308fd5e8e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 288","subsection":"UNKNOWN","table_id":null,"page":315,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1218,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 288"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p315-1219', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 288', 315, 'Differences in the designs of the variants can result from developer experience (e.g., prior use of a design pattern), design style (e.g., when decomposing a required function into smaller tasks, determining what constitutes a separate task and how far to decompose tasks into sub-tasks), selection of libraries to incorporate into the variant, and the development environment (e.g., different design tools make some design patterns easier to visualize). Hardware design diversity includes making different decisions about what information to keep in analog form and what information to convert to digital form, transmitting the same information at different times, and introducing delays in sampling (temporal diversity). Design diversity is commonly used to support fault tolerance. Related Controls:  None. References:  [ISO 15408-2], [ISO 15408-3], [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p315-1219', 0, 217, 'v2.1.0', 'aeee607aaa2e4aa2ed52df1e3852fe4c9ab33213d9c8b978f11addd8bde52c68', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 288","subsection":"UNKNOWN","table_id":null,"page":315,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1219,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 288"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p315-1220', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 288', 315, 'SA-18 TAMPER RESISTANCE AND DETECTION [Withdrawn: Moved to SR-9.] Control Enhancements: (1) TAMPER RESISTANCE AND DETECTION | MULTIPLE PHASES OF SYSTEM DEVELOPMENT LIFE CYCLE [Withdrawn: Moved to SR-9(1).]', 'vec_doc-14-nist-sp-800-53-p315-1220', 0, 52, 'v2.1.0', 'b310fb6f84d5407eba93d4edce6a60dcfd9e9f06319b7c1cbd4c630c1e2a5159', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 288","subsection":"UNKNOWN","table_id":null,"page":315,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1220,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 288"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p316-1221', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 289', 316, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (2) TAMPER RESISTANCE AND DETECTION | INSPECTION OF SYSTEMS OR COMPONENTS [Withdrawn: Moved to SR-10.] SA-19 COMPONENT AUTHENTICITY [Withdrawn: Moved to SR-11.] Control Enhancements: (1) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT TRAINING [Withdrawn: Moved to SR-11(1).] (2) COMPONENT AUTHENTICITY | CONFIGURATION CONTROL FOR COMPONENT SERVICE AND REPAIR [Withdrawn: Moved to SR-11(2).] (3) COMPONENT AUTHENTICITY | COMPONENT DISPOSAL [Withdrawn: Moved to SR-12.] (4) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT SCANNING [Withdrawn: Moved to SR-11(3).] SA-20 CUSTOMIZED DEVELOPMENT OF CRITICAL COMPONENTS Control:  Reimplement or custom develop the following critical system components: [Assignment: organization-defined critical system components].', 'vec_doc-14-nist-sp-800-53-p316-1221', 0, 210, 'v2.1.0', '6eb262f4426e3301ede90b2b2cd626613e16d55d2530ccce2ec6bbd09c663f66', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 289","subsection":"UNKNOWN","table_id":null,"page":316,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1221,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 289"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p316-1222', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 289', 316, 'Discussion:  Organizations determine that certain system components likely cannot be trusted due to specific threats to and vulnerabilities in those components for which there are no viable security controls to adequately mitigate risk. Reimplementation or custom development of such components may satisfy requirements for higher assurance and is carried out by initiating changes to system components (including hardware, software, and firmware) such that the standard attacks by adversaries are less likely to succeed. In situations where no alternative sourcing is available and organizations choose not to reimplement or custom develop critical system components, additional controls can be employed. Controls include enhanced auditing, restrictions on source code and system utility access, and protection from deletion of system and application files. Related Controls:  CP-2, RA-9, SA-8. Control Enhancements:  None. References:  [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p316-1222', 0, 239, 'v2.1.0', 'b1cd0af9efc98c08802877014fade9f327bc2281cfe4690e0ab7ba48cee995e9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 289","subsection":"UNKNOWN","table_id":null,"page":316,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1222,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 289"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p316-1223', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 289', 316, 'SA-21 DEVELOPER SCREENING Control:  Require that the developer of [Assignment: organization-defined system, system component, or system service]: a. Has appropriate access authorizations as determined by assigned [Assignment: organization- defined official government duties]; and b. Satisfies the following additional personnel screening criteria: [Assignment: organization- defined additional personnel screening criteria]. Discussion:  Developer screening is directed at external developers. Internal developer screening is addressed by PS-3. Because the system, system component, or system service may be used in critical activities essential to the national or economic security interests of the United States, organizations have a strong interest in ensuring that developers are trustworthy. The degree of', 'vec_doc-14-nist-sp-800-53-p316-1223', 0, 203, 'v2.1.0', 'b88e88671028dd041fb2a070f0a4fecb4c65b58a381892a09fd27ed78b61112d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 289","subsection":"UNKNOWN","table_id":null,"page":316,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1223,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 289"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p317-1224', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 290', 317, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 trust required of developers may need to be consistent with that of the individuals who access the systems, system components, or system services once deployed. Authorization and personnel screening criteria include clearances, background checks, citizenship, and nationality. Developer trustworthiness may also include a review and analysis of company ownership and relationships that the company has with entities that may potentially affect the quality and reliability of the systems, components, or services being developed. Satisfying the required access authorizations and personnel screening criteria includes providing a list of all individuals who are authorized to perform development activities on the selected system, system component, or system service so that organizations can validate that the developer has satisfied the authorization and screening requirements.', 'vec_doc-14-nist-sp-800-53-p317-1224', 0, 243, 'v2.1.0', '424a795c0a51a2fca9472da88087dfdc0158638a5ff9d5b29350e12afe82af88', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 290","subsection":"UNKNOWN","table_id":null,"page":317,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1224,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 290"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p317-1225', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 290', 317, 'Related Controls:  PS-2, PS-3, PS-6, PS-7, SA-4, SR-6. Control Enhancements: (1) DEVELOPER SCREENING | VALIDATION OF SCREENING [Withdrawn: Incorporated into SA-21.] References:  None. SA-22 UNSUPPORTED SYSTEM COMPONENTS Control: a. Replace system components when support for the components is no longer available from the developer, vendor, or manufacturer; or b. Provide the following options for alternative sources for continued support for unsupported components [Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]]. Discussion:  Support for system components includes software patches, firmware updates, replacement parts, and maintenance contracts. An example of unsupported components includes when vendors no longer provide critical software patches or product updates, which can result in an opportunity for adversaries to exploit weaknesses in the installed components.', 'vec_doc-14-nist-sp-800-53-p317-1225', 0, 235, 'v2.1.0', 'fe560ed3fe2519a0414f82ac30188f125776870d0d3a9573d2146b8a92419baa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 290","subsection":"UNKNOWN","table_id":null,"page":317,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1225,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 290"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p317-1226', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 290', 317, 'Exceptions to replacing unsupported system components include systems that provide critical mission or business capabilities where newer technologies are not available or where the systems are so isolated that installing replacement components is not an option. Alternative sources for support address the need to provide continued support for system components that are no longer supported by the original manufacturers, developers, or vendors when such components remain essential to organizational mission and business functions. If necessary, organizations can establish in-house support by developing customized patches for critical software components or, alternatively, obtain the services of external providers who provide ongoing support for the designated unsupported components through contractual relationships. Such contractual relationships can include open-source software value-added vendors.', 'vec_doc-14-nist-sp-800-53-p317-1226', 0, 227, 'v2.1.0', '9a700aa03a28e5210182c05ea99530909d1140e9cacefd7b03bacc9d13633b3a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 290","subsection":"UNKNOWN","table_id":null,"page":317,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1226,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 290"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p317-1227', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 290', 317, 'The increased risk of using unsupported system components can be mitigated, for example, by prohibiting the connection of such components to public or uncontrolled networks, or implementing other forms of isolation. Related Controls:  PL-2, SA-3. Control Enhancements: (1) UNSUPPORTED SYSTEM COMPONENTS | ALTERNATIVE SOURCES FOR CONTINUED SUPPORT [Withdrawn: Incorporated into SA-22.] References:  None.', 'vec_doc-14-nist-sp-800-53-p317-1227', 0, 101, 'v2.1.0', '4b51b9f856ff463370ee293a977a2dccceb7d278c9f597adbd78edc92c1731cb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 290","subsection":"UNKNOWN","table_id":null,"page":317,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1227,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 290"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p318-1228', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 291', 318, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SA-23 SPECIALIZATION Control:  Employ [Selection (one or more): design; modification; augmentation; reconfiguration] on [Assignment: organization-defined systems or system components] supporting mission essential services or functions to increase the trustworthiness in those systems or components. Discussion:  It is often necessary for a system or system component that supports mission- essential services or functions to be enhanced to maximize the trustworthiness of the resource. Sometimes this enhancement is done at the design level. In other instances, it is done post- design, either through modifications of the system in question or by augmenting the system with additional components. For example, supplemental authentication or non-repudiation functions may be added to the system to enhance the identity of critical resources to other resources that depend on the organization-defined resources. Related Controls:  RA-9, SA-8. Control Enhancements:  None. References:  [SP 800-160-1], [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p318-1228', 0, 277, 'v2.1.0', 'a045e6aba0484e5726e57c925fa4f77830a6cebef5fe0702a87e6979334ce1c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 291","subsection":"UNKNOWN","table_id":null,"page":318,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1228,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 291"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p319-1229', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.18   SYSTEM AND COMMUNICATIONS PROTECTION', 319, 'Quick link to System and Communications Protection Summary Table SC-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p319-1229', 0, 49, 'v2.1.0', '9ff96d884f4721c8b5dab3d9660af47e5b3434ccbe4c4097bbadd048068d160a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.18   SYSTEM AND COMMUNICATIONS PROTECTION","subsection":"UNKNOWN","table_id":null,"page":319,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1229,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.18   SYSTEM AND COMMUNICATIONS PROTECTION"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p319-1230', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 319, 'level] system and communications protection policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p319-1230', 0, 81, 'v2.1.0', '81cba997b82af50c468bad78757f9c42d6524e7d60cef1490719c8cde8ecab5e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":319,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1230,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p319-1231', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the system and communications', 319, 'protection policy and the associated system and communications protection controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and communications protection policy and procedures; and c. Review and update the current system and communications protection:', 'vec_doc-14-nist-sp-800-53-p319-1231', 0, 87, 'v2.1.0', '7fee00b0bf9feca23f33e31e65129b2bf2ab8e9d652c6fbab6103f12ba0cb704', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the system and communications","subsection":"UNKNOWN","table_id":null,"page":319,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1231,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the system and communications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p319-1232', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 319, 'organization-defined events]. Discussion:  System and communications protection policy and procedures address the controls in the SC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and communications protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and communications protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SA-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p319-1232', 0, 437, 'v2.1.0', '6413382666fac9e4d0d343091aff92d4665a9fc0ee4bfbc0926694c6e0971b3e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":319,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1232,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p320-1233', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 293', 320, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SC-2 SEPARATION OF SYSTEM AND USER FUNCTIONALITY Control:  Separate user functionality, including user interface services, from system management functionality. Discussion:  System management functionality includes functions that are necessary to administer databases, network components, workstations, or servers. These functions typically require privileged user access. The separation of user functions from system management functions is physical or logical. Organizations may separate system management functions from user functions by using different computers, instances of operating systems, central processing units, or network addresses; by employing virtualization techniques; or some combination of these or other methods.', 'vec_doc-14-nist-sp-800-53-p320-1233', 0, 207, 'v2.1.0', '8c8a8a997ab263e4e51d5eb98ac519eeccef6d5b079f00b26437c2f78eee4003', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 293","subsection":"UNKNOWN","table_id":null,"page":320,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1233,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 293"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p320-1234', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 293', 320, 'Separation of system management functions from user functions includes web administrative interfaces that employ separate authentication methods for users of any other system resources. Separation of system and user functions may include isolating administrative interfaces on different domains and with additional access controls. The separation of system and user functionality can be achieved by applying the systems security engineering design principles in SA-8, including SA-8(1), SA-8(3), SA-8(4), SA-8(10), SA-8(12), SA- 8(13), SA-8(14), and SA-8(18). Related Controls:  AC-6, SA-4, SA-8, SC-3, SC-7, SC-22, SC-32, SC-39. Control Enhancements: (1) SEPARATION OF SYSTEM AND USER FUNCTIONALITY | INTERFACES FOR NON-PRIVILEGED USERS Prevent the presentation of system management functionality at interfaces to non- privileged users.', 'vec_doc-14-nist-sp-800-53-p320-1234', 0, 210, 'v2.1.0', 'e2232349386f6ebc474cd2dde5f91f21b033c07606dbb499567ec3309f65b422', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 293","subsection":"UNKNOWN","table_id":null,"page":320,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1234,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 293"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p320-1235', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 293', 320, 'Discussion:  Preventing the presentation of system management functionality at interfaces to non-privileged users ensures that system administration options, including administrator privileges, are not available to the general user population. Restricting user access also prohibits the use of the grey-out option commonly used to eliminate accessibility to such information. One potential solution is to withhold system administration options until users establish sessions with administrator privileges. Related Controls:  AC-3. (2) SEPARATION OF SYSTEM AND USER FUNCTIONALITY | DISASSOCIABILITY Store state information from applications and software separately. Discussion:  If a system is compromised, storing applications and software separately from state information about users’ interactions with an application may better protect individuals’ privacy. Related Controls:  None. References:  None. SC-3 SECURITY FUNCTION ISOLATION Control:  Isolate security functions from nonsecurity functions.', 'vec_doc-14-nist-sp-800-53-p320-1235', 0, 251, 'v2.1.0', '5e40428ef36f93f34d02431a9b3680a270eb183764bf0b3547af3dee0a11508b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 293","subsection":"UNKNOWN","table_id":null,"page":320,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1235,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 293"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p320-1236', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 293', 320, 'Discussion:  Security functions are isolated from nonsecurity functions by means of an isolation boundary implemented within a system via partitions and domains. The isolation boundary controls access to and protects the integrity of the hardware, software, and firmware that perform system security functions. Systems implement code separation in many ways, such as through the provision of security kernels via processor rings or processor modes. For non-kernel code, security function isolation is often achieved through file system protections that protect the code on disk and address space protections that protect executing code. Systems can restrict access to security functions using access control mechanisms and by implementing least privilege', 'vec_doc-14-nist-sp-800-53-p320-1236', 0, 189, 'v2.1.0', '1aed0f8f559af8b7e04edb20843d980e2125848915dceeb4e07413ae79f5a39f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 293","subsection":"UNKNOWN","table_id":null,"page":320,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1236,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 293"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p321-1237', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 294', 321, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 capabilities. While the ideal is for all code within the defined security function isolation boundary to only contain security-relevant code, it is sometimes necessary to include nonsecurity functions as an exception. The isolation of security functions from nonsecurity functions can be achieved by applying the systems security engineering design principles in SA-8, including SA-8(1), SA-8(3), SA-8(4), SA-8(10), SA-8(12), SA-8(13), SA-8(14), and SA-8(18). Related Controls:  AC-3, AC-6, AC-25, CM-2, CM-4, SA-4, SA-5, SA-8, SA-15, SA-17, SC-2, SC-7, SC- 32, SC-39, SI-16. Control Enhancements: (1) SECURITY FUNCTION ISOLATION | HARDWARE SEPARATION Employ hardware separation mechanisms to implement security function isolation.', 'vec_doc-14-nist-sp-800-53-p321-1237', 0, 206, 'v2.1.0', '3da0988dbbdd1961259ce69d5f7e36d9c56b0c6a9d126aa2246779bac6ae9fd6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 294","subsection":"UNKNOWN","table_id":null,"page":321,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1237,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 294"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p321-1238', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 294', 321, 'Discussion:  Hardware separation mechanisms include hardware ring architectures that are implemented within microprocessors and hardware-enforced address segmentation used to support logically distinct storage objects with separate attributes (i.e., readable, writeable). Related Controls:  None. (2) SECURITY FUNCTION ISOLATION | ACCESS AND FLOW CONTROL FUNCTIONS Isolate security functions enforcing access and information flow control from nonsecurity functions and from other security functions. Discussion:  Security function isolation occurs because of implementation. The functions can still be scanned and monitored. Security functions that are potentially isolated from access and flow control enforcement functions include auditing, intrusion detection, and malicious code protection functions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p321-1238', 0, 208, 'v2.1.0', 'a9103152a09e43e0541aef71313fa033314c04b02131ecce6b46244320d0d5c5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 294","subsection":"UNKNOWN","table_id":null,"page":321,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1238,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 294"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p321-1239', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 294', 321, '(3) SECURITY FUNCTION ISOLATION | MINIMIZE NONSECURITY FUNCTIONALITY Minimize the number of nonsecurity functions included within the isolation boundary containing security functions. Discussion:  Where it is not feasible to achieve strict isolation of nonsecurity functions from security functions, it is necessary to take actions to minimize nonsecurity-relevant functions within the security function boundary. Nonsecurity functions contained within the isolation boundary are considered security-relevant because errors or malicious code in the software can directly impact the security functions of systems. The fundamental design objective is that the specific portions of systems that provide information security are of minimal size and complexity.', 'vec_doc-14-nist-sp-800-53-p321-1239', 0, 189, 'v2.1.0', 'f80e7b124c05622d101e93bb25b894dbbe0e0f84c324a1522421e937ee90450b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 294","subsection":"UNKNOWN","table_id":null,"page":321,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1239,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 294"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p321-1240', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 294', 321, 'Minimizing the number of nonsecurity functions in the security-relevant system components allows designers and implementers to focus only on those functions which are necessary to provide the desired security capability (typically access enforcement). By minimizing the nonsecurity functions within the isolation boundaries, the amount of code that is trusted to enforce security policies is significantly reduced, thus contributing to understandability. Related Controls:  None. (4) SECURITY FUNCTION ISOLATION | MODULE COUPLING AND COHESIVENESS Implement security functions as largely independent modules that maximize internal cohesiveness within modules and minimize coupling between modules. Discussion:  The reduction of inter-module interactions helps to constrain security functions and manage complexity. The concepts of coupling and cohesion are important with respect to modularity in software design. Coupling refers to the dependencies that one module has on other modules.', 'vec_doc-14-nist-sp-800-53-p321-1240', 0, 247, 'v2.1.0', '003715469f5b8149caf70602d417e8a1fd9a4c6b73f1f50311f7e7c5a64fa927', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 294","subsection":"UNKNOWN","table_id":null,"page":321,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1240,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 294"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p321-1241', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 294', 321, 'Cohesion refers to the relationship between functions within a module. Best practices in software engineering and systems security engineering rely on layering,', 'vec_doc-14-nist-sp-800-53-p321-1241', 0, 40, 'v2.1.0', '8e5afbd6f534506068bc8e428373b19153d076e29c0d710bce41be98408e3a25', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 294","subsection":"UNKNOWN","table_id":null,"page":321,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1241,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 294"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p322-1242', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 295', 322, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 minimization, and modular decomposition to reduce and manage complexity. This produces software modules that are highly cohesive and loosely coupled. Related Controls:  None. (5) SECURITY FUNCTION ISOLATION | LAYERED STRUCTURES Implement security functions as a layered structure minimizing interactions between layers of the design and avoiding any dependence by lower layers on the functionality or correctness of higher layers. Discussion:  The implementation of layered structures with minimized interactions among security functions and non-looping layers (i.e., lower-layer functions do not depend on higher-layer functions) enables the isolation of security functions and the management of complexity. Related Controls:  None. References:  None. SC-4 INFORMATION IN SHARED SYSTEM RESOURCES Control:  Prevent unauthorized and unintended information transfer via shared system resources.', 'vec_doc-14-nist-sp-800-53-p322-1242', 0, 246, 'v2.1.0', '9fa9a994a1385bc7015f220194f70c91be35b6e0fb79ba513fc1594279534d01', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 295","subsection":"UNKNOWN","table_id":null,"page":322,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1242,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 295"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p322-1243', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 295', 322, 'Discussion:  Preventing unauthorized and unintended information transfer via shared system resources stops information produced by the actions of prior users or roles (or the actions of processes acting on behalf of prior users or roles) from being available to current users or roles (or current processes acting on behalf of current users or roles) that obtain access to shared system resources after those resources have been released back to the system. Information in shared system resources also applies to encrypted representations of information. In other contexts, control of information in shared system resources is referred to as object reuse and residual information protection.', 'vec_doc-14-nist-sp-800-53-p322-1243', 0, 173, 'v2.1.0', 'ae7a761e44c60ebd8cc44a7a35b8382937c98adc6e06384296b756045b915dba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 295","subsection":"UNKNOWN","table_id":null,"page":322,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1243,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 295"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p322-1244', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 295', 322, 'Information in shared system resources does not address information remanence, which refers to the residual representation of data that has been nominally deleted; covert channels (including storage and timing channels), where shared system resources are manipulated to violate information flow restrictions; or components within systems for which there are only single users or roles. Related Controls:  AC-3, AC-4, SA-8. Control Enhancements: (1) INFORMATION IN SHARED SYSTEM RESOURCES | SECURITY LEVELS [Withdrawn: Incorporated into SC-4.] (2) INFORMATION IN SHARED SYSTEM RESOURCES | MULTILEVEL OR PERIODS PROCESSING Prevent unauthorized information transfer via shared resources in accordance with [Assignment: organization-defined procedures] when system processing explicitly switches between different information classification levels or security categories.', 'vec_doc-14-nist-sp-800-53-p322-1244', 0, 217, 'v2.1.0', '1bbeb465f2ff75efe1f8dbb2ae27352748e4b9deb46c14bf1140cbbcf64e3646', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 295","subsection":"UNKNOWN","table_id":null,"page":322,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1244,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 295"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p322-1245', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 295', 322, 'Discussion:  Changes in processing levels can occur during multilevel or periods processing with information at different classification levels or security categories. It can also occur during serial reuse of hardware components at different classification levels. Organization- defined procedures can include approved sanitization processes for electronically stored information. Related Controls:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p322-1245', 0, 106, 'v2.1.0', '8c3ae68010f19121a0ace7d1ce80b91112969813a0b2bc49ee25b624682395d8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 295","subsection":"UNKNOWN","table_id":null,"page":322,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1245,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 295"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p323-1246', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 296', 323, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SC-5 DENIAL-OF-SERVICE PROTECTION Control: a. [Selection: Protect against; Limit] the effects of the following types of denial-of-service events: [Assignment: organization-defined types of denial-of-service events]; and b. Employ the following controls to achieve the denial-of-service objective: [Assignment: organization-defined controls by type of denial-of-service event]. Discussion:  Denial-of-service events may occur due to a variety of internal and external causes, such as an attack by an adversary or a lack of planning to support organizational needs with respect to capacity and bandwidth. Such attacks can occur across a wide range of network protocols (e.g., IPv4, IPv6). A variety of technologies are available to limit or eliminate the origination and effects of denial-of-service events.', 'vec_doc-14-nist-sp-800-53-p323-1246', 0, 225, 'v2.1.0', '2d840da81661a0e5025b77dd213f5be1f4b09f47aa78808d3ed7f88a8b654bb6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 296","subsection":"UNKNOWN","table_id":null,"page":323,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1246,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 296"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p323-1247', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 296', 323, 'For example, boundary protection devices can filter certain types of packets to protect system components on internal networks from being directly affected by or the source of denial-of-service attacks. Employing increased network capacity and bandwidth combined with service redundancy also reduces the susceptibility to denial-of-service events. Related Controls:  CP-2, IR-4, SC-6, SC-7, SC-40. Control Enhancements: (1) DENIAL-OF-SERVICE PROTECTION | RESTRICT ABILITY TO ATTACK OTHER SYSTEMS Restrict the ability of individuals to launch the following denial-of-service attacks against other systems: [Assignment: organization-defined denial-of-service attacks]. Discussion:  Restricting the ability of individuals to launch denial-of-service attacks requires the mechanisms commonly used for such attacks to be unavailable. Individuals of concern include hostile insiders or external adversaries who have breached or compromised the system and are using it to launch a denial-of-service attack.', 'vec_doc-14-nist-sp-800-53-p323-1247', 0, 250, 'v2.1.0', '7f31ee7b37e311c3303127de1bf6afaa19cc3321e9680338e8822a9be70650c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 296","subsection":"UNKNOWN","table_id":null,"page":323,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1247,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 296"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p323-1248', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 296', 323, 'Organizations can restrict the ability of individuals to connect and transmit arbitrary information on the transport medium (i.e., wired networks, wireless networks, spoofed Internet protocol packets). Organizations can also limit the ability of individuals to use excessive system resources. Protection against individuals having the ability to launch denial-of-service attacks may be implemented on specific systems or boundary devices that prohibit egress to potential target systems. Related Controls:  None. (2) DENIAL-OF-SERVICE PROTECTION | CAPACITY, BANDWIDTH, AND REDUNDANCY Manage capacity, bandwidth, or other redundancy to limit the effects of information flooding denial-of-service attacks. Discussion:  Managing capacity ensures that sufficient capacity is available to counter flooding attacks. Managing capacity includes establishing selected usage priorities, quotas, partitioning, or load balancing. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p323-1248', 0, 236, 'v2.1.0', '53b3cd984b7f6abbd2311417e4b46d77feb1dc162c92c42ac2a34d4b769abb34', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 296","subsection":"UNKNOWN","table_id":null,"page":323,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1248,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 296"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p323-1249', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 296', 323, '(3) DENIAL-OF-SERVICE PROTECTION | DETECTION AND MONITORING (a) Employ the following monitoring tools to detect indicators of denial-of-service attacks against, or launched from, the system: [Assignment: organization-defined monitoring tools]; and (b) Monitor the following system resources to determine if sufficient resources exist to prevent effective denial-of-service attacks: [Assignment: organization-defined system resources].', 'vec_doc-14-nist-sp-800-53-p323-1249', 0, 109, 'v2.1.0', '6dedd84ca823181f301d215b286c556d69b4bef70646821e8dce2c3a9da00642', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 296","subsection":"UNKNOWN","table_id":null,"page":323,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1249,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 296"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p324-1250', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 297', 324, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Organizations consider the utilization and capacity of system resources when managing risk associated with a denial of service due to malicious attacks. Denial-of-service attacks can originate from external or internal sources. System resources that are sensitive to denial of service include physical disk storage, memory, and CPU cycles. Techniques used to prevent denial-of-service attacks related to storage utilization and capacity include instituting disk quotas, configuring systems to automatically alert administrators when specific storage capacity thresholds are reached, using file compression technologies to maximize available storage space, and imposing separate partitions for system and user data. Related Controls:  CA-7, SI-4. References:  [SP 800-189].', 'vec_doc-14-nist-sp-800-53-p324-1250', 0, 220, 'v2.1.0', '5d84ff84855fcc95ba683a570f26704f58b608e41202d607dfff6bf75fe59894', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 297","subsection":"UNKNOWN","table_id":null,"page":324,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1250,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 297"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p324-1251', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 297', 324, 'SC-6 RESOURCE AVAILABILITY Control:  Protect the availability of resources by allocating [Assignment: organization-defined resources] by [Selection (one or more): priority; quota; [Assignment: organization-defined controls]]. Discussion:  Priority protection prevents lower-priority processes from delaying or interfering with the system that services higher-priority processes. Quotas prevent users or processes from obtaining more than predetermined amounts of resources. Related Controls:  SC-5. Control Enhancements:  None. References:  [OMB M-08-05], [DHS TIC]. SC-7  BOUNDARY PROTECTION Control: a. Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces within the system; b. Implement subnetworks for publicly accessible system components that are [Selection: physically; logically] separated from internal organizational networks; and c.', 'vec_doc-14-nist-sp-800-53-p324-1251', 0, 229, 'v2.1.0', 'e7d6d6e6dce6bd10854d5b6251cd5ffbb65b5b576502e2c62a33d7ad349f81d7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 297","subsection":"UNKNOWN","table_id":null,"page":324,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1251,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 297"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p324-1252', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 297', 324, 'Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture. Discussion:  Managed interfaces include gateways, routers, firewalls, guards, network-based malicious code analysis, virtualization systems, or encrypted tunnels implemented within a security architecture. Subnetworks that are physically or logically separated from internal networks are referred to as demilitarized zones or DMZs. Restricting or prohibiting interfaces within organizational systems includes restricting external web traffic to designated web servers within managed interfaces, prohibiting external traffic that appears to be spoofing internal addresses, and prohibiting internal traffic that appears to be spoofing external addresses. [SP 800-189] provides additional information on source address validation techniques to prevent ingress and egress of traffic with spoofed addresses.', 'vec_doc-14-nist-sp-800-53-p324-1252', 0, 250, 'v2.1.0', '5b13a2a2eee8e43b776fc464b171610c469d1bba4779d745ae14986094c66288', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 297","subsection":"UNKNOWN","table_id":null,"page":324,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1252,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 297"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p324-1253', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 297', 324, 'Commercial telecommunications services are provided by network components and consolidated management systems shared by customers. These services may also include third party-provided access lines and other service elements. Such services may represent sources of increased risk despite contract security provisions. Boundary protection may be implemented as a common control for all or part of an organizational network such that the boundary to be protected is greater than a system-specific boundary (i.e., an authorization boundary).', 'vec_doc-14-nist-sp-800-53-p324-1253', 0, 135, 'v2.1.0', 'f3acd5eb9160b4b83a848198ea5528a90d9815bcdfaf7f6c704532c92732db1c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 297","subsection":"UNKNOWN","table_id":null,"page":324,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1253,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 297"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p325-1254', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 298', 325, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  AC-4, AC-17, AC-18, AC-19, AC-20, AU-13, CA-3, CM-2, CM-4, CM-7, CM-10, CP- 8, CP-10, IR-4, MA-4, PE-3, PL-8, PM-12, SA-8, SA-17, SC-5, SC-26, SC-32, SC-35, SC-43. Control Enhancements: (1) BOUNDARY PROTECTION | PHYSICALLY SEPARATED SUBNETWORKS [Withdrawn: Incorporated into SC-7.] (2) BOUNDARY PROTECTION | PUBLIC ACCESS [Withdrawn: Incorporated into SC-7.] (3) BOUNDARY PROTECTION | ACCESS POINTS Limit the number of external network connections to the system. Discussion:  Limiting the number of external network connections facilitates monitoring of inbound and outbound communications traffic. The Trusted Internet Connection [DHS TIC] initiative is an example of a federal guideline that requires limits on the number of external network connections.', 'vec_doc-14-nist-sp-800-53-p325-1254', 0, 217, 'v2.1.0', '57377f17138708c95a7ff8380728777a178546bf0e6617ea15f14e65335da429', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 298","subsection":"UNKNOWN","table_id":null,"page":325,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1254,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 298"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p325-1255', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 298', 325, 'Limiting the number of external network connections to the system is important during transition periods from older to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Such transitions may require implementing the older and newer technologies simultaneously during the transition period and thus increase the number of access points to the system. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p325-1255', 0, 101, 'v2.1.0', '46219546588f4505a7a7efe64114c3f435e83b9c5d92700e7a63f9bf95bfa324', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 298","subsection":"UNKNOWN","table_id":null,"page":325,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1255,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 298"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p325-1256', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 298', 325, '(4) BOUNDARY PROTECTION | EXTERNAL TELECOMMUNICATIONS SERVICES (a) Implement a managed interface for each external telecommunication service; (b) Establish a traffic flow policy for each managed interface; (c) Protect the confidentiality and integrity of the information being transmitted across each interface; (d) Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need; (e) Review exceptions to the traffic flow policy [Assignment: organization-defined frequency] and remove exceptions that are no longer supported by an explicit mission or business need; (f) Prevent unauthorized exchange of control plane traffic with external networks; (g) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and (h) Filter unauthorized control plane traffic from external networks.', 'vec_doc-14-nist-sp-800-53-p325-1256', 0, 225, 'v2.1.0', '4e14b0d3831d3eb41a0d4b1896fed7d9486bb17be86b6d266de6e8c245cc6f2a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 298","subsection":"UNKNOWN","table_id":null,"page":325,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1256,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 298"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p325-1257', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 298', 325, 'Discussion:  External telecommunications services can provide data and/or voice communications services. Examples of control plane traffic include Border Gateway Protocol (BGP) routing, Domain Name System (DNS), and management protocols. See [SP 800-189] for additional information on the use of the resource public key infrastructure (RPKI) to protect BGP routes and detect unauthorized BGP announcements. Related Controls:  AC-3, SC-8, SC-20, SC-21, SC-22. (5) BOUNDARY PROTECTION | DENY BY DEFAULT —  ALLOW BY EXCEPTION Deny network communications traffic by default and allow network communications traffic by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]]. Discussion:  Denying by default and allowing by exception applies to inbound and outbound network communications traffic. A deny-all, permit-by-exception network communications traffic policy ensures that only those system connections that are essential and approved are', 'vec_doc-14-nist-sp-800-53-p325-1257', 0, 248, 'v2.1.0', '89572062efb09b43cfddefbe4105bd6ce3c68e9f47a5788e616b4c886ba2c37b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 298","subsection":"UNKNOWN","table_id":null,"page":325,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1257,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 298"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p326-1258', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 299', 326, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 allowed. Deny by default, allow by exception also applies to a system that is connected to an external system. Related Controls:  None. (6) BOUNDARY PROTECTION | RESPONSE TO RECOGNIZED FAILURES [Withdrawn: Incorporated into SC-7(18).] (7) BOUNDARY PROTECTION | SPLIT TUNNELING FOR REMOTE DEVICES Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is securely provisioned using [Assignment: organization-defined safeguards]. Discussion:  Split tunneling is the process of allowing a remote user or device to establish a non-remote connection with a system and simultaneously communicate via some other connection to a resource in an external network. This method of network access enables a user to access remote devices and simultaneously, access uncontrolled networks.', 'vec_doc-14-nist-sp-800-53-p326-1258', 0, 229, 'v2.1.0', '1dbb87c52cc18ae263b733600744c2ed95369178377f356d5d534b52ab1c5ec7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 299","subsection":"UNKNOWN","table_id":null,"page":326,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1258,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 299"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p326-1259', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 299', 326, 'Split tunneling might be desirable by remote users to communicate with local system resources, such as printers or file servers. However, split tunneling can facilitate unauthorized external connections, making the system vulnerable to attack and to exfiltration of organizational information. Split tunneling can be prevented by disabling configuration settings that allow such capability in remote devices and by preventing those configuration settings from being configurable by users. Prevention can also be achieved by the detection of split tunneling (or of configuration settings that allow split tunneling) in the remote device, and by prohibiting the connection if the remote device is using split tunneling. A virtual private network (VPN) can be used to securely provision a split tunnel. A securely provisioned VPN includes locking connectivity to exclusive, managed, and named environments, or to a specific set of pre- approved addresses, without user control. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p326-1259', 0, 250, 'v2.1.0', '55c3d2bb12a987a82d19a5fccd4d4c4fba9320105e8da098159545efe3d21477', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 299","subsection":"UNKNOWN","table_id":null,"page":326,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1259,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 299"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p326-1260', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 299', 326, '(8) BOUNDARY PROTECTION | ROUTE TRAFFIC TO AUTHENTICATED PROXY SERVERS Route [Assignment: organization-defined internal communications traffic] to [Assignment: organization-defined external networks] through authenticated proxy servers at managed interfaces. Discussion:  External networks are networks outside of organizational control. A proxy server is a server (i.e., system or application) that acts as an intermediary for clients requesting system resources from non-organizational or other organizational servers. System resources that may be requested include files, connections, web pages, or services. Client requests established through a connection to a proxy server are assessed to manage complexity and provide additional protection by limiting direct connectivity. Web content filtering devices are one of the most common proxy servers that provide access to the Internet.', 'vec_doc-14-nist-sp-800-53-p326-1260', 0, 222, 'v2.1.0', '33176f1f017fc360935956954dd19e6ded74d1fec661d995847167469923af5a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 299","subsection":"UNKNOWN","table_id":null,"page":326,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1260,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 299"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p326-1261', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 299', 326, 'Proxy servers can support the logging of Transmission Control Protocol sessions and the blocking of specific Uniform Resource Locators, Internet Protocol addresses, and domain names. Web proxies can be configured with organization-defined lists of authorized and unauthorized websites. Note that proxy servers may inhibit the use of virtual private networks (VPNs) and create the potential for “man-in-the-middle” attacks (depending on the implementation). Related Controls:  AC-3. (9) BOUNDARY PROTECTION | RESTRICT THREATENING OUTGOING COMMUNICATIONS TRAFFIC (a) Detect and deny outgoing communications traffic posing a threat to external systems; and (b) Audit the identity of internal users associated with denied communications. Discussion:  Detecting outgoing communications traffic from internal actions that may pose threats to external systems is known as extrusion detection. Extrusion detection is carried out within the system at managed interfaces. Extrusion detection includes the analysis of', 'vec_doc-14-nist-sp-800-53-p326-1261', 0, 252, 'v2.1.0', '8d222d2d52c7df22f2cd1105fea29a9f149e1eb19d288282730881c601f7666c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 299","subsection":"UNKNOWN","table_id":null,"page":326,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1261,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 299"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p327-1262', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 300', 327, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 incoming and outgoing communications traffic while searching for indications of internal threats to the security of external systems. Internal threats to external systems include traffic indicative of denial-of-service attacks, traffic with spoofed source addresses, and traffic that contains malicious code. Organizations have criteria to determine, update, and manage identified threats related to extrusion detection. Related Controls:  AU-2, AU-6, SC-5, SC-38, SC-44, SI-3, SI-4. (10) BOUNDARY PROTECTION | PREVENT EXFILTRATION (a) Prevent the exfiltration of information; and (b) Conduct exfiltration tests [Assignment: organization-defined frequency]. Discussion:  Prevention of exfiltration applies to both the intentional and unintentional exfiltration of information.', 'vec_doc-14-nist-sp-800-53-p327-1262', 0, 217, 'v2.1.0', '68d3eb60d228881cfe89babf604888341bd88c04be73581785feb1e749fcb0e8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 300","subsection":"UNKNOWN","table_id":null,"page":327,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1262,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 300"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p327-1263', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 300', 327, 'Techniques used to prevent the exfiltration of information from systems may be implemented at internal endpoints, external boundaries, and across managed interfaces and include adherence to protocol formats, monitoring for beaconing activity from systems, disconnecting external network interfaces except when explicitly needed, employing traffic profile analysis to detect deviations from the volume and types of traffic expected, call backs to command and control centers, conducting penetration testing, monitoring for steganography, disassembling and reassembling packet headers, and using data loss and data leakage prevention tools. Devices that enforce strict adherence to protocol formats include deep packet inspection firewalls and Extensible Markup Language (XML) gateways. The devices verify adherence to protocol formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices that operate at the network or transport layers.', 'vec_doc-14-nist-sp-800-53-p327-1263', 0, 248, 'v2.1.0', '734bd617aa62c00d5696083a3b69e4e7cdd6c99f515b191119b927dddc6be7d1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 300","subsection":"UNKNOWN","table_id":null,"page":327,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1263,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 300"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p327-1264', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 300', 327, 'The prevention of exfiltration is similar to data loss prevention or data leakage prevention and is closely associated with cross-domain solutions and system guards that enforce information flow requirements. Related Controls:  AC-2, CA-8, SI-3. (11) BOUNDARY PROTECTION | RESTRICT INCOMING COMMUNICATIONS TRAFFIC Only allow incoming communications from [Assignment: organization-defined authorized sources] to be routed to [Assignment: organization-defined authorized destinations]. Discussion:  General source address validation techniques are applied to restrict the use of illegal and unallocated source addresses as well as source addresses that should only be used within the system. The restriction of incoming communications traffic provides determinations that source and destination address pairs represent authorized or allowed communications.', 'vec_doc-14-nist-sp-800-53-p327-1264', 0, 214, 'v2.1.0', 'a81c03aa5b90dc70bf12e9804629a3c4e7750b4f9d121898524c27bf8eb6062b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 300","subsection":"UNKNOWN","table_id":null,"page":327,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1264,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 300"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p327-1265', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 300', 327, 'Determinations can be based on several factors, including the presence of such address pairs in the lists of authorized or allowed communications, the absence of such address pairs in lists of unauthorized or disallowed pairs, or meeting more general rules for authorized or allowed source and destination pairs. Strong authentication of network addresses is not possible without the use of explicit security protocols, and thus, addresses can often be spoofed. Further, identity-based incoming traffic restriction methods can be employed, including router access control lists and firewall rules. Related Controls:  AC-3. (12) BOUNDARY PROTECTION | HOST-BASED PROTECTION Implement [Assignment: organization-defined host-based boundary protection mechanisms] at [Assignment: organization-defined system components]. Discussion:  Host-based boundary protection mechanisms include host-based firewalls.', 'vec_doc-14-nist-sp-800-53-p327-1265', 0, 225, 'v2.1.0', '19a56c2939ba2cc7857a586c836782670a0d097f51e648c6a28c3e528b7beb3d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 300","subsection":"UNKNOWN","table_id":null,"page":327,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1265,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 300"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p327-1266', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 300', 327, 'System components that employ host-based boundary protection mechanisms include servers, workstations, notebook computers, and mobile devices. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p327-1266', 0, 42, 'v2.1.0', '4f50672fcecda7901f67e2235d2939b9c7c77ab4732c6fb64887fa91f72a86d9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 300","subsection":"UNKNOWN","table_id":null,"page":327,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1266,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 300"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p328-1267', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 301', 328, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (13) BOUNDARY PROTECTION | ISOLATION OF SECURITY TOOLS, MECHANISMS, AND SUPPORT COMPONENTS Isolate [Assignment: organization-defined information security tools, mechanisms, and support components] from other internal system components by implementing physically separate subnetworks with managed interfaces to other components of the system. Discussion:  Physically separate subnetworks with managed interfaces are useful in isolating computer network defenses from critical operational processing networks to prevent adversaries from discovering the analysis and forensics techniques employed by organizations. Related Controls:  SC-2, SC-3. (14) BOUNDARY PROTECTION | PROTECT AGAINST UNAUTHORIZED PHYSICAL CONNECTIONS Protect against unauthorized physical connections at [Assignment: organization-defined managed interfaces].', 'vec_doc-14-nist-sp-800-53-p328-1267', 0, 230, 'v2.1.0', 'dd395d9d3cbba735991abb26b1ddec68447110b77e73cff387bec33e84e18654', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 301","subsection":"UNKNOWN","table_id":null,"page":328,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1267,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 301"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p328-1268', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 301', 328, 'Discussion:  Systems that operate at different security categories or classification levels may share common physical and environmental controls, since the systems may share space within the same facilities. In practice, it is possible that these separate systems may share common equipment rooms, wiring closets, and cable distribution paths. Protection against unauthorized physical connections can be achieved by using clearly identified and physically separated cable trays, connection frames, and patch panels for each side of managed interfaces with physical access controls that enforce limited authorized access to these items. Related Controls:  PE-4, PE-19. (15) BOUNDARY PROTECTION | NETWORKED PRIVILEGED ACCESSES Route networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing. Discussion:  Privileged access provides greater accessibility to system functions, including security functions.', 'vec_doc-14-nist-sp-800-53-p328-1268', 0, 240, 'v2.1.0', '05d91c0328c1ab026d1cbdd67fa76cadc638044a46f8f64f4036628d8998d5c5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 301","subsection":"UNKNOWN","table_id":null,"page":328,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1268,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 301"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p328-1269', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 301', 328, 'Adversaries attempt to gain privileged access to systems through remote access to cause adverse mission or business impacts, such as by exfiltrating information or bringing down a critical system capability. Routing networked, privileged access requests through a dedicated, managed interface further restricts privileged access for increased access control and auditing. Related Controls:  AC-2, AC-3, AU-2, SI-4. (16) BOUNDARY PROTECTION | PREVENT DISCOVERY OF SYSTEM COMPONENTS Prevent the discovery of specific system components that represent a managed interface. Discussion:  Preventing the discovery of system components representing a managed interface helps protect network addresses of those components from discovery through common tools and techniques used to identify devices on networks. Network addresses are not available for discovery and require prior knowledge for access.', 'vec_doc-14-nist-sp-800-53-p328-1269', 0, 223, 'v2.1.0', '6cd29202267547ce630f5a7cc00dfe43e4a001bdf9a9ebc25d23f6b5aee9e099', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 301","subsection":"UNKNOWN","table_id":null,"page":328,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1269,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 301"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p328-1270', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 301', 328, 'Preventing the discovery of components and devices can be accomplished by not publishing network addresses, using network address translation, or not entering the addresses in domain name systems. Another prevention technique is to periodically change network addresses. Related Controls:  None. (17) BOUNDARY PROTECTION | AUTOMATED ENFORCEMENT OF PROTOCOL FORMATS Enforce adherence to protocol formats. Discussion:  System components that enforce protocol formats include deep packet inspection firewalls and XML gateways. The components verify adherence to protocol', 'vec_doc-14-nist-sp-800-53-p328-1270', 0, 142, 'v2.1.0', '88292d6aa3a83eef7721c9ab096489b25bd64a5152fbf4bf0706d722d1aeacca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 301","subsection":"UNKNOWN","table_id":null,"page":328,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1270,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 301"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p329-1271', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 302', 329, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices operating at the network or transport layers. Related Controls:  SC-4. (18) BOUNDARY PROTECTION | FAIL SECURE Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device. Discussion:  Fail secure is a condition achieved by employing mechanisms to ensure that in the event of operational failures of boundary protection devices at managed interfaces, systems do not enter into unsecure states where intended security properties no longer hold. Managed interfaces include routers, firewalls, and application gateways that reside on protected subnetworks (commonly referred to as demilitarized zones).', 'vec_doc-14-nist-sp-800-53-p329-1271', 0, 216, 'v2.1.0', '0fe80240ee7468390143192983eec6bde53f94b8be507db2d4e0f114bb4d9177', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 302","subsection":"UNKNOWN","table_id":null,"page":329,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1271,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 302"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p329-1272', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 302', 329, 'Failures of boundary protection devices cannot lead to or cause information external to the devices to enter the devices nor can failures permit unauthorized information releases. Related Controls:  CP-2, CP-12, SC-24. (19) BOUNDARY PROTECTION | BLOCK COMMUNICATION FROM NON-ORGANIZATIONALLY CONFIGURED HOSTS Block inbound and outbound communications traffic between [Assignment: organization- defined communication clients] that are independently configured by end users and external service providers. Discussion:  Communication clients independently configured by end users and external service providers include instant messaging clients and video conferencing software and applications. Traffic blocking does not apply to communication clients that are configured by organizations to perform authorized functions. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p329-1272', 0, 211, 'v2.1.0', '14f93017123955a3c08dc484f8d421eb37020f84038ebb65cd5d412b90a7f099', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 302","subsection":"UNKNOWN","table_id":null,"page":329,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1272,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 302"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p329-1273', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 302', 329, '(20) BOUNDARY PROTECTION | DYNAMIC ISOLATION AND SEGREGATION Provide the capability to dynamically isolate [Assignment: organization-defined system components] from other system components. Discussion:  The capability to dynamically isolate certain internal system components is useful when it is necessary to partition or separate system components of questionable origin from components that possess greater trustworthiness. Component isolation reduces the attack surface of organizational systems. Isolating selected system components can also limit the damage from successful attacks when such attacks occur. Related Controls:  None. (21) BOUNDARY PROTECTION | ISOLATION OF SYSTEM COMPONENTS Employ boundary protection mechanisms to isolate [Assignment: organization-defined system components] supporting [Assignment: organization-defined missions and/or business functions]. Discussion:  Organizations can isolate system components that perform different mission or business functions.', 'vec_doc-14-nist-sp-800-53-p329-1273', 0, 248, 'v2.1.0', '0d98ba68d4d9a60c3e9274728ec9f18b630cf1f65f6a5f4fd94207a36c319d1f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 302","subsection":"UNKNOWN","table_id":null,"page":329,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1273,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 302"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p329-1274', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 302', 329, 'Such isolation limits unauthorized information flows among system components and provides the opportunity to deploy greater levels of protection for selected system components. Isolating system components with boundary protection mechanisms provides the capability for increased protection of individual system components and to more effectively control information flows between those components. Isolating system components provides enhanced protection that limits the potential harm from hostile cyber- attacks and errors. The degree of isolation varies depending upon the mechanisms chosen. Boundary protection mechanisms include routers, gateways, and firewalls that separate system components into physically separate networks or subnetworks; cross-domain devices', 'vec_doc-14-nist-sp-800-53-p329-1274', 0, 193, 'v2.1.0', '1590f8516dab8b08a564183ec62aaf738cd7d098f616424e8dcf43c9643d7aed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 302","subsection":"UNKNOWN","table_id":null,"page":329,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1274,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 302"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p330-1275', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 303', 330, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 that separate subnetworks; virtualization techniques; and the encryption of information flows among system components using distinct encryption keys. Related Controls:  CA-9. (22) BOUNDARY PROTECTION | SEPARATE SUBNETS FOR CONNECTING TO DIFFERENT SECURITY DOMAINS Implement separate network addresses to connect to systems in different security domains. Discussion:  The decomposition of systems into subnetworks (i.e., subnets) helps to provide the appropriate level of protection for network connections to different security domains that contain information with different security categories or classification levels. Related Controls:  None. (23) BOUNDARY PROTECTION | DISABLE SENDER FEEDBACK ON PROTOCOL VALIDATION FAILURE Disable feedback to senders on protocol format validation failure.', 'vec_doc-14-nist-sp-800-53-p330-1275', 0, 222, 'v2.1.0', 'd13408dffdcbf23fb3c071b5b3d883232b0ac81172e17ba981cc470c8dd2c071', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 303","subsection":"UNKNOWN","table_id":null,"page":330,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1275,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 303"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p330-1276', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 303', 330, 'Discussion:  Disabling feedback to senders when there is a failure in protocol validation format prevents adversaries from obtaining information that would otherwise be unavailable. Related Controls:  None. (24) BOUNDARY PROTECTION | PERSONALLY IDENTIFIABLE INFORMATION For systems that process personally identifiable information: (a) Apply the following processing rules to data elements of personally identifiable information: [Assignment: organization-defined processing rules]; (b) Monitor for permitted processing at the external interfaces to the system and at key internal boundaries within the system; (c) Document each processing exception; and (d) Review and remove exceptions that are no longer supported. Discussion:  Managing the processing of personally identifiable information is an important aspect of protecting an individual’s privacy.', 'vec_doc-14-nist-sp-800-53-p330-1276', 0, 214, 'v2.1.0', '7785612a15b502149e27e15953ec2ea6bf2ab043dbf47dc90850f162d616ed0a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 303","subsection":"UNKNOWN","table_id":null,"page":330,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1276,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 303"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p330-1277', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 303', 330, 'Applying, monitoring for, and documenting exceptions to processing rules ensure that personally identifiable information is processed only in accordance with established privacy requirements. Related Controls:  PT-2, SI-15. (25) BOUNDARY PROTECTION | UNCLASSIFIED NATIONAL SECURITY SYSTEM CONNECTIONS Prohibit the direct connection of [Assignment: organization-defined unclassified national security system] to an external network without the use of [Assignment: organization- defined boundary protection device]. Discussion:  A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks, including the Internet. Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between unclassified national security systems and external networks. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p330-1277', 0, 233, 'v2.1.0', 'fbd6d9987f424252bde228519ed6f50285dbc0748c7f3a3dda9246eedc6eefe3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 303","subsection":"UNKNOWN","table_id":null,"page":330,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1277,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 303"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p330-1278', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 303', 330, '(26) BOUNDARY PROTECTION | CLASSIFIED NATIONAL SECURITY SYSTEM CONNECTIONS Prohibit the direct connection of a classified national security system to an external network without the use of [Assignment: organization-defined boundary protection device]. Discussion:  A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks,', 'vec_doc-14-nist-sp-800-53-p330-1278', 0, 109, 'v2.1.0', '54dc7e8ec3c0f595f33ac99905580fcdcf93f4180194177077154a1557bd4c84', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 303","subsection":"UNKNOWN","table_id":null,"page":330,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1278,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 303"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p331-1279', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 304', 331, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 including the Internet. Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between classified national security systems and external networks. In addition, approved boundary protection devices (typically managed interface or cross-domain systems) provide information flow enforcement from systems to external networks. Related Controls:  None. (27) BOUNDARY PROTECTION | UNCLASSIFIED NON-NATIONAL SECURITY SYSTEM CONNECTIONS Prohibit the direct connection of [Assignment: organization-defined unclassified non- national security system] to an external network without the use of [Assignment: organization-defined boundary protection device]. Discussion:  A direct connection is a dedicated physical or virtual connection between two or more systems. Organizations typically do not have complete control over external networks, including the Internet.', 'vec_doc-14-nist-sp-800-53-p331-1279', 0, 252, 'v2.1.0', '41f583dc84c308e5cf9a14b73dc1370ee31730e0bc20c3d32298e0c1bfbd0a86', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 304","subsection":"UNKNOWN","table_id":null,"page":331,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1279,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 304"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p331-1280', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 304', 331, 'Boundary protection devices (e.g., firewalls, gateways, and routers) mediate communications and information flows between unclassified non-national security systems and external networks. Related Controls:  None. (28) BOUNDARY PROTECTION | CONNECTIONS TO PUBLIC NETWORKS Prohibit the direct connection of [Assignment: organization-defined system] to a public network. Discussion:  A direct connection is a dedicated physical or virtual connection between two or more systems. A public network is a network accessible to the public, including the Internet and organizational extranets with public access. Related Controls:  None. (29) BOUNDARY PROTECTION | SEPARATE SUBNETS TO ISOLATE FUNCTIONS Implement [Selection: physically; logically] separate subnetworks to isolate the following critical system components and functions: [Assignment: organization-defined critical system components and functions].', 'vec_doc-14-nist-sp-800-53-p331-1280', 0, 226, 'v2.1.0', '37a96a9286e5f63c7c2b70560f26b5459909f5cb8d8c157926dafa429fe8fd9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 304","subsection":"UNKNOWN","table_id":null,"page":331,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1280,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 304"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p331-1281', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 304', 331, 'Discussion:  Separating critical system components and functions from other noncritical system components and functions through separate subnetworks may be necessary to reduce susceptibility to a catastrophic or debilitating breach or compromise that results in system failure. For example, physically separating the command and control function from the in-flight entertainment function through separate subnetworks in a commercial aircraft provides an increased level of assurance in the trustworthiness of critical system functions. Related Controls:  None. References:  [OMB A-130], [FIPS 199], [SP 800-37], [SP 800-41], [SP 800-77], [SP 800-189]. SC-8 TRANSMISSION CONFIDENTIALITY AND INTEGRITY Control:  Protect the [Selection (one or more): confidentiality; integrity] of transmitted information.', 'vec_doc-14-nist-sp-800-53-p331-1281', 0, 201, 'v2.1.0', '5198083a38841d1bd1504483788005ee9c24addfd003add2713b8aa26ed58392', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 304","subsection":"UNKNOWN","table_id":null,"page":331,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1281,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 304"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p331-1282', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 304', 331, 'Discussion:  Protecting the confidentiality and integrity of transmitted information applies to internal and external networks as well as any system components that can transmit information, including servers, notebook computers, desktop computers, mobile devices, printers, copiers, scanners, facsimile machines, and radios. Unprotected communication paths are exposed to the possibility of interception and modification. Protecting the confidentiality and integrity of information can be accomplished by physical or logical means. Physical protection can be achieved by using protected distribution systems. A protected distribution system is a wireline or fiber-optics telecommunications system that includes terminals and adequate electromagnetic,', 'vec_doc-14-nist-sp-800-53-p331-1282', 0, 188, 'v2.1.0', '27d7d0614f98bd0f7212af7e7805c89065360bbaf75e28f2c278f87cf6e9e444', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 304","subsection":"UNKNOWN","table_id":null,"page":331,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1282,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 304"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p332-1283', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 305', 332, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 acoustical, electrical, and physical controls to permit its use for the unencrypted transmission of classified information. Logical protection can be achieved by employing encryption techniques. Organizations that rely on commercial providers who offer transmission services as commodity services rather than as fully dedicated services may find it difficult to obtain the necessary assurances regarding the implementation of needed controls for transmission confidentiality and integrity. In such situations, organizations determine what types of confidentiality or integrity services are available in standard, commercial telecommunications service packages. If it is not feasible to obtain the necessary controls and assurances of control effectiveness through appropriate contracting vehicles, organizations can implement appropriate compensating controls.', 'vec_doc-14-nist-sp-800-53-p332-1283', 0, 238, 'v2.1.0', 'a5ab6e2d982c6af7fd8286d9eb7d9e495b6f734bc84e5b4e1168a718d1348910', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 305","subsection":"UNKNOWN","table_id":null,"page":332,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1283,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 305"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p332-1284', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 305', 332, 'Related Controls:  AC-17, AC-18, AU-10, IA-3, IA-8, IA-9, MA-4, PE-4, SA-4, SA-8, SC-7, SC-16, SC- 20, SC-23, SC-28. Control Enhancements: (1) TRANSMISSION CONFIDENTIALITY AND INTEGRITY | CRYPTOGRAPHIC PROTECTION Implement cryptographic mechanisms to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission. Discussion:  Encryption protects information from unauthorized disclosure and modification during transmission. Cryptographic mechanisms that protect the confidentiality and integrity of information during transmission include TLS and IPSec. Cryptographic mechanisms used to protect information integrity include cryptographic hash functions that have applications in digital signatures, checksums, and message authentication codes. Related Controls:  SC-12,  SC-13.', 'vec_doc-14-nist-sp-800-53-p332-1284', 0, 211, 'v2.1.0', '2f766ec5e5ed94ca7d6630a2e50e73346ffb67481a0662bebf07ef9c6a4ea774', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 305","subsection":"UNKNOWN","table_id":null,"page":332,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1284,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 305"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p332-1285', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 305', 332, '(2) TRANSMISSION CONFIDENTIALITY AND INTEGRITY | PRE- AND POST-TRANSMISSION HANDLING Maintain the [Selection (one or more): confidentiality; integrity] of information during preparation for transmission and during reception. Discussion:  Information can be unintentionally or maliciously disclosed or modified during preparation for transmission or during reception, including during aggregation, at protocol transformation points, and during packing and unpacking. Such unauthorized disclosures or modifications compromise the confidentiality or integrity of the information. Related Controls:  None. (3) TRANSMISSION CONFIDENTIALITY AND INTEGRITY | CRYPTOGRAPHIC PROTECTION FOR MESSAGE EXTERNALS Implement cryptographic mechanisms to protect message externals unless otherwise protected by [Assignment: organization-defined alternative physical controls]. Discussion:  Cryptographic protection for message externals addresses protection from the unauthorized disclosure of information.', 'vec_doc-14-nist-sp-800-53-p332-1285', 0, 247, 'v2.1.0', 'd75427057e961f6c3b70f3b2c586fce065d0e72893b9a457c987af0ef437656b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 305","subsection":"UNKNOWN","table_id":null,"page":332,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1285,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 305"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p332-1286', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 305', 332, 'Message externals include message headers and routing information. Cryptographic protection prevents the exploitation of message externals and applies to internal and external networks or links that may be visible to individuals who are not authorized users. Header and routing information is sometimes transmitted in clear text (i.e., unencrypted) because the information is not identified by organizations as having significant value or because encrypting the information can result in lower network performance or higher costs. Alternative physical controls include protected distribution systems. Related Controls:  SC-12, SC-13. (4) TRANSMISSION CONFIDENTIALITY AND INTEGRITY | CONCEAL OR RANDOMIZE COMMUNICATIONS', 'vec_doc-14-nist-sp-800-53-p332-1286', 0, 180, 'v2.1.0', '4ecdcebf9928175c2b28f380628f933341bf8f062c2865a48ea5b361f859783d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 305","subsection":"UNKNOWN","table_id":null,"page":332,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1286,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 305"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p333-1287', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 306', 333, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Implement cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by [Assignment: organization-defined alternative physical controls]. Discussion:  Concealing or randomizing communication patterns addresses protection from unauthorized disclosure of information. Communication patterns include frequency, periods, predictability, and amount. Changes to communications patterns can reveal information with intelligence value, especially when combined with other available information related to the mission and business functions of the organization. Concealing or randomizing communications prevents the derivation of intelligence based on communications patterns and applies to both internal and external networks or links that may be visible to individuals who are not authorized users.', 'vec_doc-14-nist-sp-800-53-p333-1287', 0, 231, 'v2.1.0', '7f8eada86a533ecc3ec8e3871b1e8958e63b8c547ee1890e81eb35c417a2dc3f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 306","subsection":"UNKNOWN","table_id":null,"page":333,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1287,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 306"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p333-1288', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 306', 333, 'Encrypting the links and transmitting in continuous, fixed, or random patterns prevents the derivation of intelligence from the system communications patterns. Alternative physical controls include protected distribution systems. Related Controls:  SC-12, SC-13. (5) TRANSMISSION CONFIDENTIALITY AND INTEGRITY | PROTECTED DISTRIBUTION SYSTEM Implement [Assignment: organization-defined protected distribution system] to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission. Discussion:  The purpose of a protected distribution system is to deter, detect, and/or make difficult physical access to the communication lines that carry national security information. Related Controls:  None. References:  [FIPS 140-3], [FIPS 197], [SP 800-52], [SP 800-77], [SP 800-81-2], [SP 800-113], [SP 800-177], [IR 8023].', 'vec_doc-14-nist-sp-800-53-p333-1288', 0, 220, 'v2.1.0', 'd13e0ebe0ebc7ddf0f9365a85dd5472346b25bdb5154df562ac944189c81a5cb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 306","subsection":"UNKNOWN","table_id":null,"page":333,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1288,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 306"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p333-1289', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 306', 333, 'SC-9 TRANSMISSION CONFIDENTIALITY [Withdrawn: Incorporated into SC-8.] SC-10 NETWORK DISCONNECT Control:  Terminate the network connection associated with a communications session at the end of the session or after [Assignment: organization-defined time period] of inactivity. Discussion:  Network disconnect applies to internal and external networks. Terminating network connections associated with specific communications sessions includes de-allocating TCP/IP address or port pairs at the operating system level and de-allocating the networking assignments at the application level if multiple application sessions are using a single operating system-level network connection. Periods of inactivity may be established by organizations and include time periods by type of network access or for specific network accesses. Related Controls:  AC-17, SC-23. Control Enhancements:  None. References:  None. SC-11 TRUSTED PATH Control: a.', 'vec_doc-14-nist-sp-800-53-p333-1289', 0, 234, 'v2.1.0', 'd9f509fbd3f88124d5fb49ad9e75f16698de104607e76895220be99fcebac241', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 306","subsection":"UNKNOWN","table_id":null,"page":333,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1289,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 306"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p333-1290', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 306', 333, 'Provide a [Selection: physically; logically] isolated trusted communications path for communications between the user and the trusted components of the system; and', 'vec_doc-14-nist-sp-800-53-p333-1290', 0, 41, 'v2.1.0', 'db74969c299cd9524edfedac56489a8b408354a2b6278c77c049fe808b1d965b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 306","subsection":"UNKNOWN","table_id":null,"page":333,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1290,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 306"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p334-1291', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 307', 334, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Permit users to invoke the trusted communications path for communications between the user and the following security functions of the system, including at a minimum, authentication and re-authentication: [Assignment: organization-defined security functions]. Discussion:  Trusted paths are mechanisms by which users can communicate (using input devices such as keyboards) directly with the security functions of systems with the requisite assurance to support security policies. Trusted path mechanisms can only be activated by users or the security functions of organizational systems. User responses that occur via trusted paths are protected from modification by and disclosure to untrusted applications. Organizations employ trusted paths for trustworthy, high-assurance connections between security functions of systems and users, including during system logons.', 'vec_doc-14-nist-sp-800-53-p334-1291', 0, 241, 'v2.1.0', '1284a7b01431bc6749704444bd91ebe5fc12aa42d41c43202a5d65b763ee4074', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 307","subsection":"UNKNOWN","table_id":null,"page":334,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1291,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 307"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p334-1292', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 307', 334, 'The original implementations of trusted paths employed an out-of-band signal to initiate the path, such as using the <BREAK> key, which does not transmit characters that can be spoofed. In later implementations, a key combination that could not be hijacked was used (e.g., the <CTRL> + <ALT> + <DEL> keys). Such key combinations, however, are platform-specific and may not provide a trusted path implementation in every case. The enforcement of trusted communications paths is provided by a specific implementation that meets the reference monitor concept. Related Controls:  AC-16, AC-25, SC-12, SC-23. Control Enhancements: (1) TRUSTED PATH | IRREFUTABLE COMMUNICATIONS PATH (a) Provide a trusted communications path that is irrefutably distinguishable from other communications paths; and (b) Initiate the trusted communications path for communications between the [Assignment: organization-defined security functions] of the system and the user.', 'vec_doc-14-nist-sp-800-53-p334-1292', 0, 238, 'v2.1.0', '5318c3bf92ae14cbdb5e81311f06c7ed1a91fe43e75671e795a1a7bc00aee67d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 307","subsection":"UNKNOWN","table_id":null,"page":334,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1292,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 307"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p334-1293', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 307', 334, 'Discussion:  An irrefutable communications path permits the system to initiate a trusted path, which necessitates that the user can unmistakably recognize the source of the communication as a trusted system component. For example, the trusted path may appear in an area of the display that other applications cannot access or be based on the presence of an identifier that cannot be spoofed. Related Controls:  None. References:  [OMB A-130]. SC-12 CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT Control:  Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements: [Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction]. Discussion:  Cryptographic key management and establishment can be performed using manual procedures or automated mechanisms with supporting manual procedures.', 'vec_doc-14-nist-sp-800-53-p334-1293', 0, 233, 'v2.1.0', '28365650293a1bd37ef3b85faaae8f1de624752f1aab322af15e84273e46941a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 307","subsection":"UNKNOWN","table_id":null,"page":334,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1293,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 307"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p334-1294', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 307', 334, 'Organizations define key management requirements in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and specify appropriate options, parameters, and levels. Organizations manage trust stores to ensure that only approved trust anchors are part of such trust stores. This includes certificates with visibility external to organizational systems and certificates related to the internal operations of systems. [ NIST CMVP] and [NIST CAVP] provide additional information on validated cryptographic modules and algorithms that can be used in cryptographic key management and establishment. Related Controls:  AC-17, AU-9, AU-10, CM-3, IA-3, IA-7, SA-4, SA-8, SA-9, SC-8, SC-11, SC-12, SC- 13, SC-17, SC-20, SC-37, SC-40, SI-3, SI-7.', 'vec_doc-14-nist-sp-800-53-p334-1294', 0, 198, 'v2.1.0', '2288074fbe97e209b7590bb134c35eb89f61ee7c4f344d8eceb0dc7a2907a6d4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 307","subsection":"UNKNOWN","table_id":null,"page":334,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1294,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 307"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p335-1295', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 308', 335, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | AVAILABILITY Maintain availability of information in the event of the loss of cryptographic keys by users. Discussion:  Escrowing of encryption keys is a common practice for ensuring availability in the event of key loss. A forgotten passphrase is an example of losing a cryptographic key. Related Controls:  None. (2) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | SYMMETRIC KEYS Produce, control, and distribute symmetric cryptographic keys using [Selection: NIST FIPS- validated; NSA-approved] key management technology and processes. Discussion:  [SP 800-56A], [SP 800-56B], and [SP 800-56C] provide guidance on cryptographic key establishment schemes and key derivation methods. [SP 800-57-1], [SP 800-57-2], and [SP 800-57-3] provide guidance on cryptographic key management. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p335-1295', 0, 244, 'v2.1.0', 'b651ba57cf323f49dc5a37c88947b45f84312706972a51d5b702c21aae2240b6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 308","subsection":"UNKNOWN","table_id":null,"page":335,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1295,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 308"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p335-1296', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 308', 335, '(3) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | ASYMMETRIC KEYS Produce, control, and distribute asymmetric cryptographic keys using [Selection: NSA- approved key management technology and processes; prepositioned keying material; DoD-approved or DoD-issued Medium Assurance PKI certificates; DoD-approved or DoD- issued Medium Hardware Assurance PKI certificates and hardware security tokens that protect the user’s private key; certificates issued in accordance with organization-defined requirements]. Discussion:  [SP 800-56A], [SP 800-56B], and [SP 800-56C] provide guidance on cryptographic key establishment schemes and key derivation methods. [SP 800-57-1], [SP 800-57-2], and [SP 800-57-3] provide guidance on cryptographic key management. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p335-1296', 0, 195, 'v2.1.0', '2be14fa96a0afa819c293276593efb99721215cb7d810cc0f2627ce7458b20b3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 308","subsection":"UNKNOWN","table_id":null,"page":335,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1296,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 308"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p335-1297', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 308', 335, '(4) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PKI CERTIFICATES [Withdrawn: Incorporated into SC-12(3).] (5) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PKI CERTIFICATES / HARDWARE TOKENS [Withdrawn: Incorporated into SC-12(3).] (6) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PHYSICAL CONTROL OF KEYS Maintain physical control of cryptographic keys when stored information is encrypted by external service providers. Discussion:  For organizations that use external service providers (e.g., cloud service or data center providers), physical control of cryptographic keys provides additional assurance that information stored by such external providers is not subject to unauthorized disclosure or modification. Related Controls:  None. References:  [FIPS 140-3], [SP 800-56A], [SP 800-56B], [SP 800-56C], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-63-3], [IR 7956], [IR 7966]. SC-13  CRYPTOGRAPHIC PROTECTION Control: a.', 'vec_doc-14-nist-sp-800-53-p335-1297', 0, 237, 'v2.1.0', '50064889b1c91e853321df2e2fa270197666cf815166ae289a0b88a0d1ed505f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 308","subsection":"UNKNOWN","table_id":null,"page":335,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1297,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 308"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p335-1298', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 308', 335, 'Determine the [Assignment: organization-defined cryptographic uses]; and', 'vec_doc-14-nist-sp-800-53-p335-1298', 0, 18, 'v2.1.0', '786bdfbd4faa5d3ad305701650f9b37d84d2e3f1e6054c26622e78b3727c7497', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 308","subsection":"UNKNOWN","table_id":null,"page":335,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1298,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 308"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p336-1299', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 309', 336, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Implement the following types of cryptography required for each specified cryptographic use: [Assignment: organization-defined types of cryptography for each specified cryptographic use]. Discussion:  Cryptography can be employed to support a variety of security solutions, including the protection of classified information and controlled unclassified information, the provision and implementation of digital signatures, and the enforcement of information separation when authorized individuals have the necessary clearances but lack the necessary formal access approvals. Cryptography can also be used to support random number and hash generation. Generally applicable cryptographic standards include FIPS-validated cryptography and NSA- approved cryptography. For example, organizations that need to protect classified information may specify the use of NSA-approved cryptography.', 'vec_doc-14-nist-sp-800-53-p336-1299', 0, 245, 'v2.1.0', 'b22dcc4361f3cc690723d5f50b53f1e07466217a080c3026fb39875fb591fb99', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 309","subsection":"UNKNOWN","table_id":null,"page":336,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1299,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 309"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p336-1300', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 309', 336, 'Organizations that need to provision and implement digital signatures may specify the use of FIPS-validated cryptography. Cryptography is implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  AC-2, AC-3, AC-7, AC-17, AC-18, AC-19, AU-9, AU-10, CM-11, CP-9, IA-3, IA-5, IA-7, MA-4, MP-2, MP-4, MP-5, SA-4, SA-8, SA-9, SC-8, SC-12, SC-20, SC-23, SC-28, SC-40, SI-3, SI- 7. Control Enhancements:  None. (1) CRYPTOGRAPHIC PROTECTION | FIPS-VALIDATED CRYPTOGRAPHY [Withdrawn: Incorporated into SC-13.] (2) CRYPTOGRAPHIC PROTECTION | NSA-APPROVED CRYPTOGRAPHY [Withdrawn: Incorporated into SC-13.] (3) CRYPTOGRAPHIC PROTECTION | INDIVIDUALS WITHOUT FORMAL ACCESS APPROVALS [Withdrawn: Incorporated into SC-13.] (4) CRYPTOGRAPHIC PROTECTION | DIGITAL SIGNATURES [Withdrawn: Incorporated into SC-13.] References:  [FIPS 140-3].', 'vec_doc-14-nist-sp-800-53-p336-1300', 0, 228, 'v2.1.0', '07424bc64ad64b62d4190453c6edf0ccfa8f1f8dab8593958c7120c8ed243fb1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 309","subsection":"UNKNOWN","table_id":null,"page":336,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1300,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 309"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p336-1301', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 309', 336, 'SC-14 PUBLIC ACCESS PROTECTIONS [Withdrawn: Incorporated into AC-2, AC-3, AC-5, AC-6, SI-3, SI-4, SI-5, SI-7, and SI-10.] SC-15 COLLABORATIVE COMPUTING DEVICES AND APPLICATIONS Control: a. Prohibit remote activation of collaborative computing devices and applications with the following exceptions: [Assignment: organization-defined exceptions where remote activation is to be allowed]; and b. Provide an explicit indication of use to users physically present at the devices. Discussion:  Collaborative computing devices and applications include remote meeting devices and applications, networked white boards, cameras, and microphones. The explicit indication of use includes signals to users when collaborative computing devices and applications are activated. Related Controls:  AC-21, SC-42. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p336-1301', 0, 205, 'v2.1.0', 'ed1fdb85f896e567ed4e2876109853292c8926e9efd170a4933c8be9cb540f60', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 309","subsection":"UNKNOWN","table_id":null,"page":336,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1301,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 309"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p337-1302', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 310', 337, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) COLLABORATIVE COMPUTING DEVICES | PHYSICAL OR LOGICAL DISCONNECT Provide [Selection (one or more): physical; logical] disconnect of collaborative computing devices in a manner that supports ease of use. Discussion:  Failing to disconnect from collaborative computing devices can result in subsequent compromises of organizational information. Providing easy methods to disconnect from such devices after a collaborative computing session ensures that participants carry out the disconnect activity without having to go through complex and tedious procedures. Disconnect from collaborative computing devices can be manual or automatic. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p337-1302', 0, 189, 'v2.1.0', '9203b23ae7f99224fef057a738266960192d7691ad43085f5534fa3917338920', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 310","subsection":"UNKNOWN","table_id":null,"page":337,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1302,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 310"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p337-1303', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 310', 337, '(2) COLLABORATIVE COMPUTING DEVICES | BLOCKING INBOUND AND OUTBOUND COMMUNICATIONS TRAFFIC [Withdrawn: Incorporated into SC-7.] (3) COLLABORATIVE COMPUTING DEVICES | DISABLING AND REMOVAL IN SECURE WORK AREAS Disable or remove collaborative computing devices and applications from [Assignment: organization-defined systems or system components] in [Assignment: organization-defined secure work areas]. Discussion:  Failing to disable or remove collaborative computing devices and applications from systems or system components can result in compromises of information, including eavesdropping on conversations. A Sensitive Compartmented Information Facility (SCIF) is an example of a secure work area. Related Controls:  None. (4) COLLABORATIVE COMPUTING DEVICES | EXPLICITLY INDICATE CURRENT PARTICIPANTS Provide an explicit indication of current participants in [Assignment: organization-defined online meetings and teleconferences].', 'vec_doc-14-nist-sp-800-53-p337-1303', 0, 234, 'v2.1.0', '0122ad8f75537253ce272441da1be89a6caf639e9a068f47a6efb0d476e77e7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 310","subsection":"UNKNOWN","table_id":null,"page":337,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1303,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 310"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p337-1304', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 310', 337, 'Discussion:  Explicitly indicating current participants prevents unauthorized individuals from participating in collaborative computing sessions without the explicit knowledge of other participants. Related Controls:  None. References:  None. SC-16 TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES Control:  Associate [Assignment: organization-defined security and privacy attributes] with information exchanged between systems and between system components. Discussion:  Security and privacy attributes can be explicitly or implicitly associated with the information contained in organizational systems or system components. Attributes are abstractions that represent the basic properties or characteristics of an entity with respect to protecting information or the management of personally identifiable information. Attributes are typically associated with internal data structures, including records, buffers, and files within the system.', 'vec_doc-14-nist-sp-800-53-p337-1304', 0, 236, 'v2.1.0', '77d1155637b189ccc6f1029f88126a37cb0e0dc0ef1aaba73c19316ab721ff39', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 310","subsection":"UNKNOWN","table_id":null,"page":337,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1304,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 310"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p337-1305', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 310', 337, 'Security and privacy attributes are used to implement access control and information flow control policies; reflect special dissemination, management, or distribution instructions, including permitted uses of personally identifiable information; or support other aspects of the information security and privacy policies. Privacy attributes may be used independently or in conjunction with security attributes. Related Controls:  AC-3, AC-4, AC-16. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p337-1305', 0, 118, 'v2.1.0', '7739b70b65e3b2971bc49855f80209f9dbada8c131fb746397bfd38219c574a3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 310","subsection":"UNKNOWN","table_id":null,"page":337,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1305,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 310"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p338-1306', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 311', 338, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | INTEGRITY VERIFICATION Verify the integrity of transmitted security and privacy attributes. Discussion:  Part of verifying the integrity of transmitted information is ensuring that security and privacy attributes that are associated with such information have not been modified in an unauthorized manner. Unauthorized modification of security or privacy attributes can result in a loss of integrity for transmitted information. Related Controls:  AU-10, SC-8. (2) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | ANTI-SPOOFING MECHANISMS Implement anti-spoofing mechanisms to prevent adversaries from falsifying the security attributes indicating the successful application of the security process.', 'vec_doc-14-nist-sp-800-53-p338-1306', 0, 212, 'v2.1.0', '28ec03c2ec0c70a334b77843360ad711c6aade0873aefff04b314512b389bd26', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 311","subsection":"UNKNOWN","table_id":null,"page":338,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1306,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 311"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p338-1307', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 311', 338, 'Discussion:  Some attack vectors operate by altering the security attributes of an information system to intentionally and maliciously implement an insufficient level of security within the system. The alteration of attributes leads organizations to believe that a greater number of security functions are in place and operational than have actually been implemented. Related Controls:  SI-3, SI-4, SI-7. (3) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | CRYPTOGRAPHIC BINDING Implement [Assignment: organization-defined mechanisms or techniques] to bind security and privacy attributes to transmitted information. Discussion:  Cryptographic mechanisms and techniques can provide strong security and privacy attribute binding to transmitted information to help ensure the integrity of such information. Related Controls:  AC-16, SC-12, SC-13. References:  [OMB A-130]. SC-17 PUBLIC KEY INFRASTRUCTURE CERTIFICATES Control: a.', 'vec_doc-14-nist-sp-800-53-p338-1307', 0, 233, 'v2.1.0', '389654ef4f028caf3c4b77fa48526dd4aa10981108d72260346202e8bc40812d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 311","subsection":"UNKNOWN","table_id":null,"page":338,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1307,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 311"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p338-1308', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 311', 338, 'Issue public key certificates under an [Assignment: organization-defined certificate policy] or obtain public key certificates from an approved service provider; and b. Include only approved trust anchors in trust stores or certificate stores managed by the organization. Discussion:  Public key infrastructure (PKI) certificates are certificates with visibility external to organizational systems and certificates related to the internal operations of systems, such as application-specific time services. In cryptographic systems with a hierarchical structure, a trust anchor is an authoritative source (i.e., a certificate authority) for which trust is assumed and not derived. A root certificate for a PKI system is an example of a trust anchor. A trust store or certificate store maintains a list of trusted root certificates. Related Controls:  AU-10, IA-5, SC-12. Control Enhancements:  None. References:  [SP 800-32], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-63-3].', 'vec_doc-14-nist-sp-800-53-p338-1308', 0, 246, 'v2.1.0', '62ecb3f4e792430984fd840af6149ccc258c1e4e29804f2bf32bb2b1bacb6c01', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 311","subsection":"UNKNOWN","table_id":null,"page":338,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1308,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 311"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p338-1309', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 311', 338, 'SC-18 MOBILE CODE Control: a. Define acceptable and unacceptable mobile code and mobile code technologies; and b. Authorize, monitor, and control the use of mobile code within the system.', 'vec_doc-14-nist-sp-800-53-p338-1309', 0, 47, 'v2.1.0', '9e6ed8b0a3557e0626b9319d2c6eb290365db460820998c25aaf8dd5037b15f1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 311","subsection":"UNKNOWN","table_id":null,"page":338,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1309,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 311"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p339-1310', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 312', 339, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Mobile code includes any program, application, or content that can be transmitted across a network (e.g., embedded in an email, document, or website) and executed on a remote system. Decisions regarding the use of mobile code within organizational systems are based on the potential for the code to cause damage to the systems if used maliciously. Mobile code technologies include Java applets, JavaScript, HTML5, WebGL, and VBScript. Usage restrictions and implementation guidelines apply to both the selection and use of mobile code installed on servers and mobile code downloaded and executed on individual workstations and devices, including notebook computers and smart phones.', 'vec_doc-14-nist-sp-800-53-p339-1310', 0, 197, 'v2.1.0', '8ff6554b6bb239d29a094fc124a9b5878c8390eac6872d2af47b0cc3b88b3efd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 312","subsection":"UNKNOWN","table_id":null,"page":339,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1310,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 312"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p339-1311', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 312', 339, 'Mobile code policy and procedures address specific actions taken to prevent the development, acquisition, and introduction of unacceptable mobile code within organizational systems, including requiring mobile code to be digitally signed by a trusted source. Related Controls:  AU-2, AU-12, CM-2, CM-6, SI-3. Control Enhancements: (1) MOBILE CODE | IDENTIFY UNACCEPTABLE CODE AND TAKE CORRECTIVE ACTIONS Identify [Assignment: organization-defined unacceptable mobile code] and take [Assignment: organization-defined corrective actions]. Discussion:  Corrective actions when unacceptable mobile code is detected include blocking, quarantine, or alerting administrators. Blocking includes preventing the transmission of word processing files with embedded macros when such macros have been determined to be unacceptable mobile code. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p339-1311', 0, 214, 'v2.1.0', 'd1c35af87a602baa997a763b776e733dace27c213d4302f380e1e532ab68ca6b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 312","subsection":"UNKNOWN","table_id":null,"page":339,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1311,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 312"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p339-1312', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 312', 339, '(2) MOBILE CODE | ACQUISITION, DEVELOPMENT, AND USE Verify that the acquisition, development, and use of mobile code to be deployed in the system meets [Assignment: organization-defined mobile code requirements]. Discussion:  None. Related Controls:  None. (3) MOBILE CODE | PREVENT DOWNLOADING AND EXECUTION Prevent the download and execution of [Assignment: organization-defined unacceptable mobile code]. Discussion:  None. Related Controls:  None. (4) MOBILE CODE | PREVENT AUTOMATIC EXECUTION Prevent the automatic execution of mobile code in [Assignment: organization-defined software applications] and enforce [Assignment: organization-defined actions] prior to executing the code. Discussion:  Actions enforced before executing mobile code include prompting users prior to opening email attachments or clicking on web links.', 'vec_doc-14-nist-sp-800-53-p339-1312', 0, 208, 'v2.1.0', 'a47a8cc6e704d928320912008b4c966783ecd5222363ea76b9112caeebdc2e2e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 312","subsection":"UNKNOWN","table_id":null,"page":339,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1312,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 312"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p339-1313', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 312', 339, 'Preventing the automatic execution of mobile code includes disabling auto-execute features on system components that employ portable storage devices, such as compact discs, digital versatile discs, and universal serial bus devices. Related Controls:  None. (5) MOBILE CODE | ALLOW EXECUTION ONLY IN CONFINED ENVIRONMENTS Allow execution of permitted mobile code only in confined virtual machine environments.', 'vec_doc-14-nist-sp-800-53-p339-1313', 0, 102, 'v2.1.0', '384f4e8db1da9b90693877cf22c9f70a06bdc015840fcd8823720b7474c3f13f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 312","subsection":"UNKNOWN","table_id":null,"page":339,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1313,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 312"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p340-1314', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 313', 340, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Permitting the execution of mobile code only in confined virtual machine environments helps prevent the introduction of malicious code into other systems and system components. Related Controls:  SC-44, SI-7. References:  [SP 800-28]. SC-19 VOICE OVER INTERNET PROTOCOL [Withdrawn: Technology-specific; addressed as any other technology or protocol.] SC-20 SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) Control: a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and b.', 'vec_doc-14-nist-sp-800-53-p340-1314', 0, 188, 'v2.1.0', '9d8f61735916187686d68da3ccc93ec9c622208587acca896bd047befa70ae4f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 313","subsection":"UNKNOWN","table_id":null,"page":340,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1314,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 313"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p340-1315', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 313', 340, 'Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace. Discussion:  Providing authoritative source information enables external clients, including remote Internet clients, to obtain origin authentication and integrity verification assurances for the host/service name to network address resolution information obtained through the service. Systems that provide name and address resolution services include domain name system (DNS) servers. Additional artifacts include DNS Security Extensions (DNSSEC) digital signatures and cryptographic keys. Authoritative data includes DNS resource records. The means for indicating the security status of child zones include the use of delegation signer resource records in the DNS.', 'vec_doc-14-nist-sp-800-53-p340-1315', 0, 232, 'v2.1.0', '3de3c926317c6e0dc78c02cf73956e941a719e22cb0027819e307144c4aba762', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 313","subsection":"UNKNOWN","table_id":null,"page":340,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1315,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 313"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p340-1316', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 313', 340, 'Systems that use technologies other than the DNS to map between host and service names and network addresses provide other means to assure the authenticity and integrity of response data. Related Controls:  AU-10, SC-8, SC-12, SC-13, SC-21, SC-22. Control Enhancements: (1) SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) | CHILD SUBSPACES [Withdrawn: Incorporated into SC-20.] (2) SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) | DATA ORIGIN AND INTEGRITY Provide data origin and integrity protection artifacts for internal name/address resolution queries. Discussion:  None. Related Controls:  None. References:  [FIPS 140-3], [FIPS 186-4], [SP 800-81-2]. SC-21 SECURE NAME/ADDRESS RESOLUTION SERVICE (RECURSIVE OR CACHING RESOLVER) Control:  Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.', 'vec_doc-14-nist-sp-800-53-p340-1316', 0, 236, 'v2.1.0', 'e55c44616de933964ab40221eeaa0e0592d143e69b7970cd64dda6aa7533c070', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 313","subsection":"UNKNOWN","table_id":null,"page":340,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1316,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 313"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p340-1317', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 313', 340, 'Discussion:  Each client of name resolution services either performs this validation on its own or has authenticated channels to trusted validation providers. Systems that provide name and', 'vec_doc-14-nist-sp-800-53-p340-1317', 0, 47, 'v2.1.0', '6d38535a31532a63173ba1178b17332b32c5665f4f1ea52872605d4b336aca40', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 313","subsection":"UNKNOWN","table_id":null,"page":340,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1317,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 313"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p341-1318', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 314', 341, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 address resolution services for local clients include recursive resolving or caching domain name system (DNS) servers. DNS client resolvers either perform validation of DNSSEC signatures, or clients use authenticated channels to recursive resolvers that perform such validations. Systems that use technologies other than the DNS to map between host and service names and network addresses provide some other means to enable clients to verify the authenticity and integrity of response data. Related Controls:  SC-20, SC-22. Control Enhancements:  None. (1) SECURE NAME/ADDRESS RESOLUTION SERVICE (RECURSIVE OR CACHING RESOLVER) | DATA ORIGIN AND INTEGRITY [Withdrawn: Incorporated into SC-21.] References:  [SP 800-81-2].', 'vec_doc-14-nist-sp-800-53-p341-1318', 0, 204, 'v2.1.0', 'e90bea7f8289d629fac19e8dc452e9bbc328ac90accaf8f6034d169937aba510', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 314","subsection":"UNKNOWN","table_id":null,"page":341,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1318,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 314"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p341-1319', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 314', 341, 'SC-22 ARCHITECTURE AND PROVISIONING FOR NAME/ADDRESS RESOLUTION SERVICE Control:  Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation. Discussion:  Systems that provide name and address resolution services include domain name system (DNS) servers. To eliminate single points of failure in systems and enhance redundancy, organizations employ at least two authoritative domain name system servers— one configured as the primary server and the other configured as the secondary server. Additionally, organizations typically deploy the servers in two geographically separated network subnetworks (i.e., not located in the same physical facility). For role separation, DNS servers with internal roles only process name and address resolution requests from within organizations (i.e., from internal clients).', 'vec_doc-14-nist-sp-800-53-p341-1319', 0, 230, 'v2.1.0', '125c80febb2d19393cee287d6e4d72fc285d4f33573828cb83042e1872bf1bef', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 314","subsection":"UNKNOWN","table_id":null,"page":341,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1319,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 314"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p341-1320', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 314', 341, 'DNS servers with external roles only process name and address resolution information requests from clients external to organizations (i.e., on external networks, including the Internet). Organizations specify clients that can access authoritative DNS servers in certain roles (e.g., by address ranges and explicit lists). Related Controls:  SC-2, SC-20, SC-21, SC-24. Control Enhancements:  None. References:  [SP 800-81-2]. SC-23 SESSION AUTHENTICITY Control:  Protect the authenticity of communications sessions. Discussion:  Protecting session authenticity addresses communications protection at the session level, not at the packet level. Such protection establishes grounds for confidence at both ends of communications sessions in the ongoing identities of other parties and the validity of transmitted information. Authenticity protection includes protecting against “man-in-the-middle” attacks, session hijacking, and the insertion of false information into sessions.', 'vec_doc-14-nist-sp-800-53-p341-1320', 0, 244, 'v2.1.0', '7bfccc4f1092a89c1711637dc865653bb932463920eb477232191a79f5db2906', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 314","subsection":"UNKNOWN","table_id":null,"page":341,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1320,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 314"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p341-1321', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 314', 341, 'Related Controls:  AU-10, SC-8, SC-10, SC-11. Control Enhancements: (1) SESSION AUTHENTICITY | INVALIDATE SESSION IDENTIFIERS AT LOGOUT Invalidate session identifiers upon user logout or other session termination. Discussion:  Invalidating session identifiers at logout curtails the ability of adversaries to capture and continue to employ previously valid session IDs.', 'vec_doc-14-nist-sp-800-53-p341-1321', 0, 93, 'v2.1.0', '35b14616b9c62aa2f6e0d947148e5338a5f51c3ba1196c178380045ad7efcb9d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 314","subsection":"UNKNOWN","table_id":null,"page":341,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1321,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 314"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p342-1322', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 315', 342, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. (2) SESSION AUTHENTICITY | USER-INITIATED LOGOUTS AND MESSAGE DISPLAYS [Withdrawn: Incorporated into AC-12(1).] (3) SESSION AUTHENTICITY | UNIQUE SYSTEM-GENERATED SESSION IDENTIFIERS Generate a unique session identifier for each session with [Assignment: organization- defined randomness requirements] and recognize only session identifiers that are system- generated. Discussion:  Generating unique session identifiers curtails the ability of adversaries to reuse previously valid session IDs. Employing the concept of randomness in the generation of unique session identifiers protects against brute-force attacks to determine future session identifiers. Related Controls:  AC-10, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p342-1322', 0, 204, 'v2.1.0', '4adfef86cd919754d122d9099fcc44cee73ed28448ad8804a9173198a30d6130', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 315","subsection":"UNKNOWN","table_id":null,"page":342,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1322,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 315"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p342-1323', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 315', 342, '(4) SESSION AUTHENTICITY | UNIQUE SESSION IDENTIFIERS WITH RANDOMIZATION [Withdrawn: Incorporated into SC-23(3).] (5) SESSION AUTHENTICITY | ALLOWED CERTIFICATE AUTHORITIES Only allow the use of [Assignment: organization-defined certificate authorities] for verification of the establishment of protected sessions. Discussion:  Reliance on certificate authorities for the establishment of secure sessions includes the use of Transport Layer Security (TLS) certificates. These certificates, after verification by their respective certificate authorities, facilitate the establishment of protected sessions between web clients and web servers. Related Controls:  SC-12, SC-13. References:  [SP 800-52], [SP 800-77], [SP 800-95], [SP 800-113].', 'vec_doc-14-nist-sp-800-53-p342-1323', 0, 185, 'v2.1.0', '2364240b7a4194eff5f8990c3433fe93bc9163271b246078bf0eddd349c4d799', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 315","subsection":"UNKNOWN","table_id":null,"page":342,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1323,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 315"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p342-1324', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 315', 342, 'SC-24 FAIL IN KNOWN STATE Control:   Fail to a [Assignment: organization-defined known system state] for the following failures on the indicated components while preserving [Assignment: organization-defined system state information] in failure: [Assignment: list of organization-defined types of system failures on organization-defined system components]. Discussion:  Failure in a known state addresses security concerns in accordance with the mission and business needs of organizations. Failure in a known state prevents the loss of confidentiality, integrity, or availability of information in the event of failures of organizational systems or system components. Failure in a known safe state helps to prevent systems from failing to a state that may cause injury to individuals or destruction to property. Preserving system state information facilitates system restart and return to the operational mode with less disruption of mission and business processes.', 'vec_doc-14-nist-sp-800-53-p342-1324', 0, 242, 'v2.1.0', '0310996638c27d257a4a3c82515d6fd7c213dac56fe1b516ba1156f694b206f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 315","subsection":"UNKNOWN","table_id":null,"page":342,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1324,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 315"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p342-1325', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 315', 342, 'Related Controls:  CP-2, CP-4, CP-10, CP-12, SA-8, SC-7, SC-22, SI-13. Control Enhancements:  None. References:  None. SC-25 THIN NODES Control:  Employ minimal functionality and information storage on the following system components: [Assignment: organization-defined system components].', 'vec_doc-14-nist-sp-800-53-p342-1325', 0, 72, 'v2.1.0', '72433c2ba71236f965b546765a56f46d98d7583e2dc2016e0c0d8864a8f6de01', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 315","subsection":"UNKNOWN","table_id":null,"page":342,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1325,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 315"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p343-1326', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 316', 343, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The deployment of system components with minimal functionality reduces the need to secure every endpoint and may reduce the exposure of information, systems, and services to attacks. Reduced or minimal functionality includes diskless nodes and thin client technologies. Related Controls:  SC-30, SC-44. Control Enhancements:  None. References:  None. SC-26 DECOYS Control:  Include components within organizational systems specifically designed to be the target of malicious attacks for detecting, deflecting, and analyzing such attacks. Discussion:  Decoys (i.e., honeypots, honeynets, or deception nets) are established to attract adversaries and deflect attacks away from the operational systems that support organizational mission and business functions. Use of decoys requires some supporting isolation measures to ensure that any deflected malicious code does not infect organizational systems.', 'vec_doc-14-nist-sp-800-53-p343-1326', 0, 252, 'v2.1.0', 'd37b5574e9a539e31f8967fbc3fee37b0d0d71044b41f28d96d620aabccb9254', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 316","subsection":"UNKNOWN","table_id":null,"page":343,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1326,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 316"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p343-1327', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 316', 343, 'Depending on the specific usage of the decoy, consultation with the Office of the General Counsel before deployment may be needed. Related Controls:  RA-5, SC-7, SC-30, SC-35, SC-44, SI-3, SI-4. Control Enhancements:  None. (1) DECOYS | DETECTION OF MALICIOUS CODE [Withdrawn: Incorporated into SC-35.] References:  None. SC-27 PLATFORM-INDEPENDENT APPLICATIONS Control:  Include within organizational systems the following platform independent applications: [Assignment: organization-defined platform-independent applications]. Discussion:  Platforms are combinations of hardware, firmware, and software components used to execute software applications. Platforms include operating systems, the underlying computer architectures, or both. Platform-independent applications are applications with the capability to execute on multiple platforms. Such applications promote portability and reconstitution on different platforms.', 'vec_doc-14-nist-sp-800-53-p343-1327', 0, 232, 'v2.1.0', '706335dde4715b283d2f2f0264a871921540377cc8666b7be8161def0865c55e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 316","subsection":"UNKNOWN","table_id":null,"page":343,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1327,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 316"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p343-1328', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 316', 343, 'Application portability and the ability to reconstitute on different platforms increase the availability of mission-essential functions within organizations in situations where systems with specific operating systems are under attack. Related Controls:  SC-29. Control Enhancements:  None. References:  None. SC-28 PROTECTION OF INFORMATION AT REST Control:  Protect the [Selection (one or more): confidentiality; integrity] of the following information at rest: [Assignment: organization-defined information at rest]. Discussion:  Information at rest refers to the state of information when it is not in process or in transit and is located on system components. Such components include internal or external hard disk drives, storage area network devices, or databases. However, the focus of protecting information at rest is not on the type of storage device or frequency of access but rather on the state of the information. Information at rest addresses the confidentiality and integrity of', 'vec_doc-14-nist-sp-800-53-p343-1328', 0, 249, 'v2.1.0', '409f2b8e7f4813072b0d2f6fea1532b836f2e484b954ad28fd37058bb75471bc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 316","subsection":"UNKNOWN","table_id":null,"page":343,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1328,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 316"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p344-1329', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 317', 344, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 information and covers user information and system information. System-related information that requires protection includes configurations or rule sets for firewalls, intrusion detection and prevention systems, filtering routers, and authentication information. Organizations may employ different mechanisms to achieve confidentiality and integrity protections, including the use of cryptographic mechanisms and file share scanning. Integrity protection can be achieved, for example, by implementing write-once-read-many (WORM) technologies. When adequate protection of information at rest cannot otherwise be achieved, organizations may employ other controls, including frequent scanning to identify malicious code at rest and secure offline storage in lieu of online storage.', 'vec_doc-14-nist-sp-800-53-p344-1329', 0, 218, 'v2.1.0', 'b18ee63b7b0f7ba6223278177fb5d88dd1333d8e4274352ceebb1eab49a3dab8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 317","subsection":"UNKNOWN","table_id":null,"page":344,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1329,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 317"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p344-1330', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 317', 344, 'Related Controls:  AC-3, AC-4, AC-6, AC-19, CA-7, CM-3, CM-5, CM-6, CP-9, MP-4, MP-5, PE-3, SC- 8, SC-12, SC-13, SC-34, SI-3, SI-7, SI-16. Control Enhancements: (1) PROTECTION OF INFORMATION AT REST | CRYPTOGRAPHIC PROTECTION Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on [Assignment: organization-defined system components or media]: [Assignment: organization-defined information]. Discussion:  The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of organizational information. The strength of mechanism is commensurate with the security category or classification of the information. Organizations have the flexibility to encrypt information on system components or media or encrypt data structures, including files, records, or fields. Related Controls:  AC-19, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p344-1330', 0, 229, 'v2.1.0', '0bd0621c0d35332be016d1ab62d578ffb5c557ac52e2e53569ac2cfd351cae24', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 317","subsection":"UNKNOWN","table_id":null,"page":344,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1330,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 317"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p344-1331', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 317', 344, '(2) PROTECTION OF INFORMATION AT REST | OFFLINE STORAGE Remove the following information from online storage and store offline in a secure location: [Assignment: organization-defined information]. Discussion:  Removing organizational information from online storage to offline storage eliminates the possibility of individuals gaining unauthorized access to the information through a network. Therefore, organizations may choose to move information to offline storage in lieu of protecting such information in online storage. Related Controls:  None. (3) PROTECTION OF INFORMATION AT REST | CRYPTOGRAPHIC KEYS Provide protected storage for cryptographic keys [Selection: [Assignment: organization- defined safeguards]; hardware-protected key store]. Discussion:  A Trusted Platform Module (TPM) is an example of a hardware-protected data store that can be used to protect cryptographic keys. Related Controls:  SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p344-1331', 0, 231, 'v2.1.0', '660848e6bdbcba7bb0fbd6c297a191a06d686eeebbd4e3d19d05ec7c782c78c4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 317","subsection":"UNKNOWN","table_id":null,"page":344,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1331,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 317"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p344-1332', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 317', 344, 'References:  [OMB A-130], [SP 800-56A], [SP 800-56B], [SP 800-56C], [SP 800-57-1], [SP 800-57- 2], [SP 800-57-3], [SP 800-111], [SP 800-124]. SC-29 HETEROGENEITY Control:  Employ a diverse set of information technologies for the following system components in the implementation of the system: [Assignment: organization-defined system components]. Discussion:  Increasing the diversity of information technologies within organizational systems reduces the impact of potential exploitations or compromises of specific technologies. Such diversity protects against common mode failures, including those failures induced by supply chain attacks. Diversity in information technologies also reduces the likelihood that the means', 'vec_doc-14-nist-sp-800-53-p344-1332', 0, 181, 'v2.1.0', 'e0c03e02719b66368b95096da472465ca3b3f382f0979dd0b8d2fd0b4eb864c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 317","subsection":"UNKNOWN","table_id":null,"page":344,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1332,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 317"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p345-1333', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 318', 345, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 adversaries use to compromise one system component will be effective against other system components, thus further increasing the adversary work factor to successfully complete planned attacks. An increase in diversity may add complexity and management overhead that could ultimately lead to mistakes and unauthorized configurations. Related Controls:  AU-9, PL-8, SC-27, SC-30, SR-3. Control Enhancements: (1) HETEROGENEITY | VIRTUALIZATION TECHNIQUES Employ virtualization techniques to support the deployment of a diversity of operating systems and applications that are changed [Assignment: organization-defined frequency]. Discussion:  While frequent changes to operating systems and applications can pose significant configuration management challenges, the changes can result in an increased work factor for adversaries to conduct successful attacks.', 'vec_doc-14-nist-sp-800-53-p345-1333', 0, 238, 'v2.1.0', 'a808de686c5fcccd7ab1c63935c4dc0599546252735da8f5d7fe957c7fbf1319', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 318","subsection":"UNKNOWN","table_id":null,"page":345,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1333,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 318"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p345-1334', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 318', 345, 'Changing virtual operating systems or applications, as opposed to changing actual operating systems or applications, provides virtual changes that impede attacker success while reducing configuration management efforts. Virtualization techniques can assist in isolating untrustworthy software or software of dubious provenance into confined execution environments. Related Controls:  None. References:  None. SC-30 CONCEALMENT AND MISDIRECTION Control:  Employ the following concealment and misdirection techniques for [Assignment: organization-defined systems] at [Assignment: organization-defined time periods] to confuse and mislead adversaries: [Assignment: organization-defined concealment and misdirection techniques]. Discussion:  Concealment and misdirection techniques can significantly reduce the targeting capabilities of adversaries (i.e., window of opportunity and available attack surface) to initiate and complete attacks.', 'vec_doc-14-nist-sp-800-53-p345-1334', 0, 235, 'v2.1.0', '4d199b779721d57a8cd4adbc9bbde0248bb21650e607f8e4250be392b26812aa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 318","subsection":"UNKNOWN","table_id":null,"page":345,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1334,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 318"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p345-1335', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 318', 345, 'For example, virtualization techniques provide organizations with the ability to disguise systems, potentially reducing the likelihood of successful attacks without the cost of having multiple platforms. The increased use of concealment and misdirection techniques and methods— including randomness, uncertainty, and virtualization— may sufficiently confuse and mislead adversaries and subsequently increase the risk of discovery and/or exposing tradecraft. Concealment and misdirection techniques may provide additional time to perform core mission and business functions. The implementation of concealment and misdirection techniques may add to the complexity and management overhead required for the system. Related Controls:  AC-6, SC-25, SC-26, SC-29, SC-44, SI-14.', 'vec_doc-14-nist-sp-800-53-p345-1335', 0, 193, 'v2.1.0', '7ce339516efdaea0a591bae70ceb9e5236ae099c726117887676cdeb2146fea2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 318","subsection":"UNKNOWN","table_id":null,"page":345,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1335,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 318"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p345-1336', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 318', 345, 'Control Enhancements: (1) CONCEALMENT AND MISDIRECTION | VIRTUALIZATION TECHNIQUES [Withdrawn: Incorporated into SC-29(1).] (2) CONCEALMENT AND MISDIRECTION | RANDOMNESS Employ [Assignment: organization-defined techniques] to introduce randomness into organizational operations and assets. Discussion:  Randomness introduces increased levels of uncertainty for adversaries regarding the actions that organizations take to defend their systems against attacks. Such actions may impede the ability of adversaries to correctly target information resources of organizations that support critical missions or business functions. Uncertainty may also cause adversaries to hesitate before initiating or continuing attacks. Misdirection techniques that involve', 'vec_doc-14-nist-sp-800-53-p345-1336', 0, 188, 'v2.1.0', '40c108d50d75c5bd5003c96d34b8c20a3e5f6e3cb5c0727494d0d2cfc7c59fd5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 318","subsection":"UNKNOWN","table_id":null,"page":345,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1336,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 318"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p346-1337', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 319', 346, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 randomness include performing certain routine actions at different times of day, employing different information technologies, using different suppliers, and rotating roles and responsibilities of organizational personnel. Related Controls:  None. (3) CONCEALMENT AND MISDIRECTION | CHANGE PROCESSING AND STORAGE LOCATIONS Change the location of [Assignment: organization-defined processing and/or storage] [Selection: [Assignment: organization-defined time frequency]; at random time intervals]]. Discussion:  Adversaries target critical mission and business functions and the systems that support those mission and business functions while also trying to minimize the exposure of their existence and tradecraft.', 'vec_doc-14-nist-sp-800-53-p346-1337', 0, 202, 'v2.1.0', '50a2f164ff57598354289ed27846bcbcbc5bd88f876559317bb52a9e4079b57f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 319","subsection":"UNKNOWN","table_id":null,"page":346,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1337,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 319"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p346-1338', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 319', 346, 'The static, homogeneous, and deterministic nature of organizational systems targeted by adversaries make such systems more susceptible to attacks with less adversary cost and effort to be successful. Changing processing and storage locations (also referred to as moving target defense) addresses the advanced persistent threat using techniques such as virtualization, distributed processing, and replication. This enables organizations to relocate the system components (i.e., processing, storage) that support critical mission and business functions. Changing the locations of processing activities and/or storage sites introduces a degree of uncertainty into the targeting activities of adversaries. The targeting uncertainty increases the work factor of adversaries and makes compromises or breaches of the organizational systems more difficult and time-consuming.', 'vec_doc-14-nist-sp-800-53-p346-1338', 0, 217, 'v2.1.0', 'c50ee873624ab57e342fbab13763d467d876185524c4d727d6b63879692bf904', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 319","subsection":"UNKNOWN","table_id":null,"page":346,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1338,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 319"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p346-1339', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 319', 346, 'It also increases the chances that adversaries may inadvertently disclose certain aspects of their tradecraft while attempting to locate critical organizational resources. Related Controls:  None. (4) CONCEALMENT AND MISDIRECTION | MISLEADING INFORMATION Employ realistic, but misleading information in [Assignment: organization-defined system components] about its security state or posture. Discussion:  Employing misleading information is intended to confuse potential adversaries regarding the nature and extent of controls deployed by organizations. Thus, adversaries may employ incorrect and ineffective attack techniques. One technique for misleading adversaries is for organizations to place misleading information regarding the specific controls deployed in external systems that are known to be targeted by adversaries. Another technique is the use of deception nets that mimic actual aspects of organizational systems but use, for example, out-of-date software configurations.', 'vec_doc-14-nist-sp-800-53-p346-1339', 0, 247, 'v2.1.0', '1ca1cb0c6df75fc5c835f3c2a2f6aba53a6abeac7892534584673387d9b42c62', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 319","subsection":"UNKNOWN","table_id":null,"page":346,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1339,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 319"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p346-1340', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 319', 346, 'Related Controls:  None. (5) CONCEALMENT AND MISDIRECTION | CONCEALMENT OF SYSTEM COMPONENTS Employ the following techniques to hide or conceal [Assignment: organization-defined system components]: [Assignment: organization-defined techniques]. Discussion:  By hiding, disguising, or concealing critical system components, organizations may be able to decrease the probability that adversaries target and successfully compromise those assets. Potential means to hide, disguise, or conceal system components include the configuration of routers or the use of encryption or virtualization techniques. Related Controls:  None. References:  None. SC-31 COVERT CHANNEL ANALYSIS Control:', 'vec_doc-14-nist-sp-800-53-p346-1340', 0, 171, 'v2.1.0', '4b3e7782c1f0d0f42ace125d956cf1df281459170e3774f4f4488a8589c40873', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 319","subsection":"UNKNOWN","table_id":null,"page":346,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1340,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 319"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p347-1341', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 320', 347, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Perform a covert channel analysis to identify those aspects of communications within the system that are potential avenues for covert [Selection (one or more): storage; timing] channels; and b. Estimate the maximum bandwidth of those channels. Discussion:  Developers are in the best position to identify potential areas within systems that might lead to covert channels. Covert channel analysis is a meaningful activity when there is the potential for unauthorized information flows across security domains, such as in the case of systems that contain export-controlled information and have connections to external networks (i.e., networks that are not controlled by organizations). Covert channel analysis is also useful for multilevel secure systems, multiple security level systems, and cross-domain systems. Related Controls:  AC-3, AC-4, SA-8, SI-11.', 'vec_doc-14-nist-sp-800-53-p347-1341', 0, 238, 'v2.1.0', '59bc21c43aaf222726b254f58b5ea951caefd73daa149393759ee8212b56c967', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 320","subsection":"UNKNOWN","table_id":null,"page":347,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1341,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 320"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p347-1342', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 320', 347, 'Control Enhancements: (1) COVERT CHANNEL ANALYSIS | TEST COVERT CHANNELS FOR EXPLOITABILITY Test a subset of the identified covert channels to determine the channels that are exploitable. Discussion:  None. Related Controls:  None. (2) COVERT CHANNEL ANALYSIS | MAXIMUM BANDWIDTH Reduce the maximum bandwidth for identified covert [Selection (one or more): storage; timing] channels to [Assignment: organization-defined values]. Discussion:  The complete elimination of covert channels, especially covert timing channels, is usually not possible without significant performance impacts. Related Controls:  None. (3) COVERT CHANNEL ANALYSIS | MEASURE BANDWIDTH IN OPERATIONAL ENVIRONMENTS Measure the bandwidth of [Assignment: organization-defined subset of identified covert channels] in the operational environment of the system.', 'vec_doc-14-nist-sp-800-53-p347-1342', 0, 208, 'v2.1.0', '8c55db0bc6398aa61819d4ad563732f0146b6d977581d950727d7473c1874370', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 320","subsection":"UNKNOWN","table_id":null,"page":347,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1342,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 320"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p347-1343', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 320', 347, 'Discussion:  Measuring covert channel bandwidth in specified operational environments helps organizations determine how much information can be covertly leaked before such leakage adversely affects mission or business functions. Covert channel bandwidth may be significantly different when measured in settings that are independent of the specific environments of operation, including laboratories or system development environments. Related Controls:  None. References:  None. SC-32 SYSTEM PARTITIONING Control:  Partition the system into [Assignment: organization-defined system components] residing in separate [Selection: physical; logical] domains or environments based on [Assignment: organization-defined circumstances for physical or logical separation of components]. Discussion:  System partitioning is part of a defense-in-depth protection strategy. Organizations determine the degree of physical separation of system components.', 'vec_doc-14-nist-sp-800-53-p347-1343', 0, 235, 'v2.1.0', 'fab1ea32b2eab25cc27e82f14d72de9b8c8ef9cece6320bafcd8ec0176e4e29e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 320","subsection":"UNKNOWN","table_id":null,"page":347,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1343,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 320"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p347-1344', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 320', 347, 'Physical separation options include physically distinct components in separate racks in the same room, critical components in separate rooms, and geographical separation of critical components. Security categorization can guide the selection of candidates for domain partitioning. Managed interfaces restrict or prohibit network access and information flow among partitioned system components. Related Controls:  AC-4, AC-6, SA-8, SC-2, SC-3, SC-7, SC-36.', 'vec_doc-14-nist-sp-800-53-p347-1344', 0, 114, 'v2.1.0', '6100a52cdc29428a0278d3cb82c9b4563796f2c06cc18554a6b0281d4c963b7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 320","subsection":"UNKNOWN","table_id":null,"page":347,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1344,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 320"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p348-1345', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 321', 348, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Control Enhancements: (1) SYSTEM PARTITIONING | SEPARATE PHYSICAL DOMAINS FOR PRIVILEGED FUNCTIONS Partition privileged functions into separate physical domains. Discussion:  Privileged functions that operate in a single physical domain may represent a single point of failure if that domain becomes compromised or experiences a denial of service. Related Controls:  None. References:  [FIPS 199], [IR 8179]. SC-33 TRANSMISSION PREPARATION INTEGRITY [Withdrawn: Incorporated into SC-8.] SC-34 NON-MODIFIABLE EXECUTABLE PROGRAMS Control:  For [Assignment: organization-defined system components], load and execute: a. The operating environment from hardware-enforced, read-only media; and b. The following applications from hardware-enforced, read-only media: [Assignment: organization-defined applications].', 'vec_doc-14-nist-sp-800-53-p348-1345', 0, 225, 'v2.1.0', '7cf6cea625f3436e93bb8837f52f82d8ec5b8588daf2da3f97a50494251e7564', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 321","subsection":"UNKNOWN","table_id":null,"page":348,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1345,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 321"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p348-1346', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 321', 348, 'Discussion:  The operating environment for a system contains the code that hosts applications, including operating systems, executives, or virtual machine monitors (i.e., hypervisors). It can also include certain applications that run directly on hardware platforms. Hardware-enforced, read-only media include Compact Disc-Recordable (CD-R) and Digital Versatile Disc-Recordable (DVD-R) disk drives as well as one-time, programmable, read-only memory. The use of non- modifiable storage ensures the integrity of software from the point of creation of the read-only image. The use of reprogrammable, read-only memory can be accepted as read-only media provided that integrity can be adequately protected from the point of initial writing to the insertion of the memory into the system, and there are reliable hardware protections against reprogramming the memory while installed in organizational systems. Related Controls:  AC-3, SI-7, SI-14.', 'vec_doc-14-nist-sp-800-53-p348-1346', 0, 236, 'v2.1.0', 'e5b7b4e3dc21070b4729e8e8d8fa72c01c70aedfa066c7cc113ec135f616da21', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 321","subsection":"UNKNOWN","table_id":null,"page":348,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1346,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 321"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p348-1347', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 321', 348, 'Control Enhancements: (1) NON-MODIFIABLE EXECUTABLE PROGRAMS | NO WRITABLE STORAGE Employ [Assignment: organization-defined system components] with no writeable storage that is persistent across component restart or power on/off. Discussion:  Disallowing writeable storage eliminates the possibility of malicious code insertion via persistent, writeable storage within the designated system components. The restriction applies to fixed and removable storage, with the latter being addressed either directly or as specific restrictions imposed through access controls for mobile devices. Related Controls:  AC-19, MP-7. (2) NON-MODIFIABLE EXECUTABLE PROGRAMS | INTEGRITY PROTECTION ON READ-ONLY MEDIA Protect the integrity of information prior to storage on read-only media and control the media after such information has been recorded onto the media.', 'vec_doc-14-nist-sp-800-53-p348-1347', 0, 213, 'v2.1.0', 'ef537f35532e9beace7d4073bb81410b6e7c88f9f4f017b615762192283e171a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 321","subsection":"UNKNOWN","table_id":null,"page":348,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1347,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 321"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p348-1348', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 321', 348, 'Discussion:  Controls prevent the substitution of media into systems or the reprogramming of programmable read-only media prior to installation into the systems. Integrity protection controls include a combination of prevention, detection, and response. Related Controls:  CM-3, CM-5, CM-9, MP-2, MP-4, MP-5, SC-28, SI-3.', 'vec_doc-14-nist-sp-800-53-p348-1348', 0, 81, 'v2.1.0', '6e63ac6851064a5c2cd669c81d27f1579dceb8471dc84bc4d16334b315e1c303', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 321","subsection":"UNKNOWN","table_id":null,"page":348,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1348,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 321"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p349-1349', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 322', 349, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (3) NON-MODIFIABLE EXECUTABLE PROGRAMS | HARDWARE-BASED PROTECTION [Withdrawn: Moved to SC-51.] SC-35 EXTERNAL MALICIOUS CODE IDENTIFICATION Control:  Include system components that proactively seek to identify network-based malicious code or malicious websites. Discussion:  External malicious code identification differs from decoys in SC-26 in that the components actively probe networks, including the Internet, in search of malicious code contained on external websites. Like decoys, the use of external malicious code identification techniques requires some supporting isolation measures to ensure that any malicious code discovered during the search and subsequently executed does not infect organizational systems. Virtualization is a common technique for achieving such isolation. Related Controls:  SC-7, SC-26, SC-44, SI-3, SI-4. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p349-1349', 0, 245, 'v2.1.0', '90a115dc768c87678e374e9eb6527edf414a2cba85de99950c715e5bca99bcf5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 322","subsection":"UNKNOWN","table_id":null,"page":349,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1349,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 322"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p349-1350', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 322', 349, 'SC-36 DISTRIBUTED PROCESSING AND STORAGE Control:  Distribute the following processing and storage components across multiple [Selection: physical locations; logical domains]: [Assignment: organization-defined processing and storage components]. Discussion:  Distributing processing and storage across multiple physical locations or logical domains provides a degree of redundancy or overlap for organizations. The redundancy and overlap increase the work factor of adversaries to adversely impact organizational operations, assets, and individuals. The use of distributed processing and storage does not assume a single primary processing or storage location. Therefore, it allows for parallel processing and storage. Related Controls:  CP-6, CP-7, PL-8, SC-32.', 'vec_doc-14-nist-sp-800-53-p349-1350', 0, 191, 'v2.1.0', '9824ed4354677fccc12809d1e26524f5651ba14e1cd60dd21cbb772f32965ee8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 322","subsection":"UNKNOWN","table_id":null,"page":349,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1350,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 322"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p349-1351', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 322', 349, 'Control Enhancements: (1) DISTRIBUTED PROCESSING AND STORAGE | POLLING TECHNIQUES (a) Employ polling techniques to identify potential faults, errors, or compromises to the following processing and storage components: [Assignment: organization-defined distributed processing and storage components]; and (b) Take the following actions in response to identified faults, errors, or compromises: [Assignment: organization-defined actions]. Discussion:  Distributed processing and/or storage may be used to reduce opportunities for adversaries to compromise the confidentiality, integrity, or availability of organizational information and systems. However, the distribution of processing and storage components does not prevent adversaries from compromising one or more of the components. Polling compares the processing results and/or storage content from the distributed components and subsequently votes on the outcomes.', 'vec_doc-14-nist-sp-800-53-p349-1351', 0, 230, 'v2.1.0', '142e05957fa782a074b95548d88a66b9dafbd2d17a2131cddc75309ade4670a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 322","subsection":"UNKNOWN","table_id":null,"page":349,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1351,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 322"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p349-1352', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 322', 349, 'Polling identifies potential faults, compromises, or errors in the distributed processing and storage components. Related Controls:  SI-4. (2) DISTRIBUTED PROCESSING AND STORAGE | SYNCHRONIZATION Synchronize the following duplicate systems or system components: [Assignment: organization-defined duplicate systems or system components].', 'vec_doc-14-nist-sp-800-53-p349-1352', 0, 84, 'v2.1.0', '7875a646dc77603ed55e96e459167f17e3aae1b33d58e9f6c4b71f1e23315461', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 322","subsection":"UNKNOWN","table_id":null,"page":349,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1352,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 322"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p350-1353', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 323', 350, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  SC-36 and CP-9(6) require the duplication of systems or system components in distributed locations. The synchronization of duplicated and redundant services and data helps to ensure that information contained in the distributed locations can be used in the mission or business functions of organizations, as needed. Related Controls:  CP-9. References:  [SP 800-160-2]. SC-37 OUT-OF-BAND CHANNELS Control:  Employ the following out-of-band channels for the physical delivery or electronic transmission of [Assignment: organization-defined information, system components, or devices] to [Assignment: organization-defined individuals or systems]: [Assignment: organization-defined out-of-band channels].', 'vec_doc-14-nist-sp-800-53-p350-1353', 0, 202, 'v2.1.0', '4adb90657077d03ef4abee44df310beba89932ff733c1acbce544a6cd5647580', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 323","subsection":"UNKNOWN","table_id":null,"page":350,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1353,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 323"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p350-1354', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 323', 350, 'Discussion:  Out-of-band channels include local, non-network accesses to systems; network paths physically separate from network paths used for operational traffic; or non-electronic paths, such as the U.S. Postal Service. The use of out-of-band channels is contrasted with the use of in-band channels (i.e., the same channels) that carry routine operational traffic. Out-of-band channels do not have the same vulnerability or exposure as in-band channels. Therefore, the confidentiality, integrity, or availability compromises of in-band channels will not compromise or adversely affect the out-of-band channels. Organizations may employ out-of-band channels in the delivery or transmission of organizational items, including authenticators and credentials; cryptographic key management information; system and data backups; configuration management changes for hardware, firmware, or software; security updates; maintenance information; and malicious code protection updates.', 'vec_doc-14-nist-sp-800-53-p350-1354', 0, 245, 'v2.1.0', 'a156786fb08d23a487e34d04f1c29dafc029edd33668fdb69ff82d55752be9da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 323","subsection":"UNKNOWN","table_id":null,"page":350,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1354,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 323"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p350-1355', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 323', 350, 'Related Controls:  AC-2, CM-3, CM-5, CM-7, IA-2, IA-4, IA-5, MA-4, SC-12, SI-3, SI-4, SI-7. Control Enhancements: (1) OUT-OF-BAND CHANNELS | ENSURE DELIVERY AND TRANSMISSION Employ [Assignment: organization-defined controls] to ensure that only [Assignment: organization-defined individuals or systems] receive the following information, system components, or devices: [Assignment: organization-defined information, system components, or devices]. Discussion:  Techniques employed by organizations to ensure that only designated systems or individuals receive certain information, system components, or devices include sending authenticators via an approved courier service but requiring recipients to show some form of government-issued photographic identification as a condition of receipt. Related Controls:  None. References:  [SP 800-57-1], [SP 800-57-2], [SP 800-57-3].', 'vec_doc-14-nist-sp-800-53-p350-1355', 0, 219, 'v2.1.0', '45a5e5bb0b3e30aba42023a6fdd2a6021d05d3617d4975f20ffc00979266f5dd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 323","subsection":"UNKNOWN","table_id":null,"page":350,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1355,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 323"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p350-1356', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 323', 350, 'SC-38 OPERATIONS SECURITY Control:  Employ the following operations security controls to protect key organizational information throughout the system development life cycle: [Assignment: organization-defined operations security controls]. Discussion:  Operations security (OPSEC) is a systematic process by which potential adversaries can be denied information about the capabilities and intentions of organizations by identifying, controlling, and protecting generally unclassified information that specifically relates to the planning and execution of sensitive organizational activities. The OPSEC process involves five steps: identification of critical information, analysis of threats, analysis of vulnerabilities, assessment of risks, and the application of appropriate countermeasures. OPSEC controls are', 'vec_doc-14-nist-sp-800-53-p350-1356', 0, 203, 'v2.1.0', '0406e43ebf12b025bc1cd23d8e471f470030e2eb46165ed9cd1182e182639bea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 323","subsection":"UNKNOWN","table_id":null,"page":350,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1356,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 323"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p351-1357', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 324', 351, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 applied to organizational systems and the environments in which those systems operate. OPSEC controls protect the confidentiality of information, including limiting the sharing of information with suppliers, potential suppliers, and other non-organizational elements and individuals. Information critical to organizational mission and business functions includes user identities, element uses, suppliers, supply chain processes, functional requirements, security requirements, system design specifications, testing and evaluation protocols, and security control implementation details. Related Controls:  CA-2, CA-7, PL-1, PM-9, PM-12, RA-2, RA-3, RA-5, SC-7, SR-3, SR-7. Control Enhancements:  None. References:  None. SC-39 PROCESS ISOLATION Control:  Maintain a separate execution domain for each executing system process.', 'vec_doc-14-nist-sp-800-53-p351-1357', 0, 230, 'v2.1.0', '77485e0cbb793116570c36e1d9b44236eb76f655b7e5bf1a03ffe48b81ef7889', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 324","subsection":"UNKNOWN","table_id":null,"page":351,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1357,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 324"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p351-1358', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 324', 351, 'Discussion:  Systems can maintain separate execution domains for each executing process by assigning each process a separate address space. Each system process has a distinct address space so that communication between processes is performed in a manner controlled through the security functions, and one process cannot modify the executing code of another process. Maintaining separate execution domains for executing processes can be achieved, for example, by implementing separate address spaces. Process isolation technologies, including sandboxing or virtualization, logically separate software and firmware from other software, firmware, and data. Process isolation helps limit the access of potentially untrusted software to other system resources. The capability to maintain separate execution domains is available in commercial operating systems that employ multi-state processor technologies. Related Controls:  AC-3, AC-4, AC-6, AC-25, SA-8, SC-2, SC-3, SI-16.', 'vec_doc-14-nist-sp-800-53-p351-1358', 0, 243, 'v2.1.0', '5db877026c6b1bbda8a06f647b631774fa016b7c6dc0ea2693c67a63d7e85813', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 324","subsection":"UNKNOWN","table_id":null,"page":351,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1358,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 324"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p351-1359', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 324', 351, 'Control Enhancements: (1) PROCESS ISOLATION | HARDWARE SEPARATION Implement hardware separation mechanisms to facilitate process isolation. Discussion:  Hardware-based separation of system processes is generally less susceptible to compromise than software-based separation, thus providing greater assurance that the separation will be enforced. Hardware separation mechanisms include hardware memory management. Related Controls:  None. (2) PROCESS ISOLATION | SEPARATE EXECUTION DOMAIN PER THREAD Maintain a separate execution domain for each thread in [Assignment: organization- defined multi-threaded processing]. Discussion:  None. Related Controls:  None. References:  [SP 800-160-1]. SC-40 WIRELESS LINK PROTECTION Control:  Protect external and internal [Assignment: organization-defined wireless links] from the following signal parameter attacks: [Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks].', 'vec_doc-14-nist-sp-800-53-p351-1359', 0, 242, 'v2.1.0', 'ed30b2cc4b2c82c8c4491b6a6eab4529372653fdc7bbaa194dacaab169a13f98', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 324","subsection":"UNKNOWN","table_id":null,"page":351,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1359,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 324"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p351-1360', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 324', 351, 'Discussion:  Wireless link protection applies to internal and external wireless communication links that may be visible to individuals who are not authorized system users. Adversaries can', 'vec_doc-14-nist-sp-800-53-p351-1360', 0, 47, 'v2.1.0', 'fdeb3c4772c853c0c48098d6aa424c689a2f23ed0f3670ef26c25fcdd7bf1d01', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 324","subsection":"UNKNOWN","table_id":null,"page":351,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1360,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 324"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p352-1361', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 325', 352, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 exploit the signal parameters of wireless links if such links are not adequately protected. There are many ways to exploit the signal parameters of wireless links to gain intelligence, deny service, or spoof system users. Protection of wireless links reduces the impact of attacks that are unique to wireless systems. If organizations rely on commercial service providers for transmission services as commodity items rather than as fully dedicated services, it may not be possible to implement wireless link protections to the extent necessary to meet organizational security requirements. Related Controls:  AC-18, SC-5. Control Enhancements: (1) WIRELESS LINK PROTECTION | ELECTROMAGNETIC INTERFERENCE Implement cryptographic mechanisms that achieve [Assignment: organization-defined level of protection] against the effects of intentional electromagnetic interference.', 'vec_doc-14-nist-sp-800-53-p352-1361', 0, 241, 'v2.1.0', '4ada1b1af226732d486a0bc4d022382f44e75be52ac8a9514c71d14b74abd580', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 325","subsection":"UNKNOWN","table_id":null,"page":352,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1361,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 325"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p352-1362', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 325', 352, 'Discussion:  The implementation of cryptographic mechanisms for electromagnetic interference protects systems against intentional jamming that might deny or impair communications by ensuring that wireless spread spectrum waveforms used to provide anti- jam protection are not predictable by unauthorized individuals. The implementation of cryptographic mechanisms may also coincidentally mitigate the effects of unintentional jamming due to interference from legitimate transmitters that share the same spectrum. Mission requirements, projected threats, concept of operations, and laws, executive orders, directives, regulations, policies, and standards determine levels of wireless link availability, cryptography needed, and performance. Related Controls:  PE-21, SC-12, SC-13. (2) WIRELESS LINK PROTECTION | REDUCE DETECTION POTENTIAL Implement cryptographic mechanisms to reduce the detection potential of wireless links to [Assignment: organization-defined level of reduction].', 'vec_doc-14-nist-sp-800-53-p352-1362', 0, 246, 'v2.1.0', 'e82582a40fbc8f9bce90ca326d2751d3fb2f7d8a825945edac2be26de0473fb1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 325","subsection":"UNKNOWN","table_id":null,"page":352,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1362,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 325"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p352-1363', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 325', 352, 'Discussion:  The implementation of cryptographic mechanisms to reduce detection potential is used for covert communications and to protect wireless transmitters from geo-location. It also ensures that the spread spectrum waveforms used to achieve a low probability of detection are not predictable by unauthorized individuals. Mission requirements, projected threats, concept of operations, and applicable laws, executive orders, directives, regulations, policies, and standards determine the levels to which wireless links are undetectable. Related Controls:  SC-12, SC-13. (3) WIRELESS LINK PROTECTION | IMITATIVE OR MANIPULATIVE COMMUNICATIONS DECEPTION Implement cryptographic mechanisms to identify and reject wireless transmissions that are deliberate attempts to achieve imitative or manipulative communications deception based on signal parameters.', 'vec_doc-14-nist-sp-800-53-p352-1363', 0, 214, 'v2.1.0', '019c89a1af1128a2dd1f40449ed75d2beabaeb4a2156016e4682da8ecb72bdc8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 325","subsection":"UNKNOWN","table_id":null,"page":352,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1363,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 325"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p352-1364', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 325', 352, 'Discussion:  The implementation of cryptographic mechanisms to identify and reject imitative or manipulative communications ensures that the signal parameters of wireless transmissions are not predictable by unauthorized individuals. Such unpredictability reduces the probability of imitative or manipulative communications deception based on signal parameters alone. Related Controls:  SC-12, SC-13, SI-4. (4) WIRELESS LINK PROTECTION | SIGNAL PARAMETER IDENTIFICATION Implement cryptographic mechanisms to prevent the identification of [Assignment: organization-defined wireless transmitters] by using the transmitter signal parameters. Discussion:  The implementation of cryptographic mechanisms to prevent the identification of wireless transmitters protects against the unique identification of wireless transmitters', 'vec_doc-14-nist-sp-800-53-p352-1364', 0, 206, 'v2.1.0', '7478bd8c4cef2d312155bf583fef02ee661bec90c15122fb4f52cc5447adcc6d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 325","subsection":"UNKNOWN","table_id":null,"page":352,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1364,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 325"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p353-1365', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 326', 353, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 for the purposes of intelligence exploitation by ensuring that anti-fingerprinting alterations to signal parameters are not predictable by unauthorized individuals. It also provides anonymity when required. Radio fingerprinting techniques identify the unique signal parameters of transmitters to fingerprint such transmitters for purposes of tracking and mission or user identification. Related Controls:  SC-12, SC-13. References:  None. SC-41 PORT AND I/O DEVICE ACCESS Control:  [Selection: Physically; Logically] disable or remove [Assignment: organization-defined connection ports or input/output devices] on the following systems or system components: [Assignment: organization-defined systems or system components]. Discussion:  Connection ports include Universal Serial Bus (USB), Thunderbolt, and Firewire (IEEE 1394). Input/output (I/O) devices include compact disc and digital versatile disc drives.', 'vec_doc-14-nist-sp-800-53-p353-1365', 0, 251, 'v2.1.0', '1e8880e5bfd6bff1db32292780fb8d4b1514ffceb3e0bb3fcd64e28debeab08c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 326","subsection":"UNKNOWN","table_id":null,"page":353,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1365,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 326"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p353-1366', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 326', 353, 'Disabling or removing such connection ports and I/O devices helps prevent the exfiltration of information from systems and the introduction of malicious code from those ports or devices. Physically disabling or removing ports and/or devices is the stronger action. Related Controls:  AC-20, MP-7. Control Enhancements:  None. References:  None. SC-42 SENSOR CAPABILITY AND DATA Control: a. Prohibit [Selection (one or more): the use of devices possessing [Assignment: organization- defined environmental sensing capabilities] in [Assignment: organization-defined facilities, areas, or systems]; the remote activation of environmental sensing capabilities on organizational systems or system components with the following exceptions: [Assignment: organization-defined exceptions where remote activation of sensors is allowed]]; and b. Provide an explicit indication of sensor use to [Assignment: organization-defined group of users].', 'vec_doc-14-nist-sp-800-53-p353-1366', 0, 233, 'v2.1.0', '52c2cbb389199d964a292227e7e0c6922816887ee043d1066a70c29a48e9ea0d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 326","subsection":"UNKNOWN","table_id":null,"page":353,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1366,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 326"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p353-1367', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 326', 353, 'Discussion:  Sensor capability and data applies to types of systems or system components characterized as mobile devices, such as cellular telephones, smart phones, and tablets. Mobile devices often include sensors that can collect and record data regarding the environment where the system is in use. Sensors that are embedded within mobile devices include microphones, cameras, Global Positioning System (GPS) mechanisms, and accelerometers. While the sensors on mobiles devices provide an important function, if activated covertly, such devices can potentially provide a means for adversaries to learn valuable information about individuals and organizations. For example, remotely activating the GPS function on a mobile device could provide an adversary with the ability to track the movements of an individual.', 'vec_doc-14-nist-sp-800-53-p353-1367', 0, 204, 'v2.1.0', '2b8f5be201f8ab14543dfb4bf75b5dccca99d962f25fb96a03d631a0467aff06', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 326","subsection":"UNKNOWN","table_id":null,"page":353,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1367,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 326"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p353-1368', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 326', 353, 'Organizations may prohibit individuals from bringing cellular telephones or digital cameras into certain designated facilities or controlled areas within facilities where classified information is stored or sensitive conversations are taking place. Related Controls:  SC-15. Control Enhancements: (1) SENSOR CAPABILITY AND DATA | REPORTING TO AUTHORIZED INDIVIDUALS OR ROLES', 'vec_doc-14-nist-sp-800-53-p353-1368', 0, 94, 'v2.1.0', 'a442d7fcdf1bdbce0e2d5d11945b664822e3f4e479ab6afcabcaf4669229279d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 326","subsection":"UNKNOWN","table_id":null,"page":353,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1368,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 326"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p354-1369', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 327', 354, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Verify that the system is configured so that data or information collected by the [Assignment: organization-defined sensors] is only reported to authorized individuals or roles. Discussion:  In situations where sensors are activated by authorized individuals, it is still possible that the data or information collected by the sensors will be sent to unauthorized entities. Related Controls:  None. (2) SENSOR CAPABILITY AND DATA | AUTHORIZED USE Employ the following measures so that data or information collected by [Assignment: organization-defined sensors] is only used for authorized purposes: [Assignment: organization-defined measures]. Discussion:  Information collected by sensors for a specific authorized purpose could be misused for some unauthorized purpose. For example, GPS sensors that are used to support traffic navigation could be misused to track the movements of individuals.', 'vec_doc-14-nist-sp-800-53-p354-1369', 0, 247, 'v2.1.0', '864354a36f8bb75132c91e0ddaf5f720534e510f239c75dc11b667b0381a9a99', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 327","subsection":"UNKNOWN","table_id":null,"page":354,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1369,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 327"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p354-1370', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 327', 354, 'Measures to mitigate such activities include additional training to help ensure that authorized individuals do not abuse their authority and, in the case where sensor data is maintained by external parties, contractual restrictions on the use of such data. Related Controls:  PT-2. (3) SENSOR CAPABILITY AND DATA | PROHIBIT USE OF DEVICES [Withdrawn: Incorporated into SC-42.] (4) SENSOR CAPABILITY AND DATA | NOTICE OF COLLECTION Employ the following measures to facilitate an individual’s awareness that personally identifiable information is being collected by [Assignment: organization-defined sensors]: [Assignment: organization-defined measures]. Discussion:  Awareness that organizational sensors are collecting data enables individuals to more effectively engage in managing their privacy. Measures can include conventional written notices and sensor configurations that make individuals directly or indirectly aware through other devices that the sensor is collecting information.', 'vec_doc-14-nist-sp-800-53-p354-1370', 0, 248, 'v2.1.0', '6984d84f347875c3b345d897f91d6ac653b8f082dc2cb6d56764f79dba9377c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 327","subsection":"UNKNOWN","table_id":null,"page":354,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1370,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 327"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p354-1371', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 327', 354, 'The usability and efficacy of the notice are important considerations. Related Controls:  PT-1, PT-4, PT-5. (5) SENSOR CAPABILITY AND DATA | COLLECTION MINIMIZATION Employ [Assignment: organization-defined sensors] that are configured to minimize the collection of information about individuals that is not needed. Discussion:  Although policies to control for authorized use can be applied to information once it is collected, minimizing the collection of information that is not needed mitigates privacy risk at the system entry point and mitigates the risk of policy control failures. Sensor configurations include the obscuring of human features, such as blurring or pixelating flesh tones. Related Controls:  SA-8, SI-12. References:  [OMB A-130], [SP 800-124]. SC-43 USAGE RESTRICTIONS Control: a. Establish usage restrictions and implementation guidelines for the following system components: [Assignment: organization-defined system components]; and', 'vec_doc-14-nist-sp-800-53-p354-1371', 0, 240, 'v2.1.0', '318b971e83165f97907dcf0289142854808688cf8956cacc3332fde236bfbf75', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 327","subsection":"UNKNOWN","table_id":null,"page":354,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1371,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 327"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p355-1372', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 328', 355, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 b. Authorize, monitor, and control the use of such components within the system. Discussion:  Usage restrictions apply to all system components including but not limited to mobile code, mobile devices, wireless access, and wired and wireless peripheral components (e.g., copiers, printers, scanners, optical devices, and other similar technologies). The usage restrictions and implementation guidelines are based on the potential for system components to cause damage to the system and help to ensure that only authorized system use occurs. Related Controls:  AC-18, AC-19, CM-6, SC-7, SC-18. Control Enhancements:  None. References:  [OMB A-130], [SP 800-124]. SC-44 DETONATION CHAMBERS Control:  Employ a detonation chamber capability within [Assignment: organization-defined system, system component, or location].', 'vec_doc-14-nist-sp-800-53-p355-1372', 0, 228, 'v2.1.0', '50763ec0c4d755ceee204eccc37b641f210d87597fade7b1d5b655343a3c9b91', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 328","subsection":"UNKNOWN","table_id":null,"page":355,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1372,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 328"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p355-1373', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 328', 355, 'Discussion:  Detonation chambers, also known as dynamic execution environments, allow organizations to open email attachments, execute untrusted or suspicious applications, and execute Universal Resource Locator requests in the safety of an isolated environment or a virtualized sandbox. Protected and isolated execution environments provide a means of determining whether the associated attachments or applications contain malicious code. While related to the concept of deception nets, the employment of detonation chambers is not intended to maintain a long-term environment in which adversaries can operate and their actions can be observed. Rather, detonation chambers are intended to quickly identify malicious code and either reduce the likelihood that the code is propagated to user environments of operation or prevent such propagation completely. Related Controls:  SC-7, SC-18, SC-25, SC-26, SC-30, SC-35, SC-39, SI-3, SI-7. Control Enhancements:  None. References:  [SP 800-177].', 'vec_doc-14-nist-sp-800-53-p355-1373', 0, 248, 'v2.1.0', 'ecf6b610caf5f24c4a99cf5995a0b75c9d3e8d0ece5846a8e3699e01fbd8f6b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 328","subsection":"UNKNOWN","table_id":null,"page":355,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1373,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 328"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p355-1374', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 328', 355, 'SC-45  SYSTEM TIME SYNCHRONIZATION Control:  Synchronize system clocks within and between systems and system components. Discussion:  Time synchronization of system clocks is essential for the correct execution of many system services, including identification and authentication processes that involve certificates and time-of-day restrictions as part of access control. Denial of service or failure to deny expired credentials may result without properly synchronized clocks within and between systems and system components. Time is commonly expressed in Coordinated Universal Time (UTC), a modern continuation of Greenwich Mean Time (GMT), or local time with an offset from UTC. The granularity of time measurements refers to the degree of synchronization between system clocks and reference clocks, such as clocks synchronizing within hundreds of milliseconds or tens of milliseconds. Organizations may define different time granularities for system components.', 'vec_doc-14-nist-sp-800-53-p355-1374', 0, 242, 'v2.1.0', '6afec68dd496d4e1e425b28779bf02effc5e160ee7a6d16a36f45723b8952f1f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 328","subsection":"UNKNOWN","table_id":null,"page":355,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1374,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 328"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p355-1375', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 328', 355, 'Time service can be critical to other security capabilities— such as access control and identification and authentication— depending on the nature of the mechanisms used to support the capabilities. Related Controls:  AC-3, AU-8, IA-2, IA-8. Control Enhancements: (1) SYSTEM TIME SYNCHRONIZATION | SYNCHRONIZATION WITH AUTHORITATIVE TIME SOURCE (a) Compare the internal system clocks [Assignment: organization-defined frequency] with [Assignment: organization-defined authoritative time source]; and', 'vec_doc-14-nist-sp-800-53-p355-1375', 0, 125, 'v2.1.0', 'ed19c0c841b9b84f62a46b54de6700cb47a354d62d89955a7261f78de41f38ab', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 328","subsection":"UNKNOWN","table_id":null,"page":355,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1375,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 328"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p356-1376', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 329', 356, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (b) Synchronize the internal system clocks to the authoritative time source when the time difference is greater than [Assignment: organization-defined time period]. Discussion:  Synchronization of internal system clocks with an authoritative source provides uniformity of time stamps for systems with multiple system clocks and systems connected over a network. Related Controls:  None. (2) SYSTEM TIME SYNCHRONIZATION | SECONDARY AUTHORITATIVE TIME SOURCE (a) Identify a secondary authoritative time source that is in a different geographic region than the primary authoritative time source; and (b) Synchronize the internal system clocks to the secondary authoritative time source if the primary authoritative time source is unavailable. Discussion:  It may be necessary to employ geolocation information to determine that the secondary authoritative time source is in a different geographic region.', 'vec_doc-14-nist-sp-800-53-p356-1376', 0, 249, 'v2.1.0', 'a419cf7020984a4ce004b33bf24f0c228f93509d192eda49964c910753d3b1d9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 329","subsection":"UNKNOWN","table_id":null,"page":356,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1376,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 329"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p356-1377', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 329', 356, 'Related Controls:  None. References:  [IETF 5905]. SC-46 CROSS DOMAIN POLICY ENFORCEMENT Control:  Implement a policy enforcement mechanism [Selection: physically; logically] between the physical and/or network interfaces for the connecting security domains. Discussion:  For logical policy enforcement mechanisms, organizations avoid creating a logical path between interfaces to prevent the ability to bypass the policy enforcement mechanism. For physical policy enforcement mechanisms, the robustness of physical isolation afforded by the physical implementation of policy enforcement to preclude the presence of logical covert channels penetrating the security domain may be needed. Contact ncdsmo@nsa.gov for more information. Related Controls:  AC-4, SC-7. Control Enhancements:  None. References:  [SP 800-160-1]. SC-47 ALTERNATE COMMUNICATIONS PATHS Control:  Establish [Assignment: organization-defined alternate communications paths] for system operations organizational command and control.', 'vec_doc-14-nist-sp-800-53-p356-1377', 0, 251, 'v2.1.0', 'e61ad1420ba7c08f5a82d3d66315827b94a6da514047c0c35c5be662145e19e2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 329","subsection":"UNKNOWN","table_id":null,"page":356,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1377,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 329"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p356-1378', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 329', 356, 'Discussion:  An incident, whether adversarial- or nonadversarial-based, can disrupt established communications paths used for system operations and organizational command and control. Alternate communications paths reduce the risk of all communications paths being affected by the same incident. To compound the problem, the inability of organizational officials to obtain timely information about disruptions or to provide timely direction to operational elements after a communications path incident, can impact the ability of the organization to respond to such incidents in a timely manner. Establishing alternate communications paths for command and control purposes, including designating alternative decision makers if primary decision makers are unavailable and establishing the extent and limitations of their actions, can greatly facilitate the organization’s ability to continue to operate and take appropriate actions during an incident. Related Controls:  CP-2, CP-8.', 'vec_doc-14-nist-sp-800-53-p356-1378', 0, 245, 'v2.1.0', '58c67f4931840ee864a4223c33ab0a73f2a35495b05cd6ed78a7fc8b2e4e9b59', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 329","subsection":"UNKNOWN","table_id":null,"page":356,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1378,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 329"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p356-1379', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 329', 356, 'Control Enhancements:  None. References:  [SP 800-34], [SP 800-61], [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p356-1379', 0, 21, 'v2.1.0', 'ebe63a80feed834b6d9620c27646cf3d8cf7c120caa2db3010932055dbbb1060', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 329","subsection":"UNKNOWN","table_id":null,"page":356,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1379,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 329"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p357-1380', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 330', 357, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SC-48  SENSOR RELOCATION Control:  Relocate [Assignment: organization-defined sensors and monitoring capabilities] to [Assignment: organization-defined locations] under the following conditions or circumstances: [Assignment: organization-defined conditions or circumstances]. Discussion:  Adversaries may take various paths and use different approaches as they move laterally through an organization (including its systems) to reach their target or as they attempt to exfiltrate information from the organization. The organization often only has a limited set of monitoring and detection capabilities, and they may be focused on the critical or likely infiltration or exfiltration paths. By using communications paths that the organization typically does not monitor, the adversary can increase its chances of achieving its desired goals.', 'vec_doc-14-nist-sp-800-53-p357-1380', 0, 233, 'v2.1.0', '7b72de6464f37fee85d245aace7af255971a8820d140901fedf9f69f437f5434', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 330","subsection":"UNKNOWN","table_id":null,"page":357,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1380,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 330"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p357-1381', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 330', 357, 'By relocating its sensors or monitoring capabilities to new locations, the organization can impede the adversary’s ability to achieve its goals. The relocation of the sensors or monitoring capabilities might be done based on threat information that the organization has acquired or randomly to confuse the adversary and make its lateral transition through the system or organization more challenging. Related Controls:  AU-2, SC-7, SI-4. Control Enhancements: (1) SENSOR RELOCATION | DYNAMIC RELOCATION OF SENSORS OR MONITORING CAPABILITIES Dynamically relocate [Assignment: organization-defined sensors and monitoring capabilities] to [Assignment: organization-defined locations] under the following conditions or circumstances: [Assignment: organization-defined conditions or circumstances]. Discussion:  None. Related Controls:  None. References:  [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p357-1381', 0, 217, 'v2.1.0', '8c07c28fe74425d40db9b1fb6749e4a81adbf775ca3c8f34a3f36f2b034d4a8b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 330","subsection":"UNKNOWN","table_id":null,"page":357,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1381,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 330"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p357-1382', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 330', 357, 'SC-49  HARDWARE-ENFORCED SEPARATION AND POLICY ENFORCEMENT Control:  Implement hardware-enforced separation and policy enforcement mechanisms between [Assignment: organization-defined security domains]. Discussion:  System owners may require additional strength of mechanism and robustness to ensure domain separation and policy enforcement for specific types of threats and environments of operation. Hardware-enforced separation and policy enforcement provide greater strength of mechanism than software-enforced separation and policy enforcement. Related Controls:  AC-4, SA-8, SC-50. Control Enhancements:  None. References:  [SP 800-160-1]. SC-50  SOFTWARE-ENFORCED SEPARATION AND POLICY ENFORCEMENT Control:  Implement software-enforced separation and policy enforcement mechanisms between [Assignment: organization-defined security domains].', 'vec_doc-14-nist-sp-800-53-p357-1382', 0, 212, 'v2.1.0', 'f090d7544050a14a5ae66f4f4ad5ce58946ab62c5e0320be22035394cda2902f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 330","subsection":"UNKNOWN","table_id":null,"page":357,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1382,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 330"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p357-1383', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 330', 357, 'Discussion:  System owners may require additional strength of mechanism to ensure domain separation and policy enforcement for specific types of threats and environments of operation. Related Controls:  AC-3, AC-4, SA-8, SC-2, SC-3, SC-49. Control Enhancements:  None. References:  [SP 800-160-1].', 'vec_doc-14-nist-sp-800-53-p357-1383', 0, 75, 'v2.1.0', '660d4424068c6269b2bdb031d50b767db2af1545023d77996537a9a672930425', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 330","subsection":"UNKNOWN","table_id":null,"page":357,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1383,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 330"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p358-1384', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 331', 358, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SC-51 HARDWARE-BASED PROTECTION Control: a. Employ hardware-based, write-protect for [Assignment: organization-defined system firmware components]; and b. Implement specific procedures for [Assignment: organization-defined authorized individuals] to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode. Discussion:  None. Related Controls:  None. Control Enhancements:  None. References:  None.', 'vec_doc-14-nist-sp-800-53-p358-1384', 0, 143, 'v2.1.0', 'c8702a783ff79c0102ac25fed728adf2bd3f661bbb27dc37fcc1808a9ae4fc15', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 331","subsection":"UNKNOWN","table_id":null,"page":358,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1384,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 331"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p359-1385', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.19   SYSTEM AND INFORMATION INTEGRITY', 359, 'Quick link to System and Information Integrity Summary Table SI-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p359-1385', 0, 48, 'v2.1.0', '388a3acd25d0dc6f733c255c8717f73ae4d1b4e81ffb1775cb75ba89a319d02a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.19   SYSTEM AND INFORMATION INTEGRITY","subsection":"UNKNOWN","table_id":null,"page":359,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1385,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.19   SYSTEM AND INFORMATION INTEGRITY"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p359-1386', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 359, 'level] system and information integrity policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p359-1386', 0, 80, 'v2.1.0', '394fc01c8c11fc208f91848e4c8793f63d78621fbea384ab47e775415af00271', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":359,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1386,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p359-1387', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the system and information integrity', 359, 'policy and the associated system and information integrity controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and information integrity policy and procedures; and c. Review and update the current system and information integrity:', 'vec_doc-14-nist-sp-800-53-p359-1387', 0, 81, 'v2.1.0', '88578237ad6329500606252f1914b78c83445133942cdd973b18b8e92e0772ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the system and information integrity","subsection":"UNKNOWN","table_id":null,"page":359,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1387,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the system and information integrity"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p359-1388', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 359, 'organization-defined events]. Discussion:  System and information integrity policy and procedures address the controls in the SI family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and information integrity policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and information integrity policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PS-8, SA-8, SI-12. Control Enhancements:  None. References:  [OMB A-130], [SP 800-12], [SP 800-100].', 'vec_doc-14-nist-sp-800-53-p359-1388', 0, 434, 'v2.1.0', '03f1f6c0a7d6d4b919d3f8de0cafd55de5937c850df4c6d91420e25ea15f5979', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":359,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1388,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p360-1389', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 333', 360, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 SI-2 FLAW REMEDIATION Control: a. Identify, report, and correct system flaws; b. Test software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation; c. Install security-relevant software and firmware updates within [Assignment: organization- defined time period] of the release of the updates; and d. Incorporate flaw remediation into the organizational configuration management process. Discussion:  The need to remediate system flaws applies to all types of software and firmware. Organizations identify systems affected by software flaws, including potential vulnerabilities resulting from those flaws, and report this information to designated organizational personnel with information security and privacy responsibilities. Security-relevant updates include patches, service packs, and malicious code signatures.', 'vec_doc-14-nist-sp-800-53-p360-1389', 0, 243, 'v2.1.0', '3fd216811d56027c9e3f99da5dc37601b8ed0d09dd92e7937ae61050ed1e9e9a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 333","subsection":"UNKNOWN","table_id":null,"page":360,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1389,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 333"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p360-1390', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 333', 360, 'Organizations also address flaws discovered during assessments, continuous monitoring, incident response activities, and system error handling. By incorporating flaw remediation into configuration management processes, required remediation actions can be tracked and verified. Organization-defined time periods for updating security-relevant software and firmware may vary based on a variety of risk factors, including the security category of the system, the criticality of the update (i.e., severity of the vulnerability related to the discovered flaw), the organizational risk tolerance, the mission supported by the system, or the threat environment. Some types of flaw remediation may require more testing than other types. Organizations determine the type of testing needed for the specific type of flaw remediation activity under consideration and the types of changes that are to be configuration-managed.', 'vec_doc-14-nist-sp-800-53-p360-1390', 0, 229, 'v2.1.0', '27f55c790874bf2c32537792d61fba1d213dc8f9627ad83d2669db39ac1c8754', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 333","subsection":"UNKNOWN","table_id":null,"page":360,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1390,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 333"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p360-1391', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 333', 360, 'In some situations, organizations may determine that the testing of software or firmware updates is not necessary or practical, such as when implementing simple malicious code signature updates. In testing decisions, organizations consider whether security-relevant software or firmware updates are obtained from authorized sources with appropriate digital signatures. Related Controls:  CA-5, CM-3, CM-4, CM-5, CM-6, CM-8, MA-2, RA-5, SA-8, SA-10, SA-11, SI-3, SI- 5, SI-7, SI-11. Control Enhancements: (1) FLAW REMEDIATION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) FLAW REMEDIATION | AUTOMATED FLAW REMEDIATION STATUS Determine if system components have applicable security-relevant software and firmware updates installed using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency]. Discussion:  Automated mechanisms can track and determine the status of known flaws for system components. Related Controls:  CA-7, SI-4.', 'vec_doc-14-nist-sp-800-53-p360-1391', 0, 248, 'v2.1.0', '279c45697948a32882a7476a42db15f39479ba319d490f800a4ad080c51134e7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 333","subsection":"UNKNOWN","table_id":null,"page":360,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1391,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 333"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p360-1392', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 333', 360, '(3) FLAW REMEDIATION | TIME TO REMEDIATE FLAWS AND BENCHMARKS FOR CORRECTIVE ACTIONS (a) Measure the time between flaw identification and flaw remediation; and (b) Establish the following benchmarks for taking corrective actions: [Assignment: organization-defined benchmarks]. Discussion:  Organizations determine the time it takes on average to correct system flaws after such flaws have been identified and subsequently establish organizational benchmarks', 'vec_doc-14-nist-sp-800-53-p360-1392', 0, 115, 'v2.1.0', '77d1ebd2e5501251c2feb205295e352662d3131ce9361045b206cbde49b004f1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 333","subsection":"UNKNOWN","table_id":null,"page":360,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1392,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 333"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p361-1393', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 334', 361, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (i.e., time frames) for taking corrective actions. Benchmarks can be established by the type of flaw or the severity of the potential vulnerability if the flaw can be exploited. Related Controls:  None. (4) FLAW REMEDIATION | AUTOMATED PATCH MANAGEMENT TOOLS Employ automated patch management tools to facilitate flaw remediation to the following system components: [Assignment: organization-defined system components]. Discussion:  Using automated tools to support patch management helps to ensure the timeliness and completeness of system patching operations. Related Controls:  None. (5) FLAW REMEDIATION | AUTOMATIC SOFTWARE AND FIRMWARE UPDATES Install [Assignment: organization-defined security-relevant software and firmware updates] automatically to [Assignment: organization-defined system components].', 'vec_doc-14-nist-sp-800-53-p361-1393', 0, 226, 'v2.1.0', 'acd59ce6a41eccc2945544bc7bea9149de1d51351165471aab6657ff28547025', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 334","subsection":"UNKNOWN","table_id":null,"page":361,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1393,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 334"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p361-1394', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 334', 361, 'Discussion:  Due to system integrity and availability concerns, organizations consider the methodology used to carry out automatic updates. Organizations balance the need to ensure that the updates are installed as soon as possible with the need to maintain configuration management and control with any mission or operational impacts that automatic updates might impose. Related Controls:  None. (6) FLAW REMEDIATION | REMOVAL OF PREVIOUS VERSIONS OF SOFTWARE AND FIRMWARE Remove previous versions of [Assignment: organization-defined software and firmware components] after updated versions have been installed. Discussion:  Previous versions of software or firmware components that are not removed from the system after updates have been installed may be exploited by adversaries. Some products may automatically remove previous versions of software and firmware from the system. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p361-1394', 0, 227, 'v2.1.0', '193547513e978367f6f9a32b4421889700033d038ede692e86ba55d3f6569c4e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 334","subsection":"UNKNOWN","table_id":null,"page":361,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1394,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 334"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p361-1395', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 334', 361, 'References:  [OMB A-130], [FIPS 140-3], [FIPS 186-4], [SP 800-39], [SP 800-40], [SP 800-128], [IR 7788]. SI-3 MALICIOUS CODE PROTECTION Control: a. Implement [Selection (one or more): signature based; non-signature based] malicious code protection mechanisms at system entry and exit points to detect and eradicate malicious code; b. Automatically update malicious code protection mechanisms as new releases are available in accordance with organizational configuration management policy and procedures; c. Configure malicious code protection mechanisms to:', 'vec_doc-14-nist-sp-800-53-p361-1395', 0, 140, 'v2.1.0', '005a33cdefd356159dd01039e6bbd5650b49cf66f772c6055b6e9ed6a856d3c3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 334","subsection":"UNKNOWN","table_id":null,"page":361,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1395,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 334"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p361-1396', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Perform periodic scans of the system [Assignment: organization-defined frequency] and', 361, 'real-time scans of files from external sources at [Selection (one or more): endpoint; network entry and exit points] as the files are downloaded, opened, or executed in accordance with organizational policy; and', 'vec_doc-14-nist-sp-800-53-p361-1396', 0, 53, 'v2.1.0', 'cab4df045cfbd59accae1a105190c656ad0b19d9dc67fccf18c1ecb2f451f6dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Perform periodic scans of the system [Assignment: organization-defined frequency] and","subsection":"UNKNOWN","table_id":null,"page":361,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1396,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Perform periodic scans of the system [Assignment: organization-defined frequency] and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p361-1397', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. [Selection (one or more): block malicious code; quarantine malicious code; take', 361, '[Assignment: organization-defined action]]; and send alert to [Assignment: organization- defined personnel or roles] in response to malicious code detection; and', 'vec_doc-14-nist-sp-800-53-p361-1397', 0, 41, 'v2.1.0', '50e1397d1b8d97ea9d1b52f58476cd663d7e5b0067d2782093cdf59f2d8deca3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. [Selection (one or more): block malicious code; quarantine malicious code; take","subsection":"UNKNOWN","table_id":null,"page":361,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1397,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. [Selection (one or more): block malicious code; quarantine malicious code; take"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p362-1398', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 335', 362, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 d. Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system. Discussion:  System entry and exit points include firewalls, remote access servers, workstations, electronic mail servers, web servers, proxy servers, notebook computers, and mobile devices. Malicious code includes viruses, worms, Trojan horses, and spyware. Malicious code can also be encoded in various formats contained within compressed or hidden files or hidden in files using techniques such as steganography. Malicious code can be inserted into systems in a variety of ways, including by electronic mail, the world-wide web, and portable storage devices. Malicious code insertions occur through the exploitation of system vulnerabilities. A variety of technologies and methods exist to limit or eliminate the effects of malicious code.', 'vec_doc-14-nist-sp-800-53-p362-1398', 0, 249, 'v2.1.0', '4cc7f332483ad3d55fd6b5b9193f57dfd44c0b824bbd2b2cd14b169bc6d749d2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 335","subsection":"UNKNOWN","table_id":null,"page":362,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1398,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 335"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p362-1399', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 335', 362, 'Malicious code protection mechanisms include both signature- and nonsignature-based technologies. Nonsignature-based detection mechanisms include artificial intelligence techniques that use heuristics to detect, analyze, and describe the characteristics or behavior of malicious code and to provide controls against such code for which signatures do not yet exist or for which existing signatures may not be effective. Malicious code for which active signatures do not yet exist or may be ineffective includes polymorphic malicious code (i.e., code that changes signatures when it replicates). Nonsignature-based mechanisms also include reputation-based technologies. In addition to the above technologies, pervasive configuration management, comprehensive software integrity controls, and anti-exploitation software may be effective in preventing the execution of unauthorized code.', 'vec_doc-14-nist-sp-800-53-p362-1399', 0, 221, 'v2.1.0', '51d93d8464302b17b7be960ee453b48982a0ba548487ed487aa44eda1bb65f2a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 335","subsection":"UNKNOWN","table_id":null,"page":362,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1399,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 335"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p362-1400', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 335', 362, 'Malicious code may be present in commercial off-the-shelf software as well as custom-built software and could include logic bombs, backdoors, and other types of attacks that could affect organizational mission and business functions. In situations where malicious code cannot be detected by detection methods or technologies, organizations rely on other types of controls, including secure coding practices, configuration management and control, trusted procurement processes, and monitoring practices to ensure that software does not perform functions other than the functions intended. Organizations may determine that, in response to the detection of malicious code, different actions may be warranted. For example, organizations can define actions in response to malicious code detection during periodic scans, the detection of malicious downloads, or the detection of maliciousness when attempting to open or execute files.', 'vec_doc-14-nist-sp-800-53-p362-1400', 0, 232, 'v2.1.0', 'a0682782de25d86bc4ffe7772c6c14207225a2d5868c6f0d049a2f070e849efa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 335","subsection":"UNKNOWN","table_id":null,"page":362,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1400,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 335"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p362-1401', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 335', 362, 'Related Controls:  AC-4, AC-19, CM-3, CM-8, IR-4, MA-3, MA-4, PL-9, RA-5, SC-7, SC-23, SC-26, SC- 28, SC-44, SI-2, SI-4, SI-7, SI-8, SI-15. Control Enhancements: (1) MALICIOUS CODE PROTECTION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) MALICIOUS CODE PROTECTION | AUTOMATIC UPDATES [Withdrawn: Incorporated into SI-3.] (3) MALICIOUS CODE PROTECTION | NON-PRIVILEGED USERS [Withdrawn: Incorporated into AC-6(10).] (4) MALICIOUS CODE PROTECTION | UPDATES ONLY BY PRIVILEGED USERS Update malicious code protection mechanisms only when directed by a privileged user. Discussion:  Protection mechanisms for malicious code are typically categorized as security- related software and, as such, are only updated by organizational personnel with appropriate access privileges. Related Controls:  CM-5. (5) MALICIOUS CODE PROTECTION | PORTABLE STORAGE DEVICES', 'vec_doc-14-nist-sp-800-53-p362-1401', 0, 217, 'v2.1.0', 'ec9f3c78cf2bb969e9b7653e6614e2daffc4a60f4ce7a2070955064765d2117f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 335","subsection":"UNKNOWN","table_id":null,"page":362,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1401,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 335"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p363-1402', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 336', 363, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Incorporated into MP-7.] (6) MALICIOUS CODE PROTECTION | TESTING AND VERIFICATION (a) Test malicious code protection mechanisms [Assignment: organization-defined frequency] by introducing known benign code into the system; and (b) Verify that the detection of the code and the associated incident reporting occur. Discussion:  None. Related Controls:  CA-2, CA-7, RA-5.', 'vec_doc-14-nist-sp-800-53-p363-1402', 0, 119, 'v2.1.0', '061ba33932b78ebe044f7a08b896b16125f7a148f21fc54e6a31faa53654c54f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 336","subsection":"UNKNOWN","table_id":null,"page":363,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1402,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 336"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p363-1403', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 336', 363, '(7) MALICIOUS CODE PROTECTION | NONSIGNATURE-BASED DETECTION [Withdrawn: Incorporated into SI-3.] (8) MALICIOUS CODE PROTECTION | DETECT UNAUTHORIZED COMMANDS (a) Detect the following unauthorized operating system commands through the kernel application programming interface on [Assignment: organization-defined system hardware components]: [Assignment: organization-defined unauthorized operating system commands]; and (b) [Selection (one or more): issue a warning; audit the command execution; prevent the execution of the command]. Discussion:  Detecting unauthorized commands can be applied to critical interfaces other than kernel-based interfaces, including interfaces with virtual machines and privileged applications.', 'vec_doc-14-nist-sp-800-53-p363-1403', 0, 182, 'v2.1.0', '821f24103e59f73c37a55b16d1f48a5fa067128fb40101832ecd4c34fc2b74ee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 336","subsection":"UNKNOWN","table_id":null,"page":363,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1403,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 336"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p363-1404', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 336', 363, 'Unauthorized operating system commands include commands for kernel functions from system processes that are not trusted to initiate such commands as well as commands for kernel functions that are suspicious even though commands of that type are reasonable for processes to initiate. Organizations can define the malicious commands to be detected by a combination of command types, command classes, or specific instances of commands. Organizations can also define hardware components by component type, component, component location in the network, or a combination thereof. Organizations may select different actions for different types, classes, or instances of malicious commands. Related Controls:  AU-2, AU-6, AU-12.', 'vec_doc-14-nist-sp-800-53-p363-1404', 0, 180, 'v2.1.0', 'f338d36840414f4240c2f353b0689b371a81d552e333b05496f6c864c46acd05', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 336","subsection":"UNKNOWN","table_id":null,"page":363,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1404,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 336"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p363-1405', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 336', 363, '(9) MALICIOUS CODE PROTECTION | AUTHENTICATE REMOTE COMMANDS [Withdrawn: Moved to AC-17(10).] (10) MALICIOUS CODE PROTECTION | MALICIOUS CODE ANALYSIS (a) Employ the following tools and techniques to analyze the characteristics and behavior of malicious code: [Assignment: organization-defined tools and techniques]; and (b) Incorporate the results from malicious code analysis into organizational incident response and flaw remediation processes. Discussion:  The use of malicious code analysis tools provides organizations with a more in- depth understanding of adversary tradecraft (i.e., tactics, techniques, and procedures) and the functionality and purpose of specific instances of malicious code. Understanding the characteristics of malicious code facilitates effective organizational responses to current and future threats. Organizations can conduct malicious code analyses by employing reverse engineering techniques or by monitoring the behavior of executing code. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p363-1405', 0, 251, 'v2.1.0', '0a2d65bc89d9943b59fa39378bd0a14d69d6d5342b84b2fcf7121bc9f05f2e93', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 336","subsection":"UNKNOWN","table_id":null,"page":363,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1405,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 336"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p363-1406', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 336', 363, 'References:  [SP 800-83], [SP 800-125B], [SP 800-177]. SI-4 SYSTEM MONITORING Control:', 'vec_doc-14-nist-sp-800-53-p363-1406', 0, 22, 'v2.1.0', '33b99cd8247465c04da68af526399c19d0fc037ed928fdbc059ce5b82663291a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 336","subsection":"UNKNOWN","table_id":null,"page":363,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1406,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 336"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1407', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 337', 364, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Monitor the system to detect:', 'vec_doc-14-nist-sp-800-53-p364-1407', 0, 31, 'v2.1.0', '997efcc1b80182c6069e0cb64fc506f7d05a0925e132b4be5b86cedf9ee06a6f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 337","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1407,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 337"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1408', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. Attacks and indicators of potential attacks in accordance with the following monitoring', 364, 'objectives: [Assignment: organization-defined monitoring objectives]; and', 'vec_doc-14-nist-sp-800-53-p364-1408', 0, 19, 'v2.1.0', 'ad82ebf895d42272341e9db1ed91d950a219722e75b26cedb48703c597c38443', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. Attacks and indicators of potential attacks in accordance with the following monitoring","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1408,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. Attacks and indicators of potential attacks in accordance with the following monitoring"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1409', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Unauthorized local, network, and remote connections;', 364, 'b. Identify unauthorized use of the system through the following techniques and methods: [Assignment: organization-defined techniques and methods]; c. Invoke internal monitoring capabilities or deploy monitoring devices:', 'vec_doc-14-nist-sp-800-53-p364-1409', 0, 55, 'v2.1.0', '5aa9d657afc8cf70122ebafafebf1b14c40cce9499e789af50d4e89998a5ee97', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Unauthorized local, network, and remote connections;","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1409,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Unauthorized local, network, and remote connections;"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1410', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. At ad hoc locations within the system to track specific types of transactions of interest', 364, 'to the organization; d. Analyze detected events and anomalies; e. Adjust the level of system monitoring activity when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation; f. Obtain legal opinion regarding system monitoring activities; and g. Provide [Assignment: organization-defined system monitoring information] to [Assignment: organization-defined personnel or roles] [Selection (one or more): as needed; [Assignment: organization-defined frequency]]. Discussion:  System monitoring includes external and internal monitoring. External monitoring includes the observation of events occurring at external interfaces to the system. Internal monitoring includes the observation of events occurring within the system. Organizations monitor systems by observing audit activities in real time or by observing other system aspects such as access patterns, characteristics of access, and other actions.', 'vec_doc-14-nist-sp-800-53-p364-1410', 0, 240, 'v2.1.0', '8bc632d7736a29be08d9b28430138a22d02fc9c8cbea84bc51e3a5d3849ae604', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. At ad hoc locations within the system to track specific types of transactions of interest","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1410,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. At ad hoc locations within the system to track specific types of transactions of interest"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1411', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. At ad hoc locations within the system to track specific types of transactions of interest', 364, 'The monitoring objectives guide and inform the determination of the events. System monitoring capabilities are achieved through a variety of tools and techniques, including intrusion detection and prevention systems, malicious code protection software, scanning tools, audit record monitoring software, and network monitoring software. Depending on the security architecture, the distribution and configuration of monitoring devices may impact throughput at key internal and external boundaries as well as at other locations across a network due to the introduction of network throughput latency. If throughput management is needed, such devices are strategically located and deployed as part of an established organization-wide security architecture. Strategic locations for monitoring devices include selected perimeter locations and near key servers and server farms that support critical applications.', 'vec_doc-14-nist-sp-800-53-p364-1411', 0, 227, 'v2.1.0', '694740de79f8dbfcaac2cc403f2cd5cbccd3d4a475b0c4cfef0e5897e0c5dda5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. At ad hoc locations within the system to track specific types of transactions of interest","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1411,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. At ad hoc locations within the system to track specific types of transactions of interest"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1412', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. At ad hoc locations within the system to track specific types of transactions of interest', 364, 'Monitoring devices are typically employed at the managed interfaces associated with controls SC-7 and AC-17. The information collected is a function of the organizational monitoring objectives and the capability of systems to support such objectives. Specific types of transactions of interest include Hypertext Transfer Protocol (HTTP) traffic that bypasses HTTP proxies. System monitoring is an integral part of organizational continuous monitoring and incident response programs, and output from system monitoring serves as input to those programs. System monitoring requirements, including the need for specific types of system monitoring, may be referenced in other controls (e.g., AC-2g, AC-2(7), AC-2(12)(a), AC-17(1), AU- 13, AU-13(1), AU-13(2), CM-3f, CM-6d, MA-3a, MA-4a, SC-5(3)(b), SC-7a, SC-7(24)(b), SC-18b, SC- 43b). Adjustments to levels of system monitoring are based on law enforcement information, intelligence information, or other sources of information.', 'vec_doc-14-nist-sp-800-53-p364-1412', 0, 244, 'v2.1.0', 'bcd6737c4b441cce1c1180c70cac402030fd29c7abafe3d742534b18d9978473', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. At ad hoc locations within the system to track specific types of transactions of interest","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1412,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. At ad hoc locations within the system to track specific types of transactions of interest"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p364-1413', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. At ad hoc locations within the system to track specific types of transactions of interest', 364, 'The legality of system monitoring activities is based on applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'vec_doc-14-nist-sp-800-53-p364-1413', 0, 39, 'v2.1.0', '9758252449ffdb777565d13399a8ea2cd1d0e36446277d90ed0e82b241436a60', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. At ad hoc locations within the system to track specific types of transactions of interest","subsection":"UNKNOWN","table_id":null,"page":364,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1413,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. At ad hoc locations within the system to track specific types of transactions of interest"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p365-1414', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 338', 365, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  AC-2, AC-3, AC-4, AC-8, AC-17, AU-2, AU-6, AU-7, AU-9, AU-12, AU-13, AU-14, CA-7, CM-3, CM-6, CM-8, CM-11, IA-10, IR-4, MA-3, MA-4, PL-9, PM-12, RA-5, RA-10, SC-5, SC-7, SC-18, SC-26, SC-31, SC-35, SC-36, SC-37, SC-43, SI-3, SI-6, SI-7, SR-9, SR-10. Control Enhancements: (1) SYSTEM MONITORING | SYSTEM-WIDE INTRUSION DETECTION SYSTEM Connect and configure individual intrusion detection tools into a system-wide intrusion detection system. Discussion:  Linking individual intrusion detection tools into a system-wide intrusion detection system provides additional coverage and effective detection capabilities. The information contained in one intrusion detection tool can be shared widely across the organization, making the system-wide detection capability more robust and powerful. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p365-1414', 0, 231, 'v2.1.0', 'ca2d28312748e9271f3d287ac2c2485ce8b50ec917f56b260a6c2b5c831e6ec3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 338","subsection":"UNKNOWN","table_id":null,"page":365,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1414,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 338"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p365-1415', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 338', 365, '(2) SYSTEM MONITORING | AUTOMATED TOOLS AND MECHANISMS FOR REAL-TIME ANALYSIS Employ automated tools and mechanisms to support near real-time analysis of events. Discussion:  Automated tools and mechanisms include host-based, network-based, transport-based, or storage-based event monitoring tools and mechanisms or security information and event management (SIEM) technologies that provide real-time analysis of alerts and notifications generated by organizational systems. Automated monitoring techniques can create unintended privacy risks because automated controls may connect to external or otherwise unrelated systems. The matching of records between these systems may create linkages with unintended consequences. Organizations assess and document these risks in their privacy impact assessment and make determinations that are in alignment with their privacy program plan. Related Controls:  PM-23, PM-25.', 'vec_doc-14-nist-sp-800-53-p365-1415', 0, 229, 'v2.1.0', 'c58f5b7dccaa788e01f60a0ba22980d0438234682218d061b3a74aa6d3fd1eda', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 338","subsection":"UNKNOWN","table_id":null,"page":365,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1415,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 338"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p365-1416', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 338', 365, '(3) SYSTEM MONITORING | AUTOMATED TOOL AND MECHANISM INTEGRATION Employ automated tools and mechanisms to integrate intrusion detection tools and mechanisms into access control and flow control mechanisms. Discussion:  Using automated tools and mechanisms to integrate intrusion detection tools and mechanisms into access and flow control mechanisms facilitates a rapid response to attacks by enabling the reconfiguration of mechanisms in support of attack isolation and elimination. Related Controls:  PM-23, PM-25. (4) SYSTEM MONITORING | INBOUND AND OUTBOUND COMMUNICATIONS TRAFFIC (a) Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic; (b) Monitor inbound and outbound communications traffic [Assignment: organization- defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions].', 'vec_doc-14-nist-sp-800-53-p365-1416', 0, 225, 'v2.1.0', '6e8865ca65e6d560bf25e8638cb32c44a8b80fc44f8e5324a48cdda6c25f677f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 338","subsection":"UNKNOWN","table_id":null,"page":365,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1416,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 338"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p365-1417', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 338', 365, 'Discussion:  Unusual or unauthorized activities or conditions related to system inbound and outbound communications traffic includes internal traffic that indicates the presence of malicious code or unauthorized use of legitimate code or credentials within organizational systems or propagating among system components, signaling to external systems, and the unauthorized exporting of information. Evidence of malicious code or unauthorized use of legitimate code or credentials is used to identify potentially compromised systems or system components. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p365-1417', 0, 145, 'v2.1.0', 'ec16df5a7abeb526c7cc85bfe175ee9689a48d2aa234b6b0deeaacb3d9782290', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 338","subsection":"UNKNOWN","table_id":null,"page":365,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1417,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 338"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p366-1418', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 339', 366, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (5) SYSTEM MONITORING | SYSTEM-GENERATED ALERTS Alert [Assignment: organization-defined personnel or roles] when the following system- generated indications of compromise or potential compromise occur: [Assignment: organization-defined compromise indicators]. Discussion:  Alerts may be generated from a variety of sources, including audit records or inputs from malicious code protection mechanisms, intrusion detection or prevention mechanisms, or boundary protection devices such as firewalls, gateways, and routers. Alerts can be automated and may be transmitted telephonically, by electronic mail messages, or by text messaging.', 'vec_doc-14-nist-sp-800-53-p366-1418', 0, 182, 'v2.1.0', '13e689fb7609a738c277f66d3e5efaf6b773d4003136840a7af5872220560ed0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 339","subsection":"UNKNOWN","table_id":null,"page":366,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1418,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 339"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p366-1419', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 339', 366, 'Organizational personnel on the alert notification list can include system administrators, mission or business owners, system owners, information owners/stewards, senior agency information security officers, senior agency officials for privacy, system security officers, or privacy officers. In contrast to alerts generated by the system, alerts generated by organizations in SI-4(12) focus on information sources external to the system, such as suspicious activity reports and reports on potential insider threats. Related Controls:  AU-4, AU-5, PE-6. (6) SYSTEM MONITORING | RESTRICT NON-PRIVILEGED USERS [Withdrawn: Incorporated into AC-6(10).] (7) SYSTEM MONITORING | AUTOMATED RESPONSE TO SUSPICIOUS EVENTS (a) Notify [Assignment: organization-defined incident response personnel (identified by name and/or by role)] of detected suspicious events; and (b) Take the following actions upon detection: [Assignment: organization-defined least- disruptive actions to terminate suspicious events].', 'vec_doc-14-nist-sp-800-53-p366-1419', 0, 249, 'v2.1.0', 'cff42c7e49ee85fa1d3d3a7c01b600bab3485d33b91c3c5b7180265681204f51', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 339","subsection":"UNKNOWN","table_id":null,"page":366,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1419,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 339"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p366-1420', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 339', 366, 'Discussion:  Least-disruptive actions include initiating requests for human responses. Related Controls:  None. (8) SYSTEM MONITORING | PROTECTION OF MONITORING INFORMATION [Withdrawn: Incorporated into SI-4.] (9) SYSTEM MONITORING | TESTING OF MONITORING TOOLS AND MECHANISMS Test intrusion-monitoring tools and mechanisms [Assignment: organization-defined frequency]. Discussion:  Testing intrusion-monitoring tools and mechanisms is necessary to ensure that the tools and mechanisms are operating correctly and continue to satisfy the monitoring objectives of organizations. The frequency and depth of testing depends on the types of tools and mechanisms used by organizations and the methods of deployment. Related Controls:  None. (10) SYSTEM MONITORING | VISIBILITY OF ENCRYPTED COMMUNICATIONS Make provisions so that [Assignment: organization-defined encrypted communications traffic] is visible to [Assignment: organization-defined system monitoring tools and mechanisms].', 'vec_doc-14-nist-sp-800-53-p366-1420', 0, 245, 'v2.1.0', '591f4abb6b9d005b64aa46a14d41237431a0a5e33a4565b87c16d11f8a63bf02', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 339","subsection":"UNKNOWN","table_id":null,"page":366,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1420,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 339"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p366-1421', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 339', 366, 'Discussion:  Organizations balance the need to encrypt communications traffic to protect data confidentiality with the need to maintain visibility into such traffic from a monitoring perspective. Organizations determine whether the visibility requirement applies to internal encrypted traffic, encrypted traffic intended for external destinations, or a subset of the traffic types. Related Controls:  None. (11) SYSTEM MONITORING | ANALYZE COMMUNICATIONS TRAFFIC ANOMALIES', 'vec_doc-14-nist-sp-800-53-p366-1421', 0, 118, 'v2.1.0', '7b4f6b49400d637503b572d1ea539b330c78c8bc3ab4684386dbd2e48ef0bec0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 339","subsection":"UNKNOWN","table_id":null,"page":366,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1421,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 339"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p367-1422', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 340', 367, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Analyze outbound communications traffic at the external interfaces to the system and selected [Assignment: organization-defined interior points within the system] to discover anomalies. Discussion:  Organization-defined interior points include subnetworks and subsystems. Anomalies within organizational systems include large file transfers, long-time persistent connections, attempts to access information from unexpected locations, the use of unusual protocols and ports, the use of unmonitored network protocols (e.g., IPv6 usage during IPv4 transition), and attempted communications with suspected malicious external addresses. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p367-1422', 0, 187, 'v2.1.0', '5e2ca09592e33383cf450b95fd2f254cca81e66f119d3f89c8970f07f548f707', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 340","subsection":"UNKNOWN","table_id":null,"page":367,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1422,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 340"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p367-1423', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 340', 367, '(12) SYSTEM MONITORING | AUTOMATED ORGANIZATION-GENERATED ALERTS Alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms] when the following indications of inappropriate or unusual activities with security or privacy implications occur: [Assignment: organization-defined activities that trigger alerts]. Discussion:  Organizational personnel on the system alert notification list include system administrators, mission or business owners, system owners, senior agency information security officer, senior agency official for privacy, system security officers, or privacy officers. Automated organization-generated alerts are the security alerts generated by organizations and transmitted using automated means. The sources for organization-generated alerts are focused on other entities such as suspicious activity reports and reports on potential insider threats.', 'vec_doc-14-nist-sp-800-53-p367-1423', 0, 233, 'v2.1.0', '3252b8d3baeea35a8ada882d5b9dbff4249c2a0e68c7a7a7487a132ce7193f96', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 340","subsection":"UNKNOWN","table_id":null,"page":367,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1423,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 340"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p367-1424', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 340', 367, 'In contrast to alerts generated by the organization, alerts generated by the system in SI-4(5) focus on information sources that are internal to the systems, such as audit records. Related Controls:  None. (13) SYSTEM MONITORING | ANALYZE TRAFFIC AND EVENT PATTERNS (a) Analyze communications traffic and event patterns for the system; (b) Develop profiles representing common traffic and event patterns; and (c) Use the traffic and event profiles in tuning system-monitoring devices. Discussion:  Identifying and understanding common communications traffic and event patterns help organizations provide useful information to system monitoring devices to more effectively identify suspicious or anomalous traffic and events when they occur. Such information can help reduce the number of false positives and false negatives during system monitoring. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p367-1424', 0, 219, 'v2.1.0', 'fe7029d8f64d4bc6d57b29ecc13ca103e2c1ddf5a57de61833b174ead827989b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 340","subsection":"UNKNOWN","table_id":null,"page":367,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1424,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 340"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p367-1425', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 340', 367, '(14) SYSTEM MONITORING | WIRELESS INTRUSION DETECTION Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system. Discussion:  Wireless signals may radiate beyond organizational facilities. Organizations proactively search for unauthorized wireless connections, including the conduct of thorough scans for unauthorized wireless access points. Wireless scans are not limited to those areas within facilities containing systems but also include areas outside of facilities to verify that unauthorized wireless access points are not connected to organizational systems. Related Controls:  AC-18, IA-3. (15) SYSTEM MONITORING | WIRELESS TO WIRELINE COMMUNICATIONS Employ an intrusion detection system to monitor wireless communications traffic as the traffic passes from wireless to wireline networks.', 'vec_doc-14-nist-sp-800-53-p367-1425', 0, 225, 'v2.1.0', '1546a8016e9531128146a28acf720f2577c5e4cf8b79325ad08a902a91e407ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 340","subsection":"UNKNOWN","table_id":null,"page":367,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1425,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 340"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p368-1426', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 341', 368, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Wireless networks are inherently less secure than wired networks. For example, wireless networks are more susceptible to eavesdroppers or traffic analysis than wireline networks. When wireless to wireline communications exist, the wireless network could become a port of entry into the wired network. Given the greater facility of unauthorized network access via wireless access points compared to unauthorized wired network access from within the physical boundaries of the system, additional monitoring of transitioning traffic between wireless and wired networks may be necessary to detect malicious activities. Employing intrusion detection systems to monitor wireless communications traffic helps to ensure that the traffic does not contain malicious code prior to transitioning to the wireline network. Related Controls:  AC-18.', 'vec_doc-14-nist-sp-800-53-p368-1426', 0, 235, 'v2.1.0', 'f86e187eaad32ff81cfe86709c4b8f363d524b9a389e6aa6d8221c61883eb871', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 341","subsection":"UNKNOWN","table_id":null,"page":368,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1426,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 341"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p368-1427', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 341', 368, '(16) SYSTEM MONITORING | CORRELATE MONITORING INFORMATION Correlate information from monitoring tools and mechanisms employed throughout the system. Discussion:  Correlating information from different system monitoring tools and mechanisms can provide a more comprehensive view of system activity. Correlating system monitoring tools and mechanisms that typically work in isolation— including malicious code protection software, host monitoring, and network monitoring— can provide an organization-wide monitoring view and may reveal otherwise unseen attack patterns. Understanding the capabilities and limitations of diverse monitoring tools and mechanisms and how to maximize the use of information generated by those tools and mechanisms can help organizations develop, operate, and maintain effective monitoring programs.', 'vec_doc-14-nist-sp-800-53-p368-1427', 0, 207, 'v2.1.0', 'ee26df695733767c44f987152f1956a4e0387bf1e3c2f22403f504c6f852ff36', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 341","subsection":"UNKNOWN","table_id":null,"page":368,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1427,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 341"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p368-1428', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 341', 368, 'The correlation of monitoring information is especially important during the transition from older to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Related Controls:  AU-6. (17) SYSTEM MONITORING | INTEGRATED SITUATIONAL AWARENESS Correlate information from monitoring physical, cyber, and supply chain activities to achieve integrated, organization-wide situational awareness. Discussion:  Correlating monitoring information from a more diverse set of information sources helps to achieve integrated situational awareness. Integrated situational awareness from a combination of physical, cyber, and supply chain monitoring activities enhances the capability of organizations to more quickly detect sophisticated attacks and investigate the methods and techniques employed to carry out such attacks.', 'vec_doc-14-nist-sp-800-53-p368-1428', 0, 208, 'v2.1.0', '607456fb1dcb965660a4687b0ef79259c780c06f98ac0921e3b2429f09f26610', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 341","subsection":"UNKNOWN","table_id":null,"page":368,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1428,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 341"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p368-1429', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 341', 368, 'In contrast to SI-4(16), which correlates the various cyber monitoring information, integrated situational awareness is intended to correlate monitoring beyond the cyber domain. Correlation of monitoring information from multiple activities may help reveal attacks on organizations that are operating across multiple attack vectors. Related Controls:  AU-16, PE-6, SR-2, SR-4, SR-6. (18) SYSTEM MONITORING | ANALYZE TRAFFIC AND COVERT EXFILTRATION Analyze outbound communications traffic at external interfaces to the system and at the following interior points to detect covert exfiltration of information: [Assignment: organization-defined interior points within the system]. Discussion:  Organization-defined interior points include subnetworks and subsystems. Covert means that can be used to exfiltrate information include steganography. Related Controls:  None. (19) SYSTEM MONITORING | RISK FOR INDIVIDUALS', 'vec_doc-14-nist-sp-800-53-p368-1429', 0, 229, 'v2.1.0', 'ef8df4803823df9f1bf96bbcd8b006f5d55be138e7239938c059a88806fee804', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 341","subsection":"UNKNOWN","table_id":null,"page":368,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1429,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 341"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p369-1430', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 342', 369, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Implement [Assignment: organization-defined additional monitoring] of individuals who have been identified by [Assignment: organization-defined sources] as posing an increased level of risk. Discussion:  Indications of increased risk from individuals can be obtained from different sources, including personnel records, intelligence agencies, law enforcement organizations, and other sources. The monitoring of individuals is coordinated with the management, legal, security, privacy, and human resource officials who conduct such monitoring. Monitoring is conducted in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Related Controls:  None. (20) SYSTEM MONITORING | PRIVILEGED USERS Implement the following additional monitoring of privileged users: [Assignment: organization-defined additional monitoring].', 'vec_doc-14-nist-sp-800-53-p369-1430', 0, 242, 'v2.1.0', '34509f0332df5d2e7e84df12ad3d64c5393a89617772c44ab7316a14939d4e7e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 342","subsection":"UNKNOWN","table_id":null,"page":369,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1430,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 342"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p369-1431', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 342', 369, 'Discussion:  Privileged users have access to more sensitive information, including security- related information, than the general user population. Access to such information means that privileged users can potentially do greater damage to systems and organizations than non-privileged users. Therefore, implementing additional monitoring on privileged users helps to ensure that organizations can identify malicious activity at the earliest possible time and take appropriate actions. Related Controls:  AC-18. (21) SYSTEM MONITORING | PROBATIONARY PERIODS Implement the following additional monitoring of individuals during [Assignment: organization-defined probationary period]: [Assignment: organization-defined additional monitoring]. Discussion:  During probationary periods, employees do not have permanent employment status within organizations.', 'vec_doc-14-nist-sp-800-53-p369-1431', 0, 214, 'v2.1.0', 'c349151f12a4c7afe372af9cb771452115580614979b5484779870c5fdeeaef2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 342","subsection":"UNKNOWN","table_id":null,"page":369,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1431,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 342"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p369-1432', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 342', 369, 'Without such status or access to information that is resident on the system, additional monitoring can help identify any potentially malicious activity or inappropriate behavior. Related Controls:  AC-18. (22) SYSTEM MONITORING | UNAUTHORIZED NETWORK SERVICES (a) Detect network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes]; and (b) [Selection (one or more): Audit; Alert [Assignment: organization-defined personnel or roles]] when detected. Discussion:  Unauthorized or unapproved network services include services in service- oriented architectures that lack organizational verification or validation and may therefore be unreliable or serve as malicious rogues for valid services. Related Controls:  CM-7.', 'vec_doc-14-nist-sp-800-53-p369-1432', 0, 197, 'v2.1.0', 'd665932a900028cf8953237d99a0381df82f5873192bd9dd67d437977ffc20ce', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 342","subsection":"UNKNOWN","table_id":null,"page":369,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1432,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 342"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p369-1433', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 342', 369, '(23) SYSTEM MONITORING | HOST-BASED DEVICES Implement the following host-based monitoring mechanisms at [Assignment: organization-defined system components]: [Assignment: organization-defined host-based monitoring mechanisms]. Discussion:  Host-based monitoring collects information about the host (or system in which it resides). System components in which host-based monitoring can be implemented include servers, notebook computers, and mobile devices. Organizations may consider employing host-based monitoring mechanisms from multiple product developers or vendors. Related Controls:  AC-18, AC-19.', 'vec_doc-14-nist-sp-800-53-p369-1433', 0, 151, 'v2.1.0', '1cc39eee6274383eca7e7c84e5d755f545da2a7a204f5a19d623b79fbfea6fba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 342","subsection":"UNKNOWN","table_id":null,"page":369,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1433,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 342"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p370-1434', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 343', 370, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (24) SYSTEM MONITORING | INDICATORS OF COMPROMISE Discover, collect, and distribute to [Assignment: organization-defined personnel or roles], indicators of compromise provided by [Assignment: organization-defined sources]. Discussion:  Indicators of compromise (IOC) are forensic artifacts from intrusions that are identified on organizational systems at the host or network level. IOCs provide valuable information on systems that have been compromised. IOCs can include the creation of registry key values. IOCs for network traffic include Universal Resource Locator or protocol elements that indicate malicious code command and control servers. The rapid distribution and adoption of IOCs can improve information security by reducing the time that systems and organizations are vulnerable to the same exploit or attack.', 'vec_doc-14-nist-sp-800-53-p370-1434', 0, 229, 'v2.1.0', '452ac43dbfc5291747b31af26ed22f428b7fa41b7e6ee40515d315c3e0358160', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 343","subsection":"UNKNOWN","table_id":null,"page":370,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1434,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 343"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p370-1435', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 343', 370, 'Threat indicators, signatures, tactics, techniques, procedures, and other indicators of compromise may be available via government and non-government cooperatives, including the Forum of Incident Response and Security Teams, the United States Computer Emergency Readiness Team, the Defense Industrial Base Cybersecurity Information Sharing Program, and the CERT Coordination Center. Related Controls:  AC-18. (25) SYSTEM MONITORING | OPTIMIZE NETWORK TRAFFIC ANALYSIS Provide visibility into network traffic at external and key internal system interfaces to optimize the effectiveness of monitoring devices. Discussion:  Encrypted traffic, asymmetric routing architectures, capacity and latency limitations, and transitioning from older to newer technologies (e.g., IPv4 to IPv6 network protocol transition) may result in blind spots for organizations when analyzing network traffic.', 'vec_doc-14-nist-sp-800-53-p370-1435', 0, 221, 'v2.1.0', '749bafad8697f232a80c7b7097888ff8263a3b3f5e99750e2e6e9b83f163714f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 343","subsection":"UNKNOWN","table_id":null,"page":370,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1435,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 343"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p370-1436', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 343', 370, 'Collecting, decrypting, pre-processing, and distributing only relevant traffic to monitoring devices can streamline the efficiency and use of devices and optimize traffic analysis. Related Controls:  None. References:  [OMB A-130], [FIPS 140-3], [SP 800-61], [SP 800-83], [SP 800-92], [SP 800-94], [SP 800-137]. SI-5 SECURITY ALERTS, ADVISORIES, AND DIRECTIVES Control: a. Receive system security alerts, advisories, and directives from [Assignment: organization- defined external organizations] on an ongoing basis; b. Generate internal security alerts, advisories, and directives as deemed necessary; c. Disseminate security alerts, advisories, and directives to: [Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements within the organization]; [Assignment: organization-defined external organizations]]; and d.', 'vec_doc-14-nist-sp-800-53-p370-1436', 0, 221, 'v2.1.0', '9c2c2cf5c7d0a3b175ebd37e1c2ad5879bf5f4c327edcd4d62e9147d9a168a3f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 343","subsection":"UNKNOWN","table_id":null,"page":370,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1436,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 343"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p370-1437', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 343', 370, 'Implement security directives in accordance with established time frames, or notify the issuing organization of the degree of noncompliance. Discussion:  The Cybersecurity and Infrastructure Security Agency (CISA) generates security alerts and advisories to maintain situational awareness throughout the Federal Government. Security directives are issued by OMB or other designated organizations with the responsibility and authority to issue such directives. Compliance with security directives is essential due to the critical nature of many of these directives and the potential (immediate) adverse effects on organizational operations and assets, individuals, other organizations, and the Nation should the directives not be implemented in a timely manner. External organizations include supply chain', 'vec_doc-14-nist-sp-800-53-p370-1437', 0, 201, 'v2.1.0', '8ace972a7aadfefa66dee73263c773181476fa6e8ba9fe82f3e39719750c7ff9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 343","subsection":"UNKNOWN","table_id":null,"page":370,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1437,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 343"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p371-1438', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 344', 371, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 partners, external mission or business partners, external service providers, and other peer or supporting organizations. Related Controls:  PM-15, RA-5, SI-2. Control Enhancements: (1) SECURITY ALERTS, ADVISORIES, AND DIRECTIVES | AUTOMATED ALERTS AND ADVISORIES Broadcast security alert and advisory information throughout the organization using [Assignment: organization-defined automated mechanisms]. Discussion:  The significant number of changes to organizational systems and environments of operation requires the dissemination of security-related information to a variety of organizational entities that have a direct interest in the success of organizational mission and business functions.', 'vec_doc-14-nist-sp-800-53-p371-1438', 0, 198, 'v2.1.0', 'a44b656ddca31aad406b05ad79bbd8d5e060aa72200c3758687c21db6d6babe8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 344","subsection":"UNKNOWN","table_id":null,"page":371,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1438,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 344"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p371-1439', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 344', 371, 'Based on information provided by security alerts and advisories, changes may be required at one or more of the three levels related to the management of risk, including the governance level, mission and business process level, and the information system level. Related Controls:  None. References:  [SP 800-40]. SI-6 SECURITY AND PRIVACY FUNCTION VERIFICATION Control: a. Verify the correct operation of [Assignment: organization-defined security and privacy functions]; b. Perform the verification of the functions specified in SI-6a [Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]]; c. Alert [Assignment: organization-defined personnel or roles] to failed security and privacy verification tests; and d. [Selection (one or more): Shut the system down; Restart the system; [Assignment: organization-defined alternative action(s)]] when anomalies are discovered.', 'vec_doc-14-nist-sp-800-53-p371-1439', 0, 250, 'v2.1.0', 'f811f01a36523b21096f63863d76ca3f04d79789e66a176ff61943e5f7a24aa8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 344","subsection":"UNKNOWN","table_id":null,"page":371,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1439,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 344"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p371-1440', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 344', 371, 'Discussion:  Transitional states for systems include system startup, restart, shutdown, and abort. System notifications include hardware indicator lights, electronic alerts to system administrators, and messages to local computer consoles. In contrast to security function verification, privacy function verification ensures that privacy functions operate as expected and are approved by the senior agency official for privacy or that privacy attributes are applied or used as expected. Related Controls:  CA-7, CM-4, CM-6, SI-7. Control Enhancements: (1) SECURITY AND PRIVACY FUNCTION VERIFICATION | NOTIFICATION OF FAILED SECURITY TESTS [Withdrawn: Incorporated into SI-6.] (2) SECURITY AND PRIVACY FUNCTION VERIFICATION | AUTOMATION SUPPORT FOR DISTRIBUTED TESTING Implement automated mechanisms to support the management of distributed security and privacy function testing.', 'vec_doc-14-nist-sp-800-53-p371-1440', 0, 220, 'v2.1.0', '84a823838c06c2be8e84b4f58e07fc63150036a6d44885c4b8314095d28d86b6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 344","subsection":"UNKNOWN","table_id":null,"page":371,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1440,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 344"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p372-1441', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 345', 372, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The use of automated mechanisms to support the management of distributed function testing helps to ensure the integrity, timeliness, completeness, and efficacy of such testing. Related Controls:  SI-2. (3) SECURITY AND PRIVACY FUNCTION VERIFICATION | REPORT VERIFICATION RESULTS Report the results of security and privacy function verification to [Assignment: organization-defined personnel or roles]. Discussion:  Organizational personnel with potential interest in the results of the verification of security and privacy functions include systems security officers, senior agency information security officers, and senior agency officials for privacy. Related Controls:  SI-4, SR-4, SR-5. References:  [OMB A-130]. SI-7 SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY Control: a.', 'vec_doc-14-nist-sp-800-53-p372-1441', 0, 221, 'v2.1.0', 'a78acec918f074cecfa70879763f75e1e2fff2cb7d9d031e45150cd77d2fb75c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 345","subsection":"UNKNOWN","table_id":null,"page":372,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1441,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 345"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p372-1442', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 345', 372, 'Employ integrity verification tools to detect unauthorized changes to the following software, firmware, and information: [Assignment: organization-defined software, firmware, and information]; and b. Take the following actions when unauthorized changes to the software, firmware, and information are detected: [Assignment: organization-defined actions]. Discussion:  Unauthorized changes to software, firmware, and information can occur due to errors or malicious activity. Software includes operating systems (with key internal components, such as kernels or drivers), middleware, and applications. Firmware interfaces include Unified Extensible Firmware Interface (UEFI) and Basic Input/Output System (BIOS). Information includes personally identifiable information and metadata that contains security and privacy attributes associated with information.', 'vec_doc-14-nist-sp-800-53-p372-1442', 0, 214, 'v2.1.0', '3bf5ed753929f5769e55b1312723265c8f46223bc973c13ef0bd618f46bd9248', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 345","subsection":"UNKNOWN","table_id":null,"page":372,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1442,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 345"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p372-1443', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 345', 372, 'Integrity-checking mechanisms— including parity checks, cyclical redundancy checks, cryptographic hashes, and associated tools— can automatically monitor the integrity of systems and hosted applications. Related Controls:  AC-4, CM-3, CM-7, CM-8, MA-3, MA-4, RA-5, SA-8, SA-9, SA-10, SC-8, SC-12, SC-13, SC-28, SC-37, SI-3, SR-3, SR-4, SR-5, SR-6, SR-9, SR-10, SR-11. Control Enhancements: (1) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | INTEGRITY CHECKS Perform an integrity check of [Assignment: organization-defined software, firmware, and information] [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]. Discussion:  Security-relevant events include the identification of new threats to which organizational systems are susceptible and the installation of new hardware, software, or firmware. Transitional states include system startup, restart, shutdown, and abort.', 'vec_doc-14-nist-sp-800-53-p372-1443', 0, 249, 'v2.1.0', '4c951e22a184dce5ef8166e55d85c931ba4dde3eba83c6c447b56be4526bb678', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 345","subsection":"UNKNOWN","table_id":null,"page":372,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1443,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 345"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p372-1444', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 345', 372, 'Related Controls:  None. (2) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | AUTOMATED NOTIFICATIONS OF INTEGRITY VIOLATIONS Employ automated tools that provide notification to [Assignment: organization-defined personnel or roles] upon discovering discrepancies during integrity verification.', 'vec_doc-14-nist-sp-800-53-p372-1444', 0, 73, 'v2.1.0', '09a545e0142b232ed2809892c3c95476d8739e90562af2c65765f775053ce47b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 345","subsection":"UNKNOWN","table_id":null,"page":372,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1444,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 345"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p373-1445', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 346', 373, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  The employment of automated tools to report system and information integrity violations and to notify organizational personnel in a timely matter is essential to effective risk response. Personnel with an interest in system and information integrity violations include mission and business owners, system owners, senior agency information security official, senior agency official for privacy, system administrators, software developers, systems integrators, information security officers, and privacy officers. Related Controls:  None. (3) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CENTRALLY MANAGED INTEGRITY TOOLS Employ centrally managed integrity verification tools. Discussion:  Centrally managed integrity verification tools provides greater consistency in the application of such tools and can facilitate more comprehensive coverage of integrity verification actions.', 'vec_doc-14-nist-sp-800-53-p373-1445', 0, 247, 'v2.1.0', '690ff22f1ca92947f5f25ccde641a379c26c10d29945be664a7b48bfe9573659', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 346","subsection":"UNKNOWN","table_id":null,"page":373,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1445,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 346"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p373-1446', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 346', 373, 'Related Controls:  AU-3, SI-2, SI-8. (4) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | TAMPER-EVIDENT PACKAGING [Withdrawn: Incorporated into SR-9.] (5) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | AUTOMATED RESPONSE TO INTEGRITY VIOLATIONS Automatically [Selection (one or more): shut the system down; restart the system; implement [Assignment: organization-defined controls]] when integrity violations are discovered. Discussion:  Organizations may define different integrity-checking responses by type of information, specific information, or a combination of both. Types of information include firmware, software, and user data. Specific information includes boot firmware for certain types of machines. The automatic implementation of controls within organizational systems includes reversing the changes, halting the system, or triggering audit alerts when unauthorized modifications to critical security files occur. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p373-1446', 0, 239, 'v2.1.0', '861bbd333a8f85750875ab4d549db9f7924f1f213eb9e7e8839e1d6fd2dd1477', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 346","subsection":"UNKNOWN","table_id":null,"page":373,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1446,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 346"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p373-1447', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 346', 373, '(6) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CRYPTOGRAPHIC PROTECTION Implement cryptographic mechanisms to detect unauthorized changes to software, firmware, and information. Discussion:  Cryptographic mechanisms used to protect integrity include digital signatures and the computation and application of signed hashes using asymmetric cryptography, protecting the confidentiality of the key used to generate the hash, and using the public key to verify the hash information. Organizations that employ cryptographic mechanisms also consider cryptographic key management solutions. Related Controls:  SC-12, SC-13. (7) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | INTEGRATION OF DETECTION AND RESPONSE Incorporate the detection of the following unauthorized changes into the organizational incident response capability: [Assignment: organization-defined security-relevant changes to the system].', 'vec_doc-14-nist-sp-800-53-p373-1447', 0, 227, 'v2.1.0', '2ad4914865674558602cc5e5c0e7218f7701743ce2760938d1329b64fdda6dfc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 346","subsection":"UNKNOWN","table_id":null,"page":373,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1447,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 346"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p373-1448', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 346', 373, 'Discussion:  Integrating detection and response helps to ensure that detected events are tracked, monitored, corrected, and available for historical purposes. Maintaining historical records is important for being able to identify and discern adversary actions over an extended time period and for possible legal actions. Security-relevant changes include', 'vec_doc-14-nist-sp-800-53-p373-1448', 0, 89, 'v2.1.0', 'cf441b419106e0dbd69f08b7371d7e762fbf13cd84985e6d37ee500d7facb035', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 346","subsection":"UNKNOWN","table_id":null,"page":373,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1448,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 346"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p374-1449', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 347', 374, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 unauthorized changes to established configuration settings or the unauthorized elevation of system privileges. Related Controls:  AU-2, AU-6, IR-4, IR-5, SI-4. (8) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | AUDITING CAPABILITY FOR SIGNIFICANT EVENTS Upon detection of a potential integrity violation, provide the capability to audit the event and initiate the following actions: [Selection (one or more): generate an audit record; alert current user; alert [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined other actions]]. Discussion:  Organizations select response actions based on types of software, specific software, or information for which there are potential integrity violations. Related Controls:  AU-2, AU-6, AU-12.', 'vec_doc-14-nist-sp-800-53-p374-1449', 0, 216, 'v2.1.0', 'c2780abc14823c9ba87b8e9b5e33789a0ea04adc9e39c5657b6b76e6b6af0bba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 347","subsection":"UNKNOWN","table_id":null,"page":374,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1449,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 347"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p374-1450', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 347', 374, '(9) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | VERIFY BOOT PROCESS Verify the integrity of the boot process of the following system components: [Assignment: organization-defined system components]. Discussion:  Ensuring the integrity of boot processes is critical to starting system components in known, trustworthy states. Integrity verification mechanisms provide a level of assurance that only trusted code is executed during boot processes. Related Controls:  SI-6. (10) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | PROTECTION OF BOOT FIRMWARE Implement the following mechanisms to protect the integrity of boot firmware in [Assignment: organization-defined system components]: [Assignment: organization- defined mechanisms]. Discussion:  Unauthorized modifications to boot firmware may indicate a sophisticated, targeted attack. These types of targeted attacks can result in a permanent denial of service or a persistent malicious code presence.', 'vec_doc-14-nist-sp-800-53-p374-1450', 0, 240, 'v2.1.0', 'c475b2b97a70777127437837ed34bd5bf7d228701d3ce19d0290af6a71576ed9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 347","subsection":"UNKNOWN","table_id":null,"page":374,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1450,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 347"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p374-1451', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 347', 374, 'These situations can occur if the firmware is corrupted or if the malicious code is embedded within the firmware. System components can protect the integrity of boot firmware in organizational systems by verifying the integrity and authenticity of all updates to the firmware prior to applying changes to the system component and preventing unauthorized processes from modifying the boot firmware. Related Controls:  SI-6. (11) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CONFINED ENVIRONMENTS WITH LIMITED PRIVILEGES [Withdrawn: Moved to CM-7(6).] (12) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | INTEGRITY VERIFICATION Require that the integrity of the following user-installed software be verified prior to execution: [Assignment: organization-defined user-installed software]. Discussion:  Organizations verify the integrity of user-installed software prior to execution to reduce the likelihood of executing malicious code or programs that contains errors from unauthorized modifications.', 'vec_doc-14-nist-sp-800-53-p374-1451', 0, 251, 'v2.1.0', 'd0ed226171311f5ec6bab96e7fe46faced131001f2694d92f2c88d821cc562ee', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 347","subsection":"UNKNOWN","table_id":null,"page":374,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1451,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 347"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p374-1452', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 347', 374, 'Organizations consider the practicality of approaches to verifying software integrity, including the availability of trustworthy checksums from software developers and vendors. Related Controls:  CM-11. (13) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CODE EXECUTION IN PROTECTED ENVIRONMENTS', 'vec_doc-14-nist-sp-800-53-p374-1452', 0, 74, 'v2.1.0', '688e3dd1cc4e129e03410161558ddddbbe70f24af1763c3b8b36ddc15aad228b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 347","subsection":"UNKNOWN","table_id":null,"page":374,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1452,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 347"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p375-1453', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 348', 375, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [Withdrawn: Moved to CM-7(7).] (14) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | BINARY OR MACHINE EXECUTABLE CODE [Withdrawn: Moved to CM-7(8).] (15) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CODE AUTHENTICATION Implement cryptographic mechanisms to authenticate the following software or firmware components prior to installation: [Assignment: organization-defined software or firmware components]. Discussion:  Cryptographic authentication includes verifying that software or firmware components have been digitally signed using certificates recognized and approved by organizations. Code signing is an effective method to protect against malicious code. Organizations that employ cryptographic mechanisms also consider cryptographic key management solutions. Related Controls:  CM-5, SC-12, SC-13.', 'vec_doc-14-nist-sp-800-53-p375-1453', 0, 226, 'v2.1.0', '18612f2058c84c2a8c21dff9a4c29931d0ccfc19cabf3991613479c57f730681', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 348","subsection":"UNKNOWN","table_id":null,"page":375,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1453,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 348"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p375-1454', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 348', 375, '(16) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | TIME LIMIT ON PROCESS EXECUTION WITHOUT SUPERVISION Prohibit processes from executing without supervision for more than [Assignment: organization-defined time period]. Discussion:  Placing a time limit on process execution without supervision is intended to apply to processes for which typical or normal execution periods can be determined and situations in which organizations exceed such periods. Supervision includes timers on operating systems, automated responses, and manual oversight and response when system process anomalies occur. Related Controls:  None. (17) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | RUNTIME APPLICATION SELF-PROTECTION Implement [Assignment: organization-defined controls] for application self-protection at runtime.', 'vec_doc-14-nist-sp-800-53-p375-1454', 0, 202, 'v2.1.0', '0cd8d5ffa2232981f0a84565168fa50dd087524e780bae9f417467895e4a2a34', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 348","subsection":"UNKNOWN","table_id":null,"page":375,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1454,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 348"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p375-1455', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 348', 375, 'Discussion:  Runtime application self-protection employs runtime instrumentation to detect and block the exploitation of software vulnerabilities by taking advantage of information from the software in execution. Runtime exploit prevention differs from traditional perimeter-based protections such as guards and firewalls which can only detect and block attacks by using network information without contextual awareness. Runtime application self-protection technology can reduce the susceptibility of software to attacks by monitoring its inputs and blocking those inputs that could allow attacks. It can also help protect the runtime environment from unwanted changes and tampering. When a threat is detected, runtime application self-protection technology can prevent exploitation and take other actions (e.g., sending a warning message to the user, terminating the user''s session, terminating the application, or sending an alert to organizational personnel).', 'vec_doc-14-nist-sp-800-53-p375-1455', 0, 241, 'v2.1.0', '56b5e122098e2f1e59e2f3be6d5657be17ae820452a032a262f6c4a2ea9be461', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 348","subsection":"UNKNOWN","table_id":null,"page":375,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1455,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 348"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p375-1456', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 348', 375, 'Runtime application self-protection solutions can be deployed in either a monitor or protection mode. Related Controls:  SI-16. References:  [OMB A-130], [FIPS 140-3], [FIPS 180-4], [FIPS 186-4], [FIPS 202], [SP 800-70], [SP 800-147]. SI-8 SPAM PROTECTION Control:', 'vec_doc-14-nist-sp-800-53-p375-1456', 0, 66, 'v2.1.0', 'e092fb50681d0049d75f568e950565f5b08cf659b067393e79c90fb0fc2af045', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 348","subsection":"UNKNOWN","table_id":null,"page":375,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1456,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 348"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p376-1457', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 349', 376, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; and b. Update spam protection mechanisms when new releases are available in accordance with organizational configuration management policy and procedures. Discussion:  System entry and exit points include firewalls, remote-access servers, electronic mail servers, web servers, proxy servers, workstations, notebook computers, and mobile devices. Spam can be transported by different means, including email, email attachments, and web accesses. Spam protection mechanisms include signature definitions. Related Controls:  PL-9, SC-5, SC-7, SC-38, SI-3, SI-4. Control Enhancements: (1) SPAM PROTECTION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) SPAM PROTECTION | AUTOMATIC UPDATES Automatically update spam protection mechanisms [Assignment: organization-defined frequency].', 'vec_doc-14-nist-sp-800-53-p376-1457', 0, 249, 'v2.1.0', '49ddba41afacab37dbffdd67e58a78b188ab52f08523147aaf74fc089ad18cc4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 349","subsection":"UNKNOWN","table_id":null,"page":376,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1457,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 349"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p376-1458', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 349', 376, 'Discussion:  Using automated mechanisms to update spam protection mechanisms helps to ensure that updates occur on a regular basis and provide the latest content and protection capabilities. Related Controls:  None. (3) SPAM PROTECTION |CONTINUOUS LEARNING CAPABILITY Implement spam protection mechanisms with a learning capability to more effectively identify legitimate communications traffic. Discussion:  Learning mechanisms include Bayesian filters that respond to user inputs that identify specific traffic as spam or legitimate by updating algorithm parameters and thereby more accurately separating types of traffic. Related Controls:  None. References:  [SP 800-45], [SP 800-177]. SI-9 INFORMATION INPUT RESTRICTIONS [Withdrawn: Incorporated into AC-2, AC-3, AC-5, and AC-6.] SI-10  INFORMATION INPUT VALIDATION Control:  Check the validity of the following information inputs: [Assignment: organization- defined information inputs to the system].', 'vec_doc-14-nist-sp-800-53-p376-1458', 0, 239, 'v2.1.0', 'f3596af130b41e4e5b9b4caf74148ebfc037337b320e8ee2dd54bc4154ec1aed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 349","subsection":"UNKNOWN","table_id":null,"page":376,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1458,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 349"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p376-1459', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 349', 376, 'Discussion:  Checking the valid syntax and semantics of system inputs— including character set, length, numerical range, and acceptable values— verifies that inputs match specified definitions for format and content. For example, if the organization specifies that numerical values between 1-100 are the only acceptable inputs for a field in a given application, inputs of “387,” “abc,” or “%K%” are invalid inputs and are not accepted as input to the system. Valid inputs are likely to vary from field to field within a software application. Applications typically follow well-defined protocols that use structured messages (i.e., commands or queries) to communicate between software modules or system components. Structured messages can contain raw or unstructured data interspersed with metadata or control information.', 'vec_doc-14-nist-sp-800-53-p376-1459', 0, 206, 'v2.1.0', '97f3bae453e5c59e6dff11791d3d579cf59fd2400be65afaf85d245a03d91c84', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 349","subsection":"UNKNOWN","table_id":null,"page":376,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1459,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 349"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p376-1460', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 349', 376, 'If software applications use attacker- supplied inputs to construct structured messages without properly encoding such messages, then the attacker could insert malicious commands or special characters that can cause the data', 'vec_doc-14-nist-sp-800-53-p376-1460', 0, 56, 'v2.1.0', '259426483374697300f7dfda200bd9ae0063ba5b6318b9becd135b044a75a0af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 349","subsection":"UNKNOWN","table_id":null,"page":376,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1460,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 349"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p377-1461', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 350', 377, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 to be interpreted as control information or metadata. Consequently, the module or component that receives the corrupted output will perform the wrong operations or otherwise interpret the data incorrectly. Prescreening inputs prior to passing them to interpreters prevents the content from being unintentionally interpreted as commands. Input validation ensures accurate and correct inputs and prevents attacks such as cross-site scripting and a variety of injection attacks. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p377-1461', 0, 148, 'v2.1.0', 'd5b1ed58641d0c7ed9e2c960624d3f9aadc69903331f7aaa50ba7397eb7f4a55', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 350","subsection":"UNKNOWN","table_id":null,"page":377,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1461,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 350"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p377-1462', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 350', 377, 'Control Enhancements: (1) INFORMATION INPUT VALIDATION | MANUAL OVERRIDE CAPABILITY (a) Provide a manual override capability for input validation of the following information inputs: [Assignment: organization-defined inputs defined in the base control (SI-10)]; (b) Restrict the use of the manual override capability to only [Assignment: organization- defined authorized individuals]; and (c) Audit the use of the manual override capability. Discussion:  In certain situations, such as during events that are defined in contingency plans, a manual override capability for input validation may be needed. Manual overrides are used only in limited circumstances and with the inputs defined by the organization. Related Controls:  AC-3, AU-2, AU-12. (2) INFORMATION INPUT VALIDATION | REVIEW AND RESOLVE ERRORS Review and resolve input validation errors within [Assignment: organization-defined time period].', 'vec_doc-14-nist-sp-800-53-p377-1462', 0, 227, 'v2.1.0', '54e6c2430662f240cb53bafc64e97e62513c417ae96913bb378e1d278368a0a1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 350","subsection":"UNKNOWN","table_id":null,"page":377,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1462,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 350"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p377-1463', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 350', 377, 'Discussion:  Resolution of input validation errors includes correcting systemic causes of errors and resubmitting transactions with corrected input. Input validation errors are those related to the information inputs defined by the organization in the base control (SI-10). Related Controls:  None. (3) INFORMATION INPUT VALIDATION | PREDICTABLE BEHAVIOR Verify that the system behaves in a predictable and documented manner when invalid inputs are received. Discussion:  A common vulnerability in organizational systems is unpredictable behavior when invalid inputs are received. Verification of system predictability helps ensure that the system behaves as expected when invalid inputs are received. This occurs by specifying system responses that allow the system to transition to known states without adverse, unintended side effects. The invalid inputs are those related to the information inputs defined by the organization in the base control (SI-10). Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p377-1463', 0, 246, 'v2.1.0', 'ba97b206376bfec9d3343b7482ccef871c63f3b063b1aab746b43115d61cce91', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 350","subsection":"UNKNOWN","table_id":null,"page":377,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1463,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 350"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p377-1464', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 350', 377, '(4) INFORMATION INPUT VALIDATION | TIMING INTERACTIONS Account for timing interactions among system components in determining appropriate responses for invalid inputs. Discussion:  In addressing invalid system inputs received across protocol interfaces, timing interactions become relevant, where one protocol needs to consider the impact of the error response on other protocols in the protocol stack. For example, 802.11 standard wireless network protocols do not interact well with Transmission Control Protocols (TCP) when packets are dropped (which could be due to invalid packet input). TCP assumes packet losses are due to congestion, while packets lost over 802.11 links are typically dropped due to noise or collisions on the link. If TCP makes a congestion response, it takes the wrong action in response to a collision event. Adversaries may be able to use what appear to be acceptable individual behaviors of the protocols in concert to achieve adverse effects through suitable', 'vec_doc-14-nist-sp-800-53-p377-1464', 0, 248, 'v2.1.0', '8a0958618ce554297e471cb9b132c1955517284a2c24cce287d6d6b2ec055455', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 350","subsection":"UNKNOWN","table_id":null,"page":377,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1464,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 350"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p378-1465', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 351', 378, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 construction of invalid input. The invalid inputs are those related to the information inputs defined by the organization in the base control (SI-10). Related Controls:  None. (5) INFORMATION INPUT VALIDATION | RESTRICT INPUTS TO TRUSTED SOURCES AND APPROVED FORMATS Restrict the use of information inputs to [Assignment: organization-defined trusted sources] and/or [Assignment: organization-defined formats]. Discussion:  Restricting the use of inputs to trusted sources and in trusted formats applies the concept of authorized or permitted software to information inputs. Specifying known trusted sources for information inputs and acceptable formats for such inputs can reduce the probability of malicious activity. The information inputs are those defined by the organization in the base control (SI-10). Related Controls:  AC-3, AC-6.', 'vec_doc-14-nist-sp-800-53-p378-1465', 0, 233, 'v2.1.0', '5d9fbeed8115dedccd88305bc42f2f49f4ebda63ef286d4008f6cc328171bf00', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 351","subsection":"UNKNOWN","table_id":null,"page":378,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1465,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 351"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p378-1466', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 351', 378, '(6) INFORMATION INPUT VALIDATION | INJECTION PREVENTION Prevent untrusted data injections. Discussion: Untrusted data injections may be prevented using a parameterized interface or output escaping (output encoding). Parameterized interfaces separate data from code so that injections of malicious or unintended data cannot change the semantics of commands being sent. Output escaping uses specified characters to inform the interpreter’s parser whether data is trusted. Prevention of untrusted data injections are with respect to the information inputs defined by the organization in the base control (SI-10). Related Controls:  AC-3, AC-6. References:  [OMB A-130]. SI-11 ERROR HANDLING Control: a. Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; and b. Reveal error messages only to [Assignment: organization-defined personnel or roles]. Discussion:  Organizations consider the structure and content of error messages.', 'vec_doc-14-nist-sp-800-53-p378-1466', 0, 253, 'v2.1.0', 'be1c77bb26c0c3700108ca61eac927f41090ac1b6bd03f4ac24cfe1615dfc9db', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 351","subsection":"UNKNOWN","table_id":null,"page":378,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1466,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 351"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p378-1467', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 351', 378, 'The extent to which systems can handle error conditions is guided and informed by organizational policy and operational requirements. Exploitable information includes stack traces and implementation details; erroneous logon attempts with passwords mistakenly entered as the username; mission or business information that can be derived from, if not stated explicitly by, the information recorded; and personally identifiable information, such as account numbers, social security numbers, and credit card numbers. Error messages may also provide a covert channel for transmitting information. Related Controls:  AU-2, AU-3, SC-31, SI-2, SI-15. Control Enhancements:  None. References:  None. SI-12 INFORMATION MANAGEMENT AND RETENTION Control:  Manage and retain information within the system and information output from the system in accordance with applicable laws, executive orders, directives, regulations, policies, standards, guidelines and operational requirements.', 'vec_doc-14-nist-sp-800-53-p378-1467', 0, 243, 'v2.1.0', '6ba5cc29e5df4cff2e181f515933fb51160188ab1f2492f0355514c976f21cf6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 351","subsection":"UNKNOWN","table_id":null,"page":378,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1467,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 351"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p379-1468', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 352', 379, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  Information management and retention requirements cover the full life cycle of information, in some cases extending beyond system disposal. Information to be retained may also include policies, procedures, plans, reports, data output from control implementation, and other types of administrative information. The National Archives and Records Administration (NARA) provides federal policy and guidance on records retention and schedules. If organizations have a records management office, consider coordinating with records management personnel.', 'vec_doc-14-nist-sp-800-53-p379-1468', 0, 163, 'v2.1.0', '9f4ba90eee1f69466f4f86fd447f38fe0cb2933acae16b7095749a18bcc3b09d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 352","subsection":"UNKNOWN","table_id":null,"page":379,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1468,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 352"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p379-1469', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 352', 379, 'Records produced from the output of implemented controls that may require management and retention include, but are not limited to: All XX-1, AC-6(9), AT-4, AU-12, CA-2, CA-3, CA-5, CA-6, CA-7, CA-8, CA-9, CM-2, CM-3, CM-4, CM-6, CM-8, CM-9, CM-12, CM-13, CP-2, IR-6, IR-8, MA-2, MA-4, PE-2, PE-8, PE-16, PE-17, PL-2, PL-4, PL-7, PL-8, PM-5, PM-8, PM-9, PM-18, PM-21, PM-27, PM-28, PM-30, PM-31, PS-2, PS-6, PS-7, PT-2, PT-3, PT-7, RA-2, RA-3, RA-5, RA-8, SA-4, SA-5, SA-8, SA-10, SI-4, SR-2, SR-4, SR-8. Related Controls:  All XX-1 Controls, AC-16, AU-5, AU-11, CA-2, CA-3, CA-5, CA-6, CA-7, CA-9, CM- 5, CM-9, CP-2, IR-8, MP-2, MP-3, MP-4, MP-6, PL-2, PL-4, PM-4, PM-8, PM-9, PS-2, PS-6, PT-2, PT- 3, RA-2, RA-3, SA-5, SA-8, SR-2.', 'vec_doc-14-nist-sp-800-53-p379-1469', 0, 183, 'v2.1.0', 'fc7bc1d84d4e43218ee9b7a1a770efc2cfbd8a6c23367d563e63f16d07bc557f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 352","subsection":"UNKNOWN","table_id":null,"page":379,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1469,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 352"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p379-1470', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 352', 379, 'Control Enhancements: (1) INFORMATION MANAGEMENT AND RETENTION | LIMIT PERSONALLY IDENTIFIABLE INFORMATION ELEMENTS Limit personally identifiable information being processed in the information life cycle to the following elements of personally identifiable information: [Assignment: organization- defined elements of personally identifiable information]. Discussion:  Limiting the use of personally identifiable information throughout the information life cycle when the information is not needed for operational purposes helps to reduce the level of privacy risk created by a system. The information life cycle includes information creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposition. Risk assessments as well as applicable laws, regulations, and policies can provide useful inputs to determining which elements of personally identifiable information may create risk. Related Controls:  PM-25.', 'vec_doc-14-nist-sp-800-53-p379-1470', 0, 237, 'v2.1.0', 'a3afdaf6e12479c03c8268304579c8045534c6a937cf8f837826f9aae66ebb9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 352","subsection":"UNKNOWN","table_id":null,"page":379,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1470,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 352"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p379-1471', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 352', 379, '(2) INFORMATION MANAGEMENT AND RETENTION | MINIMIZE PERSONALLY IDENTIFIABLE INFORMATION IN TESTING, TRAINING, AND RESEARCH Use the following techniques to minimize the use of personally identifiable information for research, testing, or training: [Assignment: organization-defined techniques]. Discussion:  Organizations can minimize the risk to an individual’s privacy by employing techniques such as de-identification or synthetic data. Limiting the use of personally identifiable information throughout the information life cycle when the information is not needed for research, testing, or training helps reduce the level of privacy risk created by a system. Risk assessments as well as applicable laws, regulations, and policies can provide useful inputs to determining the techniques to use and when to use them. Related Controls:  PM-22, PM-25, SI-19.', 'vec_doc-14-nist-sp-800-53-p379-1471', 0, 215, 'v2.1.0', '4bfbe48bbb515eb313ad0a6222dcbfeadb78ef682e37cf4c90e721f5de66a07e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 352","subsection":"UNKNOWN","table_id":null,"page":379,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1471,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 352"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p379-1472', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 352', 379, '(3) INFORMATION MANAGEMENT AND RETENTION | INFORMATION DISPOSAL Use the following techniques to dispose of, destroy, or erase information following the retention period: [Assignment: organization-defined techniques]. Discussion:  Organizations can minimize both security and privacy risks by disposing of information when it is no longer needed. The disposal or destruction of information applies to originals as well as copies and archived records, including system logs that may contain personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p379-1472', 0, 132, 'v2.1.0', '726c2b9307c2c441928a0c48d4f0e9906af439e5749fa5b29f16b788f8dedb5c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 352","subsection":"UNKNOWN","table_id":null,"page":379,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1472,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 352"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p380-1473', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 353', 380, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Related Controls:  None. References:  [USC 2901], [OMB A-130]. SI-13 PREDICTABLE FAILURE PREVENTION Control: a. Determine mean time to failure (MTTF) for the following system components in specific environments of operation: [Assignment: organization-defined system components]; and b. Provide substitute system components and a means to exchange active and standby components in accordance with the following criteria: [Assignment: organization-defined MTTF substitution criteria]. Discussion:  While MTTF is primarily a reliability issue, predictable failure prevention is intended to address potential failures of system components that provide security capabilities. Failure rates reflect installation-specific consideration rather than the industry-average.', 'vec_doc-14-nist-sp-800-53-p380-1473', 0, 214, 'v2.1.0', '934d325a4e3b635bedc34bf57eaad2a78e3c248de54ff7e343f3a95fc5f4a13a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 353","subsection":"UNKNOWN","table_id":null,"page":380,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1473,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 353"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p380-1474', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 353', 380, 'Organizations define the criteria for the substitution of system components based on the MTTF value with consideration for the potential harm from component failures. The transfer of responsibilities between active and standby components does not compromise safety, operational readiness, or security capabilities. The preservation of system state variables is also critical to help ensure a successful transfer process. Standby components remain available at all times except for maintenance issues or recovery failures in progress. Related Controls:  CP-2, CP-10, CP-13, MA-2, MA-6, SA-8, SC-6. Control Enhancements: (1) PREDICTABLE FAILURE PREVENTION | TRANSFERRING COMPONENT RESPONSIBILITIES Take system components out of service by transferring component responsibilities to substitute components no later than [Assignment: organization-defined fraction or percentage] of mean time to failure.', 'vec_doc-14-nist-sp-800-53-p380-1474', 0, 225, 'v2.1.0', '2e2d2ff602a72e069431f5497b94f8ffc4966d8ab22f951b7e940c691e896951', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 353","subsection":"UNKNOWN","table_id":null,"page":380,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1474,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 353"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p380-1475', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 353', 380, 'Discussion:  Transferring primary system component responsibilities to other substitute components prior to primary component failure is important to reduce the risk of degraded or debilitated mission or business functions. Making such transfers based on a percentage of mean time to failure allows organizations to be proactive based on their risk tolerance. However, the premature replacement of system components can result in the increased cost of system operations. Related Controls:  None. (2) PREDICTABLE FAILURE PREVENTION | TIME LIMIT ON PROCESS EXECUTION WITHOUT SUPERVISION [Withdrawn: Incorporated into SI-7(16).] (3) PREDICTABLE FAILURE PREVENTION | MANUAL TRANSFER BETWEEN COMPONENTS Manually initiate transfers between active and standby system components when the use of the active component reaches [Assignment: organization-defined percentage] of the mean time to failure.', 'vec_doc-14-nist-sp-800-53-p380-1475', 0, 223, 'v2.1.0', '85840a4c1e1034364da98250ee665fd5b10a795dab490525a809025aeedd2d1a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 353","subsection":"UNKNOWN","table_id":null,"page":380,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1475,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 353"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p380-1476', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 353', 380, 'Discussion:  For example, if the MTTF for a system component is 100 days and the MTTF percentage defined by the organization is 90 percent, the manual transfer would occur after 90 days. Related Controls:  None. (4) PREDICTABLE FAILURE PREVENTION | STANDBY COMPONENT INSTALLATION AND NOTIFICATION If system component failures are detected:', 'vec_doc-14-nist-sp-800-53-p380-1476', 0, 85, 'v2.1.0', '6b1e769b8fa418cb76d10c2adc808be8b55e2e2ed681baea6f61239fab0d8367', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 353","subsection":"UNKNOWN","table_id":null,"page":380,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1476,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 353"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p381-1477', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 354', 381, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (a) Ensure that the standby components are successfully and transparently installed within [Assignment: organization-defined time period]; and (b) [Selection (one or more): Activate [Assignment: organization-defined alarm]; Automatically shut down the system; [Assignment: organization-defined action]]. Discussion:  Automatic or manual transfer of components from standby to active mode can occur upon the detection of component failures. Related Controls:  None. (5) PREDICTABLE FAILURE PREVENTION | FAILOVER CAPABILITY Provide [Selection: real-time; near real-time] [Assignment: organization-defined failover capability] for the system. Discussion:  Failover refers to the automatic switchover to an alternate system upon the failure of the primary system.', 'vec_doc-14-nist-sp-800-53-p381-1477', 0, 213, 'v2.1.0', '47d09509229b88b540230a552be758f27c775375ce1893c284f12e9758be6d03', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 354","subsection":"UNKNOWN","table_id":null,"page":381,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1477,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 354"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p381-1478', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 354', 381, 'Failover capability includes incorporating mirrored system operations at alternate processing sites or periodic data mirroring at regular intervals defined by the recovery time periods of organizations. Related Controls:  CP-6, CP-7, CP-9. References:  None. SI-14 NON-PERSISTENCE Control:  Implement non-persistent [Assignment: organization-defined system components and services] that are initiated in a known state and terminated [Selection (one or more): upon end of session of use; periodically at [Assignment: organization-defined frequency]]. Discussion:  Implementation of non-persistent components and services mitigates risk from advanced persistent threats (APTs) by reducing the targeting capability of adversaries (i.e., window of opportunity and available attack surface) to initiate and complete attacks.', 'vec_doc-14-nist-sp-800-53-p381-1478', 0, 205, 'v2.1.0', 'f5e4bdb11be1b5f092002393f1d0ad177bf5c76bd37b2545d9af2221d54dbde4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 354","subsection":"UNKNOWN","table_id":null,"page":381,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1478,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 354"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p381-1479', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 354', 381, 'By implementing the concept of non-persistence for selected system components, organizations can provide a trusted, known state computing resource for a specific time period that does not give adversaries sufficient time to exploit vulnerabilities in organizational systems or operating environments. Since the APT is a high-end, sophisticated threat with regard to capability, intent, and targeting, organizations assume that over an extended period, a percentage of attacks will be successful. Non-persistent system components and services are activated as required using protected information and terminated periodically or at the end of sessions. Non-persistence increases the work factor of adversaries attempting to compromise or breach organizational systems. Non-persistence can be achieved by refreshing system components, periodically reimaging components, or using a variety of common virtualization techniques.', 'vec_doc-14-nist-sp-800-53-p381-1479', 0, 231, 'v2.1.0', 'fb37e3616671bf61e77a826e2bdc405efac9cca601ca58a3b3203326a47b71e9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 354","subsection":"UNKNOWN","table_id":null,"page":381,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1479,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 354"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p381-1480', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 354', 381, 'Non-persistent services can be implemented by using virtualization techniques as part of virtual machines or as new instances of processes on physical machines (either persistent or non-persistent). The benefit of periodic refreshes of system components and services is that it does not require organizations to first determine whether compromises of components or services have occurred (something that may often be difficult to determine). The refresh of selected system components and services occurs with sufficient frequency to prevent the spread or intended impact of attacks, but not with such frequency that it makes the system unstable. Refreshes of critical components and services may be done periodically to hinder the ability of adversaries to exploit optimum windows of vulnerabilities. Related Controls:  SC-30, SC-34, SI-21. Control Enhancements: (1) NON-PERSISTENCE | REFRESH FROM TRUSTED SOURCES', 'vec_doc-14-nist-sp-800-53-p381-1480', 0, 229, 'v2.1.0', '83c00f4c59adedfd9745480cb55b76e43ebe4ce948452e646ad5d7a804fbed3c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 354","subsection":"UNKNOWN","table_id":null,"page":381,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1480,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 354"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p382-1481', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 355', 382, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Obtain software and data employed during system component and service refreshes from the following trusted sources: [Assignment: organization-defined trusted sources]. Discussion:  Trusted sources include software and data from write-once, read-only media or from selected offline secure storage facilities. Related Controls:  None. (2) NON-PERSISTENCE | NON-PERSISTENT INFORMATION (a) [Selection: Refresh [Assignment: organization-defined information] [Assignment: organization-defined frequency]; Generate [Assignment: organization-defined information] on demand]; and (b) Delete information when no longer needed. Discussion:  Retaining information longer than is needed makes the information a potential target for advanced adversaries searching for high value assets to compromise through unauthorized disclosure, unauthorized modification, or exfiltration.', 'vec_doc-14-nist-sp-800-53-p382-1481', 0, 239, 'v2.1.0', '002fff4ddfc2eabf4ef6d5d8f44df23c61631f050a0a82dfede5bde0e4e3f753', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 355","subsection":"UNKNOWN","table_id":null,"page":382,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1481,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 355"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p382-1482', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 355', 382, 'For system-related information, unnecessary retention provides advanced adversaries information that can assist in their reconnaissance and lateral movement through the system. Related Controls:  None. (3) NON-PERSISTENCE | NON-PERSISTENT CONNECTIVITY Establish connections to the system on demand and terminate connections after [Selection: completion of a request; a period of non-use]. Discussion:  Persistent connections to systems can provide advanced adversaries with paths to move laterally through systems and potentially position themselves closer to high value assets. Limiting the availability of such connections impedes the adversary’s ability to move freely through organizational systems. Related Controls:  SC-10. References:  None.', 'vec_doc-14-nist-sp-800-53-p382-1482', 0, 187, 'v2.1.0', '20aec14ee3edfd2abf2d7173a08704c3141dd2b231f8262334c2d47cc306ea8c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 355","subsection":"UNKNOWN","table_id":null,"page":382,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1482,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 355"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p382-1483', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 355', 382, 'SI-15 INFORMATION OUTPUT FILTERING Control:  Validate information output from the following software programs and/or applications to ensure that the information is consistent with the expected content: [Assignment: organization-defined software programs and/or applications]. Discussion:  Certain types of attacks, including SQL injections, produce output results that are unexpected or inconsistent with the output results that would be expected from software programs or applications. Information output filtering focuses on detecting extraneous content, preventing such extraneous content from being displayed, and then alerting monitoring tools that anomalous behavior has been discovered. Related Controls:  SI-3, SI-4, SI-11. Control Enhancements:  None. References:  None. SI-16 MEMORY PROTECTION Control:  Implement the following controls to protect the system memory from unauthorized code execution: [Assignment: organization-defined controls].', 'vec_doc-14-nist-sp-800-53-p382-1483', 0, 239, 'v2.1.0', 'a59bbb84c750856907a65d266c90559693af6737db0bd347db6bb0eef0d4fca4', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 355","subsection":"UNKNOWN","table_id":null,"page":382,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1483,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 355"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p382-1484', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 355', 382, 'Discussion:  Some adversaries launch attacks with the intent of executing code in non-executable regions of memory or in memory locations that are prohibited. Controls employed to protect memory include data execution prevention and address space layout randomization. Data', 'vec_doc-14-nist-sp-800-53-p382-1484', 0, 69, 'v2.1.0', 'd663568aeb08a2e73532324e99f3ffff4b60b72add44b6c06e28b462be6f8691', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 355","subsection":"UNKNOWN","table_id":null,"page":382,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1484,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 355"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p383-1485', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 356', 383, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 execution prevention controls can either be hardware-enforced or software-enforced with hardware enforcement providing the greater strength of mechanism. Related Controls:  AC-25, SC-3, SI-7. Control Enhancements:  None. References:  None. SI-17 FAIL-SAFE PROCEDURES Control:  Implement the indicated fail-safe procedures when the indicated failures occur: [Assignment: organization-defined list of failure conditions and associated fail-safe procedures]. Discussion:  Failure conditions include the loss of communications among critical system components or between system components and operational facilities. Fail-safe procedures include alerting operator personnel and providing specific instructions on subsequent steps to take. Subsequent steps may include doing nothing, reestablishing system settings, shutting down processes, restarting the system, or contacting designated organizational personnel.', 'vec_doc-14-nist-sp-800-53-p383-1485', 0, 251, 'v2.1.0', 'a7190e241f9c656486a86e3bfe7f1d0b4560aacab218716ed9ba2eed1bb4aa46', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 356","subsection":"UNKNOWN","table_id":null,"page":383,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1485,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 356"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p383-1486', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 356', 383, 'Related Controls:  CP-12, CP-13, SC-24, SI-13. Control Enhancements:  None. References:  None. SI-18 PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS Control: a. Check the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle [Assignment: organization-defined frequency]; and b. Correct or delete inaccurate or outdated personally identifiable information. Discussion:  Personally identifiable information quality operations include the steps that organizations take to confirm the accuracy and relevance of personally identifiable information throughout the information life cycle. The information life cycle includes the creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal of personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p383-1486', 0, 210, 'v2.1.0', 'f594cb7636410be3adbe25f19cd986707fc82e65cbc31eb9543c87d6fa1866ed', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 356","subsection":"UNKNOWN","table_id":null,"page":383,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1486,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 356"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p383-1487', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 356', 383, 'Personally identifiable information quality operations include editing and validating addresses as they are collected or entered into systems using automated address verification look-up application programming interfaces. Checking personally identifiable information quality includes the tracking of updates or changes to data over time, which enables organizations to know how and what personally identifiable information was changed should erroneous information be identified. The measures taken to protect personally identifiable information quality are based on the nature and context of the personally identifiable information, how it is to be used, how it was obtained, and the potential de-identification methods employed.', 'vec_doc-14-nist-sp-800-53-p383-1487', 0, 183, 'v2.1.0', '3b1ea489e113266538a47686f06712f73a87260ccb0584e85df49c8bf35889a5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 356","subsection":"UNKNOWN","table_id":null,"page":383,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1487,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 356"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p383-1488', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 356', 383, 'The measures taken to validate the accuracy of personally identifiable information used to make determinations about the rights, benefits, or privileges of individuals covered under federal programs may be more comprehensive than the measures used to validate personally identifiable information used for less sensitive purposes. Related Controls:  PM-22, PM-24, PT-2, SI-4. Control Enhancements: (1) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | AUTOMATION SUPPORT', 'vec_doc-14-nist-sp-800-53-p383-1488', 0, 119, 'v2.1.0', '889d4fb19b9d4a45d439582c4619cba4b18072a54dcf5cda592072675ff1a33a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 356","subsection":"UNKNOWN","table_id":null,"page":383,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1488,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 356"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p384-1489', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 357', 384, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Correct or delete personally identifiable information that is inaccurate or outdated, incorrectly determined regarding impact, or incorrectly de-identified using [Assignment: organization-defined automated mechanisms]. Discussion:  The use of automated mechanisms to improve data quality may inadvertently create privacy risks. Automated tools may connect to external or otherwise unrelated systems, and the matching of records between these systems may create linkages with unintended consequences. Organizations assess and document these risks in their privacy impact assessments and make determinations that are in alignment with their privacy program plans. As data is obtained and used across the information life cycle, it is important to confirm the accuracy and relevance of personally identifiable information.', 'vec_doc-14-nist-sp-800-53-p384-1489', 0, 228, 'v2.1.0', 'aa79485c3bc0c7e39c6d6ed3d18ed468b754fa149f7cdf1bc05f511c42166508', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 357","subsection":"UNKNOWN","table_id":null,"page":384,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1489,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 357"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p384-1490', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 357', 384, 'Automated mechanisms can augment existing data quality processes and procedures and enable an organization to better identify and manage personally identifiable information in large-scale systems. For example, automated tools can greatly improve efforts to consistently normalize data or identify malformed data. Automated tools can also be used to improve the auditing of data and detect errors that may incorrectly alter personally identifiable information or incorrectly associate such information with the wrong individual. Automated capabilities backstop processes and procedures at-scale and enable more fine-grained detection and correction of data quality errors. Related Controls:  PM-18, RA-8. (2) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | DATA TAGS Employ data tags to automate the correction or deletion of personally identifiable information across the information life cycle within organizational systems.', 'vec_doc-14-nist-sp-800-53-p384-1490', 0, 234, 'v2.1.0', 'c402a17f80fc2a24914015d3b3263cdc7471a791559579b68fdb79a840fd91bf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 357","subsection":"UNKNOWN","table_id":null,"page":384,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1490,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 357"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p384-1491', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 357', 384, 'Discussion:  Data tagging personally identifiable information includes tags that note processing permissions, authority to process, de-identification, impact level, information life cycle stage, and retention or last updated dates. Employing data tags for personally identifiable information can support the use of automation tools to correct or delete relevant personally identifiable information. Related Controls:  AC-3, AC-16,  SC-16. (3) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | COLLECTION Collect personally identifiable information directly from the individual. Discussion:  Individuals or their designated representatives can be sources of correct personally identifiable information. Organizations consider contextual factors that may incentivize individuals to provide correct data versus false data.', 'vec_doc-14-nist-sp-800-53-p384-1491', 0, 207, 'v2.1.0', '13a93a8e23351f309130f717108d1447916a1ddd13762b1e80c9d81e2457af6f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 357","subsection":"UNKNOWN","table_id":null,"page":384,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1491,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 357"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p384-1492', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 357', 384, 'Additional steps may be necessary to validate collected information based on the nature and context of the personally identifiable information, how it is to be used, and how it was obtained. The measures taken to validate the accuracy of personally identifiable information used to make determinations about the rights, benefits, or privileges of individuals under federal programs may be more comprehensive than the measures taken to validate less sensitive personally identifiable information. Related Controls:  None. (4) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | INDIVIDUAL REQUESTS Correct or delete personally identifiable information upon request by individuals or their designated representatives.', 'vec_doc-14-nist-sp-800-53-p384-1492', 0, 180, 'v2.1.0', 'a98e2d9547d6995b57ac28d959e003f9f5c3e7d68ce074db972d851df9669b03', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 357","subsection":"UNKNOWN","table_id":null,"page":384,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1492,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 357"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p384-1493', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 357', 384, 'Discussion:  Inaccurate personally identifiable information maintained by organizations may cause problems for individuals, especially in those business functions where inaccurate information may result in inappropriate decisions or the denial of benefits and services to individuals. Even correct information, in certain circumstances, can cause problems for', 'vec_doc-14-nist-sp-800-53-p384-1493', 0, 90, 'v2.1.0', 'f8e72978bbffb12556255407cf8d8314239ac05abfeb72470b7e9919a9c826ef', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 357","subsection":"UNKNOWN","table_id":null,"page":384,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1493,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 357"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p385-1494', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 358', 385, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 individuals that outweigh the benefits of an organization maintaining the information. Organizations use discretion when determining if personally identifiable information is to be corrected or deleted based on the scope of requests, the changes sought, the impact of the changes, and laws, regulations, and policies. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding appropriate instances of correction or deletion. Related Controls:  None. (5) PERSONALLY IDENTIFIABLE INFORMATION QUALITY OPERATIONS | NOTICE OF CORRECTION OR DELETION Notify [Assignment: organization-defined recipients of personally identifiable information] and individuals that the personally identifiable information has been corrected or deleted.', 'vec_doc-14-nist-sp-800-53-p385-1494', 0, 217, 'v2.1.0', '18c6e336b5edf43355cf354d6979b3476a22d4f00f6728cbd8401ea4b5df715a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 358","subsection":"UNKNOWN","table_id":null,"page":385,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1494,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 358"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p385-1495', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 358', 385, 'Discussion:  When personally identifiable information is corrected or deleted, organizations take steps to ensure that all authorized recipients of such information, and the individual with whom the information is associated or their designated representatives, are informed of the corrected or deleted information. Related Controls:  None. References:  [OMB M-19-15], [SP 800-188], [IR 8112]. SI-19 DE-IDENTIFICATION Control: a. Remove the following elements of personally identifiable information from datasets: [Assignment: organization-defined elements of personally identifiable information]; and b. Evaluate [Assignment: organization-defined frequency] for effectiveness of de-identification. Discussion:  De-identification is the general term for the process of removing the association between a set of identifying data and the data subject.', 'vec_doc-14-nist-sp-800-53-p385-1495', 0, 213, 'v2.1.0', '6d16ba4c095923a6c4835f9b1d71626cf2dd7e505be9665500bb4dd3ec1de344', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 358","subsection":"UNKNOWN","table_id":null,"page":385,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1495,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 358"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p385-1496', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 358', 385, 'Many datasets contain information about individuals that can be used to distinguish or trace an individual’s identity, such as name, social security number, date and place of birth, mother’s maiden name, or biometric records. Datasets may also contain other information that is linked or linkable to an individual, such as medical, educational, financial, and employment information. Personally identifiable information is removed from datasets by trained individuals when such information is not (or no longer) necessary to satisfy the requirements envisioned for the data. For example, if the dataset is only used to produce aggregate statistics, the identifiers that are not needed for producing those statistics are removed. Removing identifiers improves privacy protection since information that is removed cannot be inadvertently disclosed or improperly used. Organizations may be subject to specific de-identification definitions or methods under applicable laws, regulations, or policies.', 'vec_doc-14-nist-sp-800-53-p385-1496', 0, 249, 'v2.1.0', 'd3ebdffbbb2a2ad2d77b0b61aaee425110542dda4a2c675b3cc08d41513c48c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 358","subsection":"UNKNOWN","table_id":null,"page":385,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1496,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 358"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p385-1497', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 358', 385, 'Re-identification is a residual risk with de-identified data. Re-identification attacks can vary, including combining new datasets or other improvements in data analytics. Maintaining awareness of potential attacks and evaluating for the effectiveness of the de-identification over time support the management of this residual risk. Related Controls:  MP-6, PM-22, PM-23, PM-24, RA-2, SI-12. Control Enhancements: (1) DE-IDENTIFICATION | COLLECTION De-identify the dataset upon collection by not collecting personally identifiable information. Discussion:  If a data source contains personally identifiable information but the information will not be used, the dataset can be de-identified when it is created by not collecting the', 'vec_doc-14-nist-sp-800-53-p385-1497', 0, 183, 'v2.1.0', '98b7ddd0261fb44c76042310789b8e6942014ad1e421a9d5c19e0713d1cee6ba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 358","subsection":"UNKNOWN","table_id":null,"page":385,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1497,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 358"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p386-1498', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 359', 386, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 data elements that contain the personally identifiable information. For example, if an organization does not intend to use the social security number of an applicant, then application forms do not ask for a social security number. Related Controls:  None. (2) DE-IDENTIFICATION | ARCHIVING Prohibit archiving of personally identifiable information elements if those elements in a dataset will not be needed after the dataset is archived. Discussion:  Datasets can be archived for many reasons. The envisioned purposes for the archived dataset are specified, and if personally identifiable information elements are not required, the elements are not archived. For example, social security numbers may have been collected for record linkage, but the archived dataset may include the required elements from the linked records. In this case, it is not necessary to archive the social security numbers.', 'vec_doc-14-nist-sp-800-53-p386-1498', 0, 248, 'v2.1.0', '49a441ceb4724c36bb7920894f2f8026513875d1f401bb82a5568085395357c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 359","subsection":"UNKNOWN","table_id":null,"page":386,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1498,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 359"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p386-1499', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 359', 386, 'Related Controls:  None. (3) DE-IDENTIFICATION | RELEASE Remove personally identifiable information elements from a dataset prior to its release if those elements in the dataset do not need to be part of the data release. Discussion:  Prior to releasing a dataset, a data custodian considers the intended uses of the dataset and determines if it is necessary to release personally identifiable information. If the personally identifiable information is not necessary, the information can be removed using de-identification techniques. Related Controls:  None. (4) DE-IDENTIFICATION | REMOVAL, MASKING, ENCRYPTION, HASHING, OR REPLACEMENT OF DIRECT IDENTIFIERS Remove, mask, encrypt, hash, or replace direct identifiers in a dataset. Discussion:  There are many possible processes for removing direct identifiers from a dataset. Columns in a dataset that contain a direct identifier can be removed. In masking, the direct identifier is transformed into a repeating character, such as XXXXXX or 999999.', 'vec_doc-14-nist-sp-800-53-p386-1499', 0, 250, 'v2.1.0', '6af23af7dca96479435a30d0b789a91f3c5aadf20ab92fe7731423df5b5c896b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 359","subsection":"UNKNOWN","table_id":null,"page":386,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1499,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 359"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p386-1500', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 359', 386, 'Identifiers can be encrypted or hashed so that the linked records remain linked. In the case of encryption or hashing, algorithms are employed that require the use of a key, including the Advanced Encryption Standard or a Hash-based Message Authentication Code. Implementations may use the same key for all identifiers or use a different key for each identifier. Using a different key for each identifier provides a higher degree of security and privacy. Identifiers can alternatively be replaced with a keyword, including transforming “George Washington” to “PATIENT” or replacing it with a surrogate value, such as transforming “George Washington” to “Abraham Polk.” Related Controls:  SC-12, SC-13. (5) DE-IDENTIFICATION | STATISTICAL DISCLOSURE CONTROL Manipulate numerical data, contingency tables, and statistical findings so that no individual or organization is identifiable in the results of the analysis.', 'vec_doc-14-nist-sp-800-53-p386-1500', 0, 229, 'v2.1.0', '614488cec6f004de55d660e75dbbece280144e7c4ad566b16f6367e4178956cc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 359","subsection":"UNKNOWN","table_id":null,"page":386,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1500,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 359"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p386-1501', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 359', 386, 'Discussion:  Many types of statistical analyses can result in the disclosure of information about individuals even if only summary information is provided. For example, if a school that publishes a monthly table with the number of minority students enrolled, reports that it has 10-19 such students in January, and subsequently reports that it has 20-29 such students in March, then it can be inferred that the student who enrolled in February was a minority. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p386-1501', 0, 121, 'v2.1.0', '36a1ecd280739a3e932d8ea47ef3d681dd0dd48c246a7e803f450abdda91419c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 359","subsection":"UNKNOWN","table_id":null,"page":386,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1501,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 359"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p387-1502', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 360', 387, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (6) DE-IDENTIFICATION | DIFFERENTIAL PRIVACY Prevent disclosure of personally identifiable information by adding non-deterministic noise to the results of mathematical operations before the results are reported. Discussion:  The mathematical definition for differential privacy holds that the result of a dataset analysis should be approximately the same before and after the addition or removal of a single data record (which is assumed to be the data from a single individual). In its most basic form, differential privacy applies only to online query systems. However, it can also be used to produce machine-learning statistical classifiers and synthetic data. Differential privacy comes at the cost of decreased accuracy of results, forcing organizations to quantify the trade-off between privacy protection and the overall accuracy, usefulness, and utility of the de-identified dataset.', 'vec_doc-14-nist-sp-800-53-p387-1502', 0, 246, 'v2.1.0', '4917cfda1af26332e3713af1e4b131ffaaf8a4f3eec47a1d7c830168fb9a7740', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 360","subsection":"UNKNOWN","table_id":null,"page":387,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1502,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 360"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p387-1503', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 360', 387, 'Non-deterministic noise can include adding small, random values to the results of mathematical operations in dataset analysis. Related Controls:  SC-12, SC-13. (7) DE-IDENTIFICATION | VALIDATED ALGORITHMS AND SOFTWARE Perform de-identification using validated algorithms and software that is validated to implement the algorithms. Discussion:  Algorithms that appear to remove personally identifiable information from a dataset may in fact leave information that is personally identifiable or data that is re- identifiable. Software that is claimed to implement a validated algorithm may contain bugs or implement a different algorithm. Software may de-identify one type of data, such as integers, but not de-identify another type of data, such as floating point numbers. For these reasons, de-identification is performed using algorithms and software that are validated. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p387-1503', 0, 224, 'v2.1.0', '939816f303343652ac7466e20017a47b90ee715caf8c6f679da68009ff21128b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 360","subsection":"UNKNOWN","table_id":null,"page":387,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1503,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 360"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p387-1504', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 360', 387, '(8) DE-IDENTIFICATION | MOTIVATED INTRUDER Perform a motivated intruder test on the de-identified dataset to determine if the identified data remains or if the de-identified data can be re-identified. Discussion:  A motivated intruder test is a test in which an individual or group takes a data release and specified resources and attempts to re-identify one or more individuals in the de-identified dataset. Such tests specify the amount of inside knowledge, computational resources, financial resources, data, and skills that intruders possess to conduct the tests. A motivated intruder test can determine if the de-identification is insufficient. It can also be a useful diagnostic tool to assess if de-identification is likely to be sufficient. However, the test alone cannot prove that de-identification is sufficient. Related Controls:  None. References:  [OMB A-130], [SP 800-188].', 'vec_doc-14-nist-sp-800-53-p387-1504', 0, 222, 'v2.1.0', '86d07d6228f393fa6237a893e8a79bd3fff50f1eeb7d06fc411b1edc08e2f4c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 360","subsection":"UNKNOWN","table_id":null,"page":387,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1504,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 360"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p387-1505', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 360', 387, 'SI-20 TAINTING Control:  Embed data or capabilities in the following systems or system components to determine if organizational data has been exfiltrated or improperly removed from the organization: [Assignment: organization-defined systems or system components]. Discussion:  Many cyber-attacks target organizational information, or information that the organization holds on behalf of other entities (e.g., personally identifiable information), and exfiltrate that data. In addition, insider attacks and erroneous user procedures can remove information from the system that is in violation of the organizational policies. Tainting approaches can range from passive to active. A passive tainting approach can be as simple as adding false email names and addresses to an internal database. If the organization receives email at one of the false email addresses, it knows that the database has been compromised. Moreover, the organization knows that the email was sent by an unauthorized entity, so any', 'vec_doc-14-nist-sp-800-53-p387-1505', 0, 251, 'v2.1.0', '89995e9c60fe4020d58393ef036a0fcb5da80483c3233a96130026d07ee33314', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 360","subsection":"UNKNOWN","table_id":null,"page":387,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1505,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 360"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p388-1506', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 361', 388, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 packets it includes potentially contain malicious code, and that the unauthorized entity may have potentially obtained a copy of the database. Another tainting approach can include embedding false data or steganographic data in files to enable the data to be found via open-source analysis. Finally, an active tainting approach can include embedding software in the data that is able to “call home,” thereby alerting the organization to its “capture,” and possibly its location, and the path by which it was exfiltrated or removed. Related Controls:  AU-13. Control Enhancements:  None. References:  [OMB A-130], [SP 800-160-2]. SI-21 INFORMATION REFRESH Control:  Refresh [Assignment: organization-defined information] at [Assignment: organization- defined frequencies] or generate the information on demand and delete the information when no longer needed.', 'vec_doc-14-nist-sp-800-53-p388-1506', 0, 238, 'v2.1.0', '2eaa3d26b603f1428427d3e7ac4396d3b918b717af1a7e6c4c839b4c3a8c3bf3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 361","subsection":"UNKNOWN","table_id":null,"page":388,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1506,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 361"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p388-1507', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 361', 388, 'Discussion:  Retaining information for longer than it is needed makes it an increasingly valuable and enticing target for adversaries. Keeping information available for the minimum period of time needed to support organizational missions or business functions reduces the opportunity for adversaries to compromise, capture, and exfiltrate that information. Related Controls:  SI-14. Control Enhancements:  None. References:  [OMB A-130], [SP 800-160-2]. SI-22 INFORMATION DIVERSITY Control: a. Identify the following alternative sources of information for [Assignment: organization- defined essential functions and services]: [Assignment: organization-defined alternative information sources]; and b. Use an alternative information source for the execution of essential functions or services on [Assignment: organization-defined systems or system components] when the primary source of information is corrupted or unavailable.', 'vec_doc-14-nist-sp-800-53-p388-1507', 0, 232, 'v2.1.0', '7afe95969c3fbec9d8680116e33242fda69f2790d273b336f8adfd05448eafa1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 361","subsection":"UNKNOWN","table_id":null,"page":388,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1507,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 361"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p388-1508', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 361', 388, 'Discussion:  Actions taken by a system service or a function are often driven by the information it receives. Corruption, fabrication, modification, or deletion of that information could impact the ability of the service function to properly carry out its intended actions. By having multiple sources of input, the service or function can continue operation if one source is corrupted or no longer available. It is possible that the alternative sources of information may be less precise or less accurate than the primary source of information. But having such sub-optimal information sources may still provide a sufficient level of quality that the essential service or function can be carried out, even in a degraded or debilitated manner. Related Controls:  None. Control Enhancements:  None. References:  [SP 800-160-2]. SI-23 INFORMATION FRAGMENTATION Control:  Based on [Assignment: organization-defined circumstances]:', 'vec_doc-14-nist-sp-800-53-p388-1508', 0, 232, 'v2.1.0', '0d4bab3311e2e04e48c05eabb942473666220c0fb312d7ab74b3183f9ffcc090', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 361","subsection":"UNKNOWN","table_id":null,"page":388,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1508,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 361"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p389-1509', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 362', 389, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 a. Fragment the following information: [Assignment: organization-defined information]; and b. Distribute the fragmented information across the following systems or system components: [Assignment organization-defined systems or system components]. Discussion:  One objective of the advanced persistent threat is to exfiltrate valuable information. Once exfiltrated, there is generally no way for the organization to recover the lost information. Therefore, organizations may consider dividing the information into disparate elements and distributing those elements across multiple systems or system components and locations. Such actions will increase the adversary’s work factor to capture and exfiltrate the desired information and, in so doing, increase the probability of detection. The fragmentation of information impacts the organization’s ability to access the information in a timely manner. The extent of the fragmentation is dictated by the impact or classification level (and value) of the information, threat intelligence information received, and whether data tainting is used (i.e., data tainting- derived information about the exfiltration of some information could result in the fragmentation of the remaining information). Related Controls:  None. Control Enhancements:  None. References:  [SP 800-160-2].', 'vec_doc-14-nist-sp-800-53-p389-1509', 0, 354, 'v2.1.0', '0dc57c3352bb8e1e02ae7dac96e78e8138d024126d5913843cbfa200e9d3f920', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 362","subsection":"UNKNOWN","table_id":null,"page":389,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1509,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 362"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p390-1510', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '3.20   SUPPLY CHAIN RISK MANAGEMENT', 390, 'Quick link to Supply Chain Risk Management Summary Table SR-1 POLICY AND PROCEDURES Control: a. Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:', 'vec_doc-14-nist-sp-800-53-p390-1510', 0, 47, 'v2.1.0', 'f6347901332e4431a758cd4bdc6be58c66f9518d06289e35086e351b77956f8c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"3.20   SUPPLY CHAIN RISK MANAGEMENT","subsection":"UNKNOWN","table_id":null,"page":390,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1510,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"3.20   SUPPLY CHAIN RISK MANAGEMENT"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p390-1511', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '1. [Selection (one or more): Organization-level; Mission/business process-level; System-', 390, 'level] supply chain risk management policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and', 'vec_doc-14-nist-sp-800-53-p390-1511', 0, 79, 'v2.1.0', '81c51f2a6d84659f83bfdcd615c3647ab6fca69af25850ed11e06aca6fc77fdc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-","subsection":"UNKNOWN","table_id":null,"page":390,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1511,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"1. [Selection (one or more): Organization-level; Mission/business process-level; System-"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p390-1512', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures to facilitate the implementation of the supply chain risk management policy', 390, 'and the associated supply chain risk management controls; b. Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures; and c. Review and update the current supply chain risk management:', 'vec_doc-14-nist-sp-800-53-p390-1512', 0, 76, 'v2.1.0', 'e7763aae7514d949b93564a212e8641a425f7446c6c3261efa149fb3635b4dcb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures to facilitate the implementation of the supply chain risk management policy","subsection":"UNKNOWN","table_id":null,"page":390,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1512,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures to facilitate the implementation of the supply chain risk management policy"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p390-1513', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', '2. Procedures [Assignment: organization-defined frequency] and following [Assignment:', 390, 'organization-defined events]. Discussion:  Supply chain risk management policy and procedures address the controls in the SR family as well as supply chain-related controls in other families that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of supply chain risk management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to supply chain risk management policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure. Related Controls:  PM-9, PM-30, PS-8, SI-12. Control Enhancements:  None.', 'vec_doc-14-nist-sp-800-53-p390-1513', 0, 433, 'v2.1.0', '0b4fbc6b6aa69768b5e636e65d69a2af12a4eb4fbf1a1792045be47e249dd15f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:","subsection":"UNKNOWN","table_id":null,"page":390,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1513,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"2. Procedures [Assignment: organization-defined frequency] and following [Assignment:"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p391-1514', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 364', 391, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 References:  [FASC18], [41 CFR 201], [EO 13873], [CNSSD 505], [SP 800-12], [SP 800-30], [SP 800- 39], [SP 800-100], [SP 800-161]. SR-2 SUPPLY CHAIN RISK MANAGEMENT PLAN Control: a. Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of the following systems, system components or system services: [Assignment: organization-defined systems, system components, or system services]; b. Review and update the supply chain risk management plan [Assignment: organization- defined frequency] or as required, to address threat, organizational or environmental changes; and c. Protect the supply chain risk management plan from unauthorized disclosure and modification.', 'vec_doc-14-nist-sp-800-53-p391-1514', 0, 224, 'v2.1.0', 'b51cdaa182e8df6c97e832e3fd39700e679a786f162bae3fe77081a167204b8e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 364","subsection":"UNKNOWN","table_id":null,"page":391,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1514,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 364"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p391-1515', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 364', 391, 'Discussion:  The dependence on products, systems, and services from external providers, as well as the nature of the relationships with those providers, present an increasing level of risk to an organization. Threat actions that may increase security or privacy risks include unauthorized production, the insertion or use of counterfeits, tampering, theft, insertion of malicious software and hardware, and poor manufacturing and development practices in the supply chain. Supply chain risks can be endemic or systemic within a system element or component, a system, an organization, a sector, or the Nation. Managing supply chain risk is a complex, multifaceted undertaking that requires a coordinated effort across an organization to build trust relationships and communicate with internal and external stakeholders.', 'vec_doc-14-nist-sp-800-53-p391-1515', 0, 205, 'v2.1.0', '7ae9b2ea8f7e988aa0008864acfb4c5d05cb3de0ee4d2d675f1d5faa42f55919', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 364","subsection":"UNKNOWN","table_id":null,"page":391,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1515,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 364"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p391-1516', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 364', 391, 'Supply chain risk management (SCRM) activities include identifying and assessing risks, determining appropriate risk response actions, developing SCRM plans to document response actions, and monitoring performance against plans. The SCRM plan (at the system-level) is implementation specific, providing policy implementation, requirements, constraints and implications. It can either be stand-alone, or incorporated into system security and privacy plans. The SCRM plan addresses managing, implementation, and monitoring of SCRM controls and the development/sustainment of systems across the SDLC to support mission and business functions. Because supply chains can differ significantly across and within organizations, SCRM plans are tailored to the individual program, organizational, and operational contexts. Tailored SCRM plans provide the basis for determining whether a technology, service, system component, or system is fit for purpose, and as such, the controls need to be tailored accordingly.', 'vec_doc-14-nist-sp-800-53-p391-1516', 0, 251, 'v2.1.0', 'ac308997a927f8e9d17c02179d94c4d492ed90cdd759fb1f7d348de4dc1c8f18', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 364","subsection":"UNKNOWN","table_id":null,"page":391,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1516,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 364"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p391-1517', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 364', 391, 'Tailored SCRM plans help organizations focus their resources on the most critical mission and business functions based on mission and business requirements and their risk environment. Supply chain risk management plans include an expression of the supply chain risk tolerance for the organization, acceptable supply chain risk mitigation strategies or controls, a process for consistently evaluating and monitoring supply chain risk, approaches for implementing and communicating the plan, a description of and justification for supply chain risk mitigation measures taken, and associated roles and responsibilities. Finally, supply chain risk management plans address requirements for developing trustworthy, secure, privacy-protective, and resilient system components and systems, including the application of the security design principles implemented as part of life cycle-based systems security engineering processes (see SA-8 ).', 'vec_doc-14-nist-sp-800-53-p391-1517', 0, 234, 'v2.1.0', '01870c38c849e60b7669ac622b162bf5e81b72fa37fa3c9447f7cdf044b77bbd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 364","subsection":"UNKNOWN","table_id":null,"page":391,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1517,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 364"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p391-1518', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 364', 391, 'Related Controls:  CA-2, CP-4, IR-4, MA-2, MA-6, PE-16, PL-2, PM-9, PM-30, RA-3, RA-7, SA-8, SI-4. Control Enhancements: (1) SUPPLY CHAIN RISK MANAGEMENT PLAN | ESTABLISH SCRM TEAM', 'vec_doc-14-nist-sp-800-53-p391-1518', 0, 45, 'v2.1.0', '3367e5525f4ab4649074fc653f26d196d3a300ea0878041da76f9d6a2a842d87', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 364","subsection":"UNKNOWN","table_id":null,"page":391,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1518,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 364"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p392-1519', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 365', 392, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Establish a supply chain risk management team consisting of [Assignment: organization- defined personnel, roles, and responsibilities] to lead and support the following SCRM activities: [Assignment: organization-defined supply chain risk management activities]. Discussion: To implement supply chain risk management plans, organizations establish a coordinated, team-based approach to identify and assess supply chain risks and manage these risks by using programmatic and technical mitigation techniques. The team approach enables organizations to conduct an analysis of their supply chain, communicate with internal and external partners or stakeholders, and gain broad consensus regarding the appropriate resources for SCRM.', 'vec_doc-14-nist-sp-800-53-p392-1519', 0, 205, 'v2.1.0', 'f3bd7a98b2aecce7905d1313278b176f43e2cfdc404ec2abcdb70a2dbb920c97', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 365","subsection":"UNKNOWN","table_id":null,"page":392,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1519,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 365"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p392-1520', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 365', 392, 'The SCRM team consists of organizational personnel with diverse roles and responsibilities for leading and supporting SCRM activities, including risk executive, information technology, contracting, information security, privacy, mission or business, legal, supply chain and logistics, acquisition, business continuity, and other relevant functions. Members of the SCRM team are involved in various aspects of the SDLC and, collectively, have an awareness of and provide expertise in acquisition processes, legal practices, vulnerabilities, threats, and attack vectors, as well as an understanding of the technical aspects and dependencies of systems. The SCRM team can be an extension of the security and privacy risk management processes or be included as part of an organizational risk management team. Related Controls:  None. References: [FASC18], [41 CFR 201], [EO 13873], [CNSSD 505], [SP 800-30], [SP 800-39], [SP-800- 160-1], [SP 800-161], [SP 800-181], [IR 7622], [IR 8272].', 'vec_doc-14-nist-sp-800-53-p392-1520', 0, 246, 'v2.1.0', 'c8d242fefcbd3e99887ed4e213eb8e0608e4473cfcc1cde9e9215aa18fdb6944', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 365","subsection":"UNKNOWN","table_id":null,"page":392,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1520,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 365"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p392-1521', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 365', 392, 'SR-3 SUPPLY CHAIN CONTROLS AND PROCESSES Control: a. Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component] in coordination with [Assignment: organization-defined supply chain personnel]; b. Employ the following controls to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain- related events: [Assignment: organization-defined supply chain controls]; and c. Document the selected and implemented supply chain processes and controls in [Selection: security and privacy plans; supply chain risk management plan; [Assignment: organization- defined document]].', 'vec_doc-14-nist-sp-800-53-p392-1521', 0, 196, 'v2.1.0', '2acac6b50157080b47d02ada8942ba30e5558e354ad42a739fca6b0475399ff5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 365","subsection":"UNKNOWN","table_id":null,"page":392,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1521,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 365"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p392-1522', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 365', 392, 'Discussion:  Supply chain elements include organizations, entities, or tools employed for the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of systems and system components. Supply chain processes include hardware, software, and firmware development processes; shipping and handling procedures; personnel security and physical security programs; configuration management tools, techniques, and measures to maintain provenance; or other programs, processes, or procedures associated with the development, acquisition, maintenance and disposal of systems and system components. Supply chain elements and processes may be provided by organizations, system integrators, or external providers.', 'vec_doc-14-nist-sp-800-53-p392-1522', 0, 192, 'v2.1.0', '2bfeb5ab7b99961519db9ddf6f1847985368ce931cb10d774743b4f0e16f1f25', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 365","subsection":"UNKNOWN","table_id":null,"page":392,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1522,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 365"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p392-1523', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 365', 392, 'Weaknesses or deficiencies in supply chain elements or processes represent potential vulnerabilities that can be exploited by adversaries to cause harm to the organization and affect its ability to carry out its core missions or business functions. Supply chain personnel are individuals with roles and responsibilities in the supply chain. Related Controls:  CA-2, MA-2, MA-6, PE-3, PE-16, PL-8, PM-30, SA-2, SA-3, SA-4, SA-5, SA-8, SA-9, SA-10, SA-15, SC-7, SC-29, SC-30, SC-38, SI-7, SR-6, SR-9, SR-11. Control Enhancements:', 'vec_doc-14-nist-sp-800-53-p392-1523', 0, 132, 'v2.1.0', '339df757f594c0ef1627723ea0a0d7398c6b13d237383db1839c0c1f57dcb0a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 365","subsection":"UNKNOWN","table_id":null,"page":392,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1523,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 365"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p393-1524', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 366', 393, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 (1) SUPPLY CHAIN CONTROLS AND PROCESSES | DIVERSE SUPPLY BASE Employ a diverse set of sources for the following system components and services: [Assignment: organization-defined system components and services]. Discussion:  Diversifying the supply of systems, system components, and services can reduce the probability that adversaries will successfully identify and target the supply chain and can reduce the impact of a supply chain event or compromise. Identifying multiple suppliers for replacement components can reduce the probability that the replacement component will become unavailable. Employing a diverse set of developers or logistics service providers can reduce the impact of a natural disaster or other supply chain event. Organizations consider designing the system to include diverse materials and components. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p393-1524', 0, 236, 'v2.1.0', '9666c85c518a7334513f018a4b6851ccc7b4db3cb375a380626c33412afc51d8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 366","subsection":"UNKNOWN","table_id":null,"page":393,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1524,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 366"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p393-1525', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 366', 393, '(2) SUPPLY CHAIN PROTECTION CONTROLS AND PROCESSES | LIMITATION OF HARM Employ the following controls to limit harm from potential adversaries identifying and targeting the organizational supply chain: [Assignment: organization-defined controls]. Discussion:  Controls that can be implemented to reduce the probability of adversaries successfully identifying and targeting the supply chain include avoiding the purchase of custom or non-standardized configurations, employing approved vendor lists with standing reputations in industry, following pre-agreed maintenance schedules and update and patch delivery mechanisms, maintaining a contingency plan in case of a supply chain event, using procurement carve-outs that provide exclusions to commitments or obligations, using diverse delivery routes, and minimizing the time between purchase decisions and delivery. Related Controls:  None.', 'vec_doc-14-nist-sp-800-53-p393-1525', 0, 223, 'v2.1.0', 'ba559d82b6b0f9f0a279b9247e903eed412ef54cbb569ff1d64646f427809a3f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 366","subsection":"UNKNOWN","table_id":null,"page":393,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1525,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 366"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p393-1526', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 366', 393, '(3) SUPPLY CHAIN PROTECTION CONTROLS AND PROCESSES | SUB-TIER FLOW DOWN Ensure that the controls included in the contracts of prime contractors are also included in the contracts of subcontractors. Discussion:  To manage supply chain risk effectively and holistically, it is important that organizations ensure that supply chain risk management controls are included at all tiers in the supply chain. This includes ensuring that Tier 1 (prime) contractors have implemented processes to facilitate the “flow down” of supply chain risk management controls to sub-tier contractors. The controls subject to flow down are identified in SR-3b. Related Controls:  SR-5, SR-8. References:  [FASC18], [41 CFR 201], [EO 13873], [ISO 20243], [SP 800-30], [SP 800-161], [IR 7622]. SR-4 PROVENANCE Control:  Document, monitor, and maintain valid provenance of the following systems, system components, and associated data: [Assignment: organization-defined systems, system components, and associated data].', 'vec_doc-14-nist-sp-800-53-p393-1526', 0, 249, 'v2.1.0', 'e76dff49aed208b3c5d46b43a025c4ccdc1886dbf94ee1010aa72f077918e94d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 366","subsection":"UNKNOWN","table_id":null,"page":393,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1526,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 366"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p393-1527', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 366', 393, 'Discussion:  Every system and system component has a point of origin and may be changed throughout its existence. Provenance is the chronology of the origin, development, ownership, location, and changes to a system or system component and associated data. It may also include personnel and processes used to interact with or make modifications to the system, component, or associated data. Organizations consider developing procedures (see SR-1) for allocating responsibilities for the creation, maintenance, and monitoring of provenance for systems and system components; transferring provenance documentation and responsibility between organizations; and preventing and monitoring for unauthorized changes to the provenance records. Organizations have methods to document, monitor, and maintain valid provenance baselines for systems, system components, and related data. These actions help track, assess,', 'vec_doc-14-nist-sp-800-53-p393-1527', 0, 227, 'v2.1.0', '2a8e29c692d36896efc35f8919e7607837e886a0e1d46b743b024be3a752880d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 366","subsection":"UNKNOWN","table_id":null,"page":393,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1527,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 366"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p394-1528', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 367', 394, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 and document any changes to the provenance, including changes in supply chain elements or configuration, and help ensure non-repudiation of provenance information and the provenance change records. Provenance considerations are addressed throughout the system development life cycle and incorporated into contracts and other arrangements, as appropriate. Related Controls:  CM-8, MA-2, MA-6, RA-9, SA-3, SA-8, SI-4. Control Enhancements: (1) PROVENANCE | IDENTITY Establish and maintain unique identification of the following supply chain elements, processes, and personnel associated with the identified system and critical system components: [Assignment: organization-defined supply chain elements, processes, and personnel associated with organization-defined systems and critical system components].', 'vec_doc-14-nist-sp-800-53-p394-1528', 0, 224, 'v2.1.0', 'ffa8ed5a2f24f666480458aba4e8ffe2a01d9a14211e1514a8d02dc4b4ee60a2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 367","subsection":"UNKNOWN","table_id":null,"page":394,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1528,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 367"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p394-1529', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 367', 394, 'Discussion:  Knowing who and what is in the supply chains of organizations is critical to gaining visibility into supply chain activities. Visibility into supply chain activities is also important for monitoring and identifying high-risk events and activities. Without reasonable visibility into supply chains elements, processes, and personnel, it is very difficult for organizations to understand and manage risk and reduce their susceptibility to adverse events. Supply chain elements include organizations, entities, or tools used for the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of systems and system components.', 'vec_doc-14-nist-sp-800-53-p394-1529', 0, 175, 'v2.1.0', '567ce5d096dfb895d4fa2293ebae1bbfc6cfe5998b759211009bfbecf82d2e8d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 367","subsection":"UNKNOWN","table_id":null,"page":394,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1529,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 367"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p394-1530', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 367', 394, 'Supply chain processes include development processes for hardware, software, and firmware; shipping and handling procedures; configuration management tools, techniques, and measures to maintain provenance; personnel and physical security programs; or other programs, processes, or procedures associated with the production and distribution of supply chain elements. Supply chain personnel are individuals with specific roles and responsibilities related to the secure the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of a system or system component. Identification methods are sufficient to support an investigation in case of a supply chain change (e.g. if a supply company is purchased), compromise, or event. Related Controls:  IA-2, IA-8, PE-16.', 'vec_doc-14-nist-sp-800-53-p394-1530', 0, 208, 'v2.1.0', '348687a6af0ce483997f675d5d82831393d332306622ba9c92e815cd10b52ff9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 367","subsection":"UNKNOWN","table_id":null,"page":394,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1530,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 367"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p394-1531', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 367', 394, '(2) PROVENANCE | TRACK AND TRACE Establish and maintain unique identification of the following systems and critical system components for tracking through the supply chain: [Assignment: organization-defined systems and critical system components]. Discussion:  Tracking the unique identification of systems and system components during development and transport activities provides a foundational identity structure for the establishment and maintenance of provenance. For example, system components may be labeled using serial numbers or tagged using radio-frequency identification tags. Labels and tags can help provide better visibility into the provenance of a system or system component. A system or system component may have more than one unique identifier. Identification methods are sufficient to support a forensic investigation after a supply chain compromise or event. Related Controls:  IA-2, IA-8, PE-16, PL-2.', 'vec_doc-14-nist-sp-800-53-p394-1531', 0, 231, 'v2.1.0', '5fcb1b19ffc16aa09d62962713453aafc48113b88afc4623e7d34be24d951aa7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 367","subsection":"UNKNOWN","table_id":null,"page":394,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1531,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 367"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p394-1532', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 367', 394, '(3) PROVENANCE | VALIDATE AS GENUINE AND NOT ALTERED Employ the following controls to validate that the system or system component received is genuine and has not been altered: [Assignment: organization-defined controls]. Discussion:  For many systems and system components, especially hardware, there are technical means to determine if the items are genuine or have been altered, including optical and nanotechnology tagging, physically unclonable functions, side-channel analysis,', 'vec_doc-14-nist-sp-800-53-p394-1532', 0, 121, 'v2.1.0', '91d92f90ced04d3fd5ee950f27a382a84d459428c6b6999800bc5b92d8a56c2b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 367","subsection":"UNKNOWN","table_id":null,"page":394,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1532,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 367"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p395-1533', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 368', 395, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 cryptographic hash verifications or digital signatures, and visible anti-tamper labels or stickers. Controls can also include monitoring for out of specification performance, which can be an indicator of tampering or counterfeits. Organizations may leverage supplier and contractor processes for validating that a system or component is genuine and has not been altered and for replacing a suspect system or component. Some indications of tampering may be visible and addressable before accepting delivery, such as inconsistent packaging, broken seals, and incorrect labels. When a system or system component is suspected of being altered or counterfeit, the supplier, contractor, or original equipment manufacturer may be able to replace the item or provide a forensic capability to determine the origin of the counterfeit or altered item.', 'vec_doc-14-nist-sp-800-53-p395-1533', 0, 233, 'v2.1.0', '5171ee4907deb6b2350b79f16744fcf62f2ea959eaaa2e69d5c2474fc08681eb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 368","subsection":"UNKNOWN","table_id":null,"page":395,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1533,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 368"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p395-1534', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 368', 395, 'Organizations can provide training to personnel on how to identify suspicious system or component deliveries. Related Controls:  AT-3, SR-9, SR-10, SR-11 . (4) PROVENANCE | SUPPLY CHAIN INTEGRITY —  PEDIGREE Employ [Assignment: organization-defined controls] and conduct [Assignment: organization-defined analysis] to ensure the integrity of the system and system components by validating the internal composition and provenance of critical or mission- essential technologies, products, and services. Discussion:  Authoritative information regarding the internal composition of system components and the provenance of technology, products, and services provides a strong basis for trust. The validation of the internal composition and provenance of technologies, products, and services is referred to as the pedigree. For microelectronics, this includes material composition of components.', 'vec_doc-14-nist-sp-800-53-p395-1534', 0, 223, 'v2.1.0', '9c9288941cb6c57e48633e2d18052cf834e8fe8510801a906650abca164cc4a3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 368","subsection":"UNKNOWN","table_id":null,"page":395,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1534,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 368"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p395-1535', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 368', 395, 'For software this includes the composition of open- source and proprietary code, including the version of the component at a given point in time. Pedigrees increase the assurance that the claims suppliers assert about the internal composition and provenance of the products, services, and technologies they provide are valid. The validation of the internal composition and provenance can be achieved by various evidentiary artifacts or records that manufacturers and suppliers produce during the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of technology, products, and services. Evidentiary artifacts include, but are not limited to, software identification (SWID) tags, software component inventory, the manufacturers’ declarations of platform attributes (e.g., serial numbers, hardware component inventory), and measurements (e.g., firmware hashes) that are tightly bound to the hardware itself. Related Controls:  RA-3.', 'vec_doc-14-nist-sp-800-53-p395-1535', 0, 251, 'v2.1.0', '225c38289acf6c2b40a89c87a32f8a17b9b54f7d2c9555e1172eb09e401d6d98', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 368","subsection":"UNKNOWN","table_id":null,"page":395,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1535,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 368"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p395-1536', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 368', 395, 'References:  [FASC18], [41 CFR 201], [EO 13873], [ISO 27036], [ISO 20243], [SP 800-160-1], [SP 800-161], [IR 7622], [IR 8112], [IR 8272]. SR-5 ACQUISITION STRATEGIES, TOOLS, AND METHODS Control:  Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks: [Assignment: organization-defined acquisition strategies, contract tools, and procurement methods]. Discussion:  The use of the acquisition process provides an important vehicle to protect the supply chain. There are many useful tools and techniques available, including obscuring the end use of a system or system component, using blind or filtered buys, requiring tamper-evident packaging, or using trusted or controlled distribution. The results from a supply chain risk assessment can guide and inform the strategies, tools, and methods that are most applicable to the situation.', 'vec_doc-14-nist-sp-800-53-p395-1536', 0, 232, 'v2.1.0', '46a593d1e60cbfa90c2d4f9f5a935f0cb9a9215080a4b98af15f0d81d4622bd9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 368","subsection":"UNKNOWN","table_id":null,"page":395,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1536,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 368"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p395-1537', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 368', 395, 'Tools and techniques may provide protections against unauthorized production, theft, tampering, insertion of counterfeits, insertion of malicious software or backdoors, and poor development practices throughout the system development life cycle. Organizations also', 'vec_doc-14-nist-sp-800-53-p395-1537', 0, 66, 'v2.1.0', '658fbc9275f3ba12c55e2e0af4623c45bac8002755d6c00c9c7cf50f1ed1d8fe', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 368","subsection":"UNKNOWN","table_id":null,"page":395,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1537,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 368"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p396-1538', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 369', 396, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 consider providing incentives for suppliers who implement controls, promote transparency into their processes and security and privacy practices, provide contract language that addresses the prohibition of tainted or counterfeit components, and restrict purchases from untrustworthy suppliers. Organizations consider providing training, education, and awareness programs for personnel regarding supply chain risk, available mitigation strategies, and when the programs should be employed. Methods for reviewing and protecting development plans, documentation, and evidence are commensurate with the security and privacy requirements of the organization. Contracts may specify documentation protection requirements. Related Controls:  AT-3, SA-2, SA-3, SA-4, SA-5, SA-8, SA-9, SA-10, SA-15, SR-6, SR-9, SR-10, SR-11.', 'vec_doc-14-nist-sp-800-53-p396-1538', 0, 227, 'v2.1.0', '7c8da48b242c1da38cf02ed0ccc310f5d784ca33b0bf872f9d3cbb1dc68383e0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 369","subsection":"UNKNOWN","table_id":null,"page":396,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1538,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 369"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p396-1539', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 369', 396, 'Control Enhancements: (1) ACQUISITION STRATEGIES, TOOLS, AND METHODS | ADEQUATE SUPPLY Employ the following controls to ensure an adequate supply of [Assignment: organization- defined critical system components]: [Assignment: organization-defined controls]. Discussion:  Adversaries can attempt to impede organizational operations by disrupting the supply of critical system components or corrupting supplier operations. Organizations may track systems and component mean time to failure to mitigate the loss of temporary or permanent system function. Controls to ensure that adequate supplies of critical system components include the use of multiple suppliers throughout the supply chain for the identified critical components, stockpiling spare components to ensure operation during mission-critical times, and the identification of functionally identical or similar components that may be used, if necessary. Related Controls:  RA-9.', 'vec_doc-14-nist-sp-800-53-p396-1539', 0, 235, 'v2.1.0', 'b8c23d26c23ee2b81eaa10e35e5313c3f71007c6d2a64e66c54eb5aa2d86f3dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 369","subsection":"UNKNOWN","table_id":null,"page":396,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1539,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 369"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p396-1540', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 369', 396, '(2) ACQUISITION STRATEGIES, TOOLS, AND METHODS | ASSESSMENTS PRIOR TO SELECTION, ACCEPTANCE, MODIFICATION, OR UPDATE Assess the system, system component, or system service prior to selection, acceptance, modification, or update. Discussion:  Organizational personnel or independent, external entities conduct assessments of systems, components, products, tools, and services to uncover evidence of tampering, unintentional and intentional vulnerabilities, or evidence of non-compliance with supply chain controls. These include malicious code, malicious processes, defective software, backdoors, and counterfeits. Assessments can include evaluations; design proposal reviews; visual or physical inspection; static and dynamic analyses; visual, x-ray, or magnetic particle inspections; simulations; white, gray, or black box testing; fuzz testing; stress testing; and penetration testing (see SR-6(1)). Evidence generated during assessments is documented for follow-on actions by organizations.', 'vec_doc-14-nist-sp-800-53-p396-1540', 0, 249, 'v2.1.0', '76def81a8abf8a6ab6e67dfb797d8d1731f160483050edd92f1311bedf245741', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 369","subsection":"UNKNOWN","table_id":null,"page":396,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1540,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 369"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p396-1541', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 369', 396, 'The evidence generated during the organizational or independent assessments of supply chain elements may be used to improve supply chain processes and inform the supply chain risk management process. The evidence can be leveraged in follow-on assessments. Evidence and other documentation may be shared in accordance with organizational agreements. Related Controls:  CA-8, RA-5, SA-11, SI-7. References:  [FASC18], [41 CFR 201], [EO 13873], [ISO 27036], [ISO 20243], [SP 800-30], [SP 800- 161], [IR 7622], [IR 8272]. SR-6 SUPPLIER ASSESSMENTS AND REVIEWS Control:  Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide [Assignment: organization-defined frequency].', 'vec_doc-14-nist-sp-800-53-p396-1541', 0, 192, 'v2.1.0', '2235b5507a16a5ea8038c20cd07313181445e7a684b04c588c962dc4f717d449', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 369","subsection":"UNKNOWN","table_id":null,"page":396,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1541,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 369"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p397-1542', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 370', 397, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 Discussion:  An assessment and review of supplier risk includes security and supply chain risk management processes, foreign ownership, control or influence (FOCI), and the ability of the supplier to effectively assess subordinate second-tier and third-tier suppliers and contractors. The reviews may be conducted by the organization or by an independent third party. The reviews consider documented processes, documented controls, all-source intelligence, and publicly available information related to the supplier or contractor. Organizations can use open-source information to monitor for indications of stolen information, poor development and quality control practices, information spillage, or counterfeits.', 'vec_doc-14-nist-sp-800-53-p397-1542', 0, 202, 'v2.1.0', '529abe3820df6adbb4a9b2066d5008a93b2b1a6a558ffed77cbfbe339bdc1d87', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 370","subsection":"UNKNOWN","table_id":null,"page":397,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1542,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 370"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p397-1543', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 370', 397, 'In some cases, it may be appropriate or required to share assessment and review results with other organizations in accordance with any applicable rules, policies, or inter-organizational agreements or contracts. Related Controls:  SR-3, SR-5. Control Enhancements: (1) SUPPLIER ASSESSMENTS AND REVIEWS | TESTING AND ANALYSIS Employ [Selection (one or more): organizational analysis; independent third-party analysis; organizational testing; independent third-party testing] of the following supply chain elements, processes, and actors associated with the system, system component, or system service: [Assignment: organization-defined supply chain elements, processes, and actors]. Discussion:  Relationships between entities and procedures within the supply chain, including development and delivery, are considered.', 'vec_doc-14-nist-sp-800-53-p397-1543', 0, 205, 'v2.1.0', 'a4ed058d093bfd5d3366742f9b7ff5039eb54b5506dfa530227cc722204a0f82', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 370","subsection":"UNKNOWN","table_id":null,"page":397,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1543,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 370"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p397-1544', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 370', 397, 'Supply chain elements include organizations, entities, or tools that are used for the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of systems, system components, or system services. Supply chain processes include supply chain risk management programs; SCRM strategies and implementation plans; personnel and physical security programs; hardware, software, and firmware development processes; configuration management tools, techniques, and measures to maintain provenance; shipping and handling procedures; and programs, processes, or procedures associated with the production and distribution of supply chain elements. Supply chain actors are individuals with specific roles and responsibilities in the supply chain. The evidence generated and collected during analyses and testing of supply chain elements, processes, and actors is documented and used to inform organizational risk management activities and decisions.', 'vec_doc-14-nist-sp-800-53-p397-1544', 0, 250, 'v2.1.0', '73dae02722e1c356a4e48fe9f898c36908b54f4041ac1ce65216d5b37891033c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 370","subsection":"UNKNOWN","table_id":null,"page":397,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1544,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 370"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p397-1545', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 370', 397, 'Related Controls:  CA-8, SI-4. References:  [FASC18], [41 CFR 201], [EO 13873], [ISO 27036], [ISO 20243], [FIPS 140-3], [FIPS 180-4], [FIPS 186-4], [FIPS 202], [SP 800-30], [SP 800-161], [IR 7622], [IR 8272]. SR-7 SUPPLY CHAIN OPERATIONS SECURITY Control:  Employ the following Operations Security (OPSEC) controls to protect supply chain- related information for the system, system component, or system service: [Assignment: organization-defined Operations Security (OPSEC) controls]. Discussion:  Supply chain OPSEC expands the scope of OPSEC to include suppliers and potential suppliers.', 'vec_doc-14-nist-sp-800-53-p397-1545', 0, 148, 'v2.1.0', '3713e0b3560ea44268f52f85fe2301c326d5cc24b1447885d095ed5d07b7e988', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 370","subsection":"UNKNOWN","table_id":null,"page":397,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1545,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 370"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p397-1546', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 370', 397, 'OPSEC is a process that includes identifying critical information, analyzing friendly actions related to operations and other activities to identify actions that can be observed by potential adversaries, determining indicators that potential adversaries might obtain that could be interpreted or pieced together to derive information in sufficient time to cause harm to organizations, implementing safeguards or countermeasures to eliminate or reduce exploitable vulnerabilities and risk to an acceptable level, and considering how aggregated information may expose users or specific uses of the supply chain. Supply chain information includes user identities; uses for systems, system components, and system services; supplier identities; security and privacy requirements; system and component configurations; supplier processes; design specifications; and testing and evaluation results. Supply chain OPSEC may require', 'vec_doc-14-nist-sp-800-53-p397-1546', 0, 231, 'v2.1.0', '53141161ecaf2e70cf522d08ba432f9330376c1d325731bac9444ee5484d51c9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 370","subsection":"UNKNOWN","table_id":null,"page":397,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1546,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 370"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p398-1547', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 371', 398, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 organizations to withhold mission or business information from suppliers and may include the use of intermediaries to hide the end use or users of systems, system components, or system services. Related Controls:  SC-38. Control Enhancements:  None. References:  [EO 13873], [SP 800-30], [ISO 27036], [SP 800-161], [IR 7622]. SR-8 NOTIFICATION AGREEMENTS Control:  Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the [Selection (one or more): notification of supply chain compromises; results of assessments or audits; [Assignment: organization-defined information]]. Discussion:  The establishment of agreements and procedures facilitates communications among supply chain entities.', 'vec_doc-14-nist-sp-800-53-p398-1547', 0, 216, 'v2.1.0', 'bdaebe28f77000176e5e52a5f23a9d2161053ba0cfecab36b2d28f87bf2c37d7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 371","subsection":"UNKNOWN","table_id":null,"page":398,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1547,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 371"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p398-1548', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 371', 398, 'Early notification of compromises and potential compromises in the supply chain that can potentially adversely affect or have adversely affected organizational systems or system components is essential for organizations to effectively respond to such incidents. The results of assessments or audits may include open-source information that contributed to a decision or result and could be used to help the supply chain entity resolve a concern or improve its processes. Related Controls:  IR-4, IR-6, IR-8. Control Enhancements:  None. References:  [FASC18], [41 CFR 201], [EO 13873], [ISO 27036], [SP 800-30], [SP 800-161], [IR 7622]. SR-9 TAMPER RESISTANCE AND DETECTION Control:  Implement a tamper protection program for the system, system component, or system service. Discussion:  Anti-tamper technologies, tools, and techniques provide a level of protection for systems, system components, and services against many threats, including reverse engineering, modification, and substitution.', 'vec_doc-14-nist-sp-800-53-p398-1548', 0, 249, 'v2.1.0', 'ae213bcea86e58569214013fdbdd1ec84e0f6f493ddec800b78332663bb135c2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 371","subsection":"UNKNOWN","table_id":null,"page":398,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1548,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 371"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p398-1549', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 371', 398, 'Strong identification combined with tamper resistance and/or tamper detection is essential to protecting systems and components during distribution and when in use. Related Controls:  PE-3, PM-30, SA-15, SI-4, SI-7, SR-3, SR-4, SR-5, SR-10, SR-11. Control Enhancements: (1) TAMPER RESISTANCE AND DETECTION | MULTIPLE STAGES OF SYSTEM DEVELOPMENT LIFE CYCLE Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle. Discussion:  The system development life cycle includes research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal. Organizations use a combination of hardware and software techniques for tamper resistance and detection. Organizations use obfuscation and self-checking to make reverse engineering and modifications more difficult, time-consuming, and expensive for adversaries.', 'vec_doc-14-nist-sp-800-53-p398-1549', 0, 226, 'v2.1.0', '65b3a088b9664baeb321024bcfa70278fdeedfdc443d048d46413f5d60e27c81', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 371","subsection":"UNKNOWN","table_id":null,"page":398,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1549,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 371"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p398-1550', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 371', 398, 'The customization of systems and system components can make substitutions easier to detect and therefore limit damage. Related Controls:  SA-3.', 'vec_doc-14-nist-sp-800-53-p398-1550', 0, 36, 'v2.1.0', 'a77d7479e2d77ed124c8227fd03d700516830603d4ab2898f2208d12b0271086', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 371","subsection":"UNKNOWN","table_id":null,"page":398,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1550,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 371"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p399-1551', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 372', 399, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 References:  [ISO 20243]. SR-10 INSPECTION OF SYSTEMS OR COMPONENTS Control:  Inspect the following systems or system components [Selection (one or more): at random; at [Assignment: organization-defined frequency], upon [Assignment: organization- defined indications of need for inspection]] to detect tampering: [Assignment: organization- defined systems or system components]. Discussion:  The inspection of systems or systems components for tamper resistance and detection addresses physical and logical tampering and is applied to systems and system components removed from organization-controlled areas. Indications of a need for inspection include changes in packaging, specifications, factory location, or entity in which the part is purchased, and when individuals return from travel to high-risk locations. Related Controls:  AT-3, PM-30, SI-4, SI-7, SR-3, SR-4, SR-5, SR-9, SR-11.', 'vec_doc-14-nist-sp-800-53-p399-1551', 0, 246, 'v2.1.0', '24b9f3a579d1a4956ad2623214cfa3157837b467ea2e207d9dc53431d097d00c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 372","subsection":"UNKNOWN","table_id":null,"page":399,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1551,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 372"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p399-1552', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 372', 399, 'References:  [ISO 20243]. SR-11 COMPONENT AUTHENTICITY Control: a. Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; and b. Report counterfeit system components to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]]. Discussion:  Sources of counterfeit components include manufacturers, developers, vendors, and contractors. Anti-counterfeiting policies and procedures support tamper resistance and provide a level of protection against the introduction of malicious code. External reporting organizations include CISA. Related Controls:  PE-3, SA-4, SI-7, SR-9, SR-10.', 'vec_doc-14-nist-sp-800-53-p399-1552', 0, 202, 'v2.1.0', 'e3e509ccc9d569bc420380abf61e10ad07b1ef005f21d676b19792e3a889c1e3', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 372","subsection":"UNKNOWN","table_id":null,"page":399,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1552,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 372"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p399-1553', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 372', 399, 'Control Enhancements: (1) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT TRAINING Train [Assignment: organization-defined personnel or roles] to detect counterfeit system components (including hardware, software, and firmware). Discussion:  None. Related Controls:  AT-3. (2) COMPONENT AUTHENTICITY | CONFIGURATION CONTROL FOR COMPONENT SERVICE AND REPAIR Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: [Assignment: organization-defined system components]. Discussion:  None. Related Controls:  CM-3, MA-2, MA-4, SA-10. (3) COMPONENT AUTHENTICITY | ANTI-COUNTERFEIT SCANNING Scan for counterfeit system components [Assignment: organization-defined frequency]. Discussion:  The type of component determines the type of scanning to be conducted (e.g., web application scanning if the component is a web application). Related Controls:  RA-5.', 'vec_doc-14-nist-sp-800-53-p399-1553', 0, 237, 'v2.1.0', '560e28c228eb1c2be79204da964cf612eddf5a1f1122b5c8e8a0c6d3c08b237d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 372","subsection":"UNKNOWN","table_id":null,"page":399,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1553,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 372"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p400-1554', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 400, 'This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 References:  [ISO 20243]. SR-12 COMPONENT DISPOSAL Control:  Dispose of [Assignment: organization-defined data, documentation, tools, or system components] using the following techniques and methods: [Assignment: organization-defined techniques and methods]. Discussion: Data, documentation, tools, or system components can be disposed of at any time during the system development life cycle (not only in the disposal or retirement phase of the life cycle). For example, disposal can occur during research and development, design, prototyping, or operations/maintenance and include methods such as disk cleaning, removal of cryptographic keys, partial reuse of components. Opportunities for compromise during disposal affect physical and logical data, including system documentation in paper-based or digital files; shipping and delivery documentation; memory sticks with software code; or complete routers or servers that include permanent media, which contain sensitive or proprietary information. Additionally, proper disposal of system components helps to prevent such components from entering the gray market. Related Controls:  MP-6. References:  None.', 'vec_doc-14-nist-sp-800-53-p400-1554', 0, 313, 'v2.1.0', 'a0f4668247e079fccec1d0974707c113d02da8c844c1f440976451d7669374a6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":400,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1554,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p401-1555', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 401, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ REFERENCES   PAGE 374 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 REFERENCES LAWS, POLICIES, DIRECTIVES, REGULATIONS, STANDARDS, AND GUIDELINES34 LAWS AND EXECUTIVE ORDERS [ATOM54] Atomic Energy Act (P.L. 83-703), August 1954. https://www.govinfo.gov/content/pkg/STATUTE-68/pdf/STATUTE-68-Pg919.pdf [CMPPA] Computer Matching and Privacy Protection Act of 1988 (P.L. 100-503), October 1988. https://www.govinfo.gov/content/pkg/STATUTE-102/pdf/STATUTE-102- Pg2507.pdf [EGOV] E-Government Act [includes FISMA] (P.L. 107-347), December 2002. https://www.congress.gov/107/plaws/publ347/PLAW-107publ347.pdf [EVIDACT] Foundations for Evidence-Based Policymaking Act of 2018 (P.L.', 'vec_doc-14-nist-sp-800-53-p401-1555', 0, 250, 'v2.1.0', '8190e01ae3079c424589856dbd6b1f100b17ee5fd5fc295f8b15b0b5eed5004c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":401,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1555,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
