INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p401-1557', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 401, 'https://www.congress.gov/107/plaws/publ56/PLAW-107publ56.pdf [USC 552] United States Code, 2006 Edition, Supplement 4, Title 5 - Government Organization and Employees, January 2011. https://www.govinfo.gov/content/pkg/USCODE-2010-title5/pdf/USCODE-2010- title5-partI-chap5-subchapII-sec552a.pdf [USC 2901] United States Code, 2008 Edition, Title 44 - Public Printing and Documents, Chapters 29, 31, and 33, January 2012. https://www.govinfo.gov/content/pkg/USCODE-2011-title44/pdf/USCODE-2011- title44-chap29-sec2901.pdf 34 The references cited in this appendix are those external publications that directly support the FISMA and Privacy Projects at NIST. Additional NIST standards, guidelines, and interagency reports are also cited throughout this publication, including in the references section of the applicable controls in Chapter Three. Direct links to the NIST website are provided to obtain access to those publications.', 'vec_doc-14-nist-sp-800-53-p401-1557', 0, 233, 'v2.1.0', '2710f9a6d846104438053fa9ea8f6c71438d1ebc75aabde403a7c8a8a0003f53', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":401,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1557,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
