INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p419-1623', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 419, 'https://www.niap-ccevs.org [NIST CAVP] National Institute of Standards and Technology (2020) Cryptographic Algorithm Validation Program. Available at https://csrc.nist.gov/projects/cryptographic-algorithm-validation-program [NIST CMVP] National Institute of Standards and Technology (2020) Cryptographic Module Validation Program. Available at https://csrc.nist.gov/projects/cryptographic-module-validation-program [NIST CSF] National Institute of Standards and Technology (2018) Framework for Improving Critical Infrastructure Cybersecurity, Version 1.1. (National Institute of Standards and Technology, Gaithersburg, MD). https://doi.org/10.6028/NIST.CSWP.04162018 [NIST PF] National Institute of Standards and Technology (2020) Privacy Framework: A Tool for Improving Privacy through Enterprise Risk Management, Version 1.0. (National Institute of Standards and Technology, Gaithersburg, MD).', 'vec_doc-14-nist-sp-800-53-p419-1623', 0, 224, 'v2.1.0', 'd356499e44922b59b2e0d9871cc289cc48b9498dbed5b3e07ceac0b4f0cf78cf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":419,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1623,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p419-1624', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 419, 'https://doi.org/10.6028/NIST.CSWP.01162020 [NCPR] National Institute of Standards and Technology (2020) National Checklist Program Repository. Available at https://nvd.nist.gov/ncp/repository [NVD 800-53] National Institute of Standards and Technology (2020) National Vulnerability Database: NIST Special Publication 800-53 [database of controls]. Available at https://nvd.nist.gov/800-53 [NEUM04] Principled Assuredly Trustworthy Composable Architectures, P. Neumann, CDRL A001 Final Report, SRI International, December 2004. http://www.csl.sri.com/users/neumann/chats4.pdf [NSA CSFC] National Security Agency, Commercial Solutions for Classified Program (CSfC). https://www.nsa.gov/resources/everyone/csfc [NSA MEDIA] National Security Agency, Media Destruction Guidance. https://www.nsa.gov/resources/everyone/media-destruction', 'vec_doc-14-nist-sp-800-53-p419-1624', 0, 208, 'v2.1.0', 'ad1ef269b6f1931084407d960bbdd2e895af6c1b0593a11def3bff86dea74d07', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":419,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1624,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p420-1625', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 420, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ REFERENCES   PAGE 393 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 [ODNI CTF] Office of the Director of National Intelligence (ODNI) Cyber Threat Framework. https://www.dni.gov/index.php/cyber-threat-framework [POPEK74] G. Popek, The Principle of Kernel Design, in 1974 NCC, AFIPS Cong. Proc., Vol. 43, pp. 977-978. [SALTZER75] J. Saltzer and M. Schroeder, The Protection of Information in Computer Systems, in Proceedings of the IEEE 63(9), September 1975, pp. 1278-1308. [SP 800-53 RES] NIST Special Publication 800-53, Revision 5 Resource Center. https://csrc.nist.gov/publications/detail/sp/800-53/rev-5/final [USGCB] National Institute of Standards and Technology (2020) United States Government Configuration Baseline. Available at https://csrc.nist.gov/projects/united-states-government-configuration-baseline', 'vec_doc-14-nist-sp-800-53-p420-1625', 0, 285, 'v2.1.0', '2aad310653c21df6804f822cc991fe10989e99a5dbd26b307a10a67596c8a712', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":420,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1625,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p421-1626', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 421, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 394 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 APPENDIX A GLOSSARY COMMON TERMS AND DEFINITIONS Appendix A provides definitions for terminology used in NIST Special Publication 800-53. Sources for terms used in this publication are cited as applicable. Where no citation is noted, the source of the definition is Special Publication 800-53. access control [FIPS 201-2] The process of granting or denying specific requests for obtaining and using information and related information processing services; and to enter specific physical facilities (e.g., Federal buildings, military establishments, and border crossing entrances).', 'vec_doc-14-nist-sp-800-53-p421-1626', 0, 243, 'v2.1.0', 'c264055e1463746fef1ea0511d40c70ec306cff91dc8a27e4f0d279f4bcc1faa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":421,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1626,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p421-1627', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 421, 'adequate security [OMB A-130] Security protections commensurate with the risk resulting from the unauthorized access, use, disclosure, disruption, modification, or destruction of information. This includes ensuring that information hosted on behalf of an agency and information systems and applications used by the agency operate effectively and provide appropriate confidentiality, integrity, and availability protections through the application of cost-effective security controls. advanced persistent threat [SP 800-39] An adversary that possesses sophisticated levels of expertise and significant resources which allow it to create opportunities to achieve its objectives by using multiple attack vectors, including cyber, physical, and deception.', 'vec_doc-14-nist-sp-800-53-p421-1627', 0, 188, 'v2.1.0', 'cd3d12b0b44b696c4606081b8f08aaebc0f54005cc84071c3ef682a5ee6d368e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":421,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1627,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p421-1628', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 421, 'These objectives typically include establishing and extending footholds within the IT infrastructure of the targeted organizations for purposes of exfiltrating information, undermining or impeding critical aspects of a mission, program, or organization; or positioning itself to carry out these objectives in the future. The advanced persistent threat pursues its objectives repeatedly over an extended period; adapts to defenders’ efforts to resist it; and is determined to maintain the level of interaction needed to execute its objectives. agency [OMB A-130] Any executive agency or department, military department, Federal Government corporation, Federal Government- controlled corporation, or other establishment in the Executive Branch of the Federal Government, or any independent regulatory agency. See executive agency.', 'vec_doc-14-nist-sp-800-53-p421-1628', 0, 207, 'v2.1.0', '91791536de6c48f1ecf730d82a6227d8ca21780a30eda8e2dde90b46018995b9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":421,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1628,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p421-1629', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 421, 'all-source intelligence [DODTERMS] Intelligence products and/or organizations and activities that incorporate all sources of information, most frequently including human resources intelligence, imagery intelligence, measurement and signature intelligence, signals intelligence, and open-source data in the production of finished intelligence.', 'vec_doc-14-nist-sp-800-53-p421-1629', 0, 86, 'v2.1.0', '56a6b9806d85b076086ee7b17f33da70b1f20ca8820ef49ad3b819b0d13ef2ae', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":421,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1629,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p422-1630', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 422, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 395 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 application [SP 800-37] A software program hosted by an information system. assessment See control assessment  or risk assessment. assessment plan The objectives for the security and privacy control assessments and a detailed roadmap of how to conduct such assessments. assessor The individual, group, or organization responsible for conducting a security or privacy control assessment.', 'vec_doc-14-nist-sp-800-53-p422-1630', 0, 195, 'v2.1.0', '4d43cf6848233ba193562a275dffe580858fb4c7ffdcc9d359816c15bff17d39', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":422,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1630,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p422-1631', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 422, 'assignment operation A control parameter that allows an organization to assign a specific, organization-defined value to the control or control enhancement (e.g., assigning a list of roles to be notified or a value for the frequency of testing). See organization-defined control parameters and selection operation. assurance [ISO/IEC 15026, Adapted] Grounds for justified confidence that a [security or privacy] claim has been or will be achieved. Note 1: Assurance is typically obtained relative to a set of specific claims. The scope and focus of such claims may vary (e.g., security claims, safety claims) and the claims themselves may be interrelated. Note 2: Assurance is obtained through techniques and methods that generate credible evidence to substantiate claims. attack surface The set of points on the boundary of a system, a system component, or an environment where an attacker can try to enter, cause an effect on, or extract data from, that system, component, or environment.', 'vec_doc-14-nist-sp-800-53-p422-1631', 0, 248, 'v2.1.0', 'd0a747c8b8a1f29fd742e64557c3a665f055b086b8bee17079a68ee7af3b85fd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":422,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1631,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p422-1632', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 422, 'audit [CNSSI 4009] Independent review and examination of records and activities to assess the adequacy of system controls, to ensure compliance with established policies and operational procedures. audit log [CNSSI 4009] A chronological record of system activities, including records of system accesses and operations performed in a given period. audit record An individual entry in an audit log related to an audited event. audit record reduction A process that manipulates collected audit information and organizes it into a summary format that is more meaningful to analysts. audit trail A chronological record that reconstructs and examines the sequence of activities surrounding or leading to a specific operation, procedure, or event in a security-relevant transaction from inception to result. authentication [FIPS 200] Verifying the identity of a user, process, or device, often as a prerequisite to allowing access to resources in a system.', 'vec_doc-14-nist-sp-800-53-p422-1632', 0, 238, 'v2.1.0', 'f61e5304fb6ebca56dd4e9e472b43e6a70f37a7cbaf57ce0b6c44a836e2e43ea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":422,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1632,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p423-1633', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 423, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 396 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 authenticator Something that the claimant possesses and controls (typically a cryptographic module or password) that is used to authenticate the claimant’s identity. This was previously referred to as a token. authenticity The property of being genuine and being able to be verified and trusted; confidence in the validity of a transmission, message, or message originator. See authentication. authorization [CNSSI 4009] Access privileges granted to a user, program, or process or the act of granting those privileges.', 'vec_doc-14-nist-sp-800-53-p423-1633', 0, 228, 'v2.1.0', '0b93c1ea25f7d024c8f5e98009cf612d5d712d860bbad64f3fabc6b8a84b4c97', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":423,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1633,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p423-1634', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 423, 'authorization boundary [OMB A-130] All components of an information system to be authorized for operation by an authorizing official. This excludes separately authorized systems to which the information system is connected. authorization to operate [OMB A-130] The official management decision given by a senior Federal official or officials to authorize operation of an information system and to explicitly accept the risk to agency operations (including mission, functions, image, or reputation), agency assets, individuals, other organizations, and the Nation based on the implementation of an agreed-upon set of security and privacy controls. Authorization also applies to common controls inherited by agency information systems.', 'vec_doc-14-nist-sp-800-53-p423-1634', 0, 184, 'v2.1.0', 'd790498015d00f5d89234cab38a5cc42ac296904997bc80b677baf464593176a', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":423,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1634,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p423-1635', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 423, 'authorizing official [OMB A-130] A senior Federal official or executive with the authority to authorize (i.e., assume responsibility for) the operation of an information system or the use of a designated set of common controls at an acceptable level of risk to agency operations (including mission, functions, image, or reputation), agency assets, individuals, other organizations, and the Nation. availability [FISMA] Ensuring timely and reliable access to and use of information. baseline See control baseline. baseline configuration [SP 800-128, Adapted] A documented set of specifications for a system, or a configuration item within a system, that has been formally reviewed and agreed on at a given point in time, and which can be changed only through change control procedures. boundary [CNSSI 4009] Physical or logical perimeter of a system. See also authorization boundary and interface.', 'vec_doc-14-nist-sp-800-53-p423-1635', 0, 224, 'v2.1.0', '10fa51a435977ce0ea59c99fc94c2de41e34f7ca97cb32582310e2daacaa8fcb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":423,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1635,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p423-1636', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 423, 'boundary protection Monitoring and control of communications at the external interface to a system to prevent and detect malicious and other unauthorized communications using boundary protection devices.', 'vec_doc-14-nist-sp-800-53-p423-1636', 0, 51, 'v2.1.0', 'd2a93e2178595b613bbffa73d6f7a23d0ece235935792bb1b5b7c871d37f8328', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":423,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1636,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p424-1637', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 424, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 397 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 boundary protection device A device (e.g., gateway, router, firewall, guard, or encrypted tunnel) that facilitates the adjudication of different system security policies for connected systems or provides boundary protection. The boundary may be the authorization boundary for a system, the organizational network boundary, or a logical boundary defined by the organization.', 'vec_doc-14-nist-sp-800-53-p424-1637', 0, 191, 'v2.1.0', '563b7f623ff8075c696bb121318b672ebaf803e96d411efcf9fb65359f8701f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":424,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1637,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p424-1638', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 424, 'breach [OMB M-17-12] The loss of control, compromise, unauthorized disclosure, unauthorized acquisition, or any similar occurrence where: a person other than an authorized user accesses or potentially accesses personally identifiable information; or an authorized user accesses personally identifiable information for another than authorized purpose. breadth [SP 800-53A] An attribute associated with an assessment method that addresses the scope or coverage of the assessment objects included with the assessment. capability A combination of mutually reinforcing security and/or privacy controls implemented by technical, physical, and procedural means. Such controls are typically selected to achieve a common information security- or privacy-related purpose. central management The organization-wide management and implementation of selected security and privacy controls and related processes.', 'vec_doc-14-nist-sp-800-53-p424-1638', 0, 225, 'v2.1.0', '09bdfcfa8d2ead6ecb2063931c77471a7382655c071b79b168f0ad222b9f7897', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":424,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1638,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p424-1639', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 424, 'Central management includes planning, implementing, assessing, authorizing, and monitoring the organization-defined, centrally managed security and privacy controls and processes. checksum [IETF 4949] A value that (a) is computed by a function that is dependent on the contents of a data object and (b) is stored or transmitted together with the object, for detecting changes in the data.', 'vec_doc-14-nist-sp-800-53-p424-1639', 0, 97, 'v2.1.0', 'ec0eafab7c026e994059e834e942fa1eb1688be00520a529e9fa6edb37358ac9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":424,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1639,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p424-1640', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 424, 'chief information officer [OMB A-130] The senior official that provides advice and other assistance to the head of the agency and other senior management personnel of the agency to ensure that IT is acquired and information resources are managed for the agency in a manner that achieves the agency’s strategic goals and information resources management goals; and is responsible for ensuring agency compliance with, and prompt, efficient, and effective implementation of, the information policies and information resources management responsibilities, including the reduction of information collection burdens on the public. chief information security officer See senior agency information security officer. classified information See classified national security information.', 'vec_doc-14-nist-sp-800-53-p424-1640', 0, 194, 'v2.1.0', '0f367407f2874e459d7d416e8c29a861b998520762e0673e23480143071fa171', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":424,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1640,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p424-1641', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 424, 'classified national security information [EO 13526] Information that has been determined pursuant to Executive Order (E.O.) 13526 or any predecessor order to require protection against unauthorized disclosure and is marked to indicate its classified status when in documentary form.', 'vec_doc-14-nist-sp-800-53-p424-1641', 0, 71, 'v2.1.0', 'd14e80cca13ef9f78fd7db0307c48cfa5e38d2823bb04a15f94422f1fc1bb487', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":424,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1641,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p425-1642', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 425, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 398 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 commodity service A system service provided by a commercial service provider to a large and diverse set of consumers. The organization acquiring or receiving the commodity service possesses limited visibility into the management structure and operations of the provider, and while the organization may be able to negotiate service-level agreements, the organization is typically not able to require that the provider implement specific security or privacy controls. common carrier A telecommunications company that holds itself out to the public for hire to provide communications transmission services.', 'vec_doc-14-nist-sp-800-53-p425-1642', 0, 249, 'v2.1.0', 'defc090eb2af2c7808f238093ab458eda07f958e94a9ba85bbf9fa1069d27c4b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":425,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1642,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p425-1643', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 425, 'common control [OMB A-130] A security or privacy control that is inherited by multiple information systems or programs. common control provider [SP 800-37] An organizational official responsible for the development, implementation, assessment, and monitoring of common controls (i.e., security or privacy controls inheritable by systems). common criteria [CNSSI 4009] Governing document that provides a comprehensive, rigorous method for specifying security function and assurance requirements for products and systems. common secure configuration [SP 800-128] A recognized standardized and established benchmark that stipulates specific secure configuration settings for a given information technology platform. compensating controls The security and privacy controls employed in lieu of the controls in the baselines described in NIST Special Publication 800-53B that provide equivalent or comparable protection for a system or organization. component See system component.', 'vec_doc-14-nist-sp-800-53-p425-1643', 0, 244, 'v2.1.0', '5ac1c3c28b7fcfaee4784d56c3de6057f1c57a0848c6e034881a5962825ba5f7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":425,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1643,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p425-1644', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 425, 'confidentiality [FISMA] Preserving authorized restrictions on information access and disclosure, including means for protecting personal privacy and proprietary information. configuration control [SP 800-128] Process for controlling modifications to hardware, firmware, software, and documentation to protect the system against improper modifications before, during, and after system implementation. configuration item [SP 800-128] An aggregation of system components that is designated for configuration management and treated as a single entity in the configuration management process. configuration management [SP 800-128] A collection of activities focused on establishing and maintaining the integrity of information technology products and systems, through control of processes for initializing, changing, and monitoring the configurations of those products and systems throughout the system development life cycle.', 'vec_doc-14-nist-sp-800-53-p425-1644', 0, 231, 'v2.1.0', 'fdbaa53194850061dcf172c6999494117827feec3fe1438f2ab47055606c035d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":425,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1644,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p426-1645', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 426, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 399 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 configuration settings [SP 800-128] The set of parameters that can be changed in hardware, software, or firmware that affect the security posture and/or functionality of the system. continuous monitoring [SP 800-137] Maintaining ongoing awareness to support organizational risk decisions. control See security control or privacy control.', 'vec_doc-14-nist-sp-800-53-p426-1645', 0, 182, 'v2.1.0', '04e434cd8f7c8585cd3e2dd5b1c3bc190421ea15aa3e60cbe3ea74e806afa3b8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":426,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1645,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p426-1646', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 426, 'control assessment [SP 800-37] The testing or evaluation of the controls in an information system or an organization to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting the security or privacy requirements for the system or the organization. control assessor See assessor. control baseline [SP 800-53B] Predefined sets of controls specifically assembled to address the protection needs of groups, organizations, or communities of interest. See privacy control baseline or security control baseline. control effectiveness A measure of whether a security or privacy control contributes to the reduction of information security or privacy risk. control enhancement Augmentation of a security or privacy control to build in additional but related functionality to the control, increase the strength of the control, or add assurance to the control.', 'vec_doc-14-nist-sp-800-53-p426-1646', 0, 237, 'v2.1.0', '4e719fdb605208d83e85d3d8a691ab7c98852051b46af55b357a5f1267a2ac2c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":426,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1646,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p426-1647', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 426, 'control inheritance A situation in which a system or application receives protection from security or privacy controls (or portions of controls) that are developed, implemented, assessed, authorized, and monitored by entities other than those responsible for the system or application; entities either internal or external to the organization where the system or application resides. See common control. control parameter See organization-defined control parameter. controlled area Any area or space for which an organization has confidence that the physical and procedural protections provided are sufficient to meet the requirements established for protecting the information and/or information system. controlled interface An interface to a system with a set of mechanisms that enforces the security policies and controls the flow of information between connected systems.', 'vec_doc-14-nist-sp-800-53-p426-1647', 0, 219, 'v2.1.0', '0f03c00d769e4bd0baaae94f3b712c52d9df796b8882294347212dbabebe0278', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":426,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1647,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p427-1648', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 427, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 400 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 controlled unclassified information [32 CFR 2002] Information that the Government creates or possesses, or that an entity creates or possesses for or on behalf of the Government, that a law, regulation, or Government-wide policy requires or permits an agency to handle using safeguarding or dissemination controls. However, CUI does not include classified information or information a non-executive branch entity possesses and maintains in its own systems that did not come from, or was not created or possessed by or for, an executive branch agency or an entity acting for an agency.', 'vec_doc-14-nist-sp-800-53-p427-1648', 0, 244, 'v2.1.0', '35d837a188275a3a402c103a14ad2dde8089b4603509eee915dc3e597b139145', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":427,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1648,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p427-1649', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 427, 'counterfeit [SP 800-161] An unauthorized copy or substitute that has been identified, marked, and/or altered by a source other than the item''s legally authorized source and has been misrepresented to be an authorized item of the legally authorized source. countermeasures [FIPS 200] Actions, devices, procedures, techniques, or other measures that reduce the vulnerability of a system. Synonymous with security controls and safeguards. covert channel [CNSSI 4009] An unintended or unauthorized intra-system channel that enables two cooperating entities to transfer information in a way that violates the system''s security policy but does not exceed the entities'' access authorizations. covert channel analysis [CNSSI 4009] Determination of the extent to which the security policy model and subsequent lower-level program descriptions may allow unauthorized access to information.', 'vec_doc-14-nist-sp-800-53-p427-1649', 0, 220, 'v2.1.0', 'c4421047374bca34c44ca27fd79ed95b2feb0cda7a68a59adcbe1ff3526b5417', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":427,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1649,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p427-1650', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 427, 'covert storage channel [CNSSI 4009] A system feature that enables one system entity to signal information to another entity by directly or indirectly writing to a storage location that is later directly or indirectly read by the second entity. covert timing channel [CNSSI 4009, Adapted] A system feature that enables one system entity to signal information to another by modulating its own use of a system resource in such a way as to affect system response time observed by the second entity. credential [SP 800-63-3] An object or data structure that authoritatively binds an identity, via an identifier or identifiers, and (optionally) additional attributes, to at least one authenticator possessed and controlled by a subscriber.', 'vec_doc-14-nist-sp-800-53-p427-1650', 0, 184, 'v2.1.0', 'b5cb04e1366d28ce565ee8deb52a6531dee14edb5e9a646d435cd6d4ff5d0126', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":427,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1650,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p427-1651', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 427, 'critical infrastructure [USA PATRIOT] Systems and assets, whether physical or virtual, so vital to the United States that the incapacity or destruction of such systems and assets would have a debilitating impact on security, national economic security, national public health or safety, or any combination of those matters. cross domain solution [CNSSI 1253] A form of controlled interface that provides the ability to manually and/or automatically access and/or transfer information between different security domains.', 'vec_doc-14-nist-sp-800-53-p427-1651', 0, 130, 'v2.1.0', '90a010c39dcb98498a42bebb38840ee0a67ae1cbe2a8464ee3b46f07fb828874', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":427,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1651,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p428-1652', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 428, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 401 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 cryptographic module [FIPS 140-3] The set of hardware, software, and/or firmware that implements Approved security functions (including cryptographic algorithms and key generation) and is contained within the cryptographic boundary. cybersecurity [OMB A-130] Prevention of damage to, protection of, and restoration of computers, electronic communications systems, electronic communications services, wire communication, and electronic communication, including information contained therein, to ensure its availability, integrity, authentication, confidentiality, and nonrepudiation.', 'vec_doc-14-nist-sp-800-53-p428-1652', 0, 244, 'v2.1.0', '798a6c6f96bd35a7e7d52f4ccb1a6cbe6478522d0120335324b2ea191eba982c', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":428,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1652,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p428-1653', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 428, 'cyberspace [CNSSI 4009] The interdependent network of information technology infrastructures that includes the Internet, telecommunications networks, computer systems, and embedded processors and controllers in critical industries. data action [IR 8062] A system operation that processes personally identifiable information. data mining An analytical process that attempts to find correlations or patterns in large data sets for the purpose of data or knowledge discovery. de-identification [ISO 25237] General term for any process of removing the association between a set of identifying data and the data subject.', 'vec_doc-14-nist-sp-800-53-p428-1653', 0, 154, 'v2.1.0', '87042e4f2b01f7321fcb5c2a656268b5b9acd507cff628cb58ed7b5b1680d8cd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":428,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1653,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p428-1654', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 428, 'defense in breadth [CNSSI 4009] A planned, systematic set of multidisciplinary activities that seek to identify, manage, and reduce risk of exploitable vulnerabilities at every stage of the system, network, or subcomponent life cycle, including system, network, or product design and development; manufacturing; packaging; assembly; system integration; distribution; operations; maintenance; and retirement. defense in depth An information security strategy that integrates people, technology, and operations capabilities to establish variable barriers across multiple layers and missions of the organization. depth [SP 800-53A] An attribute associated with an assessment method that addresses the rigor and level of detail associated with the application of the method. developer A general term that includes developers or manufacturers of systems, system components, or system services; systems integrators; vendors; and product resellers.', 'vec_doc-14-nist-sp-800-53-p428-1654', 0, 236, 'v2.1.0', '996a97852c6c4e0f3df8dc457f1d4f1d33656a21dc1bb1fb400fe6122519e0b0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":428,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1654,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p428-1655', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 428, 'The development of systems, components, or services can occur internally within organizations or through external entities. digital media A form of electronic media where data is stored in digital (as opposed to analog) form.', 'vec_doc-14-nist-sp-800-53-p428-1655', 0, 57, 'v2.1.0', '8680d6c4afb2e8de4d2c6d86a33ae1ee9a682cd333b3445a0e00e9b62a0a2ef7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":428,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1655,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p429-1656', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 429, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 402 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 discretionary access control An access control policy that is enforced over all subjects and objects in a system where the policy specifies that a subject that has been granted access to information can do one or more of the following: pass the information to other subjects or objects; grant its privileges to other subjects; change the security attributes of subjects, objects, systems, or system components; choose the security attributes to be associated with newly- created or revised objects; or change the rules governing access control. Mandatory access controls restrict this capability.', 'vec_doc-14-nist-sp-800-53-p429-1656', 0, 247, 'v2.1.0', '7aebe386cbbc245866a28da254f873b5cef214942633a8959e40b94f60c952a5', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":429,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1656,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p429-1657', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 429, 'disassociability [IR 8062] Enabling the processing of personally identifiable information or events without association to individuals or devices beyond the operational requirements of the system. domain An environment or context that includes a set of system resources and a set of system entities that have the right to access the resources as defined by a common security policy, security model, or security architecture. See security domain. enterprise [CNSSI 4009] An organization with a defined mission/goal and a defined boundary, using systems to execute that mission, and with responsibility for managing its own risks and performance. An enterprise may consist of all or some of the following business aspects: acquisition, program management, human resources, financial management, security, and systems, information and mission management. See organization.', 'vec_doc-14-nist-sp-800-53-p429-1657', 0, 218, 'v2.1.0', '32d5990f81a2d90dc833cccdefcdef705a47a6294ca6afe3cb10f471f2048922', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":429,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1657,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p429-1658', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 429, 'enterprise architecture [OMB A-130] A strategic information asset base, which defines the mission; the information necessary to perform the mission; the technologies necessary to perform the mission; and the transitional processes for implementing new technologies in response to changing mission needs; and includes a baseline architecture; a target architecture; and a sequencing plan. environment of operation [OMB A-130] The physical surroundings in which an information system processes, stores, and transmits information. event [SP 800-61, Adapted] Any observable occurrence in a system. executive agency [OMB A-130] An executive department specified in 5 U.S.C., Sec. 101; a military department specified in 5 U.S.C., Sec. 102; an independent establishment as defined in 5 U.S.C., Sec. 104(1); and a wholly owned Government corporation fully subject to the provisions of 31 U.S.C., Chapter 91. exfiltration The unauthorized transfer of information from a system.', 'vec_doc-14-nist-sp-800-53-p429-1658', 0, 243, 'v2.1.0', '652c05a2c38c925b62254bad034298119913c64b06de1159cb7f903e981033e6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":429,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1658,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p429-1659', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 429, 'external system (or component) A system or component of a system that is used by but is not a part of an organizational system and for which the organization has no direct control over the implementation of required security and privacy controls or the assessment of control effectiveness.', 'vec_doc-14-nist-sp-800-53-p429-1659', 0, 73, 'v2.1.0', '4ade906a152e07f4e5c2b283efb2819b7b4f7cfa4ea85215e265c192b33bbfd1', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":429,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1659,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p430-1660', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 430, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 403 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 external system service A system service that is provided by an external service provider and for which the organization has no direct control over the implementation of required security and privacy controls or the assessment of control effectiveness. external system service provider A provider of external system services to an organization through a variety of consumer-producer relationships, including joint ventures, business partnerships, outsourcing arrangements (i.e., through contracts, interagency agreements, lines of business arrangements), licensing agreements, and/or supply chain exchanges.', 'vec_doc-14-nist-sp-800-53-p430-1660', 0, 250, 'v2.1.0', 'd8894bec5a3336b2556606444202c3104a7cb469e39b21ced1f3da9c021e2b1f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":430,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1660,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p430-1661', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 430, 'external network A network not controlled by the organization. failover The capability to switch over automatically (typically without human intervention or warning) to a redundant or standby system upon the failure or abnormal termination of the previously active system. federal information system [OMB A-130] An information system used or operated by an executive agency, by a contractor of an executive agency, or by another organization on behalf of an executive agency. FIPS-validated cryptography A cryptographic module validated by the Cryptographic Module Validation Program (CMVP) to meet requirements specified in FIPS Publication 140-3 (as amended). As a prerequisite to CMVP validation, the cryptographic module is required to employ a cryptographic algorithm implementation that has successfully passed validation testing by the Cryptographic Algorithm Validation Program (CAVP). See NSA-approved cryptography.', 'vec_doc-14-nist-sp-800-53-p430-1661', 0, 231, 'v2.1.0', 'e1d864dd666b50412a79c5ad703239e6f7fb09eff8cb7a9fd15c9b14bb9015f2', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":430,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1661,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p430-1662', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 430, 'firmware [CNSSI 4009] Computer programs and data stored in hardware - typically in read-only memory (ROM) or programmable read-only memory (PROM) - such that the programs and data cannot be dynamically written or modified during execution of the programs. See hardware and software. hardware [CNSSI 4009] The material physical components of a system. See software and firmware. high-impact system [FIPS 200] A system in which at least one security objective (i.e., confidentiality, integrity, or availability) is assigned a FIPS Publication 199 potential impact value of high. hybrid control [OMB A-130] A security or privacy control that is implemented for an information system in part as a common control and in part as a system-specific control. identifier [FIPS 201-2] Unique data used to represent a person’s identity and associated attributes. A name or a card number are examples of identifiers. A unique label used by a system to indicate a specific entity, object, or group.', 'vec_doc-14-nist-sp-800-53-p430-1662', 0, 246, 'v2.1.0', 'fe2a524be340c5b6505b0aaa30068561563bdf032457def410bf3234467aa349', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":430,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1662,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p431-1663', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 431, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 404 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 impact The effect on organizational operations, organizational assets, individuals, other organizations, or the Nation (including the national security interests of the United States) of a loss of confidentiality, integrity, or availability of information or a system. impact value [FIPS 199] The assessed worst-case potential impact that could result from a compromise of the confidentiality, integrity, or availability of information expressed as a value of low, moderate or high.', 'vec_doc-14-nist-sp-800-53-p431-1663', 0, 219, 'v2.1.0', '9e1c87e490fed7e40938078ba4d248a3edb9842f5671ea8d763b6109d31f08c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":431,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1663,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p431-1664', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 431, 'incident [FISMA] An occurrence that actually or imminently jeopardizes, without lawful authority, the confidentiality, integrity, or availability of information or an information system; or constitutes a violation or imminent threat of violation of law, security policies, security procedures, or acceptable use policies. industrial control system [SP 800-82] General term that encompasses several types of control systems, including supervisory control and data acquisition (SCADA) systems, distributed control systems (DCS), and other control system configurations such as programmable logic controllers (PLC) found in the industrial sectors and critical infrastructures. An industrial control system consists of combinations of control components (e.g., electrical, mechanical, hydraulic, pneumatic) that act together to achieve an industrial objective (e.g., manufacturing, transportation of matter or energy).', 'vec_doc-14-nist-sp-800-53-p431-1664', 0, 229, 'v2.1.0', '81b5e23703e1e17b253132aeb14f9218d1cbd177d2966bd5e34e200874f6a82d', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":431,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1664,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p431-1665', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 431, 'information [OMB A-130] Any communication or representation of knowledge such as facts, data, or opinions in any medium or form, including textual, numerical, graphic, cartographic, narrative, electronic, or audiovisual forms. information flow control Controls to ensure that information transfers within a system or organization are not made in violation of the security policy. information leakage The intentional or unintentional release of information to an untrusted environment. information owner [SP 800-37] Official with statutory or operational authority for specified information and responsibility for establishing the controls for its generation, collection, processing, dissemination, and disposal. information resources [OMB A-130] Information and related resources, such as personnel, equipment, funds, and information technology.', 'vec_doc-14-nist-sp-800-53-p431-1665', 0, 212, 'v2.1.0', 'bd449f5d33677fa8fa9b7622f576525655051de177d5f2ff786a79da48698607', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":431,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1665,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p431-1666', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 431, 'information security [OMB A-130] The protection of information and systems from unauthorized access, use, disclosure, disruption, modification, or destruction in order to provide confidentiality, integrity, and availability. information security architecture [OMB A-130] An embedded, integral part of the enterprise architecture that describes the structure and behavior of the enterprise security processes, security systems, personnel and organizational subunits, showing their alignment with the enterprise’s mission and strategic plans.', 'vec_doc-14-nist-sp-800-53-p431-1666', 0, 135, 'v2.1.0', 'e10849a5895ff9fee9497ccc3120532e9eb528102256f0911161dd3077e7af00', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":431,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1666,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p432-1667', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 432, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 405 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 information security policy [CNSSI 4009] Aggregate of directives, regulations, rules, and practices that prescribes how an organization manages, protects, and distributes information. information security program plan [OMB A-130] Formal document that provides an overview of the security requirements for an organization-wide information security program and describes the program management controls and common controls in place or planned for meeting those requirements.', 'vec_doc-14-nist-sp-800-53-p432-1667', 0, 216, 'v2.1.0', 'ad71f066c22c0a8a1b98c428c39e32f083b36fe14cc384026b15f2287ccaa794', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":432,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1667,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p432-1668', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 432, 'information security risk [SP 800-30] The risk to organizational operations (including mission, functions, image, reputation), organizational assets, individuals, other organizations, and the Nation due to the potential for unauthorized access, use, disclosure, disruption, modification, or destruction of information and/or systems. information steward [SP 800-37] An agency official with statutory or operational authority for specified information and responsibility for establishing the controls for its generation, collection, processing, dissemination, and disposal. information system [USC 3502] A discrete set of information resources organized for the collection, processing, maintenance, use, sharing, dissemination, or disposition of information.', 'vec_doc-14-nist-sp-800-53-p432-1668', 0, 190, 'v2.1.0', '531c6cd8f009b9c3f7b482bdb514a038a571da705783828c2fd0f857fc3b7391', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":432,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1668,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p432-1669', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 432, 'information technology [USC 11101] Any services, equipment, or interconnected system(s) or subsystem(s) of equipment, that are used in the automatic acquisition, storage, analysis, evaluation, manipulation, management, movement, control, display, switching, interchange, transmission, or reception of data or information by the agency. For purposes of this definition, such services or equipment if used by the agency directly or is used by a contractor under a contract with the agency that requires its use; or to a significant extent, its use in the performance of a service or the furnishing of a product.', 'vec_doc-14-nist-sp-800-53-p432-1669', 0, 153, 'v2.1.0', 'd9a59390a87969909fc074991bfd3e7f1d21b23dc4bd5a68df0da3a262a93c23', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":432,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1669,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p432-1670', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 432, 'Information technology includes computers, ancillary equipment (including imaging peripherals, input, output, and storage devices necessary for security and surveillance), peripheral equipment designed to be controlled by the central processing unit of a computer, software, firmware and similar procedures, services (including cloud computing and help-desk services or other professional services which support any point of the life cycle of the equipment or service), and related resources. Information technology does not include any equipment that is acquired by a contractor incidental to a contract which does not require its use. information technology product See system component.', 'vec_doc-14-nist-sp-800-53-p432-1670', 0, 173, 'v2.1.0', 'aa9f9956177882bf7be196d27669c6b7a0454cbd0f54139272966cd095ac7898', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":432,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1670,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p433-1671', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 433, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 406 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 information type [FIPS 199] A specific category of information (e.g., privacy, medical, proprietary, financial, investigative, contractor-sensitive, security management) defined by an organization or in some instances, by a specific law, Executive Order, directive, policy, or regulation. insider [CNSSI 4009, Adapted] Any person with authorized access to any organizational resource, to include personnel, facilities, information, equipment, networks, or systems.', 'vec_doc-14-nist-sp-800-53-p433-1671', 0, 214, 'v2.1.0', '404dc610cadca473c4e4eb3b3c34c3b72f573081ae8b41ef8d164babc62411b6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":433,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1671,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p433-1672', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 433, 'insider threat [CNSSI 4009, Adapted] The threat that an insider will use her/his authorized access, wittingly or unwittingly, to do harm to the security of organizational operations and assets, individuals, other organizations, and the Nation. This threat can include damage through espionage, terrorism, unauthorized disclosure of national security information, or through the loss or degradation of organizational resources or capabilities. insider threat program [CNSSI 4009, Adapted] A coordinated collection of capabilities authorized by the organization and used to deter, detect, and mitigate the unauthorized disclosure of information. interface [CNSSI 4009] Common boundary between independent systems or modules where interactions take place. integrity [FISMA] Guarding against improper information modification or destruction, and includes ensuring information non-repudiation and authenticity.', 'vec_doc-14-nist-sp-800-53-p433-1672', 0, 227, 'v2.1.0', '44e9827f5944e9ace0c99dad175e3cba9d567b2fafdb45af96407cdd703362f0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":433,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1672,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p433-1673', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 433, 'internal network A network where the establishment, maintenance, and provisioning of security controls are under the direct control of organizational employees or contractors. Cryptographic encapsulation or similar security technology implemented between organization-controlled endpoints provides the same effect (at least regarding confidentiality and integrity). An internal network is typically organization-owned yet may be organization-controlled while not being organization-owned. label See security label. least privilege [CNSSI 4009] The principle that a security architecture is designed so that each entity is granted the minimum system resources and authorizations that the entity needs to perform its function. local access Access to an organizational system by a user (or process acting on behalf of a user) communicating through a direct connection without the use of a network.', 'vec_doc-14-nist-sp-800-53-p433-1673', 0, 224, 'v2.1.0', '67213d1291087852034c4a3f4506609f0966c40a3a66166bd56e0722350a0350', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":433,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1673,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p434-1674', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 434, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 407 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 logical access control system An automated system that controls an individual’s ability to access one or more computer system resources, such as a workstation, network, application, or database. A logical access control system requires the validation of an individual’s identity through some mechanism, such as a PIN, card, biometric, or other token. It has the capability to assign different access privileges to different individuals depending on their roles and responsibilities in an organization.', 'vec_doc-14-nist-sp-800-53-p434-1674', 0, 223, 'v2.1.0', 'f282a74ed56be5318391b7804c8c34bc7d1949662f74b6ddffaf4ca26b212f47', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":434,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1674,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p434-1675', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 434, 'low-impact system [FIPS 200] A system in which all three security objectives (i.e., confidentiality, integrity, and availability) are assigned a FIPS Publication 199 potential impact value of low. malicious code Software or firmware intended to perform an unauthorized process that will have adverse impacts on the confidentiality, integrity, or availability of a system. A virus, worm, Trojan horse, or other code-based entity that infects a host. Spyware and some forms of adware are also examples of malicious code. managed interface An interface within a system that provides boundary protection capabilities using automated mechanisms or devices. mandatory access control An access control policy that is uniformly enforced across all subjects and objects within a system.', 'vec_doc-14-nist-sp-800-53-p434-1675', 0, 195, 'v2.1.0', '20fe31850463ae014fc608c17beefe7217ac15381838bd13aef6abd17d495604', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":434,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1675,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p434-1676', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 434, 'A subject that has been granted access to information is constrained from: passing the information to unauthorized subjects or objects; granting its privileges to other subjects; changing one or more security attributes on subjects, objects, the system, or system components; choosing the security attributes to be associated with newly created or modified objects; or changing the rules for governing access control. Organization-defined subjects may explicitly be granted organization-defined privileges (i.e., they are trusted subjects) such that they are not limited by some or all of the above constraints. Mandatory access control is considered a type of nondiscretionary access control. marking See security marking. matching agreement [OMB A-108] A written agreement between a recipient agency and a source agency (or a non-Federal agency) that is required by the Privacy Act for parties engaging in a matching program.', 'vec_doc-14-nist-sp-800-53-p434-1676', 0, 232, 'v2.1.0', '81b394165cf576125138d29940cb3a7fc01995a5ddd16926d9dda10cf1974eca', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":434,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1676,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p434-1677', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 434, 'media [FIPS 200] Physical devices or writing surfaces including magnetic tapes, optical disks, magnetic disks, Large-Scale Integration memory chips, and printouts (but excluding display media) onto which information is recorded, stored, or printed within a system. metadata Information that describes the characteristics of data, including structural metadata that describes data structures (i.e., data format, syntax, semantics) and descriptive metadata that describes data contents (i.e., security labels).', 'vec_doc-14-nist-sp-800-53-p434-1677', 0, 127, 'v2.1.0', '21bb2d97846ec38d33741ac054494bbe44c8b2ed21d704f2f59ca56305416799', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":434,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1677,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p435-1678', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 435, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 408 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 mobile code Software programs or parts of programs obtained from remote systems, transmitted across a network, and executed on a local system without explicit installation or execution by the recipient. mobile code technologies Software technologies that provide the mechanisms for the production and use of mobile code.', 'vec_doc-14-nist-sp-800-53-p435-1678', 0, 178, 'v2.1.0', 'a9ebe7b1221b758ad2f6f13d8c8f224ca0c4ca708dbbcb229535322fcf420345', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":435,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1678,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p435-1679', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 435, 'mobile device A portable computing device that has a small form factor such that it can easily be carried by a single individual; is designed to operate without a physical connection (e.g., wirelessly transmit or receive information); possesses local, non-removable data storage; and is powered on for extended periods of time with a self-contained power source. Mobile devices may also include voice communication capabilities, on-board sensors that allow the device to capture (e.g., photograph, video, record, or determine location) information, and/or built-in features for synchronizing local data with remote locations. Examples include smart phones, tablets, and e-readers. moderate-impact system [FIPS 200] A system in which at least one security objective (i.e., confidentiality, integrity, or availability) is assigned a FIPS Publication 199 potential impact value of moderate and no security objective is assigned a potential impact value of high.', 'vec_doc-14-nist-sp-800-53-p435-1679', 0, 240, 'v2.1.0', 'e69151efe2b923d55733f4601f31f179a79a3c0f5eca5e703d6862b32e5d9dea', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":435,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1679,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p435-1680', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 435, 'multi-factor authentication [SP 800-63-3] An authentication system or an authenticator that requires more than one authentication factor for successful authentication. Multi-factor authentication can be performed using a single authenticator that provides more than one factor or by a combination of authenticators that provide different factors. The three authentication factors are something you know, something you have, and something you are. See authenticator. multilevel security [CNSSI 4009] Concept of processing information with different classifications and categories that simultaneously permits access by users with different security clearances and denies access to users who lack authorization. multiple security levels [CNSSI 4009] Capability of a system that is trusted to contain, and maintain separation between, resources (particularly stored data) of different security domains.', 'vec_doc-14-nist-sp-800-53-p435-1680', 0, 225, 'v2.1.0', '7666f79b1585581b7cb0f6ec34353541ca6eb96ea1623d562adbfdb99f8eb0bd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":435,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1680,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p436-1681', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 436, '5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 409 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 national security system [OMB A-130] Any system (including any telecommunications system) used or operated by an agency or by a contractor of an agency, or other organization on behalf of an agency— (i) the function, operation, or use of which involves intelligence activities; involves cryptologic activities related to national security; involves command and control of military forces; involves equipment that is an integral part of a weapon or weapons system; or is critical to the direct fulfillment of military or intelligence missions (excluding a system that is to be used for routine administrative and business applications, for example, payroll, finance, logistics, and personnel management applications); or (ii) is protected at all times by procedures established for information that have been specifically authorized under criteria established by an Executive Order or an Act of Congress to be kept classified in the interest of national defense or foreign policy.', 'vec_doc-14-nist-sp-800-53-p436-1681', 0, 338, 'v2.1.0', '05689c36c8693b205708f51c97e9e2a25f7aafd874e472114443d9eca49a1f42', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":436,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1681,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p436-1682', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 436, 'network A system implemented with a collection of connected components. Such components may include routers, hubs, cabling, telecommunications controllers, key distribution centers, and technical control devices. network access Access to a system by a user (or a process acting on behalf of a user) communicating through a network, including a local area network, a wide area network, and the Internet. nonce [SP 800-63-3] A value used in security protocols that is never repeated with the same key. For example, nonces used as challenges in challenge- response authentication protocols are not repeated until the authentication keys are changed. Otherwise, there is a possibility of a replay attack. nondiscretionary access control See mandatory access control. nonlocal maintenance Maintenance activities conducted by individuals who communicate through either an internal or external network. non-organizational user A user who is not an organizational user (including public users).', 'vec_doc-14-nist-sp-800-53-p436-1682', 0, 247, 'v2.1.0', '2b2d7cdd93103da75dc1c0376969da67ab54c93557c48938a901a7ed89789006', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":436,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1682,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p436-1683', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 436, 'non-repudiation Protection against an individual who falsely denies having performed a certain action and provides the capability to determine whether an individual took a certain action, such as creating information, sending a message, approving information, or receiving a message. NSA-approved cryptography Cryptography that consists of an approved algorithm, an implementation that has been approved for the protection of classified information and/or controlled unclassified information in a specific environment, and a supporting key management infrastructure.', 'vec_doc-14-nist-sp-800-53-p436-1683', 0, 142, 'v2.1.0', '2667e7e5c49a37073e2043e5165185b0d456319b0b75d0932309a3a23f2124dc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":436,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1683,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p437-1684', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 437, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 410 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 object Passive system-related entity, including devices, files, records, tables, processes, programs, and domains that contain or receive information. Access to an object (by a subject) implies access to the information it contains. See subject. operations security [CNSSI 4009] Systematic and proven process by which potential adversaries can be denied information about capabilities and intentions by identifying, controlling, and protecting generally unclassified evidence of the planning and execution of sensitive activities.', 'vec_doc-14-nist-sp-800-53-p437-1684', 0, 231, 'v2.1.0', '644fe0acc0758abc9558054daa0354b7a624424ad0d72063d0faacf9d7f3c622', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":437,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1684,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p437-1685', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 437, 'The process involves five steps: identification of critical information, analysis of threats, analysis of vulnerabilities, assessment of risks, and application of appropriate countermeasures. organization [FIPS 200, Adapted] An entity of any size, complexity, or positioning within an organizational structure, including federal agencies, private enterprises, academic institutions, state, local, or tribal governments, or as appropriate, any of their operational elements. organization-defined control parameter The variable part of a control or control enhancement that is instantiated by an organization during the tailoring process by either assigning an organization-defined value or selecting a value from a predefined list provided as part of the control or control enhancement. See assignment operation and selection operation.', 'vec_doc-14-nist-sp-800-53-p437-1685', 0, 209, 'v2.1.0', 'b3ff406e0fa558db99c684992c8e96c5f53a0ebd4ed2cacd8f9904cc3f47d488', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":437,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1685,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p437-1686', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 437, 'organizational user An organizational employee or an individual whom the organization deems to have equivalent status of an employee, including a contractor, guest researcher, or individual detailed from another organization. Policies and procedures for granting the equivalent status of employees to individuals may include need-to-know, relationship to the organization, and citizenship. overlay [OMB A-130] A specification of security or privacy controls, control enhancements, supplemental guidance, and other supporting information employed during the tailoring process, that is intended to complement (and further refine) security control baselines. The overlay specification may be more stringent or less stringent than the original security control baseline specification and can be applied to multiple information systems. See tailoring. parameter See organization-defined control parameter.', 'vec_doc-14-nist-sp-800-53-p437-1686', 0, 225, 'v2.1.0', '5662bd265021f2de5040ebd2d60cf9d88f911e55df029c903007380fa62e9a25', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":437,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1686,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p437-1687', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 437, 'penetration testing A test methodology in which assessors, typically working under specific constraints, attempt to circumvent or defeat the security features of a system.', 'vec_doc-14-nist-sp-800-53-p437-1687', 0, 43, 'v2.1.0', 'f08e1eb28b90e292d9f2cecca30ff26bffd0f175e0f686a0d20a28c61e6765da', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":437,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1687,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p438-1688', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 438, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 411 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 periods processing A mode of system operation in which information of different sensitivities is processed at distinctly different times by the same system with the system being properly purged or sanitized between periods. personally identifiable information [OMB A-130] Information that can be used to distinguish or trace an individual’s identity, either alone or when combined with other information that is linked or linkable to a specific individual.', 'vec_doc-14-nist-sp-800-53-p438-1688', 0, 212, 'v2.1.0', '4fcf421d11d7c1b61d96eb7a26b5965816e53c0bf7bb82353bc444dba01fba85', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":438,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1688,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p438-1689', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 438, 'personally identifiable information processing [ISO/IEC 29100, Adapted] An operation or set of operations performed upon personally identifiable information that can include, but is not limited to, the collection, retention, logging, generation, transformation, use, disclosure, transfer, and disposal of personally identifiable information. personally identifiable information processing permissions The requirements for how personally identifiable information can be processed or the conditions under which personally identifiable information can be processed. personnel security The discipline of assessing the conduct, integrity, judgment, loyalty, reliability, and stability of individuals for duties and responsibilities that require trustworthiness. physical access control system [SP 800-116] An electronic system that controls the ability of people or vehicles to enter a protected area by means of authentication and authorization at access control points.', 'vec_doc-14-nist-sp-800-53-p438-1689', 0, 242, 'v2.1.0', 'b43e1dbae6b7fb1c83b17a6e0bec0a80b234b959d6cf36ddc86ecd9aafd16756', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":438,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1689,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p438-1690', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 438, 'plan of action and milestones A document that identifies tasks that need to be accomplished. It details resources required to accomplish the elements of the plan, milestones for meeting the tasks, and the scheduled completion dates for the milestones. portable storage device A system component that can communicate with and be added to or removed from a system or network and that is limited to data storage— including text, video, audio or image data— as its primary function (e.g., optical discs, external or removable hard drives, external or removable solid-state disk drives, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks).', 'vec_doc-14-nist-sp-800-53-p438-1690', 0, 173, 'v2.1.0', '9913e4dcfe8d4cab23ae8b0a3414b79b6366752aa573baae43a4cb80fce3d9c6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":438,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1690,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p438-1691', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 438, 'potential impact [FIPS 199] The loss of confidentiality, integrity, or availability could be expected to have a limited adverse effect (FIPS Publication 199 low); a serious adverse effect (FIPS Publication 199 moderate); or a severe or catastrophic adverse effect (FIPS Publication 199 high) on organizational operations, organizational assets, or individuals. privacy architecture [SP 800-37] An embedded, integral part of the enterprise architecture that describes the structure and behavior for an enterprise’s privacy protection processes, technical measures, personnel and organizational sub-units, showing their alignment with the enterprise’s mission and strategic plans.', 'vec_doc-14-nist-sp-800-53-p438-1691', 0, 170, 'v2.1.0', 'c4864b209bde3627690184811cae6109af6b9ac8d282194dec9ab96ede998f55', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":438,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1691,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p439-1692', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 439, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 412 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 privacy control [OMB A-130] The administrative, technical, and physical safeguards employed within an agency to ensure compliance with applicable privacy requirements and manage privacy risks. privacy control baseline The set of privacy controls selected based on the privacy selection criteria that provide a starting point for the tailoring process. privacy domain A domain that implements a privacy policy.', 'vec_doc-14-nist-sp-800-53-p439-1692', 0, 200, 'v2.1.0', '4f711a7e3b1bcc1e5852126bd18eb2660bc19679ee85fbcc94cc172a22d3d7ba', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":439,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1692,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p439-1693', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 439, 'privacy impact assessment [OMB A-130] An analysis of how information is handled to ensure handling conforms to applicable legal, regulatory, and policy requirements regarding privacy; to determine the risks and effects of creating, collecting, using, processing, storing, maintaining, disseminating, disclosing, and disposing of information in identifiable form in an electronic information system; and to examine and evaluate protections and alternate processes for handling information to mitigate potential privacy concerns. A privacy impact assessment is both an analysis and a formal document detailing the process and the outcome of the analysis.', 'vec_doc-14-nist-sp-800-53-p439-1693', 0, 163, 'v2.1.0', 'e89ad27279e1396f1f852a8e368f5dfb45386d70cc5515c6e0a8dfd9ff576c9b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":439,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1693,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p439-1694', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 439, 'privacy plan [OMB A-130] A formal document that details the privacy controls selected for an information system or environment of operation that are in place or planned for meeting applicable privacy requirements and managing privacy risks, details how the controls have been implemented, and describes the methodologies and metrics that will be used to assess the controls. privacy program plan [OMB A-130] A formal document that provides an overview of an agency’s privacy program, including a description of the structure of the privacy program, the resources dedicated to the privacy program, the role of the Senior Agency Official for Privacy and other privacy officials and staff, the strategic goals and objectives of the privacy program, and the program management controls and common controls in place or planned for meeting applicable privacy requirements and managing privacy risks. privileged account A system account with the authorizations of a privileged user.', 'vec_doc-14-nist-sp-800-53-p439-1694', 0, 244, 'v2.1.0', '4be87ec6d016a06e4dbee28e317d3dffd5cf3460cb50a2b06b6a94e3ccd2addf', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":439,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1694,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p439-1695', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 439, 'privileged command A human-initiated command executed on a system that involves the control, monitoring, or administration of the system, including security functions and associated security-relevant information. privileged user [CNSSI 4009] A user that is authorized (and therefore, trusted) to perform security-relevant functions that ordinary users are not authorized to perform.', 'vec_doc-14-nist-sp-800-53-p439-1695', 0, 96, 'v2.1.0', '50767d68201acb84dec897c9efb36dfab4e122b7889dbeb9c9fc1dcdc54779aa', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":439,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1695,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p440-1696', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 440, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 413 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 protected distribution system [CNSSI 4009] Wire line or fiber optic system that includes adequate safeguards and/or countermeasures (e.g., acoustic, electric, electromagnetic, and physical) to permit its use for the transmission of unencrypted information through an area of lesser classification or control. provenance The chronology of the origin, development, ownership, location, and changes to a system or system component and associated data. It may also include the personnel and processes used to interact with or make modifications to the system, component, or associated data.', 'vec_doc-14-nist-sp-800-53-p440-1696', 0, 245, 'v2.1.0', '4a417df31c1dce0b9b9f5f7dbbedf91b5402941a51927b4e6cf8311e6763a81b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":440,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1696,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p440-1697', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 440, 'public key infrastructure [CNSSI 4009] The architecture, organization, techniques, practices, and procedures that collectively support the implementation and operation of a certificate-based public key cryptographic system. Framework established to issue, maintain, and revoke public key certificates. purge [SP 800-88] A method of sanitization that applies physical or logical techniques that render target data recovery infeasible using state of the art laboratory techniques. reciprocity [SP 800-37] Agreement among participating organizations to accept each other’s security assessments to reuse system resources and/or to accept each other’s assessed security posture to share information.', 'vec_doc-14-nist-sp-800-53-p440-1697', 0, 174, 'v2.1.0', 'c55f41f32e556b0ede3f6757a38ea61788c427e948061572f2597cfbfe060abc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":440,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1697,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p440-1698', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 440, 'records [OMB A-130] All recorded information, regardless of form or characteristics, made or received by a Federal agency under Federal law or in connection with the transaction of public business and preserved or appropriate for preservation by that agency or its legitimate successor as evidence of the organization, functions, policies, decisions, procedures, operations, or other activities of the United States Government or because of the informational value of data in them. red team exercise An exercise, reflecting real-world conditions that is conducted as a simulated adversarial attempt to compromise organizational missions or business processes and to provide a comprehensive assessment of the security capabilities of an organization and its systems. reference monitor A set of design requirements on a reference validation mechanism that, as a key component of an operating system, enforces an access control policy over all subjects and objects.', 'vec_doc-14-nist-sp-800-53-p440-1698', 0, 241, 'v2.1.0', '3d6ef07f416a1c36397be78c16c1708fbad27fde646054049c92e81dac014de6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":440,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1698,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p440-1699', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 440, 'A reference validation mechanism is always invoked (i.e., complete mediation), tamperproof, and small enough to be subject to analysis and tests, the completeness of which can be assured (i.e., verifiable).', 'vec_doc-14-nist-sp-800-53-p440-1699', 0, 52, 'v2.1.0', '280a5c46fc5113693fd8bac4d01185454b60770af6c3dc384e50dc6f20344836', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":440,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1699,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p441-1700', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 441, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 414 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 regrader [CNSSI 4009] A trusted process explicitly authorized to re-classify and re-label data in accordance with a defined policy exception. Untrusted or unauthorized processes are such actions by the security policy. remote access Access to an organizational system by a user (or a process acting on behalf of a user) communicating through an external network. remote maintenance Maintenance activities conducted by individuals communicating through an external network.', 'vec_doc-14-nist-sp-800-53-p441-1700', 0, 216, 'v2.1.0', 'c7df31ae7a0134f7d704e7c820322d7da468fcb740c67fa015ef7d37e75d22af', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":441,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1700,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p441-1701', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 441, 'replay attack [SP 800-63-3] An attack in which the Attacker is able to replay previously captured messages (between a legitimate Claimant and a Verifier) to masquerade as that Claimant to the Verifier or vice versa. replay resistance Protection against the capture of transmitted authentication or access control information and its subsequent retransmission with the intent of producing an unauthorized effect or gaining unauthorized access. resilience [OMB A-130] The ability of an information system to operate under adverse conditions or stress, even if in a degraded or debilitated state, while maintaining essential operational capabilities, and to recover to an effective operational posture in a time frame consistent with mission needs.', 'vec_doc-14-nist-sp-800-53-p441-1701', 0, 187, 'v2.1.0', 'd8190a3de909e933c3400abc9d0ac54185e120dcae3c71caf06239c5ba581a87', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":441,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1701,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p441-1702', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 441, 'restricted data [ATOM54] All data concerning (i) design, manufacture, or utilization of atomic weapons; (ii) the production of special nuclear material; or (iii) the use of special nuclear material in the production of energy, but shall not include data declassified or removed from the Restricted Data category pursuant to Section 142 [of the Atomic Energy Act of 1954]. risk [OMB A-130] A measure of the extent to which an entity is threatened by a potential circumstance or event, and typically is a function of: (i) the adverse impact, or magnitude of harm, that would arise if the circumstance or event occurs; and (ii) the likelihood of occurrence. risk assessment [SP 800-39] [IR 8062, adapted] The process of identifying risks to organizational operations (including mission, functions, image, reputation), organizational assets, individuals, other organizations, and the Nation, resulting from the operation of a system.', 'vec_doc-14-nist-sp-800-53-p441-1702', 0, 233, 'v2.1.0', '3f278e4df50b066cdc2de777041a4f25c51c4650f54262d9e3fdcb35f0bca5bd', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":441,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1702,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p441-1703', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 441, 'Risk management includes threat and vulnerability analyses as well as analyses of adverse effects on individuals arising from information processing and considers mitigations provided by security and privacy controls planned or in place. Synonymous with risk analysis.', 'vec_doc-14-nist-sp-800-53-p441-1703', 0, 67, 'v2.1.0', 'dd6562a108c9eca3e0394a758f150398f301a8090c7ae19130e3511c01cea399', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":441,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1703,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p442-1704', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 442, '5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 415 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 risk executive (function) [SP 800-37] An individual or group within an organization that helps to ensure that security risk-related considerations for individual systems, to include the authorization decisions for those systems, are viewed from an organization-wide perspective with regard to the overall strategic goals and objectives of the organization in carrying out its mission and business functions; and managing risk from individual systems is consistent across the organization, reflects organizational risk tolerance, and is considered along with other organizational risks affecting mission or business success.', 'vec_doc-14-nist-sp-800-53-p442-1704', 0, 249, 'v2.1.0', '8994d858bf39bcff3c9739a9cb6d06e4af20989c11b0f10ee9ba71a039ba777f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":442,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1704,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p442-1705', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 442, 'risk management [OMB A-130] The program and supporting processes to manage risk to agency operations (including mission, functions, image, reputation), agency assets, individuals, other organizations, and the Nation, and includes: establishing the context for risk-related activities; assessing risk; responding to risk once determined; and monitoring risk over time. risk mitigation [CNSSI 4009] Prioritizing, evaluating, and implementing the appropriate risk- reducing controls/countermeasures recommended from the risk management process. risk response [OMB A-130] Accepting, avoiding, mitigating, sharing, or transferring risk to agency operations, agency assets, individuals, other organizations, or the Nation. risk tolerance [SP 800-39] The level of risk or the degree of uncertainty that is acceptable to an organization.', 'vec_doc-14-nist-sp-800-53-p442-1705', 0, 208, 'v2.1.0', '3609d0ac282adc1fcf9f0a97ec7fd34abc8393e1e97110900199e4caeb5c5691', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":442,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1705,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p442-1706', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 442, 'role-based access control Access control based on user roles (i.e., a collection of access authorizations that a user receives based on an explicit or implicit assumption of a given role). Role permissions may be inherited through a role hierarchy and typically reflect the permissions needed to perform defined functions within an organization. A given role may apply to a single individual or to several individuals. runtime The period during which a computer program is executing. sanitization [SP 800-88] A process to render access to target data on the media infeasible for a given level of effort. Clear, purge, and destroy are actions that can be taken to sanitize media. scoping considerations A part of tailoring guidance that provides organizations with specific considerations on the applicability and implementation of security and privacy controls in the control baselines.', 'vec_doc-14-nist-sp-800-53-p442-1706', 0, 222, 'v2.1.0', 'b52c64e48923de6c190e38533be7f4d969126ab206182ce0df6222a891f4fa3f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":442,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1706,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p442-1707', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 442, 'Considerations include policy or regulatory, technology, physical infrastructure, system component allocation, public access, scalability, common control, operational or environmental, and security objective.', 'vec_doc-14-nist-sp-800-53-p442-1707', 0, 52, 'v2.1.0', '8538e796d76bdaae69294a5f93a30b43fe0700c35100b5745bdd6067c784ae4b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":442,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1707,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p443-1708', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 443, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 416 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 security [CNSSI 4009] A condition that results from the establishment and maintenance of protective measures that enable an organization to perform its mission or critical functions despite risks posed by threats to its use of systems. Protective measures may involve a combination of deterrence, avoidance, prevention, detection, recovery, and correction that should form part of the organization’s risk management approach. security attribute An abstraction that represents the basic properties or characteristics of an entity with respect to safeguarding information.', 'vec_doc-14-nist-sp-800-53-p443-1708', 0, 241, 'v2.1.0', '2e87fb1af1cc211b1770708d0a9d9cebc2fe5e25fe8917b98271b7a3cc329561', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":443,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1708,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p443-1709', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 443, 'Typically associated with internal data structures— including records, buffers, and files within the system— and used to enable the implementation of access control and flow control policies; reflect special dissemination, handling or distribution instructions; or support other aspects of the information security policy. security categorization The process of determining the security category for information or a system. Security categorization methodologies are described in CNSS Instruction 1253 for national security systems and in FIPS Publication 199 for other than national security systems. See security category. security category [OMB A-130] The characterization of information or an information system based on an assessment of the potential impact that a loss of confidentiality, integrity, or availability of such information or information system would have on agency operations, agency assets, individuals, other organizations, and the Nation.', 'vec_doc-14-nist-sp-800-53-p443-1709', 0, 241, 'v2.1.0', '76e366229018c51b01cc947b45372cddb0b23d142cbc7739922c26d6d46cfd8b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":443,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1709,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p443-1710', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 443, 'security control [OMB A-130] The safeguards or countermeasures prescribed for an information system or an organization to protect the confidentiality, integrity, and availability of the system and its information. security control baseline [OMB A-130] The set of minimum security controls defined for a low-impact, moderate-impact, or high-impact information system. security domain [CNSSI 4009] A domain that implements a security policy and is administered by a single authority. security functionality The security-related features, functions, mechanisms, services, procedures, and architectures implemented within organizational information systems or the environments in which those systems operate. security functions The hardware, software, or firmware of the system responsible for enforcing the system security policy and supporting the isolation of code and data on which the protection is based.', 'vec_doc-14-nist-sp-800-53-p443-1710', 0, 227, 'v2.1.0', 'afd46212b95b8fcbb2f29fad4129134a6b3f43435e2cd8915898e7cc9f162869', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":443,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1710,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p443-1711', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 443, 'security impact analysis [SP 800-128] The analysis conducted by qualified staff within an organization to determine the extent to which changes to the system affect the security posture of the system.', 'vec_doc-14-nist-sp-800-53-p443-1711', 0, 50, 'v2.1.0', '566b9aea2a0eb44e7c47167492bbd9caed0998a934228a474eed684f66f75ece', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":443,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1711,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p444-1712', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 444, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 417 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 security kernel [CNSSI 4009] Hardware, firmware, and software elements of a trusted computing base implementing the reference monitor concept. Security kernel must mediate all accesses, be protected from modification, and be verifiable as correct. security label The means used to associate a set of security attributes with a specific information object as part of the data structure for that object. security marking  The means used to associate a set of security attributes with objects in a human-readable form in order to enable organizational, process-based enforcement of information security policies.', 'vec_doc-14-nist-sp-800-53-p444-1712', 0, 250, 'v2.1.0', '356a36f275e0f079cd0ffa04e70814bb48ed0abc757bb373b5ee5de772a5b058', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":444,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1712,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p444-1713', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 444, 'security objective [FIPS 199] Confidentiality, integrity, or availability. security plan A formal document that provides an overview of the security requirements for an information system or an information security program and describes the security controls in place or planned for meeting those requirements. The system security plan describes the system components that are included within the system, the environment in which the system operates, how the security requirements are implemented, and the relationships with or connections to other systems. See system security plan. security policy [SP 800-160-1 adapted] A set of criteria for the provision of security services. A set of rules that governs all aspects of security-relevant system and system component behavior.', 'vec_doc-14-nist-sp-800-53-p444-1713', 0, 195, 'v2.1.0', '254468dcddf8d361a01efedc93b2428590b9ed66ff3a6d37ad3a071a46b37e49', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":444,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1713,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p444-1714', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 444, 'security policy filter A hardware and/or software component that performs one or more of the following functions: content verification to ensure the data type of the submitted content; content inspection to analyze the submitted content and verify that complies with a defined policy; malicious content checker that evaluates the content for malicious code; suspicious activity checker that evaluates or executes the content in a safe manner, such as in a sandbox or detonation chamber and monitors for suspicious activity; or content sanitization, cleansing, and transformation, which modifies the submitted content to comply with a defined policy.', 'vec_doc-14-nist-sp-800-53-p444-1714', 0, 163, 'v2.1.0', '1d5433457c02e44700dd765f1d1c14311ad017fe9f27aff169cc1a431779f36e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":444,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1714,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p445-1715', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 445, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 418 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 security requirement [FIPS 200, Adapted] A requirement levied on an information system or an organization that is derived from applicable laws, executive orders, directives, regulations, policies, standards, procedures, or mission/business needs to ensure the confidentiality, integrity, and availability of information that is being processed, stored, or transmitted. Note: Security requirements can be used in a variety of contexts from high- level policy-related activities to low-level implementation-related activities in system development and engineering disciplines.', 'vec_doc-14-nist-sp-800-53-p445-1715', 0, 242, 'v2.1.0', '3af6a75800a5ec561c8869e73ce06d403b32d4be71b37f1d0382b4c05a0fb30e', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":445,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1715,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p445-1716', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 445, 'security service [SP 800-160-1] A security capability or function provided by an entity that supports one or more security objectives. security-relevant information Information within the system that can potentially impact the operation of security functions or the provision of security services in a manner that could result in failure to enforce the system security policy or maintain isolation of code and data. selection operation A control parameter that allows an organization to select a value from a list of predefined values provided as part of the control or control enhancement (e.g., selecting to either restrict an action or prohibit an action). See assignment operation and organization-defined control parameter.', 'vec_doc-14-nist-sp-800-53-p445-1716', 0, 182, 'v2.1.0', '9e4541ff55ed05c42d3539c2f7e48fb04b854c9ec494e0ea97647151500716d6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":445,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1716,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p445-1717', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 445, 'senior agency information security officer Official responsible for carrying out the Chief Information Officer responsibilities under FISMA and serving as the Chief Information Officer’s primary liaison to the agency’s authorizing officials, information system owners, and information system security officers. Note: Organizations subordinate to federal agencies may use the term senior information security officer or chief information security officer to denote individuals who fill positions with similar responsibilities to senior agency information security officers.', 'vec_doc-14-nist-sp-800-53-p445-1717', 0, 143, 'v2.1.0', '747bf64545fa1708a7549b8fa8fe69a3f432c60242f5ef5ff2b996001d8725eb', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":445,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1717,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p445-1718', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 445, 'senior agency official for privacy [OMB A-130] Senior official, designated by the head of each agency, who has agency-wide responsibility for privacy, including implementation of privacy protections; compliance with Federal laws, regulations, and policies relating to privacy; management of privacy risks at the agency; and a central policy-making role in the agency’s development and evaluation of legislative, regulatory, and other policy proposals. senior information security officer See senior agency information security officer. sensitive compartmented information [CNSSI 4009] Classified information concerning or derived from intelligence sources, methods, or analytical processes, which is required to be handled within formal access control systems established by the Director of National Intelligence.', 'vec_doc-14-nist-sp-800-53-p445-1718', 0, 204, 'v2.1.0', 'd7e33041fa20bd4e7a151088673698ce6e0cc6934e1482fc513fd733a04aa101', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":445,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1718,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p446-1719', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 446, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 419 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 service-oriented architecture A set of principles and methodologies for designing and developing software in the form of interoperable services. These services are well-defined business functions that are built as software components (i.e., discrete pieces of code and/or data structures) that can be reused for different purposes. shared control A security or privacy control that is implemented for an information system in part as a common control and in part as a system-specific control. See hybrid control.', 'vec_doc-14-nist-sp-800-53-p446-1719', 0, 226, 'v2.1.0', '438db93e007cfe23cd02c6861a067805654db9076bec4449493d0d5098aff675', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":446,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1719,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p446-1720', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 446, 'software [CNSSI 4009] Computer programs and associated data that may be dynamically written or modified during execution. spam The abuse of electronic messaging systems to indiscriminately send unsolicited bulk messages. special access program [CNSSI 4009] A program established for a specific class of classified information that imposes safeguarding and access requirements that exceed those normally required for information at the same classification level. split tunneling The process of allowing a remote user or device to establish a non-remote connection with a system and simultaneously communicate via some other connection to a resource in an external network. This method of network access enables a user to access remote devices, and simultaneously, access uncontrolled networks. spyware Software that is secretly or surreptitiously installed into an information system to gather information on individuals or organizations without their knowledge; a type of malicious code.', 'vec_doc-14-nist-sp-800-53-p446-1720', 0, 247, 'v2.1.0', '15479998ec42f927fb1e96d6ce7ef381d79f38213682219b77b22939442e56f9', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":446,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1720,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p446-1721', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 446, 'subject An individual, process, or device that causes information to flow among objects or change to the system state. Also see object. subsystem A major subdivision or component of an information system consisting of information, information technology, and personnel that performs one or more specific functions. supplier Organization or individual that enters into an agreement with the acquirer or integrator for the supply of a product or service. This includes all suppliers in the supply chain, developers or manufacturers of systems, system components, or system services; systems integrators; vendors; product resellers; and third party partners. supply chain Linked set of resources and processes between and among multiple tiers of organizations, each of which is an acquirer, that begins with the sourcing of products and services and extends through their life cycle.', 'vec_doc-14-nist-sp-800-53-p446-1721', 0, 220, 'v2.1.0', 'e5405d76baaf004a6fd931da64766b09a1b6c24592976829e5237dc40c316d04', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":446,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1721,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p447-1722', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 447, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 420 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 supply chain element Organizations, entities, or tools employed for the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of systems and system components. supply chain risk The potential for harm or compromise that arises as a result of security risks from suppliers, their supply chains, and their products or services. Supply chain risks include exposures, threats, and vulnerabilities associated with the products and services traversing the supply chain as well as the exposures, threats, and vulnerabilities to the supply chain.', 'vec_doc-14-nist-sp-800-53-p447-1722', 0, 251, 'v2.1.0', '005fbe64bdeb4d3a1d43f095771719d8779599484deec2ccc97b55279057efa0', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":447,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1722,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p447-1723', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 447, 'supply chain risk assessment A systematic examination of supply chain risks, likelihoods of their occurrence, and potential impacts. supply chain risk management A systematic process for managing cyber supply chain risk exposures, threats, and vulnerabilities throughout the supply chain and developing risk response strategies to the risks presented by the supplier, the supplied products and services, or the supply chain. system [CNSSI 4009] [ISO 15288] Any organized assembly of resources and procedures united and regulated by interaction or interdependence to accomplish a set of specific functions. Note: Systems also include specialized systems such as industrial control systems, telephone switching and private branch exchange (PBX) systems, and environmental control systems. Combination of interacting elements organized to achieve one or more stated purposes. Note 1: There are many types of systems.', 'vec_doc-14-nist-sp-800-53-p447-1723', 0, 229, 'v2.1.0', 'c37393a701992cac5f024aa37a9209baf23b6472f20753bffd32918f813486d6', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":447,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1723,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p447-1724', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 447, 'Examples include: general and special-purpose information systems; command, control, and communication systems; crypto modules; central processing unit and graphics processor boards; industrial control systems; flight control systems; weapons, targeting, and fire control systems; medical devices and treatment systems; financial, banking, and merchandising transaction systems; and social networking systems. Note 2: The interacting elements in the definition of system include hardware, software, data, humans, processes, facilities, materials, and naturally occurring physical entities. Note 3: System-of-systems is included in the definition of system. system component [SP 800-128] A discrete identifiable information technology asset that represents a building block of a system and may include hardware, software, and firmware.', 'vec_doc-14-nist-sp-800-53-p447-1724', 0, 209, 'v2.1.0', '3e1f3861ccd7b3706f00559eebc6454530d22a701d4eab0aee683bea17ba120b', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":447,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1724,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p447-1725', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 447, 'system of records [USC 552] A group of any records under the control of any agency from which information is retrieved by the name of the individual or by some identifying number, symbol, or other identifying particular assigned to the individual. system of records notice [OMB A-108] The notice(s) published by an agency in the Federal Register upon the establishment and/or modification of a system of records describing the existence and character of the system.', 'vec_doc-14-nist-sp-800-53-p447-1725', 0, 117, 'v2.1.0', '40c1ba21e8f1d9e42e66c01fa4cce01e8a9b101b0b2404c5306399ad77c15ecc', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":447,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1725,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p448-1726', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 448, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 421 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 system owner (or program manager) Official responsible for the overall procurement, development, integration, modification, operation, and maintenance of a system. system security officer [SP 800-37] Individual with assigned responsibility for maintaining the appropriate operational security posture for a system or program. system security plan See security plan. system service A capability provided by a system that facilitates information processing, storage, or transmission.', 'vec_doc-14-nist-sp-800-53-p448-1726', 0, 218, 'v2.1.0', 'da0bce52041f698b04bab9d32f41386852869d2eb364c1b6066b641257456336', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":448,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1726,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p448-1727', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 448, 'system-related security risk [SP 800-30] Risk that arises through the loss of confidentiality, integrity, or availability of information or systems and that considers impacts to the organization (including assets, mission, functions, image, or reputation), individuals, other organizations, and the Nation. See risk. system-specific control [OMB A-130] A security or privacy control for an information system that is implemented at the system level and is not inherited by any other information system. systems engineering [SP 800-160-1] An engineering discipline whose responsibility is creating and executing an interdisciplinary process to ensure that the customer and all other stakeholder needs are satisfied in a high- quality, trustworthy, cost-efficient, and schedule-compliant manner throughout a system’s entire life cycle. systems security engineering [SP 800-160-1] A specialty engineering field strongly related to systems engineering.', 'vec_doc-14-nist-sp-800-53-p448-1727', 0, 237, 'v2.1.0', '32b84fde8724834ba756961489048c358b0408f115ffd4d39ed6186e791af7a7', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":448,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1727,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p448-1728', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 448, 'It applies scientific, engineering, and information assurance principles to deliver trustworthy systems that satisfy stakeholder requirements within their established risk tolerance. tailored control baseline A set of controls that result from the application of tailoring guidance to a control baseline. See tailoring. tailoring The process by which security control baselines are modified by: identifying and designating common controls, applying scoping considerations on the applicability and implementation of baseline controls, selecting compensating security controls, assigning specific values to organization-defined security control parameters, supplementing baselines with additional security controls or control enhancements, and providing additional specification information for control implementation. tampering [CNSSI 4009] An intentional but unauthorized act resulting in the modification of a system, components of systems, its intended behavior, or data.', 'vec_doc-14-nist-sp-800-53-p448-1728', 0, 244, 'v2.1.0', 'ebe947369cfa0b828f20b1f2e3776816c209e341dd3bb00102d079308f3a0917', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":448,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1728,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p449-1729', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 449, 'NIST SP 800-53, REV. 5                                                                                     SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ APPENDIX A   PAGE 422 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5 threat [SP 800-30] Any circumstance or event with the potential to adversely impact organizational operations, organizational assets, individuals, other organizations, or the Nation through a system via unauthorized access, destruction, disclosure, modification of information, and/or denial of service. threat assessment [CNSSI 4009] Formal description and evaluation of threat to an information system.', 'vec_doc-14-nist-sp-800-53-p449-1729', 0, 199, 'v2.1.0', 'b49de995253bc529e6fc3b749c021288c3465ca8b4846fad31e95fc2bcf3e29f', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":449,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1729,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p449-1730', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 449, 'threat modeling [SP 800-154] threat source [FIPS 200] A form of risk assessment that models aspects of the attack and defense sides of a logical entity, such as a piece of data, an application, a host, a system, or an environment. The intent and method targeted at the intentional exploitation of a vulnerability or a situation and method that may accidentally trigger a vulnerability. See threat agent. transmission [CNSSI 4009] The state that exists when information is being electronically sent from one location to one or more other locations. trusted path A mechanism by which a user (through an input device) can communicate directly with the security functions of the system with the necessary confidence to support the system security policy. This mechanism can only be activated by the user or the security functions of the system and cannot be imitated by untrusted software.', 'vec_doc-14-nist-sp-800-53-p449-1730', 0, 222, 'v2.1.0', '9872bf56bfffb6bce6b976f3befb1a4e1db7c5c7a18fd1257290eaf6cf2737d8', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":449,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1730,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p449-1731', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 449, 'trustworthiness [CNSSI 4009] The attribute of a person or enterprise that provides confidence to others of the qualifications, capabilities, and reliability of that entity to perform specific tasks and fulfill assigned responsibilities. trustworthiness (system) The degree to which an information system (including the information technology components that are used to build the system) can be expected to preserve the confidentiality, integrity, and availability of the information being processed, stored, or transmitted by the system across the full range of threats. A trustworthy information system is believed to operate within defined levels of risk despite the environmental disruptions, human errors, structural failures, and purposeful attacks that are expected to occur in its environment of operation. user Individual, or (system) process acting on behalf of an individual, authorized to access a system. See organizational user and non-organizational user.', 'vec_doc-14-nist-sp-800-53-p449-1731', 0, 243, 'v2.1.0', 'da9da28c2f6096fed779a713dcf65cb0b4e02d6dfba33b2d75091957fa191369', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":449,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1731,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-14-nist-sp-800-53-p449-1732', 'doc-14-nist-sp-800-53', 'doc-14-nist-sp-800-53', 'CHAPTER THREE   PAGE 373', 449, 'virtual private network [CNSSI 4009] Protected information system link utilizing tunneling, security controls, and endpoint address translation giving the impression of a dedicated line.', 'vec_doc-14-nist-sp-800-53-p449-1732', 0, 47, 'v2.1.0', 'e549c51125af4f1a9e4171a261f0d0358cf5420b0379f7279d0fdf59f47ba050', '{"document_id":"doc-14-nist-sp-800-53","document_title":"NIST SP 800-53 Rev. 5","chapter":"UNKNOWN","section":"CHAPTER THREE   PAGE 373","subsection":"UNKNOWN","table_id":null,"page":449,"domain":"SECURITY_CONTROLS","authority_tier":0,"chunk_seq":1732,"source_path":".zayron/knowledge/physical-15/14-nist-sp-800-53.pdf","section_path":"CHAPTER THREE   PAGE 373"}');
